def roster_text(value: Any) -> str:
    return str(value or "").strip()


def normalize_edoc_job_level(job_level: Any) -> str:
    text = roster_text(job_level)
    legacy_map = {
        "L1 員工": "職員",
        "L2 專員": "職員",
        "L3 主管": "課長",
        "L4 部門主管": "部長",
        "L5 高階主管": "區經理",
        "L6 執行長": "執行長",
    }
    if text in legacy_map:
        return legacy_map[text]
    return text if text in EDOC_JOB_LEVELS else "職員"


def derive_edoc_role_from_roster(
    job_level: Any = "",
    title: Any = "",
    department: Any = "",
    company: Any = "",
    region: Any = "",
    class_name: Any = "",
) -> str:
    level = normalize_edoc_job_level(job_level)
    title_text = roster_text(title)
    department_text = roster_text(department)
    haystack = " ".join([level, title_text, department_text, roster_text(company), roster_text(region), roster_text(class_name)])

    if "執行長" in haystack:
        return "執行長"
    if level in {"董事會", "股東", "外部檢核單位"}:
        return level
    if "行政部主任" in haystack or "行政部長" in haystack:
        return "行政部主任"
    if "總務" in haystack:
        return "總務"
    if "人資" in haystack:
        return "人資"
    if "會計" in haystack or "財務" in haystack:
        return "會計"
    if "業務助理" in title_text:
        return "業務助理"
    supervisor_keywords = {"督導", "負責人", "主任", "主管", "經理", "部長", "課長", "組長"}
    if level in {"組長", "課長", "部長", "區經理"} or any(keyword in title_text for keyword in supervisor_keywords):
        return "主管"
    return "員工"


def derive_edoc_data_scope_from_roster(job_level: Any = "", role: Any = "") -> str:
    level = normalize_edoc_job_level(job_level)
    role_text = roster_text(role)
    if role_text in {"執行長", "行政部主任", "總務"}:
        return "company"
    if role_text in {"董事會", "股東"}:
        return "group"
    if role_text == "外部檢核單位":
        return "custom"
    if level == "區經理":
        return "region"
    if level == "部長":
        return "business_unit"
    return "department"


def edoc_roster_permission_profile(row: Dict[str, Any]) -> Dict[str, Any]:
    job_level = normalize_edoc_job_level(row.get("job_level") or row.get("職等"))
    role = row.get("role") or row.get("角色") or derive_edoc_role_from_roster(
        job_level=job_level,
        title=row.get("title") or row.get("職稱"),
        department=row.get("unit") or row.get("所屬部門"),
        company=row.get("company") or row.get("所屬公司"),
        region=row.get("region") or row.get("所屬區域"),
        class_name=row.get("class_name") or row.get("課別"),
    )
    if role not in ALLOWED_EDOC_ROLES:
        role = derive_edoc_role_from_roster(
            job_level=job_level,
            title=row.get("title") or row.get("職稱"),
            department=row.get("unit") or row.get("所屬部門"),
            company=row.get("company") or row.get("所屬公司"),
            region=row.get("region") or row.get("所屬區域"),
            class_name=row.get("class_name") or row.get("課別"),
        )
    return {
        "job_level": job_level,
        "role": role,
        "data_scope": derive_edoc_data_scope_from_roster(job_level, role),
    }


def apply_user_permission_defaults(payload: Dict[str, Any]) -> None:
    if "job_level" in payload:
        payload["job_level"] = normalize_edoc_job_level(payload.get("job_level"))
    profile = edoc_roster_permission_profile(payload)
    payload.setdefault("job_level", profile["job_level"])
    if not payload.get("role") or payload.get("role") not in ALLOWED_EDOC_ROLES:
        payload["role"] = profile["role"]


def canonical_logging_role(role: Any) -> str:
    raw = roster_text(role)
    return LOGGING_ROLE_ALIASES.get(raw, raw)


def logging_role_profile(role: Any) -> Dict[str, str]:
    canonical = canonical_logging_role(role)
    return {"logging_role_key": canonical, **LOGGING_ROLE_TO_EDOC_PROFILE.get(canonical, LOGGING_ROLE_TO_EDOC_PROFILE["staff"])}


def canonical_hris_quick_login_payload(user: Dict[str, Any]) -> str:
    payload = {
        "id": roster_text(user.get("id")),
        "email": roster_text(user.get("email")),
        "role": roster_text(user.get("role")),
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))


def base64url_decode(value: str) -> bytes:
    text = urllib.parse.unquote(roster_text(value))
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode((text + padding).encode("utf-8"))


def base64url_json(value: str) -> Dict[str, Any]:
    decoded = base64url_decode(value).decode("utf-8")
    parsed = json.loads(decoded)
    return parsed if isinstance(parsed, dict) else {}


def base64url_hmac_sha256(secret: str, value: str) -> str:
    digest = hmac.new(secret.encode("utf-8"), value.encode("utf-8"), hashlib.sha256).digest()
    return base64.urlsafe_b64encode(digest).decode("utf-8").rstrip("=")


def verify_portal_handoff_payload(payload: Dict[str, Any]) -> Tuple[Dict[str, Any], str | None]:
    encoded_payload = roster_text(payload.get("payload"))
    signature = roster_text(payload.get("signature"))
    token = roster_text(payload.get("token"))
    if token and (not encoded_payload or not signature):
        parts = token.split(".", 1)
        if len(parts) == 2:
            encoded_payload, signature = parts
    if not encoded_payload or not signature:
        return {}, "missing_portal_handoff"
    if not PORTAL_HANDOFF_SECRET:
        return {}, "missing_portal_handoff_secret"
    if len(PORTAL_HANDOFF_SECRET.encode("utf-8")) < PORTAL_HANDOFF_MIN_SECRET_BYTES:
        return {}, "insecure_portal_handoff_secret"
    expected = base64url_hmac_sha256(PORTAL_HANDOFF_SECRET, encoded_payload)
    if not hmac.compare_digest(signature, expected):
        return {}, "invalid_signature"
    try:
        decoded = base64url_json(encoded_payload)
    except Exception:
        return {}, "invalid_payload"
    if decoded.get("moduleId") != "edoc":
        return {}, "invalid_target_module"
    now_ts = int(time.time())
    try:
        exp = int(decoded.get("exp") or 0)
        iat = int(decoded.get("iat") or 0)
    except (TypeError, ValueError):
        return {}, "invalid_portal_handoff_lifetime"
    if is_production():
        if not iat or not exp:
            return {}, "missing_portal_handoff_lifetime"
        if exp <= iat or exp - iat > PORTAL_HANDOFF_MAX_AGE_SECONDS:
            return {}, "invalid_portal_handoff_lifetime"
        if now_ts - iat > PORTAL_HANDOFF_MAX_AGE_SECONDS:
            return {}, "expired_portal_handoff"
    if exp and exp <= now_ts:
        return {}, "expired_portal_handoff"
    if iat and iat > now_ts + 300:
        return {}, "invalid_issued_at"
    if iat and not exp and now_ts - iat > PORTAL_HANDOFF_MAX_AGE_SECONDS:
        return {}, "expired_portal_handoff"
    jti = roster_text(decoded.get("jti"))
    if not re.fullmatch(r"[A-Za-z0-9_-]{16,128}", jti):
        return {}, "invalid_portal_handoff_jti"
    return decoded, None


def portal_handoff_jti_hash(jti: str) -> str:
    return hashlib.sha256(jti.encode("utf-8")).hexdigest()


def claim_sqlite_portal_handoff_jti(conn: sqlite3.Connection, payload: Dict[str, Any]) -> bool:
    """Atomically consume one signed Portal handoff without storing its raw jti."""
    jti_hash = portal_handoff_jti_hash(roster_text(payload.get("jti")))
    now_ts = int(time.time())
    try:
        conn.execute("DELETE FROM portal_handoff_nonces WHERE expires_at < ?", (now_ts - 3600,))
        conn.execute(
            """
            INSERT INTO portal_handoff_nonces (jti_hash, issued_at, expires_at, consumed_at)
            VALUES (?, ?, ?, ?)
            """,
            (jti_hash, int(payload.get("iat") or 0), int(payload.get("exp") or 0), now()),
        )
        return True
    except sqlite3.IntegrityError:
        return False


def verify_hris_quick_login_signature(payload: Dict[str, Any]) -> bool:
    if payload.get("v") != 1 or not isinstance(payload.get("user"), dict) or not payload.get("signature"):
        return False
    signature = roster_text(payload.get("signature"))
    expected = hmac.new(
        HRIS_QUICK_LOGIN_SECRET.encode("utf-8"),
        canonical_hris_quick_login_payload(payload["user"]).encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    return hmac.compare_digest(signature, expected)


def extract_logging_bridge_user(payload: Dict[str, Any]) -> Tuple[Dict[str, Any], str | None]:
    if not isinstance(payload, dict):
        return {}, "invalid_payload"

    if payload.get("token") or (payload.get("payload") and payload.get("signature")):
        portal_payload, error = verify_portal_handoff_payload(payload)
        if error:
            return {}, error
        return portal_payload, None

    signed_payload = payload if payload.get("signature") else payload.get("signedPayload")
    if isinstance(signed_payload, dict) and signed_payload.get("signature"):
        if is_production():
            return {}, "portal_handoff_required"
        if not verify_hris_quick_login_signature(signed_payload):
            return {}, "invalid_signature"
        return dict(signed_payload["user"]), None

    source = payload.get("user") or payload.get("currentUser") or payload.get("profile")
    if not source and isinstance(payload.get("session"), dict):
        source = payload["session"].get("user")
    if not source:
        source = payload
    if not isinstance(source, dict):
        return {}, "missing_user"
    # Production accepts only the short-lived, HMAC-signed Portal handoff above.
    # A browser value merely named accessToken/idToken is not proof that Finance
    # or Google issued it, so raw payloads must never establish a session.
    if is_production():
        return {}, "unsigned_bridge_payload"
    return dict(source), None


def portal_finance_identity(source_user: Dict[str, Any]) -> Tuple[str, str]:
    """Return only the server-stamped identity fields trusted at the EDOC boundary."""
    auth_user_id = roster_text(source_user.get("authUserId") or source_user.get("auth_user_id"))
    email = roster_text(source_user.get("email")).lower()
    if not auth_user_id or not email:
        raise PortalFinanceIdentityDenied()
    return auth_user_id, email


def select_preprovisioned_finance_user(
    rows: Iterable[Dict[str, Any]],
    auth_user_id: str,
    email: str,
) -> Tuple[Dict[str, Any], bool]:
    """Fail closed unless one active Finance row owns the exact email and auth id.

    This selector deliberately ignores role, company, manager and permission fields
    from the handoff.  A future Finance sync adapter may provision those canonical
    values in EDOC, but a browser-originated handoff may never do so.
    """
    unique_rows: Dict[str, Dict[str, Any]] = {}
    for raw_row in rows:
        row = dict(raw_row)
        row_id = roster_text(row.get("id"))
        if row_id:
            unique_rows[row_id] = row

    normalized_email = roster_text(email).lower()
    email_matches = [
        row
        for row in unique_rows.values()
        if roster_text(row.get("email")).lower() == normalized_email
    ]
    if len(email_matches) != 1:
        raise PortalFinanceIdentityDenied()

    candidate = email_matches[0]
    if roster_text(candidate.get("account_source")).lower() != "finance":
        raise PortalFinanceIdentityDenied()
    if roster_text(candidate.get("status")) != "啟用":
        raise PortalFinanceIdentityDenied()

    candidate_auth_user_id = roster_text(candidate.get("auth_user_id"))
    if candidate_auth_user_id and candidate_auth_user_id != auth_user_id:
        raise PortalFinanceIdentityDenied()

    auth_matches = [
        row
        for row in unique_rows.values()
        if roster_text(row.get("auth_user_id")) == auth_user_id
    ]
    if any(roster_text(row.get("id")) != roster_text(candidate.get("id")) for row in auth_matches):
        raise PortalFinanceIdentityDenied()

    return candidate, not candidate_auth_user_id


def resolve_preprovisioned_portal_user(
    conn: sqlite3.Connection,
    source_user: Dict[str, Any],
) -> sqlite3.Row:
    """Resolve and, when safe, bind one preprovisioned SQLite Finance user."""
    auth_user_id, email = portal_finance_identity(source_user)
    rows = conn.execute(
        """
        SELECT * FROM users
        WHERE auth_user_id = ? OR lower(email) = ?
        ORDER BY rowid
        """,
        (auth_user_id, email),
    ).fetchall()
    candidate, should_bind = select_preprovisioned_finance_user(
        (row_to_dict(row) for row in rows),
        auth_user_id,
        email,
    )

    if should_bind:
        conn.execute(
            """
            UPDATE users
            SET auth_user_id = ?
            WHERE id = ?
              AND COALESCE(auth_user_id, '') = ''
              AND lower(email) = ?
              AND lower(account_source) = 'finance'
              AND status = '啟用'
              AND NOT EXISTS (
                SELECT 1 FROM users conflicting_user
                WHERE conflicting_user.id <> users.id
                  AND conflicting_user.auth_user_id = ?
              )
            """,
            (auth_user_id, candidate["id"], email, auth_user_id),
        )

    refreshed_rows = conn.execute(
        """
        SELECT * FROM users
        WHERE auth_user_id = ? OR lower(email) = ?
        ORDER BY rowid
        """,
        (auth_user_id, email),
    ).fetchall()
    refreshed, _ = select_preprovisioned_finance_user(
        (row_to_dict(row) for row in refreshed_rows),
        auth_user_id,
        email,
    )
    if roster_text(refreshed.get("auth_user_id")) != auth_user_id:
        raise PortalFinanceIdentityDenied()
    row = conn.execute("SELECT * FROM users WHERE id = ?", (refreshed["id"],)).fetchone()
    if not row:
        raise PortalFinanceIdentityDenied()
    return row


def logging_permissions_to_edoc_codes(logging_permissions: Iterable[Any]) -> List[str]:
    codes: set[str] = set()
    for permission in logging_permissions or []:
        for code in LOGGING_PERMISSION_TO_EDOC_CODES.get(str(permission), []):
            codes.add(code)
    return sorted(codes)


def finance_company_profile(source_user: Dict[str, Any]) -> Dict[str, str]:
    raw_id = roster_text(
        source_user.get("companyId")
        or source_user.get("company_id")
        or source_user.get("entityId")
        or source_user.get("entity_id")
    )
    raw_name = roster_text(source_user.get("company") or source_user.get("companyName") or source_user.get("company_name"))
    for company in FINANCE_COMPANY_DIRECTORY:
        if raw_id and raw_id in {company["id"], company["finance_entity_id"]}:
            return dict(company)
        if raw_name and raw_name == company["name"]:
            return dict(company)
    alias_id = FINANCE_COMPANY_NAME_ALIASES.get(raw_name)
    if alias_id:
        return dict(next(company for company in FINANCE_COMPANY_DIRECTORY if company["id"] == alias_id))
    return {
        "id": raw_id if raw_id.startswith("CO-") else "",
        "finance_entity_id": raw_id if raw_id.startswith("E") else "",
        "name": raw_name,
        "tax_id": "",
        "address": roster_text(source_user.get("companyAddress") or source_user.get("company_address")),
    }


def finance_manager_profile(source_user: Dict[str, Any], prefix: str) -> Dict[str, str]:
    snake_prefix = "approval_manager" if prefix == "approvalManager" else "manager"
    employee_id = roster_text(source_user.get(f"{prefix}EmployeeId") or source_user.get(f"{snake_prefix}_employee_id"))
    email = roster_text(source_user.get(f"{prefix}Email") or source_user.get(f"{snake_prefix}_email")).lower()
    name = roster_text(source_user.get(f"{prefix}Name") or source_user.get(f"{snake_prefix}_name"))
    role_key = canonical_logging_role(
        source_user.get(f"{prefix}RoleKey")
        or source_user.get(f"{snake_prefix}_role_key")
        or "section_chief"
    )
    if role_key not in LOGGING_ROLE_TO_EDOC_PROFILE:
        role_key = "section_chief"
    return {
        "employee_id": employee_id,
        "email": email,
        "name": name,
        "role_key": role_key,
    }


FINANCE_BRIDGE_ACTOR_SLOTS = {
    "applicant_manager": "applicantManager",
    "department_head": "departmentHead",
    "ceo": "ceo",
    "admin_director": "adminDirector",
    "general_affairs_review": "generalAffairs",
}
FINANCE_BRIDGE_ACTOR_ALLOWED_ROLES = {
    # Finance's live organization resolver intentionally lets an
    # admin-director/CEO be the manager-level fallback for senior applicants.
    # The actor is still selected by Finance and cannot be supplied by the
    # browser, so accepting these canonical upper-level roles preserves the
    # Finance chain without weakening actor selection.
    "applicantManager": {
        "section_chief",
        "team_lead",
        "district_manager",
        "department_head",
        "admin_director",
        "ceo",
    },
    "departmentHead": {"department_head", "admin_director", "ceo"},
    "ceo": {"ceo"},
    "adminDirector": {"admin_director"},
    "generalAffairs": {"ga_chief"},
}


def strict_finance_role_profile(role: Any) -> Dict[str, str]:
    """Map only an explicitly supported Finance role; never default to staff."""
    canonical = canonical_logging_role(role)
    profile = LOGGING_ROLE_TO_EDOC_PROFILE.get(canonical)
    if not profile:
        raise FinanceBridgeDenied("finance_role_unsupported")
    return {"logging_role_key": canonical, **profile}


def current_finance_bridge_snapshot(email: str) -> Dict[str, Any]:
    """Fetch one live snapshot; request ids are random and never include PII."""
    return fetch_finance_bridge_snapshot(
        url=EDOC_FINANCE_BRIDGE_URL,
        secret=EDOC_FINANCE_BRIDGE_SECRET,
        timeout_seconds=EDOC_FINANCE_BRIDGE_TIMEOUT_SECONDS,
        email=str(email or "").strip().lower(),
        request_id=f"edoc-{secrets.token_hex(12)}",
        require_https=is_production(),
    )


def finance_bridge_safe_snapshot_metadata(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    canonical = json.dumps(snapshot, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    identity = snapshot.get("identity") or {}
    return {
        "source": "finance_bridge",
        "schemaVersion": FINANCE_BRIDGE_SCHEMA_VERSION,
        "snapshotAt": str(snapshot.get("snapshotAt") or ""),
        "sourceUpdatedAt": str(identity.get("sourceUpdatedAt") or ""),
        "workflowReady": bool(snapshot.get("workflowReady")),
        "issueCount": len(snapshot.get("issues") or []),
        "snapshotSha256": hashlib.sha256(canonical).hexdigest(),
    }


def normalize_finance_bridge_actor(
    actor: Dict[str, Any],
    slot: str,
) -> Dict[str, Any]:
    required_text = {
        key: roster_text(actor.get(key))
        for key in (
            "financeUserId",
            "name",
            "email",
            "role",
            "roleLabel",
            "entityId",
            "departmentCode",
            "sourceUpdatedAt",
        )
    }
    if any(not value for value in required_text.values()) or "@" not in required_text["email"]:
        raise FinanceBridgeContractError("finance_bridge_actor_invalid")
    finance_user_id = required_text["financeUserId"]
    name = required_text["name"]
    email = required_text["email"].lower()
    for key in ("active", "authUserBound", "googleLoginVerified"):
        if actor.get(key) is not True:
            raise FinanceBridgeDenied("finance_workflow_actor_inactive")
    org_status = roster_text(actor.get("orgStatus"))
    if org_status.lower() not in {"active", "enabled", "啟用", "在職"}:
        raise FinanceBridgeDenied("finance_workflow_actor_inactive")
    profile = strict_finance_role_profile(required_text["role"])
    if profile["logging_role_key"] not in FINANCE_BRIDGE_ACTOR_ALLOWED_ROLES[slot]:
        raise FinanceBridgeDenied("finance_workflow_actor_role_mismatch")
    source_revision = actor.get("memberRevision", 0)
    if isinstance(source_revision, bool) or not isinstance(source_revision, int) or source_revision < 0:
        raise FinanceBridgeContractError("finance_bridge_actor_invalid")
    return {
        "slot": slot,
        "finance_user_id": finance_user_id,
        "name": name,
        "email": email,
        "role_label": required_text["roleLabel"],
        "department_code": required_text["departmentCode"],
        "department_name": roster_text(actor.get("departmentName") or actor.get("unitName")),
        "job_title": roster_text(actor.get("jobTitle")),
        "extension": roster_text(actor.get("extension")),
        "contact_email": roster_text(actor.get("contactEmail")).lower(),
        "entity_id": required_text["entityId"],
        "source_updated_at": required_text["sourceUpdatedAt"],
        "source_revision": source_revision,
        "projection_state": "active",
        "profile": profile,
    }


def normalize_finance_bridge_snapshot(
    snapshot: Dict[str, Any],
    *,
    require_workflow: bool = False,
    required_step_keys: Iterable[str] = (),
) -> Dict[str, Any]:
    identity = snapshot.get("identity") or {}
    applicant_profile = strict_finance_role_profile(identity.get("role"))
    source_revision = identity.get("memberRevision", 0)
    if isinstance(source_revision, bool) or not isinstance(source_revision, int) or source_revision < 0:
        raise FinanceBridgeContractError("finance_bridge_identity_invalid")
    identity_active = identity.get("active") is True
    org_active = roster_text(identity.get("orgStatus")).lower() in {"active", "enabled", "啟用", "在職"}
    company_active = (snapshot.get("company") or {}).get("active", True) is not False
    login_ready = identity.get("authUserBound") is True and identity.get("googleLoginVerified") is True
    projection_state = (
        "active"
        if identity_active and org_active and company_active and login_ready
        else "pending"
        if identity_active and org_active and company_active
        else "inactive"
    )
    applicant = {
        "finance_user_id": roster_text(identity.get("financeUserId")),
        "name": roster_text(identity.get("name")),
        "email": roster_text(identity.get("email")).lower(),
        "role_label": roster_text(identity.get("roleLabel")) or applicant_profile["title"],
        "department_code": roster_text(identity.get("departmentCode")) or applicant_profile["unit"],
        "department_name": roster_text(identity.get("departmentName") or identity.get("unitName")),
        "job_title": roster_text(identity.get("jobTitle")),
        "extension": roster_text(identity.get("extension")),
        "contact_email": roster_text(identity.get("contactEmail")).lower(),
        "entity_id": roster_text(identity.get("entityId")),
        "auth_user_id": (
            roster_text(identity.get("authUserId"))
            if identity_active and org_active and company_active and login_ready
            else ""
        ),
        "source_revision": source_revision,
        "source_updated_at": roster_text(identity.get("sourceUpdatedAt")),
        "projection_state": projection_state,
        "profile": applicant_profile,
    }
    if not all(applicant.get(key) for key in ("finance_user_id", "name", "email", "entity_id")):
        raise FinanceBridgeContractError("finance_bridge_identity_invalid")
    required_slots = {
        FINANCE_BRIDGE_ACTOR_SLOTS[key]
        for key in required_step_keys
        if key in FINANCE_BRIDGE_ACTOR_SLOTS
    }
    normalized_actors: Dict[str, Dict[str, Any]] = {}
    raw_actors = snapshot.get("actors") or {}
    # Actor validity is route-specific.  Do not let an optional actor that is
    # irrelevant to this applicant/route (for example CEO on A/B, or a skipped
    # lower manager for a 主任 applicant) block login or a lawful submission.
    # Every actor that will actually receive a step remains mandatory and is
    # validated below.
    for slot in FINANCE_BRIDGE_ACTOR_ALLOWED_ROLES:
        raw_actor = raw_actors.get(slot)
        if raw_actor is None:
            if slot in required_slots:
                raise FinanceBridgeDenied("finance_workflow_actor_missing")
            continue
        try:
            normalized_actors[slot] = normalize_finance_bridge_actor(raw_actor, slot)
        except (FinanceBridgeContractError, FinanceBridgeDenied):
            if slot in required_slots:
                raise
            # A valid optional actor is still synchronized so login can retain
            # manager metadata.  Invalid optional actors are ignored and can
            # never become part of the route-specific approval plan.
            continue
    if required_slots - set(normalized_actors):
        raise FinanceBridgeDenied("finance_workflow_actor_missing")
    return {
        "applicant": applicant,
        "actors": normalized_actors,
        "metadata": finance_bridge_safe_snapshot_metadata(snapshot),
    }


def sqlite_finance_company_by_entity(
    conn: sqlite3.Connection,
    entity_id: str,
    *,
    require_launch_scope: bool = True,
) -> Dict[str, Any]:
    rows = conn.execute(
        "SELECT * FROM companies WHERE finance_entity_id = ? AND status = 'active' ORDER BY id",
        (str(entity_id or "").strip(),),
    ).fetchall()
    if len(rows) != 1:
        raise FinanceBridgeDenied("finance_company_unmapped")
    company = row_to_dict(rows[0])
    if (
        require_launch_scope
        and is_production()
        and launch_company_scope_mode() == "manual_allowlist"
        and not launch_company_scope_ids()
    ):
        raise FinanceBridgeDenied("finance_company_launch_scope_required")
    if require_launch_scope and not launch_company_in_scope(str(company.get("id") or "")):
        raise FinanceBridgeDenied("finance_company_outside_launch_scope")
    return company


def _sqlite_upsert_finance_snapshot_user(
    conn: sqlite3.Connection,
    source: Dict[str, Any],
    company: Dict[str, Any],
    metadata: Dict[str, Any],
    *,
    auth_user_id: str = "",
    manager: Dict[str, Any] | None = None,
    department_head: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    finance_user_id = source["finance_user_id"]
    email = source["email"]
    auth_user_id = roster_text(auth_user_id)
    rows = conn.execute(
        """
        SELECT * FROM users
        WHERE logging_account_id = ? OR finance_employee_id = ? OR lower(email) = ?
           OR (? <> '' AND auth_user_id = ?)
        ORDER BY rowid
        """,
        (finance_user_id, finance_user_id, email, auth_user_id, auth_user_id),
    ).fetchall()
    unique = {str(row["id"]): row for row in rows}
    if len(unique) > 1:
        raise FinanceBridgeDenied("finance_identity_ambiguous")
    existing = next(iter(unique.values()), None)
    if existing:
        existing_source = roster_text(existing["account_source"]).lower()
        existing_finance_id = roster_text(existing["logging_account_id"] or existing["finance_employee_id"])
        existing_auth_id = roster_text(existing["auth_user_id"])
        if existing_source not in {"", "finance"}:
            raise FinanceBridgeDenied("finance_identity_conflict")
        if existing_finance_id and existing_finance_id != finance_user_id:
            raise FinanceBridgeDenied("finance_identity_conflict")
        if auth_user_id and existing_auth_id and existing_auth_id != auth_user_id:
            raise FinanceBridgeDenied("finance_identity_conflict")

    profile = source["profile"]
    values: Dict[str, Any] = {
        "account_source": "finance",
        "logging_account_id": finance_user_id,
        "logging_role_key": profile["logging_role_key"],
        "finance_employee_id": finance_user_id,
        "company_id": company["id"],
        "company_name": company["name"],
        "company_address": company.get("address") or "",
        "external_account_payload_json": json.dumps({
            **metadata,
            "financeProfile": {
                "departmentName": source.get("department_name") or "",
                "jobTitle": source.get("job_title") or "",
                "extension": source.get("extension") or "",
                "contactEmail": source.get("contact_email") or "",
            },
        }, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
        "last_synced_from_logging_at": now(),
        "name": source["name"],
        "email": email,
        "unit": source.get("department_name") or source["department_code"],
        "title": source.get("job_title") or source["role_label"],
        "job_level": profile["job_level"],
        "role": profile["role"],
        "provider": "Finance Google SSO",
        "mfa_status": "由 Finance 管理",
        "status": "啟用",
    }
    if auth_user_id:
        values["auth_user_id"] = auth_user_id
    if manager:
        values.update({
            "manager_employee_id": manager["finance_user_id"],
            "manager_name": manager["name"],
            "manager_email": manager["email"],
            "manager_role_key": manager["profile"]["logging_role_key"],
        })
    if department_head:
        values.update({
            "approval_manager_employee_id": department_head["finance_user_id"],
            "approval_manager_name": department_head["name"],
            "approval_manager_email": department_head["email"],
            "approval_manager_role_key": department_head["profile"]["logging_role_key"],
        })

    if existing:
        assignments = ", ".join(f"{key} = ?" for key in values)
        conn.execute(f"UPDATE users SET {assignments} WHERE id = ?", [*values.values(), existing["id"]])
        user_id = existing["id"]
    else:
        user_id = f"FIN-{hashlib.sha256(finance_user_id.encode('utf-8')).hexdigest()[:12].upper()}"
        insert_values = {"id": user_id, **values, "created_at": now()}
        columns = ", ".join(insert_values)
        placeholders = ", ".join("?" for _ in insert_values)
        conn.execute(
            f"INSERT INTO users ({columns}) VALUES ({placeholders})",
            list(insert_values.values()),
        )
    row = conn.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
    if not row:
        raise FinanceBridgeUnavailable("finance_identity_sync_failed")
    return row_to_dict(row)


def sync_sqlite_finance_snapshot(
    conn: sqlite3.Connection,
    snapshot: Dict[str, Any],
    *,
    auth_user_id: str = "",
    expected_user_id: str = "",
    require_workflow: bool = False,
    required_step_keys: Iterable[str] = (),
) -> Tuple[Dict[str, Any], Dict[str, Dict[str, Any]]]:
    required_step_keys = tuple(required_step_keys)
    normalized = normalize_finance_bridge_snapshot(
        snapshot,
        require_workflow=require_workflow,
        required_step_keys=required_step_keys,
    )
    company_cache: Dict[Tuple[str, bool], Dict[str, Any]] = {}

    def company_for(entity_id: str, *, require_launch_scope: bool) -> Dict[str, Any]:
        cache_key = (entity_id, require_launch_scope)
        if cache_key not in company_cache:
            company_cache[cache_key] = sqlite_finance_company_by_entity(
                conn,
                entity_id,
                require_launch_scope=require_launch_scope,
            )
        return company_cache[cache_key]

    applicant = normalized["applicant"]
    applicant_company = company_for(applicant["entity_id"], require_launch_scope=True)
    actor_sources = normalized["actors"]
    # Resolve every company and validate every identity before the first write.
    for actor in actor_sources.values():
        company_for(actor["entity_id"], require_launch_scope=False)

    snapshot_company = snapshot["company"]
    conn.execute(
        """
        UPDATE companies
        SET name = ?, tax_id = ?, address = ?, source_system = 'finance',
            last_synced_from_finance_at = ?, updated_at = ?
        WHERE id = ? AND finance_entity_id = ? AND status = 'active'
        """,
        (
            snapshot_company["name"], snapshot_company.get("taxId") or "",
            snapshot_company.get("address") or "", now(), now(),
            applicant_company["id"], applicant["entity_id"],
        ),
    )
    applicant_company = sqlite_finance_company_by_entity(
        conn,
        applicant["entity_id"],
        require_launch_scope=True,
    )
    company_cache[(applicant["entity_id"], True)] = applicant_company
    company_cache[(applicant["entity_id"], False)] = applicant_company
    actor_users: Dict[str, Dict[str, Any]] = {}
    for slot, actor in actor_sources.items():
        actor_users[slot] = _sqlite_upsert_finance_snapshot_user(
            conn,
            actor,
            company_for(actor["entity_id"], require_launch_scope=False),
            normalized["metadata"],
        )
    user = _sqlite_upsert_finance_snapshot_user(
        conn,
        applicant,
        applicant_company,
        normalized["metadata"],
        auth_user_id=auth_user_id,
        manager=actor_sources.get("applicantManager"),
        department_head=actor_sources.get("departmentHead"),
    )
    if expected_user_id and user["id"] != expected_user_id:
        raise FinanceBridgeDenied("finance_identity_mismatch")
    required_plan_keys = set(required_step_keys)
    plan = {
        step_key: actor_users[slot]
        for step_key, slot in FINANCE_BRIDGE_ACTOR_SLOTS.items()
        if slot in actor_users and (not require_workflow or step_key in required_plan_keys)
    }
    plan["applicant_confirm"] = user
    return user, plan


def upsert_finance_manager_placeholder(
    conn: sqlite3.Connection,
    manager: Dict[str, str],
    source_user: Dict[str, Any],
    company: Dict[str, str],
    ts: str,
) -> Dict[str, Any] | None:
    employee_id = manager.get("employee_id") or ""
    email = (manager.get("email") or "").lower()
    if not employee_id and not email:
        return None
    conditions: List[str] = []
    params: List[Any] = []
    if employee_id:
        conditions.append("finance_employee_id = ?")
        params.append(employee_id)
    if email:
        conditions.append("lower(email) = ?")
        params.append(email)
    existing = conn.execute(
        f"SELECT * FROM users WHERE {' OR '.join(conditions)} ORDER BY rowid LIMIT 1",
        params,
    ).fetchone()
    profile = logging_role_profile(manager.get("role_key") or "section_chief")
    account_id = employee_id or email
    display_name = manager.get("name") or (email.split("@")[0] if email else account_id)
    manager_email = email or f"{employee_id.lower()}@finance.local"
    unit = roster_text(source_user.get("department") or source_user.get("unit") or profile["unit"])
    values = {
        "account_source": "finance",
        "logging_account_id": account_id,
        "logging_role_key": profile["logging_role_key"],
        "finance_employee_id": employee_id,
        "company_id": company.get("id") or "",
        "company_name": company.get("name") or "",
        "company_address": company.get("address") or "",
        "external_account_payload_json": json.dumps({"source": "finance_manager_reference"}, ensure_ascii=False),
        "last_synced_from_logging_at": ts,
        "name": display_name,
        "email": manager_email,
        "unit": unit,
        "title": profile["title"],
        "job_level": profile["job_level"],
        "role": profile["role"],
        "provider": "Finance Google SSO",
        "mfa_status": "由 Finance 管理",
        "status": "啟用",
    }
    if existing:
        assignments = ", ".join(f"{key} = ?" for key in values)
        conn.execute(f"UPDATE users SET {assignments} WHERE id = ?", [*values.values(), existing["id"]])
        row = conn.execute("SELECT * FROM users WHERE id = ?", (existing["id"],)).fetchone()
        return row_to_dict(row) if row else None
    user_id = f"FIN-{hashlib.sha256(account_id.encode('utf-8')).hexdigest()[:12].upper()}"
    conn.execute(
        """
        INSERT INTO users (
          id, auth_user_id, account_source, logging_account_id, logging_role_key, finance_employee_id,
          company_id, company_name, company_address, external_account_payload_json,
          last_synced_from_logging_at, name, email, password_hash, unit, title, job_level, role,
          provider, mfa_status, status, last_login_at, created_at
        ) VALUES (?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?, ?, ?, ?, NULL, ?)
        """,
        (
            user_id,
            values["account_source"],
            values["logging_account_id"],
            values["logging_role_key"],
            values["finance_employee_id"],
            values["company_id"],
            values["company_name"],
            values["company_address"],
            values["external_account_payload_json"],
            values["last_synced_from_logging_at"],
            values["name"],
            values["email"],
            values["unit"],
            values["title"],
            values["job_level"],
            values["role"],
            values["provider"],
            values["mfa_status"],
            values["status"],
            ts,
        ),
    )
    row = conn.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
    return row_to_dict(row) if row else None


def upsert_logging_bridge_user(conn: sqlite3.Connection, payload: Dict[str, Any]) -> sqlite3.Row:
    source_user, error = extract_logging_bridge_user(payload)
    if error:
        raise ValueError(error)
    if is_production():
        auth_user_id, email = portal_finance_identity(source_user)
        snapshot = current_finance_bridge_snapshot(email)
        user, _ = sync_sqlite_finance_snapshot(
            conn,
            snapshot,
            auth_user_id=auth_user_id,
        )
        row = conn.execute("SELECT * FROM users WHERE id = ?", (user["id"],)).fetchone()
        if not row:
            raise FinanceBridgeUnavailable("finance_identity_sync_failed")
        return row
    logging_role_key = canonical_logging_role(source_user.get("loggingRoleKey") or source_user.get("logging_role_key") or source_user.get("role"))
    profile = logging_role_profile(logging_role_key)
    email = roster_text(source_user.get("email")).lower()
    if not email:
        raise ValueError("missing_email")
    logging_account_id = roster_text(source_user.get("loggingAccountId") or source_user.get("logging_account_id") or source_user.get("id") or source_user.get("profileId") or email)
    display_name = roster_text(source_user.get("name") or source_user.get("display_name") or source_user.get("roleLabel") or email.split("@")[0])
    unit = roster_text(source_user.get("unit") or source_user.get("department") or source_user.get("departmentCode") or source_user.get("department_code") or profile["unit"])
    title = roster_text(source_user.get("title") or source_user.get("roleLabel") or profile["title"])
    job_level = normalize_edoc_job_level(source_user.get("jobLevel") or source_user.get("job_level") or profile["job_level"])
    edoc_role = profile["role"]
    finance_employee_id = roster_text(source_user.get("employeeNo") or source_user.get("employeeId") or source_user.get("employee_id"))
    company = finance_company_profile(source_user)
    manager = finance_manager_profile(source_user, "manager")
    approval_manager = finance_manager_profile(source_user, "approvalManager")
    ts = now()
    external_payload = redact_sensitive(source_user)
    user = conn.execute(
        """
        SELECT * FROM users
        WHERE logging_account_id = ? OR (? <> '' AND finance_employee_id = ?) OR lower(email) = ?
        ORDER BY CASE WHEN logging_account_id = ? THEN 0 WHEN finance_employee_id = ? THEN 1 ELSE 2 END
        LIMIT 1
        """,
        (logging_account_id, finance_employee_id, finance_employee_id, email, logging_account_id, finance_employee_id),
    ).fetchone()
    before = row_to_dict(user) if user else {}
    if user:
        conn.execute(
            """
            UPDATE users
            SET auth_user_id = COALESCE(auth_user_id, ?),
                account_source = 'finance',
                logging_account_id = ?,
                logging_role_key = ?,
                finance_employee_id = ?,
                company_id = ?,
                company_name = ?,
                company_address = ?,
                manager_employee_id = ?,
                manager_name = ?,
                manager_email = ?,
                manager_role_key = ?,
                approval_manager_employee_id = ?,
                approval_manager_name = ?,
                approval_manager_email = ?,
                approval_manager_role_key = ?,
                external_account_payload_json = ?,
                last_synced_from_logging_at = ?,
                name = ?,
                email = ?,
                unit = ?,
                title = ?,
                job_level = ?,
                role = ?,
                provider = 'Finance Google SSO',
                mfa_status = '由 Finance 管理',
                status = '啟用'
            WHERE id = ?
            """,
            (
                roster_text(source_user.get("authUserId") or source_user.get("auth_user_id")) or None,
                logging_account_id,
                logging_role_key,
                finance_employee_id,
                company.get("id") or "",
                company.get("name") or "",
                company.get("address") or "",
                manager.get("employee_id") or "",
                manager.get("name") or "",
                manager.get("email") or "",
                manager.get("role_key") or "",
                approval_manager.get("employee_id") or "",
                approval_manager.get("name") or "",
                approval_manager.get("email") or "",
                approval_manager.get("role_key") or "",
                json.dumps(external_payload, ensure_ascii=False),
                ts,
                display_name,
                email,
                unit,
                title,
                job_level,
                edoc_role,
                user["id"],
            ),
        )
        user_id = user["id"]
    else:
        user_id = f"LOG-{hashlib.sha256(logging_account_id.encode('utf-8')).hexdigest()[:10].upper()}"
        conn.execute(
            """
            INSERT INTO users (
              id, auth_user_id, account_source, logging_account_id, logging_role_key, finance_employee_id,
              company_id, company_name, company_address,
              manager_employee_id, manager_name, manager_email, manager_role_key,
              approval_manager_employee_id, approval_manager_name, approval_manager_email, approval_manager_role_key,
              external_account_payload_json,
              last_synced_from_logging_at, name, email, password_hash, unit, title, job_level, role,
              provider, mfa_status, status, last_login_at, created_at
            ) VALUES (?, ?, 'finance', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?, 'Finance Google SSO', '由 Finance 管理', '啟用', NULL, ?)
            """,
            (
                user_id,
                roster_text(source_user.get("authUserId") or source_user.get("auth_user_id")) or None,
                logging_account_id,
                logging_role_key,
                finance_employee_id,
                company.get("id") or "",
                company.get("name") or "",
                company.get("address") or "",
                manager.get("employee_id") or "",
                manager.get("name") or "",
                manager.get("email") or "",
                manager.get("role_key") or "",
                approval_manager.get("employee_id") or "",
                approval_manager.get("name") or "",
                approval_manager.get("email") or "",
                approval_manager.get("role_key") or "",
                json.dumps(external_payload, ensure_ascii=False),
                ts,
                display_name,
                email,
                unit,
                title,
                job_level,
                edoc_role,
                ts,
            ),
        )
    upsert_finance_manager_placeholder(conn, manager, source_user, company, ts)
    upsert_finance_manager_placeholder(conn, approval_manager, source_user, company, ts)
    link_id = f"LINK-FINANCE-EDOC-{hashlib.sha256(logging_account_id.encode('utf-8')).hexdigest()[:10].upper()}"
    conn.execute(
        """
        INSERT INTO module_account_links (
          id, user_id, source_system, source_account_id, source_role_key, source_email,
          target_module, target_role_key, sync_status, metadata_json, last_synced_at, created_at, updated_at
        ) VALUES (?, ?, 'finance', ?, ?, ?, 'edoc', ?, 'active', ?, ?, ?, ?)
        ON CONFLICT(source_system, source_account_id, target_module) DO UPDATE SET
          user_id = excluded.user_id,
          source_role_key = excluded.source_role_key,
          source_email = excluded.source_email,
          target_role_key = excluded.target_role_key,
          sync_status = 'active',
          metadata_json = excluded.metadata_json,
          last_synced_at = excluded.last_synced_at,
          updated_at = excluded.updated_at
        """,
        (link_id, user_id, logging_account_id, logging_role_key, email, edoc_role, json.dumps({"source": "finance_google_sso"}, ensure_ascii=False), ts, ts, ts),
    )
    updated = conn.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
    after = row_to_dict(updated) if updated else {}
    if before and any(before.get(key) != after.get(key) for key in ("role", "job_level", "unit", "title", "status", "logging_role_key")):
        log_permission_change(
            conn,
            "Finance SSO Bridge",
            user_id,
            email,
            {key: before.get(key) for key in ("role", "job_level", "unit", "title", "status", "logging_role_key")},
            {key: after.get(key) for key in ("role", "job_level", "unit", "title", "status", "logging_role_key")},
            "Finance 人員主檔與公文收發電子用印系統角色、公司及主管關係同步。",
            ["system_permissions.manage"],
        )
    else:
        log_audit(
            conn,
            "Finance SSO Bridge",
            "同步外部帳號",
            "module_account_links",
            link_id,
            f"{email} / {logging_role_key} → {edoc_role}",
            event_type="external_account_status_change",
            result="success",
            module_code="system_permissions",
            resource_type="external_account",
            resource_id=link_id,
            data_scope="custom",
            actor_roles=["system_permissions.manage"],
            target_user_id=user_id,
            target_email=email,
            reason="Finance Google 帳號進入公文收發電子用印系統，自動同步帳號、公司與主管關係。",
            metadata={"source_system": "finance", "target_module": "edoc", "logging_role_key": logging_role_key, "company_id": company.get("id") or ""},
        )
    return updated


def authenticate_logging_bridge(conn: sqlite3.Connection, payload: Dict[str, Any], ip: str, device: str) -> Tuple[Dict[str, Any], int]:
    try:
        user = upsert_logging_bridge_user(conn, payload)
    except FinanceBridgeDenied:
        return {"error": "logging_bridge_denied", "detail": PORTAL_FINANCE_IDENTITY_ERROR}, 403
    except FinanceBridgeUnavailable:
        return {"error": "logging_bridge_unavailable", "detail": "finance_bridge_unavailable"}, 503
    except PortalFinanceIdentityDenied:
        return {"error": "logging_bridge_denied", "detail": PORTAL_FINANCE_IDENTITY_ERROR}, 403
    except ValueError as error:
        return {"error": "logging_bridge_denied", "detail": str(error)}, 403 if str(error) in {"invalid_signature", "unsigned_bridge_payload", "portal_handoff_required"} else 400
    if not user or user["status"] != "啟用" or user["role"] not in ALLOWED_EDOC_ROLES:
        return {"error": "role_forbidden", "detail": "此 Finance 帳號未授權使用公文收發電子用印系統。"}, 403
    session = create_session(conn, user, "Finance Google SSO", ip, device)
    session["bridge"] = {
        "sourceSystem": "finance",
        "loggingAccountId": user["logging_account_id"],
        "loggingRoleKey": user["logging_role_key"],
        "targetModule": "edoc",
        "targetRole": user["role"],
    }
    if not is_production():
        incoming_permissions = []
        if isinstance(payload.get("permissions"), list):
            incoming_permissions = payload["permissions"]
        elif isinstance(payload.get("user"), dict) and isinstance(payload["user"].get("permissions"), list):
            incoming_permissions = payload["user"]["permissions"]
        session["permissions"] = sorted(set(session["permissions"]) | set(logging_permissions_to_edoc_codes(incoming_permissions)))
    return session, 200


def authenticate_verified_portal_handoff_sqlite(
    conn: sqlite3.Connection,
    source_user: Dict[str, Any],
    ip: str,
    device: str,
) -> Tuple[Dict[str, Any], int]:
    """Create an EDOC bearer session from a payload already verified and consumed."""
    try:
        if is_production():
            auth_user_id, email = portal_finance_identity(source_user)
            snapshot = current_finance_bridge_snapshot(email)
            synced_user, _ = sync_sqlite_finance_snapshot(conn, snapshot, auth_user_id=auth_user_id)
            user = conn.execute("SELECT * FROM users WHERE id = ?", (synced_user["id"],)).fetchone()
            if not user:
                raise FinanceBridgeUnavailable("finance_identity_sync_failed")
        else:
            user = upsert_logging_bridge_user(conn, source_user)
    except FinanceBridgeDenied:
        return {"error": "logging_bridge_denied", "detail": PORTAL_FINANCE_IDENTITY_ERROR}, 403
    except FinanceBridgeUnavailable:
        return {"error": "logging_bridge_unavailable", "detail": "finance_bridge_unavailable"}, 503
    except PortalFinanceIdentityDenied:
        return {"error": "logging_bridge_denied", "detail": PORTAL_FINANCE_IDENTITY_ERROR}, 403
    except ValueError as error:
        return {"error": "logging_bridge_denied", "detail": str(error)}, 400
    if not user or user["status"] != "啟用" or user["role"] not in ALLOWED_EDOC_ROLES:
        return {"error": "role_forbidden", "detail": "此 Finance 帳號未授權使用公文收發電子用印系統。"}, 403
    session = create_session(conn, user, "Finance Google SSO", ip, device)
    session["bridge"] = {
        "sourceSystem": "finance",
        "loggingAccountId": user["logging_account_id"],
        "loggingRoleKey": user["logging_role_key"],
        "targetModule": "edoc",
        "targetRole": user["role"],
    }
    return session, 200


