def now() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def is_production() -> bool:
    return DEPLOYMENT_ENV in {"production", "prod"}


FINANCE_MASTER_GENERIC_WRITE_TABLES = {"users", "companies", "module_account_links"}


def finance_master_generic_write_blocked(table: str) -> bool:
    """Keep Finance-owned identity/company projections read-only at the EDOC API."""
    return is_production() and str(table or "").strip() in FINANCE_MASTER_GENERIC_WRITE_TABLES


def env_present(name: str) -> bool:
    return bool(os.getenv(name, "").strip())


def notification_email_sender() -> str:
    return (
        os.getenv("MAIL_FROM", "").strip()
        or os.getenv("RESEND_FROM", "").strip()
        or os.getenv("SMTP_FROM", "").strip()
    )


def resend_email_configured() -> bool:
    return env_present("RESEND_API_KEY") and bool(notification_email_sender())


def smtp_email_configured() -> bool:
    return env_present("SMTP_HOST") and env_present("SMTP_FROM")


def notification_email_configured() -> bool:
    return resend_email_configured() or smtp_email_configured()


def notification_email_provider() -> str:
    if env_present("RESEND_API_KEY") or env_present("MAIL_FROM") or env_present("RESEND_FROM"):
        return "Resend"
    if env_present("SMTP_HOST") or env_present("SMTP_FROM"):
        return "SMTP"
    return "未設定"


def notification_email_required_env() -> List[str]:
    if env_present("RESEND_API_KEY") or env_present("MAIL_FROM") or env_present("RESEND_FROM") or not smtp_email_configured():
        return ["RESEND_API_KEY", "MAIL_FROM"]
    required = ["SMTP_HOST", "SMTP_PORT", "SMTP_FROM", "SMTP_CREDENTIAL_EXPIRES_AT"]
    if env_present("SMTP_USERNAME") or env_present("SMTP_PASSWORD"):
        required.extend(["SMTP_USERNAME", "SMTP_PASSWORD"])
    return required


def object_storage_endpoint() -> str:
    explicit = os.getenv("EDOC_OBJECT_STORAGE_URL", "").strip().rstrip("/")
    if explicit:
        return explicit
    if EDOC_STORAGE_SUPABASE_URL:
        return f"{EDOC_STORAGE_SUPABASE_URL.rstrip('/')}/storage/v1"
    if EDOC_STORAGE_PROVIDER == "supabase" and SUPABASE_URL:
        return f"{SUPABASE_URL.rstrip('/')}/storage/v1"
    return (EDOC_OBJECT_STORAGE_URL or "").rstrip("/")


def _url_origin(value: str) -> tuple[str, str, int | None]:
    parsed = urllib.parse.urlparse(str(value or "").strip())
    return ((parsed.scheme or "").lower(), (parsed.hostname or "").lower(), parsed.port)


def storage_uses_database_supabase_project() -> bool:
    endpoint_origin = _url_origin(object_storage_endpoint())
    database_origin = _url_origin(SUPABASE_URL)
    return bool(endpoint_origin[0] and endpoint_origin[1] and endpoint_origin == database_origin)


def storage_service_role_key() -> str:
    """Return the server-only Storage credential without crossing projects.

    Existing same-project installations keep working with the database key.
    A dedicated Storage project must always provide its own key; silently
    sending the database key to another Supabase origin is both incorrect and
    an avoidable credential disclosure.
    """
    explicit = str(EDOC_STORAGE_SERVICE_ROLE_KEY or "").strip()
    if explicit:
        return explicit
    if storage_uses_database_supabase_project():
        return str(SUPABASE_SERVICE_ROLE_KEY or "").strip()
    return ""


def config_present(name: str) -> bool:
    if name == "EDOC_OBJECT_STORAGE_URL":
        return bool(object_storage_endpoint())
    if name == "EDOC_STORAGE_SERVICE_ROLE_KEY":
        return bool(storage_service_role_key())
    return env_present(name)


def av_endpoint_configuration() -> Dict[str, Any]:
    """Describe the production AV transports whose wire contracts exist.

    Editor V2 implements ClamAV's INSTREAM protocol over a direct TCP socket.
    It also implements the repository-owned HTTPS HMAC v1 gateway contract for
    Cloud Run.  Other HTTP providers remain unsupported even if an API key is
    present; accepting them here would make readiness disagree with the
    fail-closed scanner.
    """
    endpoint = (EDOC_AV_ENDPOINT or "").strip()
    parsed = urllib.parse.urlparse(endpoint)
    scheme = (parsed.scheme or "").lower()
    hostname = parsed.hostname or ""
    port = 0
    valid_port = True
    try:
        port = int(parsed.port or (443 if scheme == "https" else 3310))
        valid_port = 1 <= port <= 65535
    except (TypeError, ValueError):
        valid_port = False
    provider = str(EDOC_AV_PROVIDER or "").strip().lower()
    safe_https_endpoint = bool(
        scheme == "https"
        and not parsed.username
        and not parsed.password
        and not parsed.query
        and not parsed.fragment
        and parsed.path in {"", "/", "/v1/scan"}
        and port in {443}
    )
    endpoint_configured = bool(endpoint and scheme and hostname and valid_port)
    direct_clamd = endpoint_configured and scheme in {"tcp", "clamd"}
    https_hmac = bool(
        endpoint_configured
        and safe_https_endpoint
        and provider in {"edoc-clamav-https-v1", "clamav-https-v1"}
    )
    api_key_configured = len(os.getenv("EDOC_AV_API_KEY", "").encode("utf-8")) >= 32
    sandbox_provider = provider == VERCEL_SANDBOX_AV_PROVIDER_ID
    sandbox_snapshot_configured = bool(
        re.fullmatch(r"snap_[A-Za-z0-9]{16,128}", str(EDOC_AV_SANDBOX_SNAPSHOT_ID or "").strip())
    )
    # Vercel injects a project-scoped OIDC token into production Functions.
    # Explicit tokens remain useful only for a local operator smoke test.
    sandbox_credential_configured = bool(
        RUNNING_ON_VERCEL
        or env_present("VERCEL_OIDC_TOKEN")
        or env_present("VERCEL_TOKEN")
    )
    contract_supported = direct_clamd or https_hmac or sandbox_provider
    endpoint_required = not sandbox_provider
    transport_configured = bool(
        (sandbox_provider and sandbox_snapshot_configured)
        or (not sandbox_provider and endpoint_configured)
    )
    credential_configured = bool(
        direct_clamd
        or (https_hmac and api_key_configured)
        or (sandbox_provider and sandbox_credential_configured)
    )
    credential_mode = (
        "vercel-oidc"
        if sandbox_provider
        else "direct-clamd-no-api-key"
        if direct_clamd
        else "hmac-sha256"
        if api_key_configured
        else "not-configured"
    )
    return {
        "endpoint": endpoint,
        "scheme": scheme,
        "hostname": hostname,
        "port": port,
        "endpointConfigured": endpoint_configured,
        "endpointRequired": endpoint_required,
        "transportConfigured": transport_configured,
        "contractSupported": contract_supported,
        "contract": (
            VERCEL_SANDBOX_AV_PROVIDER_ID
            if sandbox_provider
            else "clamd-instream"
            if direct_clamd
            else "edoc-clamav-https-v1"
            if https_hmac
            else (f"unsupported:{scheme}" if scheme else "not-configured")
        ),
        "credentialConfigured": credential_configured,
        "credentialMode": credential_mode,
        "requiresApiKey": https_hmac,
        "sandboxSnapshotConfigured": sandbox_snapshot_configured,
        "sandboxProjectConfigured": bool(str(EDOC_AV_SANDBOX_PROJECT_ID or "").strip()),
    }


def av_required_environment_names() -> List[str]:
    required = ["EDOC_SCAN_ENGINE", "EDOC_AV_PROVIDER"]
    av = av_endpoint_configuration()
    if av.get("contract") == VERCEL_SANDBOX_AV_PROVIDER_ID:
        required.append("EDOC_AV_SANDBOX_SNAPSHOT_ID")
    else:
        required.append("EDOC_AV_ENDPOINT")
    if av_endpoint_configuration()["requiresApiKey"]:
        required.append("EDOC_AV_API_KEY")
    return required


def internal_antivirus_readiness() -> Dict[str, Any]:
    """Return a public-safe, configuration-only AV readiness signal.

    The internal launch endpoint is intentionally public so operations can use
    it before login is released.  Do not expose the configured AV host or port
    here.  A green signal means the implemented clamd INSTREAM contract is
    configured; the launch user journeys still provide the runtime scan proof.
    """
    av = av_endpoint_configuration()
    scan_engine_configured = env_present("EDOC_SCAN_ENGINE")
    provider_configured = env_present("EDOC_AV_PROVIDER")
    configured_environment = {
        "EDOC_SCAN_ENGINE": scan_engine_configured,
        "EDOC_AV_PROVIDER": provider_configured,
        "EDOC_AV_ENDPOINT": bool(av["endpointConfigured"]),
        "EDOC_AV_API_KEY": len(os.getenv("EDOC_AV_API_KEY", "").encode("utf-8")) >= 32,
        "EDOC_AV_SANDBOX_SNAPSHOT_ID": bool(av["sandboxSnapshotConfigured"]),
    }
    missing_environment = [
        name for name in av_required_environment_names() if not configured_environment.get(name, env_present(name))
    ]
    configuration_issues: List[str] = []
    if av["transportConfigured"] and not av["contractSupported"]:
        configuration_issues.append("掃毒 transport 必須使用 Vercel Sandbox、clamd INSTREAM，或 edoc-clamav-https-v1 HTTPS HMAC")
    if av["contractSupported"] and not av["credentialConfigured"]:
        configuration_issues.append("掃毒 provider credential 尚未就緒")
    ready = not missing_environment and not configuration_issues
    return {
        "ready": ready,
        "configurationReady": ready,
        "scanEngineConfigured": scan_engine_configured,
        "providerConfigured": provider_configured,
        "endpointConfigured": bool(av["endpointConfigured"]),
        "transportConfigured": bool(av["transportConfigured"]),
        "contractSupported": bool(av["contractSupported"]),
        "contract": av["contract"],
        "credentialConfigured": bool(av["credentialConfigured"]),
        "missingEnvironment": missing_environment,
        "configurationIssues": configuration_issues,
        "runtimeEvidence": "launch-user-journey-required",
    }


def production_readiness() -> Dict[str, Any]:
    required = [
        "EDOC_DEPLOYMENT_ENV",
        "EDOC_PUBLIC_BASE_URL",
        "SUPABASE_URL",
        "SUPABASE_SERVICE_ROLE_KEY",
        "EDOC_PORTAL_HANDOFF_SECRET",
        "CRON_SECRET",
        "LINE_WEBHOOK_URL",
        "LINE_CREDENTIAL_EXPIRES_AT",
        "APP_SECRET",
        "INBOX_SIGNING_KEY_EXPIRES_AT",
        "EDOC_STORAGE_PROVIDER",
        "EDOC_STORAGE_BUCKET",
        "EDOC_SEAL_STORAGE_BUCKET",
        "EDOC_STORAGE_ACCESS_MODE",
        "EDOC_FILE_ENCRYPTION_KEY",
        *av_required_environment_names(),
        "EDOC_MAX_FILE_SIZE_MB",
        "EDOC_ALLOWED_MIME_TYPES",
        "EDOC_SIGNATURE_PROVIDER",
        "EDOC_SIGNATURE_API_URL",
        "EDOC_SIGNATURE_API_KEY",
        "EDOC_SIGNATURE_KEY_ID",
        "EDOC_HSM_PROVIDER",
        "EDOC_CERT_TRUST_STORE",
        "EDOC_TSA_URL",
        "EDOC_TSA_API_KEY",
        "EDOC_OCSP_RESPONDER_URL",
        "EDOC_CRL_DISTRIBUTION_URL",
    ]
    required.extend(notification_email_required_env())
    if EDOC_STORAGE_PROVIDER != "supabase":
        required.append("EDOC_OBJECT_STORAGE_URL")
    elif not storage_uses_database_supabase_project():
        required.append("EDOC_STORAGE_SERVICE_ROLE_KEY")
    missing = [name for name in required if not config_present(name)]
    blockers: List[str] = []
    warnings: List[str] = []
    if is_production() and not USE_SUPABASE:
        blockers.append("production 必須使用 Supabase；Vercel serverless 不可依賴本機 SQLite 持久化。")
    if env_present("SUPABASE_ANON_KEY") and not env_present("SUPABASE_SERVICE_ROLE_KEY"):
        warnings.append("只設定 SUPABASE_ANON_KEY 不足以執行 server-side migration / REST 管理操作。")
    if notification_email_provider() == "SMTP" and env_present("SMTP_HOST") and not env_present("SMTP_USERNAME"):
        warnings.append("SMTP_HOST 已設定但 SMTP_USERNAME 未設定，若郵件服務要求驗證將派送失敗。")
    storage_service = storage_service_status()
    if storage_service["productionBlocked"]:
        blockers.append(f"production 必須接正式物件儲存與防毒服務；缺少：{', '.join(storage_service['missing'])}。")
    elif not storage_service["ready"]:
        warnings.append(f"正式檔案儲存與防毒服務尚未完整：{', '.join(storage_service['missing'])}。")
    if not env_present("MONITORING_WEBHOOK_URL"):
        warnings.append("未設定 MONITORING_WEBHOOK_URL，監控告警將只留在系統內，不會推送到外部值班通道。")
    if not env_present("SENTRY_DSN"):
        warnings.append("未設定 SENTRY_DSN，正式錯誤追蹤需依賴 Vercel runtime logs 與系統 audit log。")
    if is_production() and EDOC_SIGNATURE_PROVIDER == "local-simulation":
        blockers.append("production 必須接正式電子簽章服務；不可使用 local-simulation 簽章。")
    if is_production() and not env_present("EDOC_TSA_URL"):
        blockers.append("production 必須設定 TSA 時間戳服務 URL。")
    if is_production() and not env_present("EDOC_OCSP_RESPONDER_URL"):
        blockers.append("production 必須設定 OCSP 即時撤銷查詢服務。")
    if is_production() and not env_present("EDOC_CRL_DISTRIBUTION_URL"):
        blockers.append("production 必須設定 CRL 撤銷清單來源。")
    ready = not missing and not blockers
    return {
        "environment": DEPLOYMENT_ENV,
        "vercel": RUNNING_ON_VERCEL,
        "databaseMode": "supabase" if USE_SUPABASE else "sqlite",
        "ready": ready,
        "missing": missing,
        "blockers": blockers,
        "warnings": warnings,
        "checks": {
            "supabase": bool(SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY),
            "cronSecret": env_present("CRON_SECRET"),
            "smtp": notification_email_configured(),
            "email": notification_email_configured(),
            "emailProvider": notification_email_provider(),
            "resend": resend_email_configured(),
            "line": env_present("LINE_WEBHOOK_URL"),
            "storage": storage_service,
            "encryption": EDOC_FILE_ENCRYPTION_ENABLED and env_present("EDOC_FILE_ENCRYPTION_KEY"),
            "scanner": EDOC_SCAN_ENGINE,
            "publicBaseUrl": EDOC_PUBLIC_BASE_URL,
            "monitoringWebhook": env_present("MONITORING_WEBHOOK_URL"),
            "sentry": env_present("SENTRY_DSN"),
            "signatureProvider": EDOC_SIGNATURE_PROVIDER,
            "signatureApi": bool(EDOC_SIGNATURE_API_URL and EDOC_SIGNATURE_API_KEY),
            "signatureProfile": EDOC_SIGNATURE_PROFILE,
            "signatureTimeoutSeconds": EDOC_SIGNATURE_TIMEOUT_SECONDS,
            "signatureMaxRetries": EDOC_SIGNATURE_MAX_RETRIES,
            "hsmProvider": EDOC_HSM_PROVIDER or "未設定",
            "trustStore": bool(EDOC_CERT_TRUST_STORE),
            "tsa": bool(EDOC_TSA_URL),
            "ocsp": bool(EDOC_OCSP_RESPONDER_URL),
            "crl": bool(EDOC_CRL_DISTRIBUTION_URL),
        },
    }


def public_health_payload(*, database: str = "", project: str = "") -> Dict[str, Any]:
    """Return a liveness response that never inventories production internals."""
    timestamp = now()
    if is_production():
        return {"ok": True, "status": "ok", "time": timestamp}
    payload: Dict[str, Any] = {
        "ok": True,
        "status": "ok",
        "database": database,
        "time": timestamp,
        "tables": list(TABLES),
        "production": production_readiness(),
    }
    if project:
        payload["project"] = project
    return payload


def public_readiness_payload(readiness: Dict[str, Any]) -> Dict[str, Any]:
    """Expose only an availability bit publicly; details require internal-readiness."""
    if not is_production():
        return readiness
    ready = bool(readiness.get("ready"))
    return {
        "ok": ready,
        "ready": ready,
        "status": "ready" if ready else "not_ready",
        "time": now(),
    }


def launch_scope() -> str:
    value = os.getenv("EDOC_LAUNCH_SCOPE", EDOC_LAUNCH_SCOPE).strip().lower()
    return value or "internal_official"


def launch_company_scope_mode() -> str:
    value = os.getenv("EDOC_LAUNCH_COMPANY_MODE", EDOC_LAUNCH_COMPANY_MODE).strip().lower()
    return value if value in {"finance_active", "manual_allowlist"} else "invalid"


def launch_company_scope_ids() -> List[str]:
    if launch_company_scope_mode() != "manual_allowlist":
        return []
    raw = os.getenv("EDOC_LAUNCH_COMPANY_IDS", EDOC_LAUNCH_COMPANY_IDS).strip()
    if not raw:
        return []
    normalized = raw.replace(";", ",").replace("\n", ",")
    seen: set[str] = set()
    ids: List[str] = []
    for item in normalized.split(","):
        company_id = item.strip()
        if company_id and company_id not in seen:
            ids.append(company_id)
            seen.add(company_id)
    return ids


def pdf_editor_v2_company_scope_mode() -> str:
    value = os.getenv(
        "EDOC_PDF_EDITOR_V2_COMPANY_MODE",
        EDOC_PDF_EDITOR_V2_COMPANY_MODE,
    ).strip().lower()
    return value if value in {"finance_active", "manual_allowlist"} else "invalid"


def pdf_editor_v2_company_scope_ids() -> List[str]:
    """Return the emergency manual rollout scope for mutable Editor V2 APIs.

    In ``finance_active`` mode entitlement follows active Finance companies and
    this function intentionally returns no static ids. ``manual_allowlist`` is
    retained as a fail-closed emergency or staged-rollout override.
    """
    mode = pdf_editor_v2_company_scope_mode()
    if mode == "finance_active":
        return []
    if mode == "invalid":
        return []
    raw = os.getenv("EDOC_PDF_EDITOR_V2_COMPANY_IDS", EDOC_PDF_EDITOR_V2_COMPANY_IDS).strip()
    if not raw:
        if is_production():
            return []
        inherited = launch_company_scope_ids()
        return inherited or ["CO-001"]
    normalized = raw.replace(";", ",").replace("\n", ",")
    seen: set[str] = set()
    company_ids: List[str] = []
    for item in normalized.split(","):
        company_id = item.strip()
        if company_id and company_id not in seen:
            company_ids.append(company_id)
            seen.add(company_id)
    return company_ids


def pdf_editor_v2_enabled_for_company(company_id: str) -> bool:
    mode = pdf_editor_v2_company_scope_mode()
    if mode == "finance_active":
        return bool(company_id)
    if mode != "manual_allowlist":
        return False
    return bool(company_id and company_id in set(pdf_editor_v2_company_scope_ids()))


def launch_company_scope_metadata(companies: List[Dict[str, Any]]) -> Dict[str, Any]:
    mode = launch_company_scope_mode()
    selected_ids = launch_company_scope_ids()
    active_ids = [str(company.get("id") or company.get("company_id") or "") for company in companies]
    active_ids = [company_id for company_id in active_ids if company_id]
    active_id_set = set(active_ids)
    configured = mode == "manual_allowlist" and bool(selected_ids)
    included_ids = [company_id for company_id in (selected_ids if configured else active_ids) if company_id in active_id_set]
    included_set = set(included_ids)
    excluded = [
        {
            "company_id": str(company.get("id") or company.get("company_id") or ""),
            "company_name": company.get("name") or company.get("company_name") or company.get("id") or company.get("company_id") or "",
        }
        for company in companies
        if str(company.get("id") or company.get("company_id") or "") not in included_set
    ]
    included = [
        {
            "company_id": str(company.get("id") or company.get("company_id") or ""),
            "company_name": company.get("name") or company.get("company_name") or company.get("id") or company.get("company_id") or "",
        }
        for company in companies
        if str(company.get("id") or company.get("company_id") or "") in included_set
    ]
    return {
        "configured": configured,
        "mode": "limited_companies" if configured else "finance_active_companies" if mode == "finance_active" else "invalid",
        "sourceOfTruth": "finance" if mode == "finance_active" else "manual_allowlist",
        "modeEnvVar": "EDOC_LAUNCH_COMPANY_MODE",
        "envVar": "EDOC_LAUNCH_COMPANY_IDS",
        "includedCompanyIds": included_ids,
        "includedCompanies": included,
        "excludedCompanyIds": [item["company_id"] for item in excluded],
        "excludedCompanies": excluded,
        "unknownCompanyIds": [company_id for company_id in selected_ids if company_id not in active_id_set],
        "selectionLocked": configured,
        "frontendShouldDisableExcluded": configured,
    }


def filter_launch_companies(companies: List[Dict[str, Any]]) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    scope = launch_company_scope_metadata(companies)
    if not scope["configured"]:
        return companies, scope
    included = set(scope["includedCompanyIds"])
    return [
        company
        for company in companies
        if str(company.get("id") or company.get("company_id") or "") in included
    ], scope


def launch_company_scope_blockers(all_companies: List[Dict[str, Any]], scope: Dict[str, Any]) -> List[str]:
    blockers: List[str] = []
    if not all_companies:
        blockers.append("尚未建立啟用公司，無法建立發文申請單。")
        return blockers
    if launch_company_scope_mode() == "invalid":
        blockers.append("EDOC_LAUNCH_COMPANY_MODE 必須是 finance_active 或 manual_allowlist。")
    if scope.get("unknownCompanyIds"):
        blockers.append(f"EDOC_LAUNCH_COMPANY_IDS 指定了不存在或未啟用的公司：{'、'.join(scope['unknownCompanyIds'])}。")
    if scope.get("configured") and not scope.get("includedCompanyIds"):
        blockers.append("EDOC_LAUNCH_COMPANY_IDS 已設定，但沒有任何指定公司目前為啟用狀態。")
    return blockers


def launch_company_in_scope(company_id: str) -> bool:
    mode = launch_company_scope_mode()
    if mode == "finance_active":
        return bool(company_id)
    if mode != "manual_allowlist":
        return False
    selected_ids = launch_company_scope_ids()
    return bool(selected_ids) and company_id in set(selected_ids)


def internal_readiness() -> Dict[str, Any]:
    demo_policy = demo_account_policy_status()
    required = [
        "EDOC_DEPLOYMENT_ENV",
        "EDOC_PUBLIC_BASE_URL",
        "EDOC_DB_MODE",
        "SUPABASE_URL",
        "SUPABASE_SERVICE_ROLE_KEY",
        "EDOC_PORTAL_HANDOFF_SECRET",
        "EDOC_STORAGE_PROVIDER",
        "EDOC_STORAGE_BUCKET",
        "EDOC_SEAL_STORAGE_BUCKET",
        "EDOC_STORAGE_ACCESS_MODE",
        "EDOC_FILE_ENCRYPTION_KEY",
    ]
    if is_production():
        required.extend([
            *av_required_environment_names(),
            "EDOC_LAUNCH_COMPANY_MODE",
            "EDOC_PDF_EDITOR_V2_COMPANY_MODE",
            "EDOC_FINANCE_BRIDGE_URL",
            "EDOC_FINANCE_BRIDGE_SECRET",
            "EDOC_FINANCE_BRIDGE_TIMEOUT_SECONDS",
        ])
    if EDOC_STORAGE_PROVIDER != "supabase":
        required.append("EDOC_OBJECT_STORAGE_URL")
    elif not storage_uses_database_supabase_project():
        required.append("EDOC_STORAGE_SERVICE_ROLE_KEY")
    missing = [name for name in required if not config_present(name)]
    blockers: List[str] = []
    warnings: List[str] = []
    antivirus = internal_antivirus_readiness()
    launch_company_mode = launch_company_scope_mode()
    editor_company_mode = pdf_editor_v2_company_scope_mode()
    launch_company_ids = launch_company_scope_ids()
    editor_company_ids = pdf_editor_v2_company_scope_ids()
    finance_bridge_url = urllib.parse.urlparse(EDOC_FINANCE_BRIDGE_URL)
    finance_bridge_https = bool(
        finance_bridge_url.scheme == "https"
        and finance_bridge_url.netloc
        and not finance_bridge_url.username
        and not finance_bridge_url.password
        and not finance_bridge_url.fragment
    )
    finance_bridge_timeout_ready = 0 < EDOC_FINANCE_BRIDGE_TIMEOUT_SECONDS <= 15
    finance_bridge_secret_ready = len(EDOC_FINANCE_BRIDGE_SECRET.encode("utf-8")) >= 32
    portal_handoff_secret_ready = len(PORTAL_HANDOFF_SECRET.encode("utf-8")) >= PORTAL_HANDOFF_MIN_SECRET_BYTES
    finance_bridge_configured = bool(
        EDOC_FINANCE_BRIDGE_URL
        and finance_bridge_secret_ready
        and finance_bridge_https
        and finance_bridge_timeout_ready
    )
    storage_ready = bool(
        EDOC_STORAGE_PROVIDER in {"supabase", "s3", "r2", "private-object-storage"}
        and EDOC_STORAGE_BUCKET
        and EDOC_SEAL_STORAGE_BUCKET
        and object_storage_endpoint()
        and (EDOC_STORAGE_PROVIDER != "supabase" or storage_service_role_key())
    )
    if is_production() and not USE_SUPABASE:
        blockers.append("內部正式上線必須使用 Supabase；Vercel production 不可依賴本機 SQLite。")
    if is_production() and not storage_ready:
        blockers.append("內部正式上線必須設定 private object storage 與 Seal Vault bucket。")
    if is_production() and not antivirus["ready"]:
        av_reasons = [*antivirus["missingEnvironment"], *antivirus["configurationIssues"]]
        blockers.append(f"內部正式上線必須完成可用的防毒掃描設定；缺少或不支援：{', '.join(av_reasons)}。")
    if launch_company_mode == "invalid":
        blockers.append("EDOC_LAUNCH_COMPANY_MODE 必須是 finance_active 或 manual_allowlist。")
    if launch_company_mode == "manual_allowlist" and not launch_company_ids:
        blockers.append("manual_allowlist 模式必須明確設定 EDOC_LAUNCH_COMPANY_IDS。")
    if editor_company_mode == "invalid":
        blockers.append("EDOC_PDF_EDITOR_V2_COMPANY_MODE 必須是 finance_active 或 manual_allowlist。")
    if editor_company_mode == "manual_allowlist" and not editor_company_ids:
        blockers.append("PDF Editor V2 的 manual_allowlist 模式必須設定 EDOC_PDF_EDITOR_V2_COMPANY_IDS。")
    if is_production() and EDOC_FINANCE_BRIDGE_URL and not finance_bridge_https:
        blockers.append("Finance bridge 正式環境必須使用不含帳密與 fragment 的 HTTPS endpoint。")
    if is_production() and env_present("EDOC_FINANCE_BRIDGE_TIMEOUT_SECONDS") and not finance_bridge_timeout_ready:
        blockers.append("EDOC_FINANCE_BRIDGE_TIMEOUT_SECONDS 必須大於 0 且不超過 15 秒。")
    if is_production() and EDOC_FINANCE_BRIDGE_SECRET and not finance_bridge_secret_ready:
        blockers.append("EDOC_FINANCE_BRIDGE_SECRET 必須是至少 32 bytes 的專用共享密鑰。")
    if is_production() and PORTAL_HANDOFF_SECRET and not portal_handoff_secret_ready:
        blockers.append("EDOC_PORTAL_HANDOFF_SECRET 必須是至少 32 bytes 的專用共享密鑰。")
    if (
        is_production()
        and launch_company_mode == "manual_allowlist"
        and editor_company_mode == "manual_allowlist"
        and launch_company_ids
        and editor_company_ids
    ):
        launch_without_editor = [company_id for company_id in launch_company_ids if company_id not in set(editor_company_ids)]
        editor_outside_launch = [company_id for company_id in editor_company_ids if company_id not in set(launch_company_ids)]
        if launch_without_editor:
            blockers.append(
                "下列上線公司尚未納入 EDOC_PDF_EDITOR_V2_COMPANY_IDS，無法使用必要的 PDF 編輯器："
                f"{'、'.join(launch_without_editor)}。"
            )
        if editor_outside_launch:
            blockers.append(
                "EDOC_PDF_EDITOR_V2_COMPANY_IDS 不得先開放 launch scope 外公司："
                f"{'、'.join(editor_outside_launch)}。"
            )
    if is_production() and not demo_policy["disabled"]:
        blockers.append("內部正式上線必須關閉 demo/quick role login。")
    if is_production() and demo_policy["disabled"] and not demo_policy["explicitDisable"]:
        warnings.append("正式站 demo/quick role login 已由安全預設阻擋；仍建議設定 EDOC_DISABLE_DEMO_ACCOUNTS=true 留存明確政策。")
    if EDOC_EXCHANGE_PROVIDER != "mock":
        warnings.append("內部正式上線範圍只允許 mock/sandbox 電子交換；正式交換需另走人工核准。")
    if not notification_email_configured():
        warnings.append("Resend 尚未完整設定，通知可先留在系統內，但正式營運需補 RESEND_API_KEY 與 MAIL_FROM。")
    if not env_present("LINE_WEBHOOK_URL"):
        warnings.append("LINE_WEBHOOK_URL 未設定，稽催與值班告警不會推送 LINE。")
    ready = not missing and not blockers
    return {
        "environment": DEPLOYMENT_ENV,
        "launchScope": launch_scope(),
        "ready": ready,
        "internalGo": ready and launch_scope() == "internal_official",
        "formalGo": False,
        "databaseMode": "supabase" if USE_SUPABASE else "sqlite",
        "missing": missing,
        "blockers": blockers,
        "warnings": warnings,
        "checks": {
            "supabase": bool(SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY and USE_SUPABASE),
            "financeBridge": {
                "configured": finance_bridge_configured,
                "https": finance_bridge_https,
                "secretLengthValid": finance_bridge_secret_ready,
                "serverToServer": True,
                "schemaVersion": FINANCE_BRIDGE_SCHEMA_VERSION,
                "timeoutSeconds": EDOC_FINANCE_BRIDGE_TIMEOUT_SECONDS,
                "containsEndpoint": False,
                "containsSecret": False,
            },
            "portalHandoff": {
                "configured": portal_handoff_secret_ready,
                "secretLengthValid": portal_handoff_secret_ready,
                "minimumSecretBytes": PORTAL_HANDOFF_MIN_SECRET_BYTES,
                "postOnly": True,
                "oneTimeJti": True,
                "containsSecret": False,
            },
            "privateStorage": storage_ready,
            "objectStorageEndpointDerived": bool(object_storage_endpoint()) and not env_present("EDOC_OBJECT_STORAGE_URL"),
            "documentBucket": EDOC_STORAGE_BUCKET,
            "sealVaultBucket": EDOC_SEAL_STORAGE_BUCKET,
            "encryption": EDOC_FILE_ENCRYPTION_ENABLED and env_present("EDOC_FILE_ENCRYPTION_KEY"),
            "demoAccountsDisabled": demo_policy["disabled"],
            "demoAccountsExplicitlyDisabled": demo_policy["explicitDisable"],
            "demoAccountsSafeDefault": demo_policy["safeDefault"],
            "demoAccountsExplicitlyAllowed": demo_policy["explicitAllow"],
            "exchangeProvider": EDOC_EXCHANGE_PROVIDER,
            "exchangeEnvironment": EDOC_EXCHANGE_ENV,
            "formalExchangeDisabled": launch_scope() == "internal_official" or EDOC_EXCHANGE_PROVIDER in NON_FORMAL_EXCHANGE_PROVIDERS,
            "antivirus": antivirus,
            "launchCompanyScope": {
                "configured": launch_company_mode in {"finance_active", "manual_allowlist"},
                "mode": launch_company_mode,
                "sourceOfTruth": "finance" if launch_company_mode == "finance_active" else "manual_allowlist",
                "modeEnvVar": "EDOC_LAUNCH_COMPANY_MODE",
                "envVar": "EDOC_LAUNCH_COMPANY_IDS",
                "companyIds": launch_company_ids,
                "companyCount": len(launch_company_ids),
            },
            "pdfEditorV2CompanyScope": {
                "configured": editor_company_mode in {"finance_active", "manual_allowlist"},
                "mode": editor_company_mode,
                "sourceOfTruth": "finance" if editor_company_mode == "finance_active" else "manual_allowlist",
                "modeEnvVar": "EDOC_PDF_EDITOR_V2_COMPANY_MODE",
                "envVar": "EDOC_PDF_EDITOR_V2_COMPANY_IDS",
                "companyIds": editor_company_ids,
                "companyCount": len(editor_company_ids),
                "coversLaunchScope": editor_company_mode == "finance_active"
                or (
                    launch_company_mode == "manual_allowlist"
                    and bool(launch_company_ids)
                    and set(launch_company_ids).issubset(set(editor_company_ids))
                ),
                "outsideLaunchCompanyIds": [
                    company_id for company_id in editor_company_ids if company_id not in set(launch_company_ids)
                ],
            },
            "smtp": notification_email_configured(),
            "email": notification_email_configured(),
            "emailProvider": notification_email_provider(),
            "resend": resend_email_configured(),
            "line": env_present("LINE_WEBHOOK_URL"),
        },
        "scopeNote": "內部正式使用可開放；政府 jAgent 正式交換與法定電子簽章仍未啟用。",
    }


def readiness_for_public_endpoint(parts: List[str]) -> Dict[str, Any]:
    """Select the readiness boundary without weakening formal go-live gates.

    ``/readyz`` is the runtime probe for the currently approved internal eDoc
    module, so it must not fail solely because the separately governed formal
    exchange/signature providers are intentionally disabled.  The explicit
    ``/production/readiness`` endpoint keeps the stricter formal prerequisites
    and therefore remains fail-closed until those providers are approved.
    """
    if parts == ["readyz"]:
        return internal_readiness()
    return production_readiness()


def public_readiness_response(parts: List[str]) -> Tuple[Dict[str, Any], int]:
    readiness = readiness_for_public_endpoint(parts)
    status = 200 if readiness["ready"] or not is_production() else 503
    return public_readiness_payload(readiness), status


def compact_evidence(items: List[str], limit: int = 3) -> str:
    if not items:
        return "無"
    shown = items[:limit]
    suffix = f"；另 {len(items) - limit} 項" if len(items) > limit else ""
    return "；".join(shown) + suffix


def launch_item(
    key: str,
    title: str,
    owner: str,
    blockers: List[str],
    warnings: List[str],
    action: str,
    impact: str,
) -> Dict[str, Any]:
    severity = "blocker" if blockers else "warning" if warnings else "pass"
    status = "需先處理" if blockers else "需走測/補強" if warnings else "可使用"
    return {
        "key": key,
        "title": title,
        "owner": owner,
        "severity": severity,
        "status": status,
        "impact": impact,
        "action": action,
        "blockers": blockers,
        "warnings": warnings,
        "evidence": compact_evidence(blockers or warnings),
    }


def launch_journey_item(
    key: str,
    title: str,
    actor: str,
    ready: bool,
    missing: List[str],
    evidence: List[str],
    next_action: str,
    impact: str,
    target: str,
    acceptance: List[str] | None = None,
) -> Dict[str, Any]:
    return {
        "key": key,
        "title": title,
        "actor": actor,
        "ready": ready,
        "severity": "pass" if ready else "warning",
        "status": "已完成走測" if ready else "待走測",
        "impact": impact,
        "nextAction": next_action,
        "target": target,
        "missing": missing,
        "evidence": evidence,
        "acceptanceCriteria": acceptance or [],
        "missingText": compact_evidence(missing),
        "evidenceText": compact_evidence(evidence),
        "acceptanceText": compact_evidence(acceptance or []),
    }


def launch_next_fix_priority(key: str, severity: str) -> Tuple[int, str]:
    severity_rank = {"blocker": 0, "warning": 1, "pass": 2}.get(severity, 1)
    key_rank = {
        "ops": "00",
        "login_access": "01",
        "seal_admin": "02",
        "applicant": "03",
        "approvers": "04",
        "general_affairs": "05",
        "notifications": "06",
        "user_journeys": "07",
        "formal_exchange_scope": "08",
    }.get(key, "99")
    return severity_rank, key_rank


def launch_fix_route(key: str, source: str = "") -> Dict[str, str]:
    routes = {
        "ops": ("ops", "goLive", "維運中心"),
        "login_access": ("accounts", "", "帳號權限"),
        "seal_admin": ("seals", "", "印鑑管理"),
        "applicant": ("dispatch", "newOfficial", "新增發文"),
        "approvers": ("dispatch", "dispatchTasks", "簽核待辦"),
        "general_affairs": ("dispatch", "dispatchTasks", "總務寄發"),
        "notifications": ("notifications", "", "通知中心"),
        "user_journeys": ("ops", "goLive", "上線檢核"),
        "formal_exchange_scope": ("ops", "goLive", "交換範圍"),
        "blank_official_document": ("dispatch", "newOfficial", "新增空白公文"),
        "uploaded_pdf_stamping": ("dispatch", "newOfficialPdf", "上傳 PDF 用印"),
        "general_affairs_dispatch": ("dispatch", "dispatchTasks", "總務寄發"),
        "inbound_assignment": ("inbound", "inboundRegister", "收文登錄"),
        "internal_dispatch_reply": ("dispatch", "internalDispatch", "內部派文"),
    }
    target, action, label = routes.get(key, ("dashboard", "", "工作台"))
    return {"target": target, "launchAction": action, "targetLabel": label}


