def launch_smoke_owner_actions(fixes: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    grouped: Dict[str, Dict[str, Any]] = {}
    for fix in fixes:
        owner = fix.get("owner") or "未指定"
        group = grouped.setdefault(owner, {
            "owner": owner,
            "blockerCount": 0,
            "warningCount": 0,
            "items": [],
        })
        if fix.get("severity") == "blocker":
            group["blockerCount"] += 1
        else:
            group["warningCount"] += 1
        group["items"].append({
            "key": fix.get("key"),
            "title": fix.get("title"),
            "severity": fix.get("severity"),
            "action": fix.get("action"),
            "doneWhen": fix.get("doneWhen"),
            "target": fix.get("target"),
            "targetLabel": fix.get("targetLabel"),
        })
    return sorted(
        grouped.values(),
        key=lambda item: (0 if item["blockerCount"] else 1, -(item["blockerCount"] + item["warningCount"]), str(item["owner"])),
    )


def launch_smoke_next_fixes(checklist: List[Dict[str, Any]], journeys: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    fixes: List[Dict[str, Any]] = []
    for item in checklist:
        severity = item.get("severity") or "warning"
        if severity == "pass":
            continue
        route = launch_fix_route(str(item.get("key") or ""), "role_checklist")
        acceptance = launch_fix_acceptance(str(item.get("key") or ""))
        fixes.append({
            "key": item.get("key"),
            "title": item.get("title"),
            "owner": item.get("owner") or "未指定",
            "severity": severity,
            "status": item.get("status") or "",
            "evidence": item.get("evidence") or compact_evidence((item.get("blockers") or []) + (item.get("warnings") or [])),
            "action": item.get("action") or "請檢查並補正。",
            "impact": item.get("impact") or "",
            "doneWhen": launch_fix_done_when(str(item.get("key") or ""), item.get("action") or ""),
            "acceptanceCriteria": acceptance,
            **route,
            "source": "role_checklist",
        })
    for item in journeys:
        if item.get("ready"):
            continue
        route = launch_fix_route(str(item.get("key") or ""), "user_journey")
        fixes.append({
            "key": item.get("key"),
            "title": item.get("title"),
            "owner": item.get("actor") or "未指定",
            "severity": "warning",
            "status": item.get("status") or "待走測",
            "evidence": item.get("missingText") or compact_evidence(item.get("missing") or []),
            "action": item.get("nextAction") or "請完成此使用者旅程走測。",
            "impact": item.get("impact") or "",
            "doneWhen": item.get("acceptanceText") or "走測報告顯示此旅程 ready=true。",
            "acceptanceCriteria": item.get("acceptanceCriteria") or [],
            **route,
            "source": "user_journey",
        })
    fixes.sort(key=lambda item: (*launch_next_fix_priority(str(item.get("key") or ""), str(item.get("severity") or "warning")), str(item.get("title") or "")))
    return fixes[:12]


