def launch_smoke_preflight(key: str, journey: Dict[str, Any], data_checks: Dict[str, Any]) -> Dict[str, Any]:
    missing = list(journey.get("missing") or [])
    role_counts = data_checks.get("roleCounts") or {}
    workflow_steps = data_checks.get("workflowSteps") or []
    company_seals = data_checks.get("companySeals") or []
    applicant_ready = bool(data_checks.get("applicantReady", False))
    current_seal_count = sum(
        1
        for company in company_seals
        for seal in company.get("requiredSeals") or []
        if seal.get("active") and seal.get("currentFile")
    )
    workflow_ready = bool(workflow_steps) and all(step.get("ready") for step in workflow_steps)
    active_assignee_count = sum(int(role_counts.get(role, 0) or 0) for role in ("業務助理", "員工", "主管"))
    blockers: List[str] = []
    warnings: List[str] = []
    target = ""
    action = ""
    label = ""
    if journey.get("ready"):
        return {
            "canProceed": True,
            "statusLabel": "已完成走測",
            "blockers": [],
            "warnings": [],
            "recommendedTarget": "",
            "recommendedAction": "",
            "recommendedLabel": "",
        }
    if key == "blank_official_document":
        if not applicant_ready:
            blockers.append("缺少可建立發文申請單的啟用申請人帳號。")
            target, action, label = "accounts", "", "先補正式帳號"
        if not workflow_ready:
            blockers.append("簽核關卡處理人尚未完整，送出後可能無法流到下一關。")
            target, action, label = target or "accounts", action or "", label or "先補簽核角色"
        if not blockers:
            target, action, label = "dispatch", "newOfficial", "開始空白公文"
    elif key == "uploaded_pdf_stamping":
        if current_seal_count < 1:
            blockers.append("沒有任何可用的 Seal Vault current 印章版本，無法產生已用印 PDF。")
            target, action, label = "seals", "", "先補 Seal Vault"
        elif not applicant_ready:
            blockers.append("缺少可建立 PDF 用印申請的正式申請人帳號。")
            target, action, label = "accounts", "", "先補正式帳號"
        elif not workflow_ready:
            warnings.append("簽核關卡尚未完整；可建立走測單，但送簽後可能卡關。")
            target, action, label = "dispatch", "createUploadedPdfSmoke", "建立 PDF 走測"
        else:
            target, action, label = "dispatch", "createUploadedPdfSmoke", "建立 PDF 走測"
    elif key == "general_affairs_dispatch":
        if current_seal_count < 1:
            blockers.append("PDF 用印走測需要先補 Seal Vault current 印章版本。")
            target, action, label = "seals", "", "先補 Seal Vault"
        elif "尚未建立總務寄發紀錄" in missing:
            blockers.append("尚無已用印且等待總務寄發的去識別化走測單。")
            target, action, label = "dispatch", "createUploadedPdfSmoke", "先建立 PDF 走測"
        elif role_counts.get("總務", 0) < 1:
            blockers.append("缺少可完成總務寄發的啟用總務帳號。")
            target, action, label = "accounts", "", "先補總務帳號"
        else:
            target, action, label = "dispatch", "completeDispatchSmoke", "完成寄發走測"
    elif key == "inbound_assignment":
        if role_counts.get("總務", 0) < 1:
            blockers.append("缺少可登錄收文的啟用總務帳號。")
            target, action, label = "accounts", "", "先補總務帳號"
        elif active_assignee_count < 1:
            blockers.append("缺少可被指派的啟用承辦人帳號。")
            target, action, label = "accounts", "", "先補承辦帳號"
        else:
            target, action, label = "inbound", "createInboundSmoke", "建立收文走測"
    elif key == "internal_dispatch_reply":
        if active_assignee_count < 1:
            blockers.append("缺少可收件與回覆的啟用內部同仁帳號。")
            target, action, label = "accounts", "", "先補內部帳號"
        else:
            target, action, label = "dispatch", "internalDispatch", "建立內部派文"
    else:
        target, action, label = "dashboard", "", "查看工作台"
    status_label = "可執行走測" if not blockers else "需先處理"
    if blockers and "Seal Vault" in blockers[0]:
        status_label = "需先補印章"
    elif blockers and "帳號" in blockers[0]:
        status_label = "需先補帳號"
    elif blockers and "走測單" in blockers[0]:
        status_label = "需先建立前置單"
    return {
        "canProceed": not blockers,
        "statusLabel": status_label,
        "blockers": blockers,
        "warnings": warnings,
        "recommendedTarget": target,
        "recommendedAction": action,
        "recommendedLabel": label,
    }


def launch_smoke_execution_plan(
    journeys: List[Dict[str, Any]],
    fixes: List[Dict[str, Any]],
    readiness: Dict[str, Any] | None = None,
) -> List[Dict[str, Any]]:
    fix_by_key = {str(item.get("key") or ""): item for item in fixes}
    data_checks = ((readiness or {}).get("dataReadiness") or {}).get("checks") or {}
    plan: List[Dict[str, Any]] = []
    for index, journey in enumerate(journeys, start=1):
        key = str(journey.get("key") or "")
        guide = LAUNCH_SMOKE_EXECUTION_GUIDE.get(key, {})
        fix = fix_by_key.get(key, {})
        missing = list(journey.get("missing") or [])
        preflight = launch_smoke_preflight(key, journey, data_checks)
        blocked_by = preflight.get("blockers") or missing
        if not blocked_by and fix.get("evidence") and not journey.get("ready"):
            blocked_by = [fix.get("evidence")]
        plan.append({
            "order": index,
            "key": key,
            "title": journey.get("title") or guide.get("actionLabel") or key,
            "ready": bool(journey.get("ready")),
            "status": journey.get("status") or ("已完成走測" if journey.get("ready") else "待走測"),
            "operatorRole": guide.get("operatorRole") or journey.get("actor") or "未指定",
            "entryPoint": guide.get("entryPoint") or "",
            "target": preflight.get("recommendedTarget") or guide.get("target") or fix.get("target") or "dashboard",
            "targetLabel": preflight.get("recommendedLabel") or guide.get("targetLabel") or fix.get("targetLabel") or "前往處理",
            "launchAction": preflight.get("recommendedAction") or guide.get("launchAction") or fix.get("launchAction") or "",
            "actionLabel": guide.get("actionLabel") or fix.get("action") or journey.get("nextAction") or "完成走測",
            "apiEndpoint": guide.get("apiEndpoint") or "",
            "prerequisites": guide.get("prerequisites") or [],
            "steps": guide.get("steps") or [journey.get("nextAction") or "依畫面指示完成此使用者旅程。"],
            "doneWhen": guide.get("doneWhen") or journey.get("acceptanceText") or fix.get("doneWhen") or "走測報告顯示 ready=true。",
            "blockedBy": blocked_by,
            "evidence": journey.get("evidence") or [],
            "preflight": preflight,
            "safetyNote": "僅使用去識別化走測資料；正式 jAgent 交換維持關閉，原始印章檔只允許後端 Seal Vault 讀取。",
        })
    if not plan:
        plan.append({
            "order": 1,
            "key": "go_live_check",
            "title": "重新執行 Go / No-Go",
            "ready": False,
            "status": "待檢查",
            "operatorRole": "IT、系統管理員",
            "entryPoint": "維運中心 → Go / No-Go",
            "target": "ops",
            "targetLabel": "重新檢查",
            "launchAction": "goLive",
            "actionLabel": "讀取正式上線狀態",
            "apiEndpoint": "GET /api/production/go-live-audit",
            "prerequisites": ["正式環境變數已補齊", "Supabase migrations 已套用", "private buckets 已建立"],
            "steps": ["按重新檢查並確認 internalGo 是否為 true。"],
            "doneWhen": "Go / No-Go 顯示 INTERNAL_GO；formalGo 仍為 false。",
            "blockedBy": [],
            "evidence": [],
            "safetyNote": "下週一範圍是內部正式使用，不啟用政府正式交換。",
        })
    return plan


def launch_smoke_duty_owner_for_plan(item: Dict[str, Any]) -> str:
    target = item.get("target") or ""
    action = item.get("launchAction") or ""
    if target == "seals":
        return "總務 / seal_admin"
    if target == "accounts":
        return "IT / 行政部主任"
    if target == "ops":
        return "IT / 系統管理員"
    if target == "inbound":
        return "總務 / 收文承辦"
    if action == "completeDispatchSmoke":
        return "總務"
    if action in {"createUploadedPdfSmoke", "newOfficial", "newOfficialPdf"}:
        return "申請人 / 業務助理"
    return item.get("operatorRole") or "未指定"


def launch_smoke_duty_board(fixes: List[Dict[str, Any]], execution_plan: List[Dict[str, Any]]) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = []
    seen: set[str] = set()
    for item in execution_plan:
        if item.get("ready"):
            continue
        preflight = item.get("preflight") or {}
        key = f"journey:{item.get('key')}"
        seen.add(key)
        blockers = list(preflight.get("blockers") or item.get("blockedBy") or [])
        can_proceed = bool(preflight.get("canProceed", False))
        rows.append({
            "order": len(rows) + 1,
            "key": key,
            "journeyKey": item.get("key"),
            "title": item.get("title"),
            "owner": launch_smoke_duty_owner_for_plan(item),
            "priority": "P0" if blockers and not can_proceed else "P1",
            "status": preflight.get("statusLabel") or item.get("status") or "待走測",
            "action": preflight.get("recommendedLabel") or item.get("targetLabel") or item.get("actionLabel"),
            "target": item.get("target"),
            "launchAction": item.get("launchAction"),
            "targetLabel": item.get("targetLabel"),
            "doneWhen": item.get("doneWhen"),
            "blockedBy": blockers[:3],
            "evidence": list(item.get("evidence") or [])[:3],
            "source": "execution_plan",
        })
    for fix in fixes:
        key = f"fix:{fix.get('key')}"
        if key in seen:
            continue
        rows.append({
            "order": len(rows) + 1,
            "key": key,
            "journeyKey": fix.get("key"),
            "title": fix.get("title"),
            "owner": fix.get("owner") or "未指定",
            "priority": "P0" if fix.get("severity") == "blocker" else "P1",
            "status": fix.get("status") or "待處理",
            "action": fix.get("action"),
            "target": fix.get("target"),
            "launchAction": fix.get("launchAction"),
            "targetLabel": fix.get("targetLabel"),
            "doneWhen": fix.get("doneWhen"),
            "blockedBy": [fix.get("evidence")] if fix.get("evidence") else [],
            "evidence": [fix.get("impact")] if fix.get("impact") else [],
            "source": fix.get("source") or "next_fix",
        })
    rows.sort(key=lambda row: (0 if row.get("priority") == "P0" else 1, int(row.get("order") or 0), str(row.get("title") or "")))
    owner_summary: Dict[str, Dict[str, Any]] = {}
    for row in rows:
        owner = row.get("owner") or "未指定"
        summary = owner_summary.setdefault(owner, {"owner": owner, "p0": 0, "p1": 0, "total": 0})
        summary["total"] += 1
        if row.get("priority") == "P0":
            summary["p0"] += 1
        else:
            summary["p1"] += 1
    summary_rows = sorted(owner_summary.values(), key=lambda item: (-(item["p0"]), -(item["total"]), item["owner"]))
    return {
        "summary": {
            "total": len(rows),
            "p0": sum(1 for row in rows if row.get("priority") == "P0"),
            "p1": sum(1 for row in rows if row.get("priority") == "P1"),
            "owners": len(summary_rows),
        },
        "ownerSummary": summary_rows,
        "items": rows[:16],
        "handoffNote": "值班人員請先清 P0，再跑可執行的 P1 走測；所有 smoke 資料需去識別化，且正式 jAgent 維持關閉。",
    }


def launch_user_perspective_gaps(readiness: Dict[str, Any]) -> Dict[str, Any]:
    checklist = {item.get("key"): item for item in readiness.get("userLaunchChecklist") or []}
    journeys = {item.get("key"): item for item in readiness.get("userJourneyChecklist") or []}

    def build_item(
        key: str,
        actor: str,
        user_question: str,
        entry_point: str,
        check_keys: List[str],
        journey_keys: List[str],
        next_action: str,
        done_when: str,
        target: str,
        launch_action: str = "",
        target_label: str = "前往處理",
    ) -> Dict[str, Any]:
        blocker_evidence: List[str] = []
        warning_evidence: List[str] = []
        acceptance: List[str] = []
        related_keys: List[str] = []

        for check_key in check_keys:
            item = checklist.get(check_key) or {}
            if not item:
                continue
            related_keys.append(check_key)
            evidence = item.get("evidence") or item.get("impact") or item.get("action") or ""
            if item.get("severity") == "blocker":
                blocker_evidence.append(evidence)
            elif item.get("severity") == "warning":
                warning_evidence.append(evidence)
            acceptance.extend(launch_fix_acceptance(check_key))

        for journey_key in journey_keys:
            journey = journeys.get(journey_key) or {}
            if not journey:
                continue
            related_keys.append(journey_key)
            if not journey.get("ready"):
                warning_evidence.append(journey.get("missingText") or compact_evidence(journey.get("missing") or []))
            acceptance.extend(journey.get("acceptanceCriteria") or [])

        severity = "blocker" if blocker_evidence else "warning" if warning_evidence else "pass"
        route = launch_fix_route(key)
        return {
            "key": key,
            "actor": actor,
            "userQuestion": user_question,
            "entryPoint": entry_point,
            "severity": severity,
            "status": "會卡住" if severity == "blocker" else "需走測" if severity == "warning" else "可使用",
            "blockingEvidence": [item for item in blocker_evidence if item],
            "warnings": [item for item in warning_evidence if item],
            "nextAction": next_action,
            "doneWhen": done_when,
            "acceptanceCriteria": acceptance[:6],
            "relatedKeys": related_keys,
            "target": target or route.get("target") or "dashboard",
            "launchAction": launch_action or route.get("launchAction") or "",
            "targetLabel": target_label or route.get("targetLabel") or "前往處理",
        }

    items = [
        build_item(
            "applicant_monday_start",
            "申請人 / 一般同仁",
            "我週一能不能登入、建立發文申請、送出簽核？",
            "發文管理 → 新增發文",
            ["login_access", "applicant", "seal_admin"],
            ["blank_official_document", "uploaded_pdf_stamping"],
            "先確認正式帳號可登入，再建立空白公文與上傳 PDF 用印各一筆去識別化走測。",
            "申請人可送出申請，案件進入主管待辦，且附件區保留原始 PDF / 系統 PDF。",
            "dispatch",
            "newOfficial",
            "新增發文",
        ),
        build_item(
            "approver_monday_queue",
            "申請人主管 / 行政部門主任",
            "我週一打開待辦時，是否只會看到輪到我的關卡？",
            "發文管理 → 我的待簽核",
            ["approvers"],
            ["blank_official_document", "uploaded_pdf_stamping"],
            "用主管與行政部主任正式帳號各核准一關，並測試不可跳關或代簽。",
            "前一關未核准時下一關不能操作；每一關 audit log 有 actor 與時間。",
            "dispatch",
            "dispatchTasks",
            "簽核待辦",
        ),
        build_item(
            "general_affairs_monday_dispatch",
            "總務",
            "我週一能不能審核用印、下載已用印 PDF、回填寄發證明？",
            "發文管理 → 待寄發 / 寄發資訊",
            ["general_affairs", "seal_admin", "notifications"],
            ["general_affairs_dispatch"],
            "補齊 Seal Vault current 版本後，用總務帳號完成寄發走測並上傳去識別化證明。",
            "總務可下載已用印 PDF，不可下載原始印章；寄發完成後申請人看得到證明附件。",
            "dispatch",
            "dispatchTasks",
            "總務寄發",
        ),
        build_item(
            "inbound_owner_monday_register",
            "總務 / 收文承辦",
            "我週一能不能登錄來文、分派承辦人、設定期限？",
            "收文管理 → 登錄收文",
            ["user_journeys"],
            ["inbound_assignment"],
            "建立一筆去識別化收文，分派承辦人並設定三日內辦理期限。",
            "收文已登錄、附件已保存、承辦人與期限可查詢。",
            "inbound",
            "createInboundSmoke",
            "建立收文走測",
        ),
        build_item(
            "internal_recipient_monday_reply",
            "內部收件同仁",
            "我週一收到內部派文時，能不能在期限內回覆文字與附件？",
            "內部派文 → 收件人回覆",
            ["user_journeys", "notifications"],
            ["internal_dispatch_reply"],
            "建立需限期回文的內部派文，請一位同仁完成回覆文字與附件。",
            "回文文字、附件、期限與狀態留在同一筆派文紀錄。",
            "dispatch",
            "internalDispatch",
            "建立派文",
        ),
        build_item(
            "it_ops_monday_open_gate",
            "IT / 系統管理員",
            "週一正式網址打開後，資料、檔案、印章與 demo 政策是否安全？",
            "維運中心 → Go / No-Go",
            ["ops", "login_access", "formal_exchange_scope"],
            [],
            "切到 Supabase production / private storage，關閉 demo 帳號，重新執行 Go / No-Go。",
            "internalGo=true、formalGo=false、databaseMode=supabase，且 Go / No-Go 沒有 P0 blocker。",
            "ops",
            "goLive",
            "重新檢查",
        ),
    ]
    return {
        "summary": {
            "total": len(items),
            "blocked": sum(1 for item in items if item["severity"] == "blocker"),
            "warning": sum(1 for item in items if item["severity"] == "warning"),
            "ready": sum(1 for item in items if item["severity"] == "pass"),
        },
        "items": items,
        "privacy": {
            "metadataOnly": True,
            "containsOfficialDocumentBody": False,
            "containsSealOriginalPath": False,
        },
    }


def internal_launch_user_checklist(readiness: Dict[str, Any], data_readiness: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    checks = readiness.get("checks", {})
    data_checks = (data_readiness or {}).get("checks", {})
    role_counts = data_checks.get("roleCounts") or {}
    access_readiness = data_checks.get("accessReadiness") or {}
    workflow_steps = data_checks.get("workflowSteps") or []
    seal_checks = data_checks.get("companySeals") or []
    user_journeys = data_checks.get("userJourneys") or []
    data_unverifiable = bool(data_checks.get("error")) or (
        (readiness.get("environment") == "production" or readiness.get("databaseMode") == "supabase")
        and not data_checks
    )
    missing_roles = [role for role in INTERNAL_LAUNCH_REQUIRED_ROLES if role_counts.get(role, 0) < 1]
    applicant_ready = bool(data_checks.get("applicantReady"))
    workflow_missing = [
        f"{step.get('step_name') or step.get('step_key')} 找不到處理人"
        for step in workflow_steps
        if not step.get("ready")
    ]
    missing_seals: List[str] = []
    for company in seal_checks:
        for seal in company.get("requiredSeals") or []:
            if not seal.get("active"):
                missing_seals.append(f"{company.get('company_name')} 缺少啟用{seal.get('label')}")
            elif not seal.get("currentFile"):
                missing_seals.append(f"{company.get('company_name')} 的{seal.get('label')}缺 current 版本")
    ops_missing = [
        name
        for name in [
            "SUPABASE_URL",
            "SUPABASE_SERVICE_ROLE_KEY",
            "EDOC_STORAGE_PROVIDER",
            "EDOC_STORAGE_SUPABASE_URL",
            "EDOC_STORAGE_SERVICE_ROLE_KEY",
            "EDOC_STORAGE_BUCKET",
            "EDOC_SEAL_STORAGE_BUCKET",
            "EDOC_OBJECT_STORAGE_URL",
            "EDOC_STORAGE_ACCESS_MODE",
            "EDOC_FILE_ENCRYPTION_KEY",
        ]
        if name in readiness.get("missing", [])
    ]
    if not checks.get("demoAccountsDisabled"):
        ops_missing.append("EDOC_DISABLE_DEMO_ACCOUNTS=true")
    notifications = []
    if not checks.get("smtp"):
        notifications.append("Resend 尚未設定，Email 待辦不會發出。")
    if not checks.get("line"):
        notifications.append("LINE_WEBHOOK_URL 未設定，逾期稽催不會推送 LINE。")
    formal_disabled = bool(checks.get("formalExchangeDisabled"))
    login_blockers = list(access_readiness.get("blockers") or [])
    login_warnings = list(access_readiness.get("warnings") or [])
    production_login_gate = (
        readiness.get("environment") == "production"
        or readiness.get("databaseMode") == "supabase"
        or any(name in readiness.get("missing", []) for name in ["SUPABASE_URL", "SUPABASE_SERVICE_ROLE_KEY"])
        or data_checks.get("error") in {"supabase_runtime_env_missing", "supabase_request_failed"}
    )
    supabase_missing = [
        name
        for name in ["SUPABASE_URL", "SUPABASE_SERVICE_ROLE_KEY"]
        if name in readiness.get("missing", [])
    ]
    if production_login_gate and (supabase_missing or not checks.get("supabase")):
        detail = f"缺少 {', '.join(supabase_missing)}" if supabase_missing else "Supabase 連線檢查未通過"
        login_blockers.append(f"正式資料庫尚未可用，正式帳號登入不可判定為通過：{detail}。")
    if data_checks.get("error"):
        login_blockers.extend(data_readiness.get("blockers") or ["正式帳號資料尚未完成查核。"])
    login_blockers = list(dict.fromkeys(login_blockers))
    login_warnings = list(dict.fromkeys(login_warnings))
    journey_warnings = [
        f"{item.get('title')}：{compact_evidence(item.get('missing') or [])}"
        for item in user_journeys
        if not item.get("ready")
    ]
    seal_data_blockers = ["正式資料庫尚未可用，無法驗證 Seal Vault current 印章版本。"] if data_unverifiable else []
    journey_blockers = ["正式資料庫尚未可用，無法驗證使用者旅程與走測結果。"] if data_unverifiable else []
    return [
        launch_item(
            "login_access",
            "正式帳號登入",
            "IT、行政部主任",
            login_blockers,
            login_warnings,
            "用正式帳號或 Logging Portal 分別登入申請人、主管、行政部主任、總務，確認 demo 帳密不可進入正式站。",
            "同仁週一第一步是能進系統；正式帳號沒匯入時，後面的簽核與用印都無法開始。",
        ),
        launch_item(
            "applicant",
            "申請人/一般同仁",
            "員工、業務助理",
            ([] if applicant_ready else ["缺少可建立發文申請單的啟用申請人帳號。"]) + workflow_missing,
            ["印章資料未齊，送出後可能在自動用印卡住。"] if missing_seals else [],
            "用正式帳號建立一張空白公文與一張上傳 PDF 用印申請。",
            "同仁要能登入、填發文申請單、送簽、最後下載已用印版本。",
        ),
        launch_item(
            "approvers",
            "主管與行政部主任",
            "申請人主管、行政部主任",
            [f"缺少啟用的「{role}」帳號。" for role in missing_roles if role in {"主管", "行政部主任"}] + workflow_missing,
            [],
            "用主管與行政部主任帳號各核准一關，確認不可跳關。",
            "簽核人要在我的待辦看到案件，且只能處理輪到自己的關卡。",
        ),
        launch_item(
            "general_affairs",
            "總務",
            "總務",
            [f"缺少啟用的「總務」帳號。"] if "總務" in missing_roles else [],
            ["Seal Vault current 版本未齊，總務會遇到用印失敗重試。"] if missing_seals else [],
            "用總務帳號完成審核、處理用印失敗重試、回填寄發資料與證明附件。",
            "總務要能審核用印、下載已用印 PDF、完成外部寄發紀錄。",
        ),
        launch_item(
            "seal_admin",
            "印章管理",
            "seal_admin、總務",
            seal_data_blockers + missing_seals,
            [],
            "補齊每間啟用公司便章、公司設立章、關防印、銀行章的 Seal Vault current 版本。",
            "沒有 current 版本時，主管核准後仍無法產生已用印 PDF。",
        ),
        launch_item(
            "ops",
            "IT/維運",
            "IT、系統管理員",
            ops_missing + list(readiness.get("blockers", [])),
            list(readiness.get("warnings", [])),
            "在 Vercel production 補齊 env、套用 Supabase migrations、建立 private buckets 後重跑 Go / No-Go。",
            "正式站要使用 Supabase/private storage，並關閉 demo/quick role login。",
        ),
        launch_item(
            "notifications",
            "通知與稽催",
            "IT、總務",
            [],
            notifications,
            "至少確認站內通知可用；若要避免漏簽，補 Resend 與 LINE 後測一次派送失敗重送。",
            "簽核待辦、退回、總務寄發與逾期回文都要找得到人。",
        ),
        launch_item(
            "user_journeys",
            "上線前使用者走測",
            "申請人、主管、總務、收文承辦",
            journey_blockers,
            journey_warnings,
            "用正式帳號逐一走測發文、公文 PDF 用印、總務寄發、收文分派、內部派文回文。",
            "同仁下週一進站後，必須不用工程師陪同也能完成核心工作。",
        ),
        launch_item(
            "formal_exchange_scope",
            "政府正式交換邊界",
            "行政部主任、總務",
            [] if formal_disabled else ["launch scope 或 provider 狀態不一致，可能誤開正式交換入口。"],
            [] if formal_disabled else ["未取得 jAgent/API/SDK/封包規格前不得啟用正式交換。"],
            "維持 internal_official；正式 jAgent 送交入口只保留 mock/sandbox 演練。",
            "下週一是內部正式使用，不對外宣稱政府電子交換或法定電子簽章已啟用。",
        ),
    ]


def launch_smoke_report(readiness: Dict[str, Any]) -> Dict[str, Any]:
    journeys = readiness.get("userJourneyChecklist") or []
    checklist = readiness.get("userLaunchChecklist") or []
    access_readiness = (readiness.get("dataReadiness") or {}).get("checks", {}).get("accessReadiness") or {}
    access_checks = access_readiness.get("checks") or {}
    ready_journeys = [item for item in journeys if item.get("ready")]
    blocker_items = [item for item in checklist if item.get("severity") == "blocker"]
    warning_items = [item for item in checklist if item.get("severity") == "warning"]
    next_fixes = launch_smoke_next_fixes(checklist, journeys)
    owner_actions = launch_smoke_owner_actions(next_fixes)
    execution_plan = launch_smoke_execution_plan(journeys, next_fixes, readiness)
    duty_board = launch_smoke_duty_board(next_fixes, execution_plan)
    user_perspective_gaps = launch_user_perspective_gaps(readiness)
    report = {
        "reportType": "internal_official_launch_smoke_test",
        "generatedAt": now(),
        "targetLaunchDate": "2026-07-13",
        "launchScope": readiness.get("launchScope") or launch_scope(),
        "environment": readiness.get("environment") or DEPLOYMENT_ENV,
        "databaseMode": readiness.get("databaseMode") or ("supabase" if USE_SUPABASE else "sqlite"),
        "decision": "INTERNAL_GO" if readiness.get("internalGo") else "NO_GO",
        "internalGo": bool(readiness.get("internalGo")),
        "formalGo": False,
        "formalExchangeDisabled": bool(readiness.get("checks", {}).get("formalExchangeDisabled")),
        "summary": {
            "journeyReady": len(ready_journeys),
            "journeyTotal": len(journeys),
            "blockerCount": len(blocker_items),
            "warningCount": len(warning_items),
            "missingEnvironmentCount": len(readiness.get("missing") or []),
        },
        "userJourneys": [
            {
                "key": item.get("key"),
                "title": item.get("title"),
                "actor": item.get("actor"),
                "status": item.get("status"),
                "ready": bool(item.get("ready")),
                "missing": item.get("missing") or [],
                "evidence": item.get("evidence") or [],
                "acceptanceCriteria": item.get("acceptanceCriteria") or [],
                "nextAction": item.get("nextAction"),
            }
            for item in journeys
        ],
        "nextFixes": next_fixes,
        "ownerActions": owner_actions,
        "executionPlan": execution_plan,
        "dutyBoard": duty_board,
        "userPerspectiveGaps": user_perspective_gaps,
        "accessReadiness": {
            "ready": bool(access_readiness.get("ready", False)),
            "summary": access_readiness.get("summary", ""),
            "blockers": access_readiness.get("blockers") or [],
            "warnings": access_readiness.get("warnings") or [],
            "counts": {
                "activeUserCount": access_checks.get("activeUserCount", 0),
                "demoSeedUserCount": access_checks.get("demoSeedUserCount", 0),
                "passwordLoginCandidateCount": access_checks.get("passwordLoginCandidateCount", 0),
                "demoAccountsDisabled": bool(access_checks.get("demoAccountsDisabled", False)),
                "production": bool(access_checks.get("production", False)),
            },
            "roleChecks": [
                {
                    "role": item.get("role"),
                    "activeCount": item.get("activeCount", 0),
                    "formalAccountCount": item.get("formalAccountCount", 0),
                    "demoSeedCount": item.get("demoSeedCount", 0),
                    "hasFormalAccount": bool(item.get("hasFormalAccount", False)),
                }
                for item in access_checks.get("roleChecks", [])
            ],
        },
        "roleChecklist": [
            {
                "key": item.get("key"),
                "title": item.get("title"),
                "owner": item.get("owner"),
                "severity": item.get("severity"),
                "status": item.get("status"),
                "evidence": item.get("evidence"),
                "action": item.get("action"),
            }
            for item in checklist
        ],
        "blockers": readiness.get("blockers") or [],
        "warnings": readiness.get("warnings") or [],
        "scopeNote": readiness.get("scopeNote") or "內部正式使用；政府正式電子交換未啟用。",
    }
    report["reportHash"] = hashlib.sha256(json.dumps(report, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest().upper()
    return report


def enrich_internal_readiness_with_data(readiness: Dict[str, Any], data_readiness: Dict[str, Any] | None) -> Dict[str, Any]:
    if not data_readiness:
        enriched = {**readiness, "userJourneyChecklist": [], "userLaunchChecklist": internal_launch_user_checklist(readiness, None)}
        return {**enriched, "launchSmokeReport": launch_smoke_report(enriched)}
    blockers = [*readiness.get("blockers", []), *data_readiness.get("blockers", [])]
    warnings = [*readiness.get("warnings", []), *data_readiness.get("warnings", [])]
    ready = bool(readiness.get("ready") and data_readiness.get("ready"))
    checks = {**readiness.get("checks", {}), "launchData": data_readiness.get("ready", False)}
    enriched = {**readiness, "blockers": blockers, "warnings": warnings, "checks": checks}
    result = {
        **enriched,
        "ready": ready,
        "internalGo": ready and readiness.get("launchScope") == "internal_official",
        "scopeNote": (
            "內部正式使用可開放；政府 jAgent 正式交換與法定電子簽章仍未啟用。"
            if ready
            else "內部正式使用尚不可開放；請先排除上線阻擋。政府 jAgent 正式交換與法定電子簽章仍維持關閉。"
        ),
        "dataReadiness": data_readiness,
        "userJourneyChecklist": data_readiness.get("checks", {}).get("userJourneys", []),
        "userLaunchChecklist": internal_launch_user_checklist(enriched, data_readiness),
    }
    return {**result, "launchSmokeReport": launch_smoke_report(result)}


def enrich_go_live_audit_with_data(audit: Dict[str, Any], data_readiness: Dict[str, Any] | None) -> Dict[str, Any]:
    if not data_readiness:
        return audit
    internal = enrich_internal_readiness_with_data(audit.get("internalReadiness", {}), data_readiness)
    internal_go = bool(internal.get("ready") and audit.get("launchScope") == "internal_official")
    formal_go = bool(audit.get("formalGo") and data_readiness.get("ready"))
    decision = "GO" if formal_go else "INTERNAL_GO" if internal_go else "NO_GO"
    data_category = {
        "key": "launch_data",
        "name": "上線資料完整性",
        "status": "pass" if data_readiness.get("ready") else "fail",
        "severity": "critical",
        "evidence": data_readiness.get("summary", ""),
        "action": "補齊正式帳號、主管/總務/行政角色、啟用公司與 Seal Vault current 印章版本後再重跑檢查。",
    }
    categories = [item for item in audit.get("categories", []) if item.get("key") != "launch_data"]
    categories.append(data_category)
    summary = audit.get("summary", "")
    if not data_readiness.get("ready"):
        summary = "不可上線；正式帳號、簽核角色、公司或 Seal Vault 印章資料尚未齊備。"
    return {
        **audit,
        "decision": decision,
        "formalGo": formal_go,
        "internalGo": internal_go,
        "summary": summary,
        "internalReadiness": internal,
        "internalBlockers": internal.get("blockers", []),
        "warnings": [*internal.get("warnings", []), *audit.get("readiness", {}).get("warnings", [])],
        "categories": categories,
        "dataReadiness": data_readiness,
        "launchSmokeReport": internal.get("launchSmokeReport"),
    }


def current_internal_readiness_report(conn: sqlite3.Connection | None = None) -> Dict[str, Any]:
    if USE_SUPABASE:
        return enrich_internal_readiness_with_data(internal_readiness(), supabase_internal_launch_data_readiness())
    if conn is not None:
        return enrich_internal_readiness_with_data(internal_readiness(), internal_launch_data_readiness(conn))
    with connect() as local_conn:
        return enrich_internal_readiness_with_data(internal_readiness(), internal_launch_data_readiness(local_conn))


def current_launch_smoke_report(conn: sqlite3.Connection | None = None) -> Dict[str, Any]:
    return current_internal_readiness_report(conn).get("launchSmokeReport") or launch_smoke_report(internal_readiness())


def current_go_live_audit_report(conn: sqlite3.Connection | None = None) -> Dict[str, Any]:
    if USE_SUPABASE:
        return enrich_go_live_audit_with_data(go_live_audit(), supabase_internal_launch_data_readiness())
    if conn is not None:
        return enrich_go_live_audit_with_data(go_live_audit(), internal_launch_data_readiness(conn))
    with connect() as local_conn:
        return enrich_go_live_audit_with_data(go_live_audit(), internal_launch_data_readiness(local_conn))


def launch_cutover_production_checklist(audit: Dict[str, Any]) -> List[Dict[str, Any]]:
    readiness = audit.get("internalReadiness") or {}
    checks = readiness.get("checks") or {}
    data_readiness = readiness.get("dataReadiness") or {}
    non_seal_data_ready = bool(data_readiness.get("readyWithoutSealAssets"))
    seal_assets_ready = bool(data_readiness.get("sealAssetsReady"))
    missing = set(readiness.get("missing") or [])
    database_missing = [name for name in ["EDOC_DB_MODE", "SUPABASE_URL", "SUPABASE_SERVICE_ROLE_KEY"] if name in missing]
    if readiness.get("databaseMode") != "supabase" and "EDOC_DB_MODE" not in database_missing:
        database_missing.insert(0, "EDOC_DB_MODE=supabase")
    storage_missing = [
        name
        for name in [
            "EDOC_STORAGE_PROVIDER",
            "EDOC_STORAGE_BUCKET",
            "EDOC_SEAL_STORAGE_BUCKET",
            "EDOC_STORAGE_ACCESS_MODE",
            "EDOC_FILE_ENCRYPTION_KEY",
        ]
        if name in missing
    ]
    if EDOC_STORAGE_PROVIDER != "supabase" and "EDOC_OBJECT_STORAGE_URL" in missing:
        storage_missing.append("EDOC_OBJECT_STORAGE_URL")
    launch_missing = [name for name in ["EDOC_DEPLOYMENT_ENV", "EDOC_PUBLIC_BASE_URL", "EDOC_LAUNCH_SCOPE"] if name in missing]
    notification_missing = [
        *([] if checks.get("smtp") else ["RESEND_API_KEY / MAIL_FROM"]),
        *([] if checks.get("line") else ["LINE_WEBHOOK_URL"]),
    ]
    return [
        {
            "key": "vercel_env",
            "title": "Vercel Production Env",
            "owner": "IT",
            "severity": "issue" if launch_missing or missing else "pass",
            "evidence": "、".join(launch_missing) if launch_missing else "production scope 變數已具備",
            "doneWhen": "EDOC_DEPLOYMENT_ENV=production、EDOC_LAUNCH_SCOPE=internal_official、EDOC_PUBLIC_BASE_URL 指向正式網址。",
        },
        {
            "key": "supabase_db",
            "title": "Supabase Production DB",
            "owner": "IT",
            "severity": "pass" if checks.get("supabase") and readiness.get("databaseMode") == "supabase" else "issue",
            "evidence": "、".join(database_missing) if database_missing else f"databaseMode={readiness.get('databaseMode') or 'unknown'}",
            "doneWhen": "Go / No-Go 顯示 databaseMode=supabase，internal-readiness 不再缺 SUPABASE_URL / SERVICE_ROLE_KEY。",
        },
        {
            "key": "private_storage",
            "title": "Private Storage / Seal Vault",
            "owner": "IT、總務",
            "severity": "pass" if checks.get("privateStorage") and checks.get("encryption") else "issue",
            "evidence": "、".join(storage_missing) if storage_missing else f"bucket={checks.get('documentBucket') or 'edoc-private'} / seal={checks.get('sealVaultBucket') or 'edoc-seal-vault'}",
            "doneWhen": "privateStorage=true、encryption=true，且 Seal Vault current 版本可用。",
        },
        {
            "key": "demo_policy",
            "title": "Demo / Quick Login 關閉",
            "owner": "IT、行政部主任",
            "severity": "warn" if checks.get("demoAccountsDisabled") and checks.get("demoAccountsSafeDefault") and not checks.get("demoAccountsExplicitlyDisabled") else "pass" if checks.get("demoAccountsDisabled") else "issue",
            "evidence": "EDOC_DISABLE_DEMO_ACCOUNTS=true" if checks.get("demoAccountsExplicitlyDisabled") else "正式站安全預設已阻擋 demo；仍需設定 EDOC_DISABLE_DEMO_ACCOUNTS=true" if checks.get("demoAccountsDisabled") else "EDOC_DISABLE_DEMO_ACCOUNTS 未啟用",
            "doneWhen": "正式站 demo login 被阻擋，正式帳號或 Logging Portal 可登入。",
        },
        {
            "key": "notifications",
            "title": "通知與稽催",
            "owner": "IT、總務",
            "severity": "warn" if notification_missing else "pass",
            "evidence": "、".join(notification_missing) if notification_missing else "Resend / LINE 已設定",
            "doneWhen": "待簽核、退回、用印完成與逾期提醒至少能在站內看到；Email/LINE 視上線策略啟用。",
        },
        {
            "key": "formal_exchange_guard",
            "title": "正式電子交換邊界",
            "owner": "總務、行政部主任",
            "severity": "pass" if checks.get("formalExchangeDisabled") else "issue",
            "evidence": f"provider={checks.get('exchangeProvider') or 'unknown'} / env={checks.get('exchangeEnvironment') or 'unknown'}",
            "doneWhen": "formalGo=false、正式送交按鈕禁用，UI 顯示政府電子交換未啟用。",
        },
    ]


def supabase_cutover_verification_matrix(audit: Dict[str, Any], readiness: Dict[str, Any]) -> Dict[str, Any]:
    """Metadata-only operator checklist for Supabase production cutover validation."""
    checks = readiness.get("checks") or {}
    database_mode = readiness.get("databaseMode") or audit.get("databaseMode") or ("supabase" if USE_SUPABASE else "sqlite")
    data_api_tables = [
        {
            "key": "official_document_application",
            "journey": "發文申請單、空白公文、上傳 PDF 用印",
            "tables": [
                "official_documents",
                "official_document_files",
                "official_document_approval_steps",
                "official_document_approval_logs",
                "official_document_stamp_requests",
                "official_document_stamp_positions",
                "official_document_text_overlays",
                "official_document_dispatch_records",
            ],
            "expectedGrant": "service_role 可 select/insert/update；authenticated 只依 RLS 讀取流程參與案件。",
            "smokeApis": [
                "POST /api/official-documents",
                "GET /api/official-documents/my-tasks",
                "GET /api/official-documents/:documentId",
                "POST /api/official-documents/:documentId/dispatch/complete",
            ],
        },
        {
            "key": "seal_vault_metadata",
            "journey": "公司印章管理、Seal Vault metadata、用印紀錄",
            "tables": [
                "companies",
                "seal_reference_options",
                "company_seals",
                "company_seal_files",
                "seal_permissions",
                "seal_usage_requests",
                "seal_usage_approvals",
                "seal_usage_logs",
                "file_objects",
            ],
            "expectedGrant": "company_seal_files 與 Seal Vault file_objects 原章 metadata 由 service_role/backend 管理；前端不可取得原章檔案連結或原始儲存定位資訊。",
            "smokeApis": [
                "GET /api/companies/:companyId/seals",
                "POST /api/seals/:sealId/files",
                "GET /api/seals/:sealId/files",
                "GET /api/production/seal-vault-readiness",
            ],
        },
        {
            "key": "inbound_documents",
            "journey": "收文登錄、附件、承辦分派、期限、結案",
            "tables": ["inbound_documents", "inbound_document_attachments"],
            "expectedGrant": "service_role 可寫入；authenticated 只允許總務、承辦、授權角色依 RLS 讀取。",
            "smokeApis": [
                "POST /api/inbound-documents",
                "PATCH /api/inbound-documents/:id/assign",
                "POST /api/inbound-documents/:id/attachments",
                "POST /api/inbound-documents/:id/close",
            ],
        },
        {
            "key": "internal_dispatch",
            "journey": "內部派文、N 日內回文、附件回覆、結案",
            "tables": [
                "internal_dispatches",
                "internal_dispatch_recipients",
                "internal_dispatch_replies",
                "internal_dispatch_logs",
            ],
            "expectedGrant": "service_role 可寫入；authenticated 僅派文者、收件人與授權管理角色依 RLS 讀取/回覆。",
            "smokeApis": [
                "POST /api/internal-dispatches",
                "GET /api/internal-dispatches",
                "POST /api/internal-dispatches/:id/replies",
                "POST /api/internal-dispatches/:id/close",
            ],
        },
        {
            "key": "audit_and_security",
            "journey": "下載、簽核、用印、寄發、收文與派文操作紀錄",
            "tables": ["audit_logs", "login_events", "auth_sessions", "file_download_tokens", "virus_scan_jobs"],
            "expectedGrant": "audit log 由 backend 寫入；一般使用者不得任意列出全公司敏感紀錄。",
            "smokeApis": [
                "GET /api/production/go-live-audit",
                "GET /api/production/launch-cutover-package",
                "POST /api/production/launch-cutover-package/attest",
            ],
        },
    ]
    table_names = sorted({table for group in data_api_tables for table in group["tables"]})
    table_list_sql = ", ".join(f"'{table}'" for table in table_names)
    sql_checks = [
        {
            "key": "rls_enabled",
            "title": "確認 public table 都已啟用 RLS",
            "sql": (
                "select n.nspname as schema_name, c.relname as table_name, c.relrowsecurity as rls_enabled "
                "from pg_class c join pg_namespace n on n.oid = c.relnamespace "
                f"where n.nspname = 'public' and c.relname in ({table_list_sql}) "
                "order by c.relname;"
            ),
            "passCondition": "所有列 rls_enabled=true；若缺表代表 migration 尚未套用。",
        },
        {
            "key": "data_api_grants",
            "title": "確認 Data API / PostgREST 需要的 GRANT 存在",
            "sql": (
                "select table_name, grantee, privilege_type "
                "from information_schema.role_table_grants "
                f"where table_schema = 'public' and table_name in ({table_list_sql}) "
                "order by table_name, grantee, privilege_type;"
            ),
            "passCondition": "service_role 對後端寫入表有必要權限；需前端讀取的表才授權 authenticated，且必須搭配 RLS。",
        },
        {
            "key": "storage_buckets_private",
            "title": "確認文件與 Seal Vault bucket 皆為 private",
            "sql": (
                "select id, public, file_size_limit, allowed_mime_types "
                "from storage.buckets "
                "where id in ('edoc-private', 'edoc-seal-vault') "
                "order by id;"
            ),
            "passCondition": "edoc-private.public=false 且 edoc-seal-vault.public=false。",
        },
        {
            "key": "storage_and_seal_policies",
            "title": "確認 Storage / Seal Vault policy 沒有公開原章",
            "sql": (
                "select schemaname, tablename, policyname, permissive, roles, cmd "
                "from pg_policies "
                "where (schemaname = 'storage' and tablename = 'objects') "
                "or (schemaname = 'public' and tablename in ('company_seal_files', 'file_objects')) "
                "order by schemaname, tablename, policyname;"
            ),
            "passCondition": "Seal Vault originals 只能由 service_role/backend 讀取；anon/authenticated 不得直接讀 edoc-seal-vault 原檔。",
        },
    ]
    storage_buckets = [
        {
            "bucket": "edoc-private",
            "public": False,
            "contains": "original_pdf, generated_pdf, stamped_pdf, attachments, dispatch proof",
            "frontendDirectUrlAllowed": False,
            "downloadPath": "backend checked download API with audit log",
        },
        {
            "bucket": "edoc-seal-vault",
            "public": False,
            "contains": "original seal image versions only",
            "frontendDirectUrlAllowed": False,
            "downloadPath": "no raw download; backend-only stamping service reads originals",
        },
    ]
    blockers = []
    if database_mode != "supabase" or not checks.get("supabase"):
        blockers.append("Supabase production DB 尚未連線，無法驗證 RLS/GRANT/Data API。")
    if not checks.get("privateStorage"):
        blockers.append("private object storage 尚未就緒，文件與印章不可上線使用。")
    return {
        "reportType": "supabase_cutover_verification_matrix",
        "status": "BLOCKED" if blockers else "READY_FOR_OPERATOR_VERIFICATION",
        "safeSqlArtifact": {
            "path": "supabase/verification/production_cutover_checks.sql",
            "description": "Metadata-only SQL checks for RLS, Data API grants, private storage buckets, Seal Vault policies, RLS helper functions, and internal-launch reference options.",
            "containsSecrets": False,
            "containsOfficialDocumentBody": False,
            "containsSealOriginalPath": False,
        },
        "source": {
            "supabaseChangelog": "https://supabase.com/changelog/45329-breaking-change-tables-not-exposed-to-data-and-graphql-api-automatically",
            "reason": "新 Supabase 專案 public schema table 可能不會自動暴露到 Data API；GRANT、RLS 與 API smoke test 需一起驗。",
        },
        "blockers": blockers,
        "tableGroups": data_api_tables,
        "tableCount": len(table_names),
        "storageBuckets": storage_buckets,
        "safeSqlChecks": sql_checks,
        "operatorSmokeApis": [
            "GET /api/production/internal-readiness",
            "GET /api/production/go-live-audit",
            "GET /api/production/seal-vault-readiness",
            "GET /api/production/account-readiness-package",
            "GET /api/production/launch-cutover-package",
        ],
        "securityPolicy": {
            "metadataOnly": True,
            "containsSecrets": False,
            "containsServiceRoleValue": False,
            "containsOfficialDocumentBody": False,
            "containsSealOriginalUrl": False,
            "frontendMayUseServiceRole": False,
        },
    }


def production_cutover_sql_artifact() -> Dict[str, Any]:
    path = ROOT / "supabase" / "verification" / "production_cutover_checks.sql"
    content = path.read_text(encoding="utf-8")
    data = content.encode("utf-8")
    return {
        "file_name": "edoc-production-cutover-checks.sql",
        "relative_path": "supabase/verification/production_cutover_checks.sql",
        "mime_type": "text/sql; charset=utf-8",
        "content": content,
        "data": data,
        "sha256": hashlib.sha256(data).hexdigest().upper(),
        "securityPolicy": {
            "metadataOnly": True,
            "containsSecrets": False,
            "containsOfficialDocumentBody": False,
            "containsSealOriginalPath": False,
        },
    }


def production_vercel_env_template_artifact() -> Dict[str, Any]:
    lines = [
        "# eDoc Vercel Production env 補件模板",
        "# 用途：補齊 2026-07-13 內部正式使用上線 P0 底座。",
        "# 安全：此檔只放 placeholder，不可填入後 commit 到 GitHub；實際值請貼到 Vercel Production Environment Variables。",
        "# Vercel CLI 範例：printf '%s\\n' '<actual-value>' | vercel env add VARIABLE_NAME production --scope team_LGag47eU8tKbsK6ixAmVa5Uq",
        "",
        "# 上線模式與正式站邊界",
        "EDOC_DEPLOYMENT_ENV=production",
        "EDOC_LAUNCH_SCOPE=internal_official",
        "EDOC_PUBLIC_BASE_URL=https://edoc.suiyuecare.com",
        "EDOC_DISABLE_DEMO_ACCOUNTS=true",
        "EDOC_DB_MODE=supabase",
        "EDOC_EXCHANGE_PROVIDER=mock",
        "EDOC_EXCHANGE_ENV=sandbox",
        "",
        "# P0：獨立 eDoc Supabase production project",
        "SUPABASE_URL=<paste-edoc-supabase-project-url>",
        "SUPABASE_SERVICE_ROLE_KEY=<paste-server-side-service-role-key-never-public>",
        "",
        "# P0：private document storage / Seal Vault",
        "EDOC_STORAGE_PROVIDER=supabase",
        "EDOC_STORAGE_BUCKET=edoc-private",
        "EDOC_SEAL_STORAGE_BUCKET=edoc-seal-vault",
        "# 若檔案放在另一個 Supabase 專案，請同時設定下列兩項；publishable key 不可取代 server key：",
        "# EDOC_STORAGE_SUPABASE_URL=<paste-storage-project-url>",
        "# EDOC_STORAGE_SERVICE_ROLE_KEY=<paste-storage-project-server-key-never-public>",
        "# 同專案 Storage 可省略以上兩項；系統會由 SUPABASE_URL 推導 /storage/v1。",
        "# 若改用 S3/R2/private-object-storage，才需要明確設定：",
        "# EDOC_OBJECT_STORAGE_URL=<paste-private-storage-endpoint>",
        "EDOC_STORAGE_ACCESS_MODE=server-signed-url",
        "EDOC_FILE_ENCRYPTION_ENABLED=true",
        "EDOC_FILE_ENCRYPTION_KEY=<paste-file-encryption-key>",
        "",
        "# P1：通知與監控，可先以站內通知上線，但正式營運建議補齊",
        "RESEND_API_KEY=<paste-server-side-resend-key>",
        "MAIL_FROM=公文收發電子用印系統 <notifications@suiyuecare.com>",
        "LINE_WEBHOOK_URL=<paste-line-webhook-url>",
        "MONITORING_WEBHOOK_URL=<paste-monitoring-webhook-url>",
        "SENTRY_DSN=<paste-sentry-dsn>",
        "",
        "# 驗收指令",
        "curl https://edoc.suiyuecare.com/api/production/internal-readiness",
        "curl https://edoc.suiyuecare.com/api/production/go-live-audit",
        "curl https://edoc.suiyuecare.com/api/production/cutover-readiness-package",
        "curl https://edoc.suiyuecare.com/api/production/supabase-cutover-sql -o edoc-production-cutover-checks.sql",
        "",
        "# 完成標準：internalGo=true、formalGo=false、decision=INTERNAL_GO，且登入頁不再顯示 P0 blocker。",
    ]
    content = "\n".join(lines) + "\n"
    data = content.encode("utf-8")
    return {
        "file_name": "edoc-production-vercel-env.template",
        "relative_path": "generated/edoc-production-vercel-env.template",
        "mime_type": "text/plain; charset=utf-8",
        "content": content,
        "data": data,
        "sha256": hashlib.sha256(data).hexdigest().upper(),
        "securityPolicy": {
            "metadataOnly": True,
            "containsSecrets": False,
            "containsPlaceholderValuesOnly": True,
            "containsOfficialDocumentBody": False,
            "containsSealOriginalPath": False,
        },
    }


def production_supabase_bootstrap_checklist_artifact() -> Dict[str, Any]:
    manifest_path = ROOT / "supabase" / "verification" / "migration_manifest.json"
    manifest_raw = manifest_path.read_bytes()
    try:
        migration_manifest = json.loads(manifest_raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError("supabase_migration_manifest_invalid") from exc
    migration_files = migration_manifest.get("migrations") if isinstance(migration_manifest, dict) else None
    if (
        not isinstance(migration_manifest, dict)
        or migration_manifest.get("schemaVersion") != 1
        or migration_manifest.get("directory") != "supabase/migrations"
        or not isinstance(migration_files, list)
        or not migration_files
        or migration_files != sorted(set(migration_files))
        or any(
            not isinstance(name, str)
            or not re.fullmatch(r"[0-9]{12,20}_[a-z0-9_]+\.sql", name)
            for name in migration_files
        )
    ):
        raise RuntimeError("supabase_migration_manifest_invalid")
    payload = {
        "reportType": "edoc_supabase_production_bootstrap_checklist",
        "generatedAt": now(),
        "launchScope": "internal_official",
        "purpose": "建立或切換 dedicated eDoc Supabase production project 後，套用 migrations、建立 private buckets、驗收 RLS/GRANT/Data API 與 smoke APIs。",
        "requiredExternalInputs": [
            {
                "key": "supabase_project",
                "description": "Dedicated eDoc Supabase production project ref / URL，由 Supabase owner 建立或指定。",
                "containsSecret": False,
            },
            {
                "key": "SUPABASE_SERVICE_ROLE_KEY",
                "description": "只貼到 Vercel Production server-side env；不可放 repo、前端、NEXT_PUBLIC 或截圖。",
                "containsSecret": True,
            },
        ],
        "migrationPlan": {
            "directory": "supabase/migrations",
            "count": len(migration_files),
            "files": migration_files,
            "manifest": {
                "path": "supabase/verification/migration_manifest.json",
                "schemaVersion": 1,
                "sha256": hashlib.sha256(manifest_raw).hexdigest().upper(),
                "containsMigrationSql": False,
                "containsSecrets": False,
            },
            "commands": [
                "supabase link --project-ref <project-ref>",
                "supabase db push --linked",
                "supabase migration list --linked",
                "supabase db advisors --linked",
            ],
            "notes": [
                "請先確認連到 dedicated eDoc production project，不可套到 Finance/HR/Website 等既有專案。",
                "若 Supabase Data API 對新表回 permission denied，請依 production_cutover_checks.sql 檢查 explicit GRANT 與 RLS。",
            ],
        },
        "storageBuckets": [
            {
                "id": "edoc-private",
                "public": False,
                "contains": "原始 PDF、系統產生 PDF、已用印 PDF、附件、寄發證明",
                "frontendDirectUrlAllowed": False,
            },
            {
                "id": "edoc-seal-vault",
                "public": False,
                "contains": "印章原始電子檔版本",
                "frontendDirectUrlAllowed": False,
                "rawDownloadAllowed": False,
            },
        ],
        "vercelEnvAfterProjectReady": [
            "SUPABASE_URL=https://<project-ref>.supabase.co",
            "SUPABASE_SERVICE_ROLE_KEY=<server-side-service-role-key>",
            "EDOC_DB_MODE=supabase",
            "EDOC_STORAGE_PROVIDER=supabase",
            "EDOC_STORAGE_SUPABASE_URL=https://<storage-project-ref>.supabase.co（若與資料庫不同）",
            "EDOC_STORAGE_SERVICE_ROLE_KEY=<storage-server-key>（若與資料庫不同）",
            "EDOC_STORAGE_BUCKET=edoc-private",
            "EDOC_SEAL_STORAGE_BUCKET=edoc-seal-vault",
        ],
        "verificationArtifacts": [
            "GET /api/production/vercel-env-template",
            "GET /api/production/supabase-cutover-sql",
            "GET /api/production/cutover-readiness-package",
            "GET /api/production/internal-readiness",
            "GET /api/production/go-live-audit",
        ],
        "acceptance": [
            "Vercel production 設定 SUPABASE_URL 與 SUPABASE_SERVICE_ROLE_KEY 後重新部署。",
            "production_cutover_checks.sql 的 RLS、Data API grants、private buckets、Seal Vault policies 檢查皆通過。",
            "/api/production/internal-readiness 回 internalGo=true，/api/production/go-live-audit 回 decision=INTERNAL_GO 且 formalGo=false。",
            "五條使用者走測完成：發文、公文 PDF 用印、總務寄發、收文分派、內部派文回文。",
        ],
        "securityPolicy": {
            "metadataOnly": True,
            "containsSecrets": False,
            "containsServiceRoleValue": False,
            "containsOfficialDocumentBody": False,
            "containsSealOriginalUrl": False,
            "containsFileStorageKey": False,
        },
    }
    content = json.dumps(payload, ensure_ascii=False, indent=2)
    data = content.encode("utf-8")
    return {
        "file_name": "edoc-supabase-production-bootstrap-checklist.json",
        "relative_path": "generated/edoc-supabase-production-bootstrap-checklist.json",
        "mime_type": "application/json; charset=utf-8",
        "content": content,
        "data": data,
        "sha256": hashlib.sha256(data).hexdigest().upper(),
        "securityPolicy": payload["securityPolicy"],
    }


