def production_login_auth_foundation_ready(readiness: Dict[str, Any]) -> bool:
    checks = readiness.get("checks") or {}
    missing = set(readiness.get("missing") or [])
    data_readiness = readiness.get("dataReadiness") or {}
    data_checks = data_readiness.get("checks") or {}
    data_error = data_checks.get("error") or data_readiness.get("error") or ""
    return bool(
        readiness.get("databaseMode") == "supabase"
        and checks.get("supabase")
        and (checks.get("financeBridge") or {}).get("configured")
        and (checks.get("portalHandoff") or {}).get("configured")
        and "SUPABASE_URL" not in missing
        and "SUPABASE_SERVICE_ROLE_KEY" not in missing
        and "EDOC_PORTAL_HANDOFF_SECRET" not in missing
        and "EDOC_FINANCE_BRIDGE_URL" not in missing
        and "EDOC_FINANCE_BRIDGE_SECRET" not in missing
        and "EDOC_FINANCE_BRIDGE_TIMEOUT_SECONDS" not in missing
        and data_error != "supabase_runtime_env_missing"
    )


def production_login_release_decision_artifact(readiness: Dict[str, Any] | None = None) -> Dict[str, Any]:
    # Login must stay a fast availability check. The full data/seal/journey audit
    # is intentionally kept on internal-readiness and go-live-audit endpoints.
    readiness = readiness or internal_readiness()
    checks = readiness.get("checks") or {}
    data_readiness = readiness.get("dataReadiness") or {}
    # The public login decision deliberately skips the heavyweight launch-data
    # audit.  Missing keys therefore mean "not evaluated", not "failed".  Keep
    # these values tri-state so operators are never told that workflow data is
    # broken merely because this fast endpoint did not query it.
    data_readiness_evaluated = all(
        key in data_readiness
        for key in ("readyWithoutSealAssets", "sealAssetsReady", "nonSealBlockers", "sealBlockers")
    )
    non_seal_data_ready = (
        bool(data_readiness.get("readyWithoutSealAssets"))
        if data_readiness_evaluated
        else None
    )
    seal_assets_ready = (
        bool(data_readiness.get("sealAssetsReady"))
        if data_readiness_evaluated
        else None
    )
    missing = readiness.get("missing") or []
    blockers = readiness.get("blockers") or []
    warnings = readiness.get("warnings") or []
    next_payload = json.loads(production_next_action_artifact(readiness)["content"])
    primary_action = next_payload.get("primaryAction") or {}
    internal_go = bool(readiness.get("internalGo") or readiness.get("ready"))
    auth_foundation_ready = production_login_auth_foundation_ready(readiness)
    employee_login_ready = bool(
        auth_foundation_ready
        and checks.get("demoAccountsDisabled")
        and checks.get("formalExchangeDisabled")
    )
    setup_mode_enabled = False
    operation_restrictions: List[Dict[str, Any]] = []
    if not checks.get("privateStorage"):
        operation_restrictions.append({
            "code": "PRIVATE_STORAGE_NOT_READY",
            "operations": ["file_upload", "file_download", "pdf_editor", "seal_vault", "stamping"],
            "reason": "Private Storage 尚未通過 readiness；檔案相關作業維持 fail-closed。",
            "failClosed": True,
        })
    antivirus = checks.get("antivirus") or {}
    if not antivirus.get("ready"):
        operation_restrictions.append({
            "code": "ANTIVIRUS_NOT_READY",
            "operations": ["official_attachment_upload", "pdf_editor_upload", "seal_upload"],
            "reason": "防毒掃描尚未通過 readiness；所有上傳作業維持 fail-closed。",
            "failClosed": True,
        })
    editor_scope = checks.get("pdfEditorV2CompanyScope") or {}
    if not editor_scope.get("configured") or editor_scope.get("coversLaunchScope") is False:
        operation_restrictions.append({
            "code": "PDF_EDITOR_SCOPE_NOT_READY",
            "operations": ["pdf_editor_v2"],
            "reason": "PDF Editor V2 公司 allowlist 尚未完成；未在 allowlist 的公司維持關閉。",
            "failClosed": True,
        })
    if data_readiness_evaluated and not checks.get("launchData"):
        if non_seal_data_ready and not seal_assets_ready:
            operation_restrictions.append({
                "code": "SEAL_ASSETS_NOT_READY",
                "operations": ["official_document_submit", "stamping"],
                "reason": "公司、人員與簽核關係已就緒；只因 Seal Vault 尚無正式 current 印章檔而維持阻擋。",
                "failClosed": True,
            })
        else:
            operation_restrictions.append({
                "code": "WORKFLOW_DATA_NOT_READY",
                "operations": ["official_document_submit", "approval_workflow", "stamping"],
                "reason": "公司或簽核關係仍有非印章 blocker；相關案件不得送出。",
                "failClosed": True,
            })

    if employee_login_ready:
        decision = "EMPLOYEE_LOGIN_GO"
        status_label = "可開放同仁登入" if internal_go else "可登入（部分作業受限）"
        primary_owner = "IT、行政部主任、總務"
        user_impact = (
            "一般同仁可用 Finance 正式帳號進入系統並檢視可用功能；尚未通過 readiness 的上傳、PDF 編輯、送簽或用印作業會在後端維持 fail-closed。"
            if operation_restrictions
            else "一般同仁可用正式帳號進入系統，開始發文、簽核、PDF 用印、收文與內部派文；政府正式電子交換仍不可宣稱已啟用。"
        )
        allowed_actors = [
            "Finance 中已啟用且具 EDOC 權限的申請人 / 一般同仁",
            "申請人主管",
            "行政部門主任",
            "總務",
            "收文承辦",
            "內部派文收件同仁",
            "系統管理員",
        ]
        blocked_actors = ["政府正式電子交換送交人員：formalGo=false 前不可送正式 jAgent。"]
        operator_instructions = [
            "登入 shell 與檔案／用印 readiness 分開判定；不得因 AV、Seal Vault 或走測未完成而把有效 Finance 身分導回登入頁。",
            "尚未通過的作業必須依 operationRestrictions 顯示阻擋原因，並由後端 fail-closed；不可只靠前端隱藏。",
            "仍需在 UI 與 SOP 明確標示：內部正式使用已開放，政府電子交換與法定電子簽章未啟用。",
            "若之後發現 Seal Vault、帳號或 private storage 異常，請重新執行 internal-readiness 並必要時改回限制登入。",
        ]
    elif setup_mode_enabled:
        decision = "SETUP_ONLY"
        status_label = "只開放補件人員"
        primary_owner = "行政部主任、總務、IT"
        user_impact = "一般同仁暫時不能登入；只允許補件角色進入正式站完成公司、帳號、主管關係、Seal Vault current 版本與走測資料。"
        allowed_actors = [
            "行政部主任",
            "總務",
            "執行長",
            "具 system_permissions.manage 的正式帳號",
            "具 seals.manage 的正式帳號",
            "具 official_documents.all_todo 的正式帳號",
        ]
        blocked_actors = [
            "申請人 / 一般同仁",
            "一般主管",
            "內部派文收件同仁",
            "收文承辦（除非同時具補件權限）",
        ]
        operator_instructions = [
            "不要通知全體同仁登入；先由補件人員完成下一步行動卡。",
            "補件人員可下載公司名冊、帳號模板、Seal Vault 收檔清冊與首位管理者 bootstrap。",
            "完成後重新部署或重新檢查，直到 go-live-audit 回 INTERNAL_GO 才開放一般同仁。",
        ]
    elif not auth_foundation_ready:
        decision = "LOCKED_ENV"
        status_label = "前台全鎖"
        primary_owner = "IT、Vercel owner、Supabase owner"
        user_impact = "同仁與補件人員都不應登入；正式站尚無法可靠驗證 Supabase/Auth、正式帳號與 Seal Vault 資料。"
        allowed_actors = []
        blocked_actors = [
            "申請人 / 一般同仁",
            "主管",
            "行政部主任",
            "總務",
            "收文承辦",
            "內部派文收件同仁",
            "補件人員",
        ]
        operator_instructions = [
            "先補 Vercel Production 的 Supabase env 與 private storage 設定。",
            "env 補完後必須重新部署 production，舊 deployment 不會自動吃到新 env。",
            "不要為了先進系統而打開 demo / quick role login，也不要開未登入新增 admin API。",
        ]
    else:
        decision = "LOCKED_INTERNAL_BLOCKERS"
        status_label = "前台暫不放行"
        primary_owner = "IT、行政部主任、總務"
        user_impact = "Supabase/Auth 基礎可能已可用，但 demo policy、formal exchange guard、private storage 或上線資料尚未符合補件模式條件。"
        allowed_actors = []
        blocked_actors = [
            "申請人 / 一般同仁",
            "一般主管",
            "總務與補件人員（直到安全 gate 修正）",
        ]
        operator_instructions = [
            "依下一步行動卡修正剩餘 P0，再重新讀取 login-release-decision。",
            "若問題是 demo policy 或 formal exchange guard，請先修正安全設定，不要開放任何前台登入。",
            "若問題是 private storage 或 Seal Vault，請先完成 Supabase/private bucket 驗收。",
        ]

    payload = {
        "reportType": "edoc_login_release_decision",
        "generatedAt": now(),
        "launchScope": readiness.get("launchScope") or launch_scope(),
        "decision": decision,
        "statusLabel": status_label,
        "internalGo": internal_go,
        "formalGo": False,
        "generalEmployeeLoginAllowed": employee_login_ready,
        "setupLoginAllowed": bool(employee_login_ready or setup_mode_enabled),
        "setupModeEnabled": setup_mode_enabled,
        "formalExchangeAllowed": False,
        "demoLoginAllowed": False,
        "authFoundationReady": auth_foundation_ready,
        "shellLoginReady": employee_login_ready,
        "operationRestrictions": operation_restrictions,
        "restrictedOperations": sorted({
            operation
            for restriction in operation_restrictions
            for operation in restriction.get("operations", [])
        }),
        "primaryOwner": primary_owner,
        "userImpact": user_impact,
        "allowedActors": allowed_actors,
        "blockedActors": blocked_actors,
        "currentState": {
            "databaseMode": readiness.get("databaseMode"),
            "missing": missing,
            "blockers": blockers,
            "warnings": warnings,
            "supabase": bool(checks.get("supabase")),
            "privateStorage": bool(checks.get("privateStorage")),
            "demoAccountsDisabled": bool(checks.get("demoAccountsDisabled")),
            "formalExchangeDisabled": bool(checks.get("formalExchangeDisabled")),
            "dataReadinessEvaluated": data_readiness_evaluated,
            "launchData": bool(checks.get("launchData")) if data_readiness_evaluated else None,
            "nonSealWorkflowReady": non_seal_data_ready,
            "sealAssetsReady": seal_assets_ready,
            "nonSealBlockerCount": (
                len(data_readiness.get("nonSealBlockers") or [])
                if data_readiness_evaluated
                else None
            ),
            "sealBlockerCount": (
                len(data_readiness.get("sealBlockers") or [])
                if data_readiness_evaluated
                else None
            ),
            "shellLoginReady": employee_login_ready,
        },
        "primaryAction": {
            "key": primary_action.get("key"),
            "title": primary_action.get("title"),
            "owner": primary_action.get("owner"),
            "severity": primary_action.get("severity"),
            "userImpact": primary_action.get("userImpact"),
            "doNow": primary_action.get("doNow") or [],
            "doneWhen": primary_action.get("doneWhen"),
            "verifyApi": primary_action.get("verifyApi"),
            "sourceArtifacts": primary_action.get("sourceArtifacts") or [],
        },
        "operatorInstructions": operator_instructions,
        "releaseRules": [
            {
                "state": "LOCKED_ENV",
                "rule": "缺 Supabase/Auth foundation 時，所有前台登入都維持鎖定。",
                "allowed": [],
            },
            {
                "state": "SETUP_ONLY",
                "rule": "僅保留給未來明確啟用的維護模式；AV、Seal Vault 或上線資料未齊不得單獨把一般 Finance 身分降級為補件帳號。",
                "allowed": ["行政部主任", "總務", "執行長", "system_permissions.manage", "seals.manage", "official_documents.all_todo"],
            },
            {
                "state": "EMPLOYEE_LOGIN_GO",
                "rule": "Supabase/Auth、Finance bridge、demo 禁用與 formal exchange guard 通過後即可進入 shell；各敏感作業另依 operationRestrictions fail-closed。",
                "allowed": ["Finance 中已啟用且具 EDOC 權限的正式帳號使用者"],
            },
        ],
        "verificationApis": [
            "GET /api/production/login-release-decision",
            "GET /api/production/internal-readiness",
            "GET /api/production/go-live-audit",
            "GET /api/production/account-readiness-package",
            "GET /api/production/seal-vault-readiness",
            "GET /api/production/launch-smoke-report",
        ],
        "downloadArtifacts": [
            "GET /api/production/artifact-index",
            "GET /api/production/next-action",
            "GET /api/production/day-one-support-brief",
            "GET /api/production/handoff-note",
            "GET /api/production/vercel-env-template",
            "GET /api/production/supabase-bootstrap-checklist",
            "GET /api/production/first-admin-bootstrap",
            "GET /api/production/company-launch-roster/template",
            "GET /api/production/formal-account-roster/template",
            "GET /api/production/seal-vault-custody-template",
            "GET /api/production/emergency-manual-intake-template",
        ],
        "mustNotDo": [
            "不可為了讓人先進系統而開啟 demo / quick role login。",
            "不可建立 unauthenticated create-admin API。",
            "不可把 server-side credential、PIN、私鑰、正式公文內容、附件內容或原章檔案放入此決策檔。",
            "不可在 formalGo=false 時宣稱政府電子交換或法定電子簽章已啟用。",
        ],
        "securityPolicy": {
            "metadataOnly": True,
            "containsSecrets": False,
            "containsServiceSideCredentialValue": False,
            "containsPassword": False,
            "containsOfficialDocumentBody": False,
            "containsAttachmentContent": False,
            "containsSealOriginalFile": False,
            "containsSealOriginalUrl": False,
            "containsFileStorageKey": False,
            "unauthenticatedAdminApiAllowed": False,
            "frontendMayUseServiceSideCredential": False,
        },
    }
    payload["reportHash"] = stable_json_hash(payload)
    content = json.dumps(payload, ensure_ascii=False, indent=2)
    data = content.encode("utf-8")
    return {
        "file_name": "edoc-login-release-decision.json",
        "relative_path": "generated/edoc-login-release-decision.json",
        "mime_type": "application/json; charset=utf-8",
        "content": content,
        "data": data,
        "sha256": hashlib.sha256(data).hexdigest().upper(),
        "securityPolicy": payload["securityPolicy"],
    }


