    seal_blocker = checklist_by_key.get("seal_admin", {}).get("severity") == "blocker"
    data_error = data_checks.get("error") or ""
    journey_total = int(smoke_summary.get("journeyTotal") or 0)
    journey_ready = int(smoke_summary.get("journeyReady") or 0)
    journey_incomplete = journey_total > 0 and journey_ready < journey_total
