def safe_csv_template_value(value: Any) -> str:
    text = "" if value is None else str(value)
    if text[:1] in {"=", "+", "-", "@"}:
        return "'" + text
    return text


def csv_template_artifact(
    *,
    file_name: str,
    headers: List[str],
    rows: List[Dict[str, Any]],
    x_artifact: str,
    security_policy: Dict[str, Any],
) -> Dict[str, Any]:
    output = io.StringIO()
    output.write("\ufeff")
    writer = csv.DictWriter(output, fieldnames=headers, extrasaction="ignore")
    writer.writeheader()
    for row in rows:
        writer.writerow({header: safe_csv_template_value(row.get(header, "")) for header in headers})
    content = output.getvalue()
    data = content.encode("utf-8")
    return {
        "file_name": file_name,
        "relative_path": f"generated/{file_name}",
        "mime_type": "text/csv; charset=utf-8",
        "content": content,
        "data": data,
        "sha256": hashlib.sha256(data).hexdigest().upper(),
        "securityPolicy": security_policy,
        "xArtifact": x_artifact,
    }


