def production_formal_account_roster_template_artifact() -> Dict[str, Any]:
    package = current_account_readiness_package()
    template = package.get("rosterImportTemplate") or {}
    headers = template.get("headers") or [
        "role",
        "required",
        "name",
        "email",
        "unit",
        "title",
        "job_level",
        "provider",
        "mfa_status",
        "status",
        "account_source",
        "done_when",
        "notes",
    ]
    rows = template.get("rows") or []
    if not rows:
        rows = [
            {
                "role": role,
                "required": "true" if role in {"員工", "主管", "行政部主任", "總務"} else "false",
                "name": "",
                "email": "",
                "unit": "行政部" if role in {"員工", "行政部主任"} else "總務" if role == "總務" else "營運管理部",
                "title": role,
                "job_level": "部長" if role == "行政部主任" else "課長" if role == "主管" else "職員",
                "provider": "Google Workspace",
                "mfa_status": "待設定",
                "status": "啟用",
                "account_source": "formal_roster",
                "done_when": f"{role} formalAccountCount >= 1，且正式帳號可登入並看到正確待辦。",
                "notes": "請填公司正式姓名與 Email；不可填密碼、PIN、API key、session token 或 demo/seed 帳號。",
            }
            for role in ["員工", "主管", "行政部主任", "總務", "業務助理"]
        ]
    security_policy = {
        "metadataOnly": True,
        "containsPasswords": False,
        "containsUserEmails": False,
        "containsSessionTokens": False,
        "containsServiceRoleValue": False,
        "containsOfficialDocumentBody": False,
        "containsSealOriginalFile": False,
    }
    return csv_template_artifact(
        file_name=template.get("fileName") or "edoc-formal-account-import-template.csv",
        headers=headers,
        rows=rows,
        x_artifact="formal-account-roster-template",
        security_policy=security_policy,
    )


