def launch_operator_signoff_summary(operator_signoff: Dict[str, Any] | None) -> Dict[str, Any]:
    if not isinstance(operator_signoff, dict):
        return {}
    items = operator_signoff.get("items") if isinstance(operator_signoff.get("items"), list) else []
    sanitized_items: List[Dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        sanitized_items.append({
            "key": str(item.get("key") or "")[:80],
            "system_ready": bool(item.get("systemReady")),
            "operator_verified": bool(item.get("operatorVerified")),
            "criteria_checked": int(item.get("criteriaChecked") or 0),
            "criteria_total": int(item.get("criteriaTotal") or 0),
            "has_note": bool(str(item.get("note") or "").strip()),
            "has_actor": bool(str(item.get("actor") or "").strip()),
        })
    criteria_checked = sum(item["criteria_checked"] for item in sanitized_items)
    criteria_total = sum(item["criteria_total"] for item in sanitized_items)
    verified_keys = [item["key"] for item in sanitized_items if item["operator_verified"]]
    unverified_keys = [item["key"] for item in sanitized_items if not item["operator_verified"]]
    system_not_ready_keys = [item["key"] for item in sanitized_items if not item["system_ready"]]
    unsigned_payload = {
        "source": operator_signoff.get("source") or "frontend_operator_signoff",
        "total": len(sanitized_items),
        "operator_verified_count": len(verified_keys),
        "complete_count": sum(1 for item in sanitized_items if item["operator_verified"] and item["system_ready"]),
        "criteria_checked": criteria_checked,
        "criteria_total": criteria_total,
        "verified_keys": verified_keys,
        "unverified_keys": unverified_keys,
        "system_not_ready_keys": system_not_ready_keys,
        "items": sanitized_items,
    }
    return {
        **unsigned_payload,
        "signoff_hash": stable_json_hash(unsigned_payload),
    }


def launch_smoke_report_audit_detail(report: Dict[str, Any], operator_signoff: Dict[str, Any] | None = None) -> str:
    summary = report.get("summary") or {}
    signoff = launch_operator_signoff_summary(operator_signoff)
    signoff_text = (
        f" signoff={signoff.get('operator_verified_count', 0)}/{signoff.get('total', 0)} "
        f"signoffHash={signoff.get('signoff_hash')}"
        if signoff else ""
    )
    return (
        f"decision={report.get('decision')} "
        f"journey={summary.get('journeyReady', 0)}/{summary.get('journeyTotal', 0)} "
        f"blockers={summary.get('blockerCount', 0)} "
        f"warnings={summary.get('warningCount', 0)} "
        f"hash={report.get('reportHash')}"
        f"{signoff_text}"
    )


def launch_smoke_report_audit_metadata(report: Dict[str, Any], operator_signoff: Dict[str, Any] | None = None) -> Dict[str, Any]:
    summary = report.get("summary") or {}
    metadata = {
        "report_type": report.get("reportType"),
        "report_hash": report.get("reportHash"),
        "target_launch_date": report.get("targetLaunchDate"),
        "launch_scope": report.get("launchScope"),
        "decision": report.get("decision"),
        "internal_go": bool(report.get("internalGo")),
        "formal_go": bool(report.get("formalGo")),
        "journey_ready": summary.get("journeyReady", 0),
        "journey_total": summary.get("journeyTotal", 0),
        "blocker_count": summary.get("blockerCount", 0),
        "warning_count": summary.get("warningCount", 0),
    }
    signoff = launch_operator_signoff_summary(operator_signoff)
    if signoff:
        metadata["operator_signoff"] = signoff
    return metadata


