def demo_accounts_disabled_by_policy() -> bool:
    """Production blocks demo login by default unless explicitly allowed."""
    if env_flag("EDOC_DISABLE_DEMO_ACCOUNTS", False):
        return True
    if is_production() and not env_flag("EDOC_ALLOW_DEMO_ACCOUNTS", False):
        return True
    return False


def demo_account_policy_status() -> Dict[str, bool]:
    explicit_disable = env_flag("EDOC_DISABLE_DEMO_ACCOUNTS", False)
    explicit_allow = env_flag("EDOC_ALLOW_DEMO_ACCOUNTS", False)
    safe_default = bool(is_production() and not explicit_allow)
    return {
        "disabled": demo_accounts_disabled_by_policy(),
        "explicitDisable": explicit_disable,
        "explicitAllow": explicit_allow,
        "safeDefault": safe_default,
        "production": is_production(),
    }


def demo_login_blocked(email: str, password: str) -> bool:
    return bool(
        demo_accounts_disabled_by_policy()
        and email.lower() in DEMO_LOGIN_EMAILS
        and password == "demo1234"
    )


def test_fixture_accounts_enabled() -> bool:
    return bool(
        not is_production()
        and (env_flag("EDOC_ENABLE_TEST_FIXTURES", False) or "unittest" in sys.modules)
    )


def remove_demo_accounts(conn: sqlite3.Connection) -> None:
    emails = sorted(DEMO_LOGIN_EMAILS)
    placeholders = ",".join("?" for _ in emails)
    user_ids = [
        row["id"]
        for row in conn.execute(
            f"""
            SELECT id
            FROM users
            WHERE lower(email) IN ({placeholders})
              AND COALESCE(account_source, '') <> 'finance'
            """,
            tuple(emails),
        ).fetchall()
    ]
    if not user_ids:
        return
    id_placeholders = ",".join("?" for _ in user_ids)
    conn.execute(f"DELETE FROM auth_sessions WHERE user_id IN ({id_placeholders})", tuple(user_ids))
    conn.execute(f"DELETE FROM module_account_links WHERE user_id IN ({id_placeholders})", tuple(user_ids))
    conn.execute(f"DELETE FROM seal_permissions WHERE user_id IN ({id_placeholders})", tuple(user_ids))
    conn.execute(f"DELETE FROM users WHERE id IN ({id_placeholders})", tuple(user_ids))


def go_live_audit() -> Dict[str, Any]:
    readiness = production_readiness()
    internal = internal_readiness()
    storage_service = storage_service_status()
    signing_service = signing_service_status()
    exchange_status = exchange_gateway_status()
    target_date = os.getenv("EDOC_TARGET_GO_LIVE_DATE", "").strip() or "2026-07-13"
    demo_policy = demo_account_policy_status()
    demo_accounts_disabled = demo_policy["disabled"]
    formal_exchange_ready = bool(exchange_status.get("formalConnection"))
    formal_blockers = [
        *[f"缺少正式環境變數：{name}" for name in readiness.get("missing", [])],
        *list(readiness.get("blockers", [])),
    ]
    if not formal_exchange_ready:
        formal_blockers.append("正式電子公文交換 provider 尚未開放；目前只能使用 mock provider 進行內部演練，不可送正式交換。")
    if is_production() and not demo_accounts_disabled:
        formal_blockers.append("正式站仍允許 demo / seed 帳號政策；上線前需設定 EDOC_DISABLE_DEMO_ACCOUNTS=true 並完成正式帳號匯入。")
    elif is_production() and demo_accounts_disabled and not demo_policy["explicitDisable"]:
        formal_blockers.append("正式站 demo 帳號已由安全預設阻擋，但仍需設定 EDOC_DISABLE_DEMO_ACCOUNTS=true 留存明確上線政策。")

    formal_go = not formal_blockers
    internal_go = bool(internal["ready"] and launch_scope() == "internal_official")
    internal_pilot_allowed = bool(internal_go or (not formal_go and exchange_status.get("provider") == "mock" and env_flag("EDOC_ALLOW_INTERNAL_PILOT", True)))
    decision = "GO" if formal_go else "INTERNAL_GO" if internal_go else "NO_GO"
    summary = (
        "正式上線可開放。"
        if formal_go
        else "內部正式使用可開放；政府 jAgent 正式交換與法定電子簽章維持關閉。"
        if internal_go
        else "不可上線；內部正式使用所需資料庫、私有儲存或帳號政策仍未齊備。"
    )
    categories = [
        {
            "key": "launch_scope",
            "name": "上線模式",
            "status": "pass" if internal_go or formal_go else "fail",
            "severity": "critical",
            "evidence": f"launchScope={launch_scope()}；internalGo={internal_go}；formalGo={formal_go}",
            "action": "下週一只開 EDOC_LAUNCH_SCOPE=internal_official；正式電子交換仍須等機關規格與人工核准。",
        },
        {
            "key": "internal_core",
            "name": "內部正式使用底座",
            "status": "pass" if internal["ready"] else "fail",
            "severity": "critical",
            "evidence": f"missing={','.join(internal['missing']) or 'none'}；blockers={len(internal['blockers'])}",
            "action": "補齊 Supabase、private storage、Seal Vault bucket、加密金鑰與正式帳號政策。",
        },
        {
            "key": "database",
            "name": "正式資料庫",
            "status": "pass" if internal["checks"]["supabase"] and internal["databaseMode"] == "supabase" else "fail",
            "severity": "critical",
            "evidence": f"databaseMode={internal['databaseMode']}",
            "action": "建立獨立 Supabase project，設定 SUPABASE_URL、SUPABASE_SERVICE_ROLE_KEY、EDOC_DB_MODE=supabase，套用 migrations 並驗證 RLS。",
        },
        {
            "key": "storage_av",
            "name": "檔案儲存與防毒",
            "status": "pass" if internal["checks"]["privateStorage"] else "warn",
            "severity": "critical",
            "evidence": f"mode={storage_service['mode']}；missing={','.join(storage_service['missing']) or 'none'}",
            "action": "內部上線須有 private object storage/Seal Vault；正式 AV endpoint 是 formal blocker，不擋 internal mode。",
        },
        {
            "key": "signature",
            "name": "正式簽章與憑證合法性",
            "status": "pass" if signing_service["ready"] else "warn",
            "severity": "critical",
            "evidence": f"mode={signing_service['mode']}；missing={','.join(signing_service['missing']) or 'none'}",
            "action": "內部 PDF 套印不宣稱法定電子簽章；HSM/TSA/OCSP/CRL 仍是 formal blocker。",
        },
        {
            "key": "exchange",
            "name": "jAgent / 電子交換正式 provider",
            "status": "pass" if formal_exchange_ready else "warn",
            "severity": "critical",
            "evidence": f"provider={exchange_status.get('provider')}；mode={exchange_status.get('mode')}",
            "action": "待機關提供 jAgent/API/SDK/封包規格並經人工核准後，才可啟用 RealExchangeProvider。",
        },
        {
            "key": "notifications",
            "name": "通知通道",
            "status": "pass" if internal["checks"]["smtp"] and internal["checks"]["line"] else "warn",
            "severity": "high",
            "evidence": f"emailProvider={internal['checks'].get('emailProvider')}；email={internal['checks']['smtp']}；line={internal['checks']['line']}",
            "action": "補齊 Resend 與 LINE 正式通道，跑通知測試與失敗重送測試。",
        },
        {
            "key": "monitoring",
            "name": "監控與值班告警",
            "status": "pass" if readiness["checks"]["monitoringWebhook"] and readiness["checks"]["cronSecret"] else "warn",
            "severity": "high",
            "evidence": f"monitoringWebhook={readiness['checks']['monitoringWebhook']}；cronSecret={readiness['checks']['cronSecret']}；sentry={readiness['checks']['sentry']}",
            "action": "設定 MONITORING_WEBHOOK_URL / SENTRY_DSN，並讓 Cron 每日執行 production monitoring check。",
        },
        {
            "key": "accounts",
            "name": "正式帳號與 demo 帳號關閉",
            "status": "pass" if internal["checks"]["demoAccountsDisabled"] or not is_production() else "fail",
            "severity": "critical" if is_production() else "medium",
            "evidence": f"demoAccountsDisabled={demo_accounts_disabled}; explicitDisable={demo_policy['explicitDisable']}; safeDefault={demo_policy['safeDefault']}",
            "action": "正式帳號匯入後設定 EDOC_DISABLE_DEMO_ACCOUNTS=true，避免測試帳密留在公開正式站。",
        },
    ]
    return {
        "decision": decision,
        "formalGo": formal_go,
        "internalGo": internal_go,
        "launchScope": launch_scope(),
        "internalPilotAllowed": internal_pilot_allowed,
        "summary": summary,
        "targetLaunchDate": target_date,
        "checkedAt": now(),
        "environment": DEPLOYMENT_ENV,
        "databaseMode": internal["databaseMode"],
        "formalBlockers": formal_blockers,
        "internalBlockers": internal.get("blockers", []),
        "warnings": [*internal.get("warnings", []), *readiness.get("warnings", [])],
        "categories": categories,
        "readiness": readiness,
        "internalReadiness": internal,
        "exchange": exchange_status,
        "nextActions": [
            "補齊內部正式使用所需 Supabase、private storage / Seal Vault、加密金鑰與帳號政策。",
            "正式站清楚標示：內部正式使用，政府電子交換未啟用。",
            "完成收文、發文、用印、寄發、內部派文與回文期限 smoke test。",
        ] if not internal_go and not formal_go else [
            "執行 production monitoring check。",
            "執行收文、發文、簽核、用印、寄發、內部派文、通知與下載權限 smoke test。",
            "保持 formal exchange disabled，待取得機關規格後再啟用 RealExchangeProvider。",
        ] if internal_go and not formal_go else [
            "執行 production monitoring check。",
            "執行收文、發文、簽核、用印、通知與備份還原 smoke test。",
            "將 go-live audit 報告保存到法遵營運紀錄。",
        ],
        "formalNextActions": [
            "先補 Supabase / Storage / AV / Signature / TSA / OCSP / CRL / Notification 正式設定。",
            "完成正式帳號匯入並關閉 demo 帳號政策。",
            "取得機關 jAgent/API/SDK/封包規格前，不開放正式電子交換送收。",
            "補齊後重新打 /api/production/go-live-audit，decision 必須為 GO 才能正式上線。",
        ] if not formal_go else [],
    }


