def launch_smoke_stamp_positions(
    seal_size_type: Any = "large_seal",
    seal_file: Dict[str, Any] | None = None,
) -> List[Dict[str, Any]]:
    profile = (
        company_seal_file_dimension_profile(seal_size_type, seal_file, current=True)
        if seal_file
        else company_seal_dimension_profile(seal_size_type)
    )
    width, height = canonical_company_seal_dimensions_pt(
        seal_size_type,
        render_width_mm=profile["width_mm"],
        render_height_mm=profile["height_mm"],
        allow_unspecified=True,
    )
    return [
        {"page": 1, "x": 420, "y": 640, "width": width, "height": height, "order_index": 1},
        {"page": 1, "x": 300, "y": 640, "width": width, "height": height, "order_index": 2},
    ]


def ensure_dirs() -> None:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    STORAGE_DIR.mkdir(parents=True, exist_ok=True)
    PRIVATE_SEAL_STORAGE_DIR.mkdir(parents=True, exist_ok=True)


LOCAL_SCHEMA_READY = False


def register_sqlite_functions(conn: sqlite3.Connection) -> None:
    """Register deterministic functions required by the local parity schema."""
    conn.create_function(
        "edoc_sha256",
        1,
        lambda value: hashlib.sha256(str(value or "").encode("utf-8")).hexdigest(),
        deterministic=True,
    )


def local_company_seal_position_triggers_sql() -> str:
    """Build parity guards whose authority is the selected immutable file version."""
    unbound_draft = f"""
      COALESCE(NEW.locked_seal_file_id, '') = ''
      AND COALESCE(NEW.locked_seal_sha256, '') = ''
      AND NEW.locked_render_width_pt IS NULL
      AND NEW.locked_render_height_pt IS NULL
      AND COALESCE(NEW.locked_dimension_policy_version, '') = ''
      AND EXISTS (
        SELECT 1
        FROM official_document_stamp_requests request
        JOIN official_documents document ON document.id = request.document_id
        WHERE request.id = NEW.request_id
          AND document.current_status = 'draft'
          AND request.status = 'draft'
          AND request.company_id = document.company_id
          AND request.company_id = seal.company_id
      )
      AND abs(
        NEW.width -
        (CASE seal.seal_size_type WHEN 'large_seal' THEN 30.0 WHEN 'small_seal' THEN 18.0 ELSE -1.0 END)
        * 72.0 / 25.4
      ) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
      AND abs(
        NEW.height -
        (CASE seal.seal_size_type WHEN 'large_seal' THEN 30.0 WHEN 'small_seal' THEN 18.0 ELSE -1.0 END)
        * 72.0 / 25.4
      ) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
    """
    valid_file = f"""
      SELECT 1
      FROM company_seal_files file
      WHERE file.seal_id = seal.id
        AND (
          (COALESCE(NEW.locked_seal_file_id, '') <> '' AND file.id = NEW.locked_seal_file_id)
          OR (
            COALESCE(NEW.locked_seal_file_id, '') = ''
            AND file.is_current = 1
            AND file.dimension_policy_version = '{EDOC_SEAL_DIMENSION_POLICY_VERSION}'
          )
        )
        AND file.dimension_validated = 1
        AND file.file_object_id IS NOT NULL
        AND file.pixel_width > 0
        AND file.pixel_height > 0
        AND file.render_width_mm > 0
        AND file.render_height_mm > 0
        AND abs(file.source_aspect_ratio - (1.0 * file.pixel_width / file.pixel_height)) <= 0.000001
        AND abs(
          ((1.0 * file.pixel_width / file.pixel_height) /
           (1.0 * file.render_width_mm / file.render_height_mm)) - 1.0
        ) <= {EDOC_SEAL_SOURCE_ASPECT_TOLERANCE}
        AND min(file.pixel_width, file.pixel_height) >=
            (max(file.render_width_mm, file.render_height_mm) / 25.4 * {EDOC_SEAL_CALIBRATION_DPI})
        AND (
          (
            file.dimension_policy_version = '{EDOC_SEAL_LEGACY_DIMENSION_POLICY_VERSION}'
            AND (
              (seal.seal_size_type = 'large_seal'
               AND abs(file.render_width_mm - 30.0) <= 0.000001
               AND abs(file.render_height_mm - 30.0) <= 0.000001)
              OR
              (seal.seal_size_type = 'small_seal'
               AND abs(file.render_width_mm - 18.0) <= 0.000001
               AND abs(file.render_height_mm - 18.0) <= 0.000001)
            )
          )
          OR
          (
            file.dimension_policy_version = '{EDOC_SEAL_DIMENSION_POLICY_VERSION}'
            AND abs(file.render_width_mm - file.render_height_mm) <= {EDOC_SEAL_PHYSICAL_SQUARE_TOLERANCE_MM}
            AND (
              (seal.seal_size_type = 'large_seal'
               AND file.render_width_mm BETWEEN 25.0 AND 35.0
               AND file.render_height_mm BETWEEN 25.0 AND 35.0)
              OR
              (seal.seal_size_type = 'small_seal'
               AND file.render_width_mm BETWEEN 15.0 AND 22.0
               AND file.render_height_mm BETWEEN 15.0 AND 22.0)
            )
          )
        )
        AND EXISTS (
          SELECT 1 FROM file_objects object
          WHERE object.id = file.file_object_id
            AND lower(COALESCE(object.scan_status, '')) IN ('已通過', 'clean', 'passed')
        )
        AND abs(NEW.width - (file.render_width_mm * 72.0 / 25.4)) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
        AND abs(NEW.height - (file.render_height_mm * 72.0 / 25.4)) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
        AND (
          (
            COALESCE(NEW.locked_seal_file_id, '') = ''
            AND COALESCE(NEW.locked_seal_sha256, '') = ''
            AND NEW.locked_render_width_pt IS NULL
            AND NEW.locked_render_height_pt IS NULL
            AND COALESCE(NEW.locked_dimension_policy_version, '') = ''
          )
          OR
          (
            COALESCE(NEW.locked_seal_file_id, '') <> ''
            AND NEW.locked_seal_sha256 = file.file_hash
            AND abs(NEW.locked_render_width_pt - (file.render_width_mm * 72.0 / 25.4)) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
            AND abs(NEW.locked_render_height_pt - (file.render_height_mm * 72.0 / 25.4)) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
            AND NEW.locked_dimension_policy_version = file.dimension_policy_version
          )
        )
    """
    invalid_transition_binding = f"""
      SELECT 1
      FROM official_document_stamp_requests request
      JOIN official_document_stamp_positions position ON position.request_id = request.id
      JOIN company_seals seal ON seal.id = position.seal_id
      WHERE request.document_id = NEW.id
        AND request.status = 'pending'
        AND (
          request.company_id <> NEW.company_id
          OR seal.company_id <> NEW.company_id
          OR COALESCE(position.locked_seal_file_id, '') = ''
          OR COALESCE(position.locked_seal_sha256, '') = ''
          OR position.locked_render_width_pt IS NULL
          OR position.locked_render_height_pt IS NULL
          OR COALESCE(position.locked_dimension_policy_version, '') = ''
          OR NOT EXISTS (
            SELECT 1
            FROM company_seal_files file
            JOIN file_objects object ON object.id = file.file_object_id
            WHERE file.id = position.locked_seal_file_id
              AND file.seal_id = position.seal_id
              AND file.file_hash = position.locked_seal_sha256
              AND file.dimension_policy_version = '{EDOC_SEAL_DIMENSION_POLICY_VERSION}'
              AND file.dimension_validated = 1
              AND file.pixel_width > 0
              AND file.pixel_height > 0
              AND abs(file.source_aspect_ratio - (1.0 * file.pixel_width / file.pixel_height)) <= 0.000001
              AND abs(file.render_width_mm - file.render_height_mm) <= {EDOC_SEAL_PHYSICAL_SQUARE_TOLERANCE_MM}
              AND lower(COALESCE(object.scan_status, '')) IN ('已通過', 'clean', 'passed')
              AND abs(position.width - (file.render_width_mm * 72.0 / 25.4)) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
              AND abs(position.height - (file.render_height_mm * 72.0 / 25.4)) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
              AND abs(position.locked_render_width_pt - (file.render_width_mm * 72.0 / 25.4)) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
              AND abs(position.locked_render_height_pt - (file.render_height_mm * 72.0 / 25.4)) <= {EDOC_SEAL_DIMENSION_TOLERANCE_PT}
              AND position.locked_dimension_policy_version = file.dimension_policy_version
          )
        )
    """
    unbound_cancel_position = """
      SELECT 1
      FROM official_document_stamp_requests request
      JOIN official_document_stamp_positions position ON position.request_id = request.id
      WHERE request.document_id = NEW.id
        AND (
          COALESCE(position.locked_seal_file_id, '') = ''
          OR COALESCE(position.locked_seal_sha256, '') = ''
          OR position.locked_render_width_pt IS NULL
          OR position.locked_render_height_pt IS NULL
          OR COALESCE(position.locked_dimension_policy_version, '') = ''
        )
    """
    return f"""
      DROP TRIGGER IF EXISTS trg_official_stamp_position_size_insert;
      DROP TRIGGER IF EXISTS trg_official_stamp_position_size_update;

      CREATE TRIGGER trg_official_stamp_position_size_insert
      BEFORE INSERT ON official_document_stamp_positions
      WHEN EXISTS (
        SELECT 1 FROM company_seals seal
        WHERE seal.id = NEW.seal_id
          AND NOT ({unbound_draft})
          AND NOT EXISTS ({valid_file})
      )
      BEGIN
        SELECT RAISE(ABORT, 'seal_size_locked');
      END;

      CREATE TRIGGER trg_official_stamp_position_size_update
      BEFORE UPDATE OF seal_id, width, height, locked_seal_file_id, locked_seal_sha256,
        locked_render_width_pt, locked_render_height_pt, locked_dimension_policy_version
      ON official_document_stamp_positions
      WHEN EXISTS (
        SELECT 1 FROM company_seals seal
        WHERE seal.id = NEW.seal_id
          AND NOT ({unbound_draft})
          AND NOT EXISTS ({valid_file})
      )
      BEGIN
        SELECT RAISE(ABORT, 'seal_size_locked');
      END;

      DROP TRIGGER IF EXISTS trg_official_document_seal_binding_transition;
      CREATE TRIGGER trg_official_document_seal_binding_transition
      BEFORE UPDATE OF current_status ON official_documents
      WHEN OLD.current_status = 'draft'
       AND NEW.current_status <> 'draft'
       AND NEW.requires_stamp = 1
       AND (
         (
           NEW.current_status = 'cancelled'
           AND EXISTS ({unbound_cancel_position})
         )
         OR (
           NEW.current_status <> 'cancelled'
           AND (
             NOT EXISTS (
               SELECT 1
               FROM official_document_stamp_requests request
               JOIN official_document_stamp_positions position ON position.request_id = request.id
               WHERE request.document_id = NEW.id
                 AND request.status = 'pending'
             )
             OR EXISTS ({invalid_transition_binding})
           )
         )
       )
      BEGIN
        SELECT RAISE(ABORT, 'official_seal_binding_required_before_submit');
      END;
    """


def ensure_local_company_seal_file_integrity(conn: sqlite3.Connection) -> None:
    """Install SQLite parity guards without rewriting audit-significant rows."""
    table_exists = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'company_seal_files'"
    ).fetchone()
    if not table_exists:
        return
    for column, definition in {
        "pixel_width": "INTEGER",
        "pixel_height": "INTEGER",
        "source_aspect_ratio": "REAL",
        "render_width_mm": "REAL",
        "render_height_mm": "REAL",
        "dimension_policy_version": "TEXT",
        "dimension_validated": "INTEGER NOT NULL DEFAULT 0",
    }.items():
        ensure_column(conn, "company_seal_files", column, definition)
    stamp_positions_exists = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'official_document_stamp_positions'"
    ).fetchone()
    if stamp_positions_exists:
        ensure_column(conn, "official_document_stamp_positions", "locked_render_width_pt", "REAL")
        ensure_column(conn, "official_document_stamp_positions", "locked_render_height_pt", "REAL")
        ensure_column(conn, "official_document_stamp_positions", "locked_dimension_policy_version", "TEXT")
    # A v1 row remains immutable evidence for locked historical cases, but it
    # may not be selected by a new draft or submission after the v2 rollout.
    conn.execute(
        "UPDATE company_seal_files SET is_current = 0 "
        "WHERE is_current = 1 AND COALESCE(dimension_policy_version, '') <> ?",
        (EDOC_SEAL_DIMENSION_POLICY_VERSION,),
    )
    conn.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS ux_company_seal_files_version "
        "ON company_seal_files(seal_id, version)"
    )
    conn.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS ux_company_seal_files_one_current "
        "ON company_seal_files(seal_id) WHERE is_current = 1"
    )
    conn.executescript(
        """
        CREATE TRIGGER IF NOT EXISTS trg_company_seal_file_version_immutable
        BEFORE UPDATE OF seal_id, file_object_id, file_storage_key, file_name, file_mime_type,
          file_size, file_hash, pixel_width, pixel_height, source_aspect_ratio,
          render_width_mm, render_height_mm, dimension_policy_version,
          dimension_validated, version, uploaded_by, uploaded_at
        ON company_seal_files
        BEGIN
          SELECT RAISE(ABORT, 'company_seal_file_version_immutable');
        END;

        CREATE TRIGGER IF NOT EXISTS trg_seal_usage_request_evidence_locked
        BEFORE UPDATE OF seal_id, company_id, document_id, stamp_positions_json, metadata_json
        ON seal_usage_requests
        WHEN OLD.status <> 'draft' OR NEW.status <> 'draft'
        BEGIN
          SELECT RAISE(ABORT, 'seal_usage_request_evidence_locked');
        END;
        """
    )
    if stamp_positions_exists:
        # Existing databases may still contain the old fixed 30/18 mm guards.
        # Always replace them so draft and locked positions follow file metadata.
        conn.executescript(local_company_seal_position_triggers_sql())


def ensure_local_official_dispatch_integrity(conn: sqlite3.Connection) -> None:
    """Refuse ambiguous legacy dispatch data before enforcing one route per case."""
    table_exists = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'official_document_dispatch_records'"
    ).fetchone()
    if not table_exists:
        return
    duplicate = conn.execute(
        """
        SELECT document_id, COUNT(*) AS row_count
        FROM official_document_dispatch_records
        GROUP BY document_id
        HAVING COUNT(*) > 1
        ORDER BY document_id
        LIMIT 1
        """
    ).fetchone()
    if duplicate:
        raise RuntimeError(
            f"official_dispatch_duplicate_records_require_manual_resolution:{duplicate['document_id']}"
        )
    conn.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS ux_official_dispatch_records_document "
        "ON official_document_dispatch_records(document_id)"
    )


def connect() -> sqlite3.Connection:
    global LOCAL_SCHEMA_READY
    ensure_dirs()
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    register_sqlite_functions(conn)
    conn.execute("PRAGMA foreign_keys = ON")
    if not LOCAL_SCHEMA_READY:
        conn.executescript(SCHEMA)
        ensure_local_company_seal_file_integrity(conn)
        ensure_local_official_dispatch_integrity(conn)
        conn.commit()
        LOCAL_SCHEMA_READY = True
    return conn


def row_to_dict(row: sqlite3.Row) -> Dict[str, Any]:
    return {key: row[key] for key in row.keys()}


def audit_severity(event_type: str, result: str = "success") -> str:
    if result == "denied" or event_type in LOGGING_CRITICAL_EVENTS:
        return "critical"
    if result == "failed":
        return "warning"
    return "info"


def normalize_audit_event_type(event_type: str | None, action: str) -> str:
    if event_type in LOGGING_AUDIT_EVENT_TYPES:
        return str(event_type)
    if "登入" in action:
        return "login"
    if "登出" in action:
        return "logout"
    if "匯出" in action:
        return "export"
    if "刪除" in action or "停用" in action:
        return "delete"
    if "退回" in action or "拒絕" in action:
        return "reject"
    if "核准" in action or "簽核" in action or "覆核" in action:
        return "approve"
    if "分派" in action or "指派" in action:
        return "assign"
    if "權限" in action or "角色" in action:
        return "permission_change"
    if "敏感" in action or "密件" in action or "下載" in action:
        return "sensitive_access"
    return "submit"


def log_audit(
    conn: sqlite3.Connection,
    actor: str,
    action: str,
    target_type: str = "",
    target_id: str = "",
    detail: str = "",
    *,
    event_type: str | None = None,
    result: str = "success",
    module_code: str = "",
    resource_type: str | None = None,
    resource_id: str | None = None,
    data_scope: str | None = None,
    actor_user_id: str = "",
    actor_email: str = "",
    actor_roles: List[str] | None = None,
    target_user_id: str = "",
    target_email: str = "",
    reason: str = "",
    request_id: str = "",
    before_snapshot: Dict[str, Any] | None = None,
    after_snapshot: Dict[str, Any] | None = None,
    metadata: Dict[str, Any] | None = None,
) -> None:
    safe_detail = redact_text(detail) if isinstance(detail, str) else json.dumps(redact_sensitive(detail), ensure_ascii=False)
    normalized_event_type = normalize_audit_event_type(event_type, action)
    normalized_result = result if result in {"success", "failed", "denied"} else "success"
    normalized_scope = data_scope if data_scope in LOGGING_DATA_SCOPES else None
    metadata_payload = {"legacy_detail": safe_detail, **(metadata or {})}
    chain_segment = "sqlite-v2"
    conn.execute(
        "INSERT OR IGNORE INTO audit_chain_state (chain_segment, next_sequence, last_hash) VALUES (?, 0, 'GENESIS')",
        (chain_segment,),
    )
    conn.execute(
        "UPDATE audit_chain_state SET next_sequence = next_sequence + 1 WHERE chain_segment = ?",
        (chain_segment,),
    )
    state = conn.execute(
        "SELECT next_sequence, last_hash FROM audit_chain_state WHERE chain_segment = ?",
        (chain_segment,),
    ).fetchone()
    audit_row = {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": actor, "action": action, "target_type": target_type, "target_id": target_id,
        "ip": "127.0.0.1", "device": "backend", "detail": safe_detail,
        "event_type": normalized_event_type,
        "severity": audit_severity(normalized_event_type, normalized_result),
        "result": normalized_result, "module_code": module_code or target_type or "edoc",
        "resource_type": resource_type or target_type or None,
        "resource_id": resource_id or target_id or None, "data_scope": normalized_scope,
        "actor_user_id": actor_user_id, "actor_email": actor_email,
        "actor_roles_json": json.dumps(actor_roles or ([actor] if actor else []), ensure_ascii=False),
        "target_user_id": target_user_id, "target_email": target_email, "reason": reason,
        "request_id": request_id or f"req_{secrets.token_hex(8)}",
        "before_snapshot_json": json.dumps(redact_sensitive(before_snapshot or {}), ensure_ascii=False),
        "after_snapshot_json": json.dumps(redact_sensitive(after_snapshot or {}), ensure_ascii=False),
        "metadata_json": json.dumps(redact_sensitive(metadata_payload), ensure_ascii=False),
        "chain_sequence": int(state["next_sequence"]), "chain_segment": chain_segment,
        "previous_hash": state["last_hash"], "chain_status": "verified-v2", "created_at": now(),
    }
    audit_row["entry_hash"] = stable_json_hash(audit_row)
    conn.execute(
        """
        INSERT INTO audit_logs (
          id, actor, action, target_type, target_id, ip, device, detail,
          event_type, severity, result, module_code, resource_type, resource_id, data_scope,
          actor_user_id, actor_email, actor_roles_json, target_user_id, target_email,
          reason, request_id, before_snapshot_json, after_snapshot_json, metadata_json,
          chain_sequence, chain_segment, previous_hash, entry_hash, chain_status, created_at
        ) VALUES (
          :id, :actor, :action, :target_type, :target_id, :ip, :device, :detail,
          :event_type, :severity, :result, :module_code, :resource_type, :resource_id, :data_scope,
          :actor_user_id, :actor_email, :actor_roles_json, :target_user_id, :target_email,
          :reason, :request_id, :before_snapshot_json, :after_snapshot_json, :metadata_json,
          :chain_sequence, :chain_segment, :previous_hash, :entry_hash, :chain_status, :created_at
        )
        """,
        audit_row,
    )
    conn.execute(
        "UPDATE audit_chain_state SET last_hash = ? WHERE chain_segment = ?",
        (audit_row["entry_hash"], chain_segment),
    )


def log_permission_change(
    conn: sqlite3.Connection,
    actor: str,
    target_user_id: str,
    target_email: str,
    before_snapshot: Dict[str, Any],
    after_snapshot: Dict[str, Any],
    reason: str,
    actor_roles: List[str] | None = None,
) -> None:
    log_audit(
        conn,
        actor,
        "權限異動",
        "user_role",
        target_user_id,
        reason,
        event_type="permission_change",
        result="success",
        module_code="system_permissions",
        resource_type="user_role",
        resource_id=target_user_id,
        data_scope="custom",
        actor_roles=actor_roles or [actor],
        target_user_id=target_user_id,
        target_email=target_email,
        reason=reason,
        before_snapshot=before_snapshot,
        after_snapshot=after_snapshot,
        metadata={"source": "edoc_rbac"},
    )


def validate_local_audit_chain(conn: sqlite3.Connection, segment: str = "sqlite-v2") -> Dict[str, Any]:
    rows = [row_to_dict(row) for row in conn.execute(
        "SELECT * FROM audit_logs WHERE chain_segment = ? ORDER BY chain_sequence",
        (segment,),
    ).fetchall()]
    expected_previous = "GENESIS"
    errors: List[Dict[str, Any]] = []
    for expected_sequence, row in enumerate(rows, start=1):
        stored_hash = str(row.pop("entry_hash", "") or "")
        valid = (
            int(row.get("chain_sequence") or 0) == expected_sequence
            and row.get("previous_hash") == expected_previous
            and stable_json_hash(row) == stored_hash
        )
        if not valid:
            errors.append({"id": row.get("id"), "sequence": row.get("chain_sequence")})
        expected_previous = stored_hash
    legacy_count = conn.execute(
        "SELECT COUNT(*) AS count FROM audit_logs WHERE chain_segment IS NULL OR chain_status = 'legacy-unverified'"
    ).fetchone()["count"]
    return {
        "ok": not errors,
        "segment": segment,
        "verified_entry_count": len(rows),
        "legacy_unverified_count": int(legacy_count),
        "errors": errors,
        "head_hash": expected_previous,
    }


def ensure_column(conn: sqlite3.Connection, table: str, column: str, definition: str) -> None:
    columns = {row["name"] for row in conn.execute(f"PRAGMA table_info({table})").fetchall()}
    if column not in columns:
        conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")


