def mask_notification_credential(env_key_name: str) -> str:
    masked = []
    for name in env_key_name.split(","):
        name = name.strip()
        value = os.getenv(name, "").strip()
        if not name:
            continue
        if not value:
            masked.append(f"{name}=未設定")
        elif len(value) <= 8:
            masked.append(f"{name}=****")
        else:
            masked.append(f"{name}={value[:4]}...{value[-4:]}")
    return "；".join(masked)


