def role_permission_codes(conn: sqlite3.Connection, role_name: str) -> List[str]:
    rows = conn.execute(
        """
        SELECT p.code
        FROM roles r
        JOIN role_permissions rp ON rp.role_id = r.id
        JOIN permissions p ON p.id = rp.permission_id
        WHERE r.name = ?
        ORDER BY p.category, p.code
        """,
        (role_name,),
    ).fetchall()
    codes = [row["code"] for row in rows]
    fallback = ROLE_PERMISSION_FALLBACKS.get(role_name, [])
    return sorted(set(codes) | set(fallback))


def session_permissions(session: Dict[str, Any] | None) -> set[str]:
    return set(session.get("permissions") or []) if session else set()


def session_has_any_permission(session: Dict[str, Any] | None, permissions: List[str]) -> bool:
    available = session_permissions(session)
    return any(permission in available for permission in permissions)


OPERATIONS_MAINTENANCE_PERMISSIONS = ["settings.system_manage", "settings.manage"]


def is_operations_maintenance_endpoint(method: str, parts: List[str]) -> bool:
    """Identify notification/scheduler operations that must be admin-only."""
    if method == "GET":
        return parts == ["notifications", "gateway-status"]
    if method != "POST":
        return False
    if parts in (
        ["production", "monitoring", "check"],
        ["backup", "restore-drill"],
        ["compliance", "attest"],
        ["jobs", "run-due"],
        ["jobs", "run-all"],
        ["notifications", "sync"],
        ["notifications", "credentials", "validate"],
        ["notifications", "send"],
        ["notifications", "test"],
        ["notifications", "retry-failed"],
        ["notifications", "push-inbox"],
    ):
        return True
    return len(parts) == 3 and parts[0] == "jobs" and parts[2] == "run"


def can_manage_operations_maintenance(session: Dict[str, Any] | None) -> bool:
    return session_has_any_permission(session, OPERATIONS_MAINTENANCE_PERMISSIONS)


