# Generic `/api/<table>` routes are retained only for small, read-only lookup
# registries used by the shell. Workflow, identity, file, seal-vault, audit,
# notification and exchange state must go through dedicated scoped endpoints.
GENERIC_API_READ_ONLY_TABLES = frozenset({
    "companies",
    "company_registry",
    "department_registry",
    "seal_type_registry",
    "seal_reference_options",
})


def can_read_table(session: Dict[str, Any] | None, table: str) -> bool:
    permissions = TABLE_READ_PERMISSIONS.get(table)
    return bool(session) if not permissions else session_has_any_permission(session, permissions)


def can_write_table(session: Dict[str, Any] | None, table: str) -> bool:
    permissions = TABLE_WRITE_PERMISSIONS.get(table)
    return bool(session) if not permissions else session_has_any_permission(session, permissions)


def can_access_generic_table_api(
    session: Dict[str, Any] | None,
    table: str,
    *,
    write: bool = False,
) -> bool:
    """Fail closed for generic CRUD; business tables use scoped APIs only."""
    if write or table not in GENERIC_API_READ_ONLY_TABLES:
        return False
    return can_read_table(session, table)


def document_scope_clause(user: Dict[str, Any] | sqlite3.Row | None) -> Tuple[str, List[Any]]:
    if not user:
        return "1 = 0", []
    role = user["role"] if isinstance(user, sqlite3.Row) else user.get("role", "")
    unit = user["unit"] if isinstance(user, sqlite3.Row) else user.get("unit", "")
    name = user["name"] if isinstance(user, sqlite3.Row) else user.get("name", "")
    if role in {"執行長", "董事會", "股東"}:
        return "", []
    acl_clause = """
      EXISTS (
        SELECT 1 FROM document_acl da
        WHERE da.document_id = documents.id
          AND da.can_view = 1
          AND (
            (da.principal_type = 'role' AND da.principal_id = ?)
            OR (da.principal_type = 'unit' AND da.principal_id = ?)
            OR (da.principal_type = 'user' AND da.principal_id = ?)
          )
          AND (da.expires_at IS NULL OR da.expires_at = '' OR da.expires_at > ?)
      )
    """
    acl_params = [role, unit, name, now()]
    if role == "總務":
        return f"(((owner = ? OR department = ?) AND owner <> ?) OR {acl_clause})", ["總務", "總務", "行政部主任", *acl_params]
    if role == "行政部主任":
        return f"(((owner = ? OR department IN (?, ?)) AND owner <> ?) OR {acl_clause})", ["行政部主任", "行政部", "總管理處", "總務", *acl_params]
    if role in {"人資", "會計", "業務助理", "主任", "主管", "員工"}:
        return f"((owner IN (?, ?) OR department IN (?, ?)) OR {acl_clause})", [role, name, role, unit, *acl_params]
    if role == "外部檢核單位":
        return acl_clause, acl_params
    return "1 = 0", []


def scoped_document_where(session: Dict[str, Any] | None, extra: List[str] | None = None) -> Tuple[str, List[Any]]:
    where = list(extra or [])
    params: List[Any] = []
    scope_clause, scope_params = document_scope_clause(session.get("user") if session else None)
    if scope_clause:
        where.append(scope_clause)
        params.extend(scope_params)
    return (" WHERE " + " AND ".join(where)) if where else "", params


def scoped_document_rows(conn: sqlite3.Connection, query: Dict[str, List[str]], session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    where: List[str] = []
    params: List[Any] = []
    if "status" in query:
        where.append("status = ?")
        params.append(query["status"][0])
    if "direction" in query:
        where.append("direction = ?")
        params.append(query["direction"][0])
    scope_clause, scope_params = document_scope_clause(session.get("user") if session else None)
    if scope_clause:
        where.append(scope_clause)
        params.extend(scope_params)
    sql = "SELECT * FROM documents"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY rowid DESC LIMIT 500"
    return [row_to_dict(row) for row in conn.execute(sql, params).fetchall()]


def search_like_clause(columns: List[str], term: str) -> Tuple[str, List[Any]]:
    like = f"%{term}%"
    return "(" + " OR ".join(f"COALESCE({column}, '') LIKE ?" for column in columns) + ")", [like] * len(columns)


def unified_search(conn: sqlite3.Connection, query: Dict[str, List[str]], session: Dict[str, Any] | None) -> Dict[str, Any]:
    term = (query.get("q") or query.get("term") or [""])[0].strip()
    category = (query.get("category") or query.get("type") or ["all"])[0]
    status = (query.get("status") or [""])[0].strip()
    limit = min(int((query.get("limit") or ["80"])[0] or 80), 200)
    if not term and not status:
        return {"query": term, "category": category, "count": 0, "results": []}

    specs = [
        ("documents", "公文", "documents", ["id", "doc_no", "agency_name", "agency_code", "subject", "body", "status", "owner", "department"], "status"),
        ("contracts", "合約", "contracts", ["id", "contract_no", "company_name", "contract_type", "title", "counterparty", "owner", "department", "status", "summary", "risk_note"], "status"),
        ("contract_approvals", "合約簽核", "contract_approvals", ["id", "contract_id", "step_name", "role", "status", "approver", "comment"], "status"),
        ("attachments", "附件", "attachments", ["id", "document_id", "file_name", "version", "mime_type", "sha256", "scan_status", "storage_key"], "scan_status"),
        ("attachment_security", "附件安全", "attachment_security", ["id", "attachment_id", "document_id", "file_name", "file_ext", "scan_status", "mask_status", "confidential_level", "allowed_roles", "watermark_status", "quarantine_reason"], "scan_status"),
        ("exchange_tasks", "交換任務", "exchange_tasks", ["id", "document_id", "direction", "target_agency", "status", "package_id"], "status"),
        ("exchange_events", "交換事件", "exchange_events", ["id", "task_id", "document_id", "event_type", "message", "payload_json"], "event_type"),
        ("notifications", "通知", "notifications", ["id", "type", "title", "target_role", "target_email", "channel", "status", "priority", "source", "body", "delivery_receipt"], "status"),
        ("audit_logs", "稽核紀錄", "audit_logs", ["id", "actor", "action", "target_type", "target_id", "detail"], "action"),
        ("file_access_logs", "檔案存取", "file_access_logs", ["id", "attachment_id", "file_object_id", "document_id", "actor", "action", "result", "detail", "watermark_text"], "result"),
    ]
    results: List[Dict[str, Any]] = []
    for table_key, label, table, columns, status_column in specs:
        if category not in {"all", table_key, label}:
            continue
        if not can_read_table(session, table):
            continue
        where: List[str] = []
        params: List[Any] = []
        if term:
            clause, clause_params = search_like_clause(columns, term)
            where.append(clause)
            params.extend(clause_params)
        if status:
            where.append(f"COALESCE({status_column}, '') LIKE ?")
            params.append(f"%{status}%")
        if table == "documents":
            scope_clause, scope_params = document_scope_clause(session.get("user") if session else None)
            if scope_clause:
                where.append(scope_clause)
                params.extend(scope_params)
        sql = f"SELECT * FROM {table}"
        if where:
            sql += " WHERE " + " AND ".join(where)
        sql += " ORDER BY rowid DESC LIMIT ?"
        rows = conn.execute(sql, (*params, limit)).fetchall()
        for row in rows:
            data = row_to_dict(row)
            title = data.get("doc_no") or data.get("contract_no") or data.get("file_name") or data.get("title") or data.get("action") or data.get("event_type") or data.get("id")
            subtitle = data.get("subject") or data.get("counterparty") or data.get("step_name") or data.get("agency_name") or data.get("target_agency") or data.get("body") or data.get("detail") or data.get("message") or ""
            results.append({
                "id": data.get("id"),
                "category": label,
                "table": table_key,
                "title": title,
                "subtitle": subtitle,
                "status": data.get("status") or data.get("scan_status") or data.get("result") or data.get("event_type") or "",
                "createdAt": data.get("created_at") or data.get("updated_at") or data.get("last_accessed_at") or "",
                "record": data,
            })
    results.sort(key=lambda item: item.get("createdAt") or "", reverse=True)
    return {"query": term, "category": category, "count": len(results[:limit]), "results": results[:limit]}


def search_pagination(query: Dict[str, List[str]]) -> Tuple[int, int]:
    try:
        page = max(1, int((query.get("page") or ["1"])[0] or 1))
        page_size = max(1, min(100, int((query.get("page_size") or query.get("limit") or ["50"])[0] or 50)))
    except (TypeError, ValueError):
        raise ValueError("search_pagination_invalid")
    return page, page_size


def canonical_search_filters(query: Dict[str, List[str]]) -> Tuple[str, str, str]:
    date_from = str((query.get("date_from") or query.get("from") or [""])[0] or "").strip()
    date_to = str((query.get("date_to") or query.get("to") or [""])[0] or "").strip()
    company_id = str((query.get("company_id") or query.get("company") or [""])[0] or "").strip()
    for value in (date_from, date_to):
        if value and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
            raise ValueError("search_date_filter_invalid")
    if date_from and date_to and date_from > date_to:
        raise ValueError("search_date_range_invalid")
    if len(company_id) > 120:
        raise ValueError("search_company_filter_invalid")
    return date_from, date_to, company_id


def canonical_search_date_matches(item: Dict[str, Any], date_from: str, date_to: str) -> bool:
    value = str(item.get("created_at") or item.get("createdAt") or "")[:10]
    return (not date_from or value >= date_from) and (not date_to or value <= date_to)


def canonical_records_search(
    conn: sqlite3.Connection,
    query: Dict[str, List[str]],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = official_session_user(session)
    term = str((query.get("q") or query.get("term") or [""])[0] or "").strip()
    status = str((query.get("status") or [""])[0] or "").strip()
    category = str((query.get("category") or query.get("type") or ["all"])[0] or "all").strip()
    if len(term) > 200:
        raise ValueError("search_term_too_long")
    page, page_size = search_pagination(query)
    date_from, date_to, company_id = canonical_search_filters(query)
    like = f"%{term}%"
    status_like = f"%{status}%"
    results: List[Dict[str, Any]] = []

    if category in {"all", "official_documents", "發文", "公文"} and can_read_table(session, "official_documents"):
        where = [
            """
            (
              d.applicant_id = ?
              OR EXISTS (SELECT 1 FROM official_document_approval_steps s WHERE s.document_id = d.id AND s.approver_user_id = ?)
              OR EXISTS (SELECT 1 FROM approval_step_actor_snapshots a WHERE a.source_id = d.id AND a.approver_user_id = ?)
              OR (d.company_id = ? AND ? = 1)
            )
            """
        ]
        params: List[Any] = [
            user["id"], user["id"], user["id"], user.get("company_id") or "",
            1 if session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]) else 0,
        ]
        if term:
            where.append(
                """
                (COALESCE(d.id,'') LIKE ? OR COALESCE(d.title,'') LIKE ? OR COALESCE(d.subject,'') LIKE ?
                 OR COALESCE(d.recipient,'') LIKE ? OR COALESCE(d.applicant_name,'') LIKE ?
                 OR COALESCE(d.handler_name,'') LIKE ? OR COALESCE(d.request_reason,'') LIKE ?
                 OR EXISTS (SELECT 1 FROM official_document_files f WHERE f.document_id = d.id AND COALESCE(f.file_name,'') LIKE ?))
                """
            )
            params.extend([like] * 8)
        if status:
            where.append("COALESCE(d.current_status,'') LIKE ?")
            params.append(status_like)
        if date_from:
            where.append("substr(COALESCE(d.created_at,''), 1, 10) >= ?")
            params.append(date_from)
        if date_to:
            where.append("substr(COALESCE(d.created_at,''), 1, 10) <= ?")
            params.append(date_to)
        if company_id:
            where.append("d.company_id = ?")
            params.append(company_id)
        for row in conn.execute(
            "SELECT d.* FROM official_documents d WHERE " + " AND ".join(where) + " ORDER BY d.created_at DESC",
            params,
        ).fetchall():
            item = row_to_dict(row)
            results.append({
                "id": item["id"], "category": "發文", "table": "official_documents",
                "title": item.get("title") or item.get("subject") or item["id"],
                "subtitle": item.get("recipient") or item.get("request_reason") or "",
                "status": item.get("current_status") or "", "createdAt": item.get("created_at") or "",
                "record": {key: item.get(key) for key in ("id", "company_id", "title", "subject", "recipient", "applicant_name", "current_status", "current_step", "created_at", "updated_at")},
            })

    if category in {"all", "inbound_documents", "收文", "公文"} and can_read_table(session, "inbound_documents"):
        where = []
        params = []
        if not session_has_any_permission(session, ["official_documents.receive", "official_documents.all_records", "official_documents.all_todo"]):
            where.append("i.assignee_user_id = ?")
            params.append(user["id"])
        if term:
            where.append(
                """
                (COALESCE(i.id,'') LIKE ? OR COALESCE(i.receive_no,'') LIKE ? OR COALESCE(i.sender_name,'') LIKE ?
                 OR COALESCE(i.subject,'') LIKE ? OR COALESCE(i.assignee_name,'') LIKE ?
                 OR EXISTS (SELECT 1 FROM inbound_document_attachments a WHERE a.inbound_document_id = i.id AND COALESCE(a.file_name,'') LIKE ?))
                """
            )
            params.extend([like] * 6)
        if status:
            where.append("COALESCE(i.status,'') LIKE ?")
            params.append(status_like)
        if date_from:
            where.append("substr(COALESCE(i.created_at,''), 1, 10) >= ?")
            params.append(date_from)
        if date_to:
            where.append("substr(COALESCE(i.created_at,''), 1, 10) <= ?")
            params.append(date_to)
        sql = "SELECT i.* FROM inbound_documents i"
        if where:
            sql += " WHERE " + " AND ".join(where)
        sql += " ORDER BY i.created_at DESC"
        for row in conn.execute(sql, params).fetchall():
            item = row_to_dict(row)
            results.append({
                "id": item["id"], "category": "收文", "table": "inbound_documents",
                "title": item.get("receive_no") or item["id"], "subtitle": item.get("subject") or item.get("sender_name") or "",
                "status": item.get("status") or "", "createdAt": item.get("created_at") or "",
                "record": {key: item.get(key) for key in ("id", "receive_no", "sender_name", "subject", "assignee_name", "status", "due_at", "created_at", "updated_at")},
            })

    if category in {"all", "internal_dispatches", "派文"} and can_read_table(session, "internal_dispatches"):
        where = [
            """
            (d.sender_user_id = ? OR EXISTS (
              SELECT 1 FROM internal_dispatch_recipients r
              WHERE r.dispatch_id = d.id AND r.recipient_user_id = ?
            ) OR ? = 1)
            """
        ]
        params = [user["id"], user["id"], 1 if session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]) else 0]
        if term:
            where.append("(COALESCE(d.id,'') LIKE ? OR COALESCE(d.title,'') LIKE ? OR COALESCE(d.subject,'') LIKE ? OR COALESCE(d.sender_name,'') LIKE ?)")
            params.extend([like] * 4)
        if status:
            where.append("COALESCE(d.status,'') LIKE ?")
            params.append(status_like)
        if date_from:
            where.append("substr(COALESCE(d.created_at,''), 1, 10) >= ?")
            params.append(date_from)
        if date_to:
            where.append("substr(COALESCE(d.created_at,''), 1, 10) <= ?")
            params.append(date_to)
        for row in conn.execute(
            "SELECT d.* FROM internal_dispatches d WHERE " + " AND ".join(where) + " ORDER BY d.created_at DESC",
            params,
        ).fetchall():
            item = row_to_dict(row)
            results.append({
                "id": item["id"], "category": "派文", "table": "internal_dispatches",
                "title": item.get("title") or item["id"], "subtitle": item.get("subject") or "",
                "status": item.get("status") or "", "createdAt": item.get("created_at") or "",
                "record": {key: item.get(key) for key in ("id", "official_document_id", "inbound_document_id", "title", "subject", "sender_name", "reply_status", "status", "due_at", "created_at", "updated_at")},
            })

    results.sort(key=lambda item: str(item.get("createdAt") or ""), reverse=True)
    total = len(results)
    start = (page - 1) * page_size
    page_results = results[start:start + page_size]
    return {
        "query": term, "category": category, "status": status,
        "date_from": date_from, "date_to": date_to, "company_id": company_id,
        "count": len(page_results), "total": total, "page": page, "page_size": page_size,
        "has_more": start + page_size < total, "results": page_results,
    }


def _supabase_search_rows(
    table: str,
    *,
    columns: List[str],
    term: str,
    status_column: str,
    status: str,
    select: str,
) -> List[Dict[str, Any]]:
    safe_term = re.sub(r"[*,()\\%_]", " ", term).strip()
    safe_status = re.sub(r"[*,()\\%_]", " ", status).strip()
    rows: List[Dict[str, Any]] = []
    offset = 0
    while True:
        params: Dict[str, str] = {"select": select, "limit": "1000", "offset": str(offset), "order": "created_at.desc"}
        if safe_term:
            params["or"] = "(" + ",".join(f"{column}.ilike.*{safe_term}*" for column in columns) + ")"
        if safe_status:
            params[status_column] = f"ilike.*{safe_status}*"
        batch = supabase_request("GET", f"{table}?{urllib.parse.urlencode(params)}")
        if not isinstance(batch, list):
            raise RuntimeError("supabase_search_invalid_response")
        rows.extend(batch)
        if len(batch) < 1000:
            break
        offset += len(batch)
        if offset > 100_000:
            raise ValueError("search_result_limit_exceeded")
    return rows


def _supabase_attachment_parent_ids(
    table: str,
    parent_column: str,
    term: str,
) -> set[str]:
    """Find canonical records by attachment filename without a client cap."""
    safe_term = re.sub(r"[*,()\\%_]", " ", term).strip()
    if not safe_term:
        return set()
    result: set[str] = set()
    offset = 0
    while True:
        params = {
            "select": parent_column,
            "file_name": f"ilike.*{safe_term}*",
            "limit": "1000",
            "offset": str(offset),
        }
        batch = supabase_request("GET", f"{table}?{urllib.parse.urlencode(params)}")
        if not isinstance(batch, list):
            raise RuntimeError("supabase_search_attachment_invalid_response")
        result.update(str(item.get(parent_column) or "") for item in batch if item.get(parent_column))
        if len(batch) < 1000:
            break
        offset += len(batch)
        if offset > 100_000:
            raise ValueError("search_result_limit_exceeded")
    return result


def supabase_canonical_records_search(
    query: Dict[str, List[str]],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    term = str((query.get("q") or query.get("term") or [""])[0] or "").strip()
    status = str((query.get("status") or [""])[0] or "").strip()
    category = str((query.get("category") or query.get("type") or ["all"])[0] or "all").strip()
    if len(term) > 200:
        raise ValueError("search_term_too_long")
    page, page_size = search_pagination(query)
    date_from, date_to, company_id = canonical_search_filters(query)
    results: List[Dict[str, Any]] = []

    if category in {"all", "official_documents", "發文", "公文"} and can_read_table(session, "official_documents"):
        official_rows = _supabase_search_rows(
            "official_documents", columns=["id", "title", "subject", "recipient", "applicant_name", "handler_name", "request_reason"],
            term=term, status_column="current_status", status=status,
            select="id,company_id,title,subject,recipient,applicant_id,applicant_name,handler_name,current_status,current_step,created_at,updated_at",
        )
        if term:
            known_ids = {str(item.get("id") or "") for item in official_rows}
            for document_id in _supabase_attachment_parent_ids("official_document_files", "document_id", term):
                if document_id not in known_ids:
                    attached_document = supabase_get("official_documents", document_id)
                    if attached_document:
                        official_rows.append(attached_document)
                        known_ids.add(document_id)
        for item in official_rows:
            if company_id and item.get("company_id") != company_id:
                continue
            if not canonical_search_date_matches(item, date_from, date_to):
                continue
            steps = supabase_official_document_steps(item["id"])
            snapshots = supabase_official_document_actor_snapshots(item["id"])
            is_participant = user["id"] in official_document_participant_ids(item, steps, snapshots)
            if not is_participant and not (
                item.get("company_id") == user.get("company_id")
                and session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"])
            ):
                continue
            results.append({
                "id": item["id"], "category": "發文", "table": "official_documents",
                "title": item.get("title") or item.get("subject") or item["id"], "subtitle": item.get("recipient") or "",
                "status": item.get("current_status") or "", "createdAt": item.get("created_at") or "", "record": item,
            })

    if category in {"all", "inbound_documents", "收文", "公文"} and can_read_table(session, "inbound_documents"):
        can_all_inbound = session_has_any_permission(session, ["official_documents.receive", "official_documents.all_records", "official_documents.all_todo"])
        inbound_rows = _supabase_search_rows(
            "inbound_documents", columns=["id", "receive_no", "sender_name", "subject", "assignee_name"],
            term=term, status_column="status", status=status,
            select="id,receive_no,sender_name,subject,assignee_user_id,assignee_name,due_at,status,created_at,updated_at",
        )
        if term:
            known_ids = {str(item.get("id") or "") for item in inbound_rows}
            for inbound_id in _supabase_attachment_parent_ids("inbound_document_attachments", "inbound_document_id", term):
                if inbound_id not in known_ids:
                    attached_inbound = supabase_get("inbound_documents", inbound_id)
                    if attached_inbound:
                        inbound_rows.append(attached_inbound)
                        known_ids.add(inbound_id)
        for item in inbound_rows:
            if not canonical_search_date_matches(item, date_from, date_to):
                continue
            if not can_all_inbound and item.get("assignee_user_id") != user["id"]:
                continue
            results.append({
                "id": item["id"], "category": "收文", "table": "inbound_documents",
                "title": item.get("receive_no") or item["id"], "subtitle": item.get("subject") or item.get("sender_name") or "",
                "status": item.get("status") or "", "createdAt": item.get("created_at") or "", "record": item,
            })

    if category in {"all", "internal_dispatches", "派文"} and can_read_table(session, "internal_dispatches"):
        can_all_dispatches = session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"])
        recipient_dispatch_ids = {
            item.get("dispatch_id") for item in supabase_filter_rows("internal_dispatch_recipients", {"recipient_user_id": user["id"]}, limit=100000, select="dispatch_id")
        }
        for item in _supabase_search_rows(
            "internal_dispatches", columns=["id", "title", "subject", "sender_name"],
            term=term, status_column="status", status=status,
            select="id,official_document_id,inbound_document_id,title,subject,sender_user_id,sender_name,due_at,reply_status,status,created_at,updated_at",
        ):
            if not canonical_search_date_matches(item, date_from, date_to):
                continue
            if not can_all_dispatches and item.get("sender_user_id") != user["id"] and item["id"] not in recipient_dispatch_ids:
                continue
            results.append({
                "id": item["id"], "category": "派文", "table": "internal_dispatches",
                "title": item.get("title") or item["id"], "subtitle": item.get("subject") or "",
                "status": item.get("status") or "", "createdAt": item.get("created_at") or "", "record": item,
            })

    results.sort(key=lambda item: str(item.get("createdAt") or ""), reverse=True)
    total = len(results)
    start = (page - 1) * page_size
    page_results = results[start:start + page_size]
    return {
        "query": term, "category": category, "status": status,
        "date_from": date_from, "date_to": date_to, "company_id": company_id,
        "count": len(page_results), "total": total, "page": page, "page_size": page_size,
        "has_more": start + page_size < total, "results": page_results,
    }


def can_read_document(conn: sqlite3.Connection, document_id: str, session: Dict[str, Any] | None) -> bool:
    scope_clause, scope_params = document_scope_clause(session.get("user") if session else None)
    if not scope_clause:
        return True
    row = conn.execute(f"SELECT 1 FROM documents WHERE id = ? AND {scope_clause}", (document_id, *scope_params)).fetchone()
    return bool(row)


def roc_date_serial(date: datetime | None = None) -> str:
    date = date or datetime.now()
    return f"{date.year - 1911}{date.month:02d}{date.day:02d}"


def next_dispatch_no(conn: sqlite3.Connection) -> str:
    date_serial = roc_date_serial()
    prefix = f"歲悅字第{date_serial}"
    rows = conn.execute(
        "SELECT doc_no FROM documents WHERE direction = '發文' AND doc_no LIKE ?",
        (f"{prefix}%號",),
    ).fetchall()
    max_serial = 0
    for row in rows:
        value = row["doc_no"]
        if value.startswith(prefix) and value.endswith("號"):
            serial = value[len(prefix):-1]
            if serial.isdigit():
                max_serial = max(max_serial, int(serial))
    return f"{prefix}{max_serial + 1:03d}號"


def record_login_event(
    conn: sqlite3.Connection,
    email: str,
    provider: str,
    status: str,
    reason: str = "",
    user_id: str | None = None,
    ip: str = "",
    device: str = "",
) -> None:
    conn.execute(
        """
        INSERT INTO login_events (id, user_id, email, provider, ip, device, status, reason, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (f"LOGIN-{int(time.time() * 1000)}", user_id, email, provider, ip, device, status, reason, now()),
    )


def create_session(conn: sqlite3.Connection, user: sqlite3.Row, provider: str, ip: str, device: str) -> Dict[str, Any]:
    token = secrets.token_urlsafe(36)
    expires = datetime.now() + timedelta(hours=8)
    conn.execute(
        """
        INSERT INTO auth_sessions (id, user_id, token_hash, provider, ip, device, expires_at, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (f"SES-{int(time.time() * 1000)}", user["id"], hash_token(token), provider, ip, device, expires.strftime("%Y-%m-%d %H:%M:%S"), now()),
    )
    conn.execute("UPDATE users SET last_login_at = ? WHERE id = ?", (now(), user["id"]))
    record_login_event(conn, user["email"], provider, "成功", "帳密驗證通過", user["id"], ip, device)
    log_audit(conn, user["email"], "使用者登入", "users", user["id"], f"{provider} / {ip} / {device}")
    return {
        "token": token,
        "expiresAt": expires.strftime("%Y-%m-%d %H:%M:%S"),
        "user": public_user(user),
        "permissions": role_permission_codes(conn, user["role"]),
    }


def authenticate_local(conn: sqlite3.Connection, payload: Dict[str, Any], ip: str, device: str) -> Tuple[Dict[str, Any], int]:
    email = str(payload.get("email", "")).strip().lower()
    password = str(payload.get("password", ""))
    provider = str(payload.get("provider") or payload.get("environment") or "本機帳號")
    if not test_fixture_accounts_enabled():
        record_login_event(conn, email or "-", provider, "失敗", "僅允許 Finance Google SSO", None, ip, device)
        return {"error": "finance_sso_required", "detail": "請由公司統一登入頁使用 Finance Google 帳號登入。"}, 403
    if not email or not password:
        record_login_event(conn, email or "-", provider, "失敗", "缺少帳號或密碼", None, ip, device)
        return {"error": "invalid_request", "detail": "請輸入帳號與密碼。"}, 400

    user = conn.execute("SELECT * FROM users WHERE lower(email) = ?", (email,)).fetchone()
    if not user:
        record_login_event(conn, email, provider, "失敗", "帳號不存在", None, ip, device)
        return {"error": "invalid_credentials", "detail": "帳號或密碼不正確。"}, 401
    if user["status"] != "啟用":
        record_login_event(conn, email, provider, "失敗", "帳號停用", user["id"], ip, device)
        return {"error": "account_disabled", "detail": "此帳號已停用。"}, 403
    if user["role"] not in ALLOWED_EDOC_ROLES:
        record_login_event(conn, email, provider, "失敗", "角色未授權", user["id"], ip, device)
        return {"error": "role_forbidden", "detail": "此帳號角色未授權使用電子公文系統。"}, 403
    if demo_login_blocked(email, password):
        record_login_event(conn, email, provider, "失敗", "正式站禁止 demo 帳號登入", user["id"], ip, device)
        return {"error": "demo_login_disabled", "detail": "正式環境已關閉 demo 帳號，請使用正式帳號或 Logging Portal 登入。"}, 403
    if not verify_password(password, user["password_hash"]):
        record_login_event(conn, email, provider, "失敗", "密碼錯誤", user["id"], ip, device)
        return {"error": "invalid_credentials", "detail": "帳號或密碼不正確。"}, 401
    return create_session(conn, user, provider, ip, device), 200


def current_session(conn: sqlite3.Connection, token: str) -> Dict[str, Any] | None:
    if not token:
        return None
    row = conn.execute(
        """
        SELECT
          s.id AS session_id, s.expires_at,
          u.id, u.auth_user_id, u.account_source, u.logging_account_id, u.logging_role_key,
          u.finance_employee_id, u.company_id, u.company_name, u.company_address,
          u.manager_employee_id, u.manager_name, u.manager_email, u.manager_role_key,
          u.approval_manager_employee_id, u.approval_manager_name, u.approval_manager_email, u.approval_manager_role_key,
          u.name, u.email, u.unit, u.title, u.job_level, u.role,
          u.provider, u.mfa_status, u.status, u.last_login_at, u.created_at
        FROM auth_sessions s
        JOIN users u ON u.id = s.user_id
        WHERE s.token_hash = ? AND s.revoked_at IS NULL AND s.expires_at > ?
        """,
        (hash_token(token), now()),
    ).fetchone()
    if not row:
        return None
    identity_invalid = (
        row["status"] != "啟用"
        or row["role"] not in ALLOWED_EDOC_ROLES
        or (
            is_production()
            and (
                str(row["account_source"] or "").strip().lower() != "finance"
                or not str(row["auth_user_id"] or "").strip()
                or not str(row["company_id"] or "").strip()
            )
        )
    )
    if identity_invalid:
        # Finance remains the source of truth after login.  A previously
        # issued EDOC bearer must stop working as soon as the linked roster
        # account is disabled, unbound, or loses its company/role assignment.
        conn.execute(
            "UPDATE auth_sessions SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL",
            (now(), row["session_id"]),
        )
        return None
    user: Dict[str, Any] = {
        key: row[key]
        for key in row.keys()
        if key not in {"session_id", "expires_at"}
    }
    if is_production():
        try:
            snapshot = current_finance_bridge_snapshot(user["email"])
            refreshed, _ = sync_sqlite_finance_snapshot(
                conn,
                snapshot,
                auth_user_id=user.get("auth_user_id") or "",
                expected_user_id=user["id"],
            )
            user = refreshed
        except FinanceBridgeDenied:
            conn.execute(
                "UPDATE auth_sessions SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL",
                (now(), row["session_id"]),
            )
            return None
        except FinanceBridgeUnavailable:
            # A stale local mirror is never accepted. Keep the bearer unrevoked
            # for recovery, but deny this request while Finance is unavailable.
            return None
    return {
        "sessionId": row["session_id"],
        "expiresAt": row["expires_at"],
        "user": user,
        "permissions": role_permission_codes(conn, user["role"]),
    }


def dashboard(conn: sqlite3.Connection, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    def scalar(sql: str, params: Tuple[Any, ...] = ()) -> int:
        return int(conn.execute(sql, params).fetchone()[0])

    document_where, document_params = scoped_document_where(session)
    inbound_where, inbound_params = scoped_document_where(session, ["direction = '收文'", "status IN ('待登錄','待分派')"])
    dispatch_where, dispatch_params = scoped_document_where(session, ["direction = '發文'", "status IN ('草稿','待清稿','已清稿')"])
    exchange_scope = f"document_id IN (SELECT id FROM documents{document_where})"
    total_tasks = scalar(f"SELECT COUNT(*) FROM exchange_tasks WHERE {exchange_scope}", tuple(document_params))
    failed_tasks = scalar(f"SELECT COUNT(*) FROM exchange_tasks WHERE status LIKE '%失敗%' AND {exchange_scope}", tuple(document_params))
    complete_tasks = scalar(
        f"SELECT COUNT(*) FROM exchange_tasks WHERE (status LIKE '%完成%' OR status LIKE '%確認%') AND {exchange_scope}",
        tuple(document_params),
    )
    audit_count = scalar("SELECT COUNT(*) FROM audit_logs") if session_has_any_permission(session, ["audit_logs.view", "audit_logs.export", "audit.view"]) else 0
    return {
        "documents": scalar(f"SELECT COUNT(*) FROM documents{document_where}", tuple(document_params)),
        "inboundPending": scalar(f"SELECT COUNT(*) FROM documents{inbound_where}", tuple(inbound_params)),
        "dispatchPending": scalar(f"SELECT COUNT(*) FROM documents{dispatch_where}", tuple(dispatch_params)),
        "exchangeTasks": total_tasks,
        "exchangeFailed": failed_tasks,
        "successRate": round((complete_tasks / total_tasks) * 100, 1) if total_tasks else 100,
        "auditLogs": audit_count,
    }


def pull_inbound(conn: sqlite3.Connection) -> Dict[str, Any]:
    assert_formal_exchange_allowed({})
    gateway = create_exchange_gateway(conn)
    result = gateway.receiveOfficialDocuments({})
    created = [item.get("document_id") for item in result.get("items", []) if item.get("document_id")]
    for doc_id in created:
        log_audit(conn, "Exchange Gateway", "每日收文拉取", "documents", doc_id, "mock provider 已建立收文主檔")
    return {"created": created[0] if created else "", "created_ids": created, "count": result.get("count", 0), "gateway": result}


def exchange_gateway_status() -> Dict[str, Any]:
    formal_requested = EDOC_EXCHANGE_ENV in FORMAL_EXCHANGE_ENVIRONMENTS or EDOC_EXCHANGE_PROVIDER not in NON_FORMAL_EXCHANGE_PROVIDERS
    formal_disabled = launch_scope() == "internal_official" or not formal_requested
    return {
        "provider": EDOC_EXCHANGE_PROVIDER,
        "environment": EDOC_EXCHANGE_ENV,
        "maxRetries": EDOC_EXCHANGE_MAX_RETRIES,
        "formalConnection": False,
        "mode": "mock-only" if EDOC_EXCHANGE_PROVIDER == "mock" else "provider-not-implemented",
        "formalExchangeDisabled": formal_disabled,
        "formalDisabledReason": "內部正式使用模式不啟用政府電子交換。" if formal_disabled else "正式 provider 尚未完成人工核准。",
        "secrets": {
            "configuredByEnvironment": True,
            "logged": False,
        },
    }


def formal_exchange_requested(payload: Dict[str, Any] | None = None) -> bool:
    payload = payload or {}
    target = str(payload.get("exchange_env") or payload.get("target_environment") or payload.get("environment") or "").strip().lower()
    mode = str(payload.get("exchange_mode") or payload.get("mode") or "").strip().lower()
    return bool(
        payload.get("formal")
        or target in FORMAL_EXCHANGE_ENVIRONMENTS
        or mode in {"formal", "production", "real"}
        or EDOC_EXCHANGE_ENV in FORMAL_EXCHANGE_ENVIRONMENTS
        or EDOC_EXCHANGE_PROVIDER not in NON_FORMAL_EXCHANGE_PROVIDERS
    )


def assert_formal_exchange_allowed(payload: Dict[str, Any] | None = None) -> None:
    if not formal_exchange_requested(payload):
        return
    if launch_scope() == "internal_official" or not exchange_gateway_status().get("formalConnection"):
        raise PermissionError("formal_exchange_disabled")


def exchange_queue_document(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    gateway = create_exchange_gateway(conn)
    result = gateway.queueOfficialDocument(payload)
    log_audit(conn, "Exchange Gateway", "加入交換待發佇列", "exchange_outbox", result.get("id", ""), json.dumps(redact_sensitive(payload), ensure_ascii=False))
    return result


def exchange_send_document(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    assert_formal_exchange_allowed(payload)
