def backup_database(conn: sqlite3.Connection) -> Dict[str, Any]:
    ensure_dirs()
    name = f"edoc-backup-{datetime.now().strftime('%Y%m%d-%H%M%S')}.sqlite3"
    target = BACKUP_DIR / name
    conn.commit()
    shutil.copy2(DB_PATH, target)
    digest = sha256_bytes(target.read_bytes())
    log_audit(conn, "API", "資料備份", "backup", name, f"{target} sha256={digest}")
    return {"backup": name, "path": str(target), "size": target.stat().st_size, "sha256": digest, "created_at": now()}


def sqlite_table_counts(db_path: Path) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    readonly = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    readonly.row_factory = sqlite3.Row
    try:
        for table in TABLES:
            try:
                counts[table] = readonly.execute(f"SELECT COUNT(*) AS count FROM {table}").fetchone()["count"]
            except sqlite3.Error:
                counts[table] = 0
    finally:
        readonly.close()
    return counts


def directory_sha256_manifest(root: Path) -> Dict[str, str]:
    if not root.exists():
        return {}
    return {
        str(path.relative_to(root)): sha256_bytes(path.read_bytes())
        for path in sorted(root.rglob("*"))
        if path.is_file()
    }


def validate_restored_pdf_samples(db_path: Path, storage_root: Path, limit: int = 20) -> Dict[str, Any]:
    restored = sqlite3.connect(str(db_path))
    restored.row_factory = sqlite3.Row
    checked = 0
    failures: List[str] = []
    try:
        rows = restored.execute(
            "SELECT id, storage_key, sha256, encryption_status, encryption_alg FROM file_objects WHERE lower(mime_type) = 'application/pdf' ORDER BY created_at DESC LIMIT ?",
            (limit,),
        ).fetchall()
        for row in rows:
            path = storage_root / row["storage_key"]
            try:
                raw = path.read_bytes()
                data = decrypt_file_bytes(raw, row["encryption_status"] or "", row["encryption_alg"] or "")
                if sha256_bytes(data) != row["sha256"] or not data.startswith(b"%PDF-"):
                    failures.append(str(row["id"]))
            except Exception:
                failures.append(str(row["id"]))
            checked += 1
    finally:
        restored.close()
    return {"checked": checked, "failures": failures, "ok": not failures}


def run_backup_restore_drill(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    ensure_dirs()
    started = time.time()
    scope = payload.get("scope") or "全部資料表"
    target_env = payload.get("target_env") or payload.get("target") or "測試沙盒"
    rto_target = int(payload.get("rto_target_minutes") or payload.get("rtoTarget") or 30)
    rpo_target = int(payload.get("rpo_target_minutes") or payload.get("rpoTarget") or 15)
    backup = backup_database(conn)
    source_hash = backup["sha256"]
    source_counts = sqlite_table_counts(Path(backup["path"]))
    sandbox_name = backup["backup"].replace("edoc-backup-", "restore-sandbox-")
    sandbox_path = BACKUP_DIR / sandbox_name
    shutil.copy2(backup["path"], sandbox_path)
    sandbox_storage_path = BACKUP_DIR / f"{Path(sandbox_name).stem}-storage"
    if sandbox_storage_path.exists():
        shutil.rmtree(sandbox_storage_path)
    shutil.copytree(STORAGE_DIR, sandbox_storage_path)
    restore_hash = sha256_bytes(sandbox_path.read_bytes())
    restored_counts = sqlite_table_counts(sandbox_path)
    integrity_row = sqlite3.connect(str(sandbox_path)).execute("PRAGMA integrity_check").fetchone()
    integrity = integrity_row[0] if integrity_row else "unknown"
    source_storage_manifest = directory_sha256_manifest(STORAGE_DIR)
    restored_storage_manifest = directory_sha256_manifest(sandbox_storage_path)
    storage_hash_match = source_storage_manifest == restored_storage_manifest
    pdf_samples = validate_restored_pdf_samples(sandbox_path, sandbox_storage_path)
    duration_ms = int((time.time() - started) * 1000)
    rto_minutes = max(1, (duration_ms + 59999) // 60000)
    backup_age_seconds = max(0, int(time.time() - Path(backup["path"]).stat().st_mtime))
    rpo_minutes = max(1, (backup_age_seconds + 59) // 60)
    counts_match = source_counts == restored_counts
    hash_match = source_hash == restore_hash
    rto_ok = rto_minutes <= rto_target
    rpo_ok = rpo_minutes <= rpo_target
    ok = integrity == "ok" and counts_match and hash_match and storage_hash_match and pdf_samples["ok"] and rto_ok and rpo_ok
    drill_id = f"DRILL-{datetime.now().strftime('%Y%m%d-%H%M%S')}-{secrets.token_hex(3).upper()}"
    report = {
        "id": drill_id,
        "ok": ok,
        "result": "通過" if ok else "需改善",
        "created_at": now(),
        "scope": scope,
        "target_env": target_env,
        "backup": backup,
        "sandbox": {"path": str(sandbox_path), "storage_path": str(sandbox_storage_path), "sha256": restore_hash, "integrity": integrity},
        "storage": {
            "source_object_count": len(source_storage_manifest),
            "restored_object_count": len(restored_storage_manifest),
            "hash_match": storage_hash_match,
            "pdf_samples": pdf_samples,
        },
        "source_counts": source_counts,
        "restored_counts": restored_counts,
        "row_count": sum(source_counts.values()),
        "checks": {
            "integrity": integrity == "ok",
            "hash_match": hash_match,
            "counts_match": counts_match,
            "storage_restored": storage_hash_match,
            "pdf_open_sample": pdf_samples["ok"],
            "rto_ok": rto_ok,
            "rpo_ok": rpo_ok,
        },
        "rto_minutes": rto_minutes,
        "rto_target_minutes": rto_target,
        "rpo_minutes": rpo_minutes,
        "rpo_target_minutes": rpo_target,
        "duration_ms": duration_ms,
        "steps": {
            "snapshot": f"{backup['backup']} 已建立，{sum(source_counts.values())} 筆資料",
            "sourceHash": f"{source_hash} 已產生",
            "sandboxRestore": f"{target_env} Database 與 Storage 還原完成，未覆蓋正式資料",
            "verify": "筆數與雜湊比對通過" if counts_match and hash_match else "筆數或雜湊不一致",
            "rtoRpo": f"RTO {rto_minutes}/{rto_target} 分，RPO {rpo_minutes}/{rpo_target} 分",
        },
        "improvements": [] if ok else [
            item for item, passed in {
                "確認備份檔完整性或重新產生備份": integrity == "ok" and hash_match,
                "檢查還原程序是否漏表或資料筆數不一致": counts_match,
                "檢查 private Storage 還原物件與逐檔 hash": storage_hash_match,
                "檢查還原後 PDF 可讀性與檔案 hash": pdf_samples["ok"],
                "優化還原程序以符合 RTO": rto_ok,
                "提高備份頻率以符合 RPO": rpo_ok,
            }.items() if not passed
        ],
    }
    report_path = BACKUP_DIR / f"{drill_id}.json"
    report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    log_audit(conn, "Ops Drill", "備份還原演練", "backup_restore_drill", drill_id, json.dumps({"result": report["result"], "backup": backup["backup"], "rto": rto_minutes, "rpo": rpo_minutes}, ensure_ascii=False))
    return {**report, "report_path": str(report_path)}


def record_file_access(
    conn: sqlite3.Connection,
    *,
    attachment_id: str = "",
    file_object_id: str = "",
    document_id: str = "",
    actor: str = "API",
    action: str,
    result: str,
    detail: str = "",
    watermark_text: str = "",
) -> Dict[str, Any]:
    document_log_id = document_id or ""
    if document_log_id and not conn.execute("SELECT 1 FROM documents WHERE id = ?", (document_log_id,)).fetchone():
        document_log_id = ""
    row = {
        "id": f"FLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "attachment_id": attachment_id or None,
        "file_object_id": file_object_id or None,
        "document_id": document_log_id or None,
        "actor": actor,
        "action": action,
        "ip": "",
        "device": "",
        "watermark_text": watermark_text,
        "result": result,
        "detail": detail,
        "created_at": now(),
    }
    insert_row(conn, "file_access_logs", row)
    log_audit(conn, actor, action, "attachments", attachment_id or file_object_id, detail or result)
    return row


def is_seal_vault_file(item: Dict[str, Any] | sqlite3.Row | None) -> bool:
    if not item:
        return False
    data = row_to_dict(item) if isinstance(item, sqlite3.Row) else item
    purpose = str(data.get("purpose") or "")
    storage_key = str(data.get("storage_key") or "")
    document_id = str(data.get("document_id") or "")
    return (
        purpose.startswith(SEAL_VAULT_PURPOSE_PREFIX)
        or storage_key.startswith("seal-vault/")
        or storage_key.startswith("private/seals/")
        or document_id == SEAL_VAULT_DOCUMENT_ID
    )


def seal_file_row_for_file_object(conn: sqlite3.Connection, file_id: str) -> Dict[str, Any] | None:
    row = conn.execute("SELECT * FROM company_seal_files WHERE file_object_id = ? ORDER BY uploaded_at DESC LIMIT 1", (file_id,)).fetchone()
    return row_to_dict(row) if row else None


def audit_seal_vault_access(
    conn: sqlite3.Connection,
    *,
    file_id: str,
    actor: str,
    action: str,
    result: str,
    detail: str = "",
    document_id: str = "",
) -> None:
    seal_file = seal_file_row_for_file_object(conn, file_id)
    log_seal_usage(
        conn,
        action=action,
        actor_id=actor,
        seal_id=seal_file.get("seal_id", "") if seal_file else "",
        document_id=document_id,
        detail=f"{result}: {detail or file_id}",
    )


def official_document_file_reference(conn: sqlite3.Connection, file_object_id: str) -> Dict[str, Any] | None:
    row = conn.execute(
        """
        SELECT id, document_id, file_type
        FROM official_document_files
        WHERE file_object_id = ?
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (file_object_id,),
    ).fetchone()
    return row_to_dict(row) if row else None


def create_file_signed_url(conn: sqlite3.Connection, file_id: str, actor: str = "API", ttl_seconds: int | None = None, purpose: str = "download") -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM file_objects WHERE id = ?", (file_id,)).fetchone()
    if not row:
        return {"error": "file_not_found"}
    item = row_to_dict(row)
    if is_seal_vault_file(item):
        audit_seal_vault_access(conn, file_id=file_id, actor=actor, action="block_seal_vault_signed_url", result="denied", detail="seal_original_never_gets_download_url")
        return {"error": "seal_vault_download_forbidden", "detail": "seal_original_files_must_be_accessed_only_by_authorized_backend_seal_workflows"}
    official_reference = official_document_file_reference(conn, file_id)
    if official_reference:
        log_audit(
            conn,
            actor,
            "阻擋發文檔案通用下載 URL",
            "official_document_files",
            official_reference["id"],
            f"document_id={official_reference['document_id']};file_type={official_reference['file_type']}",
        )
        return {
            "error": "official_document_file_requires_participant_endpoint",
            "detail": "official_document_files_must_use_the_audited_participant_download_endpoint",
        }
    expires_at = signed_url_expiry(ttl_seconds)
    token = secrets.token_urlsafe(32)
    token_id = f"FDL-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    conn.execute(
        """
        INSERT INTO file_download_tokens (id, file_object_id, token_hash, actor, purpose, expires_at, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        """,
        (token_id, file_id, hash_token(token), actor, purpose, expires_at, now()),
    )
    conn.execute("UPDATE file_objects SET signed_url_expires_at = ? WHERE id = ?", (expires_at, file_id))
    url = f"/api/files/{file_id}/download?token={urllib.parse.quote(token)}"
    log_audit(conn, actor, "產生短效檔案下載 URL", "file_objects", file_id, f"expires_at={expires_at}, provider={item.get('storage_provider')}")
    return {"file": item, "token_id": token_id, "download_url": url, "expires_at": expires_at, "ttl_seconds": ttl_seconds or EDOC_SIGNED_URL_TTL_SECONDS}


def validate_file_download_token(conn: sqlite3.Connection, file_id: str, token: str) -> Tuple[bool, str, Dict[str, Any] | None]:
    if not token:
        return False, "missing_token", None
    row = conn.execute(
        "SELECT * FROM file_download_tokens WHERE file_object_id = ? AND token_hash = ? ORDER BY created_at DESC LIMIT 1",
        (file_id, hash_token(token)),
    ).fetchone()
    if not row:
        return False, "invalid_token", None
    item = row_to_dict(row)
    if item.get("revoked_at"):
        return False, "revoked_token", item
    if parse_time(item.get("expires_at", "")) < datetime.now():
        return False, "expired_token", item
    return True, "ok", item


def scan_bytes_for_threats(data: bytes, file_name: str) -> Tuple[str, str]:
    upper = data.upper()
    if b"EICAR-STANDARD-ANTIVIRUS-TEST-FILE" in upper or b"X5O!P%@AP" in upper:
        return "已隔離", "EICAR-Test-File"
    if Path(file_name).suffix.lower().lstrip(".") not in {"pdf", "xml", "xlsx", "xls", "docx", "doc", "csv", "p7m", "txt", "png", "jpg", "jpeg", "webp"}:
        return "已隔離", "Disallowed-Extension"
    return "已通過", "Clean"


def _av_request_signing_message(timestamp: str, nonce: str, body_sha256: str) -> bytes:
    return f"v1\n{timestamp}\n{nonce}\n{body_sha256.lower()}".encode("ascii")


def _av_response_signing_message(timestamp: str, nonce: str, body_sha256: str) -> bytes:
    return f"v1-response\n{timestamp}\n{nonce}\n{body_sha256.lower()}".encode("ascii")


def _av_hmac_signature(secret: bytes, message: bytes) -> str:
    return "v1=" + hmac.new(secret, message, hashlib.sha256).hexdigest()


def _https_hmac_scan_bytes(
    data: bytes,
    *,
    storage_key: str = "",
    storage_bucket: str = "",
    expected_sha256: str = "",
) -> Tuple[str, str]:
    av = av_endpoint_configuration()
    if av.get("contract") != "edoc-clamav-https-v1":
        raise ValueError("editor_antivirus_not_ready")
    secret = os.getenv("EDOC_AV_API_KEY", "").encode("utf-8")
    if len(secret) < 32:
        raise ValueError("editor_antivirus_not_ready")
    digest = str(expected_sha256 or sha256_bytes(data)).lower()
    if not re.fullmatch(r"[a-f0-9]{64}", digest):
        raise ValueError("editor_antivirus_scan_failed")
    if storage_key:
        signed = supabase_storage_create_signed_scan_url(
            storage_key,
            storage_bucket or EDOC_STORAGE_BUCKET,
            ttl_seconds=60,
        )
        body = json.dumps(
            {
                "schemaVersion": 1,
                "sourceUrl": signed["url"],
                "sha256": digest,
                "sizeBytes": len(data),
            },
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8")
        content_type = "application/json"
    else:
        if len(data) > EDOC_AV_HTTP_INLINE_MAX_BYTES:
            raise ValueError("editor_antivirus_storage_source_required")
        body = data
        content_type = "application/octet-stream"
    timestamp = str(int(time.time()))
    nonce = secrets.token_hex(24)
    body_sha256 = hashlib.sha256(body).hexdigest()
    request_signature = _av_hmac_signature(
        secret,
        _av_request_signing_message(timestamp, nonce, body_sha256),
    )
    endpoint = str(av["endpoint"]).rstrip("/")
    url = endpoint if urllib.parse.urlparse(endpoint).path == "/v1/scan" else f"{endpoint}/v1/scan"
    request = urllib.request.Request(
        url,
        data=body,
        headers={
            "Content-Type": content_type,
            "Content-Length": str(len(body)),
            "Cache-Control": "no-store",
            "X-EDOC-AV-Timestamp": timestamp,
            "X-EDOC-AV-Nonce": nonce,
            "X-EDOC-AV-Body-SHA256": body_sha256,
            "X-EDOC-AV-Content-SHA256": digest,
            "X-EDOC-AV-Content-Length": str(len(data)),
            "X-EDOC-AV-Signature": request_signature,
        },
        method="POST",
    )
    timeout = max(2, min(120, EDOC_AV_TIMEOUT_SECONDS))
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read(16 * 1024)
            response_timestamp = str(response.headers.get("X-EDOC-AV-Response-Timestamp") or "")
            response_signature = str(response.headers.get("X-EDOC-AV-Response-Signature") or "")
    except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
        raise ValueError("editor_antivirus_scan_failed") from exc
    if (
        not response_timestamp.isdigit()
        or abs(int(time.time()) - int(response_timestamp)) > EDOC_AV_HMAC_MAX_AGE_SECONDS
        or not re.fullmatch(r"v1=[a-fA-F0-9]{64}", response_signature)
    ):
        raise ValueError("editor_antivirus_response_invalid")
    response_body_sha256 = hashlib.sha256(raw).hexdigest()
    expected_response_signature = _av_hmac_signature(
        secret,
        _av_response_signing_message(response_timestamp, nonce, response_body_sha256),
    )
    if not hmac.compare_digest(response_signature, expected_response_signature):
        raise ValueError("editor_antivirus_response_invalid")
    try:
        result = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("editor_antivirus_response_invalid") from exc
    if not isinstance(result, dict) or set(result) != {
        "schemaVersion", "status", "engine", "signature", "sha256", "sizeBytes", "scannedAt"
    }:
        raise ValueError("editor_antivirus_response_invalid")
    if (
        result.get("schemaVersion") != 1
        or str(result.get("engine") or "") != "ClamAV"
        or str(result.get("sha256") or "").lower() != digest
        or int(result.get("sizeBytes") or -1) != len(data)
    ):
        raise ValueError("editor_antivirus_response_invalid")
    status = str(result.get("status") or "")
    if status == "clean" and not str(result.get("signature") or ""):
        return "已通過", "ClamAV-Clean"
    if status == "clean":
        return "已通過", "ClamAV-Clean"
    if status == "infected":
        signature = re.sub(r"[^A-Za-z0-9._-]", "-", str(result.get("signature") or ""))[:120]
        return "已隔離", signature or "Malware-Found"
    raise ValueError("editor_antivirus_response_invalid")


def editor_scan_bytes_for_threats(
    data: bytes,
    file_name: str,
    *,
    storage_key: str = "",
    storage_bucket: str = "",
    expected_sha256: str = "",
) -> Tuple[str, str]:
    """Scan editor bytes, using a pinned production transport.

    Production supports a fresh Vercel Sandbox microVM, direct clamd INSTREAM,
    and the repository-owned HTTPS HMAC v1 gateway. Scanner/network/protocol
    errors fail closed. Development and tests use the deterministic EICAR
    fixture scanner unless a test explicitly patches production mode.
    """
    if not is_production():
        return scan_bytes_for_threats(data, file_name)
    av = av_endpoint_configuration()
    if not av["contractSupported"]:
        raise ValueError("editor_antivirus_not_ready")
    if av.get("contract") == VERCEL_SANDBOX_AV_PROVIDER_ID:
        if not av.get("transportConfigured") or not av.get("credentialConfigured"):
            raise ValueError("editor_antivirus_not_ready")
        try:
            result = scan_bytes_in_vercel_sandbox(
                data,
                snapshot_id=str(EDOC_AV_SANDBOX_SNAPSHOT_ID or "").strip(),
                project_id=str(EDOC_AV_SANDBOX_PROJECT_ID or "").strip(),
                expected_sha256=expected_sha256 or sha256_bytes(data),
                timeout_seconds=EDOC_AV_TIMEOUT_SECONDS,
                max_file_size_bytes=EDOC_MAX_FILE_SIZE_MB * 1024 * 1024,
            )
        except SandboxAntivirusError as exc:
            raise ValueError("editor_antivirus_scan_failed") from exc
        if result.status == "clean":
            return "已通過", "ClamAV-Clean"
        if result.status == "infected":
            return "已隔離", result.signature
        raise ValueError("editor_antivirus_scan_failed")
    if av.get("contract") == "edoc-clamav-https-v1":
        return _https_hmac_scan_bytes(
            data,
            storage_key=storage_key,
            storage_bucket=storage_bucket,
            expected_sha256=expected_sha256,
        )
    host = av["hostname"]
    port = int(av["port"])
    timeout = max(1, min(60, EDOC_AV_TIMEOUT_SECONDS))
    try:
        with socket.create_connection((host, port), timeout=timeout) as scanner:
            scanner.settimeout(timeout)
            scanner.sendall(b"zINSTREAM\0")
            for offset in range(0, len(data), 1024 * 1024):
                chunk = data[offset:offset + 1024 * 1024]
                scanner.sendall(struct.pack("!I", len(chunk)))
                scanner.sendall(chunk)
            scanner.sendall(struct.pack("!I", 0))
            response = bytearray()
            while len(response) < 4096:
                block = scanner.recv(1024)
                if not block:
                    break
                response.extend(block)
                if b"\0" in block or b"\n" in block:
                    break
    except (OSError, TimeoutError, ValueError) as exc:
        raise ValueError("editor_antivirus_scan_failed") from exc
    result = bytes(response).split(b"\0", 1)[0].decode("utf-8", "replace").strip()
    if result.endswith(" OK") or result == "OK":
        return "已通過", "ClamAV-Clean"
    found = re.search(r":\s*(.+?)\s+FOUND$", result)
    if found:
        signature = re.sub(r"[^A-Za-z0-9._-]", "-", found.group(1))[:120] or "Malware-Found"
        return "已隔離", signature
    raise ValueError("editor_antivirus_scan_failed")


def antivirus_runtime_smoke() -> Dict[str, Any]:
    """Exercise the configured production scanner with deidentified fixtures.

    The operation is exposed only through a CRON_SECRET-protected route.  Its
    result contains no uploaded content, filenames, storage paths, or malware
    signature text, so operations can verify the runtime without weakening the
    document logging policy.
    """
    started = time.monotonic()
    clean_payload = b"%PDF-1.4\n1 0 obj<<>>endobj\n%%EOF\n"
    eicar_payload = base64.b64decode(
        "WDVPIVAlQEFQWzRcUFpYNTQoUF4pN0NDKTd9JEVJQ0FSLVNUQU5EQVJELUFOVElWSVJVUy1URVNULUZJTEUhJEgrSCo="
    )
    clean_status, _ = editor_scan_bytes_for_threats(clean_payload, "runtime-clean.pdf")
    infected_status, _ = editor_scan_bytes_for_threats(eicar_payload, "runtime-test.bin")
    ok = clean_status == "已通過" and infected_status == "已隔離"
    return {
        "ok": ok,
        "provider": EDOC_AV_PROVIDER,
        "cleanAccepted": clean_status == "已通過",
        "malwareRejected": infected_status == "已隔離",
        "durationMs": int((time.monotonic() - started) * 1000),
        "checkedAt": now(),
    }


def scan_file_object(conn: sqlite3.Connection, file_id: str, actor: str = "AV Worker") -> Dict[str, Any]:
    storage_service = storage_service_status()
    if storage_service["productionBlocked"]:
        return {"ok": False, "error": "formal_storage_av_not_ready", "missing": storage_service["missing"], "service": storage_service}
    row = conn.execute("SELECT * FROM file_objects WHERE id = ?", (file_id,)).fetchone()
    if not row:
        return {"ok": False, "error": "file_not_found"}
    item = row_to_dict(row)
    path = STORAGE_DIR / item["storage_key"]
    if not path.exists():
        return {"ok": False, "error": "file_missing"}
    raw = path.read_bytes()
    data = decrypt_file_bytes(raw, item.get("encryption_status", ""), item.get("encryption_alg", ""))
    # editor_scan_bytes_for_threats selects deterministic fixtures only outside
    # production and always uses a pinned configured production transport.
    # No production file category may fall back to the mock scan.
    status, signature = editor_scan_bytes_for_threats(data, item["file_name"])
    detail = "防毒掃描通過" if status == "已通過" else f"隔離：{signature}"
    job_id = f"VS-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    timestamp = now()
    scan_document_id = item.get("document_id") or ""
    if scan_document_id and not conn.execute("SELECT 1 FROM documents WHERE id = ?", (scan_document_id,)).fetchone():
        scan_document_id = ""
    conn.execute(
        """
        INSERT INTO virus_scan_jobs (
          id, file_object_id, attachment_id, document_id, engine, status, signature, result, detail,
          started_at, finished_at, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (job_id, file_id, None, scan_document_id or None, EDOC_SCAN_ENGINE, "完成", signature, status, detail, timestamp, timestamp, timestamp),
    )
    conn.execute(
        "UPDATE file_objects SET scan_status = ?, scan_engine = ?, quarantine_reason = ?, last_scan_at = ? WHERE id = ?",
        (status, EDOC_SCAN_ENGINE, "" if status == "已通過" else signature, timestamp, file_id),
    )
    log_audit(conn, actor, "正式防毒掃描", "file_objects", file_id, f"{EDOC_SCAN_ENGINE} / {status} / {signature}")
    refreshed = row_to_dict(conn.execute("SELECT * FROM file_objects WHERE id = ?", (file_id,)).fetchone())
    return {"ok": status == "已通過", "file": refreshed, "job": {"id": job_id, "engine": EDOC_SCAN_ENGINE, "result": status, "signature": signature, "detail": detail}}


