def read_file_object_bytes(conn: sqlite3.Connection, file_id: str) -> Tuple[Dict[str, Any], bytes]:
    row = conn.execute("SELECT * FROM file_objects WHERE id = ?", (file_id,)).fetchone()
    if not row:
        raise ValueError("file_not_found")
    item = row_to_dict(row)
    path = STORAGE_DIR / item["storage_key"]
    if not path.exists():
        raise ValueError("file_missing")
    raw = path.read_bytes()
    data = decrypt_file_bytes(raw, item.get("encryption_status", ""), item.get("encryption_alg", ""))
    actual = sha256_bytes(data)
    if actual != item["sha256"]:
        raise ValueError("file_hash_mismatch")
    return item, data


def seal_actor(session: Dict[str, Any] | None, payload: Dict[str, Any] | None = None) -> str:
    user = current_user_from_session(session)
    payload = payload or {}
    return user.get("id") or user.get("email") or user.get("name") or payload.get("actor_id") or payload.get("actor") or "API"


def seal_reference_codes(conn: sqlite3.Connection, option_type: str) -> set[str]:
    rows = conn.execute(
        "SELECT code FROM seal_reference_options WHERE option_type = ? AND status = 'active'",
        (option_type,),
    ).fetchall()
    return {row["code"] for row in rows}


FILE_AV_CLEAN_STATUSES = frozenset({"已通過", "clean", "passed"})
SEAL_FILE_AV_CLEAN_STATUSES = FILE_AV_CLEAN_STATUSES


def file_object_av_is_clean(file_object: Dict[str, Any] | sqlite3.Row | None) -> bool:
    if not file_object:
        return False
    data = row_to_dict(file_object) if isinstance(file_object, sqlite3.Row) else file_object
    return str(data.get("scan_status") or "").strip().lower() in {
        status.lower() for status in FILE_AV_CLEAN_STATUSES
    }


def seal_file_av_is_clean(file_object: Dict[str, Any] | sqlite3.Row | None) -> bool:
    return file_object_av_is_clean(file_object)


def seal_file_with_backing_status(
    conn: sqlite3.Connection,
    file_row: Dict[str, Any] | sqlite3.Row,
) -> Dict[str, Any]:
    item = row_to_dict(file_row) if isinstance(file_row, sqlite3.Row) else dict(file_row)
    file_object = (
        conn.execute("SELECT * FROM file_objects WHERE id = ?", (item.get("file_object_id") or "",)).fetchone()
        if item.get("file_object_id")
        else None
    )
    item["scan_status"] = file_object["scan_status"] if file_object else "檔案不存在"
    item["scan_engine"] = file_object["scan_engine"] if file_object else ""
    item["last_scan_at"] = file_object["last_scan_at"] if file_object else ""
    item["av_clean"] = seal_file_av_is_clean(file_object)
    seal = conn.execute(
        "SELECT seal_size_type FROM company_seals WHERE id = ?",
        (item.get("seal_id") or "",),
    ).fetchone()
    try:
        item["dimension_valid"] = bool(
            seal and company_seal_file_dimension_is_valid(item, seal["seal_size_type"])
        )
    except ValueError:
        item["dimension_valid"] = False
    item["usable"] = bool(
        item.get("is_current")
        and item.get("file_object_id")
        and item["av_clean"]
        and item["dimension_valid"]
    )
    return item


def current_company_seal_file(
    conn: sqlite3.Connection,
    seal_id: str,
    *,
    require_usable: bool = True,
) -> Dict[str, Any] | None:
    row = conn.execute(
        "SELECT * FROM company_seal_files WHERE seal_id = ? AND is_current = 1 ORDER BY version DESC LIMIT 1",
        (seal_id,),
    ).fetchone()
    if not row:
        return None
    item = seal_file_with_backing_status(conn, row)
    return item if not require_usable or item.get("usable") else None


def require_current_company_seal_file(conn: sqlite3.Connection, seal_id: str) -> Dict[str, Any]:
    item = current_company_seal_file(conn, seal_id, require_usable=False)
    if not item:
        raise ValueError("current_seal_file_required")
    if not item.get("file_object_id"):
        raise ValueError("seal_file_object_required")
    if not item.get("av_clean"):
        raise ValueError("current_seal_file_antivirus_required")
    seal = conn.execute("SELECT seal_size_type FROM company_seals WHERE id = ?", (seal_id,)).fetchone()
    if not seal:
        raise ValueError("seal_not_found")
    require_company_seal_file_dimensions(item, seal["seal_size_type"], current=True)
    return item


def require_seal_file_av_clean(conn: sqlite3.Connection, file_row: Dict[str, Any] | sqlite3.Row) -> Dict[str, Any]:
    item = seal_file_with_backing_status(conn, file_row)
    if not item.get("file_object_id"):
        raise ValueError("seal_file_object_required")
    if not item.get("av_clean"):
        raise ValueError("seal_file_antivirus_required")
    seal = conn.execute(
        "SELECT seal_size_type FROM company_seals WHERE id = ?",
        (item.get("seal_id") or "",),
    ).fetchone()
    if not seal:
        raise ValueError("seal_not_found")
    require_company_seal_file_dimensions(item, seal["seal_size_type"])
    return item


def company_seal_api_dimension_metadata(
    seal_size_type: Any,
    current_file: Dict[str, Any] | None,
) -> Dict[str, Any]:
    """Expose current-version geometry separately from the calibration policy."""
    policy = company_seal_dimension_profile(seal_size_type)
    current_profile = (
        company_seal_file_dimension_profile(seal_size_type, current_file, current=True)
        if current_file
        else policy
    )
    return {
        "render_size_mm": current_profile["width_mm"],
        "render_width_mm": current_profile["width_mm"],
        "render_height_mm": current_profile["height_mm"],
        "render_width_pt": current_profile["width_pt"],
        "render_height_pt": current_profile["height_pt"],
        "default_render_width_mm": policy["default_width_mm"],
        "default_render_height_mm": policy["default_height_mm"],
        "default_render_size_mm": policy["default_width_mm"],
        "min_render_width_mm": policy["min_width_mm"],
        "min_render_height_mm": policy["min_height_mm"],
        "min_render_size_mm": policy["min_width_mm"],
        "max_render_width_mm": policy["max_width_mm"],
        "max_render_height_mm": policy["max_height_mm"],
        "max_render_size_mm": policy["max_width_mm"],
        "calibration_dpi": policy["calibration_dpi"],
        "dimension_policy_version": policy["dimension_policy_version"],
        "dimension_policy": {
            "default_size_mm": policy["default_width_mm"],
            "default_width_mm": policy["default_width_mm"],
            "default_height_mm": policy["default_height_mm"],
            "min_size_mm": policy["min_width_mm"],
            "min_width_mm": policy["min_width_mm"],
            "min_height_mm": policy["min_height_mm"],
            "max_size_mm": policy["max_width_mm"],
            "max_width_mm": policy["max_width_mm"],
            "max_height_mm": policy["max_height_mm"],
            "square_tolerance_mm": EDOC_SEAL_PHYSICAL_SQUARE_TOLERANCE_MM,
            "source_aspect_tolerance": EDOC_SEAL_SOURCE_ASPECT_TOLERANCE,
            "calibration_dpi": policy["calibration_dpi"],
            "version": policy["dimension_policy_version"],
        },
        "size_locked": True,
    }


def company_seal_row(conn: sqlite3.Connection, seal_id: str) -> Dict[str, Any]:
    row = conn.execute(
        """
        SELECT s.*, c.name AS company_name, c.tax_id AS company_tax_id
        FROM company_seals s
        JOIN companies c ON c.id = s.company_id
        WHERE s.id = ?
        """,
        (seal_id,),
    ).fetchone()
    if not row:
        raise ValueError("seal_not_found")
    data = row_to_dict(row)
    designated_current = current_company_seal_file(conn, seal_id, require_usable=False)
    usable_current = (
        designated_current
        if designated_current
        and designated_current.get("usable")
        and str(designated_current.get("dimension_policy_version") or "") == EDOC_SEAL_DIMENSION_POLICY_VERSION
        else None
    )
    data.update(company_seal_api_dimension_metadata(data.get("seal_size_type"), usable_current))
    data["current_file"] = seal_file_metadata(usable_current) if usable_current else None
    data["current_file_status"] = seal_file_metadata(designated_current) if designated_current else None
    return data


def validate_official_document_seal(
    conn: sqlite3.Connection,
    seal_id: str,
    company_id: str,
    require_current: bool = False,
) -> Dict[str, Any]:
    seal = company_seal_row(conn, seal_id)
    if seal.get("company_id") != company_id:
        raise ValueError("official_document_seal_company_mismatch")
    if not seal.get("is_active"):
        raise ValueError("inactive_seal_cannot_be_requested")
    current_file = seal.get("current_file")
    if require_current:
        if not current_file:
            current_file = require_current_company_seal_file(conn, seal_id)
        if not current_file.get("file_object_id"):
            raise ValueError("seal_file_object_required")
    return seal


def launch_smoke_current_official_seal(conn: sqlite3.Connection, company_id: str = "") -> Dict[str, Any]:
    params: List[Any] = []
    where = [
        "s.is_active = 1",
        "f.is_current = 1",
        "f.file_object_id IS NOT NULL",
        "f.dimension_validated = 1",
        "f.dimension_policy_version = ?",
        "LOWER(COALESCE(fo.scan_status, '')) IN ('已通過', 'clean', 'passed')",
    ]
    params.append(EDOC_SEAL_DIMENSION_POLICY_VERSION)
    if company_id:
        where.append("s.company_id = ?")
        params.append(company_id)
    row = conn.execute(
        f"""
        SELECT s.id
        FROM company_seals s
        JOIN company_seal_files f ON f.seal_id = s.id
        JOIN file_objects fo ON fo.id = f.file_object_id
        WHERE {" AND ".join(where)}
        ORDER BY
          CASE s.seal_category
            WHEN 'general_seal' THEN 1
            WHEN 'official_seal' THEN 2
            WHEN 'establishment_seal' THEN 3
            WHEN 'bank_seal' THEN 4
            ELSE 9
          END,
          s.company_id,
          f.version DESC
        LIMIT 1
        """,
        params,
    ).fetchone()
    if not row:
        raise ValueError("launch_smoke_current_seal_required")
    return company_seal_row(conn, row["id"])


