def official_document_is_launch_smoke(document: Dict[str, Any]) -> bool:
    metadata = parse_json_any(document.get("metadata_json"), {}) or {}
    extra = metadata.get("extra") if isinstance(metadata.get("extra"), dict) else {}
    smoke_markers = {
        metadata.get("launch_smoke_journey"),
        metadata.get("source"),
        extra.get("journey"),
        extra.get("source"),
    }
    if smoke_markers & {"uploaded_pdf_stamping", "backend_launch_smoke_test", "frontend_launch_smoke_test"}:
        return True
    text = " ".join(str(document.get(key) or "") for key in ("title", "subject", "description", "request_reason"))
    return "去識別化" in text and "走測" in text


def launch_smoke_general_affairs_dispatch_candidate(conn: sqlite3.Connection, document_id: str = "") -> Dict[str, Any]:
    if document_id:
        document = official_document_row(conn, document_id)
        if not official_document_is_launch_smoke(document):
            raise ValueError("launch_smoke_dispatch_requires_smoke_document")
        return document
    rows = conn.execute(
        """
        SELECT d.*
        FROM official_documents d
        JOIN official_document_dispatch_records r ON r.document_id = d.id
        WHERE d.current_status = 'pending_general_affairs_dispatch'
          AND r.dispatch_owner_type = 'general_affairs'
          AND r.dispatch_status = 'pending'
        ORDER BY d.updated_at DESC
        LIMIT 50
        """
    ).fetchall()
    for row in rows:
        document = row_to_dict(row)
        if official_document_is_launch_smoke(document):
            return document
    raise ValueError("launch_smoke_dispatch_candidate_required")


def complete_general_affairs_dispatch_launch_smoke(
    conn: sqlite3.Connection,
    payload: Dict[str, Any] | None,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    payload = payload or {}
    user = official_session_user(session)
    document = launch_smoke_general_affairs_dispatch_candidate(conn, payload.get("document_id") or "")
    record = official_dispatch_record(conn, document["id"])
    if not record or record.get("dispatch_owner_type") != "general_affairs":
        raise ValueError("launch_smoke_dispatch_record_required")
    if document.get("current_status") != "pending_general_affairs_dispatch":
        raise ValueError("official_document_not_pending_general_affairs_dispatch")
    proof = build_launch_dispatch_proof_pdf()
    upload = upload_official_dispatch_proof_file(
        conn,
        document["id"],
        {
            "file_name": proof["file_name"],
            "file_mime_type": proof["mime_type"],
            "content_base64": base64.b64encode(proof["data"]).decode("ascii"),
            "ip_address": payload.get("ip_address") or "",
            "user_agent": payload.get("user_agent") or "",
        },
        session,
    )
    date_compact = datetime.now().strftime("%Y%m%d")
    completed = complete_official_dispatch(
        conn,
        document["id"],
        {
            "external_official_document_number": payload.get("external_official_document_number") or f"TEST-EDOC-{date_compact}-{secrets.token_hex(2).upper()}",
            "dispatch_date": payload.get("dispatch_date") or datetime.now().strftime("%Y-%m-%d"),
            "recipient": payload.get("recipient") or document.get("recipient") or "測試收件對象（去識別化）",
            "recipient_contact": payload.get("recipient_contact") or "recipient@example.invalid",
            "dispatch_note": payload.get("dispatch_note") or "去識別化走測：已用後端範本建立寄發證明並完成總務寄發紀錄。",
            "ip_address": payload.get("ip_address") or "",
            "user_agent": payload.get("user_agent") or "",
        },
        session,
    )
    insert_official_log(
        conn,
        document["id"],
        "launch_smoke_general_affairs_dispatch",
        user,
        "deidentified_dispatch_proof_completed",
        file_id=upload["file"]["id"],
        ip_address=payload.get("ip_address") or "",
        user_agent=payload.get("user_agent") or "",
    )
    return {
        "ok": True,
        "journey": "general_affairs_dispatch",
        "document": completed,
        "dispatch_record": completed.get("dispatch_record"),
        "proof_file": upload.get("file"),
        "next_action": "請由申請人回到申請單確認寄發紀錄與已用印版本。",
    }


def seal_file_metadata(row: Dict[str, Any]) -> Dict[str, Any]:
    allowed = {
        "id", "seal_id", "file_object_id", "file_name", "file_mime_type", "file_size",
        "file_hash", "version", "is_current", "uploaded_by", "uploaded_at",
        "pixel_width", "pixel_height", "source_aspect_ratio", "render_width_mm",
        "render_height_mm", "dimension_policy_version", "dimension_validated", "dimension_valid",
        "scan_status", "scan_engine", "last_scan_at", "av_clean", "usable",
    }
    metadata = {key: row.get(key) for key in allowed if key in row}
    try:
        if abs(float(metadata["render_width_mm"]) - float(metadata["render_height_mm"])) <= 0.000001:
            metadata["render_size_mm"] = float(metadata["render_width_mm"])
        metadata["render_width_pt"] = float(metadata["render_width_mm"]) * PDF_PT_PER_MM
        metadata["render_height_pt"] = float(metadata["render_height_mm"]) * PDF_PT_PER_MM
    except (KeyError, TypeError, ValueError):
        pass
    return metadata


SEAL_READINESS_PERMISSIONS = frozenset({"seals.manage", "settings.system_manage"})


def can_view_seal_vault_readiness(session: Dict[str, Any] | None) -> bool:
    """Keep company/seal deficiency details inside the custody-admin boundary."""
    return bool(session_permissions(session) & SEAL_READINESS_PERMISSIONS)


def assert_seal_company_scope(
    company: Dict[str, Any] | sqlite3.Row | None,
    session: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    """Authorize one Finance-owned launch company for a seal-vault operation.

    The company comes from the server-side EDOC mirror of Finance.  A seal
    custodian may work across the configured launch scope; ordinary compose or
    contract users remain restricted to the company in their server session.
    ``session=None`` is reserved for trusted backend jobs/tests and still has
    to pass the Finance/active/launch validation.
    """
    if not company:
        raise ValueError("company_not_found")
    item = row_to_dict(company) if isinstance(company, sqlite3.Row) else dict(company)
    company_id = str(item.get("id") or item.get("company_id") or "").strip()
    status = str(item.get("status") or "").strip().lower()
    if status not in {"active", "enabled", "啟用"}:
        raise PermissionError("seal_company_inactive")
    if str(item.get("source_system") or "").strip().lower() != "finance" or not str(
        item.get("finance_entity_id") or ""
    ).strip():
        raise PermissionError("seal_company_not_finance_linked")
    launch_ids = launch_company_scope_ids()
    if is_production() and launch_company_scope_mode() == "manual_allowlist" and not launch_ids:
        raise PermissionError("seal_company_launch_scope_required")
    if not launch_company_in_scope(company_id):
        raise PermissionError("seal_company_outside_launch_scope")
    if session is None:
        return item
    user = session.get("user") or {}
    if not user:
        raise PermissionError("authentication_required")
    try:
        require_seal_custodian_role(session)
    except PermissionError:
        pass
    else:
        return item
    if str(user.get("company_id") or "").strip() != company_id:
        raise PermissionError("seal_company_access_forbidden")
    return item


def assert_sqlite_seal_company_access(
    conn: sqlite3.Connection,
    company_id: str,
    session: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM companies WHERE id = ?", (str(company_id or ""),)).fetchone()
    return assert_seal_company_scope(row, session)


