def require_seal_custodian_role(session: Dict[str, Any] | None) -> Dict[str, Any]:
    """Authorize the two Finance identities allowed to mutate Seal Vault state.

    ``session=None`` is reserved for trusted backend initialization and tests.
    Browser permissions such as ``seals.manage`` are deliberately ignored.
    """
    if session is None:
        return {"id": "trusted-internal", "role": "trusted_internal"}
    user = session.get("user") if isinstance(session, dict) else None
    if not isinstance(user, dict):
        raise PermissionError("seal_custodian_role_required")
    account_source = roster_text(user.get("account_source")).lower()
    status = roster_text(user.get("status")).lower()
    role = re.sub(r"\s+", "", roster_text(user.get("role")))
    bridge = session.get("bridge") if isinstance(session.get("bridge"), dict) else {}
    logging_role_key = roster_text(
        user.get("logging_role_key")
        or user.get("loggingRoleKey")
        or bridge.get("loggingRoleKey")
        or bridge.get("logging_role_key")
    ).strip().lower()
    normalized_logging_role_key = re.sub(r"[\s-]+", "_", logging_role_key)
    unit = re.sub(
        r"\s+",
        "",
        roster_text(user.get("unit") or user.get("department")),
    )
    title = re.sub(r"\s+", "", roster_text(user.get("title")))
    if account_source != "finance" or status not in {"active", "enabled", "啟用"}:
        raise PermissionError("seal_custodian_role_required")
    if unit == "系統處" or normalized_logging_role_key == "system_department":
        raise PermissionError("seal_custodian_role_required")
    if role == "執行長":
        return user
    allowed_admin_titles = ("行政部主任", "行政部門主任", "行政部長")
    if (
        role in {"行政部主任", "行政部門主任"}
        and unit in {"行政部", "行政部門"}
        and any(value in title for value in allowed_admin_titles)
    ):
        return user
    raise PermissionError("seal_custodian_role_required")


def log_seal_usage(
    conn: sqlite3.Connection,
    *,
    action: str,
    actor_id: str = "API",
    usage_request_id: str = "",
    seal_id: str = "",
    document_id: str = "",
    detail: str = "",
    ip_address: str = "",
    user_agent: str = "",
) -> Dict[str, Any]:
    row = {
        "id": f"SLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "usage_request_id": usage_request_id or None,
        "seal_id": seal_id or None,
        "document_id": document_id or None,
        "action": action,
        "actor_id": actor_id,
        "ip_address": ip_address,
        "user_agent": user_agent,
        "detail": detail,
        "created_at": now(),
    }
    insert_row(conn, "seal_usage_logs", row)
    log_audit(conn, actor_id, action, "seal_usage", usage_request_id or seal_id or document_id, detail, event_type=action, module_code="seals")
    return row


def list_company_seals(
    conn: sqlite3.Connection,
    company_id: str,
    session: Dict[str, Any] | None = None,
) -> List[Dict[str, Any]]:
    assert_sqlite_seal_company_access(conn, company_id, session)
    rows = conn.execute(
        """
        SELECT s.*, c.name AS company_name, c.tax_id AS company_tax_id
        FROM company_seals s
        JOIN companies c ON c.id = s.company_id
        WHERE s.company_id = ?
        ORDER BY s.is_active DESC, s.seal_category, s.seal_size_type, s.created_at DESC
        """,
        (company_id,),
    ).fetchall()
    return [company_seal_row(conn, row["id"]) for row in rows]


def create_company_seal(conn: sqlite3.Connection, company_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    assert_sqlite_seal_company_access(conn, company_id, session)
    category = payload.get("seal_category") or payload.get("category") or "other"
    size_type = payload.get("seal_size_type") or payload.get("size_type") or "large_seal"
    if category not in seal_reference_codes(conn, "category"):
        raise ValueError("invalid_seal_category")
    if size_type not in seal_reference_codes(conn, "size"):
        raise ValueError("invalid_seal_size_type")
    actor = seal_actor(session, payload)
    seal_id = payload.get("id") or f"CSEAL-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    row = {
        "id": seal_id,
        "company_id": company_id,
        "seal_name": payload.get("seal_name") or payload.get("name") or "未命名印章",
        "seal_category": category,
        "seal_size_type": size_type,
        "purpose_description": payload.get("purpose_description") or payload.get("purpose") or "",
        "is_active": 1 if payload.get("is_active", True) else 0,
        "created_by": actor,
        "created_at": now(),
        "updated_at": now(),
        "deactivated_at": "",
    }
    insert_row(conn, "company_seals", row)
    for role in payload.get("default_permission_roles") or ["viewer", "requester", "approver", "seal_admin"]:
        if role not in seal_reference_codes(conn, "permission_role"):
            continue
        insert_row(conn, "seal_permissions", {
            "id": f"SPERM-{seal_id}-{role}",
            "seal_id": seal_id,
            "user_id": payload.get("user_id") or "",
            "role": role,
            "created_at": now(),
        })
    log_seal_usage(conn, action="create_seal", actor_id=actor, seal_id=seal_id, detail=row["seal_name"])
    return company_seal_row(conn, seal_id)


def patch_company_seal(conn: sqlite3.Connection, seal_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    assert_sqlite_seal_access(conn, seal_id, session)
    current_seal = company_seal_row(conn, seal_id)
    update: Dict[str, Any] = {}
    for source_key, target_key in [
        ("seal_name", "seal_name"),
        ("seal_category", "seal_category"),
        ("seal_size_type", "seal_size_type"),
        ("purpose_description", "purpose_description"),
        ("is_active", "is_active"),
    ]:
        if source_key in payload:
            update[target_key] = payload[source_key]
    if "seal_category" in update and update["seal_category"] not in seal_reference_codes(conn, "category"):
        raise ValueError("invalid_seal_category")
    if "seal_size_type" in update and update["seal_size_type"] not in seal_reference_codes(conn, "size"):
        raise ValueError("invalid_seal_size_type")
    if (
        "seal_size_type" in update
        and str(update["seal_size_type"]) != str(current_seal.get("seal_size_type") or "")
        and conn.execute("SELECT 1 FROM company_seal_files WHERE seal_id = ? LIMIT 1", (seal_id,)).fetchone()
    ):
        raise ValueError("seal_size_type_locked_after_upload")
    if "is_active" in update:
        update["is_active"] = 1 if update["is_active"] else 0
        update["deactivated_at"] = "" if update["is_active"] else now()
    update["updated_at"] = now()
    conn.execute(
        f"UPDATE company_seals SET {', '.join(f'{key} = ?' for key in update)} WHERE id = ?",
        [*update.values(), seal_id],
    )
    log_seal_usage(conn, action="update_seal", actor_id=seal_actor(session, payload), seal_id=seal_id, detail=json.dumps(update, ensure_ascii=False))
    return company_seal_row(conn, seal_id)


def deactivate_company_seal(conn: sqlite3.Connection, seal_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    row = patch_company_seal(conn, seal_id, {"is_active": False}, session)
    log_seal_usage(conn, action="deactivate_seal", actor_id=seal_actor(session), seal_id=seal_id, detail="soft_delete_only")
    return row


def decode_seal_file_content(content: str) -> bytes:
    try:
        return base64.b64decode(content, validate=True)
    except (binascii.Error, ValueError, TypeError) as exc:
        raise ValueError("seal_file_content_base64_invalid") from exc


def verify_seal_raster_image(data: bytes, expected_mime_type: str) -> Dict[str, Any]:
    """Fully decode a single-frame seal raster with bounded geometry."""
    try:
        from PIL import Image, UnidentifiedImageError
    except ImportError as exc:  # fail closed if the pinned decoder is absent
        raise RuntimeError("seal_image_decoder_unavailable") from exc

    format_mime_types = {"PNG": "image/png", "JPEG": "image/jpeg", "WEBP": "image/webp"}

    def inspect(image: Any) -> Tuple[str, int, int]:
        image_format = str(image.format or "").upper()
        detected_mime = format_mime_types.get(image_format, "")
        if not detected_mime:
            raise ValueError("seal_file_content_invalid")
        if detected_mime != expected_mime_type:
            raise ValueError("seal_file_mime_type_mismatch")
        width, height = (int(image.size[0]), int(image.size[1]))
        if width < 1 or height < 1:
            raise ValueError("seal_image_dimensions_invalid")
        if width > EDOC_SEAL_MAX_IMAGE_DIMENSION or height > EDOC_SEAL_MAX_IMAGE_DIMENSION:
            raise ValueError("seal_image_dimensions_exceeded")
        if width * height > EDOC_SEAL_MAX_IMAGE_PIXELS:
            raise ValueError("seal_image_pixels_exceeded")
        if int(getattr(image, "n_frames", 1) or 1) != 1:
            raise ValueError("animated_seal_image_not_allowed")
        return image_format, width, height

    warning_type = getattr(Image, "DecompressionBombWarning", RuntimeWarning)
    error_type = getattr(Image, "DecompressionBombError", Exception)
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("error", warning_type)
            with Image.open(io.BytesIO(data)) as probe:
                image_format, width, height = inspect(probe)
                probe.verify()
        # Pillow's verify() intentionally does not retain decoded pixels.  Open
        # the stream again and force load() so a valid header with corrupt or
        # truncated raster data can never become a Seal Vault version.
        with warnings.catch_warnings():
            warnings.simplefilter("error", warning_type)
            with Image.open(io.BytesIO(data)) as decoded:
                loaded_format, loaded_width, loaded_height = inspect(decoded)
                decoded.load()
                if (loaded_format, loaded_width, loaded_height) != (image_format, width, height):
                    raise ValueError("seal_image_decode_changed")
    except ValueError:
        raise
    except (warning_type, error_type) as exc:
        raise ValueError("seal_image_decompression_bomb") from exc
    except (UnidentifiedImageError, OSError, EOFError, SyntaxError) as exc:
        raise ValueError("seal_file_decode_invalid") from exc
    return {"format": image_format, "width": width, "height": height, "pixels": width * height}


def validate_seal_file_upload(
    file_name: str,
    mime_type: str,
    data: bytes,
    seal_size_type: str = "",
    render_width_mm: Any = None,
    render_height_mm: Any = None,
) -> Dict[str, Any]:
    configured_mime_types = {item.strip().lower() for item in EDOC_SEAL_ALLOWED_MIME_TYPES.split(",") if item.strip()}
    suffix = Path(file_name).suffix.lower().lstrip(".")
    normalized_mime = mime_type.lower()
    if suffix == "svg" or normalized_mime == "image/svg+xml":
        raise ValueError("unsafe_svg_rejected")
    fixed_mime_by_suffix = {
        "png": "image/png",
        "jpg": "image/jpeg",
        "jpeg": "image/jpeg",
        "webp": "image/webp",
    }
    if normalized_mime not in {"image/png", "image/jpeg", "image/webp"} or normalized_mime not in configured_mime_types:
        raise ValueError("seal_file_mime_type_not_allowed")
    if suffix not in fixed_mime_by_suffix:
        raise ValueError("seal_file_extension_not_allowed")
    if fixed_mime_by_suffix[suffix] != normalized_mime:
        raise ValueError("seal_file_mime_type_mismatch")
    max_bytes = EDOC_SEAL_FILE_MAX_SIZE_MB * 1024 * 1024
    if not data:
        raise ValueError("seal_file_content_required")
    if len(data) > max_bytes:
        raise ValueError("seal_file_too_large")
    inspection = verify_seal_raster_image(data, normalized_mime)
    return (
        validate_company_seal_raster_dimensions(
            seal_size_type,
            inspection,
            render_width_mm,
            render_height_mm,
        )
        if seal_size_type
        else inspection
    )


def scan_seal_upload_bytes(data: bytes, file_name: str) -> Tuple[str, str]:
    status, signature = editor_scan_bytes_for_threats(data, file_name)
    if status != "已通過":
        raise ValueError("seal_file_antivirus_rejected")
    return status, signature


def upload_company_seal_file(conn: sqlite3.Connection, seal_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    assert_sqlite_seal_access(conn, seal_id, session)
    seal = company_seal_row(conn, seal_id)
    if not seal.get("is_active"):
        raise ValueError("inactive_seal_cannot_upload_new_file")
    content = payload.get("content_base64") or ""
    if not content:
        raise ValueError("seal_file_content_required")
    data = decode_seal_file_content(content)
    file_name = Path(payload.get("file_name") or f"{seal_id}.png").name
    mime_type = payload.get("file_mime_type") or payload.get("mime_type") or "image/png"
    render_width_mm, render_height_mm = normalize_company_seal_upload_dimensions(payload)
    image_info = validate_seal_file_upload(
        file_name,
        mime_type,
        data,
        str(seal.get("seal_size_type") or ""),
        render_width_mm,
        render_height_mm,
    )
    scan_status, scan_signature = scan_seal_upload_bytes(data, file_name)
    actor = seal_actor(session, payload)
    owns_transaction = not conn.in_transaction
    savepoint = f"seal_upload_{secrets.token_hex(4)}"
    stored_path: Path | None = None
    try:
        if owns_transaction:
            conn.execute("BEGIN IMMEDIATE")
        else:
            conn.execute(f"SAVEPOINT {savepoint}")
            # SQLite has no SELECT ... FOR UPDATE.  A harmless write takes the
            # database write lock before max(version) is observed.
            conn.execute("UPDATE company_seals SET updated_at = updated_at WHERE id = ?", (seal_id,))
        next_version = conn.execute(
            "SELECT COALESCE(MAX(version), 0) + 1 AS version FROM company_seal_files WHERE seal_id = ?",
            (seal_id,),
        ).fetchone()["version"]
        file_row = store_file_object(
            conn,
            SEAL_VAULT_DOCUMENT_ID,
            file_name,
            data,
            f"{SEAL_VAULT_PURPOSE_PREFIX}/seals/{seal_id}",
            f"seal-v{next_version}",
            actor,
        )
        stored_path = STORAGE_DIR / file_row["storage_key"]
        conn.execute(
            """
            UPDATE file_objects
            SET mime_type = ?, storage_provider = ?, purpose = ?, scan_status = ?, scan_engine = ?,
                quarantine_reason = '', last_scan_at = ?
            WHERE id = ?
            """,
            (mime_type, "seal-vault", "seal-vault-original", scan_status, EDOC_SCAN_ENGINE, now(), file_row["id"]),
        )
        file_row = row_to_dict(conn.execute("SELECT * FROM file_objects WHERE id = ?", (file_row["id"],)).fetchone())
        conn.execute("UPDATE company_seal_files SET is_current = 0 WHERE seal_id = ?", (seal_id,))
        row = {
            "id": f"SFILE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "seal_id": seal_id,
            "file_object_id": file_row["id"],
            "file_storage_key": file_row["storage_key"],
            "file_name": file_name,
            "file_mime_type": mime_type,
            "file_size": len(data),
            "file_hash": sha256_bytes(data),
            "pixel_width": image_info["pixel_width"],
            "pixel_height": image_info["pixel_height"],
            "source_aspect_ratio": image_info["source_aspect_ratio"],
            "render_width_mm": image_info["render_width_mm"],
            "render_height_mm": image_info["render_height_mm"],
            "dimension_policy_version": image_info["dimension_policy_version"],
            "dimension_validated": 1,
            "version": int(next_version),
            "is_current": 1,
            "uploaded_by": actor,
            "uploaded_at": now(),
        }
        insert_row(conn, "company_seal_files", row)
        log_seal_usage(
            conn,
            action="upload_seal",
            actor_id=actor,
            seal_id=seal_id,
            detail=(
                f"version={next_version} hash={row['file_hash']} "
                f"pixels={image_info['pixel_width']}x{image_info['pixel_height']} "
                f"render_mm={image_info['render_width_mm']}x{image_info['render_height_mm']} "
                f"policy={EDOC_SEAL_DIMENSION_POLICY_VERSION} av={scan_signature}"
            ),
        )
        if owns_transaction:
            conn.commit()
        else:
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
    except Exception:
        if owns_transaction:
            conn.rollback()
        else:
            conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        if stored_path is not None:
            stored_path.unlink(missing_ok=True)
        raise
    return {"seal": company_seal_row(conn, seal_id), "file": seal_file_metadata(seal_file_with_backing_status(conn, row))}


def list_company_seal_files(conn: sqlite3.Connection, seal_id: str, session: Dict[str, Any] | None = None) -> List[Dict[str, Any]]:
    assert_sqlite_seal_access(conn, seal_id, session)
    company_seal_row(conn, seal_id)
    actor = seal_actor(session)
    log_seal_usage(conn, action="view_seal_metadata", actor_id=actor, seal_id=seal_id, detail="metadata_only")
    rows = conn.execute("SELECT * FROM company_seal_files WHERE seal_id = ? ORDER BY version DESC", (seal_id,)).fetchall()
    return [seal_file_metadata(seal_file_with_backing_status(conn, row)) for row in rows]


def set_current_seal_file(conn: sqlite3.Connection, file_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    row = conn.execute("SELECT * FROM company_seal_files WHERE id = ?", (file_id,)).fetchone()
    if not row:
        raise ValueError("seal_file_not_found")
    assert_sqlite_seal_access(conn, row["seal_id"], session)
    item = require_seal_file_av_clean(conn, row)
    seal = conn.execute(
        "SELECT seal_size_type FROM company_seals WHERE id = ?",
        (item["seal_id"],),
    ).fetchone()
    if not seal:
        raise ValueError("seal_not_found")
    require_company_seal_file_dimensions(item, seal["seal_size_type"], current=True)
    owns_transaction = not conn.in_transaction
    savepoint = f"seal_current_{secrets.token_hex(4)}"
    try:
        if owns_transaction:
            conn.execute("BEGIN IMMEDIATE")
        else:
            conn.execute(f"SAVEPOINT {savepoint}")
            conn.execute("UPDATE company_seals SET updated_at = updated_at WHERE id = ?", (item["seal_id"],))
        conn.execute("UPDATE company_seal_files SET is_current = 0 WHERE seal_id = ?", (item["seal_id"],))
        conn.execute("UPDATE company_seal_files SET is_current = 1 WHERE id = ?", (file_id,))
        log_seal_usage(
            conn,
            action="set_current_seal_file",
            actor_id=seal_actor(session),
            seal_id=item["seal_id"],
            detail=f"version={item['version']}",
        )
        if owns_transaction:
            conn.commit()
        else:
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
    except Exception:
        if owns_transaction:
            conn.rollback()
        else:
            conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        raise
    return company_seal_row(conn, item["seal_id"])


def seal_usage_request_row(
    conn: sqlite3.Connection,
    request_id: str,
    session: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    row = conn.execute(
        """
        SELECT r.*, c.name AS company_name, s.company_id AS seal_company_id,
               s.seal_name, s.seal_category, s.seal_size_type
        FROM seal_usage_requests r
        JOIN companies c ON c.id = r.company_id
        JOIN company_seals s ON s.id = r.seal_id
        WHERE r.id = ?
        """,
        (request_id,),
    ).fetchone()
    if not row:
        raise ValueError("seal_usage_request_not_found")
    data = row_to_dict(row)
    # Validate both persisted references.  Never authorize a legacy request
    # from a caller-supplied company filter, and fail closed if the request and
    # its seal have drifted across companies.
    assert_sqlite_seal_company_access(conn, str(data.get("company_id") or ""), session)
    assert_sqlite_seal_company_access(conn, str(data.get("seal_company_id") or ""), session)
    if data.get("company_id") != data.get("seal_company_id"):
        raise ValueError("seal_usage_request_company_mismatch")
    data.pop("seal_company_id", None)
    data["stamp_positions"] = parse_json_any(data.get("stamp_positions_json"), []) or []
    data["metadata"] = parse_json_any(data.get("metadata_json"), {}) or {}
    data["approvals"] = [row_to_dict(item) for item in conn.execute("SELECT * FROM seal_usage_approvals WHERE usage_request_id = ? ORDER BY approval_order", (request_id,)).fetchall()]
    data["logs"] = [row_to_dict(item) for item in conn.execute("SELECT * FROM seal_usage_logs WHERE usage_request_id = ? ORDER BY created_at DESC LIMIT 50", (request_id,)).fetchall()]
    return data


def company_seal_usage_lock_metadata(
    seal: Dict[str, Any],
    seal_file: Dict[str, Any],
) -> Dict[str, Any]:
    """Build the immutable evidence needed to reproduce one approved seal use."""
    profile = company_seal_file_dimension_profile(seal.get("seal_size_type"), seal_file)
    return {
        "seal_id": str(seal.get("id") or ""),
        "seal_file_id": str(seal_file.get("id") or ""),
        "seal_file_sha256": str(seal_file.get("file_hash") or ""),
        "seal_size_type": str(seal.get("seal_size_type") or ""),
        "render_size_mm": profile["width_mm"],
        "render_width_mm": profile["width_mm"],
        "render_height_mm": profile["height_mm"],
        "render_width_pt": profile["width_pt"],
        "render_height_pt": profile["height_pt"],
        "dimension_policy_version": profile["dimension_policy_version"],
    }


def canonicalize_company_seal_usage_positions(
    raw_positions: Any,
    seal: Dict[str, Any],
    seal_file: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """Normalize one-seal request positions and replace noise with exact PDF points."""
    profile = company_seal_file_dimension_profile(seal.get("seal_size_type"), seal_file, current=True)
    seal_id = str(seal.get("id") or "")
    if not raw_positions:
        raw_positions = [{
            "page": 1,
            "x": 420,
            "y": 130,
            "w": profile["width_pt"],
            "h": profile["height_pt"],
            "label": seal.get("seal_name") or "公司章",
            "type": seal.get("seal_category") or "general_seal",
            "seal_id": seal_id,
        }]
    positions = normalized_stamp_positions({
        "stamp_positions": raw_positions,
        "seal_id": seal_id,
    })
    canonical: List[Dict[str, Any]] = []
    for raw_position in positions:
        position = dict(raw_position)
        if str(position.get("seal_id") or seal_id) != seal_id:
            raise ValueError("seal_usage_request_seal_mismatch")
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"),
            position.get("w"),
            position.get("h"),
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
        )
        position.update({
            "seal_id": seal_id,
            "w": width,
            "h": height,
            "locked_seal_file_id": str(seal_file.get("id") or ""),
            "locked_seal_sha256": str(seal_file.get("file_hash") or ""),
            "locked_render_width_pt": profile["width_pt"],
            "locked_render_height_pt": profile["height_pt"],
            "locked_dimension_policy_version": profile["dimension_policy_version"],
        })
        canonical.append(position)
    return canonical


def validate_company_seal_usage_lock(
    request: Dict[str, Any],
    seal: Dict[str, Any],
    seal_file: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """Fail closed unless approved positions still bind to the exact Seal Vault version."""
    metadata = request.get("metadata")
    if not isinstance(metadata, dict):
        metadata = parse_json_any(request.get("metadata_json"), {}) or {}
    lock = metadata.get("seal_dimension_lock") if isinstance(metadata, dict) else None
    if not isinstance(lock, dict):
        raise ValueError("seal_dimension_lock_required")
    profile = company_seal_file_dimension_profile(seal.get("seal_size_type"), seal_file)
    expected = {
        "seal_id": str(seal.get("id") or ""),
        "seal_file_id": str(seal_file.get("id") or ""),
        "seal_file_sha256": str(seal_file.get("file_hash") or ""),
        "seal_size_type": str(seal.get("seal_size_type") or ""),
        "dimension_policy_version": profile["dimension_policy_version"],
    }
    for key, value in expected.items():
        if str(lock.get(key) or "") != value:
            raise ValueError("seal_dimension_lock_mismatch")
    for key, value in (
        ("render_width_mm", profile["width_mm"]),
        ("render_height_mm", profile["height_mm"]),
        ("render_width_pt", profile["width_pt"]),
        ("render_height_pt", profile["height_pt"]),
    ):
        try:
            supplied = float(lock.get(key))
        except (TypeError, ValueError) as exc:
            raise ValueError("seal_dimension_lock_mismatch") from exc
        tolerance = EDOC_SEAL_DIMENSION_TOLERANCE_PT if key.endswith("_pt") else 0.000001
        if not math.isfinite(supplied) or abs(supplied - float(value)) > tolerance:
            raise ValueError("seal_dimension_lock_mismatch")

    raw_positions = request.get("stamp_positions")
    if not isinstance(raw_positions, list) or not raw_positions:
        raise ValueError("locked_stamp_positions_required")
    canonical: List[Dict[str, Any]] = []
    for raw_position in raw_positions:
        if not isinstance(raw_position, dict):
            raise ValueError("invalid_stamp_position")
        position = dict(raw_position)
        if str(position.get("seal_id") or "") != expected["seal_id"]:
            raise ValueError("seal_usage_request_seal_mismatch")
        if (
            str(position.get("locked_seal_file_id") or "") != expected["seal_file_id"]
            or str(position.get("locked_seal_sha256") or "") != expected["seal_file_sha256"]
        ):
            raise ValueError("seal_dimension_lock_mismatch")
        width, height = validate_locked_company_seal_position(
            position,
            seal.get("seal_size_type"),
            seal_file,
        )
        position["w"] = width
        position["h"] = height
        canonical.append(position)
    return canonical


def locked_company_seal_usage_file(
    conn: sqlite3.Connection,
    request: Dict[str, Any],
    seal: Dict[str, Any],
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    metadata = request.get("metadata") if isinstance(request.get("metadata"), dict) else {}
    lock = metadata.get("seal_dimension_lock") if isinstance(metadata, dict) else None
    file_id = str(lock.get("seal_file_id") or "") if isinstance(lock, dict) else ""
    if not file_id:
        raise ValueError("seal_dimension_lock_required")
    row = conn.execute("SELECT * FROM company_seal_files WHERE id = ?", (file_id,)).fetchone()
    if not row:
        raise ValueError("locked_seal_file_not_found")
    file_meta = require_seal_file_av_clean(conn, row)
    if str(file_meta.get("seal_id") or "") != str(seal.get("id") or ""):
        raise ValueError("seal_dimension_lock_mismatch")
    positions = validate_company_seal_usage_lock(request, seal, file_meta)
    return file_meta, positions


def list_seal_usage_requests(
    conn: sqlite3.Connection,
    query: Dict[str, List[str]] | None = None,
    session: Dict[str, Any] | None = None,
) -> List[Dict[str, Any]]:
    query = query or {}
    where: List[str] = []
    params: List[Any] = []
    requested_company_id = str((query.get("company_id") or [""])[0] or "").strip()
    if session:
        user_company_id = str(((session.get("user") or {}).get("company_id") or "")).strip()
        if "seals.manage" in session_permissions(session):
            if requested_company_id:
                assert_sqlite_seal_company_access(conn, requested_company_id, session)
        else:
            if not user_company_id:
                raise PermissionError("seal_company_access_forbidden")
            assert_sqlite_seal_company_access(conn, user_company_id, session)
            if requested_company_id and requested_company_id != user_company_id:
                assert_sqlite_seal_company_access(conn, requested_company_id, session)
            requested_company_id = user_company_id
    if requested_company_id:
        where.append("r.company_id = ?")
        params.append(requested_company_id)
    for key, column in [("seal_id", "r.seal_id"), ("requested_by", "r.requested_by"), ("usage_type", "r.usage_type"), ("status", "r.status")]:
        if key in query and query[key]:
            where.append(f"{column} = ?")
            params.append(query[key][0])
    if "date_from" in query and query["date_from"]:
        where.append("r.requested_at >= ?")
        params.append(query["date_from"][0])
    if "date_to" in query and query["date_to"]:
        where.append("r.requested_at <= ?")
        params.append(query["date_to"][0])
    sql = """
        SELECT r.id
        FROM seal_usage_requests r
        JOIN company_seals s ON s.id = r.seal_id
    """
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY r.requested_at DESC LIMIT 300"
    results: List[Dict[str, Any]] = []
    for row in conn.execute(sql, params).fetchall():
        try:
            results.append(seal_usage_request_row(conn, row["id"], session))
        except PermissionError:
            # A seals.manage list without a company filter may encounter old
            # rows outside the current Finance/launch scope. Do not reveal or
            # let those rows block access to the authorized scope.
            if requested_company_id or "seals.manage" not in session_permissions(session):
                raise
    return results


def create_seal_usage_request(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    seal_id = payload.get("seal_id") or ""
    if not seal_id:
        raise ValueError("seal_id_required")
    assert_sqlite_seal_access(conn, seal_id, session)
    seal = company_seal_row(conn, seal_id)
    if not seal.get("is_active"):
        raise ValueError("inactive_seal_cannot_be_requested")
    seal_file = require_current_company_seal_file(conn, seal_id)
    usage_type = payload.get("usage_type") or "official_document"
    if usage_type not in seal_reference_codes(conn, "usage_type"):
        raise ValueError("invalid_usage_type")
    document = get_or_create_pdf_document(conn, {"document_id": document_id, **(payload.get("document") or {})})
    actor = seal_actor(session, payload)
    request_id = payload.get("id") or f"SREQ-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    requested_status = str(payload.get("status") or "pending")
    if requested_status not in {"draft", "pending"}:
        raise ValueError("invalid_initial_seal_request_status")
    positions = canonicalize_company_seal_usage_positions(
        payload.get("stamp_positions") or payload.get("positions") or [],
        seal,
        seal_file,
    )
    metadata = parse_json_any(payload.get("metadata"), {}) if isinstance(payload.get("metadata"), str) else dict(payload.get("metadata") or {})
    metadata["seal_dimension_lock"] = company_seal_usage_lock_metadata(seal, seal_file)
    row = {
        "id": request_id,
        "document_id": document["id"],
        "company_id": seal["company_id"],
        "seal_id": seal_id,
        "requested_by": actor,
        "request_reason": payload.get("request_reason") or payload.get("reason") or "",
        "usage_type": usage_type,
        "status": requested_status,
        "stamp_positions_json": json.dumps(positions, ensure_ascii=False),
        "stamped_pdf_version_id": None,
        "metadata_json": json.dumps(metadata, ensure_ascii=False),
        "requested_at": now(),
        "approved_at": "",
        "stamped_at": "",
        "updated_at": now(),
    }
    insert_row(conn, "seal_usage_requests", row)
    approvers = payload.get("approvers") or [{"approver_id": "seal_approver", "approval_order": 1}]
    for index, approver in enumerate(approvers, start=1):
        insert_row(conn, "seal_usage_approvals", {
            "id": f"SAPP-{request_id}-{index}",
            "usage_request_id": request_id,
            "approver_id": approver.get("approver_id") or approver.get("id") or "seal_approver",
            "approval_order": int(approver.get("approval_order") or index),
            "status": "pending",
            "comment": "",
            "approved_at": "",
            "created_at": now(),
            "updated_at": now(),
        })
    log_seal_usage(conn, action="request_use", actor_id=actor, usage_request_id=request_id, seal_id=seal_id, document_id=document["id"], detail=row["request_reason"])
    return seal_usage_request_row(conn, request_id, session)


def approve_seal_usage_request(conn: sqlite3.Connection, request_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    request = seal_usage_request_row(conn, request_id, session)
    if request["status"] not in {"pending", "draft"}:
        raise ValueError("seal_request_not_pending")
    seal = company_seal_row(conn, request["seal_id"])
    locked_company_seal_usage_file(conn, request, seal)
    actor = seal_actor(session, payload)
    pending = conn.execute("SELECT * FROM seal_usage_approvals WHERE usage_request_id = ? AND status = 'pending' ORDER BY approval_order LIMIT 1", (request_id,)).fetchone()
    if pending:
        conn.execute(
            "UPDATE seal_usage_approvals SET status = 'approved', approver_id = ?, comment = ?, approved_at = ?, updated_at = ? WHERE id = ?",
            (actor, payload.get("comment") or "核准用印。", now(), now(), pending["id"]),
        )
    remaining = conn.execute("SELECT COUNT(*) AS count FROM seal_usage_approvals WHERE usage_request_id = ? AND status = 'pending'", (request_id,)).fetchone()["count"]
    if remaining == 0:
        conn.execute("UPDATE seal_usage_requests SET status = 'approved', approved_at = ?, updated_at = ? WHERE id = ?", (now(), now(), request_id))
    log_seal_usage(conn, action="approve_use", actor_id=actor, usage_request_id=request_id, seal_id=request["seal_id"], document_id=request["document_id"], detail=payload.get("comment") or "")
    return seal_usage_request_row(conn, request_id, session)


def reject_seal_usage_request(conn: sqlite3.Connection, request_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    request = seal_usage_request_row(conn, request_id, session)
    if request["status"] in {"stamped", "cancelled"}:
        raise ValueError("seal_request_cannot_be_rejected")
    actor = seal_actor(session, payload)
    conn.execute("UPDATE seal_usage_approvals SET status = 'rejected', comment = ?, approved_at = ?, updated_at = ? WHERE usage_request_id = ? AND status = 'pending'", (payload.get("comment") or "駁回用印。", now(), now(), request_id))
    conn.execute("UPDATE seal_usage_requests SET status = 'rejected', updated_at = ? WHERE id = ?", (now(), request_id))
    log_seal_usage(conn, action="reject_use", actor_id=actor, usage_request_id=request_id, seal_id=request["seal_id"], document_id=request["document_id"], detail=payload.get("comment") or "")
    return seal_usage_request_row(conn, request_id, session)


def stamp_seal_usage_request(conn: sqlite3.Connection, request_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    request = seal_usage_request_row(conn, request_id, session)
    if request["status"] != "approved":
        raise ValueError("seal_request_must_be_approved_before_stamp")
    seal = company_seal_row(conn, request["seal_id"])
    if not seal.get("is_active"):
        raise ValueError("inactive_seal_cannot_stamp")
    file_meta, positions = locked_company_seal_usage_file(conn, request, seal)
    log_seal_usage(conn, action="read_seal_vault_for_stamp", actor_id=seal_actor(session, payload), usage_request_id=request_id, seal_id=request["seal_id"], document_id=request["document_id"], detail="authorized_backend_stamp_only")
    file_object, seal_bytes = read_file_object_bytes(conn, file_meta["file_object_id"])
    if sha256_bytes(seal_bytes) != file_meta["file_hash"]:
        raise ValueError("seal_file_hash_mismatch")
    stamp_no = payload.get("stamp_no") or f"STAMP-{request_id}-{int(time.time())}"
    result = pdf_stamp(conn, {
        "document_id": request["document_id"],
        "seal_id": request["seal_id"],
        "applicant": request.get("requested_by") or "申請人",
        "reason": request.get("request_reason") or "核准後自動用印",
        "stamp_no": stamp_no,
        "stamp_positions": positions,
        "coordinates": payload.get("coordinates") or {},
        "template": payload.get("template") or "公司用印文件",
        "_trusted_seal_asset": {
            "data": seal_bytes,
            "mime_type": file_meta.get("file_mime_type") or file_object.get("mime_type") or "image/png",
        },
    })
    conn.execute(
        "UPDATE seal_usage_requests SET status = 'stamped', stamped_at = ?, stamped_pdf_version_id = ?, updated_at = ? WHERE id = ?",
        (now(), result.get("pdf_version_id") or result.get("id") or "", now(), request_id),
    )
    conn.execute("UPDATE documents SET status = '已用印', updated_at = ? WHERE id = ?", (now(), request["document_id"]))
    actor = seal_actor(session, payload)
    log_seal_usage(conn, action="stamp_document", actor_id=actor, usage_request_id=request_id, seal_id=request["seal_id"], document_id=request["document_id"], detail=f"{stamp_no} seal_file_hash={file_meta['file_hash']}")
    refreshed = seal_usage_request_row(conn, request_id, session)
    return {"request": refreshed, "stamped_file": {"pdf_version_id": result.get("pdf_version_id") or result.get("id"), "file_object_id": result.get("file_object_id"), "sha256": result.get("sha256"), "stamp_no": stamp_no, "download_url": result.get("download_url")}}


OFFICIAL_UNIFIED_APPROVAL_STEPS = [
    {"key": "applicant_manager", "name": "申請人主管", "status": "pending_applicant_manager", "role": "主管", "required": True},
    {"key": "department_head", "name": "部門主任", "status": "pending_department_head", "role": "主任", "required": True},
    {"key": "ceo", "name": "執行長", "status": "pending_ceo", "role": "執行長", "required": False},
    {"key": "admin_director", "name": "行政部門主任", "status": "pending_admin_director", "role": "行政部主任", "required": True},
    {"key": "general_affairs_review", "name": "總務專員", "status": "pending_general_affairs_review", "role": "總務", "required": True},
    {"key": "applicant_confirm", "name": "申請人收件", "status": "stamped", "role": "申請人", "required": True},
]


def unified_official_workflow_steps(route_code: str = "A") -> List[Dict[str, Any]]:
    """Return the server-owned Finance organization approval chain.

    A/B share the same organization chain. C/D add the highest-level approver
    between the department director and the administrative director. The
    applicant's initial submit action is kept in the audit log; the final
    applicant receipt remains an explicit workflow step.
    """
    code = str(route_code or "A").strip().upper()
    if code not in {"A", "B", "C", "D"}:
        raise ValueError("invalid_official_seal_route")
    include_ceo = code in {"C", "D"}
    selected = [
        dict(step)
        for step in OFFICIAL_UNIFIED_APPROVAL_STEPS
        if step["key"] != "ceo" or include_ceo
    ]
    return [{**step, "order": index + 1} for index, step in enumerate(selected)]


OFFICIAL_FINANCE_APPLICANT_SKIPPED_STEPS = {
    # Finance's canonical section_chief is the role named 「課長」 in the
    # organization directory. A section chief is already the first manager in
    # the chain, so the separate applicant-manager approval must not be added.
    "section_chief": {"applicant_manager"},
    # Finance's canonical department_head is the role named 「主任」. The
    # applicant already represents both preceding organization levels.
    "department_head": {"applicant_manager", "department_head"},
}
OFFICIAL_FINANCE_CONDITIONAL_POLICY_VERSION = 1


def official_workflow_steps_for_finance_applicant(
    route_code: str,
    finance_role: Any,
) -> List[Dict[str, Any]]:
    """Derive the immutable route from the server-supplied Finance role.

    Only the two seniority reductions explicitly approved by policy are
    applied. In particular, team_lead and district_manager remain on the full
    chain; their titles are not aliases for Finance's section_chief role.
    """
    canonical_role = canonical_logging_role(finance_role)
    skipped = OFFICIAL_FINANCE_APPLICANT_SKIPPED_STEPS.get(canonical_role, set())
    selected = [
        step
        for step in unified_official_workflow_steps(route_code)
        if step["key"] not in skipped
    ]
    return [{**step, "order": index + 1} for index, step in enumerate(selected)]


def locked_official_finance_workflow_metadata(
    document: Dict[str, Any],
    snapshot: Dict[str, Any],
    finance_role: Any,
    workflow_steps: Iterable[Dict[str, Any]],
) -> Dict[str, Any]:
    """Persist a metadata-only, immutable explanation of the chosen route."""
    metadata = parse_json_field(document.get("metadata_json"))
    seal = dict(metadata.get("official_seal") or {})
    canonical_role = canonical_logging_role(finance_role)
    locked_steps = [
        {
            "order": int(step.get("order") or index),
            "key": str(step.get("key") or ""),
            "name": str(step.get("name") or ""),
            "role": str(step.get("role") or ""),
        }
        for index, step in enumerate(workflow_steps, start=1)
    ]
    bridge_metadata = finance_bridge_safe_snapshot_metadata(snapshot)
    seal.update({
        "approval_steps": locked_steps,
        "approval_step_keys": [step["key"] for step in locked_steps],
        "applicant_finance_role": canonical_role,
        "conditional_policy_version": OFFICIAL_FINANCE_CONDITIONAL_POLICY_VERSION,
        "finance_snapshot_sha256": bridge_metadata["snapshotSha256"],
        "finance_snapshot_at": bridge_metadata["snapshotAt"],
        "workflow_locked_at": now(),
    })
    metadata["official_seal"] = seal
    return metadata


