def official_seal_approval_context(payload: Dict[str, Any] | None = None) -> Dict[str, Any] | None:
    """Validate a client classification and derive the server-owned A-D route."""
    payload = payload or {}
    category = str(payload.get("document_category") or payload.get("documentCategory") or "").strip()
    requested_route = str(payload.get("approval_route_code") or payload.get("approvalRouteCode") or "").strip().upper()
    if not category and not requested_route:
        return None
    if not category:
        raise ValueError("official_seal_document_category_required")
    definition = OFFICIAL_SEAL_DOCUMENT_CATEGORIES.get(category)
    if not definition:
        raise ValueError("invalid_official_seal_document_category")
    route_code = definition["route"]
    if requested_route and requested_route != route_code:
        raise ValueError("official_seal_route_mismatch")
    return {
        "document_category": category,
        "document_category_group": definition["group"],
        "approval_route_code": route_code,
        "approval_route_name": OFFICIAL_SEAL_ROUTE_NAMES[route_code],
        "workflow_template_key": f"official_seal_route_{route_code.lower()}_v2",
        "route_version": 2,
    }


def official_seal_context_from_document(document: Dict[str, Any] | None) -> Dict[str, Any] | None:
    metadata = parse_json_field((document or {}).get("metadata_json"))
    stored = metadata.get("official_seal") if isinstance(metadata.get("official_seal"), dict) else None
    if not stored:
        return None
    return official_seal_approval_context(stored)


def official_seal_workflow_steps(route_code: str) -> List[Dict[str, Any]]:
    normalized = str(route_code or "").strip().upper()
    if normalized not in OFFICIAL_SEAL_ROUTE_APPROVAL_STEPS:
        raise ValueError("invalid_official_seal_route")
    return unified_official_workflow_steps(normalized)


def normalize_official_workflow_config(payload: Dict[str, Any] | None = None) -> Dict[str, Any]:
    payload = payload or {}
    # The approval chain is an organization policy, not a per-screen option.
    # Persist the canonical no-CEO chain for settings/readiness displays; C/D
    # routes are expanded by official_seal_workflow_steps on the server.
    steps = unified_official_workflow_steps("A")
    return {
        "key": "internal_official_dispatch_v2",
        "name": str(payload.get("name") or "發文與用印簽核流程"),
        "enabled_steps": [step["key"] for step in steps],
        "steps": steps,
        "locked": True,
        "updated_at": str(payload.get("updated_at") or now()),
    }


def local_official_workflow_config(conn: sqlite3.Connection) -> Dict[str, Any]:
    row = conn.execute("SELECT value_json FROM settings WHERE key = ?", (OFFICIAL_WORKFLOW_SETTING_KEY,)).fetchone()
    if not row:
        return normalize_official_workflow_config()
    return normalize_official_workflow_config(parse_json_field(row["value_json"]))


def save_local_official_workflow_config(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    config = normalize_official_workflow_config(payload)
    conn.execute(
        """
        INSERT INTO settings (key, value_json, version, updated_at) VALUES (?, ?, 1, ?)
        ON CONFLICT(key) DO UPDATE SET value_json = excluded.value_json, version = settings.version + 1, updated_at = excluded.updated_at
        """,
        (OFFICIAL_WORKFLOW_SETTING_KEY, json.dumps(config, ensure_ascii=False), now()),
    )
    return config


def official_workflow_steps_for_document(conn: sqlite3.Connection, document: Dict[str, Any]) -> List[Dict[str, Any]]:
    seal_context = official_seal_context_from_document(document)
    if seal_context:
        return official_seal_workflow_steps(seal_context["approval_route_code"])
    return unified_official_workflow_steps("A")


def official_workflow_step_sequence_matches(
    stored_steps: Iterable[Dict[str, Any]],
    expected_steps: Iterable[Dict[str, Any]],
) -> bool:
    stored = list(stored_steps)
    expected = list(expected_steps)
    if len(stored) != len(expected):
        return False
    return all(
        int(stored_step.get("step_order") or 0) == int(expected_step.get("order") or 0)
        and str(stored_step.get("step_key") or "") == str(expected_step.get("key") or "")
        for stored_step, expected_step in zip(stored, expected)
    )


