def official_session_user(session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = session.get("user") if session else None
    if not user:
        raise PermissionError("authentication_required")
    return user


def can_create_internal_dispatch(session: Dict[str, Any] | None) -> bool:
    user = session.get("user") if session else None
    return bool(user and user.get("role") in INTERNAL_DISPATCH_CREATOR_ROLES)


def require_internal_dispatch_creator(session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    if not can_create_internal_dispatch(session):
        raise PermissionError("internal_dispatch_create_forbidden")
    return user


def can_create_inbound_archive(session: Dict[str, Any] | None, source_type: str) -> bool:
    user = session.get("user") if session else None
    if not user:
        return False
    source = (source_type or "manual").strip()
    if source in LOCAL_INBOUND_ARCHIVE_SOURCE_TYPES:
        return True
    if source in GENERAL_AFFAIRS_INBOUND_SOURCE_TYPES:
        return user.get("role") == "總務" or session_has_any_permission(
            session,
            ["official_documents.receive"],
        )
    return False


def official_actor_name(user: Dict[str, Any] | None) -> str:
    if not user:
        return "System"
    return user.get("name") or user.get("email") or user.get("role") or user.get("id") or "API"


def official_company_row(conn: sqlite3.Connection, company_id: str) -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM companies WHERE id = ?", (company_id,)).fetchone()
    if not row:
        raise ValueError("company_not_found")
    return row_to_dict(row)


def official_document_row(conn: sqlite3.Connection, document_id: str) -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM official_documents WHERE id = ?", (document_id,)).fetchone()
    if not row:
        raise ValueError("official_document_not_found")
    return row_to_dict(row)


def active_user_by_role(
    conn: sqlite3.Connection,
    role: str,
    exclude_user_id: str = "",
    company_id: str = "",
) -> Dict[str, Any] | None:
    params: List[Any] = [role]
    sql = "SELECT * FROM users WHERE role = ? AND status = '啟用'"
    if exclude_user_id:
        sql += " AND id <> ?"
        params.append(exclude_user_id)
    if company_id:
        sql += " AND company_id = ?"
        params.append(company_id)
    sql += " ORDER BY rowid LIMIT 1"
    row = conn.execute(sql, params).fetchone()
    return row_to_dict(row) if row else None


def active_user_by_id(conn: sqlite3.Connection, user_id: str) -> Dict[str, Any] | None:
    row = conn.execute("SELECT * FROM users WHERE id = ? AND status = '啟用'", (user_id,)).fetchone()
    return row_to_dict(row) if row else None


def select_active_finance_reference_user(
    rows: Iterable[Dict[str, Any]],
    employee_id: str = "",
    email: str = "",
    exclude_user_id: str = "",
) -> Dict[str, Any] | None:
    """Resolve every supplied Finance identifier to one unique active actor."""
    expected_employee_id = str(employee_id or "").strip()
    expected_email = str(email or "").strip().lower()
    if not expected_employee_id and not expected_email:
        return None

    unique_rows: Dict[str, Dict[str, Any]] = {}
    for raw_row in rows:
        row = dict(raw_row)
        row_id = str(row.get("id") or "").strip()
        if (
            row_id
            and str(row.get("status") or "") == "啟用"
            and str(row.get("account_source") or "").strip().lower() == "finance"
        ):
            unique_rows[row_id] = row

    resolved_sets: List[set[str]] = []
    if expected_employee_id:
        employee_matches = {
            row_id
            for row_id, row in unique_rows.items()
            if str(row.get("finance_employee_id") or "").strip() == expected_employee_id
        }
        if len(employee_matches) != 1:
            return None
        resolved_sets.append(employee_matches)
    if expected_email:
        email_matches = {
            row_id
            for row_id, row in unique_rows.items()
            if str(row.get("email") or "").strip().lower() == expected_email
        }
        if len(email_matches) != 1:
            return None
        resolved_sets.append(email_matches)

    resolved_ids = set.intersection(*resolved_sets) if resolved_sets else set()
    if len(resolved_ids) != 1:
        return None
    resolved_id = next(iter(resolved_ids))
    if exclude_user_id and resolved_id == str(exclude_user_id):
        return None
    return unique_rows[resolved_id]


def active_user_by_finance_identity(conn: sqlite3.Connection, employee_id: str = "", email: str = "", exclude_user_id: str = "") -> Dict[str, Any] | None:
    expected_employee_id = str(employee_id or "").strip()
    expected_email = str(email or "").strip().lower()
    if not expected_employee_id and not expected_email:
        return None
    rows = conn.execute(
        """
        SELECT * FROM users
        WHERE status = '啟用'
          AND (
            (? <> '' AND finance_employee_id = ?)
            OR (? <> '' AND lower(email) = ?)
          )
        ORDER BY rowid
        """,
        (expected_employee_id, expected_employee_id, expected_email, expected_email),
    ).fetchall()
    return select_active_finance_reference_user(
        (row_to_dict(row) for row in rows),
        expected_employee_id,
        expected_email,
        exclude_user_id,
    )


OFFICIAL_WORKFLOW_ACTOR_DIRECTORY = {
    "applicant_manager": {
        "roles": ("主管", "主任"),
        "logging_roles": ("section_chief", "team_lead", "district_manager"),
    },
    "department_head": {
        "roles": ("主任", "主管"),
        "logging_roles": ("department_head",),
    },
    "ceo": {"roles": ("執行長",), "logging_roles": ("ceo",)},
    "admin_director": {"roles": ("行政部主任",), "logging_roles": ("admin_director",)},
    "general_affairs_review": {"roles": ("總務",), "logging_roles": ("ga_chief",)},
}


def workflow_user_company_score(
    user: Dict[str, Any],
    company: Dict[str, Any],
) -> int | None:
    """Rank same-company Finance users and reject cross-company assignments."""
    company_id = str(company.get("id") or "")
    company_name = str(company.get("name") or "")
    user_company_id = str(user.get("company_id") or "")
    user_company_name = str(user.get("company_name") or "")
    if company_id and user_company_id == company_id:
        return 0
    if company_name and user_company_name == company_name:
        return 1
    if user_company_id or user_company_name:
        return None
    # Old SQLite fixtures and non-production roster imports predate company
    # identifiers. Keep that compatibility only outside production; production
    # must never route an approval to an unscoped account.
    return 3 if not is_production() else None


def active_workflow_user(
    conn: sqlite3.Connection,
    step_key: str,
    company: Dict[str, Any],
    *,
    unit: str = "",
    exclude_user_id: str = "",
    exclude_user_ids: Iterable[str] = (),
    extra_roles: Iterable[str] = (),
) -> Dict[str, Any] | None:
    directory = OFFICIAL_WORKFLOW_ACTOR_DIRECTORY.get(step_key) or {}
    roles = {str(role) for role in (*directory.get("roles", ()), *extra_roles) if role}
    logging_roles = {str(role) for role in directory.get("logging_roles", ()) if role}
    excluded = {str(value) for value in (*exclude_user_ids, exclude_user_id) if value}
    candidates: List[Tuple[Tuple[int, int, int, int, int], Dict[str, Any]]] = []
    shared_candidates: Dict[str, Dict[str, Any]] = {}
    rows = conn.execute(
        "SELECT rowid AS workflow_rowid, * FROM users WHERE status = '啟用' ORDER BY rowid"
    ).fetchall()
    for row in rows:
        user = row_to_dict(row)
        if user.get("id") in excluded:
            continue
        role_match = user.get("role") in roles
        logging_match = canonical_logging_role(user.get("logging_role_key")) in logging_roles
        if not role_match and not logging_match:
            continue
        if (
            step_key in {"ceo", "admin_director", "general_affairs_review"}
            and str(user.get("account_source") or "").lower() == "finance"
            and user.get("company_id")
            and launch_company_in_scope(str(user.get("company_id")))
        ):
            shared_candidates[str(user.get("id") or "")] = user
        company_score = workflow_user_company_score(user, company)
        if company_score is None:
            continue
        unit_score = 0 if unit and str(user.get("unit") or "") == unit else 1
        finance_score = 0 if str(user.get("account_source") or "").lower() == "finance" else 1
        candidates.append((
            (
                company_score,
                0 if logging_match else 1,
                unit_score,
                finance_score,
                int(user.get("workflow_rowid") or 0),
            ),
            user,
        ))
    scoped = [item for item in candidates if item[0][0] < 3]
    if scoped:
        return min(scoped, key=lambda item: item[0])[1]
    # Finance may expose group shared-service actors under a different company.
    # Fall back only when exactly one active Finance-linked role holder exists
    # inside the launch scope; ambiguity remains fail-closed.
    if len(shared_candidates) == 1:
        return next(iter(shared_candidates.values()))
    if len(shared_candidates) > 1:
        return None
    if candidates:
        return min(candidates, key=lambda item: item[0])[1]
    return None


def official_department_head_role(conn: sqlite3.Connection, company: Dict[str, Any], department_name: str) -> str:
    row = conn.execute(
        """
        SELECT manager_role FROM department_registry
        WHERE status = '啟用' AND company_name = ? AND name = ?
        ORDER BY rowid LIMIT 1
        """,
        (company.get("name") or "", department_name or ""),
    ).fetchone()
    return row["manager_role"] if row else "主任"


def resolve_official_step_approver(conn: sqlite3.Connection, step: Dict[str, Any], applicant: Dict[str, Any], company: Dict[str, Any]) -> Dict[str, Any] | None:
    key = step["key"]
    if key == "applicant_confirm":
        return applicant
    if key == "applicant_manager":
        manager = active_user_by_finance_identity(
            conn,
            applicant.get("manager_employee_id") or "",
            applicant.get("manager_email") or "",
            applicant.get("id") or "",
        )
        if manager:
            return manager
        if finance_workflow_actor(applicant):
            # Finance is authoritative for direct-report relationships. A
            # missing or stale manager reference must block submit, not silently
            # fall back to an unrelated global role holder.
            return None
        return active_workflow_user(
            conn,
            key,
            company,
            unit=applicant.get("unit") or "",
            exclude_user_id=applicant.get("id") or "",
        )
    if key == "department_head":
        direct_manager = active_user_by_finance_identity(
            conn,
            applicant.get("manager_employee_id") or "",
            applicant.get("manager_email") or "",
            applicant.get("id") or "",
        )
        approval_manager = active_user_by_finance_identity(
            conn,
            applicant.get("approval_manager_employee_id") or "",
            applicant.get("approval_manager_email") or "",
            applicant.get("id") or "",
        )
        # Finance may intentionally use the same approvalManager as manager.
        # Preserve that organization decision as two consecutive approvals.
        if approval_manager:
            return approval_manager
        if finance_workflow_actor(applicant):
            # Finance approvalManager is authoritative for the department-head
            # step. Missing/stale references may never fall back to any other
            # same-company director.
            return None
        department_role = official_department_head_role(conn, company, applicant.get("unit") or "")
        return active_workflow_user(
            conn,
            key,
            company,
            unit=applicant.get("unit") or "",
            exclude_user_ids=(applicant.get("id") or "", (direct_manager or {}).get("id") or ""),
            extra_roles=(department_role,),
        )
    return active_workflow_user(conn, key, company)


def finance_workflow_actor(user: Dict[str, Any] | None) -> bool:
    return bool(user and str(user.get("account_source") or "").strip().lower() == "finance")


def finance_actor_matches_reference(
    actor: Dict[str, Any] | None,
    employee_id: str = "",
    email: str = "",
) -> bool:
    if not actor:
        return False
    expected_employee_id = str(employee_id or "").strip()
    expected_email = str(email or "").strip().lower()
    if not expected_employee_id and not expected_email:
        return False
    employee_matches = (
        not expected_employee_id
        or str(actor.get("finance_employee_id") or "").strip() == expected_employee_id
    )
    email_matches = (
        not expected_email
        or str(actor.get("email") or "").strip().lower() == expected_email
    )
    return employee_matches and email_matches


def finance_workflow_step_failure_reason(
    step: Dict[str, Any],
    applicant: Dict[str, Any],
    approver: Dict[str, Any] | None,
) -> str:
    key = str(step.get("key") or "")
    if (
        key != "applicant_confirm"
        and approver
        and str(approver.get("id") or "") == str(applicant.get("id") or "")
    ):
        return "self_assignment"
    if key == "applicant_manager":
        employee_id = str(applicant.get("manager_employee_id") or "").strip()
        email = str(applicant.get("manager_email") or "").strip()
        if not employee_id and not email:
            return "finance_relationship_missing"
        if not approver:
            return "actor_not_found"
        if not finance_actor_matches_reference(approver, employee_id, email):
            return "finance_relationship_unresolved"
    elif key == "department_head":
        employee_id = str(applicant.get("approval_manager_employee_id") or "").strip()
        email = str(applicant.get("approval_manager_email") or "").strip()
        if not employee_id and not email:
            return "finance_relationship_missing"
        if not approver:
            return "actor_not_found"
        if not finance_actor_matches_reference(approver, employee_id, email):
            return "finance_relationship_unresolved"
    elif not approver:
        return "actor_not_found"
    if not finance_workflow_actor(approver):
        return "non_finance_actor"
    return ""


def require_valid_finance_workflow_step_actor(
    step: Dict[str, Any],
    applicant: Dict[str, Any],
    approver: Dict[str, Any] | None,
    *,
    seal_context: Dict[str, Any] | None = None,
) -> None:
    """Apply the canonical Finance actor gate to new and reused workflow steps."""
    if not finance_workflow_actor(applicant):
        return
    normalized_step = {**step, "key": step.get("key") or step.get("step_key") or ""}
    reason = finance_workflow_step_failure_reason(normalized_step, applicant, approver)
    if not reason:
        return
    error = "official_seal_route_actor_unresolved" if seal_context else "official_workflow_actor_unresolved"
    step_key = str(normalized_step.get("key") or "unknown")
    raise ValueError(f"{error}:{step_key}:{reason}")


INTERNAL_LAUNCH_WORKFLOW_FAILURE_LABELS = {
    "finance_applicant_missing": "缺少啟用的 Finance 申請人",
    "finance_relationship_missing": "Finance 組織關係未提供",
    "finance_relationship_unresolved": "Finance 組織關係無法解析",
    "actor_not_found": "找不到可解析的 Finance actor",
    "actor_resolution_error": "Finance actor 解析失敗",
    "non_finance_actor": "解析結果不是 Finance actor",
    "self_assignment": "簽核人不可為申請人本人",
}


def build_internal_launch_workflow_readiness(
    companies: List[Dict[str, Any]],
    applicants_by_company: Dict[str, List[Dict[str, Any]]],
    resolve_step: Any,
) -> Dict[str, Any]:
    """Build a metadata-only Finance actor matrix for every launch company.

    No user id, name, email, PDF content, or document payload is returned.  An
    applicant ordinal is sufficient to identify which de-identified chain
    needs repair when a company has more than one Finance applicant.
    """
    blockers: List[str] = []
    route_checks: List[Dict[str, Any]] = []
    workflow_steps: List[Dict[str, Any]] = []
    applicant_coverage: List[Dict[str, Any]] = []
    for company in companies:
        company_id = str(company.get("id") or company.get("company_id") or "").strip()
        applicants = list(applicants_by_company.get(company_id) or [])
        applicants.sort(key=lambda item: (str(item.get("role") or ""), str(item.get("id") or "")))
        applicant_coverage.append({
            "company_id": company_id,
            "financeApplicantCount": len(applicants),
            # A canonical legal entity with no enabled Finance applicant has
            # no route to exercise yet. Keep it in company parity reporting,
            # but do not invent a user or fail every route for an empty entity.
            "applicable": bool(applicants),
            "ready": True,
        })
        if not applicants:
            continue
        for applicant_index, applicant in enumerate(applicants, start=1):
            for route_code in INTERNAL_LAUNCH_WORKFLOW_ROUTE_CODES:
                step_checks: List[Dict[str, Any]] = []
                missing_steps: List[str] = []
                # Readiness must evaluate the same server-owned conditional
                # route used at submit time.  Otherwise a 課長／主任 would be
                # reported as blocked by an actor for a step that is correctly
                # omitted from their real workflow.
                applicant_steps = official_workflow_steps_for_finance_applicant(
                    route_code,
                    applicant.get("logging_role_key") or "staff",
                )
                for step in applicant_steps:
                    try:
                        approver = resolve_step(step, applicant, company)
                        reason = finance_workflow_step_failure_reason(step, applicant, approver)
                    except Exception:
                        # Readiness must remain actionable without disclosing a
                        # service error, account identifier, or Finance payload.
                        approver = None
                        reason = "actor_resolution_error"
                    step_ready = not reason
                    step_check = {
                        "company_id": company_id,
                        "route": route_code,
                        "applicantOrdinal": applicant_index,
                        "applicantRole": str(applicant.get("role") or ""),
                        "step_key": step["key"],
                        "step_name": step["name"],
                        "role": step["role"],
                        "ready": step_ready,
                        "actorSource": "finance" if finance_workflow_actor(approver) else "unresolved",
                        "failureReason": reason,
                    }
                    step_checks.append(step_check)
                    workflow_steps.append(dict(step_check))
                    if step_ready:
                        continue
                    missing_steps.append(step["key"])
                    blockers.append(
                        f"公司 {company_id} / route {route_code} / applicant #{applicant_index} / "
                        f"step {step['key']}：{INTERNAL_LAUNCH_WORKFLOW_FAILURE_LABELS.get(reason, '無法解析 Finance actor')}。"
                    )
                route_checks.append({
                    "company_id": company_id,
                    "route": route_code,
                    "applicantOrdinal": applicant_index,
                    "applicantRole": str(applicant.get("role") or ""),
                    "ready": not missing_steps,
                    "missingSteps": missing_steps,
                    "steps": step_checks,
                })
    blockers = list(dict.fromkeys(blockers))
    return {
        "ready": bool(companies) and bool(route_checks) and all(item["ready"] for item in route_checks),
        "applicantReady": bool(companies) and all(item["ready"] for item in applicant_coverage),
        "routeCodes": list(INTERNAL_LAUNCH_WORKFLOW_ROUTE_CODES),
        "companyCount": len(companies),
        "applicableCompanyCount": sum(1 for item in applicant_coverage if item["applicable"]),
        "applicantCoverage": applicant_coverage,
        "routeChecks": route_checks,
        "workflowSteps": workflow_steps,
        "blockers": blockers,
    }


def internal_launch_finance_applicants_by_company(
    conn: sqlite3.Connection,
    companies: List[Dict[str, Any]],
) -> Dict[str, List[Dict[str, Any]]]:
    placeholders = ", ".join("?" for _ in INTERNAL_LAUNCH_APPLICANT_ROLES)
    rows = [
        row_to_dict(row)
        for row in conn.execute(
            f"""
            SELECT * FROM users
            WHERE status = '啟用'
              AND lower(COALESCE(account_source, '')) = 'finance'
              AND role IN ({placeholders})
            ORDER BY role, id
            """,
            tuple(INTERNAL_LAUNCH_APPLICANT_ROLES),
        ).fetchall()
    ]
    result: Dict[str, List[Dict[str, Any]]] = {}
    for company in companies:
        company_id = str(company.get("id") or company.get("company_id") or "")
        result[company_id] = [
            user
            for user in rows
            if workflow_user_company_score(user, company) in {0, 1}
        ]
    return result


def first_internal_launch_applicant(conn: sqlite3.Connection) -> Dict[str, Any] | None:
    placeholders = ", ".join("?" for _ in INTERNAL_LAUNCH_APPLICANT_ROLES)
    row = conn.execute(
        f"""
        SELECT * FROM users
        WHERE status = '啟用' AND role IN ({placeholders})
        ORDER BY CASE role WHEN '業務助理' THEN 0 WHEN '員工' THEN 1 ELSE 2 END, rowid
        LIMIT 1
        """,
        tuple(INTERNAL_LAUNCH_APPLICANT_ROLES),
    ).fetchone()
    return row_to_dict(row) if row else None


def internal_launch_user_counts(conn: sqlite3.Connection) -> Dict[str, int]:
    roles = list(dict.fromkeys([*INTERNAL_LAUNCH_APPLICANT_ROLES, *INTERNAL_LAUNCH_REQUIRED_ROLES]))
    counts: Dict[str, int] = {}
    for role in roles:
        counts[role] = conn.execute(
            "SELECT COUNT(*) AS count FROM users WHERE status = '啟用' AND role = ?",
            (role,),
        ).fetchone()["count"]
    return counts


def user_is_demo_seed_account(user: Dict[str, Any]) -> bool:
    return str(user.get("email") or "").lower() in DEMO_LOGIN_EMAILS


def user_has_formal_login_identity(user: Dict[str, Any]) -> bool:
    """Mirror the signed Finance Portal gate without mixing Auth namespaces.

    Finance and eDoc intentionally use separate Supabase Auth namespaces.  A
    valid signed Portal handoff therefore does not need an eDoc ``auth_user_id``
    on the mirror row.  Readiness instead requires the revisioned Finance
    identity, active source state and canonical company that the production
    session resolver actually verifies.  This keeps hand-created or stale rows
    fail-closed without falsely rejecting legitimate Finance SSO accounts.
    """
    finance_identity = str(
        user.get("logging_account_id")
        or user.get("finance_employee_id")
        or ""
    ).strip()
    try:
        source_revision = int(user.get("finance_source_revision") or 0)
    except (TypeError, ValueError):
        source_revision = 0
    return bool(
        not user_is_demo_seed_account(user)
        and str(user.get("account_source") or "").strip().lower() == "finance"
        and finance_identity
        and str(user.get("finance_source_status") or "").strip().lower() == "active"
        and source_revision > 0
        and str(user.get("finance_source_event_id") or "").strip()
        and str(user.get("company_id") or "").strip()
    )


def internal_launch_access_readiness(conn: sqlite3.Connection, role_counts: Dict[str, int]) -> Dict[str, Any]:
    rows = [
        row_to_dict(row)
        for row in conn.execute(
            """
            SELECT id, account_source, logging_account_id, finance_employee_id,
                   finance_source_revision, finance_source_event_id, finance_source_status,
                   auth_user_id, company_id, last_synced_from_logging_at,
                   name, email, password_hash, role, provider, mfa_status, status, last_login_at
            FROM users
            WHERE status = '啟用'
            ORDER BY role, email
            """
        ).fetchall()
    ]
    expected_roles = list(dict.fromkeys([*INTERNAL_LAUNCH_APPLICANT_ROLES, *INTERNAL_LAUNCH_REQUIRED_ROLES]))
    role_checks: List[Dict[str, Any]] = []
    for role in expected_roles:
        role_users = [user for user in rows if user.get("role") == role]
        formal_users = [user for user in role_users if user_has_formal_login_identity(user)]
        demo_users = [user for user in role_users if user_is_demo_seed_account(user)]
        role_checks.append({
            "role": role,
            "activeCount": len(role_users),
            "formalAccountCount": len(formal_users),
            "demoSeedCount": len(demo_users),
            "hasActiveUser": bool(role_users),
            "hasFormalAccount": bool(formal_users),
        })
    required_roles = ["員工", "主管", "主任", "行政部主任", "總務"]
    missing_active = [role for role in required_roles if role_counts.get(role, 0) < 1]
    missing_formal = [check["role"] for check in role_checks if check["role"] in required_roles and not check["hasFormalAccount"]]
    demo_seed_count = sum(1 for user in rows if user_is_demo_seed_account(user))
    password_login_candidates = sum(1 for user in rows if user.get("password_hash"))
    demo_policy = demo_account_policy_status()
    checks = {
        "activeUserCount": len(rows),
        "demoSeedUserCount": demo_seed_count,
        "passwordLoginCandidateCount": password_login_candidates,
        "demoAccountsDisabled": demo_policy["disabled"],
        "demoAccountsExplicitlyDisabled": demo_policy["explicitDisable"],
        "demoAccountsSafeDefault": demo_policy["safeDefault"],
        "demoAccountsExplicitlyAllowed": demo_policy["explicitAllow"],
        "production": is_production(),
        "roleChecks": role_checks,
    }
    blockers = [f"缺少啟用的「{role}」正式帳號。" for role in missing_active]
    warnings: List[str] = []
    if missing_formal:
        message = f"角色尚未看到非 seed/demo 或外部同步帳號：{'、'.join(missing_formal)}。"
        if is_production():
            blockers.append(message)
        else:
            warnings.append(message)
    if demo_seed_count and not demo_policy["disabled"]:
        warnings.append("仍可使用 seed/demo 帳號政策；正式站需設定 EDOC_DISABLE_DEMO_ACCOUNTS=true。")
    if demo_seed_count and demo_policy["disabled"] and not demo_policy["explicitDisable"]:
        warnings.append("正式站 seed/demo 帳號已由安全預設阻擋；IT 仍需設定 EDOC_DISABLE_DEMO_ACCOUNTS=true 留存明確政策。")
    if demo_policy["disabled"] and demo_seed_count and password_login_candidates == demo_seed_count:
        warnings.append("目前啟用帳號看起來多為 seed/demo 帳號；請確認正式帳號或 Logging Portal 已匯入。")
    return {
        "ready": not blockers,
        "blockers": blockers,
        "warnings": warnings,
        "checks": checks,
        "summary": f"activeUsers={len(rows)}；demoSeedUsers={demo_seed_count}；formalRoleMissing={len(missing_formal)}",
    }


def internal_launch_companies(conn: sqlite3.Connection) -> Tuple[List[Dict[str, Any]], Dict[str, Any], List[Dict[str, Any]]]:
    all_companies = [
        row_to_dict(row)
        for row in conn.execute("SELECT * FROM companies WHERE status IN ('active', '啟用') ORDER BY id").fetchall()
    ]
    companies, scope = filter_launch_companies(all_companies)
    return companies, scope, all_companies


def internal_launch_company_seal_checks(conn: sqlite3.Connection) -> Tuple[List[Dict[str, Any]], List[str]]:
    companies, scope, all_companies = internal_launch_companies(conn)
    blockers: List[str] = launch_company_scope_blockers(all_companies, scope)
    checks: List[Dict[str, Any]] = []
    if blockers and not companies:
        return checks, blockers
    for company in companies:
        company_check = {
            "company_id": company["id"],
            "company_name": company.get("name") or company["id"],
            "launchScopeIncluded": True,
            "requiredSeals": [],
        }
        for category, label in INTERNAL_LAUNCH_REQUIRED_SEAL_CATEGORIES.items():
            rows = conn.execute(
                """
                SELECT s.id, s.seal_name, s.seal_category,
                       EXISTS (
                         SELECT 1
                         FROM company_seal_files f
                         JOIN file_objects fo ON fo.id = f.file_object_id
                         WHERE f.seal_id = s.id AND f.is_current = 1
                           AND LOWER(COALESCE(fo.scan_status, '')) IN ('已通過', 'clean', 'passed')
                       ) AS has_current_file,
                       EXISTS (
                         SELECT 1 FROM company_seal_files f
                         WHERE f.seal_id = s.id AND f.is_current = 1
                       ) AS has_designated_current
                FROM company_seals s
                WHERE s.company_id = ? AND s.is_active = 1 AND s.seal_category = ?
                ORDER BY s.seal_size_type, s.created_at
                """,
                (company["id"], category),
            ).fetchall()
            has_active = bool(rows)
            has_current = any(bool(row["has_current_file"]) for row in rows)
            has_unscanned_current = any(bool(row["has_designated_current"]) and not bool(row["has_current_file"]) for row in rows)
            current_row = next((row for row in rows if bool(row["has_current_file"])), None)
            company_check["requiredSeals"].append({
                "category": category,
                "label": label,
                "active": has_active,
                "currentFile": has_current,
                "sealCount": len(rows),
                "sealIds": [row["id"] for row in rows],
                "firstSealId": rows[0]["id"] if rows else "",
                "currentSealId": current_row["id"] if current_row else "",
                "nextAction": (
                    "已具備 AV 通過的 current 版本"
                    if has_current
                    else "完成 Seal Vault 防毒掃描後再設為 current"
                    if has_unscanned_current
                    else "上傳 Seal Vault current 版本"
                    if has_active
                    else "建立啟用印章並上傳 current 版本"
                ),
            })
            if not has_active:
                blockers.append(f"{company_check['company_name']} 缺少啟用的{label}。")
            elif not has_current:
                blockers.append(f"{company_check['company_name']} 的{label}尚無 AV 通過的 Seal Vault current 版本。")
        checks.append(company_check)
    return checks, blockers


def sqlite_count(conn: sqlite3.Connection, sql: str, params: Tuple[Any, ...] = ()) -> int:
    row = conn.execute(sql, params).fetchone()
    return int(row["count"] if row and row["count"] is not None else 0)


def internal_launch_user_journeys(conn: sqlite3.Connection) -> List[Dict[str, Any]]:
    blank_docs = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_documents WHERE source_type = 'blank_editor'")
    blank_submitted = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_documents WHERE source_type = 'blank_editor' AND current_status NOT IN ('draft', 'cancelled')")
    approval_steps = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_document_approval_steps")
    generated_pdfs = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_document_files WHERE file_type = 'generated_pdf'")
    uploaded_docs = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_documents WHERE source_type = 'uploaded_pdf'")
    original_pdfs = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_document_files WHERE file_type = 'original_pdf'")
    stamp_positions = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_document_stamp_positions")
    stamped_pdfs = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_document_files WHERE file_type = 'stamped_pdf'")
    ga_dispatches = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_document_dispatch_records WHERE dispatch_owner_type = 'general_affairs'")
    completed_ga_dispatches = sqlite_count(
        conn,
        """
        SELECT COUNT(*) AS count FROM official_document_dispatch_records
        WHERE dispatch_owner_type = 'general_affairs'
          AND dispatch_status IN ('dispatched', 'sent_by_applicant', 'closed')
          AND completed_at <> ''
        """,
    )
    ga_dispatch_proofs = sqlite_count(conn, "SELECT COUNT(*) AS count FROM official_document_dispatch_records WHERE dispatch_owner_type = 'general_affairs' AND proof_file_id <> ''")
    inbound_docs = sqlite_count(conn, "SELECT COUNT(*) AS count FROM inbound_documents")
    assigned_inbound = sqlite_count(conn, "SELECT COUNT(*) AS count FROM inbound_documents WHERE assignee_user_id <> ''")
    inbound_with_due = sqlite_count(conn, "SELECT COUNT(*) AS count FROM inbound_documents WHERE due_at <> ''")
    closed_inbound = sqlite_count(conn, "SELECT COUNT(*) AS count FROM inbound_documents WHERE status IN ('closed', '已結案')")
    internal_dispatches = sqlite_count(conn, "SELECT COUNT(*) AS count FROM internal_dispatches")
    reply_required_dispatches = sqlite_count(conn, "SELECT COUNT(*) AS count FROM internal_dispatches WHERE reply_required = 1")
    dispatches_with_due = sqlite_count(conn, "SELECT COUNT(*) AS count FROM internal_dispatches WHERE due_at <> ''")
    internal_recipients = sqlite_count(conn, "SELECT COUNT(*) AS count FROM internal_dispatch_recipients")
    internal_replies = sqlite_count(conn, "SELECT COUNT(*) AS count FROM internal_dispatch_replies")

    blank_missing = [
        "尚未建立空白公文申請單" if blank_docs < 1 else "",
        "空白公文尚未送出簽核" if blank_submitted < 1 else "",
        "尚未產生簽核關卡" if approval_steps < len(OFFICIAL_DOCUMENT_WORKFLOW_STEPS) else "",
        "尚未產生系統公文 PDF" if generated_pdfs < 1 else "",
    ]
    pdf_missing = [
        "尚未建立上傳 PDF 用印申請" if uploaded_docs < 1 else "",
        "尚未保存原始 PDF" if original_pdfs < 1 else "",
        "尚未設定拖拉用印位置" if stamp_positions < 1 else "",
        "尚未產生已用印 PDF" if stamped_pdfs < 1 else "",
    ]
    dispatch_missing = [
        "尚未建立總務寄發紀錄" if ga_dispatches < 1 else "",
        "總務尚未完成寄發" if completed_ga_dispatches < 1 else "",
        "尚未上傳寄發證明" if ga_dispatch_proofs < 1 else "",
    ]
    inbound_missing = [
        "尚未登錄收文" if inbound_docs < 1 else "",
        "尚未分派承辦人" if assigned_inbound < 1 else "",
        "尚未設定辦理期限" if inbound_with_due < 1 else "",
    ]
    internal_missing = [
        "尚未建立內部派文" if internal_dispatches < 1 else "",
        "尚未設定需回文派文" if reply_required_dispatches < 1 else "",
        "尚未設定回文期限" if dispatches_with_due < 1 else "",
        "尚未指定收件同仁" if internal_recipients < 1 else "",
        "尚未收到同仁回文" if internal_replies < 1 else "",
    ]
    return [
        launch_journey_item(
            "blank_official_document",
            "空白公文撰寫、簽核與附件版本",
            "申請人、主管、行政部主任",
            not any(blank_missing),
            [item for item in blank_missing if item],
            [f"空白公文 {blank_docs} 件", f"已送簽 {blank_submitted} 件", f"簽核節點 {approval_steps} 筆", f"公文 PDF {generated_pdfs} 份"],
            "建立一張空白公文，送出後逐關核准，確認附件區有系統產生 PDF。",
            "同仁要能從零撰寫電子公文，並在同一張申請單看到版本與簽核歷程。",
            "dispatch",
            ["申請單不是草稿", "至少有 5 個簽核節點", "附件區看得到系統產生 PDF"],
        ),
        launch_journey_item(
            "uploaded_pdf_stamping",
            "上傳 PDF、多位置用印與已用印版本",
            "申請人、總務",
            not any(pdf_missing),
            [item for item in pdf_missing if item],
            [f"上傳 PDF 申請 {uploaded_docs} 件", f"原始 PDF {original_pdfs} 份", f"用印位置 {stamp_positions} 個", f"已用印 PDF {stamped_pdfs} 份"],
            "上傳一份 PDF，拖拉至少一個用印位置，核准後確認後端產生 stamped PDF。",
            "同仁要能自己選位子，主管核准後系統自動用印並保留原始檔。",
            "dispatch",
            ["原始 PDF 保留", "至少 1 個用印位置", "附件區置頂顯示已用印 PDF"],
        ),
        launch_journey_item(
            "general_affairs_dispatch",
            "總務寄發、證明附件與申請人確認",
            "總務、申請人",
            not any(dispatch_missing),
            [item for item in dispatch_missing if item],
            [f"總務寄發紀錄 {ga_dispatches} 筆", f"已完成 {completed_ga_dispatches} 筆", f"寄發證明 {ga_dispatch_proofs} 份"],
            "總務下載已用印 PDF，回填發文字號/日期/備註，上傳寄發證明後交申請人確認。",
            "用印完成不等於流程結束；必須寄發、留證、結案，使用者才查得到完整申請單。",
            "dispatch",
            ["總務寄發紀錄存在", "寄發狀態已完成", "發文字號或寄發證明已留存"],
        ),
        launch_journey_item(
            "inbound_assignment",
            "收文登錄、承辦分派與期限",
            "總務、收文承辦",
            not any(inbound_missing),
            [item for item in inbound_missing if item],
            [f"收文 {inbound_docs} 件", f"已分派 {assigned_inbound} 件", f"有期限 {inbound_with_due} 件", f"已結案 {closed_inbound} 件"],
            "登錄一筆收文，上傳附件，指派承辦人並設定期限。",
            "收文同仁要能知道誰承辦、何時到期、附件在哪裡。",
            "inbound",
            ["收文已登錄", "承辦人已指派", "辦理期限已設定"],
        ),
        launch_journey_item(
            "internal_dispatch_reply",
            "內部派文、限期回文與回覆附件",
            "發文者、內部收件同仁",
            not any(internal_missing),
            [item for item in internal_missing if item],
            [f"內部派文 {internal_dispatches} 件", f"需回文 {reply_required_dispatches} 件", f"有期限 {dispatches_with_due} 件", f"收件人 {internal_recipients} 位", f"回文 {internal_replies} 筆"],
            "建立一筆需 N 日內回文的內部派文，指定同仁後由收件人回覆文字與附件。",
            "內部同仁要能收到公文、依期限回覆，總務或發文者可追蹤逾期。",
            "dispatch",
            ["指定至少 1 位收件人", "需回文且有期限", "收件人已送出回文"],
        ),
    ]


def internal_launch_data_readiness(conn: sqlite3.Connection) -> Dict[str, Any]:
    try:
        non_seal_blockers: List[str] = []
        warnings: List[str] = []
        role_counts = internal_launch_user_counts(conn)
        access_readiness = internal_launch_access_readiness(conn, role_counts)
        non_seal_blockers.extend(access_readiness.get("blockers", []))
        warnings.extend(access_readiness.get("warnings", []))
        for role in INTERNAL_LAUNCH_REQUIRED_ROLES:
            if role_counts.get(role, 0) < 1:
                non_seal_blockers.append(f"缺少啟用的「{role}」帳號，簽核流程會卡關。")
        companies, launch_company_scope, all_companies = internal_launch_companies(conn)
        workflow_readiness = build_internal_launch_workflow_readiness(
            companies,
            internal_launch_finance_applicants_by_company(conn, companies),
            lambda step, applicant, company: resolve_official_step_approver(conn, step, applicant, company),
        )
        non_seal_blockers.extend(workflow_readiness["blockers"])
        seal_checks, seal_blockers = internal_launch_company_seal_checks(conn)
        user_journeys = internal_launch_user_journeys(conn)
        warnings.extend([
            f"{item['title']}尚未完成走測：{compact_evidence(item.get('missing') or [])}"
            for item in user_journeys
            if not item.get("ready")
        ])
        non_seal_blockers = list(dict.fromkeys(non_seal_blockers))
        seal_blockers = list(dict.fromkeys(seal_blockers))
        blockers = [*non_seal_blockers, *seal_blockers]
        ready_without_seal_assets = not non_seal_blockers and workflow_readiness["ready"]
        ready = ready_without_seal_assets and not seal_blockers
        return {
            "ready": ready,
            "readyWithoutSealAssets": ready_without_seal_assets,
            "sealAssetsReady": not seal_blockers,
            "summary": f"roles={role_counts}；companies={len(companies)}/{len(all_companies)}；workflowRoutes={sum(1 for item in workflow_readiness['routeChecks'] if item.get('ready'))}/{len(workflow_readiness['routeChecks'])}；sealCompanies={len(seal_checks)}；journeys={sum(1 for item in user_journeys if item.get('ready'))}/{len(user_journeys)}；blockers={len(blockers)}",
            "blockers": blockers,
            "nonSealBlockers": non_seal_blockers,
            "sealBlockers": seal_blockers,
            "warnings": warnings,
            "checks": {
                "roleCounts": role_counts,
                "accessReadiness": access_readiness,
                "applicantReady": workflow_readiness["applicantReady"],
                "applicantCoverage": workflow_readiness["applicantCoverage"],
                "applicableCompanies": workflow_readiness["applicableCompanyCount"],
                "activeCompanies": len(companies),
                "allActiveCompanies": len(all_companies),
                "launchCompanyScope": launch_company_scope,
                "workflowRouteCodes": workflow_readiness["routeCodes"],
                "workflowRoutes": workflow_readiness["routeChecks"],
                "workflowSteps": workflow_readiness["workflowSteps"],
                "companySeals": seal_checks,
                "userJourneys": user_journeys,
            },
        }
    except Exception as exc:
        blocker = f"無法檢查正式上線資料：{type(exc).__name__}"
        return {
            "ready": False,
            "readyWithoutSealAssets": False,
            "sealAssetsReady": False,
            "summary": "launch data readiness query failed",
            "blockers": [blocker],
            "nonSealBlockers": [blocker],
            "sealBlockers": [],
            "warnings": [],
            "checks": {"error": str(exc)[:160]},
        }


def official_stamp_position_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    raw = payload.get("stamp_position") or {}
    positions = payload.get("stamp_positions") or payload.get("positions")
    if positions:
        raw = positions[0] if isinstance(positions, list) and positions else positions
    return {
        "stamp_page": max(1, int(pdf_safe_float(raw.get("page", raw.get("stamp_page", payload.get("stamp_page", 1))), 1))),
        "stamp_x": pdf_safe_float(raw.get("x", raw.get("stamp_x", payload.get("stamp_x", 420))), 420),
        "stamp_y": pdf_safe_float(raw.get("y", raw.get("stamp_y", payload.get("stamp_y", 130))), 130),
        "stamp_width": pdf_safe_float(raw.get("w", raw.get("width", raw.get("stamp_width", payload.get("stamp_width", 85)))), 85),
        "stamp_height": pdf_safe_float(raw.get("h", raw.get("height", raw.get("stamp_height", payload.get("stamp_height", 85)))), 85),
    }


OFFICIAL_STAMP_POSITION_COMPARABLE_FIELDS = (
    "seal_id", "page", "page_ref", "x", "y", "width", "height",
    "rotation", "opacity", "z_index", "order_index",
    "locked_seal_file_id", "locked_seal_sha256",
    "locked_render_width_pt", "locked_render_height_pt",
    "locked_dimension_policy_version",
)


def official_stamp_positions_payload(payload: Dict[str, Any], seal_id: str) -> List[Dict[str, Any]]:
    raw = payload.get("stamp_positions") or payload.get("positions") or []
    if isinstance(raw, str):
        raw = parse_json_any(raw, []) or []
    if not raw:
        nested = payload.get("stamp_position") if isinstance(payload.get("stamp_position"), dict) else {}
        raw = [nested or {
            "page": payload.get("stamp_page", 1),
            "x": payload.get("stamp_x", 420),
            "y": payload.get("stamp_y", 130),
            "width": payload.get("stamp_width") if "stamp_width" in payload else None,
            "height": payload.get("stamp_height") if "stamp_height" in payload else None,
        }]
    if not isinstance(raw, list):
        raise ValueError("invalid_official_stamp_positions")
    positions: List[Dict[str, Any]] = []
    for index, item in enumerate(raw, start=1):
        if not isinstance(item, dict):
            raise ValueError("invalid_official_stamp_position")
        width_supplied = any(key in item and item.get(key) is not None for key in ("width", "w", "stamp_width"))
        height_supplied = any(key in item and item.get(key) is not None for key in ("height", "h", "stamp_height"))
        width = pdf_safe_float(item.get("width", item.get("w", item.get("stamp_width"))), 85)
        height = pdf_safe_float(item.get("height", item.get("h", item.get("stamp_height"))), 85)
        if width <= 0 or height <= 0:
            raise ValueError("invalid_official_stamp_size")
        binding_keys = {
            "locked_seal_file_id", "lockedSealFileId",
            "locked_seal_sha256", "lockedSealSha256",
            "locked_render_width_pt", "lockedRenderWidthPt",
            "locked_render_height_pt", "lockedRenderHeightPt",
            "locked_dimension_policy_version", "lockedDimensionPolicyVersion",
        }
        binding_requested = any(
            key in item and item.get(key) not in (None, "")
            for key in binding_keys
        )
        positions.append({
            "id": str(item.get("id") or item.get("position_id") or item.get("positionId") or ""),
            "seal_id": item.get("seal_id") or seal_id,
            "page": max(1, int(pdf_safe_float(item.get("page", item.get("stamp_page", 1)), 1))),
            "page_ref": str(item.get("page_ref") or item.get("pageRef") or item.get("pageId") or ""),
            "x": round(pdf_safe_float(item.get("x", item.get("stamp_x", 420)), 420), 2),
            "y": round(pdf_safe_float(item.get("y", item.get("stamp_y", 130)), 130), 2),
            "width": round(width, 2),
            "height": round(height, 2),
            "rotation": round(pdf_safe_float(item.get("rotation"), 0) % 360, 2),
            "opacity": max(0.0, min(1.0, round(pdf_safe_float(item.get("opacity"), 1), 4))),
            "z_index": int(pdf_safe_float(item.get("z_index", item.get("zIndex")), index)),
            "locked_seal_file_id": str(item.get("locked_seal_file_id") or item.get("lockedSealFileId") or ""),
            "locked_seal_sha256": str(item.get("locked_seal_sha256") or item.get("lockedSealSha256") or ""),
            "locked_render_width_pt": item.get("locked_render_width_pt") or item.get("lockedRenderWidthPt"),
            "locked_render_height_pt": item.get("locked_render_height_pt") or item.get("lockedRenderHeightPt"),
            "locked_dimension_policy_version": str(item.get("locked_dimension_policy_version") or item.get("lockedDimensionPolicyVersion") or ""),
            # Detail responses intentionally include all five empty lock keys
            # for an unbound draft.  Treat only a non-empty value as an
            # attempted binding; partial non-empty evidence is still rejected
            # by canonicalization.
            "_binding_requested": binding_requested,
            "_rebind_current": bool(item.get("rebind_current") or item.get("rebindCurrent")),
            "_width_supplied": width_supplied,
            "_height_supplied": height_supplied,
            "order_index": int(item.get("order_index") or index),
        })
    return sorted(positions, key=lambda item: item["order_index"])


def local_official_seal_file_by_id(
    conn: sqlite3.Connection,
    file_id: str,
    seal_id: str,
) -> Dict[str, Any]:
    row = conn.execute(
        "SELECT * FROM company_seal_files WHERE id = ? AND seal_id = ?",
        (file_id, seal_id),
    ).fetchone()
    if not row:
        raise ValueError("official_seal_file_not_found")
    return require_seal_file_av_clean(conn, row)


def supabase_official_seal_file_by_id(file_id: str, seal_id: str) -> Dict[str, Any]:
    rows = supabase_filter_rows(
        "company_seal_files",
        {"id": file_id, "seal_id": seal_id},
        limit=1,
    )
    if not rows:
        raise ValueError("official_seal_file_not_found")
    return supabase_require_seal_file_av_clean(rows[0])


def canonicalize_official_company_seal_positions(
    positions: List[Dict[str, Any]],
    seal_lookup: Any,
    seal_file_lookup: Any,
    previous_positions: List[Dict[str, Any]] | None = None,
    *,
    allow_persisted_bindings: bool = False,
    allow_unbound_current: bool = False,
) -> List[Dict[str, Any]]:
    previous_by_id = {
        str(item.get("id") or ""): item
        for item in previous_positions or []
        if isinstance(item, dict) and item.get("id")
    }
    canonical: List[Dict[str, Any]] = []
    for raw_position in positions:
        position = dict(raw_position)
        binding_requested = bool(position.pop("_binding_requested", False))
        rebind_current = bool(position.pop("_rebind_current", False))
        seal = seal_lookup(str(position.get("seal_id") or ""))
        seal_id = str(seal.get("id") or position.get("seal_id") or "")
        selected_file_id = str(position.get("locked_seal_file_id") or "")
        selected_hash = str(position.get("locked_seal_sha256") or "")
        if (
            bool(selected_file_id) != bool(selected_hash)
            or (binding_requested and not all((selected_file_id, selected_hash)))
        ):
            raise ValueError("official_seal_file_binding_required")
        previous = previous_by_id.get(str(position.get("id") or "")) or {}
        previous_file_id = str(previous.get("locked_seal_file_id") or "")
        previous_hash = str(previous.get("locked_seal_sha256") or "")
        if bool(previous_file_id) != bool(previous_hash):
            raise ValueError("official_seal_file_binding_required")
        current_file = seal.get("current_file") if isinstance(seal, dict) else None
        previous_binding = bool(previous_file_id and previous_hash)
        same_previous_seal = str(previous.get("seal_id") or "") == seal_id
        same_existing_binding = False
        if previous_binding and not rebind_current:
            binding_changed = bool(
                not same_previous_seal
                or (
                    selected_file_id
                    and (
                        selected_file_id != previous_file_id
                        or selected_hash != previous_hash
                    )
                )
            )
            if binding_changed:
                if not allow_persisted_bindings:
                    raise ValueError("official_seal_rebind_confirmation_required")
                if not selected_file_id:
                    raise ValueError("official_seal_file_binding_required")
            else:
                selected_file_id = previous_file_id
                selected_hash = previous_hash
                same_existing_binding = True
        elif rebind_current:
            if not isinstance(current_file, dict):
                raise ValueError("current_seal_file_required")
            current_file_id = str(current_file.get("id") or "")
            current_hash = str(current_file.get("file_hash") or "")
            if not current_file_id or not current_hash:
                raise ValueError("current_seal_file_required")
            if selected_file_id and (
                selected_file_id != current_file_id
                or selected_hash != current_hash
            ):
                raise ValueError("official_seal_rebind_must_use_current")
            # The browser only confirms intent.  The immutable version is
            # always selected from the server-owned current pointer.
            selected_file_id = current_file_id
            selected_hash = current_hash
        if selected_file_id:
            seal_file = seal_file_lookup(selected_file_id, seal_id)
            if selected_hash != str(seal_file.get("file_hash") or ""):
                raise ValueError("official_seal_file_hash_mismatch")
            if (
                not same_existing_binding
                and not allow_persisted_bindings
                and str((current_file or {}).get("id") or "") != selected_file_id
            ):
                raise ValueError("official_seal_file_must_be_current")
        else:
            seal_file = seal.get("current_file") if isinstance(seal, dict) else None
            if not isinstance(seal_file, dict):
                if not allow_unbound_current:
                    raise ValueError("current_seal_file_required")
                seal_file = None
        if seal_file is not None:
            if str(seal_file.get("dimension_policy_version") or "") != EDOC_SEAL_DIMENSION_POLICY_VERSION:
                raise ValueError("official_seal_file_policy_upgrade_required")
            profile = company_seal_file_dimension_profile(
                seal.get("seal_size_type"),
                seal_file,
            )
        else:
            # A draft may record where an institution seal will be placed
            # before a custodian uploads its first usable Vault version.  The
            # placeholder remains fixed at the policy default and deliberately
            # carries no version evidence; submission binds the then-current
            # immutable file and replaces this placeholder geometry.
            profile = company_seal_dimension_profile(seal.get("seal_size_type"))
        width_supplied = bool(position.pop("_width_supplied", "width" in position))
        height_supplied = bool(position.pop("_height_supplied", "height" in position))
        if width_supplied != height_supplied:
            raise ValueError("seal_size_locked")
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"),
            position.get("width") if width_supplied else None,
            position.get("height") if height_supplied else None,
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
            allow_unspecified=not width_supplied and not height_supplied,
        )
        position["width"] = width
        position["height"] = height
        position["locked_seal_file_id"] = str((seal_file or {}).get("id") or "")
        position["locked_seal_sha256"] = str((seal_file or {}).get("file_hash") or "")
        position["locked_render_width_pt"] = profile["width_pt"] if seal_file else None
        position["locked_render_height_pt"] = profile["height_pt"] if seal_file else None
        position["locked_dimension_policy_version"] = profile["dimension_policy_version"] if seal_file else ""
        canonical.append(position)
    return canonical


def preserve_unidentified_official_position_bindings(
    positions: List[Dict[str, Any]],
    existing: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Upgrade geometry-only legacy draft edits to stable placement identities.

    New clients round-trip the server ``id`` and immutable lock fields.  Older
    clients omitted both, so an otherwise ordinary coordinate edit could
    silently follow a newly-current seal version.  Only a one-for-one position
    set with the same seal and order is eligible for this compatibility path;
    additions/removals and explicit rebinds are treated as new selections.
    """
    if len(positions) != len(existing):
        return positions
    existing_by_order = {
        int(item.get("order_index") or index): item
        for index, item in enumerate(existing, start=1)
        if isinstance(item, dict)
    }
    for index, position in enumerate(positions, start=1):
        if not isinstance(position, dict):
            continue
        if position.get("id") or position.get("_rebind_current"):
            continue
        order_index = int(position.get("order_index") or index)
        previous = existing_by_order.get(order_index) or {}
        if (
            not previous.get("id")
            or str(previous.get("seal_id") or "") != str(position.get("seal_id") or "")
        ):
            continue
        previous_file_id = str(previous.get("locked_seal_file_id") or "")
        previous_hash = str(previous.get("locked_seal_sha256") or "")
        if bool(previous_file_id) != bool(previous_hash):
            raise ValueError("official_seal_file_binding_required")
        position["id"] = str(previous["id"])
        if not position.get("_binding_requested") and previous_file_id:
            position.update({
                "locked_seal_file_id": previous_file_id,
                "locked_seal_sha256": previous_hash,
                "locked_render_width_pt": previous.get("locked_render_width_pt"),
                "locked_render_height_pt": previous.get("locked_render_height_pt"),
                "locked_dimension_policy_version": str(previous.get("locked_dimension_policy_version") or ""),
            })
    return positions


def require_official_position_set_intent(
    positions: List[Dict[str, Any]],
    existing: List[Dict[str, Any]],
    *,
    allow_persisted_bindings: bool = False,
) -> List[Dict[str, Any]]:
    """Reject identity replacement disguised as a newly-added placement.

    Existing server identities may be retained, deleted, or reordered.  A
    structurally-new unbound placement is also safe when every old identity is
    still present: its immutable version will be selected by the server.  If
    an old identity disappears while an unknown identity appears, however,
    the client must explicitly confirm ``rebindCurrent`` for every replacement.
    A new placement carrying client-supplied lock evidence requires the same
    confirmation even when it is a pure addition.

    ``allow_persisted_bindings`` is reserved for the trusted second pass after
    a correction/editor plan has already canonicalized its immutable evidence.
    """
    supplied_ids = [
        str(item.get("id") or "")
        for item in positions
        if isinstance(item, dict) and item.get("id")
    ]
    if len(supplied_ids) != len(set(supplied_ids)):
        raise ValueError("official_seal_position_identity_duplicate")
    if not existing or allow_persisted_bindings:
        return positions
    existing_ids = {
        str(item.get("id") or "")
        for item in existing
        if isinstance(item, dict) and item.get("id")
    }
    incoming_existing_ids = {
        str(item.get("id") or "")
        for item in positions
        if isinstance(item, dict) and str(item.get("id") or "") in existing_ids
    }
    removed_ids = existing_ids - incoming_existing_ids
    unknown = [
        item
        for item in positions
        if isinstance(item, dict) and str(item.get("id") or "") not in existing_ids
    ]
    if removed_ids and unknown:
        if any(not item.get("_rebind_current") for item in unknown):
            raise ValueError("official_seal_rebind_confirmation_required")
    elif not removed_ids:
        for item in unknown:
            if item.get("_binding_requested") and not item.get("_rebind_current"):
                raise ValueError("official_seal_rebind_confirmation_required")
    return positions


def replace_official_stamp_positions(
    conn: sqlite3.Connection,
    request_id: str,
    seal_id: str,
    payload: Dict[str, Any],
    *,
    allow_persisted_bindings: bool = False,
    allow_unbound_current: bool = False,
) -> List[Dict[str, Any]]:
    existing = official_document_stamp_positions(conn, request_id)
    incoming = preserve_unidentified_official_position_bindings(
        official_stamp_positions_payload(payload, seal_id),
        existing,
    )
    incoming = require_official_position_set_intent(
        incoming,
        existing,
        allow_persisted_bindings=allow_persisted_bindings,
    )
    positions = canonicalize_official_company_seal_positions(
        incoming,
        lambda item_seal_id: company_seal_row(conn, item_seal_id),
        lambda file_id, item_seal_id: local_official_seal_file_by_id(conn, file_id, item_seal_id),
        existing,
        allow_persisted_bindings=allow_persisted_bindings,
        allow_unbound_current=allow_unbound_current,
    )
    conn.execute("DELETE FROM official_document_stamp_positions WHERE request_id = ?", (request_id,))
    existing_ids = {str(item.get("id") or "") for item in existing}
    created: List[Dict[str, Any]] = []
    for index, position in enumerate(positions, start=1):
        row = {
            "id": (
                str(position.get("id") or "")
                if str(position.get("id") or "") in existing_ids
                else f"ODPOS-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
            ),
            "request_id": request_id,
            "seal_id": position["seal_id"],
            "page": position["page"],
            "x": position["x"],
            "y": position["y"],
            "width": position["width"],
            "height": position["height"],
            "page_ref": position.get("page_ref") or "",
            "rotation": position.get("rotation") or 0,
            "opacity": position.get("opacity") if position.get("opacity") is not None else 1,
            "z_index": position.get("z_index") or index,
            "locked_seal_file_id": position.get("locked_seal_file_id") or None,
            "locked_seal_sha256": position.get("locked_seal_sha256") or "",
            "locked_render_width_pt": position.get("locked_render_width_pt"),
            "locked_render_height_pt": position.get("locked_render_height_pt"),
            "locked_dimension_policy_version": position.get("locked_dimension_policy_version") or "",
            "order_index": index,
            "created_at": now(),
            "updated_at": now(),
        }
        insert_row(conn, "official_document_stamp_positions", row)
        created.append(row)
    return created


def official_document_stamp_positions(conn: sqlite3.Connection, request_id: str) -> List[Dict[str, Any]]:
    rows = conn.execute(
        "SELECT * FROM official_document_stamp_positions WHERE request_id = ? ORDER BY order_index",
        (request_id,),
    ).fetchall()
    return [row_to_dict(row) for row in rows]


def official_text_overlays_payload(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    raw = payload.get("text_overlays") or payload.get("textOverlays") or []
    if isinstance(raw, str):
        raw = parse_json_any(raw, []) or []
    if not isinstance(raw, list):
        raise ValueError("invalid_official_text_overlays")
    if len(raw) > 100:
        raise ValueError("official_text_overlay_limit_exceeded")
    overlays: List[Dict[str, Any]] = []
    for index, item in enumerate(raw, start=1):
        if not isinstance(item, dict):
            raise ValueError("invalid_official_text_overlay")
        text_content = str(item.get("text_content") or item.get("text") or "").strip()
        if not text_content:
            raise ValueError("official_text_overlay_content_required")
        if len(text_content) > 500:
            raise ValueError("official_text_overlay_content_too_long")
        font_size = round(pdf_safe_float(item.get("font_size", item.get("fontSize")), 14), 2)
        if font_size < 8 or font_size > 72:
            raise ValueError("official_text_overlay_font_size_invalid")
        x = round(pdf_safe_float(item.get("x"), 72), 2)
        y = round(pdf_safe_float(item.get("y"), 72), 2)
        if x < 0 or y < 0:
            raise ValueError("official_text_overlay_coordinate_invalid")
        overlays.append({
            "page": max(1, int(pdf_safe_float(item.get("page"), 1))),
            "x": x,
            "y": y,
            "text_content": text_content,
            "font_size": font_size,
            "font_family": "biau_kai",
            "order_index": int(item.get("order_index") or index),
        })
    return sorted(overlays, key=lambda item: item["order_index"])


def replace_official_text_overlays(conn: sqlite3.Connection, request_id: str, payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    overlays = official_text_overlays_payload(payload)
    conn.execute("DELETE FROM official_document_text_overlays WHERE request_id = ?", (request_id,))
    created: List[Dict[str, Any]] = []
    for index, overlay in enumerate(overlays, start=1):
        row = {
            "id": f"ODTEXT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "request_id": request_id,
            **overlay,
            "order_index": index,
            "created_at": now(),
            "updated_at": now(),
        }
        insert_row(conn, "official_document_text_overlays", row)
        created.append(row)
    return created


def official_document_text_overlays(conn: sqlite3.Connection, request_id: str) -> List[Dict[str, Any]]:
    rows = conn.execute(
        "SELECT * FROM official_document_text_overlays WHERE request_id = ? ORDER BY order_index",
        (request_id,),
    ).fetchall()
    return [row_to_dict(row) for row in rows]


def official_stamp_positions_from_request(stamp_request: Dict[str, Any], seal: Dict[str, Any]) -> List[Dict[str, Any]]:
    stored = stamp_request.get("stamp_positions") or []
    if stored:
        return [
            {
                "page": int(item.get("page") or 1),
                "x": pdf_safe_float(item.get("x"), 420),
                "y": pdf_safe_float(item.get("y"), 130),
                "w": pdf_safe_float(item.get("width", item.get("w")), 85),
                "h": pdf_safe_float(item.get("height", item.get("h")), 85),
                "label": seal.get("seal_name") or "公司印章",
                "type": seal.get("seal_category") or "company_seal",
                "seal_id": item.get("seal_id") or seal.get("id") or "",
            }
            for item in stored
        ]
    return [{
        "page": int(stamp_request.get("stamp_page") or 1),
        "x": pdf_safe_float(stamp_request.get("stamp_x"), 420),
        "y": pdf_safe_float(stamp_request.get("stamp_y"), 130),
        "w": pdf_safe_float(stamp_request.get("stamp_width"), 85),
        "h": pdf_safe_float(stamp_request.get("stamp_height"), 85),
        "label": seal.get("seal_name") or "公司印章",
        "type": seal.get("seal_category") or "company_seal",
        "seal_id": seal.get("id") or "",
    }]


def official_file_metadata(row: Dict[str, Any] | sqlite3.Row) -> Dict[str, Any]:
    data = row_to_dict(row) if isinstance(row, sqlite3.Row) else dict(row)
    data.pop("file_storage_key", None)
    data.pop("file_object_id", None)
    data.pop("stamp_claim_token", None)
    data["is_stamped"] = data.get("file_type") == "stamped_pdf"
    data["display_label"] = OFFICIAL_DOCUMENT_FILE_LABELS.get(data.get("file_type"), data.get("file_type") or "文件")
    return data


OFFICIAL_AV_REQUIRED_FILE_TYPES = frozenset({"original_pdf", "attachment", "dispatch_proof"})


def require_official_file_av_clean(
    file_meta: Dict[str, Any] | sqlite3.Row,
    file_object: Dict[str, Any] | sqlite3.Row | None,
) -> Dict[str, Any]:
    meta = row_to_dict(file_meta) if isinstance(file_meta, sqlite3.Row) else dict(file_meta)
    if meta.get("file_type") not in OFFICIAL_AV_REQUIRED_FILE_TYPES:
        return row_to_dict(file_object) if isinstance(file_object, sqlite3.Row) else dict(file_object or {})
    if not file_object:
        raise ValueError("official_document_file_object_missing")
    item = row_to_dict(file_object) if isinstance(file_object, sqlite3.Row) else dict(file_object)
    if str(item.get("scan_status") or "").strip() == "已隔離":
        raise ValueError("official_file_quarantined")
    if not file_object_av_is_clean(item):
        raise ValueError("official_file_antivirus_required")
    return item


def verify_private_storage_file_metadata(
    file_meta: Dict[str, Any] | sqlite3.Row,
    file_object: Dict[str, Any] | sqlite3.Row,
    *,
    expected_document_id: str = "",
    expected_storage_key: str = "",
    expected_bucket: str = "",
) -> str:
    """Fail closed before issuing a private Storage signed URL.

    A direct download cannot hash the response inside the Function without
    defeating the direct-download design.  Instead, require the immutable
    metadata recorded when scanning/finalizing the object to agree across the
    business record and ``file_objects`` reference before signing its path.
    """
    meta = row_to_dict(file_meta) if isinstance(file_meta, sqlite3.Row) else dict(file_meta)
    item = row_to_dict(file_object) if isinstance(file_object, sqlite3.Row) else dict(file_object)
    bucket = str(item.get("bucket") or expected_bucket or EDOC_STORAGE_BUCKET).strip()
    storage_key = str(item.get("storage_key") or "").strip()
    if bucket == EDOC_SEAL_STORAGE_BUCKET or is_seal_vault_file(item):
        raise PermissionError("seal_vault_signed_download_forbidden")
    if bucket != EDOC_STORAGE_BUCKET:
        raise ValueError("private_storage_file_metadata_mismatch")
    if not storage_key:
        raise ValueError("private_storage_file_metadata_mismatch")
    if expected_storage_key and storage_key != str(expected_storage_key):
        raise ValueError("private_storage_file_metadata_mismatch")
    if expected_bucket and bucket != str(expected_bucket):
        raise ValueError("private_storage_file_metadata_mismatch")
    if expected_document_id and str(item.get("document_id") or "") != str(expected_document_id):
        raise ValueError("private_storage_file_metadata_mismatch")
    referenced_object_id = str(meta.get("file_object_id") or "")
    if referenced_object_id and referenced_object_id != str(item.get("id") or ""):
        raise ValueError("private_storage_file_metadata_mismatch")
    meta_hash = str(meta.get("file_hash") or meta.get("sha256") or "").strip().lower()
    object_hash = str(item.get("sha256") or "").strip().lower()
    if not meta_hash or not object_hash or meta_hash != object_hash:
        raise ValueError("private_storage_file_metadata_mismatch")
    meta_size_value = meta.get("file_size") if meta.get("file_size") not in (None, "") else meta.get("size_bytes")
    try:
        meta_size = int(meta_size_value)
        object_size = int(item.get("size_bytes"))
    except (TypeError, ValueError) as exc:
        raise ValueError("private_storage_file_metadata_mismatch") from exc
    if meta_size < 0 or object_size < 0 or meta_size != object_size:
        raise ValueError("private_storage_file_metadata_mismatch")
    return object_hash


def verify_official_file_bytes(
    file_meta: Dict[str, Any] | sqlite3.Row,
    file_object: Dict[str, Any] | sqlite3.Row,
    data: bytes,
) -> str:
    """Verify immutable official-file metadata against the downloaded bytes."""
    meta = row_to_dict(file_meta) if isinstance(file_meta, sqlite3.Row) else dict(file_meta)
    item = row_to_dict(file_object) if isinstance(file_object, sqlite3.Row) else dict(file_object)
    actual_sha256 = sha256_bytes(data)
    expected_hashes = [
        str(value or "").strip().lower()
        for value in (meta.get("file_hash"), item.get("sha256"))
        if str(value or "").strip()
    ]
    if not expected_hashes or any(value != actual_sha256.lower() for value in expected_hashes):
        raise ValueError("official_file_hash_mismatch")
    expected_sizes = [
        int(value)
        for value in (meta.get("file_size"), item.get("size_bytes"))
        if value not in (None, "", 0, "0")
    ]
    if any(value != len(data) for value in expected_sizes):
        raise ValueError("official_file_hash_mismatch")
    return actual_sha256


def assert_official_document_uploads_av_clean(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
) -> List[Dict[str, Any]]:
    rows = conn.execute(
        """
        SELECT * FROM official_document_files
        WHERE document_id = ? AND file_type IN ('original_pdf', 'attachment', 'dispatch_proof')
        ORDER BY created_at, id
        """,
        (document["id"],),
    ).fetchall()
    if document.get("source_type") == "uploaded_pdf" and not any(row["file_type"] == "original_pdf" for row in rows):
        raise ValueError("official_document_source_pdf_required")
    checked: List[Dict[str, Any]] = []
    for row in rows:
        file_object = (
            conn.execute("SELECT * FROM file_objects WHERE id = ?", (row["file_object_id"],)).fetchone()
            if row["file_object_id"]
            else None
        )
        checked.append(require_official_file_av_clean(row, file_object))
    return checked


def official_document_files(conn: sqlite3.Connection, document_id: str) -> List[Dict[str, Any]]:
    rows = conn.execute(
        """
        SELECT * FROM official_document_files
        WHERE document_id = ?
        ORDER BY CASE WHEN file_type = 'stamped_pdf' THEN 0 ELSE 1 END, version DESC, created_at DESC
        """,
        (document_id,),
    ).fetchall()
    return [official_file_metadata(row) for row in rows]


def official_document_steps(conn: sqlite3.Connection, document_id: str) -> List[Dict[str, Any]]:
    return [row_to_dict(row) for row in conn.execute(
        "SELECT * FROM official_document_approval_steps WHERE document_id = ? ORDER BY workflow_generation, step_order",
        (document_id,),
    ).fetchall()]


def current_official_document_steps(conn: sqlite3.Connection, document_id: str) -> List[Dict[str, Any]]:
    rows = official_document_steps(conn, document_id)
    if not rows:
        return []
    generation = max(int(row.get("workflow_generation") or 1) for row in rows)
    return [row for row in rows if int(row.get("workflow_generation") or 1) == generation]


OFFICIAL_DOCUMENT_ACTOR_SNAPSHOT_SOURCE_TYPES = frozenset({
    "official_document",
    "official_documents",
    "official_document_application",
})
OFFICIAL_DOCUMENT_ACTOR_SNAPSHOT_SOURCE_TYPE = "official_document"


def official_document_actor_snapshot_payload(
    document_id: str,
    step: Dict[str, Any],
    timestamp: str | None = None,
) -> Dict[str, Any] | None:
    """Build the immutable, minimal actor assignment used for historical access."""
    approver_user_id = str(step.get("approver_user_id") or "").strip()
    step_id = str(step.get("id") or "").strip()
    if not approver_user_id or not step_id:
        return None
    timestamp = timestamp or now()
    snapshot_id = hashlib.sha256(
        f"{OFFICIAL_DOCUMENT_ACTOR_SNAPSHOT_SOURCE_TYPE}:{document_id}:{step_id}".encode("utf-8")
    ).hexdigest()[:32].upper()
    return {
        "id": f"ODAPSN-{snapshot_id}",
        "workflow_task_id": None,
        "seal_application_id": None,
        "source_type": OFFICIAL_DOCUMENT_ACTOR_SNAPSHOT_SOURCE_TYPE,
        "source_id": document_id,
        "step_no": int(step.get("step_order") or 0),
        "step_name": str(step.get("step_name") or step.get("step_key") or "簽核關卡"),
        "approver_role": str(step.get("approver_role") or "簽核人"),
        "approver_user_id": approver_user_id,
        "approver_name": str(step.get("approver_name") or ""),
        # Email is not required for participant authorization or audit history.
        "approver_email": "",
        "status": "已鎖定",
        "comment": "",
        "acted_at": "",
        "snapshot_json": json.dumps({
            "step_id": step_id,
            "step_key": str(step.get("step_key") or ""),
        }, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
        "created_at": timestamp,
        "updated_at": timestamp,
    }


def snapshot_official_document_approval_steps(
    conn: sqlite3.Connection,
    document_id: str,
    steps: List[Dict[str, Any]],
) -> int:
    """Persist actor assignments before mutable approval steps can be replaced."""
    timestamp = now()
    inserted = 0
    for step in steps:
        row = official_document_actor_snapshot_payload(document_id, step, timestamp)
        if not row:
            continue
        cursor = conn.execute(
            """
            INSERT INTO approval_step_actor_snapshots (
              id, workflow_task_id, seal_application_id, source_type, source_id,
              step_no, step_name, approver_role, approver_user_id, approver_name,
              approver_email, status, comment, acted_at, snapshot_json, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO NOTHING
            """,
            tuple(row[key] for key in (
                "id", "workflow_task_id", "seal_application_id", "source_type", "source_id",
                "step_no", "step_name", "approver_role", "approver_user_id", "approver_name",
                "approver_email", "status", "comment", "acted_at", "snapshot_json", "created_at", "updated_at",
            )),
        )
        inserted += max(int(cursor.rowcount or 0), 0)
    return inserted


def official_document_actor_snapshots(conn: sqlite3.Connection, document_id: str) -> List[Dict[str, Any]]:
    placeholders = ", ".join("?" for _ in OFFICIAL_DOCUMENT_ACTOR_SNAPSHOT_SOURCE_TYPES)
    rows = conn.execute(
        f"""
        SELECT * FROM approval_step_actor_snapshots
        WHERE source_id = ? AND source_type IN ({placeholders})
        ORDER BY step_no, created_at
        """,
        (document_id, *sorted(OFFICIAL_DOCUMENT_ACTOR_SNAPSHOT_SOURCE_TYPES)),
    ).fetchall()
    return [row_to_dict(row) for row in rows]


def official_document_logs(conn: sqlite3.Connection, document_id: str) -> List[Dict[str, Any]]:
    return [row_to_dict(row) for row in conn.execute("SELECT * FROM official_document_approval_logs WHERE document_id = ? ORDER BY created_at DESC", (document_id,)).fetchall()]


def official_document_stamp_request(conn: sqlite3.Connection, document_id: str) -> Dict[str, Any] | None:
    row = conn.execute(
        "SELECT * FROM official_document_stamp_requests WHERE document_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
        (document_id,),
    ).fetchone()
    if not row:
        return None
    data = row_to_dict(row)
    positions = official_document_stamp_positions(conn, data["id"])
    if (
        not positions
        and str(data.get("status") or "") != "cancelled"
        and str(data.get("error_message") or "") != "cleared_by_draft_correction"
    ):
        positions = official_stamp_positions_payload({
            "stamp_page": data.get("stamp_page"),
            "stamp_x": data.get("stamp_x"),
            "stamp_y": data.get("stamp_y"),
            "stamp_width": data.get("stamp_width"),
            "stamp_height": data.get("stamp_height"),
        }, data.get("seal_id") or "")
    data["stamp_positions"] = positions
    data["text_overlays"] = official_document_text_overlays(conn, data["id"])
    return data


def lock_official_stamp_seal_versions(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    stamp_request: Dict[str, Any],
) -> Dict[str, Any]:
    """Freeze every legacy/non-V2 seal placement at submission time."""
    positions = stamp_request.get("stamp_positions") or []
    if not positions:
        raise ValueError("official_document_seal_position_required")
    timestamp = now()
    for position in positions:
        seal_id = str(position.get("seal_id") or stamp_request.get("seal_id") or "")
        selected_file_id = str(position.get("locked_seal_file_id") or "")
        selected_hash = str(position.get("locked_seal_sha256") or "")
        if bool(selected_file_id) != bool(selected_hash):
            raise ValueError("official_seal_file_binding_required")
        seal = validate_official_document_seal(conn, seal_id, str(document.get("company_id") or ""), require_current=False)
        seal_file = (
            local_official_seal_file_by_id(conn, selected_file_id, seal_id)
            if selected_file_id
            else require_current_company_seal_file(conn, seal_id)
        )
        if selected_file_id and selected_hash != str(seal_file.get("file_hash") or ""):
            raise ValueError("official_seal_file_hash_mismatch")
        if str(seal_file.get("dimension_policy_version") or "") != EDOC_SEAL_DIMENSION_POLICY_VERSION:
            raise ValueError("official_seal_file_policy_upgrade_required")
        profile = company_seal_file_dimension_profile(seal.get("seal_size_type"), seal_file)
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"),
            position.get("width") if selected_file_id else None,
            position.get("height") if selected_file_id else None,
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
            allow_unspecified=not selected_file_id,
        )
        conn.execute(
            """
            UPDATE official_document_stamp_positions
            SET width = ?, height = ?, locked_seal_file_id = ?, locked_seal_sha256 = ?,
                locked_render_width_pt = ?, locked_render_height_pt = ?,
                locked_dimension_policy_version = ?, updated_at = ?
            WHERE id = ? AND request_id = ?
            """,
            (
                width, height, seal_file["id"], seal_file["file_hash"],
                profile["width_pt"], profile["height_pt"], profile["dimension_policy_version"],
                timestamp, position["id"], stamp_request["id"],
            ),
        )
    conn.execute(
        "UPDATE official_document_stamp_requests SET status = 'pending', error_message = '', updated_at = ? WHERE id = ?",
        (timestamp, stamp_request["id"]),
    )
    refreshed = official_document_stamp_request(conn, str(document.get("id") or ""))
    if not refreshed:
        raise ValueError("official_document_stamp_request_required")
    return refreshed


def locked_legacy_official_seal_asset(
    conn: sqlite3.Connection,
    stamp_request: Dict[str, Any],
) -> Tuple[Dict[str, Any], bytes]:
    """Read the immutable submit-time Seal Vault version for legacy renders."""
    positions = stamp_request.get("stamp_positions") or []
    locked_versions = {
        (
            str(position.get("seal_id") or stamp_request.get("seal_id") or ""),
            str(position.get("locked_seal_file_id") or ""),
            str(position.get("locked_seal_sha256") or ""),
        )
        for position in positions
    }
    if not locked_versions or any(not all(version) for version in locked_versions):
        raise ValueError("official_locked_seal_version_missing")
    if len(locked_versions) != 1:
        raise ValueError("legacy_multiple_seal_versions_requires_editor_v2")
    seal_id, seal_file_id, locked_hash = next(iter(locked_versions))
    row = conn.execute(
        "SELECT * FROM company_seal_files WHERE id = ? AND seal_id = ?",
        (seal_file_id, seal_id),
    ).fetchone()
    if not row:
        raise ValueError("official_locked_seal_version_missing")
    seal_file = require_seal_file_av_clean(conn, row)
    seal = conn.execute("SELECT seal_size_type FROM company_seals WHERE id = ?", (seal_id,)).fetchone()
    if not seal:
        raise ValueError("seal_not_found")
    for position in positions:
        validate_locked_company_seal_position(position, seal["seal_size_type"], seal_file)
    if seal_file.get("file_hash") != locked_hash or not seal_file.get("file_object_id"):
        raise ValueError("official_locked_seal_hash_mismatch")
    _, seal_bytes = read_file_object_bytes(conn, seal_file["file_object_id"])
    if sha256_bytes(seal_bytes) != locked_hash:
        raise ValueError("official_locked_seal_hash_mismatch")
    return seal_file, seal_bytes


def official_dispatch_method(value: str | None) -> str:
    method = value or "electronic_official_document_by_general_affairs"
    if method not in OFFICIAL_DISPATCH_METHODS:
        raise ValueError("invalid_official_dispatch_method")
    return method


def official_document_dispatch_method(source_type: str, value: str | None = None) -> str:
    """Keep outgoing letters in-system and return seal-only PDFs to the applicant."""
    if source_type == "uploaded_pdf":
        return "no_dispatch_required"
    method = official_dispatch_method(value)
    if OFFICIAL_DISPATCH_METHODS[method]["owner_type"] != "general_affairs":
        raise ValueError("official_document_dispatch_must_be_managed_in_system")
    return method


def official_dispatch_record_metadata(conn: sqlite3.Connection, row: Dict[str, Any] | sqlite3.Row | None) -> Dict[str, Any] | None:
    if not row:
        return None
    data = row_to_dict(row) if isinstance(row, sqlite3.Row) else dict(row)
    method = official_dispatch_method(data.get("dispatch_method"))
    data["dispatch_method_label"] = OFFICIAL_DISPATCH_METHODS[method]["label"]
    owner = active_user_by_id(conn, data.get("dispatch_owner_user_id") or "")
    data["dispatch_owner_name"] = owner.get("name") if owner else (data.get("dispatch_owner_user_id") or data.get("dispatch_owner_type") or "")
    proof_file_id = data.get("proof_file_id")
    if proof_file_id:
        proof = conn.execute("SELECT * FROM official_document_files WHERE id = ? AND document_id = ?", (proof_file_id, data["document_id"])).fetchone()
        data["proof_file"] = official_file_metadata(proof) if proof else None
    else:
        data["proof_file"] = None
    return data


def official_dispatch_record(conn: sqlite3.Connection, document_id: str) -> Dict[str, Any] | None:
    row = conn.execute("SELECT * FROM official_document_dispatch_records WHERE document_id = ? ORDER BY created_at DESC LIMIT 1", (document_id,)).fetchone()
    return official_dispatch_record_metadata(conn, row)


def official_dispatch_workflow_owner(steps: Iterable[Dict[str, Any]]) -> Dict[str, Any]:
    """Return the immutable GA actor selected by this document's workflow."""
    step = next((item for item in steps if item.get("step_key") == "general_affairs_review"), None)
    owner_id = str((step or {}).get("approver_user_id") or "").strip()
    if not step or not owner_id:
        raise ValueError("official_dispatch_owner_unresolved:general_affairs_review")
    return {
        "id": owner_id,
        "name": step.get("approver_name") or "總務專員",
        "role": step.get("approver_role") or "總務",
    }


def resolve_official_dispatch_owner(conn: sqlite3.Connection, document: Dict[str, Any], method: str) -> Dict[str, Any]:
    config = OFFICIAL_DISPATCH_METHODS[method]
    if config["owner_type"] == "general_affairs":
        workflow_owner = official_dispatch_workflow_owner(official_document_steps(conn, document["id"]))
        return active_user_by_id(conn, workflow_owner["id"]) or workflow_owner
    if config["owner_type"] == "applicant":
        return active_user_by_id(conn, document["applicant_id"]) or {"id": document["applicant_id"], "name": document.get("applicant_name") or "申請人", "role": "申請人"}
    return {"id": "system", "name": "System", "role": "system"}


def upsert_official_dispatch_record(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    method: str | None = None,
    actor: Dict[str, Any] | None = None,
    payload: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    method = official_dispatch_method(method or document.get("dispatch_method"))
    owner = resolve_official_dispatch_owner(conn, document, method)
    config = OFFICIAL_DISPATCH_METHODS[method]
    payload = payload or {}
    if payload.get("proof_file_id"):
        raise ValueError("official_dispatch_proof_file_server_managed")
    values = {
        "dispatch_method": method,
        "dispatch_owner_type": config["owner_type"],
        "dispatch_owner_user_id": owner.get("id") or "",
        "dispatch_status": payload.get("dispatch_status") or config["dispatch_status"],
        "external_official_document_number": payload.get("external_official_document_number") or "",
        "dispatch_date": payload.get("dispatch_date") or "",
        "recipient": payload.get("recipient") or document.get("recipient") or "",
        "recipient_contact": payload.get("recipient_contact") or "",
        "dispatch_note": payload.get("dispatch_note") or "",
        "proof_file_id": None,
        "created_by": actor.get("id") if actor else "system",
        "completed_at": payload.get("completed_at") or (now() if config["owner_type"] == "system" else ""),
    }
    row = {
        "id": f"ODDISP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "document_id": document["id"],
        **values,
        "created_at": now(),
        "updated_at": now(),
    }
    conn.execute(
        """
        INSERT INTO official_document_dispatch_records (
          id, document_id, dispatch_method, dispatch_owner_type,
          dispatch_owner_user_id, dispatch_status,
          external_official_document_number, dispatch_date, recipient,
          recipient_contact, dispatch_note, proof_file_id, created_by,
          created_at, updated_at, completed_at
        ) VALUES (
          :id, :document_id, :dispatch_method, :dispatch_owner_type,
          :dispatch_owner_user_id, :dispatch_status,
          :external_official_document_number, :dispatch_date, :recipient,
          :recipient_contact, :dispatch_note, :proof_file_id, :created_by,
          :created_at, :updated_at, :completed_at
        )
        ON CONFLICT(document_id) DO NOTHING
        """,
        row,
    )
    existing = official_dispatch_record(conn, document["id"])
    if not existing:
        raise RuntimeError("official_dispatch_record_create_failed")
    if (
        existing.get("dispatch_method") != method
        or existing.get("dispatch_owner_type") != config["owner_type"]
        or str(existing.get("dispatch_owner_user_id") or "") != str(owner.get("id") or "")
    ):
        raise ValueError("official_dispatch_route_conflict")
    return existing


def official_dispatch_route_notification_payload(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    record: Dict[str, Any],
) -> Dict[str, Any]:
    owner_type = str(record.get("dispatch_owner_type") or "")
    if owner_type == "general_affairs":
        target = active_user_by_id(conn, record.get("dispatch_owner_user_id") or "") or {}
        return {
            "id": f"NTF-DISPATCH-ROUTE-{record['id']}",
            "type": "發文寄發待辦",
            "title": f"{document['title']} 待總務寄發",
            **exact_notification_target_payload(target, document.get("company_id") or ""),
            "channel": "Email + 系統通知",
            "source": document["id"],
            "priority": "高",
            "body": "已用印版本已產生，請完成寄發並回填寄送日期與證明。",
        }
    if owner_type == "applicant":
        target = active_user_by_id(conn, document.get("applicant_id") or "") or {}
        return {
            "id": f"NTF-DISPATCH-ROUTE-{record['id']}",
            "type": "發文寄發待辦",
            "title": f"{document['title']} 已回到申請人寄發",
            **exact_notification_target_payload(target, document.get("company_id") or ""),
            "channel": "Email + 系統通知",
            "source": document["id"],
            "priority": "高",
            "body": "已用印版本已產生，請完成寄送並回填寄送日期與證明。",
        }
    target = active_user_by_id(conn, document.get("applicant_id") or "") or {}
    return {
        "id": f"NTF-DISPATCH-ROUTE-{record['id']}",
        "type": "發文申請人確認",
        "title": f"{document['title']} 已完成，請確認結案",
        **exact_notification_target_payload(target, document.get("company_id") or ""),
        "channel": "Email + 系統通知",
        "source": document["id"],
        "priority": "高",
        "body": "寄發方式為不需寄發，已用印版本已產生，請確認結案。",
    }


def enqueue_official_dispatch_route(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    record: Dict[str, Any],
    actor: Dict[str, Any] | None,
    stamped_file_id: str,
) -> Dict[str, Any]:
    existing_log = conn.execute(
        "SELECT id FROM official_document_approval_logs WHERE document_id = ? AND action = 'dispatch_route_created' LIMIT 1",
        (document["id"],),
    ).fetchone()
    if not existing_log:
        insert_official_log(
            conn,
            document["id"],
            "dispatch_route_created",
            actor,
            f"{record['dispatch_method']}:{record.get('dispatch_owner_type') or ''}",
            file_id=stamped_file_id,
        )
    return create_notification(conn, official_dispatch_route_notification_payload(conn, document, record))


def can_manage_official_dispatch(
    user: Dict[str, Any] | None,
    document: Dict[str, Any],
    record: Dict[str, Any] | None,
    session: Dict[str, Any] | None = None,
    workflow_steps: Iterable[Dict[str, Any]] | None = None,
) -> bool:
    if not user:
        return False
    user_id = str(user.get("id") or "").strip()
    owner_id = str((record or {}).get("dispatch_owner_user_id") or "").strip()
    if not user_id or not owner_id:
        return False
    owner_type = (record or {}).get("dispatch_owner_type")
    if owner_type == "general_affairs":
        try:
            workflow_owner_id = official_dispatch_workflow_owner(workflow_steps or [])["id"]
        except ValueError:
            return False
        return user_id == owner_id == workflow_owner_id
    if owner_type == "applicant":
        applicant_id = str(document.get("applicant_id") or "").strip()
        return bool(applicant_id and user_id == applicant_id and owner_id == applicant_id)
    return False


def can_retry_official_stamp(
    user: Dict[str, Any] | None,
    workflow_steps: Iterable[Dict[str, Any]] | None,
) -> bool:
    """Only this document's immutable GA approver may request a retry."""
    if not user:
        return False
    assigned = next(
        (step for step in (workflow_steps or []) if step.get("step_key") == "general_affairs_review"),
        None,
    )
    return bool(
        assigned
        and str(assigned.get("approver_user_id") or "")
        and str(assigned.get("approver_user_id") or "") == str(user.get("id") or "")
    )


def advance_official_dispatch_after_stamp(
    conn: sqlite3.Connection,
    document_id: str,
    stamped_file: Dict[str, Any],
    actor: Dict[str, Any] | None,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    method = official_dispatch_method(document.get("dispatch_method"))
    record = upsert_official_dispatch_record(conn, document, method, actor)
    # The stamp-completion transaction has already persisted the document
    # transition, route log, dispatch event and notification outbox.  This
    # helper is intentionally read/idempotency-only so a post-commit retry
    # cannot create a second route or rewrite its owner.
    return record


def _validated_official_dispatch_date(value: Any) -> str:
    dispatch_date = str(value or "").strip()
    if not dispatch_date:
        raise ValueError("official_dispatch_date_required")
    try:
        parsed = datetime.strptime(dispatch_date, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError("official_dispatch_date_invalid") from exc
    if parsed.strftime("%Y-%m-%d") != dispatch_date:
        raise ValueError("official_dispatch_date_invalid")
    return dispatch_date


def validate_official_dispatch_completion(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    record: Dict[str, Any],
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    if "proof_file_id" in payload:
        raise ValueError("official_dispatch_proof_file_server_managed")
    method = official_dispatch_method(record.get("dispatch_method"))
    if method != official_dispatch_method(document.get("dispatch_method")):
        raise ValueError("official_dispatch_route_conflict")
    values = {
        "external_official_document_number": str(
            payload.get("external_official_document_number")
            if "external_official_document_number" in payload
            else record.get("external_official_document_number") or ""
        ).strip(),
        "dispatch_date": _validated_official_dispatch_date(
            payload.get("dispatch_date") if "dispatch_date" in payload else record.get("dispatch_date")
        ),
        "recipient": str(payload.get("recipient") if "recipient" in payload else record.get("recipient") or "").strip(),
        "recipient_contact": str(
            payload.get("recipient_contact")
            if "recipient_contact" in payload
            else record.get("recipient_contact") or ""
        ).strip(),
        "dispatch_note": str(
            payload.get("dispatch_note") if "dispatch_note" in payload else record.get("dispatch_note") or ""
        ).strip(),
    }
    if method == "electronic_official_document_by_general_affairs" and not values["external_official_document_number"]:
        raise ValueError("official_dispatch_external_number_required")
    proof_file_id = str(record.get("proof_file_id") or "").strip()
    if method != "no_dispatch_required" and not proof_file_id:
        raise ValueError("official_dispatch_proof_required")
    if proof_file_id:
        proof = conn.execute(
            """
            SELECT * FROM official_document_files
            WHERE id = ? AND document_id = ? AND file_type = 'dispatch_proof'
            LIMIT 1
            """,
            (proof_file_id, document["id"]),
        ).fetchone()
        if not proof:
            raise ValueError("official_dispatch_proof_invalid")
        file_object = (
            conn.execute("SELECT * FROM file_objects WHERE id = ?", (proof["file_object_id"],)).fetchone()
            if proof["file_object_id"]
            else None
        )
        require_official_file_av_clean(proof, file_object)
    return values


def update_official_dispatch_record(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    steps = official_document_steps(conn, document_id)
    actor_snapshots = official_document_actor_snapshots(conn, document_id)
    if not canDownloadOfficialDocument(user, document, steps, actor_snapshots) and not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
        raise PermissionError("official_dispatch_access_denied")
    record = official_dispatch_record(conn, document_id)
    if not record:
        # The persisted document route is server-owned. A PATCH body must not
        # switch a GA-managed document into an applicant-owned dispatch branch.
        method = official_dispatch_method(document.get("dispatch_method"))
        owner = resolve_official_dispatch_owner(conn, document, method)
        prospective_record = {
            "dispatch_owner_type": OFFICIAL_DISPATCH_METHODS[method]["owner_type"],
            "dispatch_owner_user_id": owner.get("id") or "",
        }
        if not can_manage_official_dispatch(user, document, prospective_record, session, steps):
            raise PermissionError("official_dispatch_update_forbidden")
        record = upsert_official_dispatch_record(conn, document, method, user)
    if not can_manage_official_dispatch(user, document, record, session, steps):
        raise PermissionError("official_dispatch_update_forbidden")
    if "proof_file_id" in payload:
        raise ValueError("official_dispatch_proof_file_server_managed")
    allowed = {
        "external_official_document_number",
        "dispatch_date",
        "recipient",
        "recipient_contact",
        "dispatch_note",
    }
    update = {key: payload.get(key) or "" for key in allowed if key in payload}
    if not update:
        return official_dispatch_record(conn, document_id) or record
    assignments = ", ".join([f"{key} = ?" for key in update])
    conn.execute(f"UPDATE official_document_dispatch_records SET {assignments}, updated_at = ? WHERE id = ?", [*update.values(), now(), record["id"]])
    insert_official_log(conn, document_id, "update_dispatch", user, json.dumps(update, ensure_ascii=False), ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return official_dispatch_record(conn, document_id) or {}


def complete_official_dispatch(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    savepoint = f"official_dispatch_complete_{secrets.token_hex(4)}"
    conn.execute(f"SAVEPOINT {savepoint}")
    try:
        user = official_session_user(session)
        document = official_document_row(conn, document_id)
        steps = official_document_steps(conn, document_id)
        record = official_dispatch_record(conn, document_id)
        if not record:
            method = official_dispatch_method(document.get("dispatch_method"))
            owner = resolve_official_dispatch_owner(conn, document, method)
            prospective_record = {
                "dispatch_owner_type": OFFICIAL_DISPATCH_METHODS[method]["owner_type"],
                "dispatch_owner_user_id": owner.get("id") or "",
            }
            if not can_manage_official_dispatch(user, document, prospective_record, session, steps):
                raise PermissionError("official_dispatch_complete_forbidden")
            record = upsert_official_dispatch_record(conn, document, method, user)
            enqueue_official_dispatch_route(
                conn,
                document,
                record,
                user,
                str(document.get("stamped_file_id") or ""),
            )
        if not can_manage_official_dispatch(user, document, record, session, steps):
            raise PermissionError("official_dispatch_complete_forbidden")
        if record.get("dispatch_owner_type") == "general_affairs" and document.get("current_status") != "pending_general_affairs_dispatch":
            raise ValueError("official_document_not_pending_general_affairs_dispatch")
        if record.get("dispatch_owner_type") == "applicant" and document.get("current_status") != "returned_to_applicant_for_send":
            raise ValueError("official_document_not_returned_to_applicant_for_send")
        values = validate_official_dispatch_completion(conn, document, record, payload)
        final_dispatch_status = "sent_by_applicant" if record.get("dispatch_owner_type") == "applicant" else "dispatched"
        final_document_status = "sent_by_applicant" if record.get("dispatch_owner_type") == "applicant" else "dispatched"
        timestamp = now()
        record_update = conn.execute(
            """
            UPDATE official_document_dispatch_records
            SET external_official_document_number = ?, dispatch_date = ?,
                recipient = ?, recipient_contact = ?, dispatch_note = ?,
                dispatch_status = ?, completed_at = ?, updated_at = ?
            WHERE id = ? AND document_id = ? AND dispatch_status = 'pending'
            """,
            (
                values["external_official_document_number"],
                values["dispatch_date"],
                values["recipient"],
                values["recipient_contact"],
                values["dispatch_note"],
                final_dispatch_status,
                timestamp,
                timestamp,
                record["id"],
                document_id,
            ),
        )
        document_update = conn.execute(
            """
            UPDATE official_documents
            SET current_status = ?, current_step = 'applicant_confirm', updated_at = ?
            WHERE id = ? AND current_status = ? AND current_step = ?
            """,
            (
                final_document_status,
                timestamp,
                document_id,
                document.get("current_status") or "",
                document.get("current_step") or "",
            ),
        )
        if record_update.rowcount != 1 or document_update.rowcount != 1:
            raise ValueError("official_dispatch_completion_conflict")
        insert_official_log(
            conn,
            document_id,
            "complete_dispatch",
            user,
            final_dispatch_status,
            file_id=str(record.get("proof_file_id") or ""),
            ip_address=payload.get("ip_address") or "",
            user_agent=payload.get("user_agent") or "",
        )
        applicant = active_user_by_id(conn, document.get("applicant_id") or "") or {}
        create_notification(conn, {
            "id": f"NTF-DISPATCH-COMPLETE-{record['id']}",
            "type": "發文申請人確認",
            "title": f"{document['title']} 已完成寄發，請確認結案",
            **exact_notification_target_payload(applicant, document.get("company_id") or ""),
            "channel": "Email + 系統通知",
            "source": document_id,
            "priority": "高",
            "body": f"寄發狀態：{final_dispatch_status}。請回到申請單確認已用印版本與寄發紀錄。",
        })
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        raise
    return official_document_detail(conn, document_id, session)


def upload_official_dispatch_proof_file(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    steps = official_document_steps(conn, document_id)
    record = official_dispatch_record(conn, document_id)
    if not record:
        method = official_dispatch_method(document.get("dispatch_method"))
        owner = resolve_official_dispatch_owner(conn, document, method)
        prospective_record = {
            "dispatch_owner_type": OFFICIAL_DISPATCH_METHODS[method]["owner_type"],
            "dispatch_owner_user_id": owner.get("id") or "",
        }
        if not can_manage_official_dispatch(user, document, prospective_record, session, steps):
            raise PermissionError("official_dispatch_proof_upload_forbidden")
        record = upsert_official_dispatch_record(conn, document, method, user)
    if not can_manage_official_dispatch(user, document, record, session, steps):
        raise PermissionError("official_dispatch_proof_upload_forbidden")
    content = payload.get("content_base64") or ""
    if not content:
        raise ValueError("dispatch_proof_file_required")
    data = base64.b64decode(content)
    mime_type = payload.get("file_mime_type") or payload.get("mime_type") or "application/pdf"
    if mime_type.lower() not in OFFICIAL_DISPATCH_PROOF_MIME_TYPES:
        raise ValueError("dispatch_proof_mime_type_not_allowed")
    if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
        raise ValueError("dispatch_proof_file_too_large")
    file_name = Path(payload.get("file_name") or f"{document_id}-dispatch-proof").name
    scan_status, scan_signature = scan_official_upload_bytes(data, file_name)
    file_row = store_file_object(conn, document_id, file_name, data, "official-documents", "dispatch-proof", official_actor_name(user))
    conn.execute("UPDATE file_objects SET mime_type = ? WHERE id = ?", (mime_type, file_row["id"]))
    file_row = persist_file_object_scan_result(
        conn,
        file_row["id"],
        scan_status,
        scan_signature,
        official_actor_name(user),
    )
    official_file = insert_official_document_file(conn, document_id, "dispatch_proof", file_row, official_actor_name(user))
    conn.execute("UPDATE official_document_dispatch_records SET proof_file_id = ?, updated_at = ? WHERE id = ?", (official_file["id"], now(), record["id"]))
    insert_official_log(conn, document_id, "upload_dispatch_proof", user, official_file["file_hash"], file_id=official_file["id"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return {"dispatch_record": official_dispatch_record(conn, document_id), "file": official_file_metadata(official_file)}


def normalized_official_attachment_mime(payload: Dict[str, Any], file_name: str) -> str:
    mime_type = roster_text(payload.get("file_mime_type") or payload.get("mime_type")).lower()
    extension_mime = {
        ".pdf": "application/pdf",
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".webp": "image/webp",
        ".txt": "text/plain",
        ".csv": "text/csv",
        ".doc": "application/msword",
        ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        ".xls": "application/vnd.ms-excel",
        ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    }.get(Path(file_name).suffix.lower(), "")
    if not mime_type or mime_type == "application/octet-stream":
        mime_type = extension_mime
    if mime_type not in OFFICIAL_ATTACHMENT_MIME_TYPES or (extension_mime and mime_type != extension_mime):
        raise ValueError("official_attachment_mime_type_not_allowed")
    return mime_type


def upload_official_document_attachment(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document.get("applicant_id") != user.get("id"):
        raise PermissionError("official_document_attachment_upload_forbidden")
    require_official_creation_company(user, document.get("company_id"))
    if document.get("current_status") not in {"draft", "rejected"}:
        raise ValueError("official_document_attachments_locked_after_submit")
    content = payload.get("content_base64") or payload.get("file_content_base64") or ""
    if not content:
        raise ValueError("official_document_attachment_required")
    try:
        data = base64.b64decode(content, validate=True)
    except (ValueError, binascii.Error) as exc:
        raise ValueError("official_document_attachment_invalid_base64") from exc
    if not data:
        raise ValueError("official_document_attachment_empty")
    if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
        raise ValueError("official_document_attachment_too_large")
    file_name = Path(payload.get("file_name") or "attachment.pdf").name
    mime_type = normalized_official_attachment_mime(payload, file_name)
    if mime_type == "application/pdf":
        inspect_editor_pdf(data)
    scan_status, scan_signature = scan_official_upload_bytes(data, file_name)
    file_row = store_file_object(
        conn,
        document_id,
        file_name,
        data,
        "official-documents",
        "attachment",
        official_actor_name(user),
        mime_type,
    )
    file_row = persist_file_object_scan_result(
        conn,
        file_row["id"],
        scan_status,
        scan_signature,
        official_actor_name(user),
    )
    official_file = insert_official_document_file(conn, document_id, "attachment", file_row, official_actor_name(user))
    insert_official_log(
        conn,
        document_id,
        "upload_attachment",
        user,
        official_file["file_hash"],
        file_id=official_file["id"],
        ip_address=payload.get("ip_address") or "",
        user_agent=payload.get("user_agent") or "",
    )
    return {"file": official_file_metadata(official_file), "document": official_document_detail(conn, document_id, session)}


def insert_official_log(
    conn: sqlite3.Connection,
    document_id: str,
    action: str,
    actor: Dict[str, Any] | None,
    comment: str = "",
    *,
    step_id: str = "",
    file_id: str = "",
    ip_address: str = "",
    user_agent: str = "",
    principal_actor_id: str = "",
    decision_evidence: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    row = {
        "id": f"ODLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "document_id": document_id,
        "step_id": step_id or None,
        "file_id": file_id or None,
        "actor_id": actor.get("id") if actor else "system",
        "actor_name": official_actor_name(actor),
        "principal_actor_id": principal_actor_id or None,
        "action": action,
        "comment": comment,
        "decision_evidence_json": json.dumps(decision_evidence or {}, ensure_ascii=False),
        "ip_address": ip_address,
        "user_agent": user_agent[:180] if user_agent else "",
        "created_at": now(),
    }
    insert_row(conn, "official_document_approval_logs", row)
    log_audit(
        conn,
        row["actor_name"],
        action,
        "official_documents",
        document_id,
        comment,
        event_type=action if action in LOGGING_AUDIT_EVENT_TYPES else None,
        module_code="official_documents",
        actor_user_id=row["actor_id"],
        metadata={
            "principal_actor_id": row.get("principal_actor_id") or "",
            "decision_evidence": decision_evidence or {},
        },
    )
    return row


def insert_official_document_file(
    conn: sqlite3.Connection,
    document_id: str,
    file_type: str,
    file_row: Dict[str, Any],
    actor: str,
    *,
    stamp_request_id: str = "",
    stamp_claim_token: str = "",
) -> Dict[str, Any]:
    next_version = conn.execute(
        "SELECT COALESCE(MAX(version), 0) + 1 AS version FROM official_document_files WHERE document_id = ? AND file_type = ?",
        (document_id, file_type),
    ).fetchone()["version"]
    row = {
        "id": f"ODFILE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "document_id": document_id,
        "file_object_id": file_row.get("id"),
        "file_type": file_type,
        "file_name": file_row.get("file_name") or f"{document_id}-{file_type}.pdf",
        "file_storage_key": file_row.get("storage_key") or "",
        "file_mime_type": file_row.get("mime_type") or "application/pdf",
        "file_size": int(file_row.get("size_bytes") or 0),
        "file_hash": file_row.get("sha256") or "",
        "version": int(next_version),
        "uploaded_by": actor,
        "created_at": now(),
    }
    if stamp_request_id:
        row["stamp_request_id"] = stamp_request_id
        row["stamp_claim_token"] = stamp_claim_token or None
    insert_row(conn, "official_document_files", row)
    return row


def store_official_pdf_file(
    conn: sqlite3.Connection,
    document_id: str,
    file_type: str,
    file_name: str,
    data: bytes,
    actor: str,
    *,
    stamp_request_id: str = "",
    stamp_claim_token: str = "",
) -> Dict[str, Any]:
    scan_result = scan_official_upload_bytes(data, file_name) if file_type == "original_pdf" else None
    file_row = store_file_object(conn, document_id, file_name, data, "official-documents", f"{file_type}-v1", actor)
    if scan_result:
        file_row = persist_file_object_scan_result(conn, file_row["id"], scan_result[0], scan_result[1], actor)
    return insert_official_document_file(
        conn,
        document_id,
        file_type,
        file_row,
        actor,
        stamp_request_id=stamp_request_id,
        stamp_claim_token=stamp_claim_token,
    )


def validated_uploaded_official_pdf(payload: Dict[str, Any]) -> bytes:
    content = payload.get("content_base64") or payload.get("file_content_base64") or ""
    if not content:
        raise ValueError("original_pdf_required")
    try:
        data = base64.b64decode(content, validate=True)
    except (ValueError, binascii.Error) as exc:
        raise ValueError("original_pdf_must_be_pdf") from exc
    if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
        raise ValueError("original_pdf_inline_upload_too_large_use_pdf_editor")
    if not data.startswith(b"%PDF"):
        raise ValueError("original_pdf_must_be_pdf")
    inspect_editor_pdf(data)
    return data


def official_pdf_document_payload(conn: sqlite3.Connection, document: Dict[str, Any]) -> Dict[str, Any]:
    company = official_company_row(conn, document["company_id"])
    metadata = parse_json_field(document.get("metadata_json"))
    extra = metadata.get("extra") if isinstance(metadata.get("extra"), dict) else {}
    body_parts = []
    if document.get("description"):
        body_parts.append(f"說明：\n{document['description']}")
    if document.get("method"):
        body_parts.append(f"辦法：\n{document['method']}")
    return {
        "id": document["id"],
        "doc_no": document["id"],
        "company_name": company.get("name") or "歲悅股份有限公司",
        "doc_type": extra.get("document_type") or metadata.get("document_type") or "函",
        "agency_name": document.get("recipient") or "未指定受文者",
        "copy_recipients": official_pdf_copy_recipients(
            extra.get("copy_recipients") or extra.get("copyRecipients") or metadata.get("copy_recipients") or metadata.get("copyRecipients"),
            company.get("name") or "",
        ),
        "subject": document.get("subject") or document.get("title") or "未命名發文",
        "body": "\n\n".join(body_parts) or document.get("description") or "尚未填寫說明內容。",
        "owner": document.get("handler_name") or document.get("applicant_name") or "承辦人",
        "department": document.get("dispatch_unit") or document.get("applicant_department_name") or "",
        "attachments": metadata.get("attachments", "附件詳如附件區"),
        "priority": extra.get("priority") or metadata.get("priority") or "普通件",
        "contact_address": extra.get("contact_address") or extra.get("contactAddress") or company.get("address") or "",
        "contact_owner": extra.get("contact_owner") or extra.get("contactOwner") or document.get("handler_name") or document.get("applicant_name") or "",
        "contact_phone": extra.get("contact_phone") or extra.get("contactPhone") or "",
        "contact_fax": extra.get("contact_fax") or extra.get("contactFax") or EDOC_DEFAULT_CONTACT_FAX,
        "contact_email": extra.get("contact_email") or extra.get("contactEmail") or "",
        "created_at": document.get("created_at"),
    }


def ensure_official_generated_pdf(conn: sqlite3.Connection, document: Dict[str, Any], actor: str = "PDF Worker") -> Dict[str, Any]:
    row = conn.execute(
        "SELECT * FROM official_document_files WHERE document_id = ? AND file_type = 'generated_pdf' ORDER BY version DESC LIMIT 1",
        (document["id"],),
    ).fetchone()
    if row:
        return row_to_dict(row)
    package = build_official_pdf_package(official_pdf_document_payload(conn, document), [], "歲悅正式函", 1)
    file_row = store_official_pdf_file(conn, document["id"], "generated_pdf", f"{document['id']}-generated.pdf", package["data"], actor)
    insert_official_log(conn, document["id"], "generate_pdf", {"id": "system", "name": actor, "role": "system"}, file_row["file_hash"], file_id=file_row["id"])
    return file_row


def official_latest_source_file(conn: sqlite3.Connection, document: Dict[str, Any]) -> Dict[str, Any]:
    file_type = "original_pdf" if document.get("source_type") == "uploaded_pdf" else "generated_pdf"
    if file_type == "generated_pdf":
        ensure_official_generated_pdf(conn, document)
    row = conn.execute(
        "SELECT * FROM official_document_files WHERE document_id = ? AND file_type = ? ORDER BY version DESC LIMIT 1",
        (document["id"], file_type),
    ).fetchone()
    if not row:
        raise ValueError("official_document_source_pdf_required")
    return row_to_dict(row)


def create_official_workflow_steps(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    applicant: Dict[str, Any],
    *,
    actor_plan: Dict[str, Dict[str, Any]] | None = None,
    workflow_steps: List[Dict[str, Any]] | None = None,
) -> List[Dict[str, Any]]:
    seal_context = official_seal_context_from_document(document)
    selected_workflow_steps = workflow_steps or official_workflow_steps_for_document(conn, document)
    all_existing = official_document_steps(conn, document["id"])
    existing = current_official_document_steps(conn, document["id"])
    current_generation = max(
        (int(step.get("workflow_generation") or 1) for step in all_existing),
        default=0,
    )
    target_generation = current_generation or 1
    generation_base = 0
    if existing and all(step.get("status") == "skipped" for step in existing):
        snapshot_official_document_approval_steps(conn, document["id"], existing)
        # A rejected generation remains part of the permanent decision record.
        # Allocate the replacement generation after it instead of deleting the
        # exact step ids referenced by immutable approval logs.
        generation_base = max(int(step.get("step_order") or 0) for step in all_existing)
        target_generation = current_generation + 1
        existing = []
    if existing and not official_workflow_step_sequence_matches(existing, selected_workflow_steps):
        recoverable_prefix = (
            document.get("current_status") in {"draft", "rejected"}
            and all(step.get("status") == "pending" for step in existing)
        )
        if not recoverable_prefix:
            raise ValueError("official_workflow_existing_steps_invalid")
        # A prior non-transactional remote attempt may have left only a prefix.
        # A draft/rejected document has not entered approval, so preserving the
        # prefix as an immutable participant snapshot and rebuilding the exact
        # policy sequence is safe and idempotent.
        snapshot_official_document_approval_steps(conn, document["id"], existing)
        generation_base = max(int(step.get("step_order") or 0) for step in all_existing)
        target_generation = current_generation + 1
        conn.execute(
            """
            UPDATE official_document_approval_steps
            SET status = 'skipped',
                comment = '未啟用的舊流程已作廢；系統已建立完整簽核流程。',
                updated_at = ?
            WHERE document_id = ? AND workflow_generation = ? AND status = 'pending'
            """,
            (now(), document["id"], current_generation),
        )
        existing = []
    if existing and document.get("current_status") in {"draft", "rejected"} and any(
        step.get("status") != "pending" for step in existing
    ):
        raise ValueError("official_workflow_existing_steps_invalid")
    if existing:
        if actor_plan is not None:
            for stored_step in existing:
                expected_actor = actor_plan.get(stored_step.get("step_key") or "")
                if not expected_actor or stored_step.get("approver_user_id") != expected_actor.get("id"):
                    raise ValueError(f"official_workflow_actor_snapshot_changed:{stored_step.get('step_key') or 'unknown'}")
        if finance_workflow_actor(applicant):
            for stored_step in existing:
                approver = active_user_by_id(conn, stored_step.get("approver_user_id") or "")
                require_valid_finance_workflow_step_actor(
                    stored_step,
                    applicant,
                    approver,
                    seal_context=seal_context,
                )
        snapshot_official_document_approval_steps(conn, document["id"], existing)
        return existing
    company = official_company_row(conn, document["company_id"])
    resolved_steps: List[Tuple[Dict[str, Any], Dict[str, Any] | None]] = []
    for step in selected_workflow_steps:
        approver = actor_plan.get(step["key"]) if actor_plan is not None else resolve_official_step_approver(conn, step, applicant, company)
        require_valid_finance_workflow_step_actor(
            step,
            applicant,
            approver,
            seal_context=seal_context,
        )
        if not approver:
            error = "official_seal_route_actor_unresolved" if seal_context else "official_workflow_actor_unresolved"
            raise ValueError(f"{error}:{step['key']}")
        resolved_steps.append((step, approver))
    created: List[Dict[str, Any]] = []
    for step, approver in resolved_steps:
        timestamp = now()
        row = {
            "id": f"ODSTEP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "document_id": document["id"],
            "workflow_generation": target_generation,
            "step_order": int(step["order"]),
            "step_key": step["key"],
            "step_name": step["name"],
            "approver_user_id": approver.get("id") if approver else "",
            "approver_name": approver.get("name") if approver else step["role"],
            "approver_role": approver.get("role") if approver else step["role"],
            "status": "pending",
            "comment": "",
            "approved_at": "",
            "review_started_at": None,
            "created_at": timestamp,
            "updated_at": timestamp,
        }
        insert_row(conn, "official_document_approval_steps", row)
        created.append(row)
    snapshot_official_document_approval_steps(conn, document["id"], created)
    return created


def official_document_participant_ids(
    document: Dict[str, Any],
    steps: List[Dict[str, Any]] | None = None,
    actor_snapshots: List[Dict[str, Any]] | None = None,
) -> set[str]:
    participant_ids = {
        str(document.get("applicant_id") or "").strip(),
        *(str(step.get("approver_user_id") or "").strip() for step in steps or []),
        *(str(step.get("decision_actor_user_id") or "").strip() for step in steps or []),
        *(str(snapshot.get("approver_user_id") or "").strip() for snapshot in actor_snapshots or []),
    }
    participant_ids.discard("")
    return participant_ids


def official_document_user_same_company(user: Dict[str, Any] | None, document: Dict[str, Any]) -> bool:
    if not user:
        return False
    user_company_id = str(user.get("company_id") or "").strip()
    document_company_id = str(document.get("company_id") or "").strip()
    if not document_company_id:
        return False
    # Historical actor snapshots can predate Finance company synchronization.
    # This helper describes only the company boundary; immutable workflow
    # participation is evaluated separately and may legitimately cross it.
    return not user_company_id or user_company_id == document_company_id


def canDownloadOfficialDocument(
    user: Dict[str, Any] | None,
    document: Dict[str, Any],
    steps: List[Dict[str, Any]] | None = None,
    actor_snapshots: List[Dict[str, Any]] | None = None,
) -> bool:
    if not user:
        return False
    user_id = str(user.get("id") or "").strip()
    if not user_id:
        return False
    return user_id in official_document_participant_ids(document, steps, actor_snapshots)


def official_application_package(
    document: Dict[str, Any],
    files: List[Dict[str, Any]],
    steps: List[Dict[str, Any]],
    logs: List[Dict[str, Any]],
    stamp_request: Dict[str, Any] | None,
    dispatch_record: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    metadata = parse_json_field(document.get("metadata_json"))
    seal_context = metadata.get("official_seal") if isinstance(metadata.get("official_seal"), dict) else None
    versions = [file for file in files if file.get("file_type") in {"original_pdf", "generated_pdf", "prepared_pdf", "stamped_pdf"}]
    attachments = [file for file in files if file.get("file_type") == "attachment"]
    download_logs = [log for log in logs if log.get("action") == "download_file"]
    process_logs = [log for log in logs if log.get("action") != "download_file"]
    public_stamp_request = dict(stamp_request or {}) if stamp_request else None
    if public_stamp_request:
        public_stamp_request.pop("claim_token", None)
        public_stamp_request.pop("claim_owner_id", None)
    return {
        "id": document.get("id"),
        "record_type": "official_document_application",
        "title": document.get("title") or document.get("subject") or document.get("id"),
        "company_id": document.get("company_id"),
        "source_type": document.get("source_type"),
        "document_type": document.get("document_type"),
        "workflow_template_key": document.get("workflow_template_key") or metadata.get("workflow_template"),
        "official_seal": seal_context,
        "document_category": (seal_context or {}).get("document_category") or "",
        "approval_route_code": (seal_context or {}).get("approval_route_code") or "",
        "approval_route_name": (seal_context or {}).get("approval_route_name") or "",
        "dispatch_method": document.get("dispatch_method"),
        "stamped_file_id": document.get("stamped_file_id"),
        "current_status": document.get("current_status"),
        "current_step": document.get("current_step"),
        "applicant_id": document.get("applicant_id"),
        "applicant_name": document.get("applicant_name"),
        "all_files": files,
        "document_versions": versions,
        "attachments": attachments,
        "stamped_versions": [file for file in versions if file.get("file_type") == "stamped_pdf"],
        "approval_steps": steps,
        "process_logs": process_logs,
        "download_logs": download_logs,
        "stamp_request": public_stamp_request,
        "dispatch_record": dispatch_record,
        "summary": {
            "version_count": len(versions),
            "attachment_count": len(attachments),
            "approval_step_count": len(steps),
            "download_count": len(download_logs),
            "has_stamped_pdf": any(file.get("file_type") == "stamped_pdf" for file in versions),
            "has_dispatch_record": bool(dispatch_record),
        },
    }


def official_document_detail(conn: sqlite3.Connection, document_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    all_steps = official_document_steps(conn, document_id)
    steps = current_official_document_steps(conn, document_id)
    actor_snapshots = official_document_actor_snapshots(conn, document_id)
    user = session.get("user") if session else None
    is_participant = bool(user and canDownloadOfficialDocument(user, document, all_steps, actor_snapshots))
    current_step = next((
        step for step in steps
        if step.get("step_key") == document.get("current_step") and step.get("status") == "pending"
    ), None)
    active_delegation = None
    if user and current_step and current_step.get("status") == "pending" and current_step.get("approver_user_id") != user.get("id"):
        active_delegation = active_official_workflow_delegation(conn, document, current_step, user)
    if user and not is_participant and not active_delegation:
        if not official_document_user_same_company(user, document) or not str(user.get("company_id") or "").strip():
            raise PermissionError("official_document_company_forbidden")
        if not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
            raise PermissionError("official_document_access_denied")
    files = official_document_files(conn, document_id)
    logs = official_document_logs(conn, document_id)
    stamp_request = official_document_stamp_request(conn, document_id)
    dispatch_record = official_dispatch_record(conn, document_id)
    package = official_application_package(document, files, steps, logs, stamp_request, dispatch_record)
    correction = {
        "reason_category": document.get("correction_reason_category") or "",
        "missing_items": parse_json_any(document.get("correction_missing_items_json"), []),
        "due_at": document.get("correction_due_at") or "",
        "requested_at": document.get("correction_requested_at") or "",
        "resubmitted_at": document.get("correction_resubmitted_at") or "",
    }
    return {
        **document,
        "metadata": parse_json_field(document.get("metadata_json")),
        "official_seal": package.get("official_seal"),
        "document_category": package.get("document_category") or "",
        "approval_route_code": package.get("approval_route_code") or "",
        "approval_route_name": package.get("approval_route_name") or "",
        "application_package": package,
        "document_versions": package["document_versions"],
        "attachments": package["attachments"],
        "download_logs": package["download_logs"],
        "process_logs": package["process_logs"],
        "files": files,
        "approval_steps": steps,
        "approval_step_history": all_steps,
        "logs": logs,
        "stamp_request": package.get("stamp_request"),
        "dispatch_record": dispatch_record,
        "correction": correction,
        "can_correct": bool(user and user.get("id") == document.get("applicant_id") and document.get("current_status") in {"draft", "rejected"}),
        "can_resubmit": bool(user and user.get("id") == document.get("applicant_id") and document.get("current_status") == "rejected"),
        "can_download": is_participant,
        "can_manage_dispatch": bool(user and can_manage_official_dispatch(user, document, dispatch_record, session, steps)),
        "can_retry_stamp": bool(user and official_stamp_recoverable(document, stamp_request) and can_retry_official_stamp(user, steps)),
        "can_confirm": bool(user and user.get("id") == document.get("applicant_id") and document.get("current_step") == "applicant_confirm" and document.get("current_status") in {"stamped", "dispatched", "sent_by_applicant"}),
        "can_act": bool(user and current_step and current_step.get("status") == "pending" and (current_step.get("approver_user_id") == user.get("id") or active_delegation)),
        "acting_for_user_id": current_step.get("approver_user_id") if active_delegation and current_step else "",
        "delegation_id": active_delegation.get("id") if active_delegation else "",
    }


def list_official_documents(conn: sqlite3.Connection, query: Dict[str, List[str]] | None, session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    user = official_session_user(session)
    query = query or {}
    where: List[str] = []
    params: List[Any] = []
    user_company_id = str(user.get("company_id") or "").strip()
    if user_company_id:
        where.append(
            """
            (
              d.company_id = ?
              OR d.applicant_id = ?
              OR EXISTS (
                SELECT 1 FROM official_document_approval_steps participant_step
                WHERE participant_step.document_id = d.id
                  AND participant_step.approver_user_id = ?
              )
              OR EXISTS (
                SELECT 1 FROM approval_step_actor_snapshots participant_snapshot
                WHERE participant_snapshot.source_id = d.id
                  AND participant_snapshot.source_type IN ('official_document', 'official_documents', 'official_document_application')
                  AND participant_snapshot.approver_user_id = ?
              )
            )
            """
        )
        params.extend([user_company_id, user["id"], user["id"], user["id"]])
    if query.get("status"):
        where.append("d.current_status = ?")
        params.append(query["status"][0])
    if query.get("company_id"):
        where.append("d.company_id = ?")
        params.append(query["company_id"][0])
    if query.get("applicant_id"):
        where.append("d.applicant_id = ?")
        params.append(query["applicant_id"][0])
    scope = (query.get("scope") or [""])[0]
    if scope == "mine":
        where.append("d.applicant_id = ?")
        params.append(user["id"])
    elif scope == "todo":
        where.append(
            """
            (
              EXISTS (
                SELECT 1 FROM official_document_approval_steps s
                WHERE s.document_id = d.id
                  AND s.status = 'pending'
                  AND s.step_key = d.current_step
                  AND (
                    s.approver_user_id = ?
                    OR EXISTS (
                      SELECT 1 FROM official_workflow_delegations delegation
                      WHERE delegation.company_id = d.company_id
                        AND delegation.principal_user_id = s.approver_user_id
                        AND delegation.delegate_user_id = ?
                        AND delegation.status = 'active'
                        AND delegation.starts_at <= ?
                        AND delegation.ends_at > ?
                    )
                  )
              )
              OR EXISTS (
                SELECT 1 FROM official_document_dispatch_records r
                WHERE r.document_id = d.id
                  AND r.dispatch_status = 'pending'
                  AND r.dispatch_owner_user_id = ?
              )
              OR (
                EXISTS (
                  SELECT 1 FROM official_document_approval_steps ga
                  WHERE ga.document_id = d.id
                    AND ga.step_key = 'general_affairs_review'
                    AND ga.approver_user_id = ?
                )
                AND EXISTS (
                  SELECT 1 FROM official_document_stamp_requests sr
                  WHERE sr.document_id = d.id
                    AND sr.id = (
                      SELECT latest_sr.id FROM official_document_stamp_requests latest_sr
                      WHERE latest_sr.document_id = d.id
                      ORDER BY latest_sr.created_at DESC, latest_sr.id DESC LIMIT 1
                    )
                    AND sr.stamped_file_id IS NULL
                    AND (
                      (d.current_status = 'approved' AND d.current_step = 'auto_stamp' AND (
                        sr.status IN ('pending','approved','failed')
                        OR (sr.status = 'stamping' AND (sr.claim_expires_at IS NULL OR sr.claim_expires_at <= ?))
                      ))
                      OR (d.current_status = 'stamping_failed' AND d.current_step = 'general_affairs_review' AND (
                        sr.status IN ('pending','failed')
                        OR (sr.status = 'stamping' AND (sr.claim_expires_at IS NULL OR sr.claim_expires_at <= ?))
                      ))
                      OR (
                        d.current_status = 'stamping' AND d.current_step = 'auto_stamp'
                        AND sr.status = 'stamping'
                        AND (sr.claim_expires_at IS NULL OR sr.claim_expires_at <= ?)
                      )
                    )
                )
              )
            )
            """
        )
        timestamp = now()
        params.extend([user["id"], user["id"], timestamp, timestamp, user["id"], user["id"], timestamp, timestamp, timestamp])
    elif not user_company_id or not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
        where.append(
            """
            (
              d.applicant_id = ?
              OR EXISTS (
                SELECT 1 FROM official_document_approval_steps s
                WHERE s.document_id = d.id AND s.approver_user_id = ?
              )
              OR EXISTS (
                SELECT 1 FROM approval_step_actor_snapshots a
                WHERE a.source_id = d.id
                  AND a.source_type IN ('official_document', 'official_documents', 'official_document_application')
                  AND a.approver_user_id = ?
              )
              OR EXISTS (
                SELECT 1
                FROM official_document_approval_steps s
                JOIN official_workflow_delegations delegation
                  ON delegation.company_id = d.company_id
                 AND delegation.principal_user_id = s.approver_user_id
                 AND delegation.delegate_user_id = ?
                 AND delegation.status = 'active'
                 AND delegation.starts_at <= ?
                 AND delegation.ends_at > ?
                WHERE s.document_id = d.id
                  AND s.status = 'pending'
                  AND s.step_key = d.current_step
              )
            )
            """
        )
        timestamp = now()
        params.extend([user["id"], user["id"], user["id"], user["id"], timestamp, timestamp])
    sql = "SELECT d.* FROM official_documents d"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY d.created_at DESC LIMIT 300"
    rows = []
    for row in conn.execute(sql, params).fetchall():
        item = row_to_dict(row)
        seal_context = official_seal_context_from_document(item)
        item["official_seal"] = seal_context
        item["document_category"] = (seal_context or {}).get("document_category") or ""
        item["approval_route_code"] = (seal_context or {}).get("approval_route_code") or ""
        item["approval_route_name"] = (seal_context or {}).get("approval_route_name") or ""
        item["approval_steps"] = official_document_steps(conn, item["id"])
        raw_stamp_request = official_document_stamp_request(conn, item["id"])
        item["stamp_request"] = official_application_package(item, [], [], [], raw_stamp_request).get("stamp_request")
        item["dispatch_record"] = official_dispatch_record(conn, item["id"])
        item["current_step_name"] = next((step["step_name"] for step in official_document_steps(conn, item["id"]) if step.get("step_key") == item.get("current_step")), "")
        rows.append(item)
    return rows


def require_official_creation_company(user: Dict[str, Any], requested_company_id: Any) -> str:
    """Bind every applicant-created case to the Finance account company.

    Launch scope is only an operations allowlist; it is never authorization to
    create a document for another company.  The synthetic system actor remains
    available for explicitly coded launch-smoke helpers, which do not accept a
    browser supplied identity.
    """
    company_id = str(requested_company_id or "").strip()
    if not company_id:
        raise PermissionError("finance_company_required")
    if str(user.get("id") or "") == "system":
        return company_id
    user_company_id = str(user.get("company_id") or "").strip()
    if not user_company_id:
        if is_production() or finance_workflow_actor(user):
            raise PermissionError("finance_company_required")
        # Local deterministic fixtures predate Finance company columns. They
        # remain usable for unit tests only; production login cannot reach this
        # compatibility branch.
        return company_id
    if company_id != user_company_id:
        raise PermissionError("official_document_company_forbidden")
    return company_id


def require_official_seal_classification(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Require the server-derived seal category and reject client no-stamp bypasses."""
    raw_requires_stamp = payload.get("requires_stamp", True)
    requires_stamp = str(raw_requires_stamp).strip().lower() not in {"false", "0", "no", "off", "none"}
    if not requires_stamp:
        raise PermissionError("official_document_stamp_required")
    seal_context = official_seal_approval_context(payload)
    if not seal_context:
        raise ValueError("official_seal_document_category_required")
    return seal_context


def create_official_document(conn: sqlite3.Connection, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    if not session_has_any_permission(session, ["official_documents.compose", "official_documents.all_todo"]):
        raise PermissionError("official_document_create_forbidden")
    source_type = payload.get("source_type") or "blank_editor"
    if source_type not in {"blank_editor", "uploaded_pdf"}:
        raise ValueError("invalid_official_document_source_type")
    original_pdf_data = validated_uploaded_official_pdf(payload) if source_type == "uploaded_pdf" else b""
    company_id = require_official_creation_company(user, payload.get("company_id") or user.get("company_id"))
    if not launch_company_in_scope(company_id):
        raise PermissionError("company_not_in_launch_scope")
    company = official_company_row(conn, company_id)
    dispatch_method = official_document_dispatch_method(source_type, payload.get("dispatch_method"))
    document_id = payload.get("id") or f"OD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    ts = now()
    extra_metadata = dict(payload.get("metadata")) if isinstance(payload.get("metadata"), dict) else {}
    extra_metadata.setdefault("contact_owner", payload.get("handler_name") or user.get("name") or "")
    extra_metadata.setdefault("contact_email", user.get("email") or "")
    extra_metadata.setdefault("contact_address", user.get("company_address") or company.get("address") or "")
    extra_metadata["contact_fax"] = str(
        extra_metadata.get("contact_fax") or payload.get("contact_fax") or payload.get("contactFax") or EDOC_DEFAULT_CONTACT_FAX
    ).strip()[:120] or EDOC_DEFAULT_CONTACT_FAX
    extra_metadata["copy_recipients"] = official_pdf_copy_recipients(
        extra_metadata.get("copy_recipients")
        or extra_metadata.get("copyRecipients")
        or payload.get("copy_recipients")
        or payload.get("copyRecipients"),
        company.get("name") or "",
    )[:OFFICIAL_COPY_RECIPIENTS_MAX_LENGTH]
    requires_stamp = True
    seal_context = require_official_seal_classification(payload)
    workflow_template_key = (seal_context or {}).get("workflow_template_key") or payload.get("workflow_template_key") or "internal_official_dispatch_v1"
    metadata = {
        "attachments": payload.get("attachments_summary") or payload.get("attachments") or "",
        "workflow_template": workflow_template_key,
        "future_rule_inputs": {
            "company_id": company_id,
            "department": user.get("unit"),
            "document_type": payload.get("document_type"),
            "seal_id": payload.get("seal_id"),
            "dispatch_method": dispatch_method,
            "amount": payload.get("amount"),
            "document_category": (seal_context or {}).get("document_category") or "",
            "approval_route_code": (seal_context or {}).get("approval_route_code") or "",
        },
    }
    if seal_context:
        metadata["official_seal"] = {
            **seal_context,
            "approval_steps": [
                {"order": step["order"], "key": step["key"], "name": step["name"], "role": step["role"]}
                for step in official_seal_workflow_steps(seal_context["approval_route_code"])
                if step["key"] != "applicant_confirm"
            ],
        }
    if extra_metadata:
        metadata["extra"] = extra_metadata
        if extra_metadata.get("journey"):
            metadata["launch_smoke_journey"] = extra_metadata.get("journey")
        if extra_metadata.get("source"):
            metadata["source"] = extra_metadata.get("source")
    seal_id = payload.get("seal_id")
    submit_requested = bool(payload.get("submit", True))
    if seal_id and requires_stamp:
        validate_official_document_seal(conn, seal_id, company_id, require_current=submit_requested)
    document = {
        "id": document_id,
        "company_id": company_id,
        "document_type": payload.get("document_type") or ("uploaded_pdf_for_stamp" if source_type == "uploaded_pdf" else "outgoing_official_document"),
        "source_type": source_type,
        "title": payload.get("title") or payload.get("subject") or "未命名發文申請",
        "subject": payload.get("subject") or payload.get("title") or "",
        "description": payload.get("description") or payload.get("body") or "",
        "method": payload.get("method") or payload.get("辦法") or "",
        "recipient": payload.get("recipient") or payload.get("agency_name") or "",
        "dispatch_unit": payload.get("dispatch_unit") or user.get("unit") or "",
        "handler_name": payload.get("handler_name") or user.get("name") or "",
        "applicant_id": user["id"],
        "applicant_name": user.get("name") or user.get("email"),
        "applicant_department_id": payload.get("applicant_department_id") or user.get("unit") or "",
        "applicant_department_name": payload.get("applicant_department_name") or user.get("unit") or "",
        "workflow_template_key": workflow_template_key,
        "dispatch_method": dispatch_method,
        "requires_stamp": 1 if requires_stamp else 0,
        "current_status": "draft",
        "current_step": "",
        "request_reason": payload.get("request_reason") or payload.get("reason") or "",
        "stamped_file_id": None,
        "metadata_json": metadata,
        "created_at": ts,
        "updated_at": ts,
    }
    insert_row(conn, "official_documents", document)
    if source_type == "uploaded_pdf":
        file_row = store_official_pdf_file(conn, document_id, "original_pdf", Path(payload.get("file_name") or f"{document_id}.pdf").name, original_pdf_data, official_actor_name(user))
        insert_official_log(conn, document_id, "upload_original_pdf", user, file_row["file_hash"], file_id=file_row["id"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    else:
        ensure_official_generated_pdf(conn, document, official_actor_name(user))
    if seal_id and requires_stamp:
        position = official_stamp_position_payload(payload)
        stamp_request = {
            "id": f"ODSTAMP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "document_id": document_id,
            "company_id": company_id,
            "seal_id": seal_id,
            "requested_by": user["id"],
            **position,
            "status": "pending" if submit_requested else "draft",
            "stamped_file_id": None,
            "error_message": "",
            "created_at": ts,
            "stamped_at": "",
            "updated_at": ts,
        }
        insert_row(conn, "official_document_stamp_requests", stamp_request)
        created_positions = replace_official_stamp_positions(
            conn,
            stamp_request["id"],
            seal_id,
            payload,
            allow_unbound_current=not submit_requested,
        )
        first_position = created_positions[0]
        conn.execute(
            """
            UPDATE official_document_stamp_requests
            SET seal_id = ?, stamp_page = ?, stamp_x = ?, stamp_y = ?, stamp_width = ?, stamp_height = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                first_position["seal_id"], first_position["page"], first_position["x"], first_position["y"],
                first_position["width"], first_position["height"], now(), stamp_request["id"],
            ),
        )
        replace_official_text_overlays(conn, stamp_request["id"], payload)
    insert_official_log(conn, document_id, "create", user, document["request_reason"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    if payload.get("submit", True):
        return submit_official_document(conn, document_id, payload, session)
    return official_document_detail(conn, document_id, session)


OFFICIAL_CORRECTION_EDITABLE_FIELDS = {
    "title",
    "subject",
    "description",
    "method",
    "recipient",
    "dispatch_unit",
    "handler_name",
    "request_reason",
}

OFFICIAL_CORRECTION_CLASSIFICATION_FIELDS = {
    "document_category",
    "documentCategory",
    "approval_route_code",
    "approvalRouteCode",
}
OFFICIAL_CORRECTION_STAMP_FIELDS = {
    "seal_id",
    "stamp_position",
    "stamp_positions",
    "positions",
    "text_overlays",
    "textOverlays",
}
OFFICIAL_CORRECTION_FILE_FIELDS = {"content_base64", "file_content_base64"}
OFFICIAL_CORRECTION_METADATA_TEXT_FIELDS = {
    "source": 80,
    "legacy_document_id": 180,
    "dispatch_no": 180,
    "company_name": 300,
    "document_type": 80,
    "priority": 40,
    "large_seal_type": 80,
    "small_seal_type": 80,
    "purpose": 2000,
    "attachment_details": 5000,
    "contact_address": 1000,
    "contact_owner": 300,
    "contact_phone": 120,
    "contact_fax": 120,
    "contact_email": 320,
    "copy_recipients": OFFICIAL_COPY_RECIPIENTS_MAX_LENGTH,
}
OFFICIAL_CORRECTION_RENDER_METADATA_FIELDS = {
    "document_type",
    "priority",
    "purpose",
    "attachment_details",
    "contact_address",
    "contact_owner",
    "contact_phone",
    "contact_fax",
    "contact_email",
    "copy_recipients",
}


def _official_correction_client_metadata(payload: Dict[str, Any]) -> Dict[str, Any]:
    source = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    sanitized: Dict[str, Any] = {}
    for key, limit in OFFICIAL_CORRECTION_METADATA_TEXT_FIELDS.items():
        if key in source:
            value = source.get(key)
            if key == "contact_fax":
                value = str(value or EDOC_DEFAULT_CONTACT_FAX).strip() or EDOC_DEFAULT_CONTACT_FAX
            elif key == "copy_recipients":
                value = official_pdf_party_text(value)
            sanitized[key] = str(value or "").strip()[:limit]
    placements = source.get("seal_placements")
    if isinstance(placements, dict):
        safe_placements: Dict[str, Dict[str, float | int]] = {}
        for kind in ("large", "small"):
            item = placements.get(kind)
            if not isinstance(item, dict):
                continue
            safe_placements[kind] = {
                "page": max(1, min(EDOC_EDITOR_MAX_PAGES, int(pdf_safe_float(item.get("page"), 1)))),
                "x": max(0.0, min(100.0, round(pdf_safe_float(item.get("x"), 0), 4))),
                "y": max(0.0, min(100.0, round(pdf_safe_float(item.get("y"), 0), 4))),
            }
        sanitized["seal_placements"] = safe_placements
    attachments_summary = str(payload.get("attachments_summary") or "").strip()
    if attachments_summary:
        sanitized.setdefault("attachment_details", attachments_summary[:5000])
    return sanitized


def _official_correction_metadata(
    document: Dict[str, Any],
    seal_context: Dict[str, Any],
    seal_id: str,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    """Merge server-derived classification without replacing audit/editor metadata."""
    metadata = parse_json_field(document.get("metadata_json"))
    metadata = json.loads(json.dumps(metadata, ensure_ascii=False))
    client_metadata = _official_correction_client_metadata(payload)
    extra = metadata.get("extra")
    if not isinstance(extra, dict):
        extra = {}
    for key, value in client_metadata.items():
        metadata[key] = value
        extra[key] = value
    metadata["extra"] = extra
    if "attachment_details" in client_metadata:
        metadata["attachments"] = client_metadata["attachment_details"]
    metadata["workflow_template"] = seal_context["workflow_template_key"]
    future = metadata.get("future_rule_inputs")
    if not isinstance(future, dict):
        future = {}
    future.update({
        "company_id": document.get("company_id") or "",
        "document_type": document.get("document_type") or "",
        "seal_id": seal_id,
        "dispatch_method": document.get("dispatch_method") or "",
        "document_category": seal_context["document_category"],
        "approval_route_code": seal_context["approval_route_code"],
    })
    metadata["future_rule_inputs"] = future
    metadata["official_seal"] = {
        **seal_context,
        "approval_steps": [
            {
                "order": step["order"],
                "key": step["key"],
                "name": step["name"],
                "role": step["role"],
            }
            for step in official_seal_workflow_steps(seal_context["approval_route_code"])
            if step["key"] != "applicant_confirm"
        ],
    }
    metadata.update({
        "document_category": seal_context["document_category"],
        "document_category_group": seal_context["document_category_group"],
        "approval_route_code": seal_context["approval_route_code"],
        "approval_route_name": seal_context["approval_route_name"],
        "workflow_template_key": seal_context["workflow_template_key"],
    })
    if len(json.dumps(metadata, ensure_ascii=False, separators=(",", ":")).encode("utf-8")) > 64 * 1024:
        raise ValueError("official_document_metadata_too_large")
    return metadata


def _official_correction_render_metadata_changes(
    document: Dict[str, Any],
    updated_metadata: Dict[str, Any],
) -> List[str]:
    """Return compose fields whose values can affect a generated letter PDF."""
    previous = parse_json_field(document.get("metadata_json"))
    previous_extra = previous.get("extra") if isinstance(previous.get("extra"), dict) else {}
    updated_extra = updated_metadata.get("extra") if isinstance(updated_metadata.get("extra"), dict) else {}
    changed: List[str] = []
    for key in sorted(OFFICIAL_CORRECTION_RENDER_METADATA_FIELDS):
        previous_value = previous_extra.get(key, previous.get(key, ""))
        updated_value = updated_extra.get(key, updated_metadata.get(key, ""))
        if key == "attachment_details":
            previous_value = previous.get("attachments", previous_value)
            updated_value = updated_metadata.get("attachments", updated_value)
        if str(previous_value or "") != str(updated_value or ""):
            changed.append(key)
    return changed


def _validate_official_correction_geometry(
    positions: List[Dict[str, Any]],
    pages: List[Dict[str, Any]],
) -> None:
    if not positions:
        return
    if not pages:
        raise ValueError("official_document_source_pdf_required")
    for position in positions:
        page_number = int(position.get("page") or 0)
        if page_number < 1 or page_number > len(pages):
            raise ValueError("official_stamp_page_out_of_range")
        page = pages[page_number - 1]
        page_width = pdf_safe_float(page.get("widthPt"), float("nan"))
        page_height = pdf_safe_float(page.get("heightPt"), float("nan"))
        require_a4_pdf_page(page_width, page_height, page_number)
        x = pdf_safe_float(position.get("x"), float("nan"))
        y = pdf_safe_float(position.get("y"), float("nan"))
        width = pdf_safe_float(position.get("width"), float("nan"))
        height = pdf_safe_float(position.get("height"), float("nan"))
        if not all(math.isfinite(value) for value in (x, y, width, height)):
            raise ValueError("invalid_official_stamp_position")
        if x < 0 or y < 0 or width <= 0 or height <= 0:
            raise ValueError("invalid_official_stamp_position")
        if x + width > page_width + 1 or y + height > page_height + 1:
            raise ValueError("invalid_official_stamp_position")


def _official_correction_plan(
    document: Dict[str, Any],
    payload: Dict[str, Any],
    stamp_request: Dict[str, Any] | None,
    source_pages: List[Dict[str, Any]] | None = None,
    seal_lookup: Any = None,
    seal_file_lookup: Any = None,
) -> Dict[str, Any]:
    """Validate a correction payload and return only server-owned mutations.

    The browser can suggest a route name or workflow nodes, but the persisted
    route and approval steps always come from ``document_category``.
    """
    requested_company = str(payload.get("company_id") or "").strip()
    if requested_company and requested_company != str(document.get("company_id") or ""):
        raise PermissionError("official_document_company_forbidden")
    requested_source_type = str(payload.get("source_type") or "").strip()
    if requested_source_type and requested_source_type != str(document.get("source_type") or ""):
        raise ValueError("official_document_source_type_immutable")

    updates = {
        key: str(payload.get(key) or "").strip()
        for key in OFFICIAL_CORRECTION_EDITABLE_FIELDS
        if key in payload
    }
    if "title" in updates and not updates["title"]:
        raise ValueError("official_document_title_required")

    classification_supplied = bool(OFFICIAL_CORRECTION_CLASSIFICATION_FIELDS.intersection(payload))
    seal_context = (
        require_official_seal_classification(payload)
        if classification_supplied
        else official_seal_context_from_document(document)
    )
    if not seal_context:
        raise ValueError("official_seal_document_category_required")
    expected_group = str(payload.get("document_category_group") or "").strip()
    if expected_group and expected_group != seal_context["document_category_group"]:
        raise ValueError("official_seal_category_group_mismatch")
    expected_route_name = str(payload.get("approval_route_name") or "").strip()
    if expected_route_name and expected_route_name != seal_context["approval_route_name"]:
        raise ValueError("official_seal_route_name_mismatch")

    seal_id = str(payload.get("seal_id") or (stamp_request or {}).get("seal_id") or "").strip()
    if not seal_id and document.get("current_status") != "draft":
        raise ValueError("official_document_seal_required")
    positions_supplied = "stamp_positions" in payload or "positions" in payload or "stamp_position" in payload
    existing_positions = (stamp_request or {}).get("stamp_positions") or []
    if positions_supplied:
        raw_positions = payload.get("stamp_positions") if "stamp_positions" in payload else payload.get("positions")
        if raw_positions is not None and not raw_positions and document.get("current_status") != "draft":
            raise ValueError("official_document_seal_position_required")
        positions = [] if raw_positions is not None and not raw_positions else official_stamp_positions_payload(payload, seal_id)
    else:
        positions = official_stamp_positions_payload(
            {"stamp_positions": existing_positions},
            seal_id,
        ) if existing_positions or seal_id else []
    if positions:
        positions = preserve_unidentified_official_position_bindings(
            positions,
            existing_positions,
        )
        positions = require_official_position_set_intent(
            positions,
            existing_positions,
        )
    if positions and seal_lookup and seal_file_lookup:
        positions = canonicalize_official_company_seal_positions(
            positions,
            seal_lookup,
            seal_file_lookup,
            existing_positions,
            allow_unbound_current=document.get("current_status") == "draft",
        )
    if len(positions) > 100:
        raise ValueError("official_document_seal_position_limit")
    overlays_supplied = "text_overlays" in payload or "textOverlays" in payload
    overlays = (
        official_text_overlays_payload(payload)
        if overlays_supplied
        else official_text_overlays_payload({"text_overlays": (stamp_request or {}).get("text_overlays") or []})
    )
    if overlays and not positions:
        raise ValueError("official_document_text_overlay_requires_seal_position")

    new_pdf = None
    geometry_pages = list(source_pages or [])
    if OFFICIAL_CORRECTION_FILE_FIELDS.intersection(payload):
        if document.get("source_type") != "uploaded_pdf":
            raise ValueError("official_document_source_pdf_not_replaceable")
        new_pdf = validated_uploaded_official_pdf(payload)
        inspection = inspect_editor_pdf(new_pdf)
        geometry_pages = list(inspection.get("pages") or [])
    _validate_official_correction_geometry(positions, geometry_pages)

    client_metadata = _official_correction_client_metadata(payload)
    metadata = _official_correction_metadata(document, seal_context, seal_id, payload)
    updates.update({
        "workflow_template_key": seal_context["workflow_template_key"],
        "metadata_json": json.dumps(metadata, ensure_ascii=False),
    })
    if not (
        set(payload).intersection(OFFICIAL_CORRECTION_EDITABLE_FIELDS)
        or classification_supplied
        or set(payload).intersection(OFFICIAL_CORRECTION_STAMP_FIELDS)
        or new_pdf is not None
        or client_metadata
    ):
        raise ValueError("official_document_correction_fields_required")
    return {
        "updates": updates,
        "seal_context": seal_context,
        "seal_id": seal_id,
        "positions": positions,
        "positions_supplied": positions_supplied,
        "text_overlays": overlays,
        "metadata": metadata,
        "render_metadata_changes": _official_correction_render_metadata_changes(document, metadata),
        "new_pdf": new_pdf,
        "file_name": Path(str(payload.get("file_name") or f"{document['id']}.pdf")).name,
    }


def _sqlite_store_correction_source_file(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    file_type: str,
    file_name: str,
    data: bytes,
    actor: str,
    created_paths: List[Path],
) -> Dict[str, Any]:
    scan_result = scan_official_upload_bytes(data, file_name) if file_type == "original_pdf" else None
    file_row = store_file_object(
        conn,
        document["id"],
        file_name,
        data,
        "official-documents",
        f"{file_type}-correction",
        actor,
        "application/pdf",
    )
    created_paths.append(STORAGE_DIR / file_row["storage_key"])
    if scan_result:
        file_row = persist_file_object_scan_result(
            conn,
            file_row["id"],
            scan_result[0],
            scan_result[1],
            actor,
        )
    return insert_official_document_file(conn, document["id"], file_type, file_row, actor)


def update_official_document_correction(
    conn: sqlite3.Connection,
    document_id: str,
    payload: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document.get("applicant_id") != user.get("id"):
        raise PermissionError("only_applicant_can_correct")
    if document.get("current_status") not in {"draft", "rejected"}:
        raise ValueError("official_document_correction_locked")
    stamp_request = official_document_stamp_request(conn, document_id)
    source_pages: List[Dict[str, Any]] = []
    if not OFFICIAL_CORRECTION_FILE_FIELDS.intersection(payload):
        source_meta = official_latest_source_file(conn, document)
        if not source_meta.get("file_object_id"):
            raise ValueError("official_document_file_object_missing")
        source_object, source_bytes = read_file_object_bytes(conn, source_meta["file_object_id"])
        verify_official_file_bytes(source_meta, source_object, source_bytes)
        source_pages = list(inspect_editor_pdf(source_bytes).get("pages") or [])
    plan = _official_correction_plan(
        document,
        payload,
        stamp_request,
        source_pages,
        lambda item_seal_id: company_seal_row(conn, item_seal_id),
        lambda file_id, item_seal_id: local_official_seal_file_by_id(conn, file_id, item_seal_id),
    )
    for seal_id in sorted({str(item.get("seal_id") or plan["seal_id"]) for item in plan["positions"]}):
        if not seal_id:
            continue
        validate_official_document_seal(
            conn,
            seal_id,
            str(document.get("company_id") or ""),
            require_current=False,
        )

    changed_fields = [
        key
        for key in OFFICIAL_CORRECTION_EDITABLE_FIELDS
        if key in plan["updates"] and str(document.get(key) or "") != str(plan["updates"][key] or "")
    ]
    changed_fields.extend(plan["render_metadata_changes"])
    document_body_changed = bool(changed_fields)
    previous_context = official_seal_context_from_document(document) or {}
    if previous_context.get("document_category") != plan["seal_context"]["document_category"]:
        changed_fields.append("document_category")
    previous_positions = (stamp_request or {}).get("stamp_positions") or []
    comparable_positions = [
        {key: item.get(key) for key in OFFICIAL_STAMP_POSITION_COMPARABLE_FIELDS}
        for item in previous_positions
    ]
    planned_positions = [
        {key: item.get(key) for key in OFFICIAL_STAMP_POSITION_COMPARABLE_FIELDS}
        for item in plan["positions"]
    ]
    if canonical_json_hash(comparable_positions) != canonical_json_hash(planned_positions):
        changed_fields.append("stamp_positions")
    if str((stamp_request or {}).get("seal_id") or "") != plan["seal_id"]:
        changed_fields.append("seal_id")

    created_paths: List[Path] = []
    conn.execute("SAVEPOINT official_document_correction")
    try:
        assignments = ", ".join(f"{key} = ?" for key in plan["updates"])
        conn.execute(
            f"UPDATE official_documents SET {assignments}, updated_at = ? WHERE id = ?",
            [*plan["updates"].values(), now(), document_id],
        )
        updated_document = official_document_row(conn, document_id)
        position = plan["positions"][0] if plan["positions"] else None
        request_id = str((stamp_request or {}).get("id") or "")
        if position and (document.get("current_status") == "rejected" or not request_id):
            request_id = f"ODSTAMP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
            insert_row(conn, "official_document_stamp_requests", {
                "id": request_id,
                "document_id": document_id,
                "company_id": document["company_id"],
                "seal_id": plan["seal_id"],
                "requested_by": user["id"],
                "stamp_page": position["page"],
                "stamp_x": position["x"],
                "stamp_y": position["y"],
                "stamp_width": position["width"],
                "stamp_height": position["height"],
                "status": "draft" if document.get("current_status") == "draft" else "pending",
                "stamped_file_id": None,
                "locked_editor_revision_id": None,
                "locked_source_sha256": None,
                "prepared_file_id": None,
                "prepared_sha256": None,
                "editor_manifest_sha256": None,
                "editor_schema_version": None,
                "renderer_version": None,
                "editor_locked_at": None,
                "error_message": "",
                "created_at": now(),
                "stamped_at": "",
                "updated_at": now(),
            })
            if stamp_request and document.get("current_status") == "rejected":
                conn.execute(
                    "UPDATE official_document_stamp_requests SET status = 'failed', error_message = 'superseded_by_correction', updated_at = ? WHERE id = ? AND status <> 'stamped'",
                    (now(), stamp_request["id"]),
                )
        elif position and request_id:
            conn.execute(
                """
                UPDATE official_document_stamp_requests
                   SET seal_id = ?, stamp_page = ?, stamp_x = ?, stamp_y = ?,
                       stamp_width = ?, stamp_height = ?, status = ?,
                       stamped_file_id = NULL, locked_editor_revision_id = NULL,
                       locked_source_sha256 = NULL, prepared_file_id = NULL,
                       prepared_sha256 = NULL, editor_manifest_sha256 = NULL,
                       editor_schema_version = NULL, renderer_version = NULL,
                       editor_locked_at = NULL, claim_token = NULL,
                       claim_owner_id = NULL, claim_started_at = NULL,
                       claim_expires_at = NULL, claim_attempt_count = 0,
                       error_message = '', stamped_at = '', updated_at = ?
                 WHERE id = ?
                """,
                (
                    plan["seal_id"], position["page"], position["x"], position["y"],
                    position["width"], position["height"],
                    "draft" if document.get("current_status") == "draft" else "pending",
                    now(), request_id,
                ),
            )
        elif plan["positions_supplied"] and request_id:
            conn.execute("DELETE FROM official_document_stamp_positions WHERE request_id = ?", (request_id,))
            conn.execute("DELETE FROM official_document_text_overlays WHERE request_id = ?", (request_id,))
            conn.execute(
                """
                UPDATE official_document_stamp_requests
                   SET status = 'failed', stamped_file_id = NULL,
                       locked_editor_revision_id = NULL, locked_source_sha256 = NULL,
                       prepared_file_id = NULL, prepared_sha256 = NULL,
                       editor_manifest_sha256 = NULL, editor_schema_version = NULL,
                       renderer_version = NULL, editor_locked_at = NULL,
                       claim_token = NULL, claim_owner_id = NULL,
                       claim_started_at = NULL, claim_expires_at = NULL,
                       claim_attempt_count = 0,
                       error_message = 'cleared_by_draft_correction', stamped_at = '',
                       updated_at = ?
                 WHERE id = ?
                """,
                (now(), request_id),
            )
        if position and request_id:
            replace_official_stamp_positions(
                conn,
                request_id,
                plan["seal_id"],
                {"stamp_positions": plan["positions"]},
                allow_persisted_bindings=True,
                allow_unbound_current=document.get("current_status") == "draft",
            )
            replace_official_text_overlays(
                conn,
                request_id,
                {"text_overlays": plan["text_overlays"]},
            )

        source_file = None
        if plan["new_pdf"] is not None:
            new_hash = sha256_bytes(plan["new_pdf"])
            latest = conn.execute(
                "SELECT file_hash FROM official_document_files WHERE document_id = ? AND file_type = 'original_pdf' ORDER BY version DESC LIMIT 1",
                (document_id,),
            ).fetchone()
            if not latest or latest["file_hash"] != new_hash:
                source_file = _sqlite_store_correction_source_file(
                    conn,
                    updated_document,
                    "original_pdf",
                    plan["file_name"],
                    plan["new_pdf"],
                    official_actor_name(user),
                    created_paths,
                )
                changed_fields.append("original_pdf")
        elif document.get("source_type") == "blank_editor" and document_body_changed:
            package = build_official_pdf_package(
                official_pdf_document_payload(conn, updated_document),
                [],
                "歲悅正式函",
                1,
            )
            source_file = _sqlite_store_correction_source_file(
                conn,
                updated_document,
                "generated_pdf",
                f"{document_id}-generated-correction.pdf",
                package["data"],
                official_actor_name(user),
                created_paths,
            )
            changed_fields.append("generated_pdf")

        changed_fields = sorted(set(changed_fields))
        insert_official_log(
            conn,
            document_id,
            "correct",
            user,
            "申請人完成補正並建立可稽核的新版本",
            file_id=(source_file or {}).get("id") or "",
            ip_address=payload.get("ip_address") or "",
            user_agent=payload.get("user_agent") or "",
            decision_evidence={
                "updated_fields": changed_fields,
                "stamp_request_id": request_id,
                "stamp_position_count": len(plan["positions"]),
                "source_file_id": (source_file or {}).get("id") or "",
                "source_sha256": (source_file or {}).get("file_hash") or "",
            },
        )
        conn.execute("RELEASE SAVEPOINT official_document_correction")
    except Exception:
        conn.execute("ROLLBACK TO SAVEPOINT official_document_correction")
        conn.execute("RELEASE SAVEPOINT official_document_correction")
        for path in created_paths:
            path.unlink(missing_ok=True)
        raise
    return official_document_detail(conn, document_id, session)


def resubmit_official_document(
    conn: sqlite3.Connection,
    document_id: str,
    payload: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document.get("applicant_id") != user.get("id"):
        raise PermissionError("only_applicant_can_resubmit")
    if document.get("current_status") != "rejected":
        raise ValueError("official_document_not_rejected")
    result = submit_official_document(conn, document_id, payload, session)
    timestamp = now()
    conn.execute(
        """
        UPDATE official_documents
        SET correction_resubmitted_at = ?, correction_reason_category = NULL,
            correction_missing_items_json = '[]', correction_due_at = NULL,
            updated_at = ?
        WHERE id = ?
        """,
        (timestamp, timestamp, document_id),
    )
    insert_official_log(
        conn,
        document_id,
        "resubmit",
        user,
        payload.get("comment") or "補正完成，重新由第一關送簽",
        ip_address=payload.get("ip_address") or "",
        user_agent=payload.get("user_agent") or "",
    )
    return official_document_detail(conn, document_id, session)


def submit_official_document(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document["applicant_id"] != user["id"]:
        raise PermissionError("only_applicant_can_submit")
    if document["current_status"] not in {"draft", "rejected"}:
        raise ValueError("official_document_not_submittable")
    # SQLite rejection cloning is synchronous and shares the rejection
    # transaction.  The durable rejection job gate below is Supabase-only;
    # consulting it here would incorrectly couple local/offline operation to a
    # configured remote runtime.
    if not bool(document.get("requires_stamp", 1)):
        raise PermissionError("official_document_stamp_required")
    seal_context = official_seal_context_from_document(document)
    if not seal_context:
        raise ValueError("official_seal_document_category_required")
    workflow_steps = official_workflow_steps_for_document(conn, document)
    actor_plan: Dict[str, Dict[str, Any]] | None = None
    workflow_lock_metadata: Dict[str, Any] | None = None
    if is_production():
        snapshot = current_finance_bridge_snapshot(user.get("email") or "")
        finance_role = strict_finance_role_profile(
            (snapshot.get("identity") or {}).get("role")
        )["logging_role_key"]
        workflow_steps = official_workflow_steps_for_finance_applicant(
            seal_context["approval_route_code"],
            finance_role,
        )
        user, actor_plan = sync_sqlite_finance_snapshot(
            conn,
            snapshot,
            auth_user_id=user.get("auth_user_id") or "",
            expected_user_id=user["id"],
            require_workflow=True,
            required_step_keys=(step["key"] for step in workflow_steps),
        )
        workflow_lock_metadata = locked_official_finance_workflow_metadata(
            document,
            snapshot,
            finance_role,
            workflow_steps,
        )
        session = {**(session or {}), "user": user}
    require_official_creation_company(user, document.get("company_id"))
    # The live Finance snapshot and complete exact actor plan are resolved
    # before AV/editor/seal locks mutate the application.
    assert_official_document_uploads_av_clean(conn, document)
    lock_official_editor_submission(conn, document, payload, user)
    stamp_request = official_document_stamp_request(conn, document_id)
    if not stamp_request:
        raise ValueError("official_document_seal_required")
    stamp_request = lock_official_stamp_seal_versions(conn, document, stamp_request)
    validate_official_document_seal(conn, stamp_request["seal_id"], document["company_id"], require_current=True)
    if document["source_type"] == "blank_editor":
        ensure_official_generated_pdf(conn, document, official_actor_name(user))
    if workflow_lock_metadata is not None:
        document["metadata_json"] = json.dumps(workflow_lock_metadata, ensure_ascii=False)
        conn.execute(
            "UPDATE official_documents SET metadata_json = ?, updated_at = ? WHERE id = ?",
            (document["metadata_json"], now(), document_id),
        )
        workflow_lock = workflow_lock_metadata["official_seal"]
        insert_official_log(
            conn,
            document_id,
            "lock_finance_workflow",
            user,
            (
                f"policy={workflow_lock['conditional_policy_version']};"
                f"role={workflow_lock['applicant_finance_role']};"
                f"steps={','.join(workflow_lock['approval_step_keys'])};"
                f"snapshot={workflow_lock['finance_snapshot_sha256']}"
            ),
        )
    applicant = active_user_by_id(conn, document["applicant_id"]) or user
    steps = create_official_workflow_steps(
        conn,
        document,
        applicant,
        actor_plan=actor_plan,
        workflow_steps=workflow_steps,
    )
    first = steps[0]
    review_started_at = now()
    conn.execute("UPDATE official_documents SET current_status = ?, current_step = ?, updated_at = ? WHERE id = ?", (OFFICIAL_DOCUMENT_STEP_STATUS[first["step_key"]], first["step_key"], review_started_at, document_id))
    conn.execute(
        "UPDATE official_document_approval_steps SET review_started_at = ?, updated_at = ? WHERE id = ? AND review_started_at IS NULL",
        (review_started_at, review_started_at, first["id"]),
    )
    insert_official_log(conn, document_id, "submit", user, payload.get("comment") or "送出發文用印簽核", step_id=first["id"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    if first.get("approver_role"):
        approver = active_user_by_id(conn, first.get("approver_user_id") or "") or {}
        create_and_deliver_notification(conn, {
            "type": "發文簽核",
            "title": f"{document['title']} 待{first['step_name']}簽核",
            **exact_notification_target_payload(approver, document.get("company_id") or ""),
            "source": document_id,
            "priority": "高",
            "body": f"{document.get('applicant_name') or '申請人'} 已送出發文用印申請。",
        })
    return official_document_detail(conn, document_id, session)


def current_official_pending_step(conn: sqlite3.Connection, document: Dict[str, Any]) -> Dict[str, Any]:
    row = conn.execute(
        """
        SELECT * FROM official_document_approval_steps
        WHERE document_id = ? AND step_key = ? AND status = 'pending'
        ORDER BY step_order LIMIT 1
        """,
        (document["id"], document.get("current_step") or ""),
    ).fetchone()
    if not row:
        raise ValueError("official_document_current_step_not_pending")
    return row_to_dict(row)


def _active_delegation_at(row: Dict[str, Any], timestamp: datetime | None = None) -> bool:
    current = timestamp or datetime.now()
    starts = parse_date_value(str(row.get("starts_at") or ""))
    ends = parse_date_value(str(row.get("ends_at") or ""))
    return bool(row.get("status") == "active" and starts and ends and starts <= current < ends)


def active_official_workflow_delegation(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    step: Dict[str, Any],
    delegate: Dict[str, Any],
) -> Dict[str, Any] | None:
    rows = [
        row_to_dict(row)
        for row in conn.execute(
            """
            SELECT * FROM official_workflow_delegations
            WHERE company_id = ? AND principal_user_id = ? AND delegate_user_id = ? AND status = 'active'
            ORDER BY starts_at DESC
            """,
            (document.get("company_id") or "", step.get("approver_user_id") or "", delegate.get("id") or ""),
        ).fetchall()
        if _active_delegation_at(row_to_dict(row))
    ]
    if len(rows) > 1:
        raise ValueError("official_workflow_delegation_ambiguous")
    if not rows:
        return None
    principal = active_user_by_id(conn, step.get("approver_user_id") or "")
    active_delegate = active_user_by_id(conn, delegate.get("id") or "")
    if not principal or not active_delegate:
        raise PermissionError("official_workflow_delegation_actor_inactive")
    if str(active_delegate.get("company_id") or "") not in {"", str(document.get("company_id") or "")}:
        raise PermissionError("official_workflow_delegation_company_forbidden")
    return rows[0]


def supabase_active_official_workflow_delegation(
    document: Dict[str, Any],
    step: Dict[str, Any],
    delegate: Dict[str, Any],
) -> Dict[str, Any] | None:
    rows = [
        row
        for row in supabase_filter_rows(
            "official_workflow_delegations",
            {
                "company_id": document.get("company_id") or "",
                "principal_user_id": step.get("approver_user_id") or "",
                "delegate_user_id": delegate.get("id") or "",
                "status": "active",
            },
            order="starts_at.desc",
            limit=10,
        )
        if _active_delegation_at(row)
    ]
    if len(rows) > 1:
        raise ValueError("official_workflow_delegation_ambiguous")
    if not rows:
        return None
    principal = supabase_user_by_id(step.get("approver_user_id") or "")
    active_delegate = supabase_user_by_id(delegate.get("id") or "")
    if not principal or not active_delegate or principal.get("status") != "啟用" or active_delegate.get("status") != "啟用":
        raise PermissionError("official_workflow_delegation_actor_inactive")
    if str(active_delegate.get("company_id") or "") not in {"", str(document.get("company_id") or "")}:
        raise PermissionError("official_workflow_delegation_company_forbidden")
    return rows[0]


def assert_official_step_actor(
    user: Dict[str, Any],
    step: Dict[str, Any],
    document: Dict[str, Any] | None = None,
    *,
    conn: sqlite3.Connection | None = None,
    supabase_mode: bool = False,
) -> Dict[str, Any] | None:
    if step.get("approver_user_id") == user.get("id"):
        return None
    if not document:
        raise PermissionError("not_current_official_document_approver")
    delegation = (
        supabase_active_official_workflow_delegation(document, step, user)
        if supabase_mode
        else active_official_workflow_delegation(conn, document, step, user) if conn else None
    )
    if not delegation:
        raise PermissionError("not_current_official_document_approver")
    return delegation


def next_official_step(
    conn: sqlite3.Connection,
    document_id: str,
    step_order: int,
    workflow_generation: int,
) -> Dict[str, Any] | None:
    row = conn.execute(
        "SELECT * FROM official_document_approval_steps WHERE document_id = ? AND workflow_generation = ? AND step_order > ? AND status = 'pending' ORDER BY step_order LIMIT 1",
        (document_id, workflow_generation, step_order),
    ).fetchone()
    return row_to_dict(row) if row else None


def claim_official_document_approval(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    step: Dict[str, Any],
    approver_user_id: str,
    comment: str = "",
    *,
    decision_actor_user_id: str = "",
    decision_evidence: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    """CAS one SQLite approval step and its document transition.

    The caller passes the exact step it presented to the user.  This is the
    idempotency boundary: a stale retry cannot approve a later consecutive step
    owned by the same approver.  The savepoint rolls back the step mutation if
    the document compare-and-set unexpectedly loses its race.
    """
    expected_status = OFFICIAL_DOCUMENT_STEP_STATUS.get(str(step.get("step_key") or ""))
    if (
        not expected_status
        or document.get("current_status") != expected_status
        or document.get("current_step") != step.get("step_key")
    ):
        return {
            "claimed": False,
            "reason": "official_document_approval_already_claimed",
            "document_id": document.get("id") or "",
            "expected_step_id": step.get("id") or "",
        }

    live_step = conn.execute(
        "SELECT status FROM official_document_approval_steps WHERE id = ? AND document_id = ?",
        (step.get("id") or "", document.get("id") or ""),
    ).fetchone()
    if not live_step or live_step["status"] != "pending":
        return {
            "claimed": False,
            "reason": "official_document_approval_already_claimed",
            "document_id": document.get("id") or "",
            "expected_step_id": step.get("id") or "",
        }
    next_step = next_official_step(
        conn,
        str(document.get("id") or ""),
        int(step.get("step_order") or 0),
        int(step.get("workflow_generation") or 1),
    )
    if not next_step:
        raise ValueError("official_document_next_step_missing")
    if next_step.get("step_key") == "applicant_confirm":
        if step.get("step_key") not in {"general_affairs_review", "ceo"}:
            raise ValueError("official_document_invalid_final_approval_step")
        if not bool(document.get("requires_stamp", 1)):
            raise PermissionError("official_document_stamp_required")
        transition = "auto_stamp"
        next_status = "approved"
        next_key = "auto_stamp"
    else:
        transition = "next_step"
        next_key = str(next_step.get("step_key") or "")
        next_status = OFFICIAL_DOCUMENT_STEP_STATUS.get(next_key) or ""
        if not next_status:
            raise ValueError("official_document_next_step_invalid")

    timestamp = now()
    savepoint = f"official_approval_claim_{secrets.token_hex(4)}"
    conn.execute(f"SAVEPOINT {savepoint}")
    try:
        step_update = conn.execute(
            """
            UPDATE official_document_approval_steps
            SET status = 'approved', comment = ?, approved_at = ?, updated_at = ?,
                decision_actor_user_id = CASE WHEN ? <> '' THEN ? ELSE decision_actor_user_id END,
                decision_evidence_json = CASE WHEN ? <> '' THEN ? ELSE decision_evidence_json END
            WHERE id = ? AND document_id = ? AND status = 'pending' AND approver_user_id = ?
            """,
            (
                comment or "核准",
                timestamp,
                timestamp,
                decision_actor_user_id,
                decision_actor_user_id,
                "present" if decision_evidence is not None else "",
                json.dumps(decision_evidence or {}, ensure_ascii=False),
                step.get("id") or "",
                document.get("id") or "",
                approver_user_id,
            ),
        )
        if step_update.rowcount != 1:
            conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {
                "claimed": False,
                "reason": "official_document_approval_already_claimed",
                "document_id": document.get("id") or "",
                "expected_step_id": step.get("id") or "",
            }

        document_update = conn.execute(
            """
            UPDATE official_documents
            SET current_status = ?, current_step = ?, updated_at = ?
            WHERE id = ? AND current_status = ? AND current_step = ?
            """,
            (
                next_status,
                next_key,
                timestamp,
                document.get("id") or "",
                expected_status,
                step.get("step_key") or "",
            ),
        )
        if document_update.rowcount != 1:
            conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {
                "claimed": False,
                "reason": "official_document_approval_already_claimed",
                "document_id": document.get("id") or "",
                "expected_step_id": step.get("id") or "",
            }
        if transition == "next_step":
            activated = conn.execute(
                "UPDATE official_document_approval_steps SET review_started_at = ?, updated_at = ? WHERE id = ? AND review_started_at IS NULL",
                (timestamp, timestamp, next_step.get("id") or ""),
            )
            if activated.rowcount != 1:
                raise ValueError("official_document_next_step_activation_conflict")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        raise

    return {
        "claimed": True,
        "document_id": document.get("id") or "",
        "step_id": step.get("id") or "",
        "step_key": step.get("step_key") or "",
        "step_name": step.get("step_name") or "",
        "approved_at": timestamp,
        "transition": transition,
        "document_status": next_status,
        "document_step": next_key,
        "next_step": next_step,
    }


def claim_official_document_rejection(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    step: Dict[str, Any],
    approver_user_id: str,
    comment: str = "",
    *,
    decision_actor_user_id: str = "",
    decision_evidence: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    """CAS a rejection and void the current SQLite workflow generation.

    Approval and rejection share the exact presented step id as their
    idempotency boundary.  The savepoint keeps the document transition and all
    mutable generation steps atomic, so whichever action wins cannot be
    overwritten by a stale competing request.
    """
    expected_status = OFFICIAL_DOCUMENT_STEP_STATUS.get(str(step.get("step_key") or ""))
    if (
        not expected_status
        or document.get("current_status") != expected_status
        or document.get("current_step") != step.get("step_key")
    ):
        return {
            "claimed": False,
            "reason": "official_document_approval_already_claimed",
            "document_id": document.get("id") or "",
            "expected_step_id": step.get("id") or "",
        }

    timestamp = now()
    rejection_comment = str(comment or "駁回").strip() or "駁回"
    void_comment = "舊簽核已因退回作廢；重新送簽必須從第一關開始。"
    current_comment = f"駁回：{rejection_comment}；舊簽核已作廢，重新送簽必須從第一關開始。"
    savepoint = f"official_rejection_claim_{secrets.token_hex(4)}"
    conn.execute(f"SAVEPOINT {savepoint}")
    try:
        expected_step_update = conn.execute(
            """
            UPDATE official_document_approval_steps
            SET status = 'skipped', comment = ?, approved_at = ?, updated_at = ?,
                decision_actor_user_id = CASE WHEN ? <> '' THEN ? ELSE decision_actor_user_id END,
                decision_evidence_json = CASE WHEN ? <> '' THEN ? ELSE decision_evidence_json END
            WHERE id = ? AND document_id = ? AND status = 'pending' AND approver_user_id = ?
            """,
            (
                current_comment,
                timestamp,
                timestamp,
                decision_actor_user_id,
                decision_actor_user_id,
                "present" if decision_evidence is not None else "",
                json.dumps(decision_evidence or {}, ensure_ascii=False),
                step.get("id") or "",
                document.get("id") or "",
                approver_user_id,
            ),
        )
        if expected_step_update.rowcount != 1:
            conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {
                "claimed": False,
                "reason": "official_document_approval_already_claimed",
                "document_id": document.get("id") or "",
                "expected_step_id": step.get("id") or "",
            }

        remaining_steps_update = conn.execute(
            """
            UPDATE official_document_approval_steps
            SET status = 'skipped', comment = ?,
                updated_at = ?
            WHERE document_id = ? AND workflow_generation = ? AND id <> ? AND status <> 'skipped'
            """,
            (
                void_comment,
                timestamp,
                document.get("id") or "",
                int(step.get("workflow_generation") or 1),
                step.get("id") or "",
            ),
        )
        voided_step_count = 1 + int(remaining_steps_update.rowcount)

        document_update = conn.execute(
            """
            UPDATE official_documents
            SET current_status = 'rejected', current_step = 'applicant', updated_at = ?
            WHERE id = ? AND current_status = ? AND current_step = ?
            """,
            (
                timestamp,
                document.get("id") or "",
                expected_status,
                step.get("step_key") or "",
            ),
        )
        if document_update.rowcount != 1:
            conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {
                "claimed": False,
                "reason": "official_document_approval_already_claimed",
                "document_id": document.get("id") or "",
                "expected_step_id": step.get("id") or "",
            }
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        raise

    return {
        "claimed": True,
        "document_id": document.get("id") or "",
        "step_id": step.get("id") or "",
        "step_key": step.get("step_key") or "",
        "step_name": step.get("step_name") or "",
        "rejected_at": timestamp,
        "document_status": "rejected",
        "document_step": "applicant",
        "voided_step_count": voided_step_count,
    }


def _official_decision_file_entry(file_row: Dict[str, Any]) -> Dict[str, Any]:
    file_id = str(file_row.get("id") or "").strip()
    file_type = str(file_row.get("file_type") or "").strip()
    file_hash = str(file_row.get("file_hash") or "").strip().upper()
    try:
        version = int(file_row.get("version") or 0)
        size = int(file_row.get("file_size") or 0)
    except (TypeError, ValueError) as exc:
        raise ValueError("official_document_decision_file_metadata_invalid") from exc
    if (
        not file_id
        or not file_type
        or not re.fullmatch(r"[0-9A-F]{64}", file_hash)
        or version < 1
        or size < 1
    ):
        raise ValueError("official_document_decision_file_metadata_invalid")
    return {
        "id": file_id,
        "type": file_type,
        "sha256": file_hash,
        "version": version,
        "size": size,
    }


def _official_attachment_manifest_sha256(entries: List[Dict[str, Any]]) -> str:
    # Keep this representation deliberately small and reproducible in both
    # Python and PostgreSQL.  The length prefixes prevent delimiter ambiguity;
    # callers must not rely on JSON object key ordering for audit hashes.
    rows: List[str] = []
    for item in sorted(entries, key=lambda entry: str(entry.get("id") or "")):
        file_id = str(item.get("id") or "")
        file_type = str(item.get("type") or "")
        rows.append(
            f"{len(file_id)}:{file_id}|{len(file_type)}:{file_type}|"
            f"{str(item.get('sha256') or '').upper()}|{int(item.get('version') or 0)}|"
            f"{int(item.get('size') or 0)}"
        )
    return sha256_bytes("\n".join(rows).encode("utf-8"))


def _sqlite_verify_decision_file(
    conn: sqlite3.Connection,
    document_id: str,
    file_row: Dict[str, Any],
) -> Dict[str, Any]:
    if str(file_row.get("document_id") or "") != document_id or not file_row.get("file_object_id"):
        raise ValueError("official_document_decision_file_metadata_invalid")
    object_row = conn.execute(
        "SELECT * FROM file_objects WHERE id = ?",
        (file_row["file_object_id"],),
    ).fetchone()
    require_official_file_av_clean(file_row, object_row)
    stored_object, data = read_file_object_bytes(conn, file_row["file_object_id"])
    verify_official_file_bytes(file_row, stored_object, data)
    return _official_decision_file_entry(file_row)


def sqlite_official_decision_document_evidence(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    stamp_request: Dict[str, Any] | None,
) -> Dict[str, Any]:
    source = official_latest_source_file(conn, document)
    source_entry = _sqlite_verify_decision_file(conn, document["id"], source)
    attachment_rows = [
        row_to_dict(row)
        for row in conn.execute(
            "SELECT * FROM official_document_files WHERE document_id = ? AND file_type = 'attachment' ORDER BY id",
            (document["id"],),
        ).fetchall()
    ]
    attachments = [
        _sqlite_verify_decision_file(conn, document["id"], row)
        for row in attachment_rows
    ]
    request = stamp_request or {}
    v2_values = {
        "revision_id": str(request.get("locked_editor_revision_id") or "").strip(),
        "source_bundle_sha256": str(request.get("locked_source_sha256") or "").strip().upper(),
        "prepared_file_id": str(request.get("prepared_file_id") or "").strip(),
        "prepared_sha256": str(request.get("prepared_sha256") or "").strip().upper(),
        "manifest_sha256": str(request.get("editor_manifest_sha256") or "").strip().upper(),
        "editor_schema_version": int(request.get("editor_schema_version") or 0),
        "renderer_version": str(request.get("renderer_version") or "").strip(),
    }
    is_v2 = any(v2_values.values())
    prepared_entry: Dict[str, Any] | None = None
    if is_v2:
        if (
            not all(v2_values.values())
            or int(v2_values["editor_schema_version"]) < EDOC_EDITOR_SCHEMA_VERSION
            or not re.fullmatch(r"[0-9A-F]{64}", str(v2_values["source_bundle_sha256"]))
            or not re.fullmatch(r"[0-9A-F]{64}", str(v2_values["prepared_sha256"]))
            or not re.fullmatch(r"[0-9A-F]{64}", str(v2_values["manifest_sha256"]))
        ):
            raise ValueError("official_document_editor_decision_lock_incomplete")
        revision_row = conn.execute(
            "SELECT * FROM official_document_editor_revisions WHERE id = ? AND document_id = ?",
            (v2_values["revision_id"], document["id"]),
        ).fetchone()
        if not revision_row:
            raise ValueError("editor_locked_revision_missing")
        revision = row_to_dict(revision_row)
        state = parse_json_any(revision.get("editor_state_json"), {}) or {}
        computed_manifest = canonical_editor_manifest(state).upper()
        if (
            computed_manifest != str(revision.get("manifest_sha256") or "").upper()
            or computed_manifest != v2_values["manifest_sha256"]
        ):
            raise ValueError("editor_manifest_hash_mismatch")
        computed_source_bundle = _editor_source_bundle_sha256(conn, document["id"], state).upper()
        if computed_source_bundle != v2_values["source_bundle_sha256"]:
            raise ValueError("editor_source_hash_mismatch")
        prepared_row = conn.execute(
            "SELECT * FROM official_document_files WHERE id = ? AND document_id = ? AND file_type = 'prepared_pdf'",
            (v2_values["prepared_file_id"], document["id"]),
        ).fetchone()
        if not prepared_row:
            raise ValueError("official_document_prepared_file_missing")
        prepared_entry = _sqlite_verify_decision_file(conn, document["id"], row_to_dict(prepared_row))
        if prepared_entry["sha256"] != v2_values["prepared_sha256"]:
            raise ValueError("official_document_prepared_sha256_mismatch")
        preflight_asset = conn.execute(
            """
            SELECT id FROM official_document_editor_assets
            WHERE document_id = ? AND editor_revision_id = ? AND asset_kind = 'prepared_pdf'
              AND official_file_id = ? AND UPPER(sha256) = ? AND preflight_status = 'passed'
            ORDER BY created_at DESC LIMIT 1
            """,
            (
                document["id"],
                v2_values["revision_id"],
                v2_values["prepared_file_id"],
                v2_values["prepared_sha256"],
            ),
        ).fetchone()
        if not preflight_asset:
            raise ValueError("editor_preflight_not_completed")
    return {
        "source_file": source_entry,
        "source_bundle_sha256": v2_values["source_bundle_sha256"] if is_v2 else "",
        "prepared_file": prepared_entry,
        "prepared_sha256": v2_values["prepared_sha256"] if is_v2 else "",
        "manifest_sha256": v2_values["manifest_sha256"] if is_v2 else "",
        "editor_revision_id": v2_values["revision_id"] if is_v2 else "",
        "editor_schema_version": int(v2_values["editor_schema_version"]) if is_v2 else 0,
        "renderer_version": str(v2_values["renderer_version"]) if is_v2 else "",
        "attachments": attachments,
        "attachments_manifest_sha256": _official_attachment_manifest_sha256(attachments),
        "legacy_renderer": not is_v2,
    }


def sqlite_official_review_access_evidence(
    conn: sqlite3.Connection,
    document_id: str,
    step: Dict[str, Any],
    actor_id: str,
    document_evidence: Dict[str, Any],
) -> Dict[str, Any]:
    started_at = str(step.get("review_started_at") or "").strip()
    if not started_at:
        raise ValueError("official_document_review_session_not_started")
    required_ids = [document_evidence["source_file"]["id"]]
    if document_evidence.get("prepared_file"):
        required_ids.append(document_evidence["prepared_file"]["id"])
    required_ids.extend(item["id"] for item in document_evidence.get("attachments") or [])
    access_rows: List[Dict[str, Any]] = []
    for file_id in sorted(set(required_ids)):
        row = conn.execute(
            """
            SELECT id, file_id, action, created_at
            FROM official_document_approval_logs
            WHERE document_id = ? AND actor_id = ? AND file_id = ?
              AND action = 'download_file' AND created_at >= ?
            ORDER BY created_at DESC, id DESC LIMIT 1
            """,
            (document_id, actor_id, file_id, started_at),
        ).fetchone()
        if not row:
            raise ValueError(f"official_document_review_access_required:{file_id}")
        access_rows.append({
            "file_id": row["file_id"],
            "access_log_id": row["id"],
            "action": row["action"],
            "accessed_at": row["created_at"],
        })
    return {
        "step_started_at": started_at,
        "required_file_ids": sorted(set(required_ids)),
        "access_logs": access_rows,
        "server_verified": True,
    }


def official_review_acknowledgements(payload: Dict[str, Any], *, has_attachments: bool) -> Dict[str, bool]:
    raw = payload.get("review_acknowledgements") or payload.get("reviewAcknowledgements") or {}
    if isinstance(raw, list):
        selected = {str(item) for item in raw}
        raw = {key: True for key in selected}
    if not isinstance(raw, dict):
        raise ValueError("official_document_review_acknowledgements_required")
    normalized = {
        "original_reviewed": any(raw.get(key) is True for key in ("original_reviewed", "original", "source_reviewed")),
        "edited_version_reviewed": any(raw.get(key) is True for key in ("edited_version_reviewed", "prepared", "prepared_reviewed")),
        "attachments_reviewed": (
            any(raw.get(key) is True for key in ("attachments_reviewed", "attachments"))
            or not has_attachments
        ),
    }
    if not normalized["original_reviewed"] or not normalized["edited_version_reviewed"]:
        raise ValueError("official_document_review_acknowledgements_required")
    if has_attachments and not normalized["attachments_reviewed"]:
        raise ValueError("official_document_attachment_review_required")
    return normalized


def official_approval_decision_evidence(
    document: Dict[str, Any],
    stamp_request: Dict[str, Any] | None,
    payload: Dict[str, Any],
    *,
    has_attachments: bool,
    step: Dict[str, Any],
    actor: Dict[str, Any],
    principal_actor_id: str,
    document_evidence: Dict[str, Any],
    review_access: Dict[str, Any],
    require_client_acknowledgements: bool = True,
    decision_type: str = "approve",
) -> Dict[str, Any]:
    expected_prepared = str((stamp_request or {}).get("prepared_sha256") or "").strip().lower()
    expected_manifest = str((stamp_request or {}).get("editor_manifest_sha256") or "").strip().lower()
    supplied_prepared = str(payload.get("prepared_sha256") or payload.get("preparedSha256") or "").strip().lower()
    supplied_manifest = str(payload.get("manifest_sha256") or payload.get("manifestSha256") or "").strip().lower()
    is_v2 = not bool(document_evidence.get("legacy_renderer", True))
    if is_v2:
        if not expected_prepared or supplied_prepared != expected_prepared:
            raise ValueError("official_document_prepared_sha256_mismatch")
        if not expected_manifest or supplied_manifest != expected_manifest:
            raise ValueError("official_document_manifest_sha256_mismatch")
    elif supplied_prepared or supplied_manifest:
        # A legacy renderer cannot prove hashes it never locked.  Refuse a
        # client-supplied value rather than recording false evidence.
        raise ValueError("official_document_legacy_renderer_hash_not_available")
    acknowledgements = (
        official_review_acknowledgements(payload, has_attachments=has_attachments)
        if require_client_acknowledgements
        else {
            "original_reviewed": True,
            "edited_version_reviewed": True,
            "attachments_reviewed": True,
        }
    )
    comment = str(payload.get("comment") or "").strip()
    if step.get("step_key") in {"ceo", "admin_director", "general_affairs_review"} and not comment:
        raise ValueError("official_document_approval_comment_required")
    return {
        "schema_version": 2,
        "decision_type": decision_type,
        "expected_step_id": step.get("id") or "",
        **document_evidence,
        "review_acknowledgements": acknowledgements,
        "review_access": review_access,
        "decision_actor_user_id": actor.get("id") or "",
        "principal_actor_id": principal_actor_id,
        "recorded_at": now(),
    }


def structured_rejection_evidence(payload: Dict[str, Any]) -> Dict[str, Any]:
    category = str(payload.get("reason_category") or payload.get("reasonCategory") or "").strip()[:80]
    if not category:
        raise ValueError("official_document_rejection_reason_category_required")
    comment = str(payload.get("comment") or "").strip()
    if len(comment) < 6:
        raise ValueError("official_document_rejection_comment_too_short")
    missing = payload.get("missing_items") or payload.get("missingItems") or []
    if not isinstance(missing, list):
        raise ValueError("official_document_rejection_missing_items_invalid")
    missing_items = [str(item).strip()[:240] for item in missing if str(item).strip()][:50]
    due_date = str(payload.get("correction_due_date") or payload.get("correctionDueDate") or "").strip()
    if due_date and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", due_date):
        raise ValueError("official_document_correction_due_date_invalid")
    if due_date:
        try:
            if datetime.strptime(due_date, "%Y-%m-%d").date() < datetime.now().date():
                raise ValueError("official_document_correction_due_date_in_past")
        except ValueError as exc:
            if str(exc) == "official_document_correction_due_date_in_past":
                raise
            raise ValueError("official_document_correction_due_date_invalid") from exc
    return {
        "schema_version": 1,
        "reason_category": category,
        "missing_items": missing_items,
        "correction_due_date": due_date,
        "recorded_at": now(),
    }


def approve_official_document(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document["current_status"] in {"draft", "stamping", "stamped", "pending_general_affairs_dispatch", "returned_to_applicant_for_send", "dispatched", "sent_by_applicant", "closed", "cancelled", "rejected"}:
        raise ValueError("official_document_not_pending_approval")
    step = current_official_pending_step(conn, document)
    delegation = assert_official_step_actor(user, step, document, conn=conn)
    if step["step_key"] != "applicant_confirm" and user["id"] == document["applicant_id"]:
        raise PermissionError("applicant_cannot_self_approve")
    expected_step_id = str(payload.get("expected_step_id") or payload.get("expectedStepId") or "").strip()
    if not expected_step_id:
        raise ValueError("official_document_approval_expected_step_required")
    if expected_step_id != str(step.get("id") or ""):
        raise ValueError("official_document_approval_already_claimed")
    principal_actor_id = str(step.get("approver_user_id") or "")
    stamp_request = official_document_stamp_request(conn, document_id)
    document_evidence = sqlite_official_decision_document_evidence(conn, document, stamp_request)
    review_access = sqlite_official_review_access_evidence(
        conn,
        document_id,
        step,
        str(user.get("id") or ""),
        document_evidence,
    )
    evidence = official_approval_decision_evidence(
        document,
        stamp_request,
        payload,
        has_attachments=bool(document_evidence["attachments"]),
        step=step,
        actor=user,
        principal_actor_id=principal_actor_id,
        document_evidence=document_evidence,
        review_access=review_access,
    )
    claim = claim_official_document_approval(
        conn,
        document,
        step,
        principal_actor_id,
        str(payload.get("comment") or ""),
        decision_actor_user_id=str(user.get("id") or ""),
        decision_evidence=evidence,
    )
    if not claim.get("claimed"):
        raise ValueError("official_document_approval_already_claimed")
    insert_official_log(
        conn,
        document_id,
        "approve",
        user,
        payload.get("comment") or "",
        step_id=step["id"],
        ip_address=payload.get("ip_address") or "",
        user_agent=payload.get("user_agent") or "",
        principal_actor_id=principal_actor_id if delegation else "",
        decision_evidence=evidence,
    )
    next_step = claim["next_step"]
    if claim["transition"] == "auto_stamp":
        result = auto_stamp_official_document(conn, document_id, payload, user)
        return {**official_document_detail(conn, document_id, session), "auto_stamp": result}
    next_approver = active_user_by_id(conn, next_step.get("approver_user_id") or "") or {}
    create_and_deliver_notification(conn, {
        "type": "發文簽核",
        "title": f"{document['title']} 待{next_step['step_name']}簽核",
        **exact_notification_target_payload(next_approver, document.get("company_id") or ""),
        "source": document_id,
        "priority": "高",
        "body": f"{step['step_name']}已核准，請接續處理。",
    })
    return official_document_detail(conn, document_id, session)


def reject_official_document(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document["current_status"] in {"draft", "stamping", "stamped", "pending_general_affairs_dispatch", "returned_to_applicant_for_send", "dispatched", "sent_by_applicant", "closed", "cancelled", "rejected"}:
        raise ValueError("official_document_not_pending_approval")
    step = current_official_pending_step(conn, document)
    delegation = assert_official_step_actor(user, step, document, conn=conn)
    if step["step_key"] != "applicant_confirm" and user["id"] == document["applicant_id"]:
        raise PermissionError("applicant_cannot_self_approve")
    expected_step_id = str(payload.get("expected_step_id") or payload.get("expectedStepId") or "").strip()
    if not expected_step_id:
        raise ValueError("official_document_approval_expected_step_required")
    if expected_step_id != str(step.get("id") or ""):
        raise ValueError("official_document_approval_already_claimed")
    comment = payload.get("comment") or "駁回"
    principal_actor_id = str(step.get("approver_user_id") or "")
    stamp_request = official_document_stamp_request(conn, document_id)
    document_evidence = sqlite_official_decision_document_evidence(conn, document, stamp_request)
    review_access = sqlite_official_review_access_evidence(
        conn,
        document_id,
        step,
        str(user.get("id") or ""),
        document_evidence,
    )
    rejection_evidence = {
        **official_approval_decision_evidence(
            document,
            stamp_request,
            payload,
            has_attachments=bool(document_evidence["attachments"]),
            step=step,
            actor=user,
            principal_actor_id=principal_actor_id,
            document_evidence=document_evidence,
            review_access=review_access,
            require_client_acknowledgements=False,
            decision_type="reject",
        ),
        **structured_rejection_evidence(payload),
        "schema_version": 2,
        "decision_type": "reject",
    }
    claim = claim_official_document_rejection(
        conn,
        document,
        step,
        principal_actor_id,
        str(comment),
        decision_actor_user_id=str(user.get("id") or ""),
        decision_evidence=rejection_evidence,
    )
    if not claim.get("claimed"):
        raise ValueError("official_document_approval_already_claimed")
    conn.execute(
        """
        UPDATE official_documents
        SET correction_reason_category = ?, correction_missing_items_json = ?,
            correction_due_at = ?, correction_requested_at = ?, correction_resubmitted_at = NULL
        WHERE id = ?
        """,
        (
            rejection_evidence["reason_category"],
            json.dumps(rejection_evidence["missing_items"], ensure_ascii=False),
            rejection_evidence["correction_due_date"] or None,
            rejection_evidence["recorded_at"],
            document_id,
        ),
    )
    insert_official_log(
        conn,
        document_id,
        "reject",
        user,
        comment,
        step_id=step["id"],
        ip_address=payload.get("ip_address") or "",
        user_agent=payload.get("user_agent") or "",
        principal_actor_id=principal_actor_id if delegation else "",
        decision_evidence=rejection_evidence,
    )
    editor_revision = clone_official_editor_revision_after_reject(conn, document_id, user)
    applicant = active_user_by_id(conn, document.get("applicant_id") or "") or {}
    create_and_deliver_notification(conn, {
        "type": "發文退回",
        "title": f"{document['title']} 已駁回",
        **exact_notification_target_payload(applicant, document.get("company_id") or ""),
        "source": document_id,
        "priority": "高",
        "body": comment,
    })
    result = official_document_detail(conn, document_id, session)
    if editor_revision:
        result["editor_revision"] = editor_revision
        result["editor_state"] = editor_revision["state"]
        result["approval_restart_required"] = True
    return result


def cancel_official_document(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document["applicant_id"] != user["id"]:
        raise PermissionError("only_applicant_can_cancel")
    stamp_request = official_document_stamp_request(conn, document_id)
    if document["current_status"] in {"approved", "stamping", "stamping_failed", "stamped", "pending_general_affairs_dispatch", "returned_to_applicant_for_send", "dispatched", "sent_by_applicant", "closed"} or document.get("current_step") == "auto_stamp" or (stamp_request and stamp_request.get("status") in {"stamping", "stamped"}):
        raise ValueError("official_document_cannot_cancel_after_stamp")
    timestamp = now()
    conn.execute("SAVEPOINT official_document_cancel")
    try:
        if document.get("current_status") == "draft":
            # Unbound placements are only draft placeholders, not evidence.
            # Remove them before the terminal transition so no non-draft row
            # can retain incomplete Seal Vault attestation.
            conn.execute(
                """
                DELETE FROM official_document_stamp_positions
                WHERE request_id IN (
                  SELECT id FROM official_document_stamp_requests WHERE document_id = ?
                )
                  AND (
                    COALESCE(locked_seal_file_id, '') = ''
                    OR COALESCE(locked_seal_sha256, '') = ''
                    OR locked_render_width_pt IS NULL
                    OR locked_render_height_pt IS NULL
                    OR COALESCE(locked_dimension_policy_version, '') = ''
                  )
                """,
                (document_id,),
            )
        conn.execute(
            """
            UPDATE official_document_stamp_requests
            SET status = 'cancelled', error_message = 'cancelled_by_applicant', updated_at = ?
            WHERE document_id = ? AND status <> 'stamped'
            """,
            (timestamp, document_id),
        )
        updated = conn.execute(
            """
            UPDATE official_documents
            SET current_status = 'cancelled', current_step = '', updated_at = ?
            WHERE id = ? AND current_status = ? AND current_step = ?
            """,
            (timestamp, document_id, document.get("current_status") or "", document.get("current_step") or ""),
        )
        if updated.rowcount != 1:
            raise ValueError("official_document_cancel_conflict")
        insert_official_log(conn, document_id, "cancel", user, payload.get("comment") or "申請人取消", ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
        conn.execute("RELEASE SAVEPOINT official_document_cancel")
    except Exception:
        conn.execute("ROLLBACK TO SAVEPOINT official_document_cancel")
        conn.execute("RELEASE SAVEPOINT official_document_cancel")
        raise
    return official_document_detail(conn, document_id, session)


def confirm_official_document(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document["applicant_id"] != user["id"]:
        raise PermissionError("only_applicant_can_confirm")
    if document["current_status"] not in {"returned_to_applicant_for_send", "stamped", "dispatched", "sent_by_applicant"}:
        raise ValueError("official_document_not_ready_for_applicant_confirm")
    if document["current_status"] == "returned_to_applicant_for_send":
        # The applicant may complete their applicant-owned dispatch and confirm
        # receipt in this one endpoint, but the dispatch helper itself never
        # closes or approves on behalf of the applicant.
        complete_official_dispatch(conn, document_id, payload, session)
    step = next((item for item in official_document_steps(conn, document_id) if item.get("step_key") == "applicant_confirm"), None)
    if step and step.get("status") == "pending":
        conn.execute(
            "UPDATE official_document_approval_steps SET status = 'approved', comment = ?, approved_at = ?, updated_at = ? WHERE id = ?",
            (payload.get("comment") or "申請人確認完成", now(), now(), step["id"]),
        )
    conn.execute("UPDATE official_documents SET current_status = 'closed', current_step = '', updated_at = ? WHERE id = ?", (now(), document_id))
    insert_official_log(conn, document_id, "confirm", user, payload.get("comment") or "申請人確認已用印版本", ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return official_document_detail(conn, document_id, session)


def update_official_stamp_position(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    if document["applicant_id"] != user["id"]:
        raise PermissionError("only_applicant_can_update_stamp_position")
    if document["current_status"] != "draft":
        raise ValueError("stamp_position_locked_after_submit")
    stamp_request = official_document_stamp_request(conn, document_id)
    if not stamp_request:
        raise ValueError("official_document_stamp_request_not_found")
    validate_official_document_seal(
        conn,
        str(stamp_request.get("seal_id") or ""),
        str(document.get("company_id") or ""),
        require_current=False,
    )
    created_positions = replace_official_stamp_positions(
        conn,
        stamp_request["id"],
        stamp_request["seal_id"],
        payload,
        allow_unbound_current=True,
    )
    first_position = created_positions[0]
    position = {
        "stamp_page": first_position["page"],
        "stamp_x": first_position["x"],
        "stamp_y": first_position["y"],
        "stamp_width": first_position["width"],
        "stamp_height": first_position["height"],
    }
    conn.execute(
        """
        UPDATE official_document_stamp_requests
        SET stamp_page = ?, stamp_x = ?, stamp_y = ?, stamp_width = ?, stamp_height = ?, updated_at = ?
        WHERE id = ?
        """,
        (position["stamp_page"], position["stamp_x"], position["stamp_y"], position["stamp_width"], position["stamp_height"], now(), stamp_request["id"]),
    )
    if "text_overlays" in payload or "textOverlays" in payload:
        replace_official_text_overlays(conn, stamp_request["id"], payload)
    insert_official_log(conn, document_id, "update_stamp_position", user, json.dumps(position, ensure_ascii=False), ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return official_document_detail(conn, document_id, session)


def verify_locked_editor_for_stamp(conn: sqlite3.Connection, document: Dict[str, Any], stamp_request: Dict[str, Any]) -> Dict[str, Any] | None:
    revision_id = str(stamp_request.get("locked_editor_revision_id") or "")
    if not revision_id:
        return None
    revision_row = conn.execute("SELECT * FROM official_document_editor_revisions WHERE id = ? AND document_id = ?", (revision_id, document["id"])).fetchone()
    if not revision_row:
        raise ValueError("editor_locked_revision_missing")
    revision = row_to_dict(revision_row)
    state = parse_json_any(revision["editor_state_json"], {}) or {}
    if canonical_editor_manifest(state) != revision["manifest_sha256"] or revision["manifest_sha256"] != stamp_request.get("editor_manifest_sha256"):
        raise ValueError("editor_manifest_hash_mismatch")
    if _editor_source_bundle_sha256(conn, document["id"], state) != stamp_request.get("locked_source_sha256"):
        raise ValueError("editor_source_hash_mismatch")
    prepared_row = conn.execute("SELECT * FROM official_document_files WHERE id = ? AND document_id = ? AND file_type = 'prepared_pdf'", (stamp_request.get("prepared_file_id") or "", document["id"])).fetchone()
    if not prepared_row:
        raise ValueError("editor_prepared_file_missing")
    prepared_file = row_to_dict(prepared_row)
    if prepared_file["file_hash"] != stamp_request.get("prepared_sha256") or not prepared_file.get("file_object_id"):
        raise ValueError("editor_prepared_hash_mismatch")
    _, prepared_bytes = read_file_object_bytes(conn, prepared_file["file_object_id"])
    if sha256_bytes(prepared_bytes) != stamp_request.get("prepared_sha256"):
        raise ValueError("editor_prepared_hash_mismatch")
    seal_assets: Dict[str, Dict[str, Any]] = {}
    positions = stamp_request.get("stamp_positions") or []
    for position in positions:
        seal_file_id = str(position.get("locked_seal_file_id") or "")
        locked_hash = str(position.get("locked_seal_sha256") or "")
        if not seal_file_id or not locked_hash:
            raise ValueError("editor_locked_seal_version_missing")
        seal_file_row = conn.execute("SELECT * FROM company_seal_files WHERE id = ? AND seal_id = ?", (seal_file_id, position.get("seal_id") or "")).fetchone()
        if not seal_file_row:
            raise ValueError("editor_locked_seal_version_missing")
        seal_file = require_seal_file_av_clean(conn, seal_file_row)
        seal = conn.execute(
            "SELECT seal_size_type FROM company_seals WHERE id = ?",
            (position.get("seal_id") or "",),
        ).fetchone()
        if not seal:
            raise ValueError("seal_not_found")
        validate_locked_company_seal_position(position, seal["seal_size_type"], seal_file)
        if seal_file.get("file_hash") != locked_hash or not seal_file.get("file_object_id"):
            raise ValueError("editor_seal_hash_mismatch")
        _, seal_bytes = read_file_object_bytes(conn, seal_file["file_object_id"])
        if sha256_bytes(seal_bytes) != locked_hash:
            raise ValueError("editor_seal_hash_mismatch")
        seal_assets[seal_file_id] = {"data": seal_bytes, "mime_type": seal_file.get("file_mime_type") or "", "sha256": locked_hash}
    return {
        "revision": revision,
        "state": state,
        "prepared_file": prepared_file,
        "prepared_bytes": prepared_bytes,
        "positions": positions,
        "seal_assets": seal_assets,
        "renderer_version": str(stamp_request.get("renderer_version") or ""),
    }


def stamp_prepared_pdf_with_locked_seals(locked: Dict[str, Any]) -> Tuple[bytes, str, Dict[str, Any]]:
    import fitz  # type: ignore

    document = fitz.open(stream=locked["prepared_bytes"], filetype="pdf")
    try:
        ordered_pages = sorted((locked.get("state") or {}).get("pages") or [], key=lambda item: int(item.get("order") or 0))
        page_index_by_id = {str(item.get("pageId") or ""): index for index, item in enumerate(ordered_pages)}
        seal_rects_by_page: Dict[int, List[Any]] = {}
        for position in sorted(locked.get("positions") or [], key=lambda item: (int(item.get("page") or 1), int(item.get("z_index") or 0), int(item.get("order_index") or 0))):
            page_ref = str(position.get("page_ref") or "")
            page_index = page_index_by_id.get(page_ref, int(position.get("page") or 1) - 1)
            if page_index < 0 or page_index >= document.page_count:
                raise ValueError("editor_stamp_page_missing")
            page = document[page_index]
            page_height = pdf_safe_float((ordered_pages[page_index] if page_index < len(ordered_pages) else {}).get("heightPt"), float(page.rect.height))
            rect = _editor_rect({"x": position.get("x"), "y": position.get("y"), "width": position.get("width"), "height": position.get("height")}, page_height)
            asset = locked["seal_assets"].get(str(position.get("locked_seal_file_id") or ""))
            if not asset:
                raise ValueError("editor_locked_seal_version_missing")
            transformed, transformed_width, transformed_height = _editor_transformed_image(
                asset["data"],
                str(asset.get("mime_type") or "image/png"),
                float(rect.width),
                float(rect.height),
                pdf_safe_float(position.get("rotation"), 0),
                max(0.0, min(1.0, pdf_safe_float(position.get("opacity"), 1))),
            )
            placed_rect = _editor_centered_rect(rect, transformed_width, transformed_height)
            page.insert_image(
                placed_rect,
                stream=transformed,
                keep_proportion=False,
                overlay=True,
            )
            seal_rects_by_page.setdefault(page_index, []).append(placed_rect)

        # New V3 revisions guarantee entered / replacement text is the highest
        # annotation tier. Repaint only text whose visual bounds intersect a
        # company seal, avoiding changes to unrelated text while preserving the
        # locked prepared PDF as the sole base. Redaction is never replayed.
        front_text_repaint_count = 0
        if str(locked.get("renderer_version") or "") == EDOC_EDITOR_RENDERER_VERSION:
            text_elements = sorted(
                [
                    item
                    for item in (locked.get("state") or {}).get("elements") or []
                    if item.get("kind") in {"text", "replacement"}
                ],
                key=lambda item: (
                    page_index_by_id.get(str(item.get("pageId") or ""), 0),
                    int(item.get("zIndex") or 0),
                    str(item.get("id") or ""),
                ),
            )
            for element in text_elements:
                page_index = page_index_by_id.get(str(element.get("pageId") or ""), -1)
                if page_index < 0 or not seal_rects_by_page.get(page_index):
                    continue
                page = document[page_index]
                page_height = pdf_safe_float((ordered_pages[page_index] if page_index < len(ordered_pages) else {}).get("heightPt"), float(page.rect.height))
                text_bounds = _editor_visual_bounds(element, page_height)
                if not any(
                    text_bounds.x0 < seal_rect.x1
                    and text_bounds.x1 > seal_rect.x0
                    and text_bounds.y0 < seal_rect.y1
                    and text_bounds.y1 > seal_rect.y0
                    for seal_rect in seal_rects_by_page[page_index]
                ):
                    continue
                _editor_insert_kai_text(page, element, page_height, flatten_for_front=True)
                front_text_repaint_count += 1
        result = document.tobytes(garbage=4, deflate=True, clean=True)
        return result, "pymupdf-editor-v2-multi-seal", {
            "page_count": document.page_count,
            "seal_count": len(locked.get("positions") or []),
            "distinct_seal_versions": len(locked.get("seal_assets") or {}),
            "front_text_repaint_count": front_text_repaint_count,
            "layer_policy": (
                "company_seal_below_intersecting_editor_text"
                if str(locked.get("renderer_version") or "") == EDOC_EDITOR_RENDERER_VERSION
                else "legacy_seal_overlay"
            ),
        }
    finally:
        document.close()


def official_stamp_claim_expired(expires_at: Any) -> bool:
    value = str(expires_at or "").strip()
    if not value:
        return True
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        current = datetime.now(parsed.tzinfo) if parsed.tzinfo else datetime.now()
        return parsed <= current
    except ValueError:
        return True


def official_stamp_recoverable(document: Dict[str, Any], stamp_request: Dict[str, Any] | None) -> bool:
    if not stamp_request or stamp_request.get("stamped_file_id") or document.get("stamped_file_id"):
        return False
    status = str(document.get("current_status") or "")
    step = str(document.get("current_step") or "")
    request_status = str(stamp_request.get("status") or "")
    if status == "approved" and step == "auto_stamp":
        return request_status in {"pending", "approved", "failed", "stamping"} and (
            request_status != "stamping" or official_stamp_claim_expired(stamp_request.get("claim_expires_at"))
        )
    if status == "stamping_failed" and step == "general_affairs_review":
        return request_status in {"pending", "failed", "stamping"} and (
            request_status != "stamping" or official_stamp_claim_expired(stamp_request.get("claim_expires_at"))
        )
    return (
        status == "stamping"
        and step == "auto_stamp"
        and request_status in {"pending", "failed", "stamping"}
        and official_stamp_claim_expired(stamp_request.get("claim_expires_at"))
    )


def claim_official_document_stamp(
    conn: sqlite3.Connection,
    document_id: str,
    stamp_request_id: str,
    claim_token: str,
    claim_owner_id: str,
    lease_seconds: int = EDOC_STAMP_CLAIM_LEASE_SECONDS,
) -> Dict[str, Any]:
    """SQLite parity for the Supabase document-first stamp lease RPC."""
    if not all((document_id, stamp_request_id, claim_owner_id)) or len(claim_token) < 32:
        raise ValueError("official_stamp_claim_invalid")
    if lease_seconds < 60 or lease_seconds > 1800:
        raise ValueError("official_stamp_claim_invalid")
    savepoint = f"official_stamp_claim_{secrets.token_hex(4)}"
    conn.execute(f"SAVEPOINT {savepoint}")
    try:
        document = official_document_row(conn, document_id)
        row = conn.execute(
            "SELECT * FROM official_document_stamp_requests WHERE id = ? AND document_id = ?",
            (stamp_request_id, document_id),
        ).fetchone()
        if not row:
            raise ValueError("official_document_stamp_request_required")
        request = row_to_dict(row)
        latest = conn.execute(
            "SELECT id FROM official_document_stamp_requests WHERE document_id = ? ORDER BY created_at DESC, id DESC LIMIT 1",
            (document_id,),
        ).fetchone()
        if not latest or latest["id"] != stamp_request_id:
            raise ValueError("official_stamp_request_not_latest")
        if not bool(document.get("requires_stamp", 1)):
            raise PermissionError("official_document_stamp_required")
        generation_row = conn.execute(
            "SELECT MAX(workflow_generation) AS workflow_generation "
            "FROM official_document_approval_steps WHERE document_id = ?",
            (document_id,),
        ).fetchone()
        workflow_generation = int(generation_row["workflow_generation"] or 0) if generation_row else 0
        if workflow_generation < 1:
            raise ValueError("official_document_not_fully_approved_for_stamp_retry")
        unapproved = conn.execute(
            """
            SELECT 1 FROM official_document_approval_steps
            WHERE document_id = ? AND workflow_generation = ?
              AND step_key <> 'applicant_confirm' AND status <> 'approved'
            LIMIT 1
            """,
            (document_id, workflow_generation),
        ).fetchone()
        if unapproved:
            raise ValueError("official_document_not_fully_approved_for_stamp_retry")
        final_approval = conn.execute(
            """
            SELECT approver_user_id FROM official_document_approval_steps
            WHERE document_id = ? AND workflow_generation = ?
              AND step_key = 'general_affairs_review' AND status = 'approved'
            LIMIT 1
            """,
            (document_id, workflow_generation),
        ).fetchone()
        if not final_approval:
            raise ValueError("official_document_not_fully_approved_for_stamp_retry")
        if claim_owner_id != "system" and str(final_approval["approver_user_id"] or "") != claim_owner_id:
            raise PermissionError("official_stamp_retry_forbidden")
        if request.get("status") == "stamped" or request.get("stamped_file_id") or document.get("stamped_file_id"):
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {"claimed": False, "reason": "official_document_already_stamped", "document_id": document_id, "stamp_request_id": stamp_request_id}

        same_owner = (
            document.get("current_status") == "stamping"
            and document.get("current_step") == "auto_stamp"
            and request.get("status") == "stamping"
            and request.get("claim_token") == claim_token
        )
        live_other = (
            request.get("status") == "stamping"
            and bool(request.get("claim_token"))
            and not same_owner
            and not official_stamp_claim_expired(request.get("claim_expires_at"))
        )
        if live_other:
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {"claimed": False, "reason": "official_stamp_claim_busy", "document_id": document_id, "stamp_request_id": stamp_request_id, "claim_expires_at": request.get("claim_expires_at") or ""}
        if not same_owner and not official_stamp_recoverable(document, request):
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {"claimed": False, "reason": "official_document_not_recoverable_for_stamp", "document_id": document_id, "stamp_request_id": stamp_request_id}

        timestamp = now()
        expires_at = (datetime.now() + timedelta(seconds=lease_seconds)).strftime("%Y-%m-%d %H:%M:%S")
        document_update = conn.execute(
            """
            UPDATE official_documents
            SET current_status = 'stamping', current_step = 'auto_stamp', updated_at = ?
            WHERE id = ? AND current_status = ? AND current_step = ?
            """,
            (timestamp, document_id, document.get("current_status") or "", document.get("current_step") or ""),
        )
        if document_update.rowcount != 1:
            raise ValueError("official_stamp_claim_conflict")
        request_update = conn.execute(
            """
            UPDATE official_document_stamp_requests
            SET status = 'stamping', claim_token = ?, claim_owner_id = ?,
                claim_started_at = ?, claim_expires_at = ?,
                claim_attempt_count = COALESCE(claim_attempt_count, 0) + ?,
                error_message = '', updated_at = ?
            WHERE id = ? AND document_id = ? AND status = ?
              AND COALESCE(claim_token, '') = COALESCE(?, '')
            """,
            (
                claim_token,
                claim_owner_id,
                request.get("claim_started_at") if same_owner else timestamp,
                expires_at,
                0 if same_owner else 1,
                timestamp,
                stamp_request_id,
                document_id,
                request.get("status") or "",
                request.get("claim_token") or "",
            ),
        )
        if request_update.rowcount != 1:
            raise ValueError("official_stamp_claim_conflict")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        return {
            "claimed": True,
            "renewed": same_owner,
            "document_id": document_id,
            "stamp_request_id": stamp_request_id,
            "claim_token": claim_token,
            "claim_expires_at": expires_at,
            "attempt_count": int(request.get("claim_attempt_count") or 0) + (0 if same_owner else 1),
        }
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        raise


def official_stamp_candidate_file(
    conn: sqlite3.Connection,
    document_id: str,
    stamp_request_id: str,
) -> Tuple[Dict[str, Any], bytes] | None:
    row = conn.execute(
        """
        SELECT * FROM official_document_files
        WHERE document_id = ? AND file_type = 'stamped_pdf' AND stamp_request_id = ?
        ORDER BY created_at DESC LIMIT 1
        """,
        (document_id, stamp_request_id),
    ).fetchone()
    if not row:
        return None
    file_meta = row_to_dict(row)
    if not file_meta.get("file_object_id"):
        raise ValueError("official_stamp_candidate_file_invalid")
    file_object, data = read_file_object_bytes(conn, file_meta["file_object_id"])
    verify_official_file_bytes(file_meta, file_object, data)
    return file_meta, data


def complete_official_document_stamp_claim(
    conn: sqlite3.Connection,
    document_id: str,
    stamp_request_id: str,
    claim_token: str,
    stamped_file_id: str,
) -> Dict[str, Any]:
    savepoint = f"official_stamp_complete_{secrets.token_hex(4)}"
    conn.execute(f"SAVEPOINT {savepoint}")
    try:
        document = official_document_row(conn, document_id)
        request_row = conn.execute(
            "SELECT * FROM official_document_stamp_requests WHERE id = ? AND document_id = ?",
            (stamp_request_id, document_id),
        ).fetchone()
        file_row = conn.execute(
            """
            SELECT * FROM official_document_files
            WHERE id = ? AND document_id = ? AND file_type = 'stamped_pdf' AND stamp_request_id = ?
            """,
            (stamped_file_id, document_id, stamp_request_id),
        ).fetchone()
        request = row_to_dict(request_row) if request_row else {}
        if not file_row:
            raise ValueError("official_stamp_candidate_file_invalid")
        if (
            document.get("current_status") != "stamping"
            or document.get("current_step") != "auto_stamp"
            or request.get("status") != "stamping"
            or request.get("claim_token") != claim_token
            or official_stamp_claim_expired(request.get("claim_expires_at"))
        ):
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {"completed": False, "reason": "official_stamp_claim_lost", "document_id": document_id, "stamp_request_id": stamp_request_id}
        method = official_dispatch_method(document.get("dispatch_method"))
        config = OFFICIAL_DISPATCH_METHODS[method]
        timestamp = now()
        # The dispatch work item is part of the durable stamp completion.  If
        # the process dies after this savepoint is released, the assigned GA
        # specialist/applicant must still be able to find and finish the job.
        # Notification and audit delivery may safely be retried afterwards.
        dispatch_record = upsert_official_dispatch_record(
            conn,
            document,
            method,
            {"id": request.get("claim_owner_id") or "system"},
        )
        request_update = conn.execute(
            """
            UPDATE official_document_stamp_requests
            SET status = 'stamped', stamped_file_id = ?, stamped_at = ?,
                claim_expires_at = NULL, error_message = '', updated_at = ?
            WHERE id = ? AND status = 'stamping' AND claim_token = ?
            """,
            (stamped_file_id, timestamp, timestamp, stamp_request_id, claim_token),
        )
        document_update = conn.execute(
            """
            UPDATE official_documents
            SET stamped_file_id = ?, current_status = ?, current_step = ?, updated_at = ?
            WHERE id = ? AND current_status = 'stamping' AND current_step = 'auto_stamp'
            """,
            (stamped_file_id, config["next_status"], config["next_step"], timestamp, document_id),
        )
        if request_update.rowcount != 1 or document_update.rowcount != 1:
            raise ValueError("official_stamp_claim_conflict")
        route_actor = active_user_by_id(conn, request.get("claim_owner_id") or "") or {
            "id": request.get("claim_owner_id") or "system",
            "name": "System",
            "role": "system",
        }
        route_notification = enqueue_official_dispatch_route(
            conn,
            document,
            dispatch_record,
            route_actor,
            stamped_file_id,
        )
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        return {
            "completed": True,
            "document_id": document_id,
            "stamp_request_id": stamp_request_id,
            "stamped_file_id": stamped_file_id,
            "dispatch_record_id": dispatch_record.get("id") or "",
            "dispatch_notification_id": route_notification.get("id") or "",
            "document_status": config["next_status"],
            "document_step": config["next_step"],
        }
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        raise


def fail_official_document_stamp_claim(
    conn: sqlite3.Connection,
    document_id: str,
    stamp_request_id: str,
    claim_token: str,
    detail: str,
) -> Dict[str, Any]:
    savepoint = f"official_stamp_fail_{secrets.token_hex(4)}"
    conn.execute(f"SAVEPOINT {savepoint}")
    try:
        timestamp = now()
        request_update = conn.execute(
            """
            UPDATE official_document_stamp_requests
            SET status = 'failed', claim_expires_at = NULL, error_message = ?, updated_at = ?
            WHERE id = ? AND document_id = ? AND status = 'stamping' AND claim_token = ?
              AND claim_expires_at IS NOT NULL AND claim_expires_at > ?
            """,
            (detail[:500], timestamp, stamp_request_id, document_id, claim_token, timestamp),
        )
        if request_update.rowcount != 1:
            conn.execute(f"RELEASE SAVEPOINT {savepoint}")
            return {"failed": False, "reason": "official_stamp_claim_lost", "document_id": document_id, "stamp_request_id": stamp_request_id}
        document_update = conn.execute(
            """
            UPDATE official_documents
            SET current_status = 'stamping_failed', current_step = 'general_affairs_review', updated_at = ?
            WHERE id = ? AND current_status = 'stamping' AND current_step = 'auto_stamp'
            """,
            (timestamp, document_id),
        )
        if document_update.rowcount != 1:
            raise ValueError("official_stamp_claim_conflict")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        return {"failed": True, "document_id": document_id, "stamp_request_id": stamp_request_id}
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
        conn.execute(f"RELEASE SAVEPOINT {savepoint}")
        raise


def auto_stamp_official_document(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], actor: Dict[str, Any] | None = None) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    stamp_request = official_document_stamp_request(conn, document_id)
    if not stamp_request:
        raise ValueError("official_document_stamp_request_required")
    claim_token = secrets.token_hex(32)
    claim = claim_official_document_stamp(
        conn,
        document_id,
        stamp_request["id"],
        claim_token,
        str((actor or {}).get("id") or "system"),
    )
    if not claim.get("claimed"):
        return {"ok": False, "error": claim.get("reason") or "official_stamp_claim_busy", "claim": claim}
    try:
        document = official_document_row(conn, document_id)
        stamp_request = official_document_stamp_request(conn, document_id) or stamp_request
        assert_official_document_uploads_av_clean(conn, document)
        # Re-verify the locked revision/seal version and physical dimensions
        # even when recovering an already-written stamped candidate.
        prevalidated_editor = verify_locked_editor_for_stamp(conn, document, stamp_request)
        prevalidated_legacy_asset: Tuple[Dict[str, Any], bytes] | None = None
        if not prevalidated_editor:
            prevalidated_legacy_asset = locked_legacy_official_seal_asset(conn, stamp_request)
        candidate = official_stamp_candidate_file(conn, document_id, stamp_request["id"])
        if candidate:
            stamped_file, _ = candidate
            engine = "recovered-stamped-candidate"
            layout = {"recovered": True}
            stamp_no = payload.get("stamp_no") or f"ODSTAMP-{document_id}-RECOVERED"
            locked_editor = prevalidated_editor
            seal_file = {"file_hash": ""}
            text_overlays: List[Dict[str, Any]] = []
        else:
            locked_editor = prevalidated_editor
            seal = company_seal_row(conn, stamp_request["seal_id"])
            if not seal.get("is_active"):
                raise ValueError("inactive_seal_cannot_stamp")
            insert_official_log(conn, document_id, "read_seal_vault_for_stamp", actor, "authorized_backend_stamp_only", ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
            if locked_editor:
                seal_file = {"file_hash": "", "file_mime_type": ""}
                seal_bytes = b""
            else:
                if not prevalidated_legacy_asset:
                    raise ValueError("official_locked_seal_version_missing")
                seal_file, seal_bytes = prevalidated_legacy_asset
            source_file = locked_editor["prepared_file"] if locked_editor else official_latest_source_file(conn, document)
            if locked_editor:
                original_pdf = locked_editor["prepared_bytes"]
            else:
                file_object_id = source_file.get("file_object_id")
                if not file_object_id:
                    raise ValueError("official_source_file_object_missing")
                source_object, original_pdf = read_file_object_bytes(conn, file_object_id)
                verify_official_file_bytes(source_file, source_object, original_pdf)
            stamp_no = payload.get("stamp_no") or f"ODSTAMP-{document_id}-{int(time.time())}"
            positions = official_stamp_positions_from_request(stamp_request, seal)
            text_overlays = stamp_request.get("text_overlays") or []
            if locked_editor:
                stamped_pdf, engine, layout = stamp_prepared_pdf_with_locked_seals(locked_editor)
            else:
                stamped_pdf, engine, layout = stamp_uploaded_pdf_bytes(
                    original_pdf,
                    [{**item, "stamp_no": stamp_no} for item in positions],
                    stamp_no,
                    text_overlays,
                    {"data": seal_bytes, "mime_type": seal_file.get("file_mime_type") or ""},
                    source_text_on_top=document.get("source_type") == "blank_editor",
                )
            # Renew immediately before the durable output write.  A worker
            # whose lease was reclaimed while rendering cannot publish.
            renewed = claim_official_document_stamp(
                conn,
                document_id,
                stamp_request["id"],
                claim_token,
                str((actor or {}).get("id") or "system"),
            )
            if not renewed.get("claimed"):
                raise ValueError("official_stamp_claim_lost")
            stamped_file = store_official_pdf_file(
                conn,
                document_id,
                "stamped_pdf",
                f"{document_id}-stamped.pdf",
                stamped_pdf,
                "Auto Stamp",
                stamp_request_id=stamp_request["id"],
                stamp_claim_token=claim_token,
            )
        renewed = claim_official_document_stamp(
            conn,
            document_id,
            stamp_request["id"],
            claim_token,
            str((actor or {}).get("id") or "system"),
        )
        if not renewed.get("claimed"):
            raise ValueError("official_stamp_claim_lost")
        completed = complete_official_document_stamp_claim(
            conn,
            document_id,
            stamp_request["id"],
            claim_token,
            stamped_file["id"],
        )
        if not completed.get("completed"):
            raise ValueError("official_stamp_claim_lost")
        seal_hash_audit = ",".join(sorted({str(item.get("locked_seal_sha256") or "") for item in (stamp_request.get("stamp_positions") or []) if item.get("locked_seal_sha256")})) or seal_file["file_hash"]
        try:
            insert_official_log(conn, document_id, "auto_stamp", actor, f"{engine} {stamp_no} seal_hashes={seal_hash_audit} seal_image=true text_overlays={len(text_overlays)} prepared_sha256={(locked_editor or {}).get('prepared_file', {}).get('file_hash', '')}", file_id=stamped_file["id"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
            dispatch_record = advance_official_dispatch_after_stamp(conn, document_id, stamped_file, actor, payload)
            post_processing_warning = ""
        except Exception as post_exc:
            # Completion already advanced the durable document state.  A
            # notification/dispatch-record failure must not roll it back to a
            # false stamping failure or make the stamped PDF unreachable.
            dispatch_record = official_dispatch_record(conn, document_id)
            post_processing_warning = f"stamp_post_processing_failed:{type(post_exc).__name__}"
        return {"ok": True, "stamped_file": official_file_metadata(stamped_file), "engine": engine, "layout": layout, "dispatch_record": dispatch_record, "post_processing_warning": post_processing_warning}
    except Exception as exc:
        detail = redact_text(str(exc))[:500]
        failed = fail_official_document_stamp_claim(conn, document_id, stamp_request["id"], claim_token, detail)
        if failed.get("failed"):
            insert_official_log(conn, document_id, "auto_stamp_failed", actor, detail, ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
            try:
                ga_actor = official_dispatch_workflow_owner(official_document_steps(conn, document_id))
                ga_user = active_user_by_id(conn, ga_actor["id"]) or {}
                create_and_deliver_notification(conn, {
                    "type": "發文用印失敗",
                    "title": f"{document['title']} 自動用印失敗",
                    **exact_notification_target_payload(ga_user, document.get("company_id") or ""),
                    "source": document_id,
                    "priority": "高",
                    "body": detail,
                })
            except Exception as notification_exc:
                log_structured(
                    "error",
                    "official_stamp_failure_notification_failed",
                    document_id=document_id,
                    error=redact_text(str(notification_exc))[:200],
                )
            return {"ok": False, "error": "auto_stamp_failed", "detail": detail}
        return {"ok": False, "error": "official_stamp_claim_lost", "detail": "用印租約已由其他工作程序接手。"}


def retry_official_document_stamp(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    stamp_request = official_document_stamp_request(conn, document_id)
    if not official_stamp_recoverable(document, stamp_request):
        raise ValueError("official_document_not_recoverable_for_stamp")
    steps = official_document_steps(conn, document_id)
    if not can_retry_official_stamp(user, steps):
        raise PermissionError("official_stamp_retry_forbidden")
    unapproved_steps = [
        step for step in steps
        if step.get("step_key") != "applicant_confirm" and step.get("status") != "approved"
    ]
    if unapproved_steps:
        raise ValueError("official_document_not_fully_approved_for_stamp_retry")
    if not stamp_request:
        raise ValueError("official_document_stamp_request_required")
    insert_official_log(conn, document_id, "retry_auto_stamp", user, payload.get("comment") or "總務重試自動用印", ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    result = auto_stamp_official_document(conn, document_id, payload, user)
    return {**official_document_detail(conn, document_id, session), "auto_stamp": result}


def official_document_download_file(conn: sqlite3.Connection, document_id: str, file_id: str, session: Dict[str, Any] | None, ip_address: str = "", user_agent: str = "") -> Tuple[Dict[str, Any], Dict[str, Any], bytes]:
    user = official_session_user(session)
    document = official_document_row(conn, document_id)
    steps = official_document_steps(conn, document_id)
    actor_snapshots = official_document_actor_snapshots(conn, document_id)
    if not canDownloadOfficialDocument(user, document, steps, actor_snapshots):
        raise PermissionError("official_document_download_forbidden")
    # A clean stamped derivative must not become a bypass for an unscanned or
    # later-quarantined original/attachment that remains part of the package.
    assert_official_document_uploads_av_clean(conn, document)
    file_row = conn.execute("SELECT * FROM official_document_files WHERE id = ? AND document_id = ?", (file_id, document_id)).fetchone()
    if not file_row:
        raise ValueError("official_document_file_not_found")
    file_meta = row_to_dict(file_row)
    if not file_meta.get("file_object_id"):
        raise ValueError("official_document_file_object_missing")
    object_record = conn.execute("SELECT * FROM file_objects WHERE id = ?", (file_meta["file_object_id"],)).fetchone()
    require_official_file_av_clean(file_meta, object_record)
    object_row, data = read_file_object_bytes(conn, file_meta["file_object_id"])
    verify_official_file_bytes(file_meta, object_row, data)
    insert_official_log(conn, document_id, "download_file", user, file_meta["file_type"], file_id=file_id, ip_address=ip_address, user_agent=user_agent)
    record_file_access(conn, file_object_id=file_meta["file_object_id"], document_id=document_id, actor=official_actor_name(user), action="發文附件下載", result="成功", detail=file_meta["file_type"])
    return document, {**file_meta, "object": object_row}, data


def local_editor_asset_download(conn: sqlite3.Connection, document_id: str, asset_id: str, expires: int, token: str, session: Dict[str, Any] | None) -> Tuple[Dict[str, Any], bytes]:
    _validate_editor_asset_access_token(document_id, asset_id, expires, token)
    document = official_document_row(conn, document_id)
    user = _editor_assert_document_access(conn, document, session, write=False)
    row = conn.execute("SELECT * FROM official_document_editor_assets WHERE id = ? AND document_id = ? AND upload_status = 'finalized' AND scan_status = 'passed'", (asset_id, document_id)).fetchone()
    if not row:
        raise ValueError("editor_asset_not_found")
    asset = row_to_dict(row)
    if asset.get("asset_kind") == "prepared_pdf" or not asset.get("file_object_id"):
        raise PermissionError("editor_asset_download_forbidden")
    _, data = read_file_object_bytes(conn, asset["file_object_id"])
    if sha256_bytes(data) != asset["sha256"]:
        raise ValueError("editor_asset_hash_mismatch")
    insert_official_log(conn, document_id, "editor_asset_download", user, f"asset_id={asset_id};sha256={asset['sha256']};expires={expires}")
    return asset, data


def canonical_editor_manifest(state: Dict[str, Any]) -> str:
    """Hash EditorState v2 without its self-referential manifest field."""
    normalized = json.loads(json.dumps(state, ensure_ascii=False))
    normalized.pop("manifestSha256", None)
    return sha256_bytes(json.dumps(normalized, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8"))


def require_a4_pdf_page(width_pt: Any, height_pt: Any, page_number: int) -> Tuple[float, float]:
    """Require an A4 CropBox while accepting either portrait or landscape."""
    width = pdf_safe_float(width_pt, float("nan"))
    height = pdf_safe_float(height_pt, float("nan"))
    if not math.isfinite(width) or not math.isfinite(height) or width <= 0 or height <= 0:
        raise ValueError("editor_pdf_invalid_geometry")
    short_edge, long_edge = sorted((width, height))
    if (
        abs(short_edge - EDOC_A4_WIDTH_PT) > EDOC_A4_PAGE_TOLERANCE_PT
        or abs(long_edge - EDOC_A4_HEIGHT_PT) > EDOC_A4_PAGE_TOLERANCE_PT
    ):
        raise ValueError(
            f"pdf_page_not_a4:page={int(page_number)};widthPt={width:.2f};heightPt={height:.2f}"
        )
    return width, height


def validate_editor_state(state: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(state, dict) or int(state.get("schemaVersion") or 0) != EDOC_EDITOR_SCHEMA_VERSION:
        raise ValueError("editor_schema_version_unsupported")
    try:
        if len(json.dumps(state, ensure_ascii=False, separators=(",", ":")).encode("utf-8")) > EDOC_EDITOR_MAX_STATE_BYTES:
            raise ValueError("editor_state_too_large")
    except (TypeError, OverflowError) as exc:
        raise ValueError("editor_state_invalid") from exc
    pages = state.get("pages")
    elements = state.get("elements")
    source_files = state.get("sourceFiles")
    if not isinstance(pages, list) or not isinstance(elements, list) or not isinstance(source_files, list):
        raise ValueError("editor_state_invalid")
    if len(pages) > EDOC_EDITOR_MAX_PAGES:
        raise ValueError("editor_pdf_page_limit_exceeded")
    if len(elements) > EDOC_EDITOR_MAX_ELEMENTS:
        raise ValueError("editor_element_limit_exceeded")
    source_asset_ids: set[str] = set()
    for source in source_files:
        if not isinstance(source, dict):
            raise ValueError("editor_source_file_invalid")
        asset_id = str(source.get("assetId") or "")
        if not asset_id or asset_id in source_asset_ids:
            raise ValueError("editor_source_asset_id_invalid")
        if str(source.get("kind") or "source_pdf") not in EDOC_EDITOR_ALLOWED_ASSET_KINDS - {"prepared_pdf"}:
            raise ValueError("editor_source_asset_kind_invalid")
        source_asset_ids.add(asset_id)
    page_ids: set[str] = set()
    page_geometry: Dict[str, Tuple[float, float]] = {}
    for order, page in enumerate(pages):
        if not isinstance(page, dict):
            raise ValueError("editor_page_invalid")
        page_id = str(page.get("pageId") or "")
        if not page_id or page_id in page_ids:
            raise ValueError("editor_page_id_invalid")
        page_ids.add(page_id)
        source_asset_id = str(page.get("sourceAssetId") or "")
        if not source_asset_id or source_asset_id not in source_asset_ids:
            raise ValueError("editor_page_source_asset_missing")
        try:
            source_page_index = int(page.get("sourcePageIndex"))
        except (TypeError, ValueError) as exc:
            raise ValueError("editor_source_page_index_invalid") from exc
        if source_page_index < 0:
            raise ValueError("editor_source_page_index_invalid")
        page["sourcePageIndex"] = source_page_index
        width = pdf_safe_float(page.get("widthPt"), float("nan"))
        height = pdf_safe_float(page.get("heightPt"), float("nan"))
        if not math.isfinite(width) or not math.isfinite(height) or width <= 0 or height <= 0 or width > 14400 or height > 14400:
            raise ValueError("editor_page_geometry_invalid")
        require_a4_pdf_page(width, height, order + 1)
        crop_box = page.get("cropBox")
        if not isinstance(crop_box, list) or len(crop_box) != 4:
            raise ValueError("editor_page_cropbox_invalid")
        crop = [pdf_safe_float(value, float("nan")) for value in crop_box]
        if not all(math.isfinite(value) for value in crop) or crop[2] <= crop[0] or crop[3] <= crop[1]:
            raise ValueError("editor_page_cropbox_invalid")
        if abs((crop[2] - crop[0]) - width) > 1 or abs((crop[3] - crop[1]) - height) > 1:
            raise ValueError("editor_page_cropbox_mismatch")
        raw_rotation = pdf_safe_float(page.get("rotation"), float("nan"))
        if not math.isfinite(raw_rotation) or abs(raw_rotation - round(raw_rotation)) > 0.0001 or int(round(raw_rotation)) % 90:
            raise ValueError("editor_page_rotation_invalid")
        page["widthPt"] = round(width, 4)
        page["heightPt"] = round(height, 4)
        page["cropBox"] = [round(value, 4) for value in crop]
        page["order"] = order
        page["rotation"] = int(round(raw_rotation)) % 360
        page_geometry[page_id] = (width, height)
    element_ids: set[str] = set()
    for element in elements:
        if not isinstance(element, dict):
            raise ValueError("editor_element_invalid")
        element_id = str(element.get("id") or "")
        kind = str(element.get("kind") or "")
        if not element_id or element_id in element_ids:
            raise ValueError("editor_element_id_invalid")
        if kind not in EDOC_EDITOR_ALLOWED_ELEMENT_KINDS:
            raise ValueError("editor_element_kind_unsupported")
        if str(element.get("pageId") or "") not in page_ids:
            raise ValueError("editor_element_page_missing")
        element_ids.add(element_id)
        geometry: Dict[str, float] = {}
        for field in ("x", "y", "width", "height"):
            value = pdf_safe_float(element.get(field), float("nan"))
            if not math.isfinite(value) or value < 0 or (field in {"width", "height"} and value <= 0):
                raise ValueError("editor_element_geometry_invalid")
            geometry[field] = value
            element[field] = round(value, 4)
        page_width, page_height = page_geometry[str(element.get("pageId") or "")]
        if geometry["x"] + geometry["width"] > page_width + 1 or geometry["y"] + geometry["height"] > page_height + 1:
            raise ValueError("editor_element_out_of_bounds")
        rotation = pdf_safe_float(element.get("rotation", 0), float("nan"))
        opacity = pdf_safe_float(element.get("opacity", 1), float("nan"))
        if not math.isfinite(rotation) or not math.isfinite(opacity) or opacity < 0 or opacity > 1:
            raise ValueError("editor_element_style_invalid")
        radians = math.radians(rotation % 360)
        rotated_width = abs(math.cos(radians)) * geometry["width"] + abs(math.sin(radians)) * geometry["height"]
        rotated_height = abs(math.sin(radians)) * geometry["width"] + abs(math.cos(radians)) * geometry["height"]
        center_x = geometry["x"] + geometry["width"] / 2
        center_y = geometry["y"] + geometry["height"] / 2
        if center_x - rotated_width / 2 < -1 or center_y - rotated_height / 2 < -1 or center_x + rotated_width / 2 > page_width + 1 or center_y + rotated_height / 2 > page_height + 1:
            raise ValueError("editor_element_out_of_bounds")
        element["rotation"] = round(rotation % 360, 4)
        element["opacity"] = round(opacity, 4)
        z_index = pdf_safe_float(element.get("zIndex", 0), float("nan"))
        if not math.isfinite(z_index) or abs(z_index - round(z_index)) > 0.0001:
            raise ValueError("editor_element_z_index_invalid")
        element["zIndex"] = int(round(z_index))
        if not isinstance(element.get("properties"), dict):
            element["properties"] = {}
    state["manifestSha256"] = canonical_editor_manifest(state)
    return state


def editor_state_seal_ids(state: Dict[str, Any]) -> List[str]:
    """Return every distinct seal referenced by an EditorState placement."""
    seal_ids: List[str] = []
    seen: set[str] = set()
    for element in state.get("elements") or []:
        if not isinstance(element, dict) or element.get("kind") != "seal":
            continue
        properties = element.get("properties") if isinstance(element.get("properties"), dict) else {}
        seal_id = str(properties.get("sealId") or properties.get("seal_id") or element.get("sealId") or "")
        if not seal_id:
            raise ValueError("editor_seal_id_required")
        if seal_id not in seen:
            seen.add(seal_id)
            seal_ids.append(seal_id)
    return seal_ids


def local_editor_seal_file_context(
    conn: sqlite3.Connection,
    company_id: str,
    element: Dict[str, Any],
    *,
    bind_missing: bool,
    require_current_selection: bool,
) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    """Resolve and attest the immutable Seal Vault version selected by an element."""
    properties = element.get("properties") if isinstance(element.get("properties"), dict) else {}
    element["properties"] = properties
    seal_id = str(properties.get("sealId") or properties.get("seal_id") or element.get("sealId") or "")
    seal = validate_official_document_seal(conn, seal_id, company_id, require_current=False)
    file_id = str(properties.get("sealFileId") or properties.get("seal_file_id") or "")
    expected_hash = str(properties.get("sealFileSha256") or properties.get("seal_file_sha256") or "")
    if bool(file_id) != bool(expected_hash):
        raise ValueError("editor_seal_file_binding_required")
    if file_id:
        row = conn.execute(
            "SELECT * FROM company_seal_files WHERE id = ? AND seal_id = ?",
            (file_id, seal_id),
        ).fetchone()
        if not row:
            raise ValueError("editor_seal_file_not_found")
        seal_file = require_seal_file_av_clean(conn, row)
        if expected_hash != str(seal_file.get("file_hash") or ""):
            raise ValueError("editor_seal_file_hash_mismatch")
    else:
        if not bind_missing:
            raise ValueError("editor_seal_file_binding_required")
        seal_file = require_current_company_seal_file(conn, seal_id)
    if require_current_selection:
        current_file = require_current_company_seal_file(conn, seal_id)
        if str(seal_file.get("id") or "") != str(current_file.get("id") or ""):
            raise ValueError("editor_seal_file_must_be_current")
    if str(seal_file.get("dimension_policy_version") or "") != EDOC_SEAL_DIMENSION_POLICY_VERSION:
        raise ValueError("editor_seal_file_policy_upgrade_required")
    profile = company_seal_file_dimension_profile(seal.get("seal_size_type"), seal_file)
    properties.update({
        "sealId": seal_id,
        "sealFileId": str(seal_file.get("id") or ""),
        "sealFileSha256": str(seal_file.get("file_hash") or ""),
        "renderSizeMm": profile["width_mm"],
        "renderWidthMm": profile["width_mm"],
        "renderHeightMm": profile["height_mm"],
        "dimensionPolicyVersion": profile["dimension_policy_version"],
    })
    return seal, seal_file, profile


def supabase_editor_seal_file_context(
    company_id: str,
    element: Dict[str, Any],
    *,
    bind_missing: bool,
    require_current_selection: bool,
) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    properties = element.get("properties") if isinstance(element.get("properties"), dict) else {}
    element["properties"] = properties
    seal_id = str(properties.get("sealId") or properties.get("seal_id") or element.get("sealId") or "")
    seal = supabase_validate_official_document_seal(seal_id, company_id, require_current=False)
    file_id = str(properties.get("sealFileId") or properties.get("seal_file_id") or "")
    expected_hash = str(properties.get("sealFileSha256") or properties.get("seal_file_sha256") or "")
    if bool(file_id) != bool(expected_hash):
        raise ValueError("editor_seal_file_binding_required")
    if file_id:
        rows = supabase_filter_rows(
            "company_seal_files",
            {"id": file_id, "seal_id": seal_id},
            limit=1,
        )
        if not rows:
            raise ValueError("editor_seal_file_not_found")
        seal_file = supabase_require_seal_file_av_clean(rows[0])
        if expected_hash != str(seal_file.get("file_hash") or ""):
            raise ValueError("editor_seal_file_hash_mismatch")
    else:
        if not bind_missing:
            raise ValueError("editor_seal_file_binding_required")
        seal_file = supabase_require_current_company_seal_file(seal_id)
    if require_current_selection:
        current_file = supabase_require_current_company_seal_file(seal_id)
        if str(seal_file.get("id") or "") != str(current_file.get("id") or ""):
            raise ValueError("editor_seal_file_must_be_current")
    if str(seal_file.get("dimension_policy_version") or "") != EDOC_SEAL_DIMENSION_POLICY_VERSION:
        raise ValueError("editor_seal_file_policy_upgrade_required")
    profile = company_seal_file_dimension_profile(seal.get("seal_size_type"), seal_file)
    properties.update({
        "sealId": seal_id,
        "sealFileId": str(seal_file.get("id") or ""),
        "sealFileSha256": str(seal_file.get("file_hash") or ""),
        "renderSizeMm": profile["width_mm"],
        "renderWidthMm": profile["width_mm"],
        "renderHeightMm": profile["height_mm"],
        "dimensionPolicyVersion": profile["dimension_policy_version"],
    })
    return seal, seal_file, profile


def editor_state_seal_binding_map(state: Dict[str, Any] | None) -> Dict[str, Dict[str, str]]:
    bindings: Dict[str, Dict[str, str]] = {}
    for element in (state or {}).get("elements") or []:
        if not isinstance(element, dict) or element.get("kind") != "seal":
            continue
        element_id = str(element.get("id") or "")
        properties = element.get("properties") if isinstance(element.get("properties"), dict) else {}
        if not element_id:
            continue
        bindings[element_id] = {
            "seal_id": str(properties.get("sealId") or properties.get("seal_id") or element.get("sealId") or ""),
            "file_id": str(properties.get("sealFileId") or properties.get("seal_file_id") or ""),
            "file_sha256": str(properties.get("sealFileSha256") or properties.get("seal_file_sha256") or ""),
        }
    return bindings


def validate_editor_seal_placements(
    conn: sqlite3.Connection,
    company_id: str,
    state: Dict[str, Any],
    *,
    bind_missing: bool = True,
    previous_state: Dict[str, Any] | None = None,
) -> None:
    """Fail closed before persisting or preparing a placement for an unusable seal."""
    editor_state_seal_ids(state)
    previous_bindings = editor_state_seal_binding_map(previous_state)
    for element in state.get("elements") or []:
        if not isinstance(element, dict) or element.get("kind") != "seal":
            continue
        properties = element.get("properties") if isinstance(element.get("properties"), dict) else {}
        element["properties"] = properties
        element_id = str(element.get("id") or "")
        seal_id = str(properties.get("sealId") or properties.get("seal_id") or element.get("sealId") or "")
        incoming_file_id = str(properties.get("sealFileId") or properties.get("seal_file_id") or "")
        incoming_hash = str(properties.get("sealFileSha256") or properties.get("seal_file_sha256") or "")
        if bool(incoming_file_id) != bool(incoming_hash):
            raise ValueError("editor_seal_file_binding_required")
        previous = previous_bindings.get(element_id) or {}
        same_existing_binding = bool(
            previous.get("seal_id") == seal_id
            and previous.get("file_id")
            and (not incoming_file_id or incoming_file_id == previous.get("file_id"))
        )
        if same_existing_binding:
            if incoming_hash and incoming_hash != previous.get("file_sha256"):
                raise ValueError("editor_seal_file_hash_mismatch")
            properties["sealFileId"] = previous["file_id"]
            properties["sealFileSha256"] = previous["file_sha256"]
        seal, seal_file, profile = local_editor_seal_file_context(
            conn,
            company_id,
            element,
            bind_missing=bind_missing,
            require_current_selection=not same_existing_binding,
        )
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"), element.get("width"), element.get("height"),
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
        )
        # EditorState geometry is canonicalized to four decimals by
        # validate_editor_state. Keep seal calibration on the same grid so a
        # preflight recheck is idempotent and never creates a phantom revision.
        element["width"] = round(width, 4)
        element["height"] = round(height, 4)


def validate_supabase_editor_seal_placements(
    company_id: str,
    state: Dict[str, Any],
    *,
    bind_missing: bool = True,
    previous_state: Dict[str, Any] | None = None,
) -> None:
    editor_state_seal_ids(state)
    previous_bindings = editor_state_seal_binding_map(previous_state)
    for element in state.get("elements") or []:
        if not isinstance(element, dict) or element.get("kind") != "seal":
            continue
        properties = element.get("properties") if isinstance(element.get("properties"), dict) else {}
        element["properties"] = properties
        element_id = str(element.get("id") or "")
        seal_id = str(properties.get("sealId") or properties.get("seal_id") or element.get("sealId") or "")
        incoming_file_id = str(properties.get("sealFileId") or properties.get("seal_file_id") or "")
        incoming_hash = str(properties.get("sealFileSha256") or properties.get("seal_file_sha256") or "")
        if bool(incoming_file_id) != bool(incoming_hash):
            raise ValueError("editor_seal_file_binding_required")
        previous = previous_bindings.get(element_id) or {}
        same_existing_binding = bool(
            previous.get("seal_id") == seal_id
            and previous.get("file_id")
            and (not incoming_file_id or incoming_file_id == previous.get("file_id"))
        )
        if same_existing_binding:
            if incoming_hash and incoming_hash != previous.get("file_sha256"):
                raise ValueError("editor_seal_file_hash_mismatch")
            properties["sealFileId"] = previous["file_id"]
            properties["sealFileSha256"] = previous["file_sha256"]
        seal, seal_file, profile = supabase_editor_seal_file_context(
            company_id,
            element,
            bind_missing=bind_missing,
            require_current_selection=not same_existing_binding,
        )
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"), element.get("width"), element.get("height"),
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
        )
        element["width"] = round(width, 4)
        element["height"] = round(height, 4)


def _pdf_resolved(value: Any) -> Any:
    try:
        resolved = value.get_object()
    except Exception:
        resolved = value
    return None if resolved is None or type(resolved).__name__ == "NullObject" else resolved


def inspect_editor_pdf(data: bytes) -> Dict[str, Any]:
    """Strictly inspect an editor PDF without executing any embedded action."""
    if not data.startswith(b"%PDF"):
        raise ValueError("editor_pdf_invalid_header")
    if len(data) > EDOC_EDITOR_MAX_FILE_SIZE_MB * 1024 * 1024:
        raise ValueError("editor_pdf_too_large")
    try:
        from pypdf import PdfReader  # type: ignore

        reader = PdfReader(io.BytesIO(data), strict=True)
        if reader.is_encrypted:
            raise ValueError("editor_pdf_encrypted")
        root = _pdf_resolved(reader.trailer.get("/Root")) or {}
        names = _pdf_resolved(root.get("/Names")) or {}
        if root.get("/OpenAction") is not None or root.get("/AA") is not None:
            action = _pdf_resolved(root.get("/OpenAction")) or _pdf_resolved(root.get("/AA")) or {}
            if str(action.get("/S") or "") == "/Launch":
                raise ValueError("editor_pdf_launch_action_not_supported")
            raise ValueError("editor_pdf_javascript_not_supported")
        if names.get("/EmbeddedFiles") is not None:
            raise ValueError("editor_pdf_embedded_files_not_supported")
        if names.get("/JavaScript") is not None or b"/JavaScript" in data or b"/JS" in data:
            raise ValueError("editor_pdf_javascript_not_supported")
        if b"/ByteRange" in data:
            raise ValueError("editor_pdf_digital_signature_not_supported")
        acroform = _pdf_resolved(root.get("/AcroForm")) or {}
        if acroform.get("/XFA") is not None or b"/XFA" in data:
            raise ValueError("editor_pdf_xfa_not_supported")
        fields = _pdf_resolved(acroform.get("/Fields")) or []
        for raw_field in fields:
            field = _pdf_resolved(raw_field) or {}
            if str(field.get("/FT") or "") == "/Sig":
                raise ValueError("editor_pdf_digital_signature_not_supported")
            appearance = _pdf_resolved(field.get("/AP")) or {}
            kids = _pdf_resolved(field.get("/Kids")) or []
            if fields and not appearance.get("/N") and not kids:
                raise ValueError("editor_pdf_form_appearance_required")
            for raw_kid in kids:
                kid = _pdf_resolved(raw_kid) or {}
                kid_appearance = _pdf_resolved(kid.get("/AP")) or {}
                if not kid_appearance.get("/N"):
                    raise ValueError("editor_pdf_form_appearance_required")
        if len(reader.pages) < 1:
            raise ValueError("editor_pdf_empty")
        if len(reader.pages) > EDOC_EDITOR_MAX_PAGES:
            raise ValueError("editor_pdf_page_limit_exceeded")
        pages: List[Dict[str, Any]] = []
        for index, page in enumerate(reader.pages):
            if page.get("/AA") is not None:
                raise ValueError("editor_pdf_javascript_not_supported")
            for annotation_ref in _pdf_resolved(page.get("/Annots")) or []:
                annotation = _pdf_resolved(annotation_ref) or {}
                if str(annotation.get("/Subtype") or "") == "/FileAttachment":
                    raise ValueError("editor_pdf_embedded_files_not_supported")
                action = _pdf_resolved(annotation.get("/A")) or {}
                if str(action.get("/S") or "") == "/Launch":
                    raise ValueError("editor_pdf_launch_action_not_supported")
            crop = page.cropbox
            media = page.mediabox
            user_unit = pdf_safe_float(page.get("/UserUnit"), 1.0)
            raw_rotation = pdf_safe_float(page.get("/Rotate"), 0)
            if (
                not math.isfinite(raw_rotation)
                or abs(raw_rotation - round(raw_rotation)) > 0.0001
                or int(round(raw_rotation)) % 90
            ):
                raise ValueError("editor_page_rotation_invalid")
            width = float(crop.width) * user_unit
            height = float(crop.height) * user_unit
            if width <= 0 or height <= 0:
                raise ValueError("editor_pdf_invalid_geometry")
            require_a4_pdf_page(width, height, index + 1)
            pages.append({
                "sourcePageIndex": index,
                "widthPt": round(width, 4),
                "heightPt": round(height, 4),
                "cropBox": [round(float(crop.left) * user_unit, 4), round(float(crop.bottom) * user_unit, 4), round(float(crop.right) * user_unit, 4), round(float(crop.top) * user_unit, 4)],
                "mediaBox": [round(float(media.left) * user_unit, 4), round(float(media.bottom) * user_unit, 4), round(float(media.right) * user_unit, 4), round(float(media.top) * user_unit, 4)],
                "rotation": int(round(raw_rotation)) % 360,
                "userUnit": user_unit,
            })
        return {
            "ok": True,
            "pageCount": len(pages),
            "pages": pages,
            "flags": {
                "encrypted": False,
                "digitallySigned": False,
                "xfa": False,
                "embeddedFiles": False,
                "javascript": False,
                "acroForm": bool(fields),
            },
        }
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError(f"editor_pdf_corrupt:{type(exc).__name__}") from exc


def inspect_editor_image(data: bytes, mime_type: str) -> Dict[str, Any]:
    from PIL import Image, UnidentifiedImageError  # type: ignore

    expected_format = "PNG" if mime_type == "image/png" else "JPEG" if mime_type == "image/jpeg" else ""
    if not expected_format:
        raise ValueError("editor_image_type_not_supported")
    try:
        with Image.open(io.BytesIO(data)) as image:
            actual_format = str(image.format or "").upper()
            width, height = image.size
            image.verify()
        if actual_format != expected_format or width <= 0 or height <= 0 or width * height > 40_000_000:
            raise ValueError("editor_image_invalid")
        return {"ok": True, "format": actual_format, "widthPx": width, "heightPx": height, "pages": [], "pageCount": 0, "flags": {"executable": False}}
    except ValueError:
        raise
    except (UnidentifiedImageError, OSError, Image.DecompressionBombError) as exc:
        raise ValueError("editor_image_invalid") from exc


def _editor_color(value: Any, fallback: Tuple[float, float, float] = (0.0, 0.0, 0.0)) -> Tuple[float, float, float]:
    if isinstance(value, str) and re.fullmatch(r"#[0-9A-Fa-f]{6}", value):
        return tuple(int(value[index:index + 2], 16) / 255 for index in (1, 3, 5))  # type: ignore[return-value]
    if isinstance(value, list) and len(value) >= 3:
        values = [max(0.0, min(1.0, pdf_safe_float(item, 0))) for item in value[:3]]
        return values[0], values[1], values[2]
    return fallback


def _editor_rect(element: Dict[str, Any], page_height: float) -> Any:
    import fitz  # type: ignore

    x = pdf_safe_float(element.get("x"), 0)
    y = pdf_safe_float(element.get("y"), 0)
    width = max(0.1, pdf_safe_float(element.get("width"), 0.1))
    height = max(0.1, pdf_safe_float(element.get("height"), 0.1))
    return fitz.Rect(x, page_height - y - height, x + width, page_height - y)


def _editor_rect_center(rect: Any) -> Any:
    import fitz  # type: ignore

    return fitz.Point((float(rect.x0) + float(rect.x1)) / 2, (float(rect.y0) + float(rect.y1)) / 2)


def _editor_transformed_image(
    data: bytes,
    mime_type: str,
    width_pt: float,
    height_pt: float,
    rotation: float,
    opacity: float,
) -> Tuple[bytes, float, float]:
    """Create a transparent bitmap for arbitrary-angle image/seal placement."""
    import fitz  # type: ignore
    from PIL import Image, ImageEnhance  # type: ignore

    source = data
    if "svg" in str(mime_type or "").lower():
        svg_doc = fitz.open(stream=data, filetype="svg")
        pdf_doc = fitz.open(stream=svg_doc.convert_to_pdf(), filetype="pdf")
        try:
            source = pdf_doc[0].get_pixmap(matrix=fitz.Matrix(3, 3), alpha=True).tobytes("png")
        finally:
            pdf_doc.close()
            svg_doc.close()
    width_pt = max(0.1, float(width_pt))
    height_pt = max(0.1, float(height_pt))
    scale = min(
        3.0,
        math.sqrt(EDOC_EDITOR_MAX_RENDER_PIXELS / max(1.0, width_pt * height_pt)),
        EDOC_EDITOR_MAX_RENDER_DIMENSION / max(width_pt, height_pt),
    )
    target_width = max(1, int(round(max(0.1, width_pt) * scale)))
    target_height = max(1, int(round(max(0.1, height_pt) * scale)))
    with Image.open(io.BytesIO(source)) as opened:
        image = opened.convert("RGBA")
        image.thumbnail((target_width, target_height), Image.Resampling.LANCZOS)
        canvas = Image.new("RGBA", (target_width, target_height), (0, 0, 0, 0))
        canvas.alpha_composite(image, ((target_width - image.width) // 2, (target_height - image.height) // 2))
    if opacity < 1:
        alpha = ImageEnhance.Brightness(canvas.getchannel("A")).enhance(max(0.0, opacity))
        canvas.putalpha(alpha)
    angle = float(rotation or 0) % 360
    transformed = canvas.rotate(-angle, resample=Image.Resampling.BICUBIC, expand=True) if angle else canvas
    output = io.BytesIO()
    transformed.save(output, format="PNG", optimize=True)
    return output.getvalue(), transformed.width / scale, transformed.height / scale


def _editor_centered_rect(rect: Any, width: float, height: float) -> Any:
    import fitz  # type: ignore

    center = _editor_rect_center(rect)
    return fitz.Rect(center.x - width / 2, center.y - height / 2, center.x + width / 2, center.y + height / 2)


def _editor_kai_font_name() -> str:
    """Return the locked ReportLab Kai face used for all entered PDF text."""
    return str(official_pdf_font_profile()["name"])


def _editor_wrap_kai_text(text: str, max_width: float, font_name: str, font_size: float) -> List[str]:
    from reportlab.pdfbase import pdfmetrics  # type: ignore

    lines: List[str] = []
    for paragraph in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if not paragraph:
            lines.append("")
            continue
        current = ""
        for character in paragraph:
            candidate = current + character
            if current and pdfmetrics.stringWidth(candidate, font_name, font_size) > max_width:
                lines.append(current)
                current = character
            else:
                current = candidate
        lines.append(current)
    return lines or [""]


def _editor_insert_kai_text(
    page: Any,
    element: Dict[str, Any],
    page_height: float,
    *,
    flatten_for_front: bool = False,
) -> None:
    import fitz  # type: ignore
    from reportlab.pdfbase import pdfmetrics  # type: ignore
    from reportlab.pdfgen import canvas  # type: ignore

    props = element.get("properties") or {}
    text_value = str(props.get("text") or props.get("value") or "")
    if not text_value:
        return
    page_width = float(page.rect.width)
    page_height = float(page_height)
    x = pdf_safe_float(element.get("x"), 0)
    y = pdf_safe_float(element.get("y"), 0)
    width = max(0.1, pdf_safe_float(element.get("width"), 0.1))
    height = max(0.1, pdf_safe_float(element.get("height"), 0.1))
    opacity = max(0.0, min(1.0, pdf_safe_float(element.get("opacity"), 1)))
    rotation = pdf_safe_float(element.get("rotation"), 0) % 360
    font_size = max(4.0, min(144.0, pdf_safe_float(props.get("fontSize"), 12)))
    font_name = _editor_kai_font_name()
    lines = _editor_wrap_kai_text(text_value, width, font_name, font_size)
    leading = font_size * 1.2
    color = _editor_color(props.get("color"))
    align = str(props.get("align") or "left")

    overlay_buffer = io.BytesIO()
    overlay_canvas = canvas.Canvas(
        overlay_buffer,
        pagesize=(page_width, page_height),
        pageCompression=1,
        invariant=1,
        pdfVersion=(1, 4),
    )
    overlay_canvas.saveState()
    if hasattr(overlay_canvas, "setFillAlpha"):
        overlay_canvas.setFillAlpha(opacity)
    overlay_canvas.setFillColorRGB(*color)
    overlay_canvas.setFont(font_name, font_size)
    center_x = x + width / 2
    center_y = y + height / 2
    overlay_canvas.translate(center_x, center_y)
    overlay_canvas.rotate(-rotation)
    local_x = -width / 2
    local_y_top = height / 2
    ascent = pdfmetrics.getAscent(font_name, font_size)
    for line_index, line in enumerate(lines):
        baseline = local_y_top - ascent - line_index * leading
        if baseline < -height / 2 - font_size:
            break
        line_width = pdfmetrics.stringWidth(line, font_name, font_size)
        line_x = (
            local_x + (width - line_width) / 2
            if align == "center"
            else local_x + width - line_width
            if align == "right"
            else local_x
        )
        overlay_canvas.drawString(line_x, baseline, line)
    overlay_canvas.restoreState()
    overlay_canvas.showPage()
    overlay_canvas.save()

    overlay_document = fitz.open(stream=overlay_buffer.getvalue(), filetype="pdf")
    try:
        if flatten_for_front:
            # The searchable Kai text already exists once in prepared_pdf.
            # Repaint the intersecting foreground as a transparent derivative
            # so search/a11y extraction does not receive a duplicate string.
            clip = _editor_visual_bounds(element, page_height) & fitz.Rect(page.rect)
            if not clip.is_empty and not clip.is_infinite:
                pixmap = overlay_document[0].get_pixmap(matrix=fitz.Matrix(4, 4), clip=clip, alpha=True)
                page.insert_image(clip, stream=pixmap.tobytes("png"), keep_proportion=False, overlay=True)
        else:
            page.show_pdf_page(page.rect, overlay_document, 0, keep_proportion=False, overlay=True)
    finally:
        overlay_document.close()


def _editor_element_layer_rank(element: Dict[str, Any]) -> int:
    """Company seals are lowest; entered/replacement text is always highest."""
    kind = str(element.get("kind") or "")
    if kind == "seal":
        return 0
    if kind in {"text", "replacement"}:
        return 2
    return 1


def _editor_visual_bounds(element: Dict[str, Any], page_height: float) -> Any:
    import fitz  # type: ignore

    rect = _editor_rect(element, page_height)
    rotation = math.radians(pdf_safe_float(element.get("rotation"), 0) % 360)
    width = abs(math.cos(rotation)) * float(rect.width) + abs(math.sin(rotation)) * float(rect.height)
    height = abs(math.sin(rotation)) * float(rect.width) + abs(math.cos(rotation)) * float(rect.height)
    return _editor_centered_rect(rect, width, height)


def _editor_rasterize_page_in_place(document: Any, page_index: int) -> None:
    """Replace visible page content while preserving the original page boxes.

    Keeping the same page dictionary retains MediaBox, a non-zero CropBox,
    UserUnit, inherited metadata and rotation. Clearing Contents/Resources and
    Annots before inserting the raster also lets `garbage=4` remove the
    unreferenced underlying text, image and graphics objects.
    """
    import fitz  # type: ignore

    page = document[page_index]
    rotation = int(page.rotation or 0) % 360
    page.set_rotation(0)
    visible_rect = fitz.Rect(page.rect)
    pixmap = page.get_pixmap(matrix=fitz.Matrix(4, 4), clip=visible_rect, alpha=False, annots=True)
    raster_png = pixmap.tobytes("png")
    empty_contents = document.get_new_xref()
    document.update_object(empty_contents, "<<>>")
    document.update_stream(empty_contents, b"")
    page.set_contents(empty_contents)
    document.xref_set_key(page.xref, "Resources", "<<>>")
    document.xref_set_key(page.xref, "Annots", "[]")
    page.insert_image(visible_rect, stream=raster_png, keep_proportion=False, overlay=True)
    page.set_rotation(rotation)


def render_editor_prepared_pdf(state: Dict[str, Any], asset_bytes_by_id: Dict[str, bytes]) -> bytes:
    """Render a derived PDF. Source bytes are never changed in place."""
    import fitz  # type: ignore

    state = validate_editor_state(json.loads(json.dumps(state, ensure_ascii=False)))
    source_docs: Dict[str, Any] = {}
    output = fitz.open()
    try:
        for page_state in sorted(state["pages"], key=lambda item: int(item.get("order") or 0)):
            asset_id = str(page_state.get("sourceAssetId") or "")
            source_page_index = int(page_state.get("sourcePageIndex") or 0)
            source_bytes = asset_bytes_by_id.get(asset_id)
            if not source_bytes:
                raise ValueError("editor_source_asset_missing")
            source_doc = source_docs.get(asset_id)
            if source_doc is None:
                source_doc = fitz.open(stream=source_bytes, filetype="pdf")
                source_docs[asset_id] = source_doc
            if source_page_index < 0 or source_page_index >= source_doc.page_count:
                raise ValueError("editor_source_page_missing")
            output.insert_pdf(source_doc, from_page=source_page_index, to_page=source_page_index, links=False, annots=True)
            rendered_page = output[-1]
            rendered_page.set_rotation(int(page_state.get("rotation") or 0) % 360)
        page_by_id = {str(item["pageId"]): item for item in state["pages"]}
        page_index_by_id = {str(item["pageId"]): index for index, item in enumerate(sorted(state["pages"], key=lambda page: int(page.get("order") or 0)))}
        elements = sorted(
            state["elements"],
            key=lambda item: (
                page_index_by_id[str(item["pageId"])],
                _editor_element_layer_rank(item),
                int(item.get("zIndex") or 0),
                str(item.get("id") or ""),
            ),
        )
        # A secure redaction must remove text, images and crossing vector paths.
        # Rasterize only affected pages in place, then redact pixels. Reusing the
        # page dictionary preserves MediaBox/CropBox/UserUnit/rotation geometry.
        for page_id, page_index in sorted(page_index_by_id.items(), key=lambda item: item[1]):
            if not any(item.get("pageId") == page_id and item.get("kind") in {"redaction", "replacement"} for item in elements):
                continue
            _editor_rasterize_page_in_place(output, page_index)
        for page_id, page_state in page_by_id.items():
            page = output[page_index_by_id[page_id]]
            page_height = pdf_safe_float(page_state.get("heightPt"), float(page.rect.height))
            redactions = [item for item in elements if item.get("pageId") == page_id and item.get("kind") in {"redaction", "replacement"}]
            for element in redactions:
                fill = _editor_color((element.get("properties") or {}).get("fill"), (0.0, 0.0, 0.0) if element.get("kind") == "redaction" else (1.0, 1.0, 1.0))
                page.add_redact_annot(_editor_rect(element, page_height), fill=fill, cross_out=False)
            if redactions:
                page.apply_redactions(images=2, graphics=0, text=0)
        for element in elements:
            kind = str(element.get("kind") or "")
            if kind in {"seal", "redaction"}:
                continue
            page_state = page_by_id[str(element["pageId"])]
            page = output[page_index_by_id[str(element["pageId"])]]
            page_height = pdf_safe_float(page_state.get("heightPt"), float(page.rect.height))
            rect = _editor_rect(element, page_height)
            props = element.get("properties") or {}
            opacity = max(0.0, min(1.0, pdf_safe_float(element.get("opacity"), 1)))
            rotation = pdf_safe_float(element.get("rotation"), 0) % 360
            # Browser SVG/CSS uses positive angles clockwise in its y-down
            # canvas. PyMuPDF Matrix uses the opposite visual direction here.
            morph = (_editor_rect_center(rect), fitz.Matrix(-rotation)) if rotation else None
            if kind in {"text", "replacement"}:
                _editor_insert_kai_text(page, element, page_height)
            elif kind == "image":
                image_asset_id = str(props.get("assetId") or props.get("asset_id") or "")
                image_data = asset_bytes_by_id.get(image_asset_id)
                if not image_data:
                    raise ValueError("editor_image_asset_missing")
                image_mime_type = "image/png" if image_data.startswith(b"\x89PNG\r\n\x1a\n") else "image/jpeg" if image_data.startswith(b"\xff\xd8\xff") else ""
                if not image_mime_type:
                    raise ValueError("editor_image_type_not_supported")
                transformed, transformed_width, transformed_height = _editor_transformed_image(
                    image_data,
                    image_mime_type,
                    float(rect.width),
                    float(rect.height),
                    rotation,
                    opacity,
                )
                page.insert_image(_editor_centered_rect(rect, transformed_width, transformed_height), stream=transformed, keep_proportion=False, overlay=True)
            elif kind == "shape":
                stroke = _editor_color(props.get("stroke"), (0.1, 0.1, 0.1))
                fill = _editor_color(props.get("fill"), (1.0, 1.0, 1.0)) if props.get("fill") not in {None, "", "transparent"} else None
                line_width = max(0.25, min(20.0, pdf_safe_float(props.get("strokeWidth"), 1)))
                if str(props.get("shapeType") or "rectangle") == "line":
                    page.draw_line(rect.tl, rect.br, color=stroke, width=line_width, morph=morph, overlay=True, stroke_opacity=opacity)
                else:
                    page.draw_rect(rect, color=stroke, fill=fill, width=line_width, morph=morph, overlay=True, stroke_opacity=opacity, fill_opacity=opacity)
            elif kind == "checkmark":
                page.insert_textbox(rect, "✓", fontsize=max(8.0, min(rect.height, pdf_safe_float(props.get("fontSize"), rect.height * 0.8))), fontname="china-t", color=_editor_color(props.get("color")), align=1, morph=morph, overlay=True, fill_opacity=opacity)
            elif kind == "highlight":
                page.draw_rect(rect, color=None, fill=_editor_color(props.get("color"), (1.0, 0.92, 0.2)), morph=morph, overlay=True, fill_opacity=min(opacity, 0.55))
        if hasattr(output, "bake"):
            output.bake(annots=True, widgets=True)
        # Forms are flattened above. Remove the catalog reference so hidden
        # /V field values cannot survive a redaction in an unused AcroForm
        # object. Derived PDFs also omit source Info/XMP metadata.
        output.xref_set_key(output.pdf_catalog(), "AcroForm", "null")
        output.set_metadata({})
        if output.xref_xml_metadata():
            output.del_xml_metadata()
        result = output.tobytes(garbage=4, deflate=True, clean=True)
        inspect_editor_pdf(result)
        return result
    finally:
        for source_doc in source_docs.values():
            source_doc.close()
        output.close()


def generate_editor_seal_preview(seal_bytes: bytes, mime_type: str) -> bytes:
    """Generate a low resolution, visibly watermarked preview; never return vault bytes."""
    import fitz  # type: ignore

    normalized_mime = str(mime_type or "").lower()
    if "webp" in normalized_mime:
        # PyMuPDF builds do not consistently decode WebP when the stream is
        # mislabeled as JPEG. Decode with Pillow, then provide a real PNG.
        from PIL import Image  # type: ignore

        converted_raster = io.BytesIO()
        with Image.open(io.BytesIO(seal_bytes)) as source_image:
            source_image.convert("RGBA").save(converted_raster, format="PNG")
        seal_bytes = converted_raster.getvalue()
        filetype = "png"
    else:
        filetype = "svg" if "svg" in normalized_mime else "png" if "png" in normalized_mime else "jpeg"
    image_doc = fitz.open(stream=seal_bytes, filetype=filetype)
    converted = fitz.open(stream=image_doc.convert_to_pdf(), filetype="pdf")
    preview_doc = fitz.open()
    try:
        source_page = converted[0]
        source_rect = source_page.rect
        scale = min(1.0, 320.0 / max(float(source_rect.width), float(source_rect.height), 1.0))
        width = max(96.0, float(source_rect.width) * scale)
        height = max(96.0, float(source_rect.height) * scale)
        page = preview_doc.new_page(width=width, height=height)
        page.show_pdf_page(page.rect, converted, 0, keep_proportion=True)
        for offset in range(-int(height), int(width) + int(height), 28):
            page.draw_line((offset, height), (offset + height, 0), color=(0.82, 0.12, 0.12), width=2.2, stroke_opacity=0.28, overlay=True)
        for y in range(18, int(height), 42):
            page.insert_text((8, y), "PREVIEW", fontsize=9, fontname="helv", color=(0.72, 0.08, 0.08), fill_opacity=0.42, overlay=True)
        pixmap = page.get_pixmap(matrix=fitz.Matrix(1, 1), alpha=True)
        return pixmap.tobytes("png")
    finally:
        preview_doc.close()
        converted.close()
        image_doc.close()


def editor_state_references_seal_file(
    state: Dict[str, Any],
    seal_id: str,
    file_id: str,
    file_sha256: str,
) -> bool:
    return any(
        isinstance(element, dict)
        and element.get("kind") == "seal"
        and str((element.get("properties") or {}).get("sealId") or (element.get("properties") or {}).get("seal_id") or "") == seal_id
        and str((element.get("properties") or {}).get("sealFileId") or (element.get("properties") or {}).get("seal_file_id") or "") == file_id
        and str((element.get("properties") or {}).get("sealFileSha256") or (element.get("properties") or {}).get("seal_file_sha256") or "") == file_sha256
        for element in state.get("elements") or []
    )


def local_editor_seal_preview(
    conn: sqlite3.Connection,
    seal_id: str,
    session: Dict[str, Any] | None,
    *,
    file_id: str = "",
    file_sha256: str = "",
    document_id: str = "",
    revision_id: str = "",
    binding_requested: bool = False,
) -> bytes:
    user = official_session_user(session)
    seal = company_seal_row(conn, seal_id)
    if str(user.get("company_id") or "") != str(seal.get("company_id") or ""):
        # Seal custodians may maintain records across the launch allowlist, but
        # the PDF editor must never disclose even a watermarked seal preview
        # outside the editor user's own company.
        raise PermissionError("editor_seal_preview_company_forbidden")
    assert_sqlite_seal_access(conn, seal_id, session)
    has_binding_value = any((file_id, file_sha256, document_id, revision_id))
    if binding_requested or has_binding_value:
        if not file_id or not file_sha256:
            raise PermissionError("editor_seal_preview_binding_required")
        has_revision_value = bool(document_id or revision_id)
        if has_revision_value and not all((document_id, revision_id)):
            raise PermissionError("editor_seal_preview_binding_required")
        if has_revision_value:
            document = official_document_row(conn, document_id)
            _editor_assert_document_access(conn, document, session, write=False)
            revision_row = conn.execute(
                "SELECT * FROM official_document_editor_revisions WHERE id = ? AND document_id = ?",
                (revision_id, document_id),
            ).fetchone()
            if not revision_row:
                raise PermissionError("editor_seal_preview_revision_forbidden")
            state = parse_json_any(revision_row["editor_state_json"], {}) or {}
            if not editor_state_references_seal_file(state, seal_id, file_id, file_sha256):
                raise PermissionError("editor_seal_preview_binding_forbidden")
            seal_file = local_official_seal_file_by_id(conn, file_id, seal_id)
        else:
            # A newly placed seal can be previewed before the autosave creates
            # its revision, but only when both immutable identifiers exactly
            # name the current version. Historical versions always require a
            # document revision reference.
            seal_file = require_current_company_seal_file(conn, seal_id)
            if str(seal_file.get("id") or "") != file_id:
                raise PermissionError("editor_seal_preview_revision_required")
        if str(seal_file.get("file_hash") or "") != file_sha256:
            raise ValueError("editor_seal_file_hash_mismatch")
    else:
        # Compatibility for callers that supplied no binding fields at all.
        # Once any binding field is present the request must pass the strict
        # branch above and can never silently fall back to current.
        seal_file = require_current_company_seal_file(conn, seal_id)
    _, data = read_file_object_bytes(conn, seal_file["file_object_id"])
    if sha256_bytes(data) != seal_file["file_hash"]:
        raise ValueError("seal_file_hash_mismatch")
    log_seal_usage(
        conn,
        action="editor_seal_preview",
        actor_id=user.get("id") or "",
        seal_id=seal_id,
        detail=f"seal_file_id={seal_file['id']};ttl={EDOC_EDITOR_PREVIEW_TTL_SECONDS};watermarked=true",
    )
    return generate_editor_seal_preview(data, seal_file.get("file_mime_type") or "image/png")


def _editor_revision_public(row: Dict[str, Any] | sqlite3.Row, locked_revision_id: str = "") -> Dict[str, Any]:
    data = row_to_dict(row) if isinstance(row, sqlite3.Row) else dict(row)
    state = parse_json_any(data.get("editor_state_json"), {}) or {}
    return {
        "document_id": data.get("document_id"),
        "revision_id": data.get("id"),
        "id": data.get("id"),
        "revisionNo": int(data.get("revision_no") or 0),
        "manifestSha256": data.get("manifest_sha256") or "",
        "schemaVersion": int(data.get("schema_version") or EDOC_EDITOR_SCHEMA_VERSION),
        "rendererVersion": data.get("renderer_version") or EDOC_EDITOR_RENDERER_VERSION,
        "status": "locked" if locked_revision_id and locked_revision_id == data.get("id") else "draft",
        "state": state,
        "editor_state": state,
        "created_at": data.get("created_at"),
    }


def _editor_latest_revision_row(conn: sqlite3.Connection, document_id: str) -> Dict[str, Any] | None:
    row = conn.execute(
        "SELECT * FROM official_document_editor_revisions WHERE document_id = ? ORDER BY revision_no DESC LIMIT 1",
        (document_id,),
    ).fetchone()
    return row_to_dict(row) if row else None


def _insert_editor_revision(
    conn: sqlite3.Connection,
    document_id: str,
    state: Dict[str, Any],
    actor: Dict[str, Any],
    parent_revision_id: str = "",
) -> Dict[str, Any]:
    latest = _editor_latest_revision_row(conn, document_id)
    revision_no = int(latest.get("revision_no") or 0) + 1 if latest else 1
    normalized = validate_editor_state(json.loads(json.dumps(state, ensure_ascii=False)))
    normalized["revisionNo"] = revision_no
    normalized["manifestSha256"] = canonical_editor_manifest(normalized)
    row = {
        "id": f"ODREV-{int(time.time() * 1000)}-{secrets.token_hex(4).upper()}",
        "document_id": document_id,
        "revision_no": revision_no,
        "parent_revision_id": parent_revision_id or (latest.get("id") if latest else None),
        "schema_version": EDOC_EDITOR_SCHEMA_VERSION,
        "editor_state_json": json.dumps(normalized, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
        "manifest_sha256": normalized["manifestSha256"],
        "renderer_version": EDOC_EDITOR_RENDERER_VERSION,
        "created_by": actor.get("id") or actor.get("email") or "system",
        "created_at": now(),
    }
    insert_row(conn, "official_document_editor_revisions", row)
    return row


def _editor_assert_document_access(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    session: Dict[str, Any] | None,
    *,
    write: bool = False,
) -> Dict[str, Any]:
    user = official_session_user(session)
    user_company_id = str(user.get("company_id") or "")
    if write:
        if user_company_id and user_company_id != str(document.get("company_id") or "") and user.get("id") != "system":
            raise PermissionError("official_editor_company_forbidden")
        metadata = parse_json_field(document.get("metadata_json"))
        if not metadata.get("pdf_editor_v2"):
            raise ValueError("editor_legacy_document_read_only")
        if not pdf_editor_v2_enabled_for_company(str(document.get("company_id") or "")):
            raise PermissionError("pdf_editor_v2_not_enabled_for_company")
        if document.get("applicant_id") != user.get("id"):
            raise PermissionError("official_editor_write_forbidden")
        if document.get("current_status") not in {"draft", "rejected"}:
            raise ValueError("editor_locked_after_submit")
    else:
        steps = official_document_steps(conn, document["id"])
        actor_snapshots = official_document_actor_snapshots(conn, document["id"])
        is_participant = canDownloadOfficialDocument(user, document, steps, actor_snapshots)
        if not is_participant:
            if (
                not user_company_id
                or user_company_id != str(document.get("company_id") or "")
            ):
                raise PermissionError("official_editor_company_forbidden")
            if not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
                raise PermissionError("official_editor_read_forbidden")
    return user


def official_editor_draft_metadata(
    payload: Dict[str, Any],
    user: Dict[str, Any],
    company: Dict[str, Any],
) -> Tuple[Dict[str, Any], Dict[str, Any] | None, str]:
    """Build the V2 document metadata without putting personal fields in logs."""
    incoming = dict(payload.get("metadata") or {}) if isinstance(payload.get("metadata"), dict) else {}
    seal_context = official_seal_approval_context(payload)
    if not seal_context:
        raise ValueError("official_seal_document_category_required")
    workflow_template_key = (
        (seal_context or {}).get("workflow_template_key")
        or payload.get("workflow_template_key")
        or "official_pdf_editor_v2"
    )
    contact = {
        "contact_owner": payload.get("contact_owner") or payload.get("handler_name") or incoming.get("contact_owner") or user.get("name") or "",
        "contact_email": payload.get("contact_email") or payload.get("contactEmail") or incoming.get("contact_email") or user.get("email") or "",
        "contact_phone": payload.get("contact_phone") or payload.get("contactPhone") or incoming.get("contact_phone") or EDOC_DEFAULT_CONTACT_PHONE,
        "contact_address": payload.get("contact_address") or payload.get("contactAddress") or incoming.get("contact_address") or user.get("company_address") or company.get("address") or "",
    }
    metadata: Dict[str, Any] = {
        **incoming,
        **contact,
        "pdf_editor_v2": True,
        "pdf_editor_v2_company_scope": True,
        "editor_schema_version": EDOC_EDITOR_SCHEMA_VERSION,
        "editor_renderer_version": EDOC_EDITOR_RENDERER_VERSION,
        "original_immutable": True,
        "formal_exchange_provider": "disabled",
        "workflow_template": workflow_template_key,
        "application_kind": payload.get("application_kind") or "uploaded_pdf_seal",
        "future_rule_inputs": {
            "company_id": str(company.get("id") or payload.get("company_id") or ""),
            "department": payload.get("applicant_department_name") or payload.get("dispatch_unit") or user.get("unit") or "",
            "document_type": payload.get("document_type") or "electronic_seal_pdf_editor_v2",
            "document_category": (seal_context or {}).get("document_category") or "",
            "approval_route_code": (seal_context or {}).get("approval_route_code") or "",
        },
    }
    if seal_context:
        metadata["official_seal"] = {
            **seal_context,
            "approval_steps": [
                {"order": step["order"], "key": step["key"], "name": step["name"], "role": step["role"]}
                for step in official_seal_workflow_steps(seal_context["approval_route_code"])
                if step["key"] != "applicant_confirm"
            ],
        }
    return metadata, seal_context, workflow_template_key


def create_official_editor_draft(conn: sqlite3.Connection, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    if not session_has_any_permission(session, ["official_documents.compose", "official_documents.all_todo"]):
        raise PermissionError("official_document_create_forbidden")
    company_id = require_official_creation_company(user, payload.get("company_id") or user.get("company_id"))
    if not launch_company_in_scope(company_id):
        raise PermissionError("company_not_in_launch_scope")
    if not pdf_editor_v2_enabled_for_company(company_id):
        raise PermissionError("pdf_editor_v2_not_enabled_for_company")
    company = official_company_row(conn, company_id)
    require_official_seal_classification(payload)
    document_id = str(payload.get("id") or f"OD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}")
    ts = now()
    metadata, seal_context, workflow_template_key = official_editor_draft_metadata(payload, user, company)
    document = {
        "id": document_id,
        "company_id": company_id,
        "document_type": payload.get("document_type") or "electronic_seal_pdf_editor_v2",
        "source_type": "uploaded_pdf",
        "title": payload.get("title") or payload.get("subject") or "電子用印 PDF 草稿",
        "subject": payload.get("subject") or payload.get("title") or "",
        "description": payload.get("description") or "",
        "method": payload.get("method") or "",
        "recipient": payload.get("recipient") or "",
        "dispatch_unit": payload.get("dispatch_unit") or user.get("unit") or "",
        "handler_name": payload.get("handler_name") or user.get("name") or "",
        "applicant_id": user["id"],
        "applicant_name": user.get("name") or user.get("email") or "",
        "applicant_department_id": payload.get("applicant_department_id") or user.get("unit") or "",
        "applicant_department_name": payload.get("applicant_department_name") or user.get("unit") or "",
        "workflow_template_key": workflow_template_key,
        "dispatch_method": official_document_dispatch_method("uploaded_pdf", payload.get("dispatch_method")),
        "requires_stamp": 1,
        "current_status": "draft",
        "current_step": "",
        "request_reason": payload.get("request_reason") or payload.get("reason") or "",
        "stamped_file_id": None,
        "metadata_json": json.dumps(metadata, ensure_ascii=False),
        "created_at": ts,
        "updated_at": ts,
    }
    insert_row(conn, "official_documents", document)
    initial_state = {
        "schemaVersion": EDOC_EDITOR_SCHEMA_VERSION,
        "revisionNo": 1,
        "sourceFiles": [],
        "pages": [],
        "elements": [],
        "manifestSha256": "",
    }
    revision = _insert_editor_revision(conn, document_id, initial_state, user)
    insert_official_log(conn, document_id, "create_editor_draft", user, f"revision_id={revision['id']};schema=2;renderer={EDOC_EDITOR_RENDERER_VERSION}")
    public_revision = _editor_revision_public(revision)
    return {"id": document_id, "document_id": document_id, "company_id": company["id"], "editor_revision": public_revision, "editor_state": public_revision["state"]}


def _validate_editor_upload_metadata(payload: Dict[str, Any]) -> Dict[str, Any]:
    asset_kind = str(payload.get("asset_kind") or payload.get("assetKind") or "source_pdf")
    if asset_kind not in EDOC_EDITOR_ALLOWED_ASSET_KINDS - {"prepared_pdf"}:
        raise ValueError("editor_asset_kind_invalid")
    file_name = Path(str(payload.get("file_name") or payload.get("fileName") or "upload")).name
    mime_type = str(payload.get("mime_type") or payload.get("mimeType") or "application/octet-stream").lower()
    size_bytes = int(pdf_safe_float(payload.get("size_bytes", payload.get("sizeBytes")), 0))
    expected_sha256 = str(payload.get("sha256") or "").upper()
    if not re.fullmatch(r"[0-9A-F]{64}", expected_sha256):
        raise ValueError("editor_upload_sha256_required")
    if size_bytes <= 0:
        raise ValueError("editor_upload_size_required")
    max_size = EDOC_EDITOR_MAX_IMAGE_SIZE_MB * 1024 * 1024 if asset_kind == "image" else EDOC_EDITOR_MAX_FILE_SIZE_MB * 1024 * 1024
    if size_bytes > max_size:
        raise ValueError("editor_image_too_large" if asset_kind == "image" else "editor_pdf_too_large")
    if asset_kind == "image":
        if mime_type not in EDOC_EDITOR_ALLOWED_IMAGE_MIME_TYPES or Path(file_name).suffix.lower() not in {".png", ".jpg", ".jpeg"}:
            raise ValueError("editor_image_type_not_supported")
    elif mime_type != "application/pdf" or Path(file_name).suffix.lower() != ".pdf":
        raise ValueError("editor_pdf_type_required")
    return {"asset_kind": asset_kind, "file_name": file_name, "mime_type": mime_type, "size_bytes": size_bytes, "expected_sha256": expected_sha256}


def create_official_editor_upload_intent(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    user = _editor_assert_document_access(conn, document, session, write=True)
    meta = _validate_editor_upload_metadata(payload)
    latest = _editor_latest_revision_row(conn, document_id)
    if not latest:
        raise ValueError("editor_revision_not_found")
    asset_id = f"ODASSET-{int(time.time() * 1000)}-{secrets.token_hex(4).upper()}"
    storage_path = f"editor/{document_id}/{asset_id}-{meta['file_name']}"
    metadata = {"base_revision_no": int(latest["revision_no"]), "expires_at": (datetime.now() + timedelta(hours=2)).isoformat(timespec="seconds")}
    row = {
        "id": asset_id,
        "document_id": document_id,
        "editor_revision_id": latest["id"],
        "asset_kind": meta["asset_kind"],
        "file_object_id": None,
        "official_file_id": None,
        "file_name": meta["file_name"],
        "mime_type": meta["mime_type"],
        "size_bytes": meta["size_bytes"],
        "sha256": "",
        "expected_sha256": meta["expected_sha256"],
        "storage_bucket": EDOC_STORAGE_BUCKET,
        "storage_path": storage_path,
        "upload_status": "pending",
        "scan_status": "pending",
        "preflight_status": "pending",
        "page_count": 0,
        "metadata_json": json.dumps(metadata, ensure_ascii=False),
        "created_by": user.get("id") or "",
        "created_at": now(),
        "finalized_at": None,
    }
    insert_row(conn, "official_document_editor_assets", row)
    return {
        "upload_id": asset_id,
        "asset_id": asset_id,
        "protocol": "local_direct",
        "method": "PUT",
        "upload_url": f"/api/official-documents/{urllib.parse.quote(document_id)}/editor-uploads/{urllib.parse.quote(asset_id)}/content",
        "headers": {"Cache-Control": "no-store"},
        "chunk_size": EDOC_EDITOR_TUS_CHUNK_SIZE,
        "expires_at": metadata["expires_at"],
    }


def _local_editor_upload_path(asset: Dict[str, Any]) -> Path:
    root = STORAGE_DIR.resolve()
    target = (STORAGE_DIR / str(asset.get("storage_path") or "")).resolve()
    if target == root or root not in target.parents:
        raise ValueError("editor_upload_path_invalid")
    return target


def _local_editor_asset_failure(
    conn: sqlite3.Connection,
    asset: Dict[str, Any],
    error_code: str,
    *,
    quarantine: bool = False,
) -> None:
    metadata = parse_json_any(asset.get("metadata_json"), {}) or {}
    # Store only a stable error code. Never persist uploaded content, PDF text,
    # storage credentials, or scanner details in the editor audit metadata.
    metadata["error_code"] = error_code
    target = _local_editor_upload_path(asset)
    if target.exists():
        target.unlink()
    conn.execute(
        """
        UPDATE official_document_editor_assets
        SET upload_status = ?, scan_status = ?, preflight_status = ?, metadata_json = ?, finalized_at = ?
        WHERE id = ?
        """,
        (
            "quarantined" if quarantine else "failed",
            "failed" if quarantine else "pending",
            "blocked" if quarantine else "failed",
            json.dumps(metadata, ensure_ascii=False),
            now(),
            asset["id"],
        ),
    )
    # The HTTP handler catches validation errors outside the sqlite context;
    # commit the terminal asset state before raising so a failed upload cannot
    # silently return to pending and be reused.
    conn.commit()


def store_official_editor_local_upload(
    conn: sqlite3.Connection,
    document_id: str,
    upload_id: str,
    data: bytes,
    session: Dict[str, Any] | None,
    content_type: str = "",
) -> Dict[str, Any]:
    """Accept a raw same-origin development upload without JSON encoding."""
    if is_production() or USE_SUPABASE:
        raise ValueError("editor_local_direct_upload_disabled")
    document = official_document_row(conn, document_id)
    _editor_assert_document_access(conn, document, session, write=True)
    row = conn.execute(
        "SELECT * FROM official_document_editor_assets WHERE id = ? AND document_id = ?",
        (upload_id, document_id),
    ).fetchone()
    if not row:
        raise ValueError("editor_upload_not_found")
    asset = row_to_dict(row)
    if asset.get("upload_status") not in {"pending", "uploading"}:
        raise ValueError("editor_upload_new_intent_required")
    metadata = parse_json_any(asset.get("metadata_json"), {}) or {}
    expires_at = str(metadata.get("expires_at") or "")
    if expires_at and datetime.fromisoformat(expires_at) < datetime.now():
        _local_editor_asset_failure(conn, asset, "editor_upload_expired")
        raise ValueError("editor_upload_expired")
    if content_type and content_type.split(";", 1)[0].strip().lower() != str(asset.get("mime_type") or "").lower():
        _local_editor_asset_failure(conn, asset, "editor_upload_content_type_mismatch")
        raise ValueError("editor_upload_content_type_mismatch")
    if len(data) != int(asset["size_bytes"]):
        _local_editor_asset_failure(conn, asset, "editor_upload_size_mismatch")
        raise ValueError("editor_upload_size_mismatch")
    digest = sha256_bytes(data)
    if digest != str(asset["expected_sha256"]).upper():
        _local_editor_asset_failure(conn, asset, "editor_upload_hash_mismatch")
        raise ValueError("editor_upload_hash_mismatch")
    encrypted, encryption_status, encryption_alg = encrypt_file_bytes(data)
    target = _local_editor_upload_path(asset)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(encrypted)
    metadata.update({
        "local_upload_encryption_status": encryption_status,
        "local_upload_encryption_alg": encryption_alg,
        "local_upload_received_at": now(),
    })
    conn.execute(
        "UPDATE official_document_editor_assets SET upload_status = 'uploaded', metadata_json = ? WHERE id = ?",
        (json.dumps(metadata, ensure_ascii=False), upload_id),
    )
    return {"ok": True, "upload_id": upload_id, "size_bytes": len(data), "sha256": digest}


def _editor_asset_public(row: Dict[str, Any] | sqlite3.Row) -> Dict[str, Any]:
    data = row_to_dict(row) if isinstance(row, sqlite3.Row) else dict(row)
    return {
        "id": data.get("id"),
        "assetId": data.get("id"),
        "documentId": data.get("document_id"),
        "revisionId": data.get("editor_revision_id"),
        "assetKind": data.get("asset_kind"),
        "fileName": data.get("file_name"),
        "mimeType": data.get("mime_type"),
        "sizeBytes": int(data.get("size_bytes") or 0),
        "sha256": data.get("sha256") or "",
        "scanStatus": data.get("scan_status"),
        "preflightStatus": data.get("preflight_status"),
        "pageCount": int(data.get("page_count") or 0),
        "officialFileId": data.get("official_file_id"),
        "finalizedAt": data.get("finalized_at"),
    }


def _editor_asset_access_token(document_id: str, asset_id: str, expires: int) -> str:
    message = f"{document_id}:{asset_id}:{expires}".encode("utf-8")
    return hmac.new(EDOC_FILE_ENCRYPTION_KEY.encode("utf-8"), message, hashlib.sha256).hexdigest()


def _editor_asset_access_url(document_id: str, asset_id: str, ttl_seconds: int = EDOC_EDITOR_PREVIEW_TTL_SECONDS) -> Dict[str, Any]:
    expires = int(time.time()) + max(30, min(ttl_seconds, 900))
    token = _editor_asset_access_token(document_id, asset_id, expires)
    return {
        "url": f"/api/official-documents/{urllib.parse.quote(document_id)}/editor-assets/{urllib.parse.quote(asset_id)}/download?expires={expires}&token={token}",
        "expiresAt": datetime.fromtimestamp(expires).isoformat(timespec="seconds"),
    }


def official_editor_file_authorized_url(document_id: str, file_id: str) -> str:
    return f"/api/official-documents/{urllib.parse.quote(document_id)}/files/{urllib.parse.quote(file_id)}/download"


def editor_page_operations(baseline_state: Dict[str, Any], current_state: Dict[str, Any]) -> Dict[str, Any]:
    """Compare page metadata only; never expose document text in audit output."""
    baseline_pages = sorted(baseline_state.get("pages") or [], key=lambda item: int(item.get("order") or 0))
    current_pages = sorted(current_state.get("pages") or [], key=lambda item: int(item.get("order") or 0))
    before = {str(page.get("pageId") or ""): (index, page) for index, page in enumerate(baseline_pages, start=1)}
    after = {str(page.get("pageId") or ""): (index, page) for index, page in enumerate(current_pages, start=1)}
    imported = [
        {"pageId": page_id, "toOrder": index}
        for page_id, (index, _page) in after.items()
        if page_id and page_id not in before
    ]
    deleted = [
        {"pageId": page_id, "fromOrder": index}
        for page_id, (index, _page) in before.items()
        if page_id and page_id not in after
    ]
    reordered = [
        {"pageId": page_id, "fromOrder": before[page_id][0], "toOrder": after[page_id][0]}
        for page_id in before.keys() & after.keys()
        if before[page_id][0] != after[page_id][0]
    ]
    rotated = [
        {
            "pageId": page_id,
            "fromRotation": int(before[page_id][1].get("rotation") or 0) % 360,
            "toRotation": int(after[page_id][1].get("rotation") or 0) % 360,
        }
        for page_id in before.keys() & after.keys()
        if int(before[page_id][1].get("rotation") or 0) % 360 != int(after[page_id][1].get("rotation") or 0) % 360
    ]
    for items in (imported, deleted, reordered, rotated):
        items.sort(key=lambda item: (int(item.get("toOrder", item.get("fromOrder", 0))), str(item.get("pageId") or "")))
    return {
        "imported": imported,
        "deleted": deleted,
        "reordered": reordered,
        "rotated": rotated,
        "total": len(imported) + len(deleted) + len(reordered) + len(rotated),
    }


def editor_by_page_summary(state: Dict[str, Any], page_operations: Dict[str, Any]) -> Tuple[Dict[str, int], List[Dict[str, Any]]]:
    counts: Dict[str, int] = {kind: 0 for kind in sorted(EDOC_EDITOR_ALLOWED_ELEMENT_KINDS)}
    by_page: Dict[str, Dict[str, Any]] = {}
    for element in state.get("elements") or []:
        kind = str(element.get("kind") or "")
        page_id = str(element.get("pageId") or "")
        counts[kind] = counts.get(kind, 0) + 1
        entry = by_page.setdefault(page_id, {"pageId": page_id, "changes": {}, "operations": []})
        entry["changes"][kind] = entry["changes"].get(kind, 0) + 1
    for operation in ("imported", "deleted", "reordered", "rotated"):
        for item in page_operations.get(operation) or []:
            page_id = str(item.get("pageId") or "")
            entry = by_page.setdefault(page_id, {"pageId": page_id, "changes": {}, "operations": []})
            if operation not in entry["operations"]:
                entry["operations"].append(operation)
    return counts, sorted(by_page.values(), key=lambda item: str(item.get("pageId") or ""))


def _validate_editor_asset_access_token(document_id: str, asset_id: str, expires: int, token: str) -> None:
    if expires < int(time.time()) or expires > int(time.time()) + 900:
        raise PermissionError("editor_asset_url_expired")
    expected = _editor_asset_access_token(document_id, asset_id, expires)
    if not token or not hmac.compare_digest(expected, token):
        raise PermissionError("editor_asset_url_invalid")


def editor_asset_access_manifest(document_id: str, state: Dict[str, Any], *, supabase_mode: bool = False) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    for item in state.get("sourceFiles") or []:
        asset_id = str(item.get("assetId") or "")
        if not asset_id:
            continue
        access = _editor_asset_access_url(document_id, asset_id)
        entries.append({"assetId": asset_id, "kind": item.get("kind"), "mimeType": item.get("mimeType"), "sha256": item.get("sha256"), **access})
    return entries


def _editor_state_with_asset(latest: Dict[str, Any], asset: Dict[str, Any], inspection: Dict[str, Any] | None) -> Dict[str, Any]:
    state = parse_json_any(latest.get("editor_state_json"), {}) or {}
    state = json.loads(json.dumps(state, ensure_ascii=False))
    source_files = list(state.get("sourceFiles") or [])
    source_files.append({
        "assetId": asset["id"],
        "kind": asset["asset_kind"],
        "fileName": asset["file_name"],
        "mimeType": asset["mime_type"],
        "sizeBytes": int(asset["size_bytes"]),
        "sha256": asset["sha256"],
    })
    state["sourceFiles"] = source_files
    pages = list(state.get("pages") or [])
    for page in (inspection or {}).get("pages") or []:
        page_id = f"PAGE-{asset['id']}-{int(page['sourcePageIndex']) + 1}"
        pages.append({
            "pageId": page_id,
            "sourceAssetId": asset["id"],
            "sourcePageIndex": int(page["sourcePageIndex"]),
            "widthPt": page["widthPt"],
            "heightPt": page["heightPt"],
            "cropBox": page["cropBox"],
            "rotation": page["rotation"],
            "order": len(pages),
        })
    state["pages"] = pages
    return state


def finalize_official_editor_upload(conn: sqlite3.Connection, document_id: str, upload_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    user = _editor_assert_document_access(conn, document, session, write=True)
    row = conn.execute("SELECT * FROM official_document_editor_assets WHERE id = ? AND document_id = ?", (upload_id, document_id)).fetchone()
    if not row:
        raise ValueError("editor_upload_not_found")
    asset = row_to_dict(row)
    if asset.get("upload_status") == "finalized":
        latest_public = get_official_editor_state(conn, document_id, session)
        return {"asset": _editor_asset_public(asset), "pages": latest_public["state"].get("pages") or [], "editor_state": latest_public["state"], "editor_revision": latest_public}
    if asset.get("upload_status") != "uploaded":
        raise ValueError("editor_upload_new_intent_required" if asset.get("upload_status") in {"failed", "quarantined"} else "editor_local_upload_incomplete")
    metadata = parse_json_any(asset.get("metadata_json"), {}) or {}
    target = _local_editor_upload_path(asset)
    if not target.exists():
        _local_editor_asset_failure(conn, asset, "editor_local_upload_missing")
        raise ValueError("editor_local_upload_missing")
    data = decrypt_file_bytes(
        target.read_bytes(),
        str(metadata.get("local_upload_encryption_status") or ""),
        str(metadata.get("local_upload_encryption_alg") or ""),
    )
    if len(data) != int(asset["size_bytes"]):
        _local_editor_asset_failure(conn, asset, "editor_upload_size_mismatch")
        raise ValueError("editor_upload_size_mismatch")
    digest = sha256_bytes(data)
    if digest != str(asset["expected_sha256"]).upper() or (payload.get("sha256") and str(payload["sha256"]).upper() != digest):
        _local_editor_asset_failure(conn, asset, "editor_upload_hash_mismatch")
        raise ValueError("editor_upload_hash_mismatch")
    latest = _editor_latest_revision_row(conn, document_id)
    if not latest or int(metadata.get("base_revision_no") or 0) != int(latest.get("revision_no") or 0):
        _local_editor_asset_failure(conn, asset, "editor_revision_conflict")
        raise ValueError("editor_revision_conflict")
    scan_status, signature = editor_scan_bytes_for_threats(data, asset["file_name"])
    if scan_status != "已通過":
        _local_editor_asset_failure(conn, asset, "editor_asset_quarantined", quarantine=True)
        raise ValueError("editor_asset_quarantined")
    try:
        inspection = inspect_editor_pdf(data) if asset["asset_kind"] in {"source_pdf", "import_pdf"} else inspect_editor_image(data, asset["mime_type"])
    except Exception:
        _local_editor_asset_failure(conn, asset, "editor_asset_preflight_failed", quarantine=True)
        raise
    file_row = store_file_object(conn, document_id, asset["file_name"], data, "official-editor", f"editor-asset-{asset['asset_kind']}", official_actor_name(user), asset["mime_type"])
    file_row = persist_file_object_scan_result(
        conn,
        file_row["id"],
        scan_status,
        signature,
        official_actor_name(user),
    )
    official_file = None
    if asset["asset_kind"] == "source_pdf":
        official_file = insert_official_document_file(conn, document_id, "original_pdf", file_row, official_actor_name(user))
    asset.update({
        "file_object_id": file_row["id"],
        "official_file_id": official_file.get("id") if official_file else None,
        "sha256": digest,
        "upload_status": "finalized",
        "scan_status": "passed",
        "preflight_status": "passed",
        "page_count": int((inspection or {}).get("pageCount") or 0),
        "metadata_json": json.dumps({**metadata, "inspection_flags": (inspection or {}).get("flags") or {}, "renderer_version": EDOC_EDITOR_RENDERER_VERSION}, ensure_ascii=False),
        "finalized_at": now(),
    })
    conn.execute(
        """
        UPDATE official_document_editor_assets
        SET file_object_id = ?, official_file_id = ?, sha256 = ?, upload_status = ?, scan_status = ?,
            preflight_status = ?, page_count = ?, metadata_json = ?, finalized_at = ?
        WHERE id = ?
        """,
        (asset["file_object_id"], asset["official_file_id"], digest, asset["upload_status"], asset["scan_status"], asset["preflight_status"], asset["page_count"], asset["metadata_json"], asset["finalized_at"], upload_id),
    )
    new_state = _editor_state_with_asset(latest, asset, inspection)
    revision = _insert_editor_revision(conn, document_id, new_state, user, latest["id"])
    conn.execute("UPDATE official_document_editor_assets SET editor_revision_id = ? WHERE id = ?", (revision["id"], upload_id))
    if target.exists():
        target.unlink()
    insert_official_log(conn, document_id, "finalize_editor_upload", user, f"asset_id={upload_id};sha256={digest};pages={asset['page_count']};scan=passed")
    public_revision = _editor_revision_public(revision)
    return {"asset": _editor_asset_public({**asset, "editor_revision_id": revision["id"]}), "pages": inspection.get("pages") if inspection else [], "editor_state": public_revision["state"], "editor_revision": public_revision}


def get_official_editor_state(conn: sqlite3.Connection, document_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    _editor_assert_document_access(conn, document, session, write=False)
    latest = _editor_latest_revision_row(conn, document_id)
    if not latest:
        raise ValueError("editor_revision_not_found")
    stamp_request = official_document_stamp_request(conn, document_id)
    public = _editor_revision_public(latest, str((stamp_request or {}).get("locked_editor_revision_id") or ""))
    if stamp_request and stamp_request.get("locked_editor_revision_id") == latest["id"]:
        public["preparedFileId"] = stamp_request.get("prepared_file_id") or ""
        public["preparedSha256"] = stamp_request.get("prepared_sha256") or ""
    prepared_asset = conn.execute(
        """
        SELECT official_file_id, sha256 FROM official_document_editor_assets
        WHERE document_id = ? AND editor_revision_id = ? AND asset_kind = 'prepared_pdf'
          AND upload_status = 'finalized' AND preflight_status = 'passed'
        ORDER BY created_at DESC LIMIT 1
        """,
        (document_id, latest["id"]),
    ).fetchone()
    if prepared_asset and prepared_asset["official_file_id"]:
        prepared_url = official_editor_file_authorized_url(document_id, prepared_asset["official_file_id"])
        public.update({
            "preparedFileId": prepared_asset["official_file_id"],
            "preparedSha256": prepared_asset["sha256"],
            "preparedUrl": prepared_url,
            "authorizedUrl": prepared_url,
        })
    public["assets"] = editor_asset_access_manifest(document_id, public["state"], supabase_mode=False)
    return public


def save_official_editor_state(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    user = _editor_assert_document_access(conn, document, session, write=True)
    latest = _editor_latest_revision_row(conn, document_id)
    if not latest:
        raise ValueError("editor_revision_not_found")
    expected_revision = int(pdf_safe_float(payload.get("revisionNo", payload.get("revision_no")), 0))
    expected_manifest = str(payload.get("baseManifestSha256") or payload.get("manifestSha256") or payload.get("manifest_sha256") or "")
    if expected_revision != int(latest["revision_no"]) or expected_manifest != latest["manifest_sha256"]:
        raise ValueError("editor_revision_conflict")
    state = payload.get("state") or payload.get("editor_state") or payload
    if not isinstance(state, dict):
        raise ValueError("editor_state_invalid")
    state = validate_editor_state(json.loads(json.dumps(state, ensure_ascii=False)))
    previous_state = parse_json_any(latest["editor_state_json"], {}) or {}
    validate_editor_seal_placements(
        conn,
        str(document.get("company_id") or ""),
        state,
        previous_state=previous_state,
    )
    revision = _insert_editor_revision(conn, document_id, state, user, latest["id"])
    insert_official_log(conn, document_id, "save_editor_revision", user, f"revision_id={revision['id']};revision_no={revision['revision_no']};manifest={revision['manifest_sha256']};elements={len((parse_json_any(revision['editor_state_json'], {}) or {}).get('elements') or [])}")
    return _editor_revision_public(revision)


def _editor_local_asset_bytes(conn: sqlite3.Connection, document_id: str, state: Dict[str, Any]) -> Tuple[Dict[str, bytes], List[Dict[str, Any]]]:
    wanted = {str(item.get("assetId") or "") for item in state.get("sourceFiles") or []}
    for element in state.get("elements") or []:
        props = element.get("properties") or {}
        if element.get("kind") == "image" and (props.get("assetId") or props.get("asset_id")):
            wanted.add(str(props.get("assetId") or props.get("asset_id")))
    assets: List[Dict[str, Any]] = []
    result: Dict[str, bytes] = {}
    for asset_id in wanted:
        row = conn.execute("SELECT * FROM official_document_editor_assets WHERE id = ? AND document_id = ?", (asset_id, document_id)).fetchone()
        if not row:
            raise ValueError("editor_source_asset_missing")
        asset = row_to_dict(row)
        if asset.get("upload_status") != "finalized" or asset.get("scan_status") != "passed" or asset.get("preflight_status") != "passed":
            raise ValueError("editor_asset_not_ready")
        if not asset.get("file_object_id"):
            raise ValueError("editor_asset_file_missing")
        _, data = read_file_object_bytes(conn, asset["file_object_id"])
        if sha256_bytes(data) != asset["sha256"]:
            raise ValueError("editor_asset_hash_mismatch")
        result[asset_id] = data
        assets.append(asset)
    return result, assets


def preflight_official_editor(conn: sqlite3.Connection, document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    user = _editor_assert_document_access(conn, document, session, write=True)
    latest = _editor_latest_revision_row(conn, document_id)
    if not latest:
        raise ValueError("editor_revision_not_found")
    revision_id = str(payload.get("editorRevisionId") or payload.get("revision_id") or latest["id"])
    manifest = str(payload.get("manifestSha256") or payload.get("manifest_sha256") or latest["manifest_sha256"])
    if revision_id != latest["id"] or manifest != latest["manifest_sha256"]:
        raise ValueError("editor_revision_conflict")
    state = parse_json_any(latest["editor_state_json"], {}) or {}
    if not state.get("pages"):
        raise ValueError("editor_source_pdf_required")
    assert_official_document_uploads_av_clean(conn, document)
    state_before_binding = canonical_json_hash(state)
    validate_editor_seal_placements(
        conn,
        str(document.get("company_id") or ""),
        state,
        previous_state=state,
    )
    if canonical_json_hash(state) != state_before_binding:
        latest = _insert_editor_revision(conn, document_id, state, user, latest["id"])
        state = parse_json_any(latest["editor_state_json"], {}) or {}
        revision_id = latest["id"]
        manifest = latest["manifest_sha256"]
        insert_official_log(
            conn,
            document_id,
            "bind_editor_seal_versions",
            user,
            f"revision_id={revision_id};manifest={manifest};seal_versions=immutable",
        )
    asset_bytes, assets = _editor_local_asset_bytes(conn, document_id, state)
    prepared = render_editor_prepared_pdf(state, asset_bytes)
    prepared_sha256 = sha256_bytes(prepared)
    prepared_file = store_official_pdf_file(conn, document_id, "prepared_pdf", f"{document_id}-prepared-r{latest['revision_no']}.pdf", prepared, official_actor_name(user))
    prepared_asset = {
        "id": f"ODASSET-{int(time.time() * 1000)}-{secrets.token_hex(4).upper()}",
        "document_id": document_id,
        "editor_revision_id": latest["id"],
        "asset_kind": "prepared_pdf",
        "file_object_id": prepared_file.get("file_object_id"),
        "official_file_id": prepared_file["id"],
        "file_name": prepared_file["file_name"],
        "mime_type": "application/pdf",
        "size_bytes": len(prepared),
        "sha256": prepared_sha256,
        "expected_sha256": prepared_sha256,
        "storage_bucket": EDOC_STORAGE_BUCKET,
        "storage_path": prepared_file.get("file_storage_key") or "",
        "upload_status": "finalized",
        "scan_status": "passed",
        "preflight_status": "passed",
        "page_count": len(state.get("pages") or []),
        "metadata_json": json.dumps({"source_asset_hashes": sorted(asset["sha256"] for asset in assets), "manifest_sha256": manifest, "element_count": len(state.get("elements") or []), "renderer_version": EDOC_EDITOR_RENDERER_VERSION}, ensure_ascii=False),
        "created_by": user.get("id") or "",
        "created_at": now(),
        "finalized_at": now(),
    }
    insert_row(conn, "official_document_editor_assets", prepared_asset)
    insert_official_log(conn, document_id, "editor_preflight", user, f"revision_id={latest['id']};manifest={manifest};prepared_file_id={prepared_file['id']};prepared_sha256={prepared_sha256};pages={prepared_asset['page_count']};elements={len(state.get('elements') or [])};renderer={EDOC_EDITOR_RENDERER_VERSION}", file_id=prepared_file["id"])
    prepared_url = official_editor_file_authorized_url(document_id, prepared_file["id"])
    return {
        "status": "prepared",
        "documentId": document_id,
        "editorRevisionId": latest["id"],
        "revisionNo": int(latest["revision_no"]),
        "manifestSha256": manifest,
        "preparedFileId": prepared_file["id"],
        "preparedSha256": prepared_sha256,
        "preparedUrl": prepared_url,
        "authorizedUrl": prepared_url,
        "rendererVersion": EDOC_EDITOR_RENDERER_VERSION,
        "pageCount": prepared_asset["page_count"],
        "revision": _editor_revision_public(latest),
    }


def official_editor_change_summary(conn: sqlite3.Connection, document_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    document = official_document_row(conn, document_id)
    _editor_assert_document_access(conn, document, session, write=False)
    stamp_request = official_document_stamp_request(conn, document_id)
    locked_revision_id = str((stamp_request or {}).get("locked_editor_revision_id") or "")
    if locked_revision_id:
        revision_row = conn.execute("SELECT * FROM official_document_editor_revisions WHERE id = ? AND document_id = ?", (locked_revision_id, document_id)).fetchone()
        revision = row_to_dict(revision_row) if revision_row else None
    else:
        revision = _editor_latest_revision_row(conn, document_id)
    if not revision:
        raise ValueError("editor_revision_not_found")
    state = parse_json_any(revision["editor_state_json"], {}) or {}
    baseline_state: Dict[str, Any] = {"pages": []}
    for baseline_row in conn.execute(
        "SELECT editor_state_json FROM official_document_editor_revisions WHERE document_id = ? ORDER BY revision_no",
        (document_id,),
    ).fetchall():
        candidate = parse_json_any(baseline_row["editor_state_json"], {}) or {}
        if candidate.get("pages"):
            baseline_state = candidate
            break
    page_operations = editor_page_operations(baseline_state, state)
    counts, by_page = editor_by_page_summary(state, page_operations)
    original = next((item for item in official_document_files(conn, document_id) if item.get("file_type") == "original_pdf"), None)
    prepared = next((item for item in official_document_files(conn, document_id) if item.get("id") == (stamp_request or {}).get("prepared_file_id")), None)
    if not prepared:
        prepared = next((item for item in official_document_files(conn, document_id) if item.get("file_type") == "prepared_pdf"), None)
    if original:
        original_url = official_editor_file_authorized_url(document_id, original["id"])
        original = {**original, "authorizedUrl": original_url}
    if prepared:
        prepared_url = official_editor_file_authorized_url(document_id, prepared["id"])
        prepared = {**prepared, "preparedUrl": prepared_url, "authorizedUrl": prepared_url}
    return {
        "documentId": document_id,
        "original": original,
        "prepared": prepared,
        "revision": _editor_revision_public(revision, locked_revision_id),
        "changes": {
            "total": len(state.get("elements") or []),
            "byKind": counts,
            "byPage": by_page,
            "pageOperations": page_operations,
            "pageOrder": [item.get("pageId") for item in sorted(state.get("pages") or [], key=lambda page: int(page.get("order") or 0))],
        },
    }


def _editor_source_bundle_sha256(conn: sqlite3.Connection, document_id: str, state: Dict[str, Any]) -> str:
    rows: List[Dict[str, str]] = []
    for item in state.get("sourceFiles") or []:
        asset_id = str(item.get("assetId") or "")
        row = conn.execute("SELECT id, sha256 FROM official_document_editor_assets WHERE id = ? AND document_id = ? AND upload_status = 'finalized'", (asset_id, document_id)).fetchone()
        if not row or not row["sha256"]:
            raise ValueError("editor_source_asset_missing")
        rows.append({"assetId": row["id"], "sha256": row["sha256"]})
    return sha256_bytes(json.dumps(sorted(rows, key=lambda item: item["assetId"]), sort_keys=True, separators=(",", ":")).encode("utf-8"))


def lock_official_editor_submission(conn: sqlite3.Connection, document: Dict[str, Any], payload: Dict[str, Any], user: Dict[str, Any]) -> Dict[str, Any]:
    metadata = parse_json_field(document.get("metadata_json"))
    if not metadata.get("pdf_editor_v2"):
        return {}
    revision_id = str(payload.get("editorRevisionId") or "")
    manifest = str(payload.get("manifestSha256") or "")
    prepared_file_id = str(payload.get("preparedFileId") or "")
    prepared_sha256 = str(payload.get("preparedSha256") or "")
    if not all((revision_id, manifest, prepared_file_id, prepared_sha256)):
        raise ValueError("editor_preflight_fields_required")
    latest = _editor_latest_revision_row(conn, document["id"])
    if not latest or latest["id"] != revision_id or latest["manifest_sha256"] != manifest:
        raise ValueError("editor_revision_conflict")
    prepared_row = conn.execute("SELECT * FROM official_document_files WHERE id = ? AND document_id = ? AND file_type = 'prepared_pdf'", (prepared_file_id, document["id"])).fetchone()
    if not prepared_row:
        raise ValueError("editor_prepared_file_not_found")
    prepared_file = row_to_dict(prepared_row)
    if prepared_file["file_hash"] != prepared_sha256 or not prepared_file.get("file_object_id"):
        raise ValueError("editor_prepared_hash_mismatch")
    _, prepared_bytes = read_file_object_bytes(conn, prepared_file["file_object_id"])
    if sha256_bytes(prepared_bytes) != prepared_sha256:
        raise ValueError("editor_prepared_hash_mismatch")
    asset_row = conn.execute(
        """
        SELECT * FROM official_document_editor_assets
        WHERE document_id = ? AND editor_revision_id = ? AND asset_kind = 'prepared_pdf'
          AND official_file_id = ? AND sha256 = ? AND preflight_status = 'passed'
        ORDER BY created_at DESC LIMIT 1
        """,
        (document["id"], revision_id, prepared_file_id, prepared_sha256),
    ).fetchone()
    if not asset_row:
        raise ValueError("editor_preflight_not_completed")
    state = parse_json_any(latest["editor_state_json"], {}) or {}
    validate_editor_seal_placements(
        conn,
        str(document.get("company_id") or ""),
        state,
        bind_missing=False,
        previous_state=state,
    )
    source_sha256 = _editor_source_bundle_sha256(conn, document["id"], state)
    ordered_pages = sorted(state.get("pages") or [], key=lambda item: int(item.get("order") or 0))
    page_numbers = {str(item.get("pageId") or ""): index for index, item in enumerate(ordered_pages, start=1)}
    positions: List[Dict[str, Any]] = []
    for index, element in enumerate(sorted([item for item in state.get("elements") or [] if item.get("kind") == "seal"], key=lambda item: int(item.get("zIndex") or 0)), start=1):
        props = element.get("properties") or {}
        seal_id = str(props.get("sealId") or props.get("seal_id") or element.get("sealId") or "")
        if not seal_id:
            raise ValueError("editor_seal_id_required")
        seal, seal_file, profile = local_editor_seal_file_context(
            conn,
            str(document.get("company_id") or ""),
            element,
            bind_missing=False,
            require_current_selection=False,
        )
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"), element.get("width"), element.get("height"),
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
        )
        positions.append({
            "seal_id": seal_id,
            "page": page_numbers.get(str(element.get("pageId") or ""), 0),
            "page_ref": str(element.get("pageId") or ""),
            "x": element.get("x"),
            "y": element.get("y"),
            "width": width,
            "height": height,
            "rotation": element.get("rotation") or 0,
            "opacity": element.get("opacity") if element.get("opacity") is not None else 1,
            "z_index": element.get("zIndex") or index,
            "locked_seal_file_id": seal_file["id"],
            "locked_seal_sha256": seal_file["file_hash"],
            "locked_render_width_pt": profile["width_pt"],
            "locked_render_height_pt": profile["height_pt"],
            "locked_dimension_policy_version": profile["dimension_policy_version"],
            "order_index": index,
        })
    if bool(document.get("requires_stamp", 1)) and not positions:
        raise ValueError("editor_seal_position_required")
    stamp_request = official_document_stamp_request(conn, document["id"])
    first = positions[0] if positions else {"seal_id": "", "page": 1, "x": 0, "y": 0, "width": 1, "height": 1}
    timestamp = now()
    if stamp_request:
        conn.execute(
            """
            UPDATE official_document_stamp_requests
            SET seal_id = ?, stamp_page = ?, stamp_x = ?, stamp_y = ?, stamp_width = ?, stamp_height = ?,
                locked_editor_revision_id = ?, locked_source_sha256 = ?, prepared_file_id = ?, prepared_sha256 = ?,
                editor_manifest_sha256 = ?, editor_schema_version = ?, renderer_version = ?, editor_locked_at = ?,
                status = 'pending', error_message = '', updated_at = ?
            WHERE id = ?
            """,
            (first["seal_id"], first["page"], first["x"], first["y"], first["width"], first["height"], revision_id, source_sha256, prepared_file_id, prepared_sha256, manifest, EDOC_EDITOR_SCHEMA_VERSION, EDOC_EDITOR_RENDERER_VERSION, timestamp, timestamp, stamp_request["id"]),
        )
        request_id = stamp_request["id"]
    else:
        request_id = f"ODSTAMP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
        insert_row(conn, "official_document_stamp_requests", {
            "id": request_id,
            "document_id": document["id"],
            "company_id": document["company_id"],
            "seal_id": first["seal_id"],
            "requested_by": user.get("id") or "",
            "stamp_page": first["page"],
            "stamp_x": first["x"],
            "stamp_y": first["y"],
            "stamp_width": first["width"],
            "stamp_height": first["height"],
            "status": "pending",
            "stamped_file_id": None,
            "locked_editor_revision_id": revision_id,
            "locked_source_sha256": source_sha256,
            "prepared_file_id": prepared_file_id,
            "prepared_sha256": prepared_sha256,
            "editor_manifest_sha256": manifest,
            "editor_schema_version": EDOC_EDITOR_SCHEMA_VERSION,
            "renderer_version": EDOC_EDITOR_RENDERER_VERSION,
            "editor_locked_at": timestamp,
            "error_message": "",
            "created_at": timestamp,
            "stamped_at": "",
            "updated_at": timestamp,
        })
    replace_official_stamp_positions(
        conn,
        request_id,
        first["seal_id"],
        {"stamp_positions": positions},
        allow_persisted_bindings=True,
    )
    insert_official_log(conn, document["id"], "lock_editor_revision", user, f"revision_id={revision_id};manifest={manifest};source_sha256={source_sha256};prepared_file_id={prepared_file_id};prepared_sha256={prepared_sha256};seal_positions={len(positions)};renderer={EDOC_EDITOR_RENDERER_VERSION}", file_id=prepared_file_id)
    return {"revision_id": revision_id, "manifest_sha256": manifest, "source_sha256": source_sha256, "prepared_file_id": prepared_file_id, "prepared_sha256": prepared_sha256, "seal_positions": len(positions)}


def clone_official_editor_revision_after_reject(conn: sqlite3.Connection, document_id: str, actor: Dict[str, Any]) -> Dict[str, Any] | None:
    stamp_request = official_document_stamp_request(conn, document_id)
    revision_id = str((stamp_request or {}).get("locked_editor_revision_id") or "")
    if not revision_id:
        return None
    source_row = conn.execute("SELECT * FROM official_document_editor_revisions WHERE id = ? AND document_id = ?", (revision_id, document_id)).fetchone()
    if not source_row:
        raise ValueError("editor_locked_revision_missing")
    source = row_to_dict(source_row)
    state = parse_json_any(source["editor_state_json"], {}) or {}
    clone = _insert_editor_revision(conn, document_id, state, actor, source["id"])
    insert_official_log(conn, document_id, "clone_editor_revision_after_reject", actor, f"source_revision_id={source['id']};new_revision_id={clone['id']};old_approvals=void;restart_from_first_step=true")
    return _editor_revision_public(clone)


def inbound_document_attachments(conn: sqlite3.Connection, inbound_id: str) -> List[Dict[str, Any]]:
    rows = conn.execute(
        "SELECT * FROM inbound_document_attachments WHERE inbound_document_id = ? ORDER BY created_at DESC",
        (inbound_id,),
    ).fetchall()
    return [row_to_dict(row) for row in rows]


def inbound_document_detail(
    conn: sqlite3.Connection,
    inbound_id: str,
    session: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM inbound_documents WHERE id = ?", (inbound_id,)).fetchone()
    if not row:
        raise ValueError("inbound_document_not_found")
    data = row_to_dict(row)
    if session is not None and not can_access_inbound_document(conn, data, session):
        raise PermissionError("inbound_document_view_forbidden")
    data["metadata"] = parse_json_field(data.get("metadata_json"))
    data["attachments"] = inbound_document_attachments(conn, inbound_id)
    return data


def can_access_inbound_document(
    conn: sqlite3.Connection,
    document: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> bool:
    user = session.get("user") if session else None
    if not user:
        return False
    if session_has_any_permission(
        session,
        ["official_documents.all_records", "official_documents.all_todo", "official_documents.receive"],
    ):
        return True
    if user.get("id") in {document.get("created_by"), document.get("assignee_user_id")}:
        return True
    linked = conn.execute(
        """
        SELECT 1
        FROM internal_dispatches dispatch
        JOIN internal_dispatch_recipients recipient ON recipient.dispatch_id = dispatch.id
        WHERE dispatch.inbound_document_id = ?
          AND recipient.recipient_user_id = ?
        LIMIT 1
        """,
        (document.get("id"), user.get("id")),
    ).fetchone()
    return bool(linked)


def inbound_document_download_attachment(
    conn: sqlite3.Connection,
    inbound_id: str,
    attachment_id: str,
    session: Dict[str, Any] | None,
    ip_address: str = "",
    user_agent: str = "",
) -> Tuple[Dict[str, Any], Dict[str, Any], bytes]:
    user = official_session_user(session)
    document = inbound_document_detail(conn, inbound_id)
    if not can_access_inbound_document(conn, document, session):
        raise PermissionError("inbound_attachment_download_forbidden")
    row = conn.execute(
        "SELECT * FROM inbound_document_attachments WHERE id = ? AND inbound_document_id = ?",
        (attachment_id, inbound_id),
    ).fetchone()
    if not row:
        raise ValueError("inbound_attachment_not_found")
    attachment = row_to_dict(row)
    if not attachment.get("file_object_id"):
        raise ValueError("inbound_attachment_file_missing")
    file_object, data = read_file_object_bytes(conn, attachment["file_object_id"])
    log_audit(
        conn,
        official_actor_name(user),
        "download_inbound_attachment",
        "inbound_documents",
        inbound_id,
        f"attachment_id={attachment_id}",
        event_type="sensitive_access",
        module_code="official_documents",
    )
    record_file_access(
        conn,
        file_object_id=attachment["file_object_id"],
        document_id=inbound_id,
        actor=official_actor_name(user),
        action="收錄附件下載",
        result="成功",
        detail=f"attachment_id={attachment_id};ip={ip_address};device={user_agent[:120]}",
    )
    return document, {**attachment, "object": file_object}, data


def list_inbound_documents(conn: sqlite3.Connection, query: Dict[str, List[str]] | None, session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    user = official_session_user(session)
    where: List[str] = []
    params: List[Any] = []
    query = query or {}
    if query.get("status"):
        where.append("status = ?")
        params.append(query["status"][0])
    if query.get("assignee_user_id"):
        where.append("assignee_user_id = ?")
        params.append(query["assignee_user_id"][0])
    if not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo", "official_documents.receive"]):
        where.append(
            """
            (
              assignee_user_id = ?
              OR created_by = ?
              OR EXISTS (
                SELECT 1
                FROM internal_dispatches dispatch
                JOIN internal_dispatch_recipients recipient ON recipient.dispatch_id = dispatch.id
                WHERE dispatch.inbound_document_id = inbound_documents.id
                  AND recipient.recipient_user_id = ?
              )
            )
            """
        )
        params.extend([user.get("id"), user.get("id"), user.get("id")])
    sql = "SELECT * FROM inbound_documents"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY created_at DESC LIMIT 300"
    return [inbound_document_detail(conn, row["id"]) for row in conn.execute(sql, params).fetchall()]


def create_inbound_document(conn: sqlite3.Connection, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    source_type = (payload.get("source_type") or "manual").strip()
    if not can_create_inbound_archive(session, source_type):
        raise PermissionError("inbound_archive_create_forbidden")
    inbound_id = payload.get("id") or f"INB-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    receive_no = payload.get("receive_no") or payload.get("receiveNo") or f"收文字第{datetime.now().strftime('%Y%m%d%H%M%S')}"
    row = {
        "id": inbound_id,
        "receive_no": receive_no,
        "source_type": source_type,
        "external_exchange_id": payload.get("external_exchange_id") or payload.get("exchange_id") or "",
        "sender_name": payload.get("sender_name") or payload.get("agency_name") or "未指定來文單位",
        "sender_contact": payload.get("sender_contact") or "",
        "subject": payload.get("subject") or "未命名收文",
        "body": payload.get("body") or payload.get("description") or "",
        "recipient_department_id": payload.get("recipient_department_id") or "",
        "recipient_department_name": payload.get("recipient_department_name") or payload.get("department") or user.get("unit") or "",
        "assignee_user_id": payload.get("assignee_user_id") or "",
        "assignee_name": payload.get("assignee_name") or "",
        "due_at": payload.get("due_at") or "",
        "priority": payload.get("priority") or "普通件",
        "security_level": payload.get("security_level") or "普通",
        "status": payload.get("status") or "registered",
        "metadata_json": payload.get("metadata") or {},
        "created_by": user.get("id") or "",
        "created_at": now(),
        "updated_at": now(),
        "closed_at": "",
    }
    insert_row(conn, "inbound_documents", row)
    log_audit(conn, official_actor_name(user), "register_inbound_document", "inbound_documents", inbound_id, row["subject"], event_type="submit", module_code="official_documents")
    if payload.get("content_base64"):
        upload_inbound_attachment(conn, inbound_id, payload, session)
    return inbound_document_detail(conn, inbound_id)


def assign_inbound_document(conn: sqlite3.Connection, inbound_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    inbound_document_detail(conn, inbound_id)
    assignee_id = payload.get("assignee_user_id") or payload.get("user_id") or ""
    assignee = active_user_by_id(conn, assignee_id) if assignee_id else None
    update = {
        "recipient_department_id": payload.get("recipient_department_id") or payload.get("department_id") or "",
        "recipient_department_name": payload.get("recipient_department_name") or payload.get("department") or (assignee.get("unit") if assignee else ""),
        "assignee_user_id": assignee_id,
        "assignee_name": payload.get("assignee_name") or (assignee.get("name") if assignee else ""),
        "due_at": payload.get("due_at") or "",
        "status": payload.get("status") or "assigned",
        "updated_at": now(),
    }
    conn.execute(
        """
        UPDATE inbound_documents
        SET recipient_department_id = ?, recipient_department_name = ?, assignee_user_id = ?, assignee_name = ?,
            due_at = ?, status = ?, updated_at = ?
        WHERE id = ?
        """,
        (update["recipient_department_id"], update["recipient_department_name"], update["assignee_user_id"], update["assignee_name"], update["due_at"], update["status"], update["updated_at"], inbound_id),
    )
    log_audit(conn, official_actor_name(user), "assign_inbound_document", "inbound_documents", inbound_id, json.dumps(update, ensure_ascii=False), event_type="assign", module_code="official_documents")
    if assignee:
        create_and_deliver_notification(conn, {
            "type": "收文分派",
            "title": f"{inbound_id} 已分派給你",
            **exact_notification_target_payload(assignee, user.get("company_id") or ""),
            "source": inbound_id,
            "body": payload.get("note") or "請於期限內處理收文。",
        })
    return inbound_document_detail(conn, inbound_id)


def upload_inbound_attachment(conn: sqlite3.Connection, inbound_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    document = inbound_document_detail(conn, inbound_id)
    if not can_access_inbound_document(conn, document, session):
        raise PermissionError("inbound_attachment_upload_forbidden")
    content = payload.get("content_base64") or payload.get("file_content_base64") or ""
    if not content:
        raise ValueError("inbound_attachment_required")
    data = base64.b64decode(content)
    if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
        raise ValueError("inbound_attachment_too_large")
    file_name = Path(payload.get("file_name") or "inbound-attachment.pdf").name
    mime_type = payload.get("file_mime_type") or payload.get("mime_type") or "application/pdf"
    file_row = store_file_object(conn, inbound_id, file_name, data, "inbound-documents", "inbound-attachment", official_actor_name(user))
    conn.execute("UPDATE file_objects SET mime_type = ? WHERE id = ?", (mime_type, file_row["id"]))
    row = {
        "id": f"INBATT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "inbound_document_id": inbound_id,
        "file_object_id": file_row["id"],
        "file_name": file_name,
        "file_mime_type": mime_type,
        "file_size": len(data),
        "file_hash": file_row["sha256"],
        "attachment_type": payload.get("attachment_type") or "inbound_attachment",
        "uploaded_by": user.get("id") or "",
        "created_at": now(),
    }
    insert_row(conn, "inbound_document_attachments", row)
    log_audit(conn, official_actor_name(user), "upload_inbound_attachment", "inbound_documents", inbound_id, row["file_hash"], event_type="sensitive_access", module_code="official_documents")
    return {"inbound_document": inbound_document_detail(conn, inbound_id), "attachment": row}


def launch_smoke_inbound_assignee(conn: sqlite3.Connection) -> Dict[str, Any]:
    for role in ("業務助理", "員工", "主管"):
        try:
            user = active_user_by_role(conn, role)
        except ValueError:
            user = None
        if user:
            return user
    raise ValueError("launch_smoke_inbound_assignee_required")


def create_inbound_assignment_launch_smoke(
    conn: sqlite3.Connection,
    payload: Dict[str, Any] | None,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    payload = payload or {}
    user = official_session_user(session)
    if not session_has_any_permission(session, ["official_documents.receive", "official_documents.all_todo", "official_documents.all_records"]):
        raise PermissionError("inbound_launch_smoke_forbidden")
    assignee = active_user_by_id(conn, payload.get("assignee_user_id") or "") if payload.get("assignee_user_id") else launch_smoke_inbound_assignee(conn)
    package = build_launch_inbound_smoke_pdf()
    date_compact = datetime.now().strftime("%Y%m%d")
    suffix = secrets.token_hex(3).upper()
    inbound = create_inbound_document(
        conn,
        {
            "receive_no": payload.get("receive_no") or f"收測字第{date_compact}{suffix}號",
            "source_type": "manual",
            "external_exchange_id": payload.get("external_exchange_id") or f"MANUAL-SMOKE-{date_compact}-{suffix}",
            "sender_name": "去識別化來文機關",
            "sender_contact": "contact@example.invalid",
            "subject": "去識別化收文登錄與分派走測",
            "body": "本筆收文僅供下週一內部正式上線走測，確認收文登錄、附件、承辦分派、辦理期限與 audit log。",
            "priority": "普通件",
            "security_level": "普通",
            "metadata": {
                "source": "backend_launch_smoke_test",
                "journey": "inbound_assignment",
                "contains_personal_data": False,
                "contains_official_exchange_payload": False,
            },
            "file_name": package["file_name"],
            "file_mime_type": package["mime_type"],
            "content_base64": base64.b64encode(package["data"]).decode("ascii"),
            "ip_address": payload.get("ip_address") or "",
            "user_agent": payload.get("user_agent") or "",
        },
        session,
    )
    due_at = payload.get("due_at") or f"{(datetime.now() + timedelta(days=3)).strftime('%Y-%m-%d')} 18:00:00"
    assigned = assign_inbound_document(
        conn,
        inbound["id"],
        {
            "assignee_user_id": assignee["id"],
            "assignee_name": assignee.get("name") or "",
            "recipient_department_name": payload.get("recipient_department_name") or assignee.get("unit") or "總管理處",
            "due_at": due_at,
            "note": "去識別化走測：已由後端建立收文並分派承辦與期限。",
        },
        session,
    )
    log_audit(
        conn,
        official_actor_name(user),
        "launch_smoke_inbound_assignment",
        "inbound_documents",
        assigned["id"],
        f"assignee={assignee['id']} due_at={due_at}",
        event_type="launch_smoke",
        module_code="official_documents",
    )
    return {
        "ok": True,
        "journey": "inbound_assignment",
        "inbound_document": assigned,
        "assignee": public_user(assignee),
        "next_action": "請承辦人回到收文管理查看附件、期限與後續辦理狀態。",
    }


def close_inbound_document(conn: sqlite3.Connection, inbound_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    inbound_document_detail(conn, inbound_id)
    conn.execute("UPDATE inbound_documents SET status = 'closed', closed_at = ?, updated_at = ? WHERE id = ?", (now(), now(), inbound_id))
    log_audit(conn, official_actor_name(user), "close_inbound_document", "inbound_documents", inbound_id, payload.get("comment") or "收文結案", event_type="approve", module_code="official_documents")
    return inbound_document_detail(conn, inbound_id)


def internal_dispatch_log(conn: sqlite3.Connection, dispatch_id: str, user: Dict[str, Any] | None, action: str, detail: str = "", payload: Dict[str, Any] | None = None) -> Dict[str, Any]:
    row = {
        "id": f"IDLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "dispatch_id": dispatch_id,
        "actor_id": user.get("id") if user else "system",
        "action": action,
        "detail": detail,
        "ip_address": (payload or {}).get("ip_address") or "",
        "user_agent": ((payload or {}).get("user_agent") or "")[:180],
        "created_at": now(),
    }
    insert_row(conn, "internal_dispatch_logs", row)
    log_audit(conn, official_actor_name(user), action, "internal_dispatches", dispatch_id, detail, event_type="submit", module_code="official_documents")
    return row


def internal_dispatch_detail(conn: sqlite3.Connection, dispatch_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM internal_dispatches WHERE id = ?", (dispatch_id,)).fetchone()
    if not row:
        raise ValueError("internal_dispatch_not_found")
    data = row_to_dict(row)
    recipients = [row_to_dict(item) for item in conn.execute("SELECT * FROM internal_dispatch_recipients WHERE dispatch_id = ? ORDER BY created_at", (dispatch_id,)).fetchall()]
    if session is not None:
        user = official_session_user(session)
        allowed = (
            data.get("sender_user_id") == user.get("id")
            or any(item.get("recipient_user_id") == user.get("id") for item in recipients)
            or session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"])
        )
        if not allowed:
            raise PermissionError("internal_dispatch_view_forbidden")
    replies = [row_to_dict(item) for item in conn.execute("SELECT * FROM internal_dispatch_replies WHERE dispatch_id = ? ORDER BY created_at DESC", (dispatch_id,)).fetchall()]
    for reply in replies:
        reply["attachment"] = None
        if reply.get("attachment_file_id"):
            attachment = conn.execute(
                "SELECT id, file_name, mime_type, size_bytes, sha256, scan_status FROM file_objects WHERE id = ?",
                (reply["attachment_file_id"],),
            ).fetchone()
            if attachment:
                reply["attachment"] = {
                    "attachment_file_id": attachment["id"],
                    "file_name": attachment["file_name"],
                    "mime_type": attachment["mime_type"],
                    "file_size": int(attachment["size_bytes"] or 0),
                    "sha256": attachment["sha256"],
                    "scan_status": attachment["scan_status"],
                }
    logs = [row_to_dict(item) for item in conn.execute("SELECT * FROM internal_dispatch_logs WHERE dispatch_id = ? ORDER BY created_at DESC", (dispatch_id,)).fetchall()]
    data["metadata"] = parse_json_field(data.get("metadata_json"))
    data["recipients"] = recipients
    data["replies"] = replies
    data["logs"] = logs
    data["inbound_document"] = inbound_document_detail(conn, data["inbound_document_id"]) if data.get("inbound_document_id") else None
    return data


def internal_dispatch_recipient_directory(conn: sqlite3.Connection, session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    require_internal_dispatch_creator(session)
    rows = conn.execute(
        "SELECT id, name, unit, role FROM users WHERE status = '啟用' ORDER BY unit, name"
    ).fetchall()
    return [
        {"id": row["id"], "name": row["name"], "unit": row["unit"], "role": row["role"]}
        for row in rows
    ]


def list_internal_dispatches(conn: sqlite3.Connection, query: Dict[str, List[str]] | None, session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    user = official_session_user(session)
    query = query or {}
    where: List[str] = []
    params: List[Any] = []
    if query.get("status"):
        where.append("d.status = ?")
        params.append(query["status"][0])
    if not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
        where.append("(d.sender_user_id = ? OR EXISTS (SELECT 1 FROM internal_dispatch_recipients r WHERE r.dispatch_id = d.id AND r.recipient_user_id = ?))")
        params.extend([user.get("id"), user.get("id")])
    sql = "SELECT d.* FROM internal_dispatches d"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY d.created_at DESC LIMIT 300"
    return [internal_dispatch_detail(conn, row["id"], session) for row in conn.execute(sql, params).fetchall()]


def create_internal_dispatch(conn: sqlite3.Connection, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = require_internal_dispatch_creator(session)
    recipients = payload.get("recipients") or []
    if not isinstance(recipients, list) or not recipients:
        raise ValueError("internal_dispatch_recipients_required")
    if not all(isinstance(recipient, dict) for recipient in recipients):
        raise ValueError("invalid_internal_dispatch_recipient")
    default_action_required = bool(payload.get("reply_required", False))
    recipient_actions = [bool(recipient.get("action_required", default_action_required)) for recipient in recipients]
    dispatch_id = payload.get("id") or f"IDISP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    inbound_document_id = payload.get("inbound_document_id") or ""
    if inbound_document_id:
        inbound_document_detail(conn, inbound_document_id)
    reply_required = any(recipient_actions)
    due_days = int(pdf_safe_float(payload.get("reply_due_days"), 0)) if reply_required else 0
    due_at = payload.get("due_at") or ((datetime.now() + timedelta(days=due_days)).strftime("%Y-%m-%d %H:%M:%S") if due_days else "")
    row = {
        "id": dispatch_id,
        "official_document_id": payload.get("official_document_id") or payload.get("document_id") or None,
        "inbound_document_id": inbound_document_id or None,
        "title": payload.get("title") or payload.get("subject") or "內部派文",
        "subject": payload.get("subject") or payload.get("title") or "內部派文",
        "body": payload.get("body") or "",
        "sender_user_id": user.get("id") or "",
        "sender_name": user.get("name") or user.get("email") or "",
        "sender_department": user.get("unit") or "",
        "reply_required": 1 if reply_required else 0,
        "reply_due_days": due_days or None,
        "due_at": due_at,
        "reply_status": "pending" if reply_required else "not_required",
        "status": "sent",
        "metadata_json": payload.get("metadata") or {},
        "created_at": now(),
        "updated_at": now(),
        "closed_at": "",
    }
    insert_row(conn, "internal_dispatches", row)
    for index, recipient in enumerate(recipients, start=1):
        action_required = recipient_actions[index - 1]
        recipient_user_id = recipient.get("user_id") or recipient.get("recipient_user_id") or ""
        recipient_user = active_user_by_id(conn, recipient_user_id) if recipient_user_id else None
        rec = {
            "id": f"IDREC-{int(time.time() * 1000)}-{index}-{secrets.token_hex(2).upper()}",
            "dispatch_id": dispatch_id,
            "recipient_type": recipient.get("recipient_type") or ("department" if recipient.get("department_id") else "user"),
            "recipient_user_id": recipient_user_id,
            "recipient_department_id": recipient.get("department_id") or recipient.get("recipient_department_id") or "",
            "recipient_name": recipient.get("name") or recipient.get("recipient_name") or (recipient_user.get("name") if recipient_user else ""),
            "action_required": 1 if action_required else 0,
            "status": "pending" if action_required else "informed",
            "read_at": "",
            "replied_at": "",
            "created_at": now(),
            "updated_at": now(),
        }
        insert_row(conn, "internal_dispatch_recipients", rec)
        if recipient_user:
            notice = (f"請於 {due_at} 前處理並回覆。" if due_at else "請處理並回覆。") if action_required else "此件僅供知悉，不需回覆。"
            create_and_deliver_notification(conn, {
                "type": "內部派文",
                "title": row["subject"],
                **exact_notification_target_payload(recipient_user, user.get("company_id") or ""),
                "source": dispatch_id,
                "body": f"{row['sender_name']} 發送內部公文。{notice}",
            })
    internal_dispatch_log(conn, dispatch_id, user, "create_internal_dispatch", row["subject"], payload)
    return internal_dispatch_detail(conn, dispatch_id, session)


def reply_internal_dispatch(conn: sqlite3.Connection, dispatch_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    detail = internal_dispatch_detail(conn, dispatch_id, session)
    recipient = next((item for item in detail["recipients"] if item.get("recipient_user_id") == user.get("id")), None)
    if not recipient:
        raise PermissionError("internal_dispatch_reply_forbidden")
    if recipient and not bool(recipient.get("action_required")):
        raise PermissionError("internal_dispatch_reply_not_required")
    attachment_file_id = ""
    if payload.get("content_base64"):
        data = base64.b64decode(payload["content_base64"])
        if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
            raise ValueError("internal_dispatch_reply_attachment_too_large")
        file_name = Path(payload.get("file_name") or f"{dispatch_id}-reply-attachment").name
        scan_status, scan_signature = scan_official_upload_bytes(data, file_name)
        file_row = store_file_object(conn, dispatch_id, file_name, data, "internal-dispatches", "reply-attachment", official_actor_name(user))
        conn.execute("UPDATE file_objects SET mime_type = ? WHERE id = ?", (payload.get("file_mime_type") or "application/pdf", file_row["id"]))
        persist_file_object_scan_result(conn, file_row["id"], scan_status, scan_signature, official_actor_name(user))
        attachment_file_id = file_row["id"]
    row = {
        "id": f"IDREP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "dispatch_id": dispatch_id,
        "recipient_id": recipient.get("id") if recipient else None,
        "replier_user_id": user.get("id") or "",
        "replier_name": user.get("name") or user.get("email") or "",
        "reply_text": payload.get("reply_text") or payload.get("body") or "",
        "attachment_file_id": attachment_file_id or None,
        "status": "submitted",
        "created_at": now(),
    }
    insert_row(conn, "internal_dispatch_replies", row)
    if recipient:
        conn.execute("UPDATE internal_dispatch_recipients SET status = 'replied', replied_at = ?, updated_at = ? WHERE id = ?", (now(), now(), recipient["id"]))
    pending = conn.execute("SELECT COUNT(*) AS count FROM internal_dispatch_recipients WHERE dispatch_id = ? AND action_required = 1 AND status <> 'replied'", (dispatch_id,)).fetchone()["count"]
    if detail.get("reply_required") and not pending:
        conn.execute("UPDATE internal_dispatches SET reply_status = 'completed', status = 'reply_completed', updated_at = ? WHERE id = ?", (now(), dispatch_id))
    internal_dispatch_log(conn, dispatch_id, user, "reply_internal_dispatch", row["reply_text"], payload)
    return internal_dispatch_detail(conn, dispatch_id, session)


def mark_internal_dispatch_read(
    conn: sqlite3.Connection,
    dispatch_id: str,
    payload: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = official_session_user(session)
    detail = internal_dispatch_detail(conn, dispatch_id, session)
    recipient = next((item for item in detail["recipients"] if item.get("recipient_user_id") == user.get("id")), None)
    if not recipient:
        raise PermissionError("internal_dispatch_read_forbidden")
    if not recipient.get("read_at"):
        timestamp = now()
        conn.execute(
            "UPDATE internal_dispatch_recipients SET read_at = ?, updated_at = ? WHERE id = ? AND COALESCE(read_at, '') = ''",
            (timestamp, timestamp, recipient["id"]),
        )
        internal_dispatch_log(conn, dispatch_id, user, "read_internal_dispatch", "recipient_opened_dispatch", payload)
    return internal_dispatch_detail(conn, dispatch_id, session)


def internal_dispatch_reply_attachment(
    conn: sqlite3.Connection,
    dispatch_id: str,
    reply_id: str,
    session: Dict[str, Any] | None,
) -> Tuple[Dict[str, Any], Dict[str, Any], bytes]:
    user = official_session_user(session)
    internal_dispatch_detail(conn, dispatch_id, session)
    reply = conn.execute(
        "SELECT * FROM internal_dispatch_replies WHERE id = ? AND dispatch_id = ?",
        (reply_id, dispatch_id),
    ).fetchone()
    if not reply or not reply["attachment_file_id"]:
        raise ValueError("internal_dispatch_reply_attachment_not_found")
    file_object, data = read_file_object_bytes(conn, reply["attachment_file_id"])
    if not file_object_av_is_clean(file_object):
        raise ValueError("internal_dispatch_reply_attachment_antivirus_required")
    internal_dispatch_log(conn, dispatch_id, user, "download_internal_dispatch_reply_attachment", f"reply_id={reply_id}")
    return row_to_dict(reply), file_object, data


def close_internal_dispatch(conn: sqlite3.Connection, dispatch_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    detail = internal_dispatch_detail(conn, dispatch_id, session)
    if detail.get("sender_user_id") != user.get("id") and not session_has_any_permission(session, ["official_documents.all_todo", "official_documents.all_records"]):
        raise PermissionError("internal_dispatch_close_forbidden")
    conn.execute("UPDATE internal_dispatches SET status = 'closed', closed_at = ?, updated_at = ? WHERE id = ?", (now(), now(), dispatch_id))
    internal_dispatch_log(conn, dispatch_id, user, "close_internal_dispatch", payload.get("comment") or "內部派文結案", payload)
    return internal_dispatch_detail(conn, dispatch_id, session)


def canonical_json_hash(value: Any) -> str:
    return sha256_bytes(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8"))


def normalized_stamp_positions(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    raw = payload.get("stamp_positions") or payload.get("stamps") or payload.get("positions") or []
    if isinstance(raw, str):
        raw = parse_json_any(raw, []) or []
    if not isinstance(raw, list):
        raise ValueError("stamp_positions_required")
    positions: List[Dict[str, Any]] = []
    for index, item in enumerate(raw, start=1):
        if not isinstance(item, dict):
            raise ValueError("invalid_stamp_position")
        width = pdf_safe_float(item.get("w", item.get("width")), 0)
        height = pdf_safe_float(item.get("h", item.get("height")), 0)
        if width <= 0 or height <= 0:
            raise ValueError("invalid_stamp_size")
        page = item.get("page", 1)
        normalized = {
            "id": str(item.get("id") or f"STAMP-POS-{index}"),
            "page": "all" if page == "all" else max(1, int(pdf_safe_float(page, 1))),
            "x": round(pdf_safe_float(item.get("x"), 0), 2),
            "y": round(pdf_safe_float(item.get("y"), 0), 2),
            "w": round(width, 2),
            "h": round(height, 2),
            "label": str(item.get("label") or item.get("seal_type") or "用印"),
            "type": str(item.get("type") or item.get("seal_type") or "一般章"),
            "seal_id": str(item.get("seal_id") or item.get("sealId") or payload.get("seal_id") or ""),
        }
        if normalized["x"] < 0 or normalized["y"] < 0:
            raise ValueError("invalid_stamp_coordinate")
        positions.append(normalized)
    if not positions:
        raise ValueError("stamp_positions_required")
    return positions


def lock_seal_application_company_positions(
    conn: sqlite3.Connection,
    positions: List[Dict[str, Any]],
    session: Dict[str, Any] | None,
) -> List[Dict[str, Any]]:
    """Attach immutable Seal Vault evidence when a legacy application uses a company seal."""
    locked: List[Dict[str, Any]] = []
    for raw_position in positions:
        position = dict(raw_position)
        seal_id = str(position.get("seal_id") or "")
        row = conn.execute("SELECT * FROM company_seals WHERE id = ?", (seal_id,)).fetchone()
        if not row:
            # Preserve compatibility for calibrated legacy assets such as
            # SEAL-001 and the non-square page seal.
            locked.append(position)
            continue
        assert_sqlite_seal_access(conn, seal_id, session)
        seal = company_seal_row(conn, seal_id)
        if not seal.get("is_active"):
            raise ValueError("inactive_seal_cannot_be_requested")
        seal_file = require_current_company_seal_file(conn, seal_id)
        profile = company_seal_file_dimension_profile(seal.get("seal_size_type"), seal_file, current=True)
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"),
            position.get("w"),
            position.get("h"),
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
        )
        position.update({
            "w": width,
            "h": height,
            "locked_seal_file_id": seal_file["id"],
            "locked_seal_sha256": seal_file["file_hash"],
            "locked_render_width_pt": profile["width_pt"],
            "locked_render_height_pt": profile["height_pt"],
            "locked_dimension_policy_version": profile["dimension_policy_version"],
        })
        locked.append(position)
    return locked


def validate_seal_application_company_positions(
    conn: sqlite3.Connection,
    positions: List[Dict[str, Any]],
    *,
    load_assets: bool = False,
) -> Tuple[List[Dict[str, Any]], Dict[str, Dict[str, Any]]]:
    """Revalidate every company seal version before approval and final stamping."""
    validated: List[Dict[str, Any]] = []
    assets: Dict[str, Dict[str, Any]] = {}
    for raw_position in positions:
        if not isinstance(raw_position, dict):
            raise ValueError("invalid_stamp_position")
        position = dict(raw_position)
        seal_id = str(position.get("seal_id") or "")
        row = conn.execute("SELECT * FROM company_seals WHERE id = ?", (seal_id,)).fetchone()
        if not row:
            validated.append(position)
            continue
        seal = company_seal_row(conn, seal_id)
        if not seal.get("is_active"):
            raise ValueError("inactive_seal_cannot_stamp")
        file_id = str(position.get("locked_seal_file_id") or "")
        if not file_id:
            raise ValueError("seal_dimension_lock_required")
        file_row = conn.execute("SELECT * FROM company_seal_files WHERE id = ?", (file_id,)).fetchone()
        if not file_row:
            raise ValueError("locked_seal_file_not_found")
        seal_file = require_seal_file_av_clean(conn, file_row)
        if (
            str(seal_file.get("seal_id") or "") != seal_id
            or str(seal_file.get("file_hash") or "") != str(position.get("locked_seal_sha256") or "")
        ):
            raise ValueError("seal_dimension_lock_mismatch")
        width, height = validate_locked_company_seal_position(
            position,
            seal.get("seal_size_type"),
            seal_file,
        )
        position["w"] = width
        position["h"] = height
        validated.append(position)
        if load_assets and file_id not in assets:
            file_object, data = read_file_object_bytes(conn, seal_file["file_object_id"])
            if sha256_bytes(data) != seal_file["file_hash"]:
                raise ValueError("seal_file_hash_mismatch")
            assets[file_id] = {
                "data": data,
                "mime_type": seal_file.get("file_mime_type") or file_object.get("mime_type") or "image/png",
            }
    return validated, assets


def stamp_seal_application_positions(
    original: bytes,
    positions: List[Dict[str, Any]],
    stamp_no: str,
    company_seal_assets: Dict[str, Dict[str, Any]],
) -> Tuple[bytes, str, Dict[str, Any]]:
    """Render each locked company seal image; retain legacy placeholders for old assets."""
    legacy_positions = [position for position in positions if not position.get("locked_seal_file_id")]
    current = original
    modes: List[str] = []
    metadata: Dict[str, Any] = {}
    if legacy_positions:
        current, mode, metadata = stamp_uploaded_pdf_bytes(current, legacy_positions, stamp_no)
        modes.append(mode)
    for file_id, seal_asset in company_seal_assets.items():
        group = [position for position in positions if str(position.get("locked_seal_file_id") or "") == file_id]
        if not group:
            continue
        current, mode, metadata = stamp_uploaded_pdf_bytes(
            current,
            group,
            stamp_no,
            seal_asset=seal_asset,
            source_text_on_top=True,
        )
        modes.append(mode)
    if not modes:
        raise ValueError("stamp_positions_required")
    return current, "+".join(modes), metadata


def pdf_page_sizes(data: bytes) -> List[Tuple[float, float]]:
    try:
        from pypdf import PdfReader  # type: ignore

        reader = PdfReader(io.BytesIO(data))
        sizes: List[Tuple[float, float]] = []
        for page in reader.pages:
            box = page.mediabox
            sizes.append((float(box.width), float(box.height)))
        return sizes or [(A4_WIDTH_PT, A4_HEIGHT_PT)]
    except Exception:
        return [(A4_WIDTH_PT, A4_HEIGHT_PT)]


def _reportlab_raster_fit_rect(
    image_reader: Any,
    x: float,
    y: float,
    width: float,
    height: float,
) -> Tuple[float, float, float, float]:
    """Fit a decoded raster inside a stamp box without changing its aspect ratio."""
    try:
        source_width_raw, source_height_raw = image_reader.getSize()
        source_width = float(source_width_raw)
        source_height = float(source_height_raw)
    except (AttributeError, TypeError, ValueError, OSError) as exc:
        raise ValueError("invalid_raster_seal_for_pdf") from exc
    if (
        not math.isfinite(source_width)
        or not math.isfinite(source_height)
        or source_width <= 0
        or source_height <= 0
    ):
        raise ValueError("invalid_raster_seal_for_pdf")
    scale = min(width / source_width, height / source_height)
    fitted_width = source_width * scale
    fitted_height = source_height * scale
    return (
        x + (width - fitted_width) / 2,
        y + (height - fitted_height) / 2,
        fitted_width,
        fitted_height,
    )


def write_asset_stamp_overlay_pdf(
    page_sizes: List[Tuple[float, float]],
    stamps: List[Dict[str, Any]],
    text_overlays: List[Dict[str, Any]],
    seal_asset: Dict[str, Any],
) -> bytes:
    mime_type = str(seal_asset.get("mime_type") or "").lower()
    seal_bytes = seal_asset.get("data")
    if not isinstance(seal_bytes, bytes) or not seal_bytes:
        raise ValueError("seal_image_bytes_required")
    try:
        from reportlab.lib.utils import ImageReader  # type: ignore
        from reportlab.pdfgen import canvas  # type: ignore

        kai_font_name = official_pdf_font_profile()["name"]
        svg_drawing = None
        image_reader = None
        if mime_type in {"image/svg+xml", "image/svg"}:
            from svglib.svglib import svg2rlg  # type: ignore

            svg_drawing = svg2rlg(io.BytesIO(seal_bytes))
            if not svg_drawing or not svg_drawing.width or not svg_drawing.height:
                raise ValueError("invalid_svg_seal_for_pdf")
        else:
            image_reader = ImageReader(io.BytesIO(seal_bytes))
        output = io.BytesIO()
        first_size = page_sizes[0] if page_sizes else (A4_WIDTH_PT, A4_HEIGHT_PT)
        pdf = canvas.Canvas(output, pagesize=first_size, pageCompression=1)
        for page_index, (page_width, page_height) in enumerate(page_sizes, start=1):
            pdf.setPageSize((page_width, page_height))
            for stamp in stamps:
                if stamp.get("page") not in {page_index, "all"}:
                    continue
                x, y, width, height = clamp_pdf_rect(
                    pdf_safe_float(stamp.get("x"), 0),
                    pdf_safe_float(stamp.get("y"), 0),
                    pdf_safe_float(stamp.get("w"), 56),
                    pdf_safe_float(stamp.get("h"), 56),
                )
                if x + width > page_width:
                    x = max(0, page_width - width)
                if y + height > page_height:
                    y = max(0, page_height - height)
                if svg_drawing is not None:
                    from reportlab.graphics import renderPDF  # type: ignore

                    scale = min(width / float(svg_drawing.width), height / float(svg_drawing.height))
                    translate_x = x + (width - float(svg_drawing.width) * scale) / 2
                    translate_y = y + (height - float(svg_drawing.height) * scale) / 2
                    pdf.saveState()
                    pdf.translate(translate_x, translate_y)
                    pdf.scale(scale, scale)
                    renderPDF.draw(svg_drawing, pdf, 0, 0)
                    pdf.restoreState()
                elif image_reader is not None:
                    image_x, image_y, image_width, image_height = _reportlab_raster_fit_rect(
                        image_reader,
                        x,
                        y,
                        width,
                        height,
                    )
                    pdf.drawImage(
                        image_reader,
                        image_x,
                        image_y,
                        width=image_width,
                        height=image_height,
                        mask="auto",
                        preserveAspectRatio=True,
                        anchor="c",
                    )
            pdf.setFillColorRGB(0, 0, 0)
            for overlay in text_overlays:
                if overlay.get("page") not in {page_index, "all"}:
                    continue
                font_size = max(8.0, min(72.0, pdf_safe_float(overlay.get("font_size"), 14.0)))
                x = max(12.0, min(pdf_safe_float(overlay.get("x"), 72.0), page_width - 12.0))
                y = max(12.0, min(pdf_safe_float(overlay.get("y"), 72.0), page_height - font_size - 6.0))
                pdf.setFont(kai_font_name, font_size)
                for line_index, line in enumerate(str(overlay.get("text_content") or "").splitlines() or [""]):
                    line_y = y - line_index * (font_size * 1.35)
                    if line and line_y >= 12.0:
                        pdf.drawString(x, line_y, line)
            pdf.showPage()
        pdf.save()
        return output.getvalue()
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError(f"seal_image_pdf_render_failed:{type(exc).__name__}") from exc


def write_kai_text_overlay_pdf(
    page_sizes: List[Tuple[float, float]],
    text_overlays: List[Dict[str, Any]],
) -> bytes:
    """Create a transparent Kai-text layer that is always painted above seals."""
    from reportlab.pdfgen import canvas  # type: ignore

    output = io.BytesIO()
    first_size = page_sizes[0] if page_sizes else (A4_WIDTH_PT, A4_HEIGHT_PT)
    pdf = canvas.Canvas(output, pagesize=first_size, pageCompression=1)
    kai_font_name = official_pdf_font_profile()["name"]
    for page_index, (page_width, page_height) in enumerate(page_sizes, start=1):
        pdf.setPageSize((page_width, page_height))
        pdf.setFillColorRGB(0, 0, 0)
        for overlay in text_overlays:
            if overlay.get("page") not in {page_index, "all"}:
                continue
            font_size = max(8.0, min(72.0, pdf_safe_float(overlay.get("font_size"), 14.0)))
            x = max(12.0, min(pdf_safe_float(overlay.get("x"), 72.0), page_width - 12.0))
            y = max(12.0, min(pdf_safe_float(overlay.get("y"), 72.0), page_height - font_size - 6.0))
            pdf.setFont(kai_font_name, font_size)
            for line_index, line in enumerate(str(overlay.get("text_content") or "").splitlines() or [""]):
                line_y = y - line_index * (font_size * 1.35)
                if line and line_y >= 12.0:
                    pdf.drawString(x, line_y, line)
        pdf.showPage()
    pdf.save()
    return output.getvalue()


def write_stamp_overlay_pdf(
    page_sizes: List[Tuple[float, float]],
    stamps: List[Dict[str, Any]],
    stamp_no: str,
    text_overlays: List[Dict[str, Any]] | None = None,
    seal_asset: Dict[str, Any] | None = None,
) -> bytes:
    if seal_asset:
        return write_asset_stamp_overlay_pdf(page_sizes, stamps, text_overlays or [], seal_asset)
    objects = ["<< /Type /Catalog /Pages 2 0 R >>"]
    page_object_numbers = [3 + index * 2 for index in range(len(page_sizes))]
    objects.append(f"<< /Type /Pages /Kids [{' '.join(f'{num} 0 R' for num in page_object_numbers)}] /Count {len(page_sizes)} >>")
    font_object_number = 3 + len(page_sizes) * 2
    cid_font_object_number = font_object_number + 1
    for page_index, (page_width, page_height) in enumerate(page_sizes, start=1):
        stream = ""
        for stamp in stamps:
            if stamp.get("page") not in {page_index, "all"}:
                continue
            x, y, width, height = clamp_pdf_rect(
                pdf_safe_float(stamp.get("x"), 0),
                pdf_safe_float(stamp.get("y"), 0),
                pdf_safe_float(stamp.get("w"), 56),
                pdf_safe_float(stamp.get("h"), 56),
            )
            if x + width > page_width:
                x = max(0, page_width - width)
            if y + height > page_height:
                y = max(0, page_height - height)
            label = stamp.get("label") or "用印"
            stamp_type = stamp.get("type") or ""
            stream += "1 0 0 RG 1 0 0 rg\n"
            stream += f"{x:.2f} {y:.2f} {width:.2f} {height:.2f} re S\n"
            stream += pdf_show_text(label, x + 6, y + height * 0.58, min(12, max(7, width / 7)))
            if stamp_type:
                stream += pdf_show_text(stamp_type, x + 6, y + height * 0.38, min(9, max(6, width / 9)))
            stream += pdf_show_text(stamp_no[-18:], x + 4, y + 6, min(6.5, max(5, width / 13)))
            stream += "0 0 0 RG 0 0 0 rg\n"
        for overlay in text_overlays or []:
            if overlay.get("page") not in {page_index, "all"}:
                continue
            font_size = max(8.0, min(72.0, pdf_safe_float(overlay.get("font_size"), 14.0)))
            x = max(12.0, min(pdf_safe_float(overlay.get("x"), 72.0), page_width - 12.0))
            y = max(12.0, min(pdf_safe_float(overlay.get("y"), 72.0), page_height - font_size - 6.0))
            lines = str(overlay.get("text_content") or "").splitlines() or [""]
            for line_index, line in enumerate(lines):
                line_y = y - line_index * (font_size * 1.35)
                if line and line_y >= 12.0:
                    stream += pdf_show_text(line, x, line_y, font_size)
        page_object_number = 3 + (page_index - 1) * 2
        content_object_number = page_object_number + 1
        objects.append(f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {page_width:.2f} {page_height:.2f}] /Resources << /Font << /F1 {font_object_number} 0 R >> >> /Contents {content_object_number} 0 R >>")
        stream_bytes = stream.encode("latin-1", "replace")
        objects.append(f"<< /Length {len(stream_bytes)} >>\nstream\n{stream}endstream")
    objects.append(
        f"<< /Type /Font /Subtype /Type0 /BaseFont /MKai-Medium /Encoding /UniCNS-UCS2-H "
        f"/DescendantFonts [{cid_font_object_number} 0 R] >>"
    )
    objects.append(
        "<< /Type /Font /Subtype /CIDFontType0 /BaseFont /MKai-Medium "
        "/CIDSystemInfo << /Registry (Adobe) /Ordering (CNS1) /Supplement 5 >> /DW 1000 >>"
    )
    pdf = "%PDF-1.4\n"
    offsets = [0]
    for index, obj in enumerate(objects, start=1):
        offsets.append(len(pdf.encode("latin-1")))
        pdf += f"{index} 0 obj\n{obj}\nendobj\n"
    xref_at = len(pdf.encode("latin-1"))
    pdf += f"xref\n0 {len(objects) + 1}\n0000000000 65535 f \n"
    for offset in offsets[1:]:
        pdf += f"{offset:010d} 00000 n \n"
    pdf += f"trailer\n<< /Size {len(objects) + 1} /Root 1 0 R >>\nstartxref\n{xref_at}\n%%EOF"
    return pdf.encode("latin-1", "replace")


def stamp_uploaded_pdf_bytes(
    original: bytes,
    stamps: List[Dict[str, Any]],
    stamp_no: str,
    text_overlays: List[Dict[str, Any]] | None = None,
    seal_asset: Dict[str, Any] | None = None,
    source_text_on_top: bool = False,
) -> Tuple[bytes, str, Dict[str, Any]]:
    page_sizes = pdf_page_sizes(original)
    try:
        from pypdf import PdfReader, PdfWriter  # type: ignore

        source = PdfReader(io.BytesIO(original))
        if source_text_on_top:
            seal_overlay = PdfReader(io.BytesIO(write_stamp_overlay_pdf(page_sizes, stamps, stamp_no, [], seal_asset)))
            text_overlay = PdfReader(io.BytesIO(write_kai_text_overlay_pdf(page_sizes, text_overlays or []))) if text_overlays else None
        else:
            overlay = PdfReader(io.BytesIO(write_stamp_overlay_pdf(page_sizes, stamps, stamp_no, text_overlays, seal_asset)))
        writer = PdfWriter()
        for index, page in enumerate(source.pages):
            writer.add_page(page)
            if source_text_on_top:
                writer.pages[-1].merge_page(seal_overlay.pages[index], over=False)
                if text_overlay:
                    writer.pages[-1].merge_page(text_overlay.pages[index], over=True)
            else:
                writer.pages[-1].merge_page(overlay.pages[index], over=True)
        out = io.BytesIO()
        writer.write(out)
        return out.getvalue(), "pypdf-seal-underlay" if source_text_on_top else "pypdf-overlay", {
            "page_count": len(source.pages),
            "page_size": page_sizes[0] if page_sizes else (A4_WIDTH_PT, A4_HEIGHT_PT),
            "text_overlay_count": len(text_overlays or []),
            "seal_image_applied": bool(seal_asset),
            "layer_policy": "source_and_added_text_over_company_seal" if source_text_on_top else "added_text_over_company_seal",
        }
    except Exception as exc:
        if seal_asset:
            raise ValueError(f"official_seal_image_stamp_failed:{str(exc)[:160]}") from exc
        fallback_doc = {
            "doc_no": stamp_no,
            "company_name": "歲悅股份有限公司",
            "doc_type": "用印證明",
            "agency_name": "PDF 用印工作台",
            "subject": "上傳 PDF 用印證明",
            "body": f"原始 PDF hash 已鎖定，因本環境缺少 PDF 疊章套件，產生用印證明 PDF。文字標記 {len(text_overlays or [])} 處。原因：{str(exc)[:120]}",
        }
        package = build_official_pdf_package(fallback_doc, [{**stamp, "stamp_no": stamp_no} for stamp in stamps], "上傳 PDF 用印證明", max(1, len(page_sizes)))
        return package["data"], "audit-receipt-fallback", {"page_count": package["layout"]["page_count"], "page_size": (A4_WIDTH_PT, A4_HEIGHT_PT), "fallback_reason": str(exc)[:160]}


def approval_route_steps(route_code: str = "A") -> Tuple[str, List[Dict[str, Any]]]:
    code = str(route_code or "A").strip().upper()
    if code not in {"A", "B", "C", "D"}:
        code = "A"
    steps = [{"key": "applicant_submit", "step_name": "申請人送出", "role": "申請人"}]
    steps.extend(
        {"key": step["key"], "step_name": step["name"], "role": step["role"]}
        for step in unified_official_workflow_steps(code)
        if step["key"] != "applicant_confirm"
    )
    steps.extend([
        {"key": "auto_stamp", "step_name": "系統自動用印", "role": "系統"},
        {"key": "applicant_confirm", "step_name": "申請人收件", "role": "申請人"},
    ])
    return code, [{**step, "step_no": index} for index, step in enumerate(steps, start=1)]


def current_user_from_session(session: Dict[str, Any] | None) -> Dict[str, Any]:
    return (session or {}).get("user") or {}


def seal_application_row(conn: sqlite3.Connection, application_id: str) -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM seal_applications WHERE id = ?", (application_id,)).fetchone()
    if not row:
        raise ValueError("seal_application_not_found")
    data = row_to_dict(row)
    for field in ("stamp_positions_json", "approval_snapshot_json", "evidence_json"):
        data[field.replace("_json", "")] = parse_json_any(data.get(field), [] if field == "stamp_positions_json" else {}) or ([] if field == "stamp_positions_json" else {})
    return data


def seal_application_company_context(conn: sqlite3.Connection, applicant: Dict[str, Any], company_name: str) -> Dict[str, Any]:
    if applicant.get("company_id"):
        row = conn.execute("SELECT * FROM companies WHERE id = ?", (applicant["company_id"],)).fetchone()
        if row:
            return row_to_dict(row)
    if company_name:
        row = conn.execute("SELECT * FROM companies WHERE name = ? ORDER BY rowid LIMIT 1", (company_name,)).fetchone()
        if row:
            return row_to_dict(row)
    return {"id": applicant.get("company_id") or "", "name": company_name or applicant.get("company_name") or ""}


def resolve_seal_application_step_actors(
    conn: sqlite3.Connection,
    steps: List[Dict[str, Any]],
    applicant: Dict[str, Any],
    company: Dict[str, Any],
) -> Dict[int, Dict[str, Any]]:
    actors: Dict[int, Dict[str, Any]] = {}
    for step in steps:
        key = step["key"]
        if key in {"applicant_submit", "applicant_confirm"}:
            actor = applicant
        elif key == "auto_stamp":
            actor = {"id": "system", "name": "系統自動用印", "email": "", "role": "系統", "account_source": "system"}
        else:
            actor = resolve_official_step_approver(
                conn,
                {
                    "key": key,
                    "name": step["step_name"],
                    "role": step["role"],
                    "status": OFFICIAL_DOCUMENT_STEP_STATUS.get(key) or "pending",
                },
                applicant,
                company,
            )
        if not actor:
            raise ValueError(f"seal_application_route_actor_unresolved:{key}")
        actors[int(step["step_no"])] = actor
    return actors


def insert_approval_snapshots(
    conn: sqlite3.Connection,
    application_id: str,
    steps: List[Dict[str, Any]],
    applicant: Dict[str, Any],
    actors: Dict[int, Dict[str, Any]] | None = None,
) -> None:
    conn.execute("DELETE FROM approval_step_actor_snapshots WHERE source_type = 'seal_application' AND source_id = ?", (application_id,))
    timestamp = now()
    actors = actors or {int(step["step_no"]): applicant for step in steps}
    for step in steps:
        is_submitter = step["step_no"] == 1
        status = "已完成" if is_submitter else "待簽核" if step["step_no"] == 2 else "未開始"
        actor = actors[int(step["step_no"])]
        actor_source = "finance_organization_directory" if str(actor.get("account_source") or "").lower() == "finance" else "legacy_directory_compat"
        if step["key"] == "auto_stamp":
            actor_source = "system"
        conn.execute(
            """
            INSERT INTO approval_step_actor_snapshots (
              id, seal_application_id, source_type, source_id, step_no, step_name, approver_role,
              approver_user_id, approver_name, approver_email, status, comment, acted_at,
              snapshot_json, created_at, updated_at
            ) VALUES (?, ?, 'seal_application', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                f"APSN-{application_id}-{step['step_no']}",
                application_id,
                application_id,
                step["step_no"],
                step["step_name"],
                step["role"],
                actor.get("id") or "",
                actor.get("name") or step["role"],
                actor.get("email") or "",
                status,
                "送出申請並鎖定 PDF 與章位。" if is_submitter else "",
                timestamp if is_submitter else "",
                json.dumps({
                    "source": actor_source,
                    "step_key": step["key"],
                    "role": step["role"],
                    "step": step["step_name"],
                    "actor_id": actor.get("id") or "",
                }, ensure_ascii=False),
                timestamp,
                timestamp,
            ),
        )


def seal_application_step_snapshot(conn: sqlite3.Connection, application_id: str, step_no: int) -> Dict[str, Any]:
    row = conn.execute(
        """
        SELECT * FROM approval_step_actor_snapshots
        WHERE source_type = 'seal_application' AND source_id = ? AND step_no = ?
        LIMIT 1
        """,
        (application_id, step_no),
    ).fetchone()
    if not row:
        raise ValueError("seal_application_current_step_snapshot_missing")
    return row_to_dict(row)


def assert_seal_application_step_actor(user: Dict[str, Any], snapshot: Dict[str, Any]) -> None:
    if not user:
        raise PermissionError("authentication_required")
    if snapshot.get("approver_user_id") != user.get("id"):
        raise PermissionError("not_current_seal_application_approver")


def create_seal_notification(
    conn: sqlite3.Connection,
    application: Dict[str, Any],
    title: str,
    target_role: str,
    body: str,
    priority: str = "中",
    target_user: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    applicant = active_user_by_id(conn, application.get("applicant_user_id") or "") or {}
    applicant_targets = {
        application.get("applicant") or "",
        application.get("applicant_name") or "",
        "員工",
    }
    if target_user:
        resolved_target = target_user
    elif target_role in applicant_targets:
        resolved_target = applicant
    else:
        candidate_roles = [target_role]
        if target_role == "主管":
            candidate_roles.extend(["主任", "行政部主任"])
        approver = {}
        for role in candidate_roles:
            approver = active_user_by_role(
                conn,
                role,
                company_id=applicant.get("company_id") or "",
            ) or {}
            if approver:
                break
        resolved_target = approver
    return create_and_deliver_notification(conn, {
        "type": "用印簽核",
        "title": title,
        **exact_notification_target_payload(
            resolved_target,
            applicant.get("company_id") or "",
        ),
        "channel": "Email + 系統通知",
        "priority": priority,
        "source": application["id"],
        "body": body,
    })


def seal_application_submit(conn: sqlite3.Connection, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    user = current_user_from_session(session)
    applicant_name = payload.get("applicant_name") or user.get("name") or payload.get("applicant") or "申請人"
    document = get_or_create_pdf_document(conn, payload)
    file_id = payload.get("source_pdf_file_object_id") or payload.get("file_object_id")
    if not file_id and payload.get("source_pdf_content_base64"):
        upload = upload_file_object(conn, {
            "document_id": document["id"],
            "file_name": payload.get("source_pdf_name") or f"{document['doc_no']}-uploaded.pdf",
            "mime_type": "application/pdf",
            "purpose": "source-pdf",
            "version_label": "uploaded-source",
            "actor": applicant_name,
            "content_base64": payload["source_pdf_content_base64"],
        })
        if upload.get("error"):
            raise ValueError(upload["error"])
        file_id = upload["file"]["id"]
        scan = scan_file_object(conn, file_id, applicant_name)
        if not scan.get("ok"):
            raise ValueError(scan.get("error") or "source_pdf_antivirus_rejected")
    if not file_id:
        raise ValueError("source_pdf_required")
    file_row, source_bytes = read_file_object_bytes(conn, file_id)
    if str(file_row.get("scan_status") or "").strip() == "已隔離":
        raise ValueError("source_pdf_quarantined")
    if not file_object_av_is_clean(file_row):
        raise ValueError("source_pdf_antivirus_required")
    if file_row.get("mime_type") != "application/pdf" and not str(file_row.get("file_name") or "").lower().endswith(".pdf"):
        raise ValueError("source_pdf_must_be_pdf")
    inspect_editor_pdf(source_bytes)
    positions = lock_seal_application_company_positions(
        conn,
        normalized_stamp_positions(payload),
        session,
    )
    locked_pdf_sha256 = sha256_bytes(source_bytes)
    locked_positions_sha256 = canonical_json_hash(positions)
    route_code, steps = approval_route_steps(payload.get("approval_route_code") or payload.get("route") or "A")
    route_name = payload.get("approval_route_name") or OFFICIAL_SEAL_ROUTE_NAMES[route_code]
    applicant = active_user_by_id(conn, user.get("id") or "") or user
    company_name = payload.get("company_name") or document.get("company_name") or applicant.get("company_name") or "歲悅股份有限公司"
    company = seal_application_company_context(conn, applicant, company_name)
    step_actors = resolve_seal_application_step_actors(conn, steps, applicant, company)
    first_step = steps[1]
    first_actor = step_actors[int(first_step["step_no"])]
    application_id = payload.get("id") or payload.get("application_id") or f"USEAL-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    before_version = create_pdf_version_for_file(conn, document, file_row, "before_seal", payload.get("template") or "上傳 PDF", {
        "source": "uploaded_pdf",
        "page_count": len(pdf_page_sizes(source_bytes)),
        "locked_pdf_sha256": locked_pdf_sha256,
        "locked_positions_sha256": locked_positions_sha256,
        "stamp_positions": positions,
    })
    application = {
        "id": application_id,
        "document_id": document["id"],
        "seal_id": payload.get("seal_id") or positions[0].get("seal_id") or "SEAL-001",
        "application_type": payload.get("application_type") or payload.get("type") or "official_document",
        "company_name": company_name,
        "department": payload.get("department") or document.get("department") or "",
        "title": payload.get("title") or document.get("subject") or document["doc_no"],
        "source_pdf_file_object_id": file_row["id"],
        "source_pdf_sha256": file_row["sha256"],
        "source_pdf_name": file_row["file_name"],
        "locked_pdf_sha256": locked_pdf_sha256,
        "locked_positions_sha256": locked_positions_sha256,
        "stamp_positions_json": json.dumps(positions, ensure_ascii=False),
        "approval_route_code": route_code,
        "approval_route_name": route_name,
        "approval_snapshot_json": json.dumps({
            "steps": [
                {
                    **step,
                    "approver_user_id": step_actors[int(step["step_no"])].get("id") or "",
                    "approver_name": step_actors[int(step["step_no"])].get("name") or step["role"],
                }
                for step in steps
            ],
            "source": "finance_organization_directory_v2",
            "route_version": 2,
            "applicant_profile": {
                "name": applicant_name,
                "department": payload.get("department") or document.get("department") or "",
                "email": user.get("email") or payload.get("applicant_email") or "",
                "phone": payload.get("applicant_phone") or "",
            },
        }, ensure_ascii=False),
        "current_step_no": first_step["step_no"],
        "current_step_name": first_step["step_name"],
        "current_approver_role": first_actor.get("role") or first_step["role"],
        "applicant_user_id": user.get("id") or "",
        "applicant_name": applicant_name,
        "applicant_email": user.get("email") or payload.get("applicant_email") or "",
        "applicant": applicant_name,
        "approver": first_actor.get("name") or first_step["role"],
        "status": f"待{first_step['step_name']}簽核",
        "reason": payload.get("reason") or payload.get("purpose") or "上傳 PDF 後申請用印",
        "reject_reason": "",
        "stamp_no": "",
        "pdf_before_version_id": before_version["id"],
        "pdf_after_version_id": "",
        "returned_at": "",
        "completed_at": "",
        "notification_id": "",
        "created_at": now(),
        "approved_at": "",
        "updated_at": now(),
    }
    insert_row(conn, "seal_applications", application)
    insert_approval_snapshots(conn, application_id, steps, applicant, step_actors)
    notice = create_seal_notification(
        conn,
        application,
        f"{application['title']} 待{first_step['step_name']}簽核",
        first_actor.get("role") or first_step["role"],
        f"{applicant_name} 已送出 {file_row['file_name']} 用印申請，PDF 與 {len(positions)} 個章位已鎖定。",
        target_user=first_actor,
    )
    conn.execute("UPDATE seal_applications SET notification_id = ? WHERE id = ?", (notice["id"], application_id))
    log_audit(conn, applicant_name, "送簽 PDF 用印", "seal_applications", application_id, f"pdf={locked_pdf_sha256}, positions={locked_positions_sha256}", event_type="submit", module_code="seals")
    return {**seal_application_row(conn, application_id), "pdf_before": before_version, "notification": notice}


def seal_application_approve(conn: sqlite3.Connection, application_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    application = seal_application_row(conn, application_id)
    user = current_user_from_session(session)
    current_snapshot = seal_application_step_snapshot(conn, application_id, int(application.get("current_step_no") or 0))
    assert_seal_application_step_actor(user, current_snapshot)
    snapshot_meta = parse_json_any(current_snapshot.get("snapshot_json"), {}) or {}
    current_key = snapshot_meta.get("step_key") or ""
    timestamp = now()

    if current_key == "applicant_confirm":
        if not application.get("stamp_no") or application.get("status") != "待申請人收件":
            raise ValueError("seal_application_not_ready_for_applicant_receipt")
        conn.execute(
            """
            UPDATE approval_step_actor_snapshots
            SET status = '已完成', comment = ?, acted_at = ?, updated_at = ?
            WHERE id = ?
            """,
            (payload.get("comment") or "申請人確認收件。", timestamp, timestamp, current_snapshot["id"]),
        )
        conn.execute(
            """
            UPDATE seal_applications
            SET status = '完成', completed_at = ?, current_approver_role = '申請人',
                approver = ?, updated_at = ?
            WHERE id = ?
            """,
            (timestamp, user.get("name") or application.get("applicant_name") or "申請人", timestamp, application_id),
        )
        log_audit(
            conn,
            user.get("name") or "申請人",
            "確認收件並完成 PDF 用印流程",
            "seal_applications",
            application_id,
            f"stamp_no={application.get('stamp_no') or ''}",
            event_type="approve",
            module_code="seals",
        )
        return seal_application_row(conn, application_id)

    if application["status"] in {"完成", "退回補正"} or application.get("stamp_no"):
        raise ValueError("seal_application_already_completed")
    if current_key in {"", "applicant_submit", "auto_stamp"}:
        raise ValueError("seal_application_current_step_not_approvable")
    file_row, source_bytes = read_file_object_bytes(conn, application["source_pdf_file_object_id"])
    if str(file_row.get("scan_status") or "").strip() == "已隔離":
        raise ValueError("source_pdf_quarantined")
    if not file_object_av_is_clean(file_row):
        raise ValueError("source_pdf_antivirus_required")
    if sha256_bytes(source_bytes) != application["locked_pdf_sha256"]:
        raise ValueError("locked_pdf_hash_mismatch")
    positions = parse_json_any(application["stamp_positions_json"], []) or []
    if canonical_json_hash(positions) != application["locked_positions_sha256"]:
        raise ValueError("locked_stamp_positions_mismatch")
    positions, _company_seal_assets = validate_seal_application_company_positions(conn, positions)
    conn.execute(
        """
        UPDATE approval_step_actor_snapshots
        SET status = '已完成', comment = ?, acted_at = ?, updated_at = ?
        WHERE id = ?
        """,
        (payload.get("comment") or "核准", timestamp, timestamp, current_snapshot["id"]),
    )
    next_row = conn.execute(
        """
        SELECT * FROM approval_step_actor_snapshots
        WHERE source_type = 'seal_application' AND source_id = ? AND step_no > ?
        ORDER BY step_no LIMIT 1
        """,
        (application_id, current_snapshot["step_no"]),
    ).fetchone()
    if not next_row:
        raise ValueError("seal_application_next_step_missing")
    next_snapshot = row_to_dict(next_row)
    next_meta = parse_json_any(next_snapshot.get("snapshot_json"), {}) or {}
    next_key = next_meta.get("step_key") or ""

    if next_key != "auto_stamp":
        conn.execute(
            "UPDATE approval_step_actor_snapshots SET status = '待簽核', updated_at = ? WHERE id = ?",
            (timestamp, next_snapshot["id"]),
        )
        conn.execute(
            """
            UPDATE seal_applications
            SET status = ?, current_step_no = ?, current_step_name = ?,
                current_approver_role = ?, approver = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                f"待{next_snapshot['step_name']}簽核",
                next_snapshot["step_no"],
                next_snapshot["step_name"],
                next_snapshot["approver_role"],
                next_snapshot.get("approver_name") or next_snapshot["approver_role"],
                timestamp,
                application_id,
            ),
        )
        refreshed = seal_application_row(conn, application_id)
        next_actor = active_user_by_id(conn, next_snapshot.get("approver_user_id") or "") or {
            "id": next_snapshot.get("approver_user_id") or "",
            "name": next_snapshot.get("approver_name") or "",
            "email": next_snapshot.get("approver_email") or "",
            "role": next_snapshot.get("approver_role") or "",
        }
        notice = create_seal_notification(
            conn,
            refreshed,
            f"{refreshed['title']} 待{next_snapshot['step_name']}簽核",
            next_snapshot.get("approver_role") or "",
            f"{current_snapshot['step_name']}已核准，請接續處理。",
            "高",
            target_user=next_actor,
        )
        conn.execute("UPDATE seal_applications SET notification_id = ? WHERE id = ?", (notice["id"], application_id))
        log_audit(
            conn,
            user.get("name") or current_snapshot.get("approver_role") or "簽核人",
            f"完成{current_snapshot['step_name']}簽核",
            "seal_applications",
            application_id,
            f"next_step={next_key}",
            event_type="approve",
            module_code="seals",
        )
        return {**seal_application_row(conn, application_id), "notification": notice}

    document = row_to_dict(conn.execute("SELECT * FROM documents WHERE id = ?", (application["document_id"],)).fetchone())
    stamp_no = payload.get("stamp_no") or f"STAMP-{''.join(ch for ch in document['doc_no'] if ch.isdigit())[-10:] or int(time.time())}-{int(time.time())}"
    positions, company_seal_assets = validate_seal_application_company_positions(
        conn,
        positions,
        load_assets=True,
    )
    stamped_bytes, mode, metadata = stamp_seal_application_positions(
        source_bytes,
        [{**position, "stamp_no": stamp_no} for position in positions],
        stamp_no,
        company_seal_assets,
    )
    after_version = create_pdf_version(conn, document, "after_seal", payload.get("template") or "上傳 PDF 自動用印", stamped_bytes, {
        "source": "uploaded_pdf",
        "stamp_engine": mode,
        "page_count": metadata.get("page_count") or len(pdf_page_sizes(source_bytes)),
        "page_size": metadata.get("page_size"),
        "locked_pdf_sha256": application["locked_pdf_sha256"],
        "locked_positions_sha256": application["locked_positions_sha256"],
        "stamp_positions": positions,
        "fallback_reason": metadata.get("fallback_reason", ""),
    }, stamp_no, application["pdf_before_version_id"])
    signature = create_electronic_signature(conn, {
        **payload,
        "document_id": document["id"],
        "pdf_version_id": after_version["id"],
        "file_object_id": after_version["file_object_id"],
        "certificate_id": payload.get("certificate_id") or "CERT-SEAL-001",
        "signature_type": "seal",
        "signer": payload.get("approver") or user.get("name") or current_snapshot.get("approver_role") or "總務專員",
        "operation": f"總務專員完成末關核准後自動用印 {stamp_no}",
    })
    auto_snapshot = next_snapshot
    receipt_row = conn.execute(
        """
        SELECT * FROM approval_step_actor_snapshots
        WHERE source_type = 'seal_application' AND source_id = ? AND step_no > ?
        ORDER BY step_no LIMIT 1
        """,
        (application_id, auto_snapshot["step_no"]),
    ).fetchone()
    if not receipt_row:
        raise ValueError("seal_application_receipt_step_missing")
    receipt_snapshot = row_to_dict(receipt_row)
    conn.execute(
        """
        UPDATE seal_applications
        SET status = '待申請人收件', approver = ?, stamp_no = ?, pdf_after_version_id = ?,
            approved_at = ?, completed_at = '', current_step_no = ?, current_step_name = '申請人收件',
            current_approver_role = '申請人', signature_id = ?, provider_status = ?, evidence_json = ?,
            updated_at = ?
        WHERE id = ?
        """,
        (
            payload.get("approver") or user.get("name") or current_snapshot.get("approver_role") or "總務專員",
            stamp_no,
            after_version["id"],
            timestamp,
            receipt_snapshot["step_no"],
            signature["id"],
            "簽章完成" if signature.get("status") == "有效" else signature.get("status") or "簽章完成",
            json.dumps({"pdf_after_sha256": after_version["sha256"], "stamp_engine": mode, "signature_id": signature["id"], "stamp_positions": positions}, ensure_ascii=False),
            timestamp,
            application_id,
        ),
    )
    conn.execute(
        """
        UPDATE approval_step_actor_snapshots
        SET status = '已完成', comment = '後端完成雜湊驗證與自動用印。', acted_at = ?, updated_at = ?
        WHERE id = ?
        """,
        (timestamp, timestamp, auto_snapshot["id"]),
    )
    conn.execute(
        "UPDATE approval_step_actor_snapshots SET status = '待簽核', updated_at = ? WHERE id = ?",
        (timestamp, receipt_snapshot["id"]),
    )
    refreshed = seal_application_row(conn, application_id)
    applicant = active_user_by_id(conn, refreshed.get("applicant_user_id") or "") or {
        "id": refreshed.get("applicant_user_id") or "",
        "name": refreshed.get("applicant_name") or "申請人",
        "email": refreshed.get("applicant_email") or "",
        "role": "申請人",
    }
    notice = create_seal_notification(
        conn,
        refreshed,
        f"{refreshed['title']} 已完成用印，請申請人收件",
        applicant.get("role") or "申請人",
        f"總務專員已完成末關核准，系統已自動押章並產生 PDF hash {after_version['sha256']}。",
        "高",
        target_user=applicant,
    )
    conn.execute("UPDATE seal_applications SET notification_id = ? WHERE id = ?", (notice["id"], application_id))
    log_audit(conn, user.get("name") or "總務專員", "末關核准並自動用印", "seal_applications", application_id, f"{stamp_no} / {after_version['sha256']}", event_type="approve", module_code="seals")
    return {**seal_application_row(conn, application_id), "pdf_after": after_version, "signature": signature, "notification": notice}


def seal_application_return(conn: sqlite3.Connection, application_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    application = seal_application_row(conn, application_id)
    user = current_user_from_session(session)
    if application.get("stamp_no") or application.get("status") in {"待申請人收件", "完成"}:
        raise ValueError("seal_application_cannot_return_after_stamp")
    current_snapshot = seal_application_step_snapshot(conn, application_id, int(application.get("current_step_no") or 0))
    assert_seal_application_step_actor(user, current_snapshot)
    reason = payload.get("reason") or payload.get("comment") or "資料需補正後重新送簽。"
    timestamp = now()
    conn.execute(
        """
        UPDATE seal_applications
        SET status = '退回補正', reject_reason = ?, reason = ?, returned_at = ?,
            current_step_name = '申請人補正', current_approver_role = '員工', updated_at = ?
        WHERE id = ?
        """,
        (reason, reason, timestamp, timestamp, application_id),
    )
    conn.execute(
        """
        UPDATE approval_step_actor_snapshots
        SET status = '退回補正', comment = ?, approver_user_id = ?, approver_name = ?,
            approver_email = ?, acted_at = ?, updated_at = ?
        WHERE source_type = 'seal_application' AND source_id = ? AND step_no = ?
        """,
        (reason, user.get("id") or "", user.get("name") or payload.get("actor") or application.get("current_approver_role") or "主管", user.get("email") or "", timestamp, timestamp, application_id, application.get("current_step_no") or 2),
    )
    refreshed = seal_application_row(conn, application_id)
    applicant = active_user_by_id(conn, refreshed.get("applicant_user_id") or "") or {
        "id": refreshed.get("applicant_user_id") or "",
        "name": refreshed.get("applicant_name") or "申請人",
        "email": refreshed.get("applicant_email") or "",
        "role": "申請人",
    }
    notice = create_seal_notification(
        conn,
        refreshed,
        f"{refreshed['title']} 已退回補正",
        applicant.get("role") or "申請人",
        reason,
        "高",
        target_user=applicant,
    )
    conn.execute("UPDATE seal_applications SET notification_id = ? WHERE id = ?", (notice["id"], application_id))
    log_audit(conn, user.get("name") or payload.get("actor") or "主管", "退回 PDF 用印", "seal_applications", application_id, reason, event_type="reject", module_code="seals")
    return {**seal_application_row(conn, application_id), "notification": notice}


def latest_signature(conn: sqlite3.Connection, document_id: str) -> Dict[str, Any] | None:
    row = conn.execute(
        "SELECT * FROM electronic_signatures WHERE document_id = ? ORDER BY rowid DESC LIMIT 1",
        (document_id,),
    ).fetchone()
    return row_to_dict(row) if row else None


def active_certificate(conn: sqlite3.Connection, certificate_id: str = "", owner: str = "") -> Dict[str, Any]:
    if certificate_id:
        row = conn.execute("SELECT * FROM signing_certificates WHERE id = ? AND status = '啟用'", (certificate_id,)).fetchone()
    elif owner:
        row = conn.execute("SELECT * FROM signing_certificates WHERE owner = ? AND status = '啟用' ORDER BY rowid LIMIT 1", (owner,)).fetchone()
    else:
        row = conn.execute("SELECT * FROM signing_certificates WHERE status = '啟用' ORDER BY rowid LIMIT 1").fetchone()
    if not row:
        raise ValueError("active_signing_certificate_not_found")
    return row_to_dict(row)


def signature_secret() -> bytes:
    value = os.getenv("EDOC_SIGNING_SECRET") or os.getenv("CRON_SECRET") or "dev-edoc-signing-secret-change-before-production"
    return value.encode("utf-8")


class SignatureProviderError(RuntimeError):
    def __init__(self, message: str, event: Dict[str, Any] | None = None):
        super().__init__(message)
        self.event = event or {}


class SupabaseConfigurationError(RuntimeError):
    """Raised when Supabase mode is enabled but required runtime secrets are absent."""


def provider_event_row(event: Dict[str, Any], document_id: str = "", signature_id: str = "") -> Dict[str, Any]:
    return {
        "id": event.get("id") or f"SPE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "document_id": document_id or event.get("document_id") or "",
        "signature_id": signature_id or event.get("signature_id") or "",
        "provider": event.get("provider") or EDOC_SIGNATURE_PROVIDER,
        "operation": event.get("operation") or "signature-provider",
        "request_id": event.get("request_id") or "",
        "endpoint": event.get("endpoint") or "",
        "request_digest_sha256": event.get("request_digest_sha256") or "",
        "response_digest_sha256": event.get("response_digest_sha256") or "",
        "status": event.get("status") or "失敗",
        "http_status": event.get("http_status"),
        "error": event.get("error") or "",
        "attempt_count": int(event.get("attempt_count") or 1),
        "duration_ms": int(event.get("duration_ms") or 0),
        "created_at": event.get("created_at") or now(),
    }


def record_signature_provider_event(conn: sqlite3.Connection, event: Dict[str, Any], document_id: str = "", signature_id: str = "") -> Dict[str, Any]:
    row = provider_event_row(event, document_id, signature_id)
    conn.execute(
        """
        INSERT OR REPLACE INTO signature_provider_events (
          id, document_id, signature_id, provider, operation, request_id, endpoint,
          request_digest_sha256, response_digest_sha256, status, http_status,
          error, attempt_count, duration_ms, created_at
        ) VALUES (
          :id, :document_id, :signature_id, :provider, :operation, :request_id, :endpoint,
          :request_digest_sha256, :response_digest_sha256, :status, :http_status,
          :error, :attempt_count, :duration_ms, :created_at
        )
        """,
        row,
    )
    return row


def provider_json_request(url: str, payload: Dict[str, Any], api_key: str, timeout: int | None = None, operation: str = "signature-provider") -> Dict[str, Any]:
    request_id = payload.get("request_id") or f"SIGREQ-{int(time.time() * 1000)}-{secrets.token_hex(4).upper()}"
    payload["request_id"] = request_id
    request_digest = sha256_bytes(canonical_signature_payload(payload).encode("utf-8"))
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "suiyuecare-edoc-signature/1.0",
        "X-Request-ID": request_id,
        "Idempotency-Key": request_digest,
    }
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    attempts = max(1, EDOC_SIGNATURE_MAX_RETRIES + 1)
    last_event: Dict[str, Any] = {}
    for attempt in range(1, attempts + 1):
        started = time.time()
        request = urllib.request.Request(
            url,
            data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
            headers=headers,
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout or EDOC_SIGNATURE_TIMEOUT_SECONDS) as response:
                raw = response.read().decode("utf-8")
                data = json.loads(raw) if raw else {}
                return {
                    "data": data,
                    "event": {
                        "provider": EDOC_SIGNATURE_PROVIDER,
                        "operation": operation,
                        "request_id": request_id,
                        "endpoint": url,
                        "request_digest_sha256": request_digest,
                        "response_digest_sha256": sha256_bytes(raw.encode("utf-8")),
                        "status": "成功",
                        "http_status": response.status,
                        "attempt_count": attempt,
                        "duration_ms": int((time.time() - started) * 1000),
                    },
                }
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="ignore")
            last_event = {
                "provider": EDOC_SIGNATURE_PROVIDER,
                "operation": operation,
                "request_id": request_id,
                "endpoint": url,
                "request_digest_sha256": request_digest,
                "status": "失敗",
                "http_status": exc.code,
                "error": detail[:500],
                "attempt_count": attempt,
                "duration_ms": int((time.time() - started) * 1000),
            }
            if exc.code not in {408, 425, 429, 500, 502, 503, 504} or attempt == attempts:
                raise SignatureProviderError(f"provider_http_{exc.code}:{detail}", last_event) from exc
        except Exception as exc:
            last_event = {
                "provider": EDOC_SIGNATURE_PROVIDER,
                "operation": operation,
                "request_id": request_id,
                "endpoint": url,
                "request_digest_sha256": request_digest,
                "status": "失敗",
                "error": str(exc)[:500],
                "attempt_count": attempt,
                "duration_ms": int((time.time() - started) * 1000),
            }
            if attempt == attempts:
                raise SignatureProviderError(f"provider_request_failed:{exc}", last_event) from exc
        time.sleep(min(1.5, 0.25 * attempt))
    raise SignatureProviderError("provider_request_failed", last_event)


def request_formal_signature(digest_payload: Dict[str, Any], digest: str, certificate: Dict[str, Any], signer: str, signature_id: str = "") -> Dict[str, Any]:
    if EDOC_SIGNATURE_PROVIDER == "local-simulation":
        signature_value = hmac.new(signature_secret(), canonical_signature_payload(digest_payload).encode("utf-8"), hashlib.sha256).hexdigest().upper()
        tsa_token = hmac.new(signature_secret(), f"TSA|{digest}|{digest_payload['timestamp']}".encode("utf-8"), hashlib.sha256).hexdigest().upper()
        return {
            "algorithm": "HMAC-SHA256-RSA-PSS-READY",
            "signature_value": signature_value,
            "tsa_token": tsa_token,
            "provider_receipt": {"mode": "local-simulation", "profile": EDOC_SIGNATURE_PROFILE},
            "provider_request_id": f"LOCAL-{signature_id or int(time.time() * 1000)}",
            "provider_status": "local-simulation",
            "provider_events": [],
        }
    if not EDOC_SIGNATURE_API_URL or not EDOC_SIGNATURE_API_KEY:
        raise ValueError("formal_signature_provider_not_configured")
    request_id = f"SIGREQ-{signature_id or int(time.time() * 1000)}"
    response = provider_json_request(
        f"{EDOC_SIGNATURE_API_URL}/sign",
        {
            "provider": EDOC_SIGNATURE_PROVIDER,
            "key_id": EDOC_SIGNATURE_KEY_ID,
            "request_id": request_id,
            "signature_id": signature_id,
            "signature_profile": EDOC_SIGNATURE_PROFILE,
            "certificate_id": certificate["id"],
            "certificate_serial": certificate.get("serial_no"),
            "signer": signer,
            "digest_sha256": digest,
            "payload": digest_payload,
            "tsa_url": EDOC_TSA_URL,
            "tsa_policy_oid": EDOC_TSA_POLICY_OID,
        },
        EDOC_SIGNATURE_API_KEY,
        operation="sign",
    )
    result = response["data"]
    signature_value = result.get("signature_value") or result.get("signature") or result.get("cms") or result.get("p7s")
    if not signature_value:
        raise ValueError("formal_signature_provider_missing_signature")
    tsa_token = result.get("tsa_token") or result.get("timestamp_token") or ""
    provider_events = [response["event"]]
    if not tsa_token and EDOC_TSA_URL:
        tsa_response = request_formal_tsa_token(digest, digest_payload["timestamp"], signature_id)
        tsa_token = tsa_response["token"]
        provider_events.append(tsa_response["event"])
    return {
        "algorithm": result.get("algorithm") or "RSA-PSS-SHA256",
        "signature_value": signature_value,
        "tsa_token": tsa_token,
        "provider_receipt": result.get("receipt") or result.get("provider_receipt") or result,
        "provider_request_id": result.get("request_id") or result.get("provider_request_id") or request_id,
        "provider_status": result.get("status") or "signed",
        "provider_events": provider_events,
    }


def request_formal_tsa_token(digest: str, timestamp: str, signature_id: str = "") -> Dict[str, Any]:
    if EDOC_SIGNATURE_PROVIDER == "local-simulation":
        return {
            "token": hmac.new(signature_secret(), f"TSA|{digest}|{timestamp}".encode("utf-8"), hashlib.sha256).hexdigest().upper(),
            "event": {},
        }
    if not EDOC_TSA_URL or not EDOC_TSA_API_KEY:
        raise ValueError("formal_tsa_not_configured")
    response = provider_json_request(
        EDOC_TSA_URL,
        {"digest_sha256": digest, "policy_oid": EDOC_TSA_POLICY_OID, "timestamp": timestamp, "signature_id": signature_id},
        EDOC_TSA_API_KEY,
        operation="tsa",
    )
    result = response["data"]
    token = result.get("tsa_token") or result.get("timestamp_token") or result.get("token")
    if not token:
        raise ValueError("formal_tsa_missing_token")
    return {"token": token, "event": response["event"]}


def canonical_signature_payload(payload: Dict[str, Any]) -> str:
    return json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def parse_date_value(value: str) -> datetime | None:
    if not value:
        return None
    for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
        try:
            return datetime.strptime(value[:19], fmt)
        except ValueError:
            continue
    return None


def certificate_type_label(certificate: Dict[str, Any]) -> str:
    labels = {
        "natural_person": "自然人憑證",
        "business": "工商憑證",
        "organization": "組織憑證",
        "tsa": "時間戳憑證",
    }
    return labels.get(certificate.get("certificate_type") or "organization", "組織憑證")


def tsa_token_valid(signature: Dict[str, Any]) -> bool:
    proof = {}
    try:
        proof = json.loads(signature.get("non_repudiation_json") or "{}")
    except json.JSONDecodeError:
        return False
    timestamp = proof.get("timestamp")
    token = signature.get("tsa_token") or proof.get("tsa_token")
    digest = signature.get("digest_sha256") or ""
    if not timestamp or not token or not digest:
        return False
    if EDOC_SIGNATURE_PROVIDER != "local-simulation":
        return bool(EDOC_TSA_URL and token)
    expected = hmac.new(signature_secret(), f"TSA|{digest}|{timestamp}".encode("utf-8"), hashlib.sha256).hexdigest().upper()
    return hmac.compare_digest(expected, str(token).upper())


def validate_certificate_legality(
    conn: sqlite3.Connection,
    certificate: Dict[str, Any],
    signature: Dict[str, Any] | None = None,
    validator: str = "Certificate Worker",
) -> Dict[str, Any]:
    checked_at = now()
    today = datetime.now()
    valid_from = parse_date_value(certificate.get("valid_from") or "")
    valid_to = parse_date_value(certificate.get("valid_to") or "")
    is_active = certificate.get("status") == "啟用"
    is_within_validity = (valid_from is None or valid_from <= today) and (valid_to is None or today <= valid_to + timedelta(days=1))
    revoked = any(keyword in (certificate.get("status") or "") for keyword in ("撤銷", "停用", "註銷"))
    service = signing_service_status()
    ca = conn.execute(
        "SELECT * FROM certificate_authorities WHERE trust_status = 'trusted' AND (? LIKE '%' || name || '%' OR ? LIKE '%' || subject || '%' OR ? LIKE '%' || issuer || '%') ORDER BY rowid LIMIT 1",
        (certificate.get("issuer") or "", certificate.get("issuer") or "", certificate.get("issuer") or ""),
    ).fetchone()
    trusted_issuer = bool(ca) or ((not is_production()) and "Internal CA" in (certificate.get("issuer") or ""))
    chain_status = "有效" if is_active and is_within_validity and trusted_issuer else "憑證鏈異常"
    ocsp_url = certificate.get("ocsp_url") or EDOC_OCSP_RESPONDER_URL
    crl_url = certificate.get("crl_url") or EDOC_CRL_DISTRIBUTION_URL
    tsa_url = certificate.get("tsa_url") or EDOC_TSA_URL
    if revoked:
        ocsp_status = "已撤銷"
        crl_status = "已列入撤銷清單"
    else:
        ocsp_status = "良好" if ocsp_url else "無法查詢"
        crl_status = "未列入撤銷清單" if crl_url else "無法查詢"
    tsa_status = "不適用"
    if signature:
        tsa_status = "有效" if tsa_token_valid(signature) else "時間戳無效"
        if not tsa_url:
            tsa_status = "TSA 未設定"
    if is_production() and service["productionBlocked"]:
        chain_status = "正式憑證服務未設定"
    result = "通過" if chain_status == "有效" and ocsp_status == "良好" and crl_status == "未列入撤銷清單" and tsa_status in {"有效", "不適用"} else "不通過"
    report = {
        "ok": result == "通過",
        "certificate_id": certificate["id"],
        "certificate_type": certificate_type_label(certificate),
        "serial_no": certificate.get("serial_no"),
        "issuer": certificate.get("issuer"),
        "chain_status": chain_status,
        "ocsp_status": ocsp_status,
        "crl_status": crl_status,
        "tsa_status": tsa_status,
        "checked_at": checked_at,
        "ocsp_url": ocsp_url,
        "crl_url": crl_url,
        "tsa_url": tsa_url,
        "service_status": service,
        "trusted_ca": row_to_dict(ca) if ca else None,
        "result": result,
    }
    event_id = f"CVAL-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    conn.execute(
        """
        INSERT INTO certificate_validation_events (
          id, certificate_id, signature_id, validator, validation_type, chain_status, ocsp_status,
          crl_status, tsa_status, result, report_json, checked_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            event_id,
            certificate["id"],
            signature["id"] if signature else None,
            validator,
            "chain+ocsp+crl+tsa" if signature else "chain+ocsp+crl",
            chain_status,
            ocsp_status,
            crl_status,
            tsa_status,
            result,
            json.dumps(report, ensure_ascii=False),
            checked_at,
        ),
    )
    conn.execute(
        """
        UPDATE signing_certificates
        SET chain_status = ?, ocsp_status = ?, crl_status = ?, last_validated_at = ?, validation_report_json = ?
        WHERE id = ?
        """,
        (chain_status, ocsp_status, crl_status, checked_at, json.dumps(report, ensure_ascii=False), certificate["id"]),
    )
    if signature:
        conn.execute(
            """
            UPDATE electronic_signatures
            SET certificate_validation_id = ?, chain_status = ?, ocsp_status = ?, crl_status = ?, tsa_status = ?
            WHERE id = ?
            """,
            (event_id, chain_status, ocsp_status, crl_status, tsa_status, signature["id"]),
        )
        conn.execute(
            """
            INSERT OR REPLACE INTO tsa_timestamp_tokens (
              id, signature_id, tsa_name, tsa_url, imprint_sha256, token_value, policy_oid, status, issued_at, verified_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                f"TSA-{signature['id']}",
                signature["id"],
                "Suiyuecare TSA",
                tsa_url or "https://tsa.suiyuecare.local/rfc3161",
                signature.get("digest_sha256") or "",
                signature.get("tsa_token") or "",
                EDOC_TSA_POLICY_OID,
                tsa_status,
                signature.get("created_at") or checked_at,
                checked_at,
            ),
        )
    report["event_id"] = event_id
    return report


def create_electronic_signature(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    service = signing_service_status()
    if service["productionBlocked"]:
        raise ValueError(f"formal_signing_service_not_ready:{','.join(service['missing'])}")
    document = get_or_create_pdf_document(conn, payload)
    pdf_version_id = payload.get("pdf_version_id") or payload.get("version_id") or ""
    file_object_id = payload.get("file_object_id") or ""
    version = None
    if pdf_version_id and not file_object_id:
        version = conn.execute("SELECT * FROM pdf_versions WHERE id = ?", (pdf_version_id,)).fetchone()
        if version:
            file_object_id = version["file_object_id"]
    file_row = conn.execute("SELECT * FROM file_objects WHERE id = ?", (file_object_id,)).fetchone() if file_object_id else None
    file_hash = file_row["sha256"] if file_row else payload.get("digest_sha256") or sha256_bytes(canonical_signature_payload(payload.get("document") or document).encode("utf-8"))
    signer = payload.get("signer") or payload.get("approver") or "行政部主任"
    certificate = active_certificate(conn, payload.get("certificate_id") or "", signer)
    previous = latest_signature(conn, document["id"])
    timestamp = now()
    signature_id = f"ESIG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    digest_payload = {
        "signature_id": signature_id,
        "document_id": document["id"],
        "doc_no": document["doc_no"],
        "file_hash": file_hash,
        "signature_type": payload.get("signature_type") or "seal",
        "certificate_fingerprint": certificate["fingerprint_sha256"],
        "previous_signature": previous["signature_value"] if previous else "",
        "timestamp": timestamp,
    }
    digest = sha256_bytes(canonical_signature_payload(digest_payload).encode("utf-8"))
    try:
        formal_signature = request_formal_signature(digest_payload, digest, certificate, signer, signature_id)
    except SignatureProviderError as exc:
        if exc.event:
            record_signature_provider_event(conn, exc.event, document["id"], signature_id)
        log_audit(conn, signer, "正式電子簽章失敗", "documents", document["id"], f"{signature_id} / {exc}")
        raise
    signature_value = formal_signature["signature_value"]
    tsa_token = formal_signature["tsa_token"]
    for event in formal_signature.get("provider_events") or []:
        if event:
            record_signature_provider_event(conn, event, document["id"], signature_id)
    non_repudiation = {
        "version": "SYC-EDOC-SIGNATURE-EVIDENCE-1",
        "signer": signer,
        "provider": EDOC_SIGNATURE_PROVIDER,
        "provider_key_id": EDOC_SIGNATURE_KEY_ID,
        "provider_request_id": formal_signature.get("provider_request_id") or "",
        "provider_status": formal_signature.get("provider_status") or "",
        "signature_profile": EDOC_SIGNATURE_PROFILE,
        "provider_receipt": formal_signature.get("provider_receipt", {}),
        "certificate_serial": certificate["serial_no"],
        "certificate_fingerprint": certificate["fingerprint_sha256"],
        "timestamp": timestamp,
        "tsa_token": tsa_token,
        "file_hash": file_hash,
        "digest_payload": digest_payload,
        "digest_payload_sha256": digest,
        "previous_signature_id": previous["id"] if previous else "",
        "ip": payload.get("ip") or "system",
        "device": payload.get("device") or "server",
        "operation": payload.get("operation") or "PDF 電子簽章/押章",
    }
    evidence_digest = sha256_bytes(canonical_signature_payload(non_repudiation).encode("utf-8"))
    non_repudiation["evidence_digest_sha256"] = evidence_digest
    row = {
        "id": signature_id,
        "document_id": document["id"],
        "pdf_version_id": pdf_version_id or (version["id"] if version else None),
        "file_object_id": file_object_id or None,
        "certificate_id": certificate["id"],
        "signer": signer,
        "signature_type": payload.get("signature_type") or "seal",
        "algorithm": formal_signature["algorithm"],
        "digest_sha256": digest,
        "signature_value": signature_value,
        "tsa_token": tsa_token,
        "previous_signature_id": previous["id"] if previous else None,
        "non_repudiation_json": json.dumps(non_repudiation, ensure_ascii=False),
        "verified_at": timestamp,
        "status": "有效",
        "created_at": timestamp,
        "provider": EDOC_SIGNATURE_PROVIDER,
        "provider_key_id": EDOC_SIGNATURE_KEY_ID,
        "provider_request_id": formal_signature.get("provider_request_id") or "",
        "provider_receipt_json": json.dumps(formal_signature.get("provider_receipt", {}), ensure_ascii=False),
        "evidence_digest_sha256": evidence_digest,
    }
    insert_row(conn, "electronic_signatures", row)
    validation = validate_certificate_legality(conn, certificate, row, signer)
    row.update({
        "certificate_validation_id": validation["event_id"],
        "chain_status": validation["chain_status"],
        "ocsp_status": validation["ocsp_status"],
        "crl_status": validation["crl_status"],
        "tsa_status": validation["tsa_status"],
        "status": "有效" if validation["ok"] else "憑證驗證失敗",
    })
    conn.execute(
        "UPDATE electronic_signatures SET certificate_validation_id = ?, chain_status = ?, ocsp_status = ?, crl_status = ?, tsa_status = ?, status = ? WHERE id = ?",
        (row["certificate_validation_id"], row["chain_status"], row["ocsp_status"], row["crl_status"], row["tsa_status"], row["status"], row["id"]),
    )
    log_audit(conn, signer, "正式電子簽章", "documents", document["id"], f"{signature_id} / {digest}")
    return {**row, "certificate": certificate, "non_repudiation": non_repudiation, "certificate_validation": validation}


def verify_signature_value_with_provider(conn: sqlite3.Connection, signature: Dict[str, Any], certificate: Dict[str, Any]) -> Dict[str, Any]:
    try:
        proof = json.loads(signature.get("non_repudiation_json") or "{}")
    except json.JSONDecodeError:
        proof = {}
    digest_payload = proof.get("digest_payload") if isinstance(proof.get("digest_payload"), dict) else {}
    if EDOC_SIGNATURE_PROVIDER == "local-simulation":
        expected = hmac.new(signature_secret(), canonical_signature_payload(digest_payload).encode("utf-8"), hashlib.sha256).hexdigest().upper() if digest_payload else ""
        ok = bool(expected) and hmac.compare_digest(expected, str(signature.get("signature_value") or "").upper())
        return {"ok": ok, "mode": "local-simulation", "status": "簽章值有效" if ok else "簽章值不符"}
    if not EDOC_SIGNATURE_API_URL or not EDOC_SIGNATURE_API_KEY:
        return {"ok": False, "mode": "formal", "status": "簽章驗證 provider 未設定"}
    try:
        response = provider_json_request(
            f"{EDOC_SIGNATURE_API_URL}/verify",
            {
                "signature_id": signature["id"],
                "request_id": f"SIGVERIFY-{signature['id']}",
                "signature_profile": proof.get("signature_profile") or EDOC_SIGNATURE_PROFILE,
                "certificate_id": certificate["id"],
                "certificate_serial": certificate.get("serial_no"),
                "digest_sha256": signature.get("digest_sha256"),
                "signature_value": signature.get("signature_value"),
                "tsa_token": signature.get("tsa_token"),
                "payload": digest_payload,
            },
            EDOC_SIGNATURE_API_KEY,
            operation="verify",
        )
        record_signature_provider_event(conn, response["event"], signature.get("document_id") or "", signature["id"])
        data = response["data"]
        ok = bool(data.get("ok", data.get("valid", False)))
        return {"ok": ok, "mode": "formal", "status": data.get("status") or ("簽章值有效" if ok else "簽章值不符"), "provider_receipt": data}
    except SignatureProviderError as exc:
        if exc.event:
            record_signature_provider_event(conn, exc.event, signature.get("document_id") or "", signature["id"])
        return {"ok": False, "mode": "formal", "status": str(exc)}


def verify_electronic_signature(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    signature_id = payload.get("signature_id")
    row = conn.execute("SELECT * FROM electronic_signatures WHERE id = ?", (signature_id,)).fetchone() if signature_id else None
    if not row:
        return {"ok": False, "error": "signature_not_found"}
    signature = row_to_dict(row)
    file_hash = signature["digest_sha256"]
    if signature.get("file_object_id"):
        file_row = conn.execute("SELECT * FROM file_objects WHERE id = ?", (signature["file_object_id"],)).fetchone()
        if file_row:
            path = STORAGE_DIR / file_row["storage_key"]
            file_data = decrypt_file_bytes(path.read_bytes(), file_row["encryption_status"], file_row["encryption_alg"]) if path.exists() else b""
            file_hash_ok = bool(file_data) and sha256_bytes(file_data) == file_row["sha256"]
        else:
            file_hash_ok = False
    else:
        file_hash_ok = True
    cert_row = conn.execute("SELECT * FROM signing_certificates WHERE id = ?", (signature["certificate_id"],)).fetchone()
    if not cert_row:
        return {"ok": False, "error": "certificate_not_found", "signature": signature}
    certificate = row_to_dict(cert_row)
    signature_value_check = verify_signature_value_with_provider(conn, signature, certificate)
    validation = validate_certificate_legality(conn, certificate, signature, payload.get("validator") or "Signature Verifier")
    ok = file_hash_ok and signature_value_check["ok"] and validation["ok"]
    status = "有效" if ok else "憑證驗證失敗" if file_hash_ok and signature_value_check["ok"] else "簽章值異常" if file_hash_ok else "雜湊異常"
    conn.execute("UPDATE electronic_signatures SET verified_at = ?, status = ? WHERE id = ?", (now(), status, signature_id))
    return {"ok": ok, "signature": signature, "digest": file_hash, "status": status, "signature_value_check": signature_value_check, "certificate_validation": validation}


def validate_certificate_api(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    certificate_id = payload.get("certificate_id") or payload.get("id")
    row = conn.execute("SELECT * FROM signing_certificates WHERE id = ?", (certificate_id,)).fetchone() if certificate_id else None
    if not row:
        return {"ok": False, "error": "certificate_not_found"}
    signature = None
    if payload.get("signature_id"):
        signature_row = conn.execute("SELECT * FROM electronic_signatures WHERE id = ?", (payload["signature_id"],)).fetchone()
        signature = row_to_dict(signature_row) if signature_row else None
    result = validate_certificate_legality(conn, row_to_dict(row), signature, payload.get("validator") or "Certificate Verifier")
    log_audit(conn, payload.get("validator") or "Certificate Verifier", "憑證合法性驗證", "signing_certificates", certificate_id, result["result"] if "result" in result else result["chain_status"])
    return result


def certificate_health(conn: sqlite3.Connection) -> Dict[str, Any]:
    certificates = [row_to_dict(row) for row in conn.execute("SELECT * FROM signing_certificates ORDER BY rowid").fetchall()]
    authorities = [row_to_dict(row) for row in conn.execute("SELECT * FROM certificate_authorities ORDER BY rowid").fetchall()]
    events = [row_to_dict(row) for row in conn.execute("SELECT * FROM certificate_validation_events ORDER BY rowid DESC LIMIT 8").fetchall()]
    provider_events = [row_to_dict(row) for row in conn.execute("SELECT * FROM signature_provider_events ORDER BY rowid DESC LIMIT 8").fetchall()]
    service = signing_service_status()
    return {
        "mode": service["mode"],
        "ready": service["ready"],
        "certificate_count": len(certificates),
        "trusted_ca_count": len([item for item in authorities if item.get("trust_status") == "trusted"]),
        "services": {
            "provider": "啟用" if service["services"]["provider"]["configured"] else "仍為模擬",
            "providerApi": "啟用" if service["services"]["providerApi"]["configured"] else "未設定簽章 API",
            "providerCredential": "啟用" if service["services"]["providerCredential"]["configured"] else "未設定簽章 API key",
            "keyId": "啟用" if service["services"]["keyId"]["configured"] else "未設定簽章 key id",
            "chain": "啟用" if service["services"]["trustStore"]["configured"] else "未設定信任根",
            "tsa": "啟用" if service["services"]["tsa"]["configured"] else "未設定 TSA",
            "tsaCredential": "啟用" if service["services"]["tsaCredential"]["configured"] else "未設定 TSA API key",
            "ocsp": "啟用" if service["services"]["ocsp"]["configured"] else "未設定 OCSP",
            "crl": "啟用" if service["services"]["crl"]["configured"] else "未設定 CRL",
            "hsm": "啟用" if service["services"]["hsm"]["configured"] else "未設定 HSM/KMS",
        },
        "service": service,
        "policy": service.get("policy", {}),
        "certificates": certificates,
        "authorities": authorities,
        "recent_events": events,
        "provider_events": provider_events,
    }


def pdf_render_document(document: Dict[str, Any], payload: Dict[str, Any]) -> Dict[str, Any]:
    doc_payload = payload.get("document") or {}
    merged = {**document, **doc_payload}
    company_name = payload.get("company_name") or doc_payload.get("companyName") or doc_payload.get("company_name") or document.get("company_name")
    if company_name:
        merged["company_name"] = company_name
    contact_fields = {
        "contactAddress": "contactAddress",
        "contactOwner": "contactOwner",
        "contactPhone": "contactPhone",
        "contactFax": "contactFax",
        "contactEmail": "contactEmail",
    }
    for target, source in contact_fields.items():
        if doc_payload.get(source):
            merged[target] = doc_payload[source]
    return merged


def pdf_seal_plan(payload: Dict[str, Any], document: Dict[str, Any]) -> Dict[str, Any]:
    doc_payload = payload.get("document") or {}
    for value in (
        payload.get("seal_plan"),
        payload.get("sealPlan"),
        doc_payload.get("seal_plan"),
        doc_payload.get("sealPlan"),
        document.get("seal_plan_json"),
    ):
        parsed = parse_json_field(value)
        if parsed:
            return parsed
    return {}


def stamp_from_percentage(placement: Dict[str, Any], width: float, height: float, default_x: float, default_y: float, page_count: int) -> Tuple[int, float, float]:
    page = int(pdf_safe_float(placement.get("page"), 1))
    page = max(1, min(page, page_count))
    center_x = A4_WIDTH_PT * pdf_safe_float(placement.get("x"), default_x) / 100
    center_y_from_top = A4_HEIGHT_PT * pdf_safe_float(placement.get("y"), default_y) / 100
    return page, center_x - width / 2, A4_HEIGHT_PT - center_y_from_top - height / 2


def pdf_stamp_definitions(payload: Dict[str, Any], document: Dict[str, Any], stamp_no: str, page_count: int) -> List[Dict[str, Any]]:
    coordinates = payload.get("coordinates") or {}
    seal_plan = pdf_seal_plan(payload, document)
    if str(seal_plan.get("mode") or seal_plan.get("deliveryMode") or "").strip().lower() == "electronic_exchange":
        raise ValueError("official_document_stamp_required")
    explicit_positions = payload.get("stamp_positions") or payload.get("stamps") or payload.get("positions")
    if explicit_positions:
        stamps: List[Dict[str, Any]] = []
        for position in normalized_stamp_positions({"stamp_positions": explicit_positions, "seal_id": payload.get("seal_id") or ""}):
            page_value = position.get("page", 1)
            target_pages = range(1, page_count + 1) if page_value == "all" else [max(1, min(page_count, int(page_value)))]
            for page in target_pages:
                x, y, width, height = clamp_pdf_rect(
                    pdf_safe_float(position.get("x"), 420.0),
                    pdf_safe_float(position.get("y"), 120.0),
                    pdf_safe_float(position.get("w"), 56.0),
                    pdf_safe_float(position.get("h"), 56.0),
                )
                stamps.append({
                    **position,
                    "page": page,
                    "x": x,
                    "y": y,
                    "w": width,
                    "h": height,
                    "stamp_no": stamp_no,
                    "source": "stamp_positions",
                })
        return stamps
    stamps: List[Dict[str, Any]] = []
    seal_specs = [
        ("large", "公司大章", 70.0, 80.0, "company_width_mm", "company_height_mm", 30.0),
        ("small", "公司小章", 84.0, 80.0, "owner_width_mm", "owner_height_mm", 18.0),
    ]
    if seal_plan:
        for kind, label, default_x, default_y, width_key, height_key, fallback_mm in seal_specs:
            plan = seal_plan.get(kind) if isinstance(seal_plan.get(kind), dict) else {}
            seal_type = str(plan.get("type") or "無")
            if seal_type in {"無", "電子公文交換"}:
                continue
            width = mm_to_pdf_points(plan.get("widthMm") or plan.get("width_mm") or coordinates.get(width_key), fallback_mm)
            height = mm_to_pdf_points(plan.get("heightMm") or plan.get("height_mm") or coordinates.get(height_key), fallback_mm)
            placement = plan.get("placement") if isinstance(plan.get("placement"), dict) else {}
            page, x, y = stamp_from_percentage(placement, width, height, default_x, default_y, page_count)
            x, y, width, height = clamp_pdf_rect(x, y, width, height)
            stamps.append({"page": page, "x": x, "y": y, "w": width, "h": height, "label": label, "type": seal_type, "stamp_no": stamp_no, "source": "seal_plan"})
    else:
        company_width = mm_to_pdf_points(coordinates.get("company_width_mm"), 30.0)
        company_height = mm_to_pdf_points(coordinates.get("company_height_mm"), 30.0)
        owner_width = mm_to_pdf_points(coordinates.get("owner_width_mm"), 18.0)
        owner_height = mm_to_pdf_points(coordinates.get("owner_height_mm"), 18.0)
        stamps = [
            {"page": 1, "x": pdf_safe_float(coordinates.get("company_x"), 420), "y": pdf_safe_float(coordinates.get("company_y"), 130), "w": company_width, "h": company_height, "label": "公司大章", "type": "一般章", "stamp_no": stamp_no, "source": "legacy_coordinates"},
            {"page": 1, "x": pdf_safe_float(coordinates.get("owner_x"), 470), "y": pdf_safe_float(coordinates.get("owner_y"), 130), "w": owner_width, "h": owner_height, "label": "公司小章", "type": "一般章", "stamp_no": stamp_no, "source": "legacy_coordinates"},
        ]
    if coordinates.get("multi_page") and page_count > 1:
        for page in range(1, page_count + 1):
            stamps.append({"page": page, "x": A4_WIDTH_PT - 24, "y": A4_HEIGHT_PT / 2 - 36, "w": 18, "h": 72, "label": "騎縫章", "type": "多頁章", "stamp_no": stamp_no, "source": "page_seal"})
    return stamps


def pdf_coordinates_with_layout(coordinates: Dict[str, Any], package: Dict[str, Any], stamps: List[Dict[str, Any]] | None = None) -> Dict[str, Any]:
    enriched = {**coordinates, **package.get("layout", {})}
    if stamps is not None:
        enriched["stamp_positions"] = [
            {key: stamp.get(key) for key in ("page", "x", "y", "w", "h", "label", "type", "source")}
            for stamp in stamps
        ]
    return enriched


def pdf_generate(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    document = get_or_create_pdf_document(conn, payload)
    template = payload.get("template") or "歲悅正式函"
    coordinates = payload.get("coordinates") or {}
    min_page_count = 2 if coordinates.get("multi_page") else 1
    package = build_official_pdf_package(pdf_render_document(document, payload), [], template, min_page_count)
    version = create_pdf_version(conn, document, "before_seal", template, package["data"], pdf_coordinates_with_layout(coordinates, package, []))
    log_audit(conn, "PDF Worker", "產生公文 PDF 套版", "documents", document["id"], version["sha256"])
    return version


def pdf_stamp(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    trusted_seal_asset = payload.get("_trusted_seal_asset")
    if (
        not isinstance(trusted_seal_asset, dict)
        or not isinstance(trusted_seal_asset.get("data"), bytes)
        or not trusted_seal_asset.get("data")
    ):
        # The old /api/pdf/stamp endpoint used drawn placeholders and had no
        # immutable Seal Vault id/hash.  It may still generate an unstamped PDF
        # through /api/pdf/generate, but it cannot produce a formal institution
        # seal.  Authorized workflows call this function with server-read bytes.
        raise ValueError("seal_vault_file_required_for_institution_seal")
    document = get_or_create_pdf_document(conn, payload)
    template = payload.get("template") or "歲悅正式函"
    coordinates = payload.get("coordinates") or {}
    doc_digits = "".join(ch for ch in document["doc_no"] if ch.isdigit())[-10:] or str(int(time.time()))
    stamp_no = payload.get("stamp_no") or f"STAMP-{doc_digits}-{int(time.time())}"
    previous = latest_pdf_version(conn, document["id"], "before_seal") or pdf_generate(conn, payload)
    min_page_count = 2 if coordinates.get("multi_page") else 1
    dry_package = build_official_pdf_package(pdf_render_document(document, payload), [], template, min_page_count)
    stamps = pdf_stamp_definitions(payload, document, stamp_no, int(dry_package["layout"]["page_count"]))
    stamped_data, stamp_engine, _stamp_metadata = stamp_uploaded_pdf_bytes(
        dry_package["data"],
        stamps,
        stamp_no,
        seal_asset=trusted_seal_asset,
        source_text_on_top=True,
    )
    package = {**dry_package, "data": stamped_data}
    version = create_pdf_version(
        conn,
        document,
        "after_seal",
        template,
        package["data"],
        {
            **pdf_coordinates_with_layout(coordinates, package, stamps),
            "stamp_engine": stamp_engine,
            "seal_image_applied": bool(trusted_seal_asset),
        },
        stamp_no,
        previous["id"],
    )
    application_id = payload.get("application_id") or f"USEAL-{int(time.time() * 1000)}"
    conn.execute(
        """
        INSERT OR REPLACE INTO seal_applications (
          id, document_id, seal_id, applicant, approver, status, reason, stamp_no,
          pdf_before_version_id, pdf_after_version_id, provider_status, failure_reason,
          evidence_json, updated_at, created_at, approved_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, COALESCE((SELECT created_at FROM seal_applications WHERE id = ?), ?), ?)
        """,
        (
            application_id,
            document["id"],
            payload.get("seal_id") or "SEAL-001",
            payload.get("applicant") or "總務",
            payload.get("approver") or "行政部主任",
            "已押章",
            payload.get("reason") or "簽核完成後自動用印",
            stamp_no,
            previous["id"],
            version["id"],
            "待簽章",
            "",
            json.dumps({"pdf_after_sha256": version["sha256"], "stamp_positions": version.get("coordinates", {}).get("stamp_positions", [])}, ensure_ascii=False),
            now(),
            application_id,
            now(),
            now(),
        ),
    )
    signature = create_electronic_signature(conn, {
        **payload,
        "document_id": document["id"],
        "pdf_version_id": version["id"],
        "file_object_id": version["file_object_id"],
        "signature_type": "seal",
        "signer": payload.get("approver") or "行政部主任",
        "operation": f"核准用印並自動押章 {stamp_no}",
    })
    conn.execute(
        """
        UPDATE seal_applications
        SET signature_id = ?, provider_status = ?, failure_reason = '', evidence_json = ?, updated_at = ?
        WHERE id = ?
        """,
        (
            signature["id"],
            "簽章完成" if signature.get("status") == "有效" else signature.get("status") or "簽章完成",
            json.dumps({
                "pdf_after_sha256": version["sha256"],
                "signature_id": signature["id"],
                "signature_digest": signature.get("digest_sha256"),
                "evidence_digest_sha256": signature.get("evidence_digest_sha256"),
                "provider": signature.get("provider"),
                "provider_request_id": signature.get("provider_request_id"),
                "stamp_positions": version.get("coordinates", {}).get("stamp_positions", []),
            }, ensure_ascii=False),
            now(),
            application_id,
        ),
    )
    log_audit(conn, "PDF Worker", "自動押章 PDF", "documents", document["id"], f"{stamp_no} / {version['sha256']} / {signature['id']}")
    return {**version, "stamp_no": stamp_no, "application_id": application_id, "signature": signature}


def pdf_verify(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    file_id = payload.get("file_object_id")
    version_id = payload.get("version_id")
    if version_id and not file_id:
        version = conn.execute("SELECT * FROM pdf_versions WHERE id = ?", (version_id,)).fetchone()
        if version:
            file_id = version["file_object_id"]
    row = conn.execute("SELECT * FROM file_objects WHERE id = ?", (file_id,)).fetchone() if file_id else None
    if not row:
        return {"ok": False, "error": "file_not_found"}
    file_row = row_to_dict(row)
    path = STORAGE_DIR / file_row["storage_key"]
    raw = path.read_bytes() if path.exists() else b""
    actual = sha256_bytes(decrypt_file_bytes(raw, file_row.get("encryption_status", ""), file_row.get("encryption_alg", ""))) if raw else ""
    return {"ok": actual == file_row["sha256"], "expected": file_row["sha256"], "actual": actual, "file": file_row}


def compute_next_run_at(schedule_text: str, base: datetime | None = None) -> str:
    base = base or datetime.now()
    if "15 分鐘" in schedule_text:
        next_run = base + timedelta(minutes=15)
    elif "每小時" in schedule_text:
        next_run = base + timedelta(hours=1)
    elif "18:00" in schedule_text:
        next_run = base.replace(hour=18, minute=0, second=0, microsecond=0)
        if next_run <= base:
            next_run += timedelta(days=1)
    elif "09:00" in schedule_text:
        next_run = base.replace(hour=9, minute=0, second=0, microsecond=0)
        if next_run <= base:
            next_run += timedelta(days=1)
    else:
        next_run = base.replace(hour=8, minute=30, second=0, microsecond=0)
        if next_run <= base:
            next_run += timedelta(days=1)
    return next_run.strftime("%Y-%m-%d %H:%M:%S")


def scalar_int(conn: sqlite3.Connection, sql: str, params: Tuple[Any, ...] = ()) -> int:
    return int(conn.execute(sql, params).fetchone()[0])


def execute_job_logic(conn: sqlite3.Connection, job: Dict[str, Any]) -> Dict[str, Any]:
    job_type = job["job_type"]
    if job_type == "pullInbound":
        result = pull_inbound(conn)
        return {"message": f"成功：拉取 {result.get('count', 0)} 筆收文 {result.get('created', '')}", "payload": result}

    if job_type == "exchangeSendPending":
        assert_formal_exchange_allowed({})
        result = create_exchange_gateway(conn).sendPendingOfficialDocuments()
        return {"message": f"成功：送出 {result['count']} 筆待發交換公文", "payload": result}

    if job_type == "exchangeRetryFailed":
        assert_formal_exchange_allowed({})
        result = create_exchange_gateway(conn).retryFailedDeliveries()
        return {"message": f"成功：重送 {result['count']} 筆交換失敗公文", "payload": result}

    if job_type == "nextDayCheck":
        rows = conn.execute("SELECT * FROM exchange_tasks WHERE direction = '發文'").fetchall()
        checked = 0
        for row in rows:
            checked += 1
            status = "已確認收文" if row["status"] not in {"交換失敗", "退回補正"} else row["status"]
            conn.execute("UPDATE exchange_tasks SET status = ?, updated_at = ?, next_check_at = ? WHERE id = ?", (status, now(), compute_next_run_at("每日 09:00"), row["id"]))
            conn.execute(
                "INSERT INTO exchange_events (id, task_id, document_id, event_type, message, payload_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                (f"EVT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}", row["id"], row["document_id"], "next_day_check", "背景任務完成發文翌日查核。", "{}", now()),
            )
        return {"message": f"成功：完成 {checked} 筆發文翌日查核", "payload": {"checked": checked}}

    if job_type == "tokenCheck":
        active_sessions = scalar_int(conn, "SELECT COUNT(*) FROM auth_sessions WHERE revoked_at IS NULL AND expires_at > ?", (now(),))
        expiring = scalar_int(conn, "SELECT COUNT(*) FROM auth_sessions WHERE revoked_at IS NULL AND expires_at <= ?", ((datetime.now() + timedelta(hours=1)).strftime("%Y-%m-%d %H:%M:%S"),))
        detail = f"active_sessions={active_sessions}, expiring_in_1h={expiring}"
        log_audit(conn, "Scheduler", "Token 到期檢查", "auth_sessions", "tokenCheck", detail)
        return {"message": f"成功：有效 session {active_sessions}，1 小時內到期 {expiring}", "payload": {"active_sessions": active_sessions, "expiring": expiring}}

    if job_type == "overdueReminder":
        overdue_docs = conn.execute("SELECT * FROM documents WHERE due_date IS NOT NULL AND due_date <> '' AND due_date < ? AND status NOT LIKE '%完成%'", (datetime.now().strftime("%Y-%m-%d"),)).fetchall()
        for doc in overdue_docs:
            log_audit(conn, "Scheduler", "逾期稽催", "documents", doc["id"], f"{doc['doc_no']} / {doc['owner']} / {doc['due_date']}")
        return {"message": f"成功：產生 {len(overdue_docs)} 筆逾期稽催紀錄", "payload": {"overdue": len(overdue_docs)}}

    if job_type == "contractRenewalCheck":
        rows = conn.execute("SELECT * FROM contracts WHERE end_date IS NOT NULL AND end_date <> '' AND status NOT IN ('已終止','已作廢')").fetchall()
        due_contracts = []
        notified = 0
        today = datetime.now().date()
        for row in rows:
            end_date = parse_time(row["end_date"]).date()
            alert_days = int(row["renewal_alert_days"] or 60)
            days_left = (end_date - today).days
            if 0 <= days_left <= alert_days:
                due_contracts.append(row)
                target = exact_sqlite_notification_target_from_metadata(
                    conn,
                    row["metadata_json"],
                )
                if not target:
                    log_structured(
                        "warning",
                        "contract_renewal_notification_skipped",
                        contract_id=row["id"],
                        error="notification_exact_target_required",
                    )
                    continue
                notice = create_notification(conn, {
                    "type": "合約續約",
                    "title": f"{row['title']} 即將到期",
                    **exact_notification_target_payload(target, target.get("company_id") or ""),
                    "channel": "Email + 系統通知",
                    "priority": "高" if days_left <= 30 else "中",
                    "source": row["contract_no"],
                    "body": f"{row['counterparty']} 合約將於 {row['end_date']} 到期，剩餘 {days_left} 天，請確認續約、重簽或終止。",
                })
                notified += 1
                log_audit(conn, "Scheduler", "合約續約提醒", "contracts", row["id"], notice["id"])
        skipped = len(due_contracts) - notified
        return {
            "message": f"成功：找到 {len(due_contracts)} 筆到期合約，精準投遞 {notified} 筆，略過 {skipped} 筆未綁定對象資料。",
            "payload": {
                "dueContracts": len(due_contracts),
                "notified": notified,
                "skipped": skipped,
            },
        }

    if job_type == "exchangeSync":
        assert_formal_exchange_allowed({})
        gateway_result = create_exchange_gateway(conn).queryPendingDeliveryStatuses()
        rows = conn.execute("SELECT * FROM exchange_tasks").fetchall()
        for row in rows:
            conn.execute(
                "INSERT INTO exchange_events (id, task_id, document_id, event_type, message, payload_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                (f"EVT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}", row["id"], row["document_id"], "status_sync", f"背景任務同步交換狀態：{row['status']}", json.dumps({"status": row["status"]}, ensure_ascii=False), now()),
            )
        return {"message": f"成功：同步 {gateway_result['count']} 筆新介接層狀態，保留 {len(rows)} 筆舊交換事件", "payload": {"synced": gateway_result["count"], "gateway": gateway_result, "legacyEvents": len(rows)}}

    if job_type == "archiveSeal":
        files = conn.execute("SELECT * FROM file_objects").fetchall()
        verified = 0
        failed = 0
        for row in files:
            path = STORAGE_DIR / row["storage_key"]
            ok = path.exists() and sha256_bytes(path.read_bytes()) == row["sha256"]
            verified += 1 if ok else 0
            failed += 0 if ok else 1
        log_audit(conn, "Scheduler", "歸檔封存", "file_objects", "archiveSeal", f"verified={verified}, failed={failed}")
        return {"message": f"成功：歸檔檔案驗證 {verified} 件，異常 {failed} 件", "payload": {"verified": verified, "failed": failed}}

    if job_type == "reportGenerate":
        report = dashboard(conn)
        conn.execute(
            "INSERT OR REPLACE INTO settings (key, value_json, version, updated_at) VALUES (?, ?, COALESCE((SELECT version + 1 FROM settings WHERE key = ?), 1), ?)",
            ("latest_report", json.dumps({"generated_at": now(), **report}, ensure_ascii=False), "latest_report", now()),
        )
        return {"message": f"成功：報表已產生，公文 {report['documents']} 件，交換成功率 {report['successRate']}%", "payload": report}

    return {"message": f"成功：{job_type} 無額外動作", "payload": {}}


def run_background_job(conn: sqlite3.Connection, job_id: str) -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM background_jobs WHERE id = ?", (job_id,)).fetchone()
    if not row:
        return {"error": "not_found", "job_id": job_id}
    job = row_to_dict(row)
    if job["status"] != "啟用":
        return {"id": job_id, "status": "skipped", "result": "任務未啟用"}
    started = datetime.now()
    run_id = f"RUN-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    try:
        result = execute_job_logic(conn, job)
        status = "成功"
        message = result["message"]
        payload = result.get("payload", {})
    except Exception as exc:
        status = "失敗"
        message = str(exc)
        payload = {"error": message}
    finished = datetime.now()
    duration_ms = int((finished - started).total_seconds() * 1000)
    next_run = compute_next_run_at(job["schedule_text"], finished)
    conn.execute(
        """
        INSERT INTO job_runs (id, job_id, job_type, status, result, started_at, finished_at, duration_ms, payload_json)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (run_id, job_id, job["job_type"], status, message, started.strftime("%Y-%m-%d %H:%M:%S"), finished.strftime("%Y-%m-%d %H:%M:%S"), duration_ms, json.dumps(payload, ensure_ascii=False)),
    )
    conn.execute(
        """
        UPDATE background_jobs
        SET last_result = ?, next_run_at = ?, run_count = run_count + 1, updated_at = ?
        WHERE id = ?
        """,
        (f"{status}：{message}", next_run, now(), job_id),
    )
    log_audit(conn, "Scheduler", f"背景任務{status}", "background_jobs", job_id, message)
    return {"run_id": run_id, "job_id": job_id, "status": status, "result": message, "next_run_at": next_run, "duration_ms": duration_ms, "payload": payload}


def run_due_background_jobs(conn: sqlite3.Connection, all_enabled: bool = False) -> Dict[str, Any]:
    if all_enabled:
        rows = conn.execute("SELECT id FROM background_jobs WHERE status = '啟用' ORDER BY next_run_at").fetchall()
    else:
        rows = conn.execute("SELECT id FROM background_jobs WHERE status = '啟用' AND next_run_at <= ? ORDER BY next_run_at", (now(),)).fetchall()
    results = [run_background_job(conn, row["id"]) for row in rows]
    return {"count": len(results), "results": results}


def notification_channels(channel: str | None) -> List[str]:
    normalized = channel or "系統通知"
    channels: List[str] = []
    if "Email" in normalized:
        channels.append("Email")
    if "Line" in normalized or "LINE" in normalized:
        channels.append("Line 工作群組")
    if "系統" in normalized or "站內" in normalized:
        channels.append("系統站內通知")
    return channels or [normalized]


def channel_required_env(channel: str) -> List[str]:
    if channel == "Email":
        return notification_email_required_env()
    if channel == "Line 工作群組":
        if env_present("LINE_WEBHOOK_URL"):
            return ["LINE_WEBHOOK_URL"]
        return ["LINE_WEBHOOK_URL 或 LINE_CHANNEL_ACCESS_TOKEN + LINE_TARGET_ID"]
    if channel == "系統站內通知":
        return ["APP_SECRET"] if env_present("APP_SECRET") else ["CRON_SECRET"]
    return []


def notification_credential_status_for_channel(conn: sqlite3.Connection, channel: str) -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM notification_channel_credentials WHERE channel = ? ORDER BY updated_at DESC LIMIT 1", (channel,)).fetchone()
    if not row:
        return {"channel": channel, "status": "未設定", "ok": False, "error": "credential_not_registered"}
    credential = row_to_dict(row)
    required = channel_required_env(channel)
    if channel == "Line 工作群組" and not env_present("LINE_WEBHOOK_URL"):
        missing = [] if env_present("LINE_CHANNEL_ACCESS_TOKEN") and env_present("LINE_TARGET_ID") else required
    else:
        missing = [name for name in required if not env_present(name)]
    expires_at = credential.get("expires_at") or ""
    expiry = parse_time(expires_at) if expires_at else datetime.max
    days_left = None if expiry == datetime.max else (expiry - datetime.now()).days
    if missing:
        status = "缺少環境憑證"
    elif expiry < datetime.now():
        status = "已到期"
    elif days_left is not None and days_left <= 14:
        status = "即將到期"
    else:
        status = "有效"
    return {**credential, "ok": status == "有效", "status": status, "missing": missing, "days_left": days_left}


def validate_notification_credentials(conn: sqlite3.Connection, channel: str = "") -> Dict[str, Any]:
    channels = [channel] if channel else ["Email", "Line 工作群組", "系統站內通知"]
    checked_at = now()
    results = []
    for item in channels:
        status = notification_credential_status_for_channel(conn, item)
        report = {
            "channel": item,
            "status": status["status"],
            "missing": status.get("missing", []),
            "expires_at": status.get("expires_at") or "",
            "days_left": status.get("days_left"),
            "fingerprint_sha256": status.get("fingerprint_sha256") or "",
            "checked_at": checked_at,
        }
        if status.get("id"):
            conn.execute(
                """
                UPDATE notification_channel_credentials
                SET status = ?, last_validated_at = ?, validation_report_json = ?, masked_identifier = ?, fingerprint_sha256 = ?, updated_at = ?
                WHERE id = ?
                """,
                (
                    status["status"],
                    checked_at,
                    json.dumps(report, ensure_ascii=False),
                    mask_notification_credential(status["env_key_name"]),
                    notification_credential_fingerprint(status["env_key_name"]),
                    checked_at,
                    status["id"],
                ),
            )
        results.append(report)
    ok = all(item["status"] in {"有效", "即將到期"} for item in results)
    log_audit(conn, "Notify Worker", "通知通道正式憑證驗證", "notification_channel_credentials", channel or "all", json.dumps(results, ensure_ascii=False))
    return {"ok": ok, "checked_at": checked_at, "credentials": results}


def notification_gateway_status() -> Dict[str, Any]:
    smtp_host = os.getenv("SMTP_HOST", "").strip()
    smtp_username = os.getenv("SMTP_USERNAME", "").strip()
    line_url = os.getenv("LINE_WEBHOOK_URL", "").strip()
    line_token = os.getenv("LINE_CHANNEL_ACCESS_TOKEN", "").strip()
    line_target = os.getenv("LINE_TARGET_ID", "").strip()
    # This function is also used in Supabase mode without a local connection, so it reports env-derived state only.
    email_configured = notification_email_configured()
    email_provider = notification_email_provider()
    line_configured = bool(line_url or (line_token and line_target))
    return {
        "email": {
            "configured": email_configured,
            "provider": email_provider,
            "host": "api.resend.com" if email_provider == "Resend" else smtp_host or "未設定",
            "port": "443" if email_provider == "Resend" else os.getenv("SMTP_PORT", "587"),
            "from": notification_email_sender() or "未設定",
            "username": "API key（已遮罩）" if email_provider == "Resend" and env_present("RESEND_API_KEY") else smtp_username or "未設定",
            "status": "可測試" if email_configured else "未設定",
            "credentialExpiresAt": os.getenv("RESEND_CREDENTIAL_EXPIRES_AT", os.getenv("SMTP_CREDENTIAL_EXPIRES_AT", "")),
        },
        "line": {
            "configured": line_configured,
            "webhook": f"{line_url[:28]}..." if line_url else ("Messaging API push" if line_token and line_target else "未設定"),
            "mode": "webhook" if line_url else ("messaging-api-push" if line_token and line_target else "not_configured"),
            "target": f"{line_target[:8]}..." if line_target else "未設定",
            "status": "可測試" if line_configured else "未設定",
            "credentialExpiresAt": os.getenv("LINE_CREDENTIAL_EXPIRES_AT", ""),
        },
        "systemInbox": {
            "configured": True,
            "status": "啟用",
            "credentialExpiresAt": os.getenv("INBOX_SIGNING_KEY_EXPIRES_AT", ""),
        },
    }


def notification_credential_display_metadata(credential: Dict[str, Any]) -> Dict[str, Any]:
    """Report the active transport even when an older credential row is still persisted."""
    result = dict(credential)
    if result.get("channel") != "Email":
        return result

    provider = notification_email_provider()
    if provider == "Resend":
        env_key_name = "RESEND_API_KEY,MAIL_FROM"
        result.update(
            {
                "provider": "Resend Email API（沿用官網）",
                "credential_type": "Server-side API key",
                "env_key_name": env_key_name,
                "masked_identifier": mask_notification_credential(env_key_name),
                "fingerprint_sha256": notification_credential_fingerprint(env_key_name),
            }
        )
        resend_expiry = os.getenv("RESEND_CREDENTIAL_EXPIRES_AT", "").strip()
        if resend_expiry:
            result["expires_at"] = resend_expiry
    return result


def local_monitoring_snapshot(conn: sqlite3.Connection) -> Dict[str, Any]:
    readiness = production_readiness()
    alerts: List[Dict[str, str]] = []
    for name in readiness["missing"]:
        append_alert(alerts, "critical" if is_production() else "warning", "ENV-MISSING", f"缺少正式環境變數 {name}", "到 Vercel Project Settings 補齊後重新部署。")
    for item in readiness["blockers"]:
        append_alert(alerts, "critical", "READINESS-BLOCKER", item, "先處理 production readiness blocker，再開放正式交換。")
    for item in readiness["warnings"]:
        append_alert(alerts, "warning", "READINESS-WARNING", item, "排入上線前檢核清單，避免正式營運缺口。")

    counts = {
        "documents": conn.execute("SELECT COUNT(*) FROM documents").fetchone()[0],
        "attachments": conn.execute("SELECT COUNT(*) FROM attachments").fetchone()[0],
        "exchange_failed": conn.execute("SELECT COUNT(*) FROM exchange_tasks WHERE status IN ('交換失敗','失敗','逾期未確認')").fetchone()[0],
        "notification_failed": conn.execute("SELECT COUNT(*) FROM notification_deliveries WHERE status IN ('失敗','未設定','憑證異常')").fetchone()[0],
        "job_failed": conn.execute("SELECT COUNT(*) FROM job_runs WHERE status IN ('失敗','錯誤')").fetchone()[0],
    }
    if counts["exchange_failed"]:
        append_alert(alerts, "critical", "EXCHANGE-FAILED", f"{counts['exchange_failed']} 筆交換任務失敗或逾期。", "由總務工作台重送或執行翌日查核。")
    if counts["notification_failed"]:
        append_alert(alerts, "warning", "NOTIFICATION-FAILED", f"{counts['notification_failed']} 筆通知派送失敗。", "到通知中心重送，並檢查 Email/Line 憑證。")
    if counts["job_failed"]:
        append_alert(alerts, "warning", "JOB-FAILED", f"{counts['job_failed']} 筆背景任務失敗。", "到背景任務頁查看 job_runs 與 API log。")

    last_job_row = conn.execute("SELECT * FROM job_runs ORDER BY finished_at DESC LIMIT 1").fetchone()
    last_job = row_to_dict(last_job_row) if last_job_row else None
    last_job_age = age_minutes(last_job.get("finished_at") if last_job else None)
    if is_production() and (last_job_age is None or last_job_age > EDOC_MONITORING_EXPECTED_CRON_MINUTES + 120):
        append_alert(alerts, "critical", "CRON-STALLED", "正式環境背景排程超過預期時間未執行。", "檢查 Vercel Cron、CRON_SECRET 與 /api/cron/run-due 執行紀錄。")

    credentials = [notification_credential_status_for_channel(conn, channel) for channel in ["Email", "Line 工作群組", "系統站內通知"]]
    for credential in credentials:
        if credential.get("status") in {"缺少環境憑證", "已到期", "未設定"}:
            append_alert(alerts, "critical" if is_production() else "warning", "CREDENTIAL-INVALID", f"{credential['channel']} 憑證狀態：{credential.get('status')}", "補齊正式憑證、有效期限與環境變數後重新驗證。")
        elif credential.get("status") == "即將到期":
            append_alert(alerts, "warning", "CREDENTIAL-EXPIRING", f"{credential['channel']} 憑證即將到期。", "在到期前完成換證與驗證。")
    signing_service = signing_service_status()
    if signing_service["productionBlocked"]:
        append_alert(alerts, "critical", "SIGNING-SERVICE-INCOMPLETE", f"正式簽章服務尚未設定：{', '.join(signing_service['missing'])}", "設定 HSM/KMS、信任根憑證、TSA、OCSP、CRL 與 EDOC_SIGNING_SECRET 後重新部署。")
    elif not signing_service["ready"]:
        append_alert(alerts, "warning", "SIGNING-SERVICE-SIMULATION", f"簽章服務仍為模擬或不完整：{', '.join(signing_service['missing'])}", "正式上線前完成外部簽章服務接入。")
    storage_service = storage_service_status()
    if storage_service["productionBlocked"]:
        append_alert(alerts, "critical", "STORAGE-SERVICE-INCOMPLETE", f"正式檔案儲存與防毒尚未設定：{', '.join(storage_service['missing'])}", "設定 Supabase Storage private bucket、檔案加密、短效 URL、正式 AV endpoint/API key 後重新部署。")
    elif not storage_service["ready"]:
        append_alert(alerts, "warning", "STORAGE-SERVICE-SIMULATION", f"檔案儲存或防毒服務仍為本機/不完整：{', '.join(storage_service['missing'])}", "正式上線前完成物件儲存與防毒引擎接入。")

    checks = {
        "database": {"status": "ok", "mode": "sqlite", "detail": str(DB_PATH)},
        "readiness": {"status": "ok" if readiness["ready"] else "needs_action", "missing": readiness["missing"], "blockers": readiness["blockers"]},
        "storage": {"status": "ok" if storage_service["ready"] else "needs_action", **storage_service},
        "cron": {"status": "ok" if last_job_age is not None else "not_yet_run", "lastRun": last_job, "ageMinutes": last_job_age},
        "notifications": {"status": "ok" if all(item.get("status") in {"有效", "即將到期"} for item in credentials) else "needs_action", "credentials": credentials},
        "signing": {"status": "ok" if signing_service["ready"] else "needs_action", **signing_service},
        "jAgent": {"status": "needs_action" if counts["exchange_failed"] else "ok", "failedTasks": counts["exchange_failed"]},
    }
    status = monitoring_status(alerts)
    return {
        "ok": status != "critical",
        "status": status,
        "checkedAt": now(),
        "deployment": deployment_report(),
        "checks": checks,
        "counts": counts,
        "alerts": alerts,
    }


def post_monitoring_webhook(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    if not MONITORING_WEBHOOK_URL:
        return {"sent": False, "reason": "MONITORING_WEBHOOK_URL 未設定"}
    payload = json.dumps({
        "system": "Suiyuecare eDoc",
        "status": snapshot["status"],
        "checkedAt": snapshot["checkedAt"],
        "alerts": snapshot["alerts"][:8],
        "deployment": snapshot["deployment"],
    }, ensure_ascii=False).encode("utf-8")
    request = urllib.request.Request(
        MONITORING_WEBHOOK_URL,
        data=payload,
        headers={"Content-Type": "application/json", "User-Agent": "suiyuecare-edoc-monitor"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=8) as response:
            return {"sent": True, "status": response.status}
    except Exception as exc:
        return {"sent": False, "error": str(exc)}


def run_local_monitoring_check(conn: sqlite3.Connection) -> Dict[str, Any]:
    snapshot = local_monitoring_snapshot(conn)
    webhook = post_monitoring_webhook(snapshot) if snapshot["alerts"] else {"sent": False, "reason": "無告警"}
    log_structured("info", "production_monitoring_check", status=snapshot["status"], alerts=len(snapshot["alerts"]), webhook_sent=bool(webhook.get("sent")), runtime="local")
    log_audit(conn, "Ops Monitor", "正式部署監控檢查", "production_monitoring", snapshot["status"], json.dumps({"alerts": snapshot["alerts"], "webhook": webhook}, ensure_ascii=False))
    return {**snapshot, "webhook": webhook}


def notification_target_email(conn: sqlite3.Connection, role: str, explicit: str = "") -> str:
    return str(explicit or "").strip()


def notification_target_user_id(conn: sqlite3.Connection, role: str, explicit_email: str = "") -> str:
    if explicit_email:
        row = conn.execute("SELECT id FROM users WHERE lower(email) = lower(?) AND status = '啟用' ORDER BY rowid LIMIT 1", (explicit_email,)).fetchone()
        if row:
            return row["id"]
    return ""


def exact_notification_target_payload(
    user: Dict[str, Any] | sqlite3.Row | None,
    expected_company_id: str = "",
) -> Dict[str, str]:
    target = row_to_dict(user) if isinstance(user, sqlite3.Row) else dict(user or {})
    user_id = str(target.get("id") or "").strip()
    email = str(target.get("email") or "").strip()
    company_id = str(target.get("company_id") or "").strip()
    expected_company_id = str(expected_company_id or "").strip()
    if not user_id or not email or not company_id:
        raise ValueError("notification_exact_target_required")
    if expected_company_id and company_id != expected_company_id:
        raise PermissionError("notification_target_company_forbidden")
    return {
        "target_role": str(target.get("role") or "員工"),
        "target_user_id": user_id,
        "target_company_id": company_id,
        "target_email": email,
    }


def exact_sqlite_notification_target_from_metadata(
    conn: sqlite3.Connection,
    metadata_value: Any,
) -> Dict[str, Any] | None:
    metadata = parse_json_field(metadata_value)
    company_id = str(
        metadata.get("notification_target_company_id")
        or metadata.get("target_company_id")
        or ""
    ).strip()
    user_id = str(
        metadata.get("notification_target_user_id")
        or metadata.get("target_user_id")
        or ""
    ).strip()
    email = str(
        metadata.get("notification_target_email")
        or metadata.get("target_email")
        or ""
    ).strip()
    if not company_id or (not user_id and not email):
        return None
    if user_id:
        user = active_user_by_id(conn, user_id)
    else:
        resolved_id = notification_target_user_id(conn, "", email)
        user = active_user_by_id(conn, resolved_id) if resolved_id else None
    if not user:
        return None
    exact_notification_target_payload(user, company_id)
    return user


def exact_supabase_notification_target_from_metadata(metadata_value: Any) -> Dict[str, Any] | None:
    metadata = parse_json_field(metadata_value)
    company_id = str(
        metadata.get("notification_target_company_id")
        or metadata.get("target_company_id")
        or ""
    ).strip()
    user_id = str(
        metadata.get("notification_target_user_id")
        or metadata.get("target_user_id")
        or ""
    ).strip()
    email = str(
        metadata.get("notification_target_email")
        or metadata.get("target_email")
        or ""
    ).strip()
    if not company_id or (not user_id and not email):
        return None
    if not user_id:
        user_id = supabase_notification_target_user_id("", email)
    user = supabase_user_by_id(user_id) if user_id else None
    if not user:
        return None
    exact_notification_target_payload(user, company_id)
    return user


def create_notification(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    item = {
        "id": payload.get("id") or f"NTF-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "type": payload.get("type") or "一般通知",
        "title": payload.get("title") or f"{payload.get('type') or '一般'}通知",
        "target_role": payload.get("target_role") or payload.get("target") or "行政部主任",
        "target_user_id": payload.get("target_user_id") or "",
        "target_company_id": payload.get("target_company_id") or payload.get("company_id") or "",
        "target_email": payload.get("target_email") or "",
        "channel": payload.get("channel") or "系統通知",
        "status": payload.get("status") or "未讀",
        "priority": payload.get("priority") or "中",
        "source": payload.get("source") or "",
        "action_url": payload.get("action_url") or (f"/#officialWorkflow?document={urllib.parse.quote(str(payload.get('source') or ''))}" if payload.get("source") else ""),
        "body": payload.get("body") or "請確認公文收發電子用印系統待辦事項。",
        "delivery_receipt": payload.get("delivery_receipt") or "",
        "created_at": payload.get("created_at") or now(),
        "sent_at": payload.get("sent_at") or None,
    }
    target_user = None
    if item["target_user_id"]:
        target_user = conn.execute(
            "SELECT id, company_id, email, role FROM users WHERE id = ? AND status = '啟用'",
            (item["target_user_id"],),
        ).fetchone()
    elif item["target_email"]:
        item["target_user_id"] = notification_target_user_id(conn, item["target_role"], item["target_email"])
        if item["target_user_id"]:
            target_user = conn.execute(
                "SELECT id, company_id, email, role FROM users WHERE id = ? AND status = '啟用'",
                (item["target_user_id"],),
            ).fetchone()
    if not target_user:
        raise ValueError("notification_exact_target_required")
    if item["target_company_id"] and str(target_user["company_id"] or "") != str(item["target_company_id"]):
        raise PermissionError("notification_target_company_forbidden")
    if item["target_email"] and str(target_user["email"] or "").lower() != str(item["target_email"]).lower():
        raise PermissionError("notification_target_identity_mismatch")
    item["target_company_id"] = str(target_user["company_id"] or "")
    item["target_email"] = str(target_user["email"] or "")
    item["target_role"] = str(target_user["role"] or "員工")
    conn.execute(
        """
        INSERT OR IGNORE INTO notifications (
          id, type, title, target_role, target_user_id, target_company_id, target_email, channel, status, priority, source, action_url, body, delivery_receipt, created_at, sent_at
        ) VALUES (
          :id, :type, :title, :target_role, :target_user_id, :target_company_id, :target_email, :channel, :status, :priority, :source, :action_url, :body, :delivery_receipt, :created_at, :sent_at
        )
        """,
        item,
    )
    return row_to_dict(conn.execute("SELECT * FROM notifications WHERE id = ?", (item["id"],)).fetchone())


def record_notification_delivery(
    conn: sqlite3.Connection,
    notification_id: str,
    channel: str,
    target: str,
    status: str,
    receipt: str = "",
    error: str = "",
) -> Dict[str, Any]:
    row = {
        "id": f"NDEL-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "notification_id": notification_id,
        "channel": channel,
        "target": target,
        "status": status,
        "receipt": receipt,
        "error": error,
        "attempt_count": 1,
        "created_at": now(),
    }
    conn.execute(
        """
        INSERT INTO notification_deliveries (
          id, notification_id, channel, target, status, receipt, error, attempt_count, created_at
        ) VALUES (
          :id, :notification_id, :channel, :target, :status, :receipt, :error, :attempt_count, :created_at
        )
        """,
        row,
    )
    return row


def notification_email_subject(subject: str) -> str:
    clean = " ".join(str(subject or "公文系統通知").splitlines()).strip()
    return f"[公文收發電子用印系統] {clean}"[:240]


def notification_email_action_url() -> str:
    if not EDOC_PUBLIC_BASE_URL:
        return ""
    parsed = urlparse(EDOC_PUBLIC_BASE_URL)
    if parsed.scheme not in {"https", "http"} or not parsed.netloc:
        return ""
    if is_production() and parsed.scheme != "https":
        return ""
    return f"{EDOC_PUBLIC_BASE_URL}/#approvalLog"


def notification_email_html(subject: str, body: str) -> str:
    safe_subject = html.escape(" ".join(str(subject or "公文系統通知").splitlines()).strip())
    safe_body = html.escape(str(body or "請登入系統查看待辦事項。")[:6000]).replace("\n", "<br />")
    action_url = notification_email_action_url()
    action = ""
    if action_url:
        action = (
            f'<p style="margin:24px 0"><a href="{html.escape(action_url, quote=True)}" '
            'style="display:inline-block;padding:11px 18px;background:#f58a1f;color:#fff;text-decoration:none;border-radius:6px">'
            "登入系統查看</a></p>"
        )
    return (
        '<div style="font-family:-apple-system,BlinkMacSystemFont,\'Noto Sans TC\',\'Segoe UI\',sans-serif;'
        'max-width:600px;margin:0 auto;color:#3f2414;line-height:1.8">'
        '<p style="margin:0 0 8px;color:#8a7566;font-size:13px">公文收發電子用印系統通知</p>'
        f'<h1 style="margin:0 0 16px;font-size:22px;line-height:1.45">{safe_subject}</h1>'
        f'<p style="margin:0;font-size:15px">{safe_body}</p>{action}'
        '<p style="margin-top:24px;color:#8a7566;font-size:12px">本信僅提供流程提醒，不附帶公文、附件或印章原始檔；請登入系統依權限查看。</p>'
        "</div>"
    )


def resend_idempotency_key(notification_id: str) -> str:
    safe = "".join(char if char.isalnum() or char in "-_." else "-" for char in str(notification_id or ""))
    return f"edoc-notification/{safe or secrets.token_hex(8)}"[:256]


def resend_error_detail(exc: urllib.error.HTTPError) -> str:
    raw = exc.read().decode("utf-8", "replace")[:1000]
    try:
        payload = json.loads(raw)
        return str(payload.get("message") or payload.get("name") or f"HTTP {exc.code}")[:500]
    except (TypeError, ValueError):
        return raw or f"HTTP {exc.code}"


def send_resend_email_notification(to_email: str, subject: str, body: str, notification_id: str = "") -> Dict[str, str]:
    api_key = os.getenv("RESEND_API_KEY", "").strip()
    sender = notification_email_sender()
    if not api_key or not sender:
        return {"status": "未設定", "receipt": "", "error": "RESEND_API_KEY 或 MAIL_FROM 未設定"}
    if not valid_formal_email(to_email):
        return {"status": "失敗", "receipt": "", "error": "通知收件 Email 無效"}
    payload = json.dumps(
        {
            "from": sender,
            "to": [to_email],
            "subject": notification_email_subject(subject),
            "text": f"{subject}\n\n{body}\n\n{notification_email_action_url()}".strip(),
            "html": notification_email_html(subject, body),
            "tags": [{"name": "module", "value": "edoc"}],
        },
        ensure_ascii=False,
    ).encode("utf-8")
    request = urllib.request.Request(
        "https://api.resend.com/emails",
        data=payload,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "Idempotency-Key": resend_idempotency_key(notification_id),
            "User-Agent": "suiyuecare-edoc-notify",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            result = json.loads(response.read().decode("utf-8", "replace") or "{}")
            receipt = str(result.get("id") or response.headers.get("X-Request-Id") or "")
            if not receipt:
                return {"status": "失敗", "receipt": "", "error": "Resend 未回傳寄送識別碼"}
            return {"status": "成功", "receipt": receipt, "error": ""}
    except urllib.error.HTTPError as exc:
        return {"status": "失敗", "receipt": "", "error": f"Resend HTTP {exc.code}: {resend_error_detail(exc)}"}
    except Exception as exc:
        return {"status": "失敗", "receipt": "", "error": f"Resend 連線失敗：{str(exc)[:500]}"}


def send_smtp_email_notification(to_email: str, subject: str, body: str, notification_id: str = "") -> Dict[str, str]:
    host = os.getenv("SMTP_HOST", "").strip()
    if not host:
        return {"status": "未設定", "receipt": "", "error": "SMTP_HOST 未設定"}
    if not valid_formal_email(to_email):
        return {"status": "失敗", "receipt": "", "error": "通知收件 Email 無效"}
    port = int(os.getenv("SMTP_PORT", "587"))
    username = os.getenv("SMTP_USERNAME", "")
    password = os.getenv("SMTP_PASSWORD", "")
    sender = os.getenv("SMTP_FROM", username or "no-reply@suiyuecare.local")
    use_tls = os.getenv("SMTP_USE_TLS", "true").lower() not in {"0", "false", "no"}
    message = EmailMessage()
    message["From"] = sender
    message["To"] = to_email
    message["Subject"] = notification_email_subject(subject)
    message["Message-ID"] = f"<edoc-{int(time.time() * 1000)}-{secrets.token_hex(4)}@suiyuecare.com>"
    if notification_id:
        message["Resend-Idempotency-Key"] = resend_idempotency_key(notification_id)
    message.set_content(body)
    context = ssl.create_default_context()
    try:
        if port == 465:
            with smtplib.SMTP_SSL(host, port, context=context, timeout=20) as smtp:
                if username:
                    smtp.login(username, password)
                smtp.send_message(message)
        else:
            with smtplib.SMTP(host, port, timeout=20) as smtp:
                if use_tls:
                    smtp.starttls(context=context)
                if username:
                    smtp.login(username, password)
                smtp.send_message(message)
        return {"status": "成功", "receipt": message["Message-ID"], "error": ""}
    except Exception as exc:
        return {"status": "失敗", "receipt": "", "error": str(exc)}


def send_email_notification(to_email: str, subject: str, body: str, notification_id: str = "") -> Dict[str, str]:
    if env_present("RESEND_API_KEY") or env_present("MAIL_FROM") or env_present("RESEND_FROM"):
        return send_resend_email_notification(to_email, subject, body, notification_id)
    if smtp_email_configured() or env_present("SMTP_HOST"):
        return send_smtp_email_notification(to_email, subject, body, notification_id)
    return {"status": "未設定", "receipt": "", "error": "RESEND_API_KEY 與 MAIL_FROM 未設定"}


def send_line_notification(message: str) -> Dict[str, str]:
    url = os.getenv("LINE_WEBHOOK_URL", "").strip()
    token = os.getenv("LINE_CHANNEL_ACCESS_TOKEN", "").strip()
    target_id = os.getenv("LINE_TARGET_ID", "").strip()
    if url:
        data = json.dumps({"message": message, "source": "suiyuecare-edoc"}, ensure_ascii=False).encode("utf-8")
        headers = {"Content-Type": "application/json", "User-Agent": "suiyuecare-edoc-notify"}
        request = urllib.request.Request(url, data=data, headers=headers, method="POST")
    elif token and target_id:
        data = json.dumps({"to": target_id, "messages": [{"type": "text", "text": message[:5000]}]}, ensure_ascii=False).encode("utf-8")
        headers = {"Content-Type": "application/json", "Authorization": f"Bearer {token}", "User-Agent": "suiyuecare-edoc-notify"}
        request = urllib.request.Request("https://api.line.me/v2/bot/message/push", data=data, headers=headers, method="POST")
    else:
        return {"status": "未設定", "receipt": "", "error": "LINE_WEBHOOK_URL 或 LINE_CHANNEL_ACCESS_TOKEN + LINE_TARGET_ID 未設定"}
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            receipt = response.headers.get("X-Line-Request-Id") or response.headers.get("X-Request-Id") or f"LINE-{int(time.time() * 1000)}"
            return {"status": "成功" if 200 <= response.status < 300 else "失敗", "receipt": receipt, "error": ""}
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "replace")
        return {"status": "失敗", "receipt": "", "error": f"HTTP {exc.code}: {detail}"}
    except Exception as exc:
        return {"status": "失敗", "receipt": "", "error": str(exc)}


def push_system_notification(conn: sqlite3.Connection, item: Dict[str, Any]) -> Dict[str, str]:
    existing = conn.execute(
        "SELECT id FROM system_inbox WHERE notification_id = ? ORDER BY created_at DESC LIMIT 1",
        (item["id"],),
    ).fetchone()
    if existing:
        return {"status": "成功", "receipt": existing["id"], "error": ""}
    inbox_id = f"INBOX-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    # The notification row is the addressing authority. Resolving by role a
    # second time can silently deliver to a different co-worker when several
    # enabled users share the same role.
    target_user_id = str(item.get("target_user_id") or "").strip()
    if not target_user_id:
        raise ValueError("notification_exact_target_required")
    conn.execute(
        """
        INSERT INTO system_inbox (id, notification_id, target_role, target_user_id, title, body, status, created_at)
        VALUES (?, ?, ?, ?, ?, ?, '未讀', ?)
        """,
        (inbox_id, item["id"], item["target_role"], target_user_id, item["title"], item["body"], now()),
    )
    return {"status": "成功", "receipt": inbox_id, "error": ""}


def notification_attempt_result(channel: str, target: str, result: Dict[str, str], started: float) -> Dict[str, str | int]:
    return {
        "channel": channel,
        "target": target,
        "status": result.get("status", "失敗"),
        "receipt": result.get("receipt", ""),
        "error": result.get("error", ""),
        "attempted_at": now(),
        "duration_ms": int((time.time() - started) * 1000),
    }


def notification_delivery_report(notification: Dict[str, Any], delivery: Dict[str, Any], requested_channel: str) -> Dict[str, Any]:
    failed = [item for item in delivery.get("results", []) if item.get("status") != "成功"]
    return {
        "ok": delivery.get("success", 0) == delivery.get("total", 0) and delivery.get("total", 0) > 0,
        "checked_at": now(),
        "requested_channel": requested_channel,
        "notification_id": notification.get("id"),
        "title": notification.get("title"),
        "target_role": notification.get("target_role"),
        "target_email": notification.get("target_email"),
        "summary": delivery.get("receipt", ""),
        "success": delivery.get("success", 0),
        "total": delivery.get("total", 0),
        "failed": failed,
        "results": delivery.get("results", []),
    }


def deliver_notification(conn: sqlite3.Connection, notification_id: str, force_channel: str = "") -> Dict[str, Any]:
    row = conn.execute("SELECT * FROM notifications WHERE id = ?", (notification_id,)).fetchone()
    if not row:
        return {"id": notification_id, "status": "失敗", "error": "notification_not_found", "results": []}
    item = row_to_dict(row)
    channels = notification_channels(force_channel or item["channel"])
    target_email = notification_target_email(conn, item["target_role"], item.get("target_email") or "")
    results: List[Dict[str, str]] = []
    for channel in channels:
        credential = notification_credential_status_for_channel(conn, channel)
        if channel != "系統站內通知" and credential["status"] not in {"有效", "即將到期"}:
            result = {"status": "憑證異常", "receipt": "", "error": f"{channel} 正式憑證{credential['status']}，請先完成憑證驗證或更新。"}
            target = target_email if channel == "Email" else "公文收發電子用印系統 LINE 工作群組"
            record_notification_delivery(conn, item["id"], channel, target, result["status"], result.get("receipt", ""), result.get("error", ""))
            results.append({"channel": channel, "target": target, **result, "attempted_at": now(), "duration_ms": 0})
            continue
        started = time.time()
        if channel == "Email":
            result = send_email_notification(target_email, item["title"], item["body"], item["id"])
            target = target_email
        elif channel == "Line 工作群組":
            result = send_line_notification(f"{item['title']}\n{item['body']}")
            target = "公文收發電子用印系統 LINE 工作群組"
        else:
            result = push_system_notification(conn, item)
            target = item["target_role"]
        record_notification_delivery(conn, item["id"], channel, target, result["status"], result.get("receipt", ""), result.get("error", ""))
        results.append(notification_attempt_result(channel, target, result, started))

    success_count = len([item for item in results if item["status"] == "成功"])
    receipt_text = "；".join(
        f"{result['channel']}->{result['target']}:{result['status']}{('/' + result['receipt']) if result.get('receipt') else ''}{(' / ' + result['error']) if result.get('error') else ''}"
        for result in results
    )
    status = "已派送" if success_count == len(results) else "部分派送" if success_count else "派送失敗"
    conn.execute(
        "UPDATE notifications SET status = ?, sent_at = ?, delivery_receipt = ? WHERE id = ?",
        (status, now(), receipt_text, item["id"]),
    )
    log_audit(conn, "Notify Worker", "通知派送", "notifications", item["id"], receipt_text)
    return {"id": item["id"], "status": status, "success": success_count, "total": len(results), "receipt": receipt_text, "results": results}


def create_and_deliver_notification(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    notice = create_notification(conn, {**payload, "channel": payload.get("channel") or "Email + 系統通知"})
    try:
        delivery = deliver_notification(conn, notice["id"], notice["channel"])
    except Exception as exc:
        detail = redact_text(str(exc))[:500]
        delivery = {"id": notice["id"], "status": "派送失敗", "success": 0, "total": 0, "receipt": "", "error": detail, "results": []}
        conn.execute(
            "UPDATE notifications SET status = '派送失敗', delivery_receipt = ? WHERE id = ?",
            (detail, notice["id"]),
        )
        log_audit(conn, "Notify Worker", "通知自動派送失敗", "notifications", notice["id"], detail)
    return {**notice, "delivery": delivery}


def ensure_notification_for_source(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any] | None:
    source = payload.get("source") or ""
    notice_type = payload.get("type") or ""
    if not source or not notice_type:
        return create_notification(conn, payload)
    row = conn.execute("SELECT * FROM notifications WHERE source = ? AND type = ? LIMIT 1", (source, notice_type)).fetchone()
    if row:
        return row_to_dict(row)
    return create_notification(conn, payload)


def normalize_official_date_text(value: str) -> str:
    """Normalize common numeric dates for Taiwanese official-document wording."""

    def render_date(match: re.Match[str]) -> str:
        year = int(match.group(1))
        month = int(match.group(2))
        day = int(match.group(3))
        if not 1 <= month <= 12 or not 1 <= day <= 31:
            return match.group(0)
        roc_year = year - 1911 if year >= 1912 else year
        return f"民國{roc_year}年{month}月{day}日"

    normalized = re.sub(
        r"(?<!\d)(?:(?:中華)?民國\s*)?(\d{2,4})\s*[./-]\s*(\d{1,2})\s*[./-]\s*(\d{1,2})(?!\d)",
        render_date,
        value,
    )
    return re.sub(
        r"(?<!\d)(?<!民國)(\d{2,4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日",
        render_date,
        normalized,
    )


def responsible_person_change_details(plain: str) -> Dict[str, str] | None:
    """Extract the common planned responsible-person change intent."""

    compact = re.sub(r"\s+", "", normalize_official_date_text(plain))
    match = re.search(
        r"(?:要|欲|擬|預計)?(?:從)?(?:原本的|原先的|原有的|原任|原)?"
        r"(?P<position>[\u4e00-\u9fffA-Za-z0-9]{0,18}?(?:業務負責人|負責人|承辦人|代表人|管理人|聯絡人|董事長|主管|經理|主任))"
        r"(?P<previous>[\u4e00-\u9fff·]{2,5}?)"
        r"(?:更換成|更換為|變更成|變更為|改成|改為|換成|換為)"
        r"(?P<next>[\u4e00-\u9fff·]{2,5})(?=[，,。；;]|$|預計|擬|將於|自|於|生效)",
        compact,
    )
    if not match:
        return None
    date_match = re.search(r"民國\d{1,3}年\d{1,2}月\d{1,2}日", compact)
    return {
        "position": match.group("position"),
        "previous": match.group("previous"),
        "next": match.group("next"),
        "date": date_match.group(0) if date_match else "",
    }


def official_subject_closing(plain: str, doc_type: str = "函") -> str:
    if doc_type in {"簽", "簽呈"}:
        return "請核示。"
    if re.search(r"展延|延期|延長|延到|延至", plain) and re.search(r"申請|同意|核准", plain):
        return "請惠予核准。"
    if "申請" in plain:
        return "請惠予審核。"
    if re.search(r"詢問|洽詢|回覆|見復", plain):
        return "請惠復。"
    return "請查照。"


def formalize_official_subject(plain: str, doc_type: str = "函") -> str:
    """Turn purpose text into a concise subject instead of wrapping it verbatim."""

    change = responsible_person_change_details(plain)
    closing = official_subject_closing(plain, doc_type)
    if change:
        return f"有關本公司{change['position']}變更一案，{closing}"

    normalized = normalize_official_date_text(plain)
    normalized = re.sub(r"[\r\n]+", "，", normalized)
    normalized = re.sub(r"\s+", " ", normalized).strip(" ，。；;：:　")

    extension = re.search(
        r"(?:想請|請)?[^，,。；;]{0,24}?同意(?:把|將)?(?P<object>.+?期限)(?:延到|延至|展延至)(?P<date>[^，,。；;]+)",
        normalized,
    )
    if extension:
        topic = f"本公司申請展延{extension.group('object')}至{extension.group('date')}"
    else:
        first_clause = next(
            (item.strip() for item in re.split(r"[，,。；;]", normalized) if item.strip()),
            "本公司業務事項",
        )
        agency_application = re.search(r"(?:向|跟)[^，,。；;]{2,24}?(申請.+)", first_clause)
        topic = agency_application.group(1) if agency_application else first_clause
        topic = re.sub(r"^(?:這份公文(?:的)?用途(?:是|為)?|關於|有關)", "", topic).strip()
        topic = re.sub(r"^(?:我們|我|本公司)?(?:想要|想|要|希望)\s*", "", topic).strip()
        topic = topic.replace("想請問", "洽詢").replace("請問", "洽詢")
        topic = topic.replace("更換成", "變更為").replace("換成", "變更為")
        topic = topic.replace("幫忙", "協助").replace("你們", "貴機關")
        if topic.startswith("申請"):
            topic = f"本公司{topic}"

    topic = topic.strip(" ，。；;：:　") or "本公司業務事項"
    if len(topic) > 58:
        topic = topic[:58].rstrip(" ，、。；;：:")
    case_suffix = "" if re.search(r"(?:一案|事宜|事項|情形)$", topic) else "一案"
    return f"有關{topic}{case_suffix}，{closing}"


def official_subject_needs_rewrite(subject: str, plain: str) -> bool:
    candidate = subject.strip()
    if not candidate or "\n" in candidate or "..." in candidate:
        return True
    if re.search(r"要從原本的|預計會在|想請你們|我們要跟|幫我|怎麼", candidate):
        return True
    if not re.search(r"(?:請查照|請核示|請惠予審核|請惠予核准|請惠復|請辦理)[。.]$", candidate):
        return True

    plain_compact = re.sub(r"[\W_]+", "", plain, flags=re.UNICODE)
    subject_compact = re.sub(r"[\W_]+", "", candidate, flags=re.UNICODE)
    plain_is_already_formal = bool(
        re.match(r"^有關", plain.strip())
        and re.search(r"(?:請查照|請核示|請惠予審核|請惠予核准|請惠復)[。.]?$", plain.strip())
    )
    return bool(
        len(plain_compact) >= 8
        and plain_compact in subject_compact
        and not plain_is_already_formal
    )


def fallback_ai_compose(payload: Dict[str, Any]) -> Dict[str, Any]:
    plain = str(payload.get("plainText") or payload.get("plain_text") or "").strip()
    recipient = str(payload.get("recipient") or "").strip()
    doc_type = str(payload.get("docType") or payload.get("doc_type") or "函").strip()
    attachments = payload.get("attachments") or []
    change = responsible_person_change_details(plain)
    subject = formalize_official_subject(plain, doc_type)

    if change:
        date_phrase = f"擬自{change['date']}起" if change["date"] else "擬"
        body_lines = [
            f"一、依業務需要辦理本公司{change['position']}變更作業。",
            f"二、本公司{change['position']}{date_phrase}由{change['previous']}變更為{change['next']}。",
        ]
    else:
        formal_detail = normalize_official_date_text(plain).strip(" ，。；;　")
        formal_detail = formal_detail.replace("要從原本的", "擬由原").replace("更換成", "變更為")
        formal_detail = formal_detail.replace("預計會在", "預計於").replace("幫忙", "協助")
        body_lines = [
            "一、依業務需要辦理本案。",
            f"二、{formal_detail or '相關事項說明如下'}。",
        ]

    if attachments:
        body_lines.append("三、檢附相關資料如附件，敬請惠予查收並辦理後續事宜。")
    elif recipient and recipient != "未指定受文者":
        body_lines.append("三、敬請貴機關惠予辦理，俾利後續作業。")
    else:
        body_lines.append("三、請依相關規定辦理後續事宜。")
    return {
        "subject": subject,
        "body": "\n".join(body_lines),
        "model": "local-template",
        "usedOpenAI": False,
        "notice": "OPENAI_API_KEY 未設定或 OpenAI 服務暫不可用，已使用本機公文模板產生。"
    }


def extract_openai_text(data: Dict[str, Any]) -> str:
    if isinstance(data.get("output_text"), str):
        return data["output_text"]
    chunks: List[str] = []
    for item in data.get("output", []) or []:
        for content in item.get("content", []) or []:
            if content.get("type") in {"output_text", "text"} and isinstance(content.get("text"), str):
                chunks.append(content["text"])
    return "\n".join(chunks).strip()


def parse_ai_compose_json(text: str) -> Dict[str, Any]:
    cleaned = text.strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`").replace("json\n", "", 1).strip()
    try:
        return json.loads(cleaned)
    except json.JSONDecodeError:
        start = cleaned.find("{")
        end = cleaned.rfind("}")
        if start >= 0 and end > start:
            return json.loads(cleaned[start:end + 1])
        raise


def record_ai_compose_audit(
    conn: sqlite3.Connection | None,
    actor: str,
    action: str,
    model: str,
    detail: str,
) -> None:
    safe_detail = redact_text(detail)[:500]
    if conn is not None:
        log_audit(conn, actor, action, "ai_compose", model, safe_detail, module_code="official_documents")
        return
    try:
        supabase_insert("audit_logs", {
            "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "actor": actor,
            "action": action,
            "target_type": "ai_compose",
            "target_id": model,
            "detail": safe_detail,
            "event_type": "submit",
            "severity": "info",
            "result": "success",
            "module_code": "official_documents",
            "resource_type": "ai_compose",
            "resource_id": model,
            "data_scope": "self",
            "request_id": f"req_{secrets.token_hex(8)}",
            "created_at": now(),
        })
    except Exception:
        # The generated draft remains usable when the audit sink is temporarily
        # unavailable; the runtime error channel still records the failed write.
        pass


def ai_compose_official_draft(conn: sqlite3.Connection | None, payload: Dict[str, Any]) -> Dict[str, Any]:
    plain = str(payload.get("plainText") or payload.get("plain_text") or "").strip()
    if len(plain) < 6:
        return {"error": "invalid_request", "detail": "白話文內容至少需要 6 個字。"}
    context = {
        "docType": payload.get("docType") or "函",
        "priority": payload.get("priority") or "普通件",
        "recipient": payload.get("recipient") or "未指定受文者",
        "attachments": payload.get("attachments") or [],
        "role": payload.get("role") or "業務助理"
    }
    if not OPENAI_API_KEY:
        result = fallback_ai_compose({**payload, **context})
        record_ai_compose_audit(conn, context["role"], "AI 公文助理產生函稿", "local-template", result["notice"])
        return result
    request_payload = {
        "model": OPENAI_MODEL,
        "input": [
            {
                "role": "system",
                "content": (
                    "你是台灣長照公司電子公文撰寫助理。"
                    "請先抽取核心行政事項與請求動作，再把白話用途重新改寫成正式公文。"
                    "只輸出 JSON，格式為 {\"subject\":\"...\",\"body\":\"...\"}。"
                    "subject 必須是精簡、完整的一句公文主旨，不得逐字照抄用途，"
                    "也不得只在原文前後加上「有關」與「請查照」；非必要姓名、日期與執行細節應放在 body。"
                    "subject 應依意圖以「請查照」、「請核示」、「請惠予審核」、「請惠予核准」或「請惠復」等正式語氣結尾。"
                    "body 使用中文條列「一、」「二、」「三、」，語氣正式、清楚。"
                    "民國數字日期須改為「民國○年○月○日」；原文為預計、擬辦或尚未完成時，不得改寫成已完成。"
                    "attachments 為空時不得聲稱檢附、檢送或另附資料；不可捏造未提供的法規、附件或事實。"
                )
            },
            {
                "role": "user",
                "content": json.dumps({"plainText": plain, "context": context}, ensure_ascii=False)
            }
        ],
        "temperature": 0.2
    }
    data = json.dumps(request_payload, ensure_ascii=False).encode("utf-8")
    request = urllib.request.Request(
        "https://api.openai.com/v1/responses",
        data=data,
        headers={"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"},
        method="POST"
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            response_data = json.loads(response.read().decode("utf-8"))
        text = extract_openai_text(response_data)
        parsed = parse_ai_compose_json(text)
        subject = str(parsed.get("subject") or "").strip()
        body = str(parsed.get("body") or "").strip()
        if not subject or not body:
            raise ValueError("openai_response_missing_subject_or_body")
        subject = normalize_official_date_text(subject)
        body = normalize_official_date_text(body)
        subject_rewritten = bool(
            responsible_person_change_details(plain)
            or official_subject_needs_rewrite(subject, plain)
        )
        if subject_rewritten:
            subject = formalize_official_subject(plain, context["docType"])
        if not context["attachments"] and re.search(r"檢附|檢送|如附件|附件詳", body):
            raise ValueError("openai_response_invented_attachment")
        if (
            re.search(r"預計|擬|將於|將在|要.*(?:更換|變更)", plain)
            and not re.search(r"已(?:完成|變更|更換|辦理|核准|同意)", plain)
            and re.search(r"已(?:完成|變更|更換|辦理|核准|同意)", body)
        ):
            raise ValueError("openai_response_changed_planned_status")
        result = {
            "subject": subject,
            "body": body,
            "model": OPENAI_MODEL,
            "usedOpenAI": True,
            "subjectRewritten": subject_rewritten,
        }
        record_ai_compose_audit(conn, context["role"], "AI 公文助理產生函稿", OPENAI_MODEL, f"recipient={context['recipient']}")
        return result
    except Exception as exc:
        result = fallback_ai_compose({**payload, **context})
        result["notice"] = "OpenAI 暫時無法產生，已改用本機公文模板。"
        record_ai_compose_audit(conn, context["role"], "AI 公文助理備援產生函稿", "local-template", str(exc))
        return result
def sync_notifications_from_business_state(conn: sqlite3.Connection) -> Dict[str, Any]:
    created = 0
    items: List[Dict[str, Any]] = []
    skipped: List[Dict[str, str]] = []
    inbound = conn.execute("SELECT * FROM documents WHERE direction = '收文' AND status IN ('待登錄','待分派')").fetchall()
    for doc in inbound:
        target = exact_sqlite_notification_target_from_metadata(conn, doc["metadata_json"])
        if not target:
            skipped.append({"source": doc["id"], "reason": "notification_exact_target_required"})
            continue
        before = conn.execute("SELECT COUNT(*) FROM notifications WHERE source = ? AND type = '收文'", (doc["id"],)).fetchone()[0]
        item = ensure_notification_for_source(conn, {
            "type": "收文",
            "title": f"{doc['doc_no']} {doc['status']}",
            **exact_notification_target_payload(target, target.get("company_id") or ""),
            "channel": "系統通知",
            "priority": "高",
            "source": doc["id"],
            "body": f"{doc['agency_name']} 來文「{doc['subject']}」需處理。",
        })
        created += 0 if before else 1
        if item:
            items.append(item)

    dispatch = conn.execute("SELECT * FROM documents WHERE direction = '發文' AND status IN ('待清稿','已清稿','交換失敗')").fetchall()
    for doc in dispatch:
        target = exact_sqlite_notification_target_from_metadata(conn, doc["metadata_json"])
        if not target:
            skipped.append({"source": doc["id"], "reason": "notification_exact_target_required"})
            continue
        notice_type = "交換失敗" if doc["status"] == "交換失敗" else "待清稿"
        before = conn.execute("SELECT COUNT(*) FROM notifications WHERE source = ? AND type = ?", (doc["id"], notice_type)).fetchone()[0]
        item = ensure_notification_for_source(conn, {
            "type": notice_type,
            "title": f"{doc['doc_no']} {doc['status']}",
            **exact_notification_target_payload(target, target.get("company_id") or ""),
            "channel": "Email + Line + 系統通知" if notice_type == "交換失敗" else "Email + 系統通知",
            "priority": "高",
            "source": doc["id"],
            "body": f"{doc['subject']} 目前狀態：{doc['status']}。",
        })
        created += 0 if before else 1
        if item:
            items.append(item)

    expiry_limit = (datetime.now() + timedelta(hours=1)).strftime("%Y-%m-%d %H:%M:%S")
    expiring_users = conn.execute(
        """
        SELECT DISTINCT u.*
        FROM auth_sessions AS session
        JOIN users AS u ON u.id = session.user_id AND u.status = '啟用'
        WHERE session.revoked_at IS NULL AND session.expires_at <= ?
        """,
        (expiry_limit,),
    ).fetchall()
    for target_row in expiring_users:
        target = row_to_dict(target_row)
        source = f"SEC-TOKEN-{target['id']}"
        try:
            target_fields = exact_notification_target_payload(
                target,
                target.get("company_id") or "",
            )
        except (ValueError, PermissionError):
            skipped.append({"source": source, "reason": "notification_exact_target_required"})
            continue
        before = conn.execute(
            "SELECT COUNT(*) FROM notifications WHERE source = ? AND type = 'Token 到期'",
            (source,),
        ).fetchone()[0]
        item = ensure_notification_for_source(conn, {
            "type": "Token 到期",
            "title": "登入工作階段即將到期",
            **target_fields,
            "channel": "Email + 系統通知",
            "priority": "中",
            "source": source,
            "body": "你的登入工作階段將於 1 小時內到期，請重新登入以繼續使用。",
        })
        created += 0 if before else 1
        if item:
            items.append(item)
    return {"created": created, "items": items, "skipped": skipped}


def retry_failed_notifications(conn: sqlite3.Connection) -> Dict[str, Any]:
    rows = conn.execute("SELECT id FROM notifications WHERE status IN ('派送失敗','部分派送') OR delivery_receipt IS NULL OR delivery_receipt = ''").fetchall()
    results = [deliver_notification(conn, row["id"]) for row in rows]
    return {"count": len(results), "results": results}


def notification_visible_to_user(notification: Dict[str, Any], user: Dict[str, Any]) -> bool:
    """Match an inbox row to one exact EDOC identity, never to an arbitrary client filter."""
    user_id = str(user.get("id") or "").strip()
    user_email = str(user.get("email") or "").strip().lower()
    target_user_id = str(notification.get("target_user_id") or "").strip()
    target_email = str(notification.get("target_email") or "").strip().lower()
    target_company_id = str(notification.get("target_company_id") or "").strip()
    user_company_id = str(user.get("company_id") or "").strip()
    if not target_company_id or not user_company_id or target_company_id != user_company_id:
        return False
    if target_user_id:
        return bool(user_id and target_user_id == user_id)
    if target_email:
        return bool(user_email and target_email == user_email)
    # Role-only legacy rows are intentionally not exposed.  A role can contain
    # many people, so it is not an acceptable inbox authorization principal.
    return False


def notification_inbox(conn: sqlite3.Connection, session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = official_session_user(session)
    notices = [
        row_to_dict(row)
        for row in conn.execute("SELECT * FROM notifications ORDER BY created_at DESC LIMIT 500").fetchall()
    ]
    notices = [item for item in notices if notification_visible_to_user(item, user)]
    notice_ids = {item["id"] for item in notices}
    deliveries = [
        row_to_dict(row)
        for row in conn.execute("SELECT * FROM notification_deliveries ORDER BY created_at DESC LIMIT 1000").fetchall()
        if row["notification_id"] in notice_ids
    ]
    inbox = [
        row_to_dict(row)
        for row in conn.execute("SELECT * FROM system_inbox ORDER BY created_at DESC LIMIT 500").fetchall()
        if row["notification_id"] in notice_ids
        and bool(row["target_user_id"])
        and str(row["target_user_id"]) == str(user.get("id") or "")
    ]
    return {"notifications": notices, "deliveries": deliveries, "inbox": inbox}


def mark_notification_read(
    conn: sqlite3.Connection,
    notification_id: str,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = official_session_user(session)
    row = conn.execute("SELECT * FROM notifications WHERE id = ?", (notification_id,)).fetchone()
    if not row:
        raise ValueError("notification_not_found")
    notice = row_to_dict(row)
    if not notification_visible_to_user(notice, user):
        raise PermissionError("notification_access_denied")
    conn.execute("UPDATE notifications SET status = '已讀' WHERE id = ?", (notification_id,))
    conn.execute(
        """
        UPDATE system_inbox SET status = '已讀'
        WHERE notification_id = ?
          AND target_user_id = ?
        """,
        (notification_id, user.get("id") or ""),
    )
    log_audit(
        conn,
        official_actor_name(user),
        "通知已讀",
        "notification",
        notification_id,
        "scoped_system_inbox_read",
        actor_user_id=user.get("id") or "",
        actor_email=user.get("email") or "",
    )
    return row_to_dict(conn.execute("SELECT * FROM notifications WHERE id = ?", (notification_id,)).fetchone())


def supabase_notification_inbox(session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    company_id = str(user.get("company_id") or "").strip()
    if not company_id:
        return {"notifications": [], "deliveries": [], "inbox": []}
    candidates: Dict[str, Dict[str, Any]] = {}
    filters = []
    if user.get("id"):
        filters.append({"target_user_id": user["id"], "target_company_id": company_id})
    if user.get("email"):
        filters.append({"target_email": user["email"], "target_company_id": company_id})
    for row_filter in filters:
        for item in supabase_filter_rows("notifications", row_filter, order="created_at.desc", limit=500):
            if notification_visible_to_user(item, user):
                candidates[item["id"]] = item
    notices = sorted(candidates.values(), key=lambda item: str(item.get("created_at") or ""), reverse=True)
    notice_ids = {item["id"] for item in notices}
    deliveries: List[Dict[str, Any]] = []
    inbox: List[Dict[str, Any]] = []
    for notification_id in notice_ids:
        deliveries.extend(supabase_filter_rows("notification_deliveries", {"notification_id": notification_id}, order="created_at.desc", limit=100))
        for item in supabase_filter_rows("system_inbox", {"notification_id": notification_id}, order="created_at.desc", limit=20):
            if item.get("target_user_id") and str(item["target_user_id"]) == str(user.get("id") or ""):
                inbox.append(item)
    return {"notifications": notices, "deliveries": deliveries, "inbox": inbox}


def supabase_mark_notification_read(notification_id: str, session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    notice = supabase_get("notifications", notification_id)
    if not notice:
        raise ValueError("notification_not_found")
    if not notification_visible_to_user(notice, user):
        raise PermissionError("notification_access_denied")
    updated = supabase_patch("notifications", notification_id, {"status": "已讀"})
    for item in supabase_filter_rows("system_inbox", {"notification_id": notification_id}, order="created_at.desc", limit=50):
        if item.get("target_user_id") and str(item["target_user_id"]) == str(user.get("id") or ""):
            supabase_patch("system_inbox", item["id"], {"status": "已讀"})
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": official_actor_name(user),
        "actor_user_id": user.get("id") or "",
        "actor_email": user.get("email") or "",
        "action": "通知已讀",
        "target_type": "notification",
        "target_id": notification_id,
        "detail": "scoped_system_inbox_read",
        "event_type": "sensitive_access",
        "result": "success",
        "module_code": "notifications",
        "resource_type": "notification",
        "resource_id": notification_id,
        "request_id": f"req_{secrets.token_hex(8)}",
        "created_at": now(),
    })
    return updated


UI_USAGE_EVENT_TYPES = frozenset({"session_started", "route_view", "guidance_used", "search_result"})
UI_USAGE_DEVICE_CLASSES = frozenset({"desktop", "tablet", "mobile"})
UI_USAGE_SESSION_PATTERN = re.compile(r"^[A-Za-z0-9_-]{12,80}$")
UI_USAGE_ROUTE_PATTERN = re.compile(r"^[A-Za-z][A-Za-z0-9_-]{0,39}$")


def normalize_ui_usage_payload(payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = (session or {}).get("user") or {}
    if not user.get("id"):
        raise PermissionError("unauthorized")
    company_id = str(user.get("company_id") or "").strip()
    if not company_id:
        raise PermissionError("finance_company_unmapped")
    event_type = str(payload.get("eventType") or payload.get("event_type") or "").strip()
    session_id = str(payload.get("sessionId") or payload.get("session_id") or "").strip()
    device_class = str(payload.get("deviceClass") or payload.get("device_class") or "").strip()
    route = str(payload.get("route") or "dashboard").strip()
    if event_type not in UI_USAGE_EVENT_TYPES:
        raise ValueError("ui_usage_event_invalid")
    if not UI_USAGE_SESSION_PATTERN.fullmatch(session_id):
        raise ValueError("ui_usage_session_invalid")
    if device_class not in UI_USAGE_DEVICE_CLASSES:
        raise ValueError("ui_usage_device_invalid")
    if not UI_USAGE_ROUTE_PATTERN.fullmatch(route):
        raise ValueError("ui_usage_route_invalid")
    result_count = payload.get("resultCount", payload.get("result_count", 0))
    if isinstance(result_count, bool):
        raise ValueError("ui_usage_result_count_invalid")
    try:
        result_count = int(result_count or 0)
    except (TypeError, ValueError) as exc:
        raise ValueError("ui_usage_result_count_invalid") from exc
    if result_count < 0 or result_count > 1000:
        raise ValueError("ui_usage_result_count_invalid")
    return {
        "schemaVersion": 1,
        "eventType": event_type,
        "sessionId": session_id,
        "deviceClass": device_class,
        "route": route,
        "resultEmpty": payload.get("resultEmpty", payload.get("result_empty")) is True,
        "resultCount": result_count,
        "companyId": company_id[:80],
        "privacySafe": True,
    }


def record_ui_usage(conn: sqlite3.Connection, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    event = normalize_ui_usage_payload(payload, session)
    log_audit(
        conn,
        "Authenticated user",
        "UI usage event",
        "ui_usage",
        event["sessionId"],
        "privacy_safe_ui_usage",
        event_type="submit",
        module_code="uiux",
        resource_type="ui_usage",
        resource_id=event["sessionId"],
        metadata=event,
    )
    return {"ok": True, "accepted": event["eventType"], "privacySafe": True}


def supabase_record_ui_usage(payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    event = normalize_ui_usage_payload(payload, session)
    timestamp = now()
    supabase_insert("audit_logs", {
        "id": f"AUD-UI-{int(time.time() * 1000)}-{secrets.token_hex(4).upper()}",
        "actor": "Authenticated user",
        "action": "UI usage event",
        "target_type": "ui_usage",
        "target_id": event["sessionId"],
        "detail": "privacy_safe_ui_usage",
        "event_type": "submit",
        "severity": "info",
        "result": "success",
        "module_code": "uiux",
        "resource_type": "ui_usage",
        "resource_id": event["sessionId"],
        "data_scope": "company",
        "metadata_json": json.dumps(event, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
        "created_at": timestamp,
    })
    return {"ok": True, "accepted": event["eventType"], "privacySafe": True}


def ui_usage_summary_from_rows(rows: List[Dict[str, Any]], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = (session or {}).get("user") or {}
    if (
        not session_has_any_permission(session, ["reports.operational_view", "audit_logs.view", "audit_logs.export"])
        and str(user.get("role") or "") not in {"總務", "行政部主任", "行政部門主任", "執行長", "系統管理員"}
    ):
        raise PermissionError("ui_usage_summary_forbidden")
    company_id = str(user.get("company_id") or "").strip()
    if not company_id:
        raise PermissionError("finance_company_unmapped")
    cutoff = datetime.now() - timedelta(days=30)
    sessions: Dict[str, str] = {}
    guidance_sessions: set[str] = set()
    route_views = 0
    search_events = 0
    empty_search_events = 0
    for row in rows:
        created_at = parse_time(str(row.get("created_at") or ""))
        if created_at and created_at < cutoff:
            continue
        metadata = parse_json_field(row.get("metadata_json"))
        if metadata.get("privacySafe") is not True or metadata.get("companyId", "") != company_id:
            continue
        session_id = str(metadata.get("sessionId") or "")
        if not UI_USAGE_SESSION_PATTERN.fullmatch(session_id):
            continue
        event_type = str(metadata.get("eventType") or "")
        device_class = str(metadata.get("deviceClass") or "")
        if event_type == "session_started" and device_class in UI_USAGE_DEVICE_CLASSES:
            sessions.setdefault(session_id, device_class)
        elif event_type == "guidance_used":
            guidance_sessions.add(session_id)
        elif event_type == "route_view":
            route_views += 1
        elif event_type == "search_result":
            search_events += 1
            if metadata.get("resultEmpty") is True:
                empty_search_events += 1
    session_count = len(sessions)
    mobile_count = sum(1 for device in sessions.values() if device == "mobile")
    guided_count = len(guidance_sessions & set(sessions))
    return {
        "periodDays": 30,
        "sessions": session_count,
        "mobileSessions": mobile_count,
        "guidanceSessions": guided_count,
        "mobileRatio": round((mobile_count / max(session_count, 1)) * 100),
        "guidanceRate": round((guided_count / max(session_count, 1)) * 100),
        "routeViews": route_views,
        "searchEvents": search_events,
        "emptySearchEvents": empty_search_events,
        "source": "近 30 日匿名操作事件",
        "privacySafe": True,
    }


def ui_usage_summary(conn: sqlite3.Connection, session: Dict[str, Any] | None) -> Dict[str, Any]:
    rows = [row_to_dict(row) for row in conn.execute(
        "SELECT metadata_json, created_at FROM audit_logs WHERE target_type = 'ui_usage' ORDER BY created_at DESC LIMIT 2000"
    ).fetchall()]
    return ui_usage_summary_from_rows(rows, session)


def supabase_ui_usage_summary(session: Dict[str, Any] | None) -> Dict[str, Any]:
    rows = supabase_filter_rows("audit_logs", {"target_type": "ui_usage"}, order="created_at.desc", limit=2000)
    return ui_usage_summary_from_rows(rows, session)


OFFICIAL_DELEGATION_MANAGE_PERMISSION = "workflow.delegations.manage"


def _finance_delegation_actor_profile(user: Dict[str, Any] | None) -> Dict[str, str]:
    """Return a verified Finance role profile or fail closed.

    Delegation substitutes a person inside the approval chain, so an active
    account and a same-company id are insufficient.  The Finance role key,
    EDOC role and job level must describe the same position; title and durable
    Finance identity fields must also be present.
    """
    item = dict(user or {})
    role_key = canonical_logging_role(item.get("logging_role_key"))
    expected = LOGGING_ROLE_TO_EDOC_PROFILE.get(role_key)
    if (
        str(item.get("status") or "") != "啟用"
        or str(item.get("account_source") or "").strip().lower() != "finance"
        or not str(item.get("auth_user_id") or "").strip()
        or not str(item.get("finance_employee_id") or "").strip()
        or not str(item.get("company_id") or "").strip()
        or not str(item.get("title") or "").strip()
        or not expected
        or str(item.get("role") or "").strip() != expected["role"]
        or normalize_edoc_job_level(item.get("job_level")) != expected["job_level"]
    ):
        raise PermissionError("official_workflow_delegation_finance_actor_ineligible")
    return {
        "logging_role_key": role_key,
        "role": expected["role"],
        "job_level": expected["job_level"],
        "title": str(item.get("title") or "").strip(),
    }


def _can_manage_workflow_delegations(
    session: Dict[str, Any] | None,
    user: Dict[str, Any],
) -> bool:
    if not session_has_any_permission(session, [OFFICIAL_DELEGATION_MANAGE_PERMISSION]):
        return False
    return _finance_delegation_actor_profile(user)["logging_role_key"] == "admin_director"


def _assert_delegation_actor_scope(
    actor: Dict[str, Any],
    principal: Dict[str, Any],
    delegate: Dict[str, Any],
    *,
    can_manage_others: bool,
) -> None:
    actor_id = str(actor.get("id") or "")
    principal_id = str(principal.get("id") or "")
    delegate_id = str(delegate.get("id") or "")
    if not actor_id or not principal_id or not delegate_id:
        raise ValueError("official_workflow_delegation_actor_not_found")
    if actor_id != principal_id and not can_manage_others:
        raise PermissionError("official_workflow_delegation_manage_forbidden")
    # An administrator may arrange coverage but may not grant themselves a
    # decision path for somebody else's approvals.
    if actor_id != principal_id and actor_id == delegate_id:
        raise PermissionError("official_workflow_delegation_manager_self_assignment_forbidden")
    actor_profile = _finance_delegation_actor_profile(actor)
    principal_profile = _finance_delegation_actor_profile(principal)
    delegate_profile = _finance_delegation_actor_profile(delegate)
    company_ids = {
        str(actor.get("company_id") or "").strip(),
        str(principal.get("company_id") or "").strip(),
        str(delegate.get("company_id") or "").strip(),
    }
    if "" in company_ids or len(company_ids) != 1:
        raise PermissionError("official_workflow_delegation_company_forbidden")
    if (
        principal_profile["logging_role_key"] != delegate_profile["logging_role_key"]
        or principal_profile["role"] != delegate_profile["role"]
        or principal_profile["job_level"] != delegate_profile["job_level"]
    ):
        raise PermissionError("official_workflow_delegation_role_qualification_mismatch")
    if actor_id != principal_id and actor_profile["logging_role_key"] != "admin_director":
        raise PermissionError("official_workflow_delegation_manager_role_ineligible")


def _validated_delegation_payload(
    payload: Dict[str, Any],
    actor: Dict[str, Any],
    principal: Dict[str, Any],
    delegate: Dict[str, Any],
) -> Dict[str, Any]:
    if principal.get("id") == delegate.get("id"):
        raise ValueError("official_workflow_delegation_self_forbidden")
    principal_company = str(principal.get("company_id") or "").strip()
    delegate_company = str(delegate.get("company_id") or "").strip()
    if not principal_company or principal_company != delegate_company:
        raise PermissionError("official_workflow_delegation_company_forbidden")
    actor_company = str(actor.get("company_id") or "").strip()
    if not actor_company or actor_company != principal_company:
        raise PermissionError("official_workflow_delegation_company_forbidden")
    starts_at = str(payload.get("starts_at") or payload.get("startsAt") or now()).strip()
    ends_at = str(payload.get("ends_at") or payload.get("endsAt") or "").strip()
    starts = parse_date_value(starts_at)
    ends = parse_date_value(ends_at)
    if not starts or not ends or ends <= starts:
        raise ValueError("official_workflow_delegation_period_invalid")
    if ends <= datetime.now():
        raise ValueError("official_workflow_delegation_period_expired")
    if ends - starts > timedelta(days=180):
        raise ValueError("official_workflow_delegation_period_too_long")
    reason = str(payload.get("reason") or "").strip()
    if len(reason) < 2:
        raise ValueError("official_workflow_delegation_reason_required")
    return {
        "company_id": principal_company,
        "principal_user_id": principal["id"],
        "delegate_user_id": delegate["id"],
        "starts_at": starts_at,
        "ends_at": ends_at,
        "reason": reason[:500],
    }


def list_official_workflow_delegations(
    conn: sqlite3.Connection,
    session: Dict[str, Any] | None,
) -> List[Dict[str, Any]]:
    user = official_session_user(session)
    _finance_delegation_actor_profile(user)
    can_manage = _can_manage_workflow_delegations(session, user)
    if can_manage and user.get("company_id"):
        rows = conn.execute(
            "SELECT * FROM official_workflow_delegations WHERE company_id = ? ORDER BY starts_at DESC LIMIT 500",
            (user["company_id"],),
        ).fetchall()
    else:
        rows = conn.execute(
            """
            SELECT * FROM official_workflow_delegations
            WHERE principal_user_id = ? OR delegate_user_id = ?
            ORDER BY starts_at DESC LIMIT 500
            """,
            (user["id"], user["id"]),
        ).fetchall()
    return [row_to_dict(row) for row in rows]


def official_workflow_delegation_candidates(
    conn: sqlite3.Connection,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    """Return the smallest same-company directory needed by the delegation UI.

    This intentionally does not reuse the generic users API.  A normal user
    needs to choose a named delegate, but must not gain access to account,
    authentication, email, manager, or cross-company roster fields.
    """
    user = official_session_user(session)
    company_id = str(user.get("company_id") or "").strip()
    if not company_id:
        raise PermissionError("official_workflow_delegation_company_required")
    rows = conn.execute(
        """
        SELECT *
        FROM users
        WHERE status = '啟用' AND company_id = ?
        ORDER BY unit, name, id
        LIMIT 500
        """,
        (company_id,),
    ).fetchall()
    can_manage = _can_manage_workflow_delegations(session, user)
    current_profile = _finance_delegation_actor_profile(user)
    eligible_rows: List[Dict[str, Any]] = []
    for row in rows:
        item = row_to_dict(row)
        try:
            profile = _finance_delegation_actor_profile(item)
            if not can_manage:
                if (
                    profile["logging_role_key"] != current_profile["logging_role_key"]
                    or profile["role"] != current_profile["role"]
                    or profile["job_level"] != current_profile["job_level"]
                ):
                    continue
            eligible_rows.append(item)
        except PermissionError:
            continue
    return {
        "current_user_id": user["id"],
        "can_manage": can_manage,
        "users": [
            {
                "id": row["id"],
                "name": row["name"],
                "unit": row["unit"],
                "title": row["title"],
                "role": row["role"],
            }
            for row in eligible_rows
        ],
    }


def create_official_workflow_delegation(
    conn: sqlite3.Connection,
    payload: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    actor = official_session_user(session)
    principal_id = str(payload.get("principal_user_id") or payload.get("principalUserId") or actor.get("id") or "")
    delegate_id = str(payload.get("delegate_user_id") or payload.get("delegateUserId") or "")
    principal = active_user_by_id(conn, principal_id)
    delegate = active_user_by_id(conn, delegate_id)
    if not principal or not delegate:
        raise ValueError("official_workflow_delegation_actor_not_found")
    _assert_delegation_actor_scope(
        actor,
        principal,
        delegate,
        can_manage_others=session_has_any_permission(session, [OFFICIAL_DELEGATION_MANAGE_PERMISSION]),
    )
    values = _validated_delegation_payload(payload, actor, principal, delegate)
    overlaps = conn.execute(
        """
        SELECT 1 FROM official_workflow_delegations
        WHERE company_id = ? AND principal_user_id = ? AND status = 'active'
          AND starts_at < ? AND ends_at > ?
        LIMIT 1
        """,
        (values["company_id"], principal_id, values["ends_at"], values["starts_at"]),
    ).fetchone()
    if overlaps:
        raise ValueError("official_workflow_delegation_overlap")
    timestamp = now()
    row = {
        "id": f"OWD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        **values,
        "status": "active",
        "created_by": actor["id"],
        "revoked_by": None,
        "revoked_at": None,
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    insert_row(conn, "official_workflow_delegations", row)
    log_audit(
        conn,
        official_actor_name(actor),
        "建立簽核代理",
        "official_workflow_delegation",
        row["id"],
        f"principal={principal_id};delegate={delegate_id};period={values['starts_at']}..{values['ends_at']}",
        event_type="permission_change",
        actor_user_id=actor["id"],
        reason=values["reason"],
    )
    return row


def revoke_official_workflow_delegation(
    conn: sqlite3.Connection,
    delegation_id: str,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    actor = official_session_user(session)
    row = conn.execute("SELECT * FROM official_workflow_delegations WHERE id = ?", (delegation_id,)).fetchone()
    if not row:
        raise ValueError("official_workflow_delegation_not_found")
    item = row_to_dict(row)
    manages_other = item.get("principal_user_id") != actor.get("id")
    if manages_other and not session_has_any_permission(session, [OFFICIAL_DELEGATION_MANAGE_PERMISSION]):
        raise PermissionError("official_workflow_delegation_manage_forbidden")
    actor_profile = _finance_delegation_actor_profile(actor)
    if manages_other and actor_profile["logging_role_key"] != "admin_director":
        raise PermissionError("official_workflow_delegation_manager_role_ineligible")
    if not str(actor.get("company_id") or "") or str(actor.get("company_id") or "") != str(item.get("company_id") or ""):
        raise PermissionError("official_workflow_delegation_company_forbidden")
    if item.get("status") != "active":
        return item
    timestamp = now()
    conn.execute(
        "UPDATE official_workflow_delegations SET status = 'revoked', revoked_by = ?, revoked_at = ?, updated_at = ? WHERE id = ? AND status = 'active'",
        (actor["id"], timestamp, timestamp, delegation_id),
    )
    log_audit(conn, official_actor_name(actor), "撤銷簽核代理", "official_workflow_delegation", delegation_id, "delegation_revoked", event_type="permission_change", actor_user_id=actor["id"])
    return row_to_dict(conn.execute("SELECT * FROM official_workflow_delegations WHERE id = ?", (delegation_id,)).fetchone())


def supabase_list_official_workflow_delegations(session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    user = supabase_official_session_user(session)
    _finance_delegation_actor_profile(user)
    can_manage = _can_manage_workflow_delegations(session, user)
    if can_manage and user.get("company_id"):
        return supabase_filter_rows("official_workflow_delegations", {"company_id": user["company_id"]}, order="starts_at.desc", limit=500)
    rows: Dict[str, Dict[str, Any]] = {}
    for key in ("principal_user_id", "delegate_user_id"):
        for item in supabase_filter_rows("official_workflow_delegations", {key: user["id"]}, order="starts_at.desc", limit=500):
            rows[item["id"]] = item
    return sorted(rows.values(), key=lambda item: str(item.get("starts_at") or ""), reverse=True)


