def supabase_create_official_workflow_delegation(payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    actor = supabase_official_session_user(session)
    principal_id = str(payload.get("principal_user_id") or payload.get("principalUserId") or actor.get("id") or "")
    delegate_id = str(payload.get("delegate_user_id") or payload.get("delegateUserId") or "")
    principal = supabase_user_by_id(principal_id)
    delegate = supabase_user_by_id(delegate_id)
    if not principal or not delegate or principal.get("status") != "啟用" or delegate.get("status") != "啟用":
        raise ValueError("official_workflow_delegation_actor_not_found")
    _assert_delegation_actor_scope(
        actor,
        principal,
        delegate,
        can_manage_others=session_has_any_permission(session, [OFFICIAL_DELEGATION_MANAGE_PERMISSION]),
    )
    values = _validated_delegation_payload(payload, actor, principal, delegate)
    # The RPC serializes company+principal creation and checks overlap inside
    # the same transaction.  A read-then-insert check here would race and could
    # create two active delegations that later make approvals fail ambiguous.
    raw = supabase_request("POST", "rpc/edoc_create_official_workflow_delegation", {
        "p_id": f"OWD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "p_company_id": values["company_id"],
        "p_principal_user_id": principal_id,
        "p_delegate_user_id": delegate_id,
        "p_starts_at": values["starts_at"],
        "p_ends_at": values["ends_at"],
        "p_reason": values["reason"],
        "p_created_by": actor["id"],
    })
    if isinstance(raw, list):
        row = raw[0] if len(raw) == 1 and isinstance(raw[0], dict) else {}
    else:
        row = raw if isinstance(raw, dict) else {}
    if not row or row.get("principal_user_id") != principal_id or row.get("delegate_user_id") != delegate_id:
        raise RuntimeError("official_workflow_delegation_create_invalid_response")
    return row


def supabase_revoke_official_workflow_delegation(delegation_id: str, session: Dict[str, Any] | None) -> Dict[str, Any]:
    actor = supabase_official_session_user(session)
    item = supabase_get("official_workflow_delegations", delegation_id)
    if not item:
        raise ValueError("official_workflow_delegation_not_found")
    manages_other = item.get("principal_user_id") != actor.get("id")
    if manages_other and not session_has_any_permission(session, [OFFICIAL_DELEGATION_MANAGE_PERMISSION]):
        raise PermissionError("official_workflow_delegation_manage_forbidden")
    actor_profile = _finance_delegation_actor_profile(actor)
    if manages_other and actor_profile["logging_role_key"] != "admin_director":
        raise PermissionError("official_workflow_delegation_manager_role_ineligible")
    if not str(actor.get("company_id") or "") or str(actor.get("company_id") or "") != str(item.get("company_id") or ""):
        raise PermissionError("official_workflow_delegation_company_forbidden")
    raw = supabase_request(
        "POST",
        "rpc/edoc_revoke_official_workflow_delegation",
        {"p_delegation_id": delegation_id, "p_revoked_by": actor["id"]},
    )
    if isinstance(raw, list):
        updated = raw[0] if len(raw) == 1 and isinstance(raw[0], dict) else {}
    else:
        updated = raw if isinstance(raw, dict) else {}
    if not updated or updated.get("id") != delegation_id:
        raise RuntimeError("official_workflow_delegation_revoke_invalid_response")
    return updated


def supabase_headers(extra: Dict[str, str] | None = None) -> Dict[str, str]:
    headers = {
        "apikey": SUPABASE_SERVICE_ROLE_KEY,
        "Content-Type": "application/json",
    }
    # Modern Supabase ``sb_secret_`` API keys are not JWTs.  Sending one as a
    # Bearer token makes the gateway reject an otherwise valid server key with
    # HTTP 401.  Legacy service_role JWTs still require the Authorization
    # header and remain supported during the migration window.
    if not SUPABASE_SERVICE_ROLE_KEY.startswith("sb_secret_"):
        headers["Authorization"] = f"Bearer {SUPABASE_SERVICE_ROLE_KEY}"
    if extra:
        headers.update(extra)
    return headers


def supabase_storage_headers(extra: Dict[str, str] | None = None) -> Dict[str, str]:
    key = storage_service_role_key()
    if not key:
        raise SupabaseConfigurationError("supabase_storage_server_credential_missing")
    headers = {
        "apikey": key,
        "Content-Type": "application/json",
    }
    # Modern secret keys authenticate through ``apikey``.  Legacy service-role
    # JWTs additionally require a Bearer header.
    if not key.startswith("sb_secret_"):
        headers["Authorization"] = f"Bearer {key}"
    if extra:
        headers.update(extra)
    return headers


def supabase_request(method: str, path: str, body: Any = None, prefer: str = "return=representation") -> Any:
    if not SUPABASE_URL or not SUPABASE_SERVICE_ROLE_KEY:
        raise SupabaseConfigurationError("supabase_runtime_env_missing")
    url = f"{SUPABASE_URL}/rest/v1/{path.lstrip('/')}"
    data = None if body is None else json.dumps(body, ensure_ascii=False).encode("utf-8")
    headers = supabase_headers({"Prefer": prefer})
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            raw = response.read().decode("utf-8")
            return json.loads(raw) if raw else []
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8")
        raise RuntimeError(f"Supabase {exc.code}: {detail}") from exc


def supabase_list(table: str, query: Dict[str, List[str]]) -> List[Dict[str, Any]]:
    params = {"select": "*", "limit": "500"}
    if "status" in query:
        params["status"] = f"eq.{query['status'][0]}"
    if "direction" in query and table == "documents":
        params["direction"] = f"eq.{query['direction'][0]}"
    qs = urllib.parse.urlencode(params)
    rows = supabase_request("GET", f"{table}?{qs}")
    if table == "companies":
        for row in rows:
            enabled = pdf_editor_v2_enabled_for_company(str(row.get("id") or ""))
            row["pdf_editor_v2"] = enabled
            row["feature_flags"] = {"pdf_editor_v2": enabled}
    return rows


def supabase_get(table: str, row_id: str) -> Dict[str, Any] | None:
    qs = urllib.parse.urlencode({"select": "*", "id": f"eq.{row_id}", "limit": "1"})
    rows = supabase_request("GET", f"{table}?{qs}")
    return rows[0] if rows else None


def supabase_insert(table: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    if "id" not in payload or not payload["id"]:
        payload["id"] = f"{table.upper()}-{int(time.time() * 1000)}"
    if table == "users":
        apply_user_permission_defaults(payload)
    if table == "documents" and payload.get("direction") == "發文" and not payload.get("doc_no"):
        payload["doc_no"] = supabase_next_dispatch_no()
    timestamp = now()
    if table in {"documents", "recipients", "exchange_tasks", "exchange_outbox", "exchange_inbox", "settings", "notification_rules", "company_registry", "department_registry", "seal_type_registry", "companies", "seal_reference_options", "company_seals", "seal_usage_requests", "seal_usage_approvals", "workflow_tasks", "contracts", "contract_parties", "contract_approvals", "module_account_links", "official_documents", "official_document_approval_steps", "official_document_stamp_requests", "official_document_stamp_positions", "official_document_text_overlays", "official_document_dispatch_records", "official_workflow_delegations", "inbound_documents", "internal_dispatches", "internal_dispatch_recipients"}:
        payload.setdefault("updated_at", timestamp)
    if table in {"documents", "attachments", "exchange_events", "exchange_outbox", "exchange_inbox", "exchange_log", "exchange_attachment", "exchange_status_history", "audit_logs", "users", "notifications", "notification_deliveries", "system_inbox", "company_registry", "department_registry", "seal_type_registry", "companies", "seal_reference_options", "company_seals", "seal_permissions", "seal_usage_approvals", "seal_usage_logs", "workflow_tasks", "contracts", "contract_parties", "contract_approvals", "signature_provider_events", "module_account_links", "official_documents", "official_document_files", "official_document_approval_steps", "official_document_approval_logs", "official_document_stamp_requests", "official_document_stamp_positions", "official_document_text_overlays", "official_document_dispatch_records", "official_workflow_delegations", "official_document_archive_exports", "inbound_documents", "inbound_document_attachments", "internal_dispatches", "internal_dispatch_recipients", "internal_dispatch_replies", "internal_dispatch_logs"}:
        payload.setdefault("created_at", timestamp)
    if table in {"documents", "workflow_tasks", "contracts", "contract_approvals", "seal_usage_requests", "exchange_log", "exchange_inbox", "exchange_status_history", "audit_logs", "module_account_links", "official_documents", "inbound_documents", "internal_dispatches"}:
        for key, value in list(payload.items()):
            if key.endswith("_json") and not isinstance(value, str):
                payload[key] = json.dumps(value, ensure_ascii=False)
    rows = supabase_request("POST", table, payload)
    created = rows[0] if rows else payload
    if table == "users":
        permission_fields = {"role", "status", "unit", "title", "job_level", "mfa_status"}
        supabase_insert("audit_logs", {
            "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "actor": "API",
            "action": "權限異動",
            "target_type": "user_role",
            "target_id": created.get("id"),
            "ip": "vercel",
            "device": "serverless",
            "detail": "建立使用者帳號與初始角色權限。",
            "event_type": "permission_change",
            "severity": "critical",
            "result": "success",
            "module_code": "system_permissions",
            "resource_type": "user_role",
            "resource_id": created.get("id"),
            "data_scope": "custom",
            "actor_roles_json": ["system_permissions.manage"],
            "target_user_id": created.get("id"),
            "target_email": created.get("email", ""),
            "reason": "建立使用者帳號與初始角色權限。",
            "request_id": f"req_{secrets.token_hex(8)}",
            "before_snapshot_json": {},
            "after_snapshot_json": {key: created.get(key) for key in sorted(permission_fields) if key in created},
            "metadata_json": {"source": "edoc_rbac_supabase"},
        })
    return created


def claim_supabase_portal_handoff_jti(payload: Dict[str, Any]) -> bool:
    """Atomically consume one signed Portal handoff through the unique hash key."""
    jti_hash = portal_handoff_jti_hash(roster_text(payload.get("jti")))
    row = {
        "jti_hash": jti_hash,
        "issued_at": int(payload.get("iat") or 0),
        "expires_at": int(payload.get("exp") or 0),
        "consumed_at": now(),
    }
    try:
        supabase_request("POST", "portal_handoff_nonces", row)
        return True
    except RuntimeError:
        query = urllib.parse.urlencode({"select": "jti_hash", "jti_hash": f"eq.{jti_hash}", "limit": "1"})
        if supabase_request("GET", f"portal_handoff_nonces?{query}"):
            return False
        raise


def supabase_next_dispatch_no() -> str:
    date_serial = roc_date_serial()
    prefix = f"歲悅字第{date_serial}"
    qs = urllib.parse.urlencode({
        "select": "doc_no",
        "direction": "eq.發文",
        "doc_no": f"like.{prefix}%號",
        "limit": "500",
    })
    rows = supabase_request("GET", f"documents?{qs}")
    max_serial = 0
    for row in rows:
        value = row.get("doc_no", "")
        if value.startswith(prefix) and value.endswith("號"):
            serial = value[len(prefix):-1]
            if serial.isdigit():
                max_serial = max(max_serial, int(serial))
    return f"{prefix}{max_serial + 1:03d}號"


def supabase_patch(table: str, row_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    before = supabase_get(table, row_id) if table == "users" else None
    if table == "users":
        permission_inputs = {"role", "unit", "title", "job_level", "company", "region", "class_name"}
        merged_payload = {**(before or {}), **payload}
        profile = edoc_roster_permission_profile(merged_payload)
        if "job_level" in payload:
            payload["job_level"] = profile["job_level"]
        if permission_inputs.intersection(payload) and (not payload.get("role") or payload.get("role") not in ALLOWED_EDOC_ROLES):
            payload["role"] = profile["role"]
    if table in {"documents", "recipients", "exchange_tasks", "exchange_outbox", "exchange_inbox", "settings", "background_jobs", "notification_rules", "company_registry", "department_registry", "seal_type_registry", "companies", "seal_reference_options", "company_seals", "seal_usage_requests", "seal_usage_approvals", "workflow_tasks", "contracts", "contract_parties", "contract_approvals", "module_account_links", "official_documents", "official_document_approval_steps", "official_document_stamp_requests", "official_document_stamp_positions", "official_document_text_overlays", "official_document_dispatch_records", "official_workflow_delegations", "inbound_documents", "internal_dispatches", "internal_dispatch_recipients"}:
        payload["updated_at"] = now()
    if table in {"documents", "workflow_tasks", "contracts", "contract_approvals", "seal_usage_requests", "exchange_log", "exchange_inbox", "exchange_status_history", "audit_logs", "module_account_links", "official_documents", "inbound_documents", "internal_dispatches"}:
        for key, value in list(payload.items()):
            if key.endswith("_json") and not isinstance(value, str):
                payload[key] = json.dumps(value, ensure_ascii=False)
    qs = urllib.parse.urlencode({"id": f"eq.{row_id}"})
    rows = supabase_request("PATCH", f"{table}?{qs}", payload)
    updated = rows[0] if rows else {}
    permission_fields = {"role", "status", "unit", "title", "job_level", "mfa_status"}
    if table == "users" and before and updated and permission_fields.intersection(payload):
        supabase_insert("audit_logs", {
            "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "actor": "API",
            "action": "權限異動",
            "target_type": "user_role",
            "target_id": row_id,
            "ip": "vercel",
            "device": "serverless",
            "detail": "使用者角色、職等、狀態或權限相關資料異動。",
            "event_type": "permission_change",
            "severity": "critical",
            "result": "success",
            "module_code": "system_permissions",
            "resource_type": "user_role",
            "resource_id": row_id,
            "data_scope": "custom",
            "actor_roles_json": ["system_permissions.manage"],
            "target_user_id": row_id,
            "target_email": updated.get("email", before.get("email", "")),
            "reason": "使用者角色、職等、狀態或權限相關資料異動。",
            "request_id": f"req_{secrets.token_hex(8)}",
            "before_snapshot_json": {key: before.get(key) for key in sorted(permission_fields) if key in before},
            "after_snapshot_json": {key: updated.get(key) for key in sorted(permission_fields) if key in updated},
            "metadata_json": {"source": "edoc_rbac_supabase"},
        })
    return updated


def supabase_import_company_launch_roster(payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    if is_production():
        raise PermissionError("finance_company_master_read_only")
    rows = payload.get("rows") or []
    if not isinstance(rows, list) or not rows:
        raise ValueError("company_roster_rows_required")
    if len(rows) > 200:
        raise ValueError("company_roster_rows_limit_exceeded")
    actor = (session or {}).get("user") or {}
    actor_name = actor.get("email") or actor.get("name") or payload.get("actor") or "API"
    imported: List[Dict[str, Any]] = []
    errors: List[Dict[str, Any]] = []
    for index, raw_row in enumerate(rows, start=1):
        try:
            normalized = normalize_company_launch_roster_row(raw_row, index)
            existing = supabase_get("companies", normalized["id"])
            before_status = existing.get("status") if existing else ""
            if existing:
                company = supabase_patch("companies", normalized["id"], {
                    "name": normalized["name"],
                    "tax_id": normalized["tax_id"],
                    "status": normalized["status"],
                })
                action = "updated"
            else:
                company = supabase_insert("companies", dict(normalized))
                action = "created"
            registry_payload = {
                "id": normalized["id"],
                "name": normalized["name"],
                "tax_id": normalized["tax_id"] or "待設定",
                "status": "啟用" if normalized["status"] == "active" else "停用",
            }
            if supabase_get("company_registry", normalized["id"]):
                update_payload = dict(registry_payload)
                update_payload.pop("id", None)
                supabase_patch("company_registry", normalized["id"], update_payload)
            else:
                supabase_insert("company_registry", registry_payload)
            imported.append({"row": index, "action": action, "company": company})
            supabase_insert("audit_logs", {
                "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
                "actor": actor_name,
                "action": "公司上線名冊匯入",
                "target_type": "companies",
                "target_id": normalized["id"],
                "ip": "vercel",
                "device": "serverless",
                "detail": json.dumps({
                    "row": index,
                    "action": action,
                    "company_id": normalized["id"],
                    "status": normalized["status"],
                    "before_status": before_status,
                    "contains_secret": False,
                    "contains_seal_original": False,
                }, ensure_ascii=False),
                "event_type": "permission_change",
                "severity": "critical",
                "result": "success",
                "module_code": "companies",
                "resource_type": "company",
                "resource_id": normalized["id"],
                "data_scope": "custom",
                "actor_user_id": actor.get("id") or "",
                "actor_email": actor.get("email") or "",
                "actor_roles_json": ["seals.manage", "system_permissions.manage"],
                "reason": "公司上線名冊匯入；只含公司 metadata，不含 secret、正式公文內容或原章檔案。",
                "request_id": f"req_{secrets.token_hex(8)}",
                "before_snapshot_json": {"status": before_status} if before_status else {},
                "after_snapshot_json": {
                    "company_id": normalized["id"],
                    "status": normalized["status"],
                    "contains_secret": False,
                },
                "metadata_json": {"source": "company_launch_roster_import", "contains_secret": False},
            })
        except Exception as exc:
            errors.append({"row": index, "error": str(exc)})
    summary = {
        "received": len(rows),
        "imported": len(imported),
        "created": sum(1 for item in imported if item.get("action") == "created"),
        "updated": sum(1 for item in imported if item.get("action") == "updated"),
        "failed": len(errors),
        "containsSecrets": False,
        "containsSealOriginals": False,
    }
    return {
        "ok": not errors,
        "summary": summary,
        "imported": imported,
        "errors": errors,
        "sealVaultReadiness": current_seal_vault_readiness_report(),
        "launchCutoverPackage": current_launch_cutover_package(),
    }


