def supabase_filter_rows(table: str, filters: Dict[str, Any] | None = None, *, order: str = "", limit: int = 500, select: str = "*") -> List[Dict[str, Any]]:
    params: Dict[str, str] = {"select": select, "limit": str(limit)}
    for key, value in (filters or {}).items():
        if value is None:
            continue
        if value == "__is_null__":
            params[key] = "is.null"
        elif isinstance(value, bool):
            params[key] = f"eq.{str(value).lower()}"
        else:
            params[key] = f"eq.{value}"
    if order:
        params["order"] = order
    return supabase_request("GET", f"{table}?{urllib.parse.urlencode(params)}")


def supabase_update_many(table: str, filters: Dict[str, Any], payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    params = {
        key: (f"is.null" if value == "__is_null__" else f"eq.{str(value).lower()}" if isinstance(value, bool) else f"eq.{value}")
        for key, value in filters.items()
    }
    return supabase_request("PATCH", f"{table}?{urllib.parse.urlencode(params)}", payload)


def supabase_storage_object_url(storage_key: str, bucket: str | None = None) -> str:
    base = object_storage_endpoint()
    if not base:
        raise ValueError("supabase_storage_endpoint_required")
    storage_bucket = bucket or EDOC_STORAGE_BUCKET
    return f"{base.rstrip('/')}/object/{urllib.parse.quote(storage_bucket, safe='')}/{urllib.parse.quote(storage_key, safe='/')}"


def supabase_storage_upload(storage_key: str, data: bytes, mime_type: str, bucket: str | None = None) -> None:
    url = supabase_storage_object_url(storage_key, bucket)
    headers = supabase_storage_headers({"Content-Type": mime_type, "x-upsert": "false"})
    request = urllib.request.Request(url, data=data, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            response.read()
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "ignore")
        raise ValueError(f"supabase_storage_upload_failed:{exc.code}:{redact_text(detail)}") from exc


def supabase_storage_delete(storage_key: str, bucket: str | None = None) -> None:
    """Delete an object through Storage API (never by mutating storage schema)."""
    base = object_storage_endpoint()
    if not base:
        raise ValueError("supabase_storage_endpoint_required")
    storage_bucket = bucket or EDOC_STORAGE_BUCKET
    url = f"{base.rstrip('/')}/object/{urllib.parse.quote(storage_bucket, safe='')}"
    request = urllib.request.Request(
        url,
        data=json.dumps({"prefixes": [storage_key]}).encode("utf-8"),
        headers=supabase_storage_headers({"Content-Type": "application/json"}),
        method="DELETE",
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            response.read()
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "ignore")
        raise ValueError(f"supabase_storage_delete_failed:{exc.code}:{redact_text(detail)}") from exc


def supabase_storage_download(storage_key: str, bucket: str | None = None) -> bytes:
    url = supabase_storage_object_url(storage_key, bucket)
    request = urllib.request.Request(url, headers=supabase_storage_headers(), method="GET")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return response.read()
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "ignore")
        raise ValueError(f"supabase_storage_download_failed:{exc.code}:{redact_text(detail)}") from exc


def supabase_storage_create_signed_download_url(
    storage_key: str,
    bucket: str | None = None,
    *,
    file_name: str = "",
    download: bool = True,
    ttl_seconds: int | None = None,
) -> Dict[str, Any]:
    """Create a short-lived URL without proxying object bytes through Vercel.

    This helper is intentionally restricted to the normal EDOC private bucket.
    Seal Vault objects are never eligible for browser download, even when a
    caller already knows an object path or asks with the service-role backend.
    """
    storage_bucket = str(bucket or EDOC_STORAGE_BUCKET).strip()
    object_key = str(storage_key or "").strip().lstrip("/")
    if (
        storage_bucket == EDOC_SEAL_STORAGE_BUCKET
        or is_seal_vault_file({"storage_key": object_key})
    ):
        raise PermissionError("seal_vault_signed_download_forbidden")
    if not storage_bucket or storage_bucket != EDOC_STORAGE_BUCKET:
        raise PermissionError("supabase_signed_download_bucket_forbidden")
    if not object_key:
        raise ValueError("supabase_signed_download_storage_key_required")
    ttl = int(EDOC_SIGNED_URL_TTL_SECONDS if ttl_seconds is None else ttl_seconds)
    if ttl < 1 or ttl > 900:
        raise ValueError("supabase_signed_download_ttl_invalid")
    base = object_storage_endpoint().rstrip("/")
    if not base:
        raise ValueError("supabase_storage_endpoint_required")
    sign_url = (
        f"{base}/object/sign/{urllib.parse.quote(storage_bucket, safe='')}/"
        f"{urllib.parse.quote(object_key, safe='/')}"
    )
    request = urllib.request.Request(
        sign_url,
        data=json.dumps({"expiresIn": ttl}).encode("utf-8"),
        headers=supabase_storage_headers({"Content-Type": "application/json", "Cache-Control": "no-store"}),
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            payload = json.loads(response.read().decode("utf-8") or "{}")
    except urllib.error.HTTPError as exc:
        detail = redact_text(exc.read().decode("utf-8", "ignore"))
        raise ValueError(f"supabase_signed_download_failed:{exc.code}:{detail[:160]}") from exc
    except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
        raise ValueError("supabase_signed_download_unavailable") from exc
    signed_path = str(payload.get("signedURL") or payload.get("signedUrl") or "").strip()
    if not signed_path:
        raise ValueError("supabase_signed_download_url_missing")
    if signed_path.startswith("http://") or signed_path.startswith("https://"):
        signed_url = signed_path
        expected = urllib.parse.urlparse(base)
        actual = urllib.parse.urlparse(signed_url)
        if (actual.scheme, actual.hostname, actual.port) != (expected.scheme, expected.hostname, expected.port):
            raise ValueError("supabase_signed_download_origin_invalid")
    else:
        signed_url = f"{base}/{signed_path.lstrip('/')}"
    safe_name = Path(file_name).name if file_name else ""
    if download:
        separator = "&" if "?" in signed_url else "?"
        signed_url = f"{signed_url}{separator}download={urllib.parse.quote(safe_name, safe='')}"
    return {
        "url": signed_url,
        "expires_in": ttl,
        "expires_at": (datetime.now() + timedelta(seconds=ttl)).isoformat(timespec="seconds"),
    }


def supabase_storage_create_signed_scan_url(
    storage_key: str,
    bucket: str,
    *,
    ttl_seconds: int = 60,
) -> Dict[str, Any]:
    """Create an internal-only URL for the private AV service.

    Unlike browser download URLs, this may address either the normal private
    bucket or Seal Vault.  The URL is returned only to the HMAC-authenticated
    scanner request body, is never logged, carries no download file name, and
    expires within two minutes.
    """
    storage_bucket = str(bucket or "").strip()
    object_key = str(storage_key or "").strip().lstrip("/")
    if storage_bucket not in {EDOC_STORAGE_BUCKET, EDOC_SEAL_STORAGE_BUCKET}:
        raise PermissionError("supabase_scan_url_bucket_forbidden")
    if not object_key:
        raise ValueError("supabase_scan_url_storage_key_required")
    if storage_bucket == EDOC_SEAL_STORAGE_BUCKET:
        if not (
            object_key.startswith(f"{SEAL_VAULT_PURPOSE_PREFIX}/")
            or object_key.startswith("private/seals/")
        ):
            raise PermissionError("supabase_scan_url_seal_path_forbidden")
    elif is_seal_vault_file({"storage_key": object_key}):
        raise PermissionError("supabase_scan_url_bucket_path_mismatch")
    ttl = int(ttl_seconds)
    if ttl < 30 or ttl > 120:
        raise ValueError("supabase_scan_url_ttl_invalid")
    base = object_storage_endpoint().rstrip("/")
    if not base:
        raise ValueError("supabase_storage_endpoint_required")
    sign_url = (
        f"{base}/object/sign/{urllib.parse.quote(storage_bucket, safe='')}/"
        f"{urllib.parse.quote(object_key, safe='/')}"
    )
    request = urllib.request.Request(
        sign_url,
        data=json.dumps({"expiresIn": ttl}).encode("utf-8"),
        headers=supabase_storage_headers({"Content-Type": "application/json", "Cache-Control": "no-store"}),
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            payload = json.loads(response.read(4096).decode("utf-8") or "{}")
    except urllib.error.HTTPError as exc:
        exc.read(4096)
        raise ValueError(f"supabase_scan_url_failed:{exc.code}") from exc
    except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
        raise ValueError("supabase_scan_url_unavailable") from exc
    signed_path = str(payload.get("signedURL") or payload.get("signedUrl") or "").strip()
    if not signed_path:
        raise ValueError("supabase_scan_url_missing")
    if signed_path.startswith("http://") or signed_path.startswith("https://"):
        signed_url = signed_path
        expected = urllib.parse.urlparse(base)
        actual = urllib.parse.urlparse(signed_url)
        if (actual.scheme, actual.hostname, actual.port) != (expected.scheme, expected.hostname, expected.port):
            raise ValueError("supabase_scan_url_origin_invalid")
    else:
        signed_url = f"{base}/{signed_path.lstrip('/')}"
    actual = urllib.parse.urlparse(signed_url)
    if actual.scheme != "https" or not actual.query or not actual.path.startswith("/storage/v1/object/sign/"):
        raise ValueError("supabase_scan_url_invalid")
    return {
        "url": signed_url,
        "expires_in": ttl,
        "expires_at": (datetime.now() + timedelta(seconds=ttl)).isoformat(timespec="seconds"),
    }


def supabase_store_file_object(document_id: str, file_name: str, data: bytes, purpose: str, version_label: str, actor: str, mime_type: str) -> Dict[str, Any]:
    file_id = f"FILE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    safe_name = Path(file_name).name
    storage_key = f"{purpose}/{document_id}/{file_id}-{safe_name}"
    is_seal_vault = purpose.startswith(SEAL_VAULT_PURPOSE_PREFIX)
    bucket = EDOC_SEAL_STORAGE_BUCKET if is_seal_vault else EDOC_STORAGE_BUCKET
    supabase_storage_upload(storage_key, data, mime_type, bucket)
    row = {
        "id": file_id,
        "document_id": document_id,
        "file_name": safe_name,
        "storage_key": storage_key,
        "bucket": bucket,
        "storage_provider": "seal-vault" if is_seal_vault else (EDOC_STORAGE_PROVIDER or "supabase"),
        "mime_type": mime_type,
        "size_bytes": len(data),
        "sha256": sha256_bytes(data),
        "encrypted_sha256": "",
        "encryption_status": "由物件儲存服務控管",
        "encryption_alg": "",
        "encryption_key_id": "",
        "scan_status": "待掃描",
        "scan_engine": EDOC_SCAN_ENGINE,
        "quarantine_reason": "",
        "signed_url_expires_at": "",
        "last_scan_at": "",
        "last_download_at": "",
        "version_label": version_label,
        "purpose": purpose,
        "created_by": actor,
        "created_at": now(),
    }
    try:
        return supabase_insert("file_objects", row)
    except Exception:
        # Storage and Postgres do not share a transaction.  Compensate when
        # the metadata insert fails so private objects never become orphans.
        try:
            supabase_storage_delete(storage_key, bucket)
        except Exception as cleanup_error:
            log_structured(
                "error",
                "supabase_file_object_orphan_cleanup_failed",
                file_id=file_id,
                document_id=document_id,
                error=redact_text(str(cleanup_error)),
            )
        raise


def supabase_persist_file_object_scan_result(
    file_id: str,
    status: str,
    signature: str,
    actor: str,
) -> Dict[str, Any]:
    item = supabase_get("file_objects", file_id)
    if not item:
        raise ValueError("file_not_found")
    timestamp = now()
    detail = "防毒掃描通過" if status == "已通過" else f"隔離：{signature}"
    update = {
        "scan_status": status,
        "scan_engine": EDOC_SCAN_ENGINE,
        "quarantine_reason": "" if status == "已通過" else signature,
        "last_scan_at": timestamp,
    }
    supabase_patch("file_objects", file_id, update)
    supabase_insert("virus_scan_jobs", {
        "id": f"VS-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "file_object_id": file_id,
        "attachment_id": None,
        # file_objects is the durable relation for official_documents. The
        # legacy virus_scan_jobs.document_id FK targets documents, so do not
        # write an incompatible official_documents id here.
        "document_id": None,
        "engine": EDOC_SCAN_ENGINE,
        "status": "完成",
        "signature": signature,
        "result": status,
        "detail": detail,
        "started_at": timestamp,
        "finished_at": timestamp,
        "created_at": timestamp,
    })
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": actor,
        "action": "正式防毒掃描",
        "target_type": "file_objects",
        "target_id": file_id,
        "detail": f"{EDOC_SCAN_ENGINE} / {status} / {signature}",
        "event_type": "sensitive_access",
        "module_code": "files",
        "resource_type": "file_objects",
        "resource_id": file_id,
        "result": "success" if status == "已通過" else "denied",
        "severity": "info" if status == "已通過" else "critical",
    })
    return {**item, **update}


def supabase_scan_file_object(file_id: str, actor: str = "AV Worker") -> Dict[str, Any]:
    item = supabase_get("file_objects", file_id)
    if not item:
        return {"ok": False, "error": "file_not_found"}
    data = supabase_storage_download(item["storage_key"], item.get("bucket") or EDOC_STORAGE_BUCKET)
    if sha256_bytes(data) != item.get("sha256"):
        raise ValueError("file_hash_mismatch")
    status, signature = editor_scan_bytes_for_threats(
        data,
        item.get("file_name") or "file.bin",
        storage_key=item.get("storage_key") or "",
        storage_bucket=item.get("bucket") or EDOC_STORAGE_BUCKET,
        expected_sha256=item.get("sha256") or sha256_bytes(data),
    )
    refreshed = supabase_persist_file_object_scan_result(file_id, status, signature, actor)
    return {
        "ok": status == "已通過",
        "file": refreshed,
        "job": {"engine": EDOC_SCAN_ENGINE, "result": status, "signature": signature},
    }


def supabase_reference_codes(option_type: str) -> set[str]:
    return {row["code"] for row in supabase_filter_rows("seal_reference_options", {"option_type": option_type, "status": "active"})}


def supabase_log_seal_usage(
    *,
    action: str,
    actor_id: str = "API",
    usage_request_id: str = "",
    seal_id: str = "",
    document_id: str = "",
    detail: str = "",
    ip_address: str = "",
    user_agent: str = "",
) -> Dict[str, Any]:
    row = {
        "id": f"SLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "usage_request_id": usage_request_id or None,
        "seal_id": seal_id or None,
        "document_id": document_id or None,
        "action": action,
        "actor_id": actor_id,
        "ip_address": ip_address,
        "user_agent": user_agent,
        "detail": detail,
        "created_at": now(),
    }
    created = supabase_insert("seal_usage_logs", row)
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": actor_id,
        "action": action,
        "target_type": "seal_usage",
        "target_id": usage_request_id or seal_id or document_id,
        "detail": detail,
        "event_type": action,
        "module_code": "seals",
        "resource_type": "seal_usage",
        "resource_id": usage_request_id or seal_id or document_id,
        "result": "success",
        "severity": "info",
    })
    return created


def supabase_seal_file_with_backing_status(file_row: Dict[str, Any]) -> Dict[str, Any]:
    item = dict(file_row)
    file_object = supabase_get("file_objects", item.get("file_object_id") or "") if item.get("file_object_id") else None
    item["scan_status"] = file_object.get("scan_status") if file_object else "檔案不存在"
    item["scan_engine"] = file_object.get("scan_engine") if file_object else ""
    item["last_scan_at"] = file_object.get("last_scan_at") if file_object else ""
    item["av_clean"] = seal_file_av_is_clean(file_object)
    seal = supabase_get("company_seals", item.get("seal_id") or "")
    try:
        item["dimension_valid"] = bool(
            seal and company_seal_file_dimension_is_valid(item, seal.get("seal_size_type"))
        )
    except ValueError:
        item["dimension_valid"] = False
    item["usable"] = bool(
        item.get("is_current")
        and item.get("file_object_id")
        and item["av_clean"]
        and item["dimension_valid"]
    )
    return item


def supabase_current_company_seal_file(seal_id: str, *, require_usable: bool = True) -> Dict[str, Any] | None:
    rows = supabase_filter_rows("company_seal_files", {"seal_id": seal_id, "is_current": True}, order="version.desc", limit=1)
    if not rows:
        return None
    item = supabase_seal_file_with_backing_status(rows[0])
    return item if not require_usable or item.get("usable") else None


def supabase_require_current_company_seal_file(seal_id: str) -> Dict[str, Any]:
    item = supabase_current_company_seal_file(seal_id, require_usable=False)
    if not item:
        raise ValueError("current_seal_file_required")
    if not item.get("file_object_id"):
        raise ValueError("seal_file_object_required")
    if not item.get("av_clean"):
        raise ValueError("current_seal_file_antivirus_required")
    seal = supabase_get("company_seals", seal_id)
    if not seal:
        raise ValueError("seal_not_found")
    require_company_seal_file_dimensions(item, seal.get("seal_size_type"), current=True)
    return item


def supabase_require_seal_file_av_clean(file_row: Dict[str, Any]) -> Dict[str, Any]:
    item = supabase_seal_file_with_backing_status(file_row)
    if not item.get("file_object_id"):
        raise ValueError("seal_file_object_required")
    if not item.get("av_clean"):
        raise ValueError("seal_file_antivirus_required")
    seal = supabase_get("company_seals", item.get("seal_id") or "")
    if not seal:
        raise ValueError("seal_not_found")
    require_company_seal_file_dimensions(item, seal.get("seal_size_type"))
    return item


def supabase_company_seal_row(seal_id: str) -> Dict[str, Any]:
    seal = supabase_get("company_seals", seal_id)
    if not seal:
        raise ValueError("seal_not_found")
    company = supabase_get("companies", seal.get("company_id", "")) or {}
    designated_current = supabase_current_company_seal_file(seal_id, require_usable=False)
    data = {**seal, "company_name": company.get("name", ""), "company_tax_id": company.get("tax_id", "")}
    usable_current = (
        designated_current
        if designated_current
        and designated_current.get("usable")
        and str(designated_current.get("dimension_policy_version") or "") == EDOC_SEAL_DIMENSION_POLICY_VERSION
        else None
    )
    data.update(company_seal_api_dimension_metadata(data.get("seal_size_type"), usable_current))
    data["current_file"] = seal_file_metadata(usable_current) if usable_current else None
    data["current_file_status"] = seal_file_metadata(designated_current) if designated_current else None
    return data


def supabase_validate_official_document_seal(
    seal_id: str,
    company_id: str,
    require_current: bool = False,
) -> Dict[str, Any]:
    seal = supabase_company_seal_row(seal_id)
    if seal.get("company_id") != company_id:
        raise ValueError("official_document_seal_company_mismatch")
    if not seal.get("is_active"):
        raise ValueError("inactive_seal_cannot_be_requested")
    current_file = seal.get("current_file")
    if require_current:
        if not current_file:
            current_file = supabase_require_current_company_seal_file(seal_id)
        if not current_file.get("file_object_id"):
            raise ValueError("seal_file_object_required")
    return seal


def supabase_launch_smoke_current_official_seal(company_id: str = "") -> Dict[str, Any]:
    filters: Dict[str, Any] = {"is_active": True}
    if company_id:
        filters["company_id"] = company_id
    seals = supabase_filter_rows("company_seals", filters, order="seal_category.asc,seal_size_type.asc,created_at.asc", limit=500)
    priority = {"general_seal": 1, "official_seal": 2, "establishment_seal": 3, "bank_seal": 4}
    seals.sort(key=lambda item: (priority.get(item.get("seal_category"), 9), item.get("company_id") or "", item.get("id") or ""))
    for seal in seals:
        row = supabase_company_seal_row(seal["id"])
        if row.get("current_file"):
            return row
    raise ValueError("launch_smoke_current_seal_required")


def supabase_create_uploaded_pdf_launch_smoke_document(
    payload: Dict[str, Any] | None,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    payload = payload or {}
    user = supabase_official_session_user(session)
    if not session_has_any_permission(session, ["official_documents.compose", "official_documents.all_todo"]):
        raise PermissionError("official_document_create_forbidden")
    requested_company_id = payload.get("company_id") or ""
    seal = supabase_launch_smoke_current_official_seal(requested_company_id)
    package = build_launch_smoke_test_pdf()
    date_compact = datetime.now().strftime("%Y%m%d")
    suffix = secrets.token_hex(3).upper()
    document = supabase_create_official_document(
        {
            "source_type": "uploaded_pdf",
            "company_id": seal["company_id"],
            "seal_id": seal["id"],
            "document_category": "合作意向書",
            "approval_route_code": "A",
            "title": f"去識別化 PDF 用印走測申請 {date_compact}",
            "subject": "去識別化 PDF 用印走測申請",
            "description": "本申請僅供下週一內部正式上線前走測，確認 PDF 上傳、簽核、後端套印、已用印版本與下載紀錄均可追蹤。",
            "method": "請依固定流程簽核；核准後由系統自動產生已用印 PDF，並交由總務完成寄發紀錄。",
            "recipient": "測試收文機關（去識別化）",
            "dispatch_unit": user.get("unit") or "總管理處",
            "handler_name": user.get("name") or "上線走測承辦",
            "request_reason": "內部上線走測用印",
            "dispatch_method": payload.get("dispatch_method") or "electronic_official_document_by_general_affairs",
            "file_name": package["file_name"],
            "content_base64": base64.b64encode(package["data"]).decode("ascii"),
            "stamp_positions": payload.get("stamp_positions") or launch_smoke_stamp_positions(
                seal.get("seal_size_type"),
                seal.get("current_file"),
            ),
            "attachments_summary": "去識別化 PDF 走測範本，無正式附件。",
            "metadata": {
                "source": "backend_launch_smoke_test",
                "journey": "uploaded_pdf_stamping",
                "contains_personal_data": False,
                "contains_official_exchange_payload": False,
                "contains_seal_original": False,
                "smoke_suffix": suffix,
            },
            "submit": True,
            "ip_address": payload.get("ip_address") or "",
            "user_agent": payload.get("user_agent") or "",
        },
        session,
    )
    supabase_insert_official_log(
        document["id"],
        "launch_smoke_uploaded_pdf_stamping",
        user,
        f"deidentified_pdf seal={seal['id']} positions={len(document.get('stamp_request', {}).get('stamp_positions') or [])}",
        ip_address=payload.get("ip_address") or "",
        user_agent=payload.get("user_agent") or "",
    )
    return {
        "ok": True,
        "journey": "uploaded_pdf_stamping",
        "document": document,
        "next_action": "請依序用主管、行政部主任與總務完成簽核；核准後系統才會自動產生已用印 PDF。",
    }


def supabase_launch_smoke_general_affairs_dispatch_candidate(document_id: str = "") -> Dict[str, Any]:
    if document_id:
        document = supabase_official_document_row(document_id)
        if not official_document_is_launch_smoke(document):
            raise ValueError("launch_smoke_dispatch_requires_smoke_document")
        return document
    rows = supabase_filter_rows("official_documents", {"current_status": "pending_general_affairs_dispatch"}, order="updated_at.desc", limit=50)
    for document in rows:
        if not official_document_is_launch_smoke(document):
            continue
        record = supabase_official_dispatch_record(document["id"])
        if record and record.get("dispatch_owner_type") == "general_affairs" and record.get("dispatch_status") == "pending":
            return document
    raise ValueError("launch_smoke_dispatch_candidate_required")


def supabase_complete_general_affairs_dispatch_launch_smoke(
    payload: Dict[str, Any] | None,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    payload = payload or {}
    user = supabase_official_session_user(session)
    document = supabase_launch_smoke_general_affairs_dispatch_candidate(payload.get("document_id") or "")
    record = supabase_official_dispatch_record(document["id"])
    if not record or record.get("dispatch_owner_type") != "general_affairs":
        raise ValueError("launch_smoke_dispatch_record_required")
    if document.get("current_status") != "pending_general_affairs_dispatch":
        raise ValueError("official_document_not_pending_general_affairs_dispatch")
    proof = build_launch_dispatch_proof_pdf()
    upload = supabase_upload_official_dispatch_proof_file(
        document["id"],
        {
            "file_name": proof["file_name"],
            "file_mime_type": proof["mime_type"],
            "content_base64": base64.b64encode(proof["data"]).decode("ascii"),
            "ip_address": payload.get("ip_address") or "",
            "user_agent": payload.get("user_agent") or "",
        },
        session,
    )
    date_compact = datetime.now().strftime("%Y%m%d")
    completed = supabase_complete_official_dispatch(
        document["id"],
        {
            "external_official_document_number": payload.get("external_official_document_number") or f"TEST-EDOC-{date_compact}-{secrets.token_hex(2).upper()}",
            "dispatch_date": payload.get("dispatch_date") or datetime.now().strftime("%Y-%m-%d"),
            "recipient": payload.get("recipient") or document.get("recipient") or "測試收件對象（去識別化）",
            "recipient_contact": payload.get("recipient_contact") or "recipient@example.invalid",
            "dispatch_note": payload.get("dispatch_note") or "去識別化走測：已用後端範本建立寄發證明並完成總務寄發紀錄。",
            "ip_address": payload.get("ip_address") or "",
            "user_agent": payload.get("user_agent") or "",
        },
        session,
    )
    supabase_insert_official_log(
        document["id"],
        "launch_smoke_general_affairs_dispatch",
        user,
        "deidentified_dispatch_proof_completed",
        file_id=upload["file"]["id"],
        ip_address=payload.get("ip_address") or "",
        user_agent=payload.get("user_agent") or "",
    )
    return {
        "ok": True,
        "journey": "general_affairs_dispatch",
        "document": completed,
        "dispatch_record": completed.get("dispatch_record"),
        "proof_file": upload.get("file"),
        "next_action": "請由申請人回到申請單確認寄發紀錄與已用印版本。",
    }


def supabase_list_company_seals(
    company_id: str,
    session: Dict[str, Any] | None = None,
) -> List[Dict[str, Any]]:
    assert_supabase_seal_company_access(company_id, session)
    rows = supabase_filter_rows("company_seals", {"company_id": company_id}, order="is_active.desc,seal_category.asc,seal_size_type.asc,created_at.desc", limit=500)
    return [supabase_company_seal_row(row["id"]) for row in rows]


def supabase_create_company_seal(company_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    assert_supabase_seal_company_access(company_id, session)
    category = payload.get("seal_category") or payload.get("category") or "other"
    size_type = payload.get("seal_size_type") or payload.get("size_type") or "large_seal"
    if category not in supabase_reference_codes("category"):
        raise ValueError("invalid_seal_category")
    if size_type not in supabase_reference_codes("size"):
        raise ValueError("invalid_seal_size_type")
    actor = seal_actor(session, payload)
    seal_id = payload.get("id") or f"CSEAL-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    supabase_insert("company_seals", {
        "id": seal_id,
        "company_id": company_id,
        "seal_name": payload.get("seal_name") or payload.get("name") or "未命名印章",
        "seal_category": category,
        "seal_size_type": size_type,
        "purpose_description": payload.get("purpose_description") or payload.get("purpose") or "",
        "is_active": bool(payload.get("is_active", True)),
        "created_by": actor,
        "created_at": now(),
        "updated_at": now(),
        "deactivated_at": "",
    })
    for role in payload.get("default_permission_roles") or ["viewer", "requester", "approver", "seal_admin"]:
        if role in supabase_reference_codes("permission_role"):
            supabase_insert("seal_permissions", {"id": f"SPERM-{seal_id}-{role}", "seal_id": seal_id, "user_id": payload.get("user_id") or "", "role": role, "created_at": now()})
    supabase_log_seal_usage(action="create_seal", actor_id=actor, seal_id=seal_id, detail=payload.get("seal_name") or payload.get("name") or "")
    return supabase_company_seal_row(seal_id)


def supabase_patch_company_seal(seal_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    assert_supabase_seal_access(seal_id, session)
    current_seal = supabase_company_seal_row(seal_id)
    update: Dict[str, Any] = {}
    for key in ("seal_name", "seal_category", "seal_size_type", "purpose_description", "is_active"):
        if key in payload:
            update[key] = payload[key]
    if "seal_category" in update and update["seal_category"] not in supabase_reference_codes("category"):
        raise ValueError("invalid_seal_category")
    if "seal_size_type" in update and update["seal_size_type"] not in supabase_reference_codes("size"):
        raise ValueError("invalid_seal_size_type")
    if (
        "seal_size_type" in update
        and str(update["seal_size_type"]) != str(current_seal.get("seal_size_type") or "")
        and supabase_filter_rows("company_seal_files", {"seal_id": seal_id}, limit=1)
    ):
        raise ValueError("seal_size_type_locked_after_upload")
    if "is_active" in update:
        update["is_active"] = bool(update["is_active"])
        update["deactivated_at"] = "" if update["is_active"] else now()
    update["updated_at"] = now()
    supabase_patch("company_seals", seal_id, update)
    supabase_log_seal_usage(action="update_seal", actor_id=seal_actor(session, payload), seal_id=seal_id, detail=json.dumps(update, ensure_ascii=False))
    return supabase_company_seal_row(seal_id)


def supabase_deactivate_company_seal(seal_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    row = supabase_patch_company_seal(seal_id, {"is_active": False}, session)
    supabase_log_seal_usage(action="deactivate_seal", actor_id=seal_actor(session), seal_id=seal_id, detail="soft_delete_only")
    return row


def supabase_upload_company_seal_file(seal_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    assert_supabase_seal_access(seal_id, session)
    seal = supabase_company_seal_row(seal_id)
    if not seal.get("is_active"):
        raise ValueError("inactive_seal_cannot_upload_new_file")
    content = payload.get("content_base64") or ""
    if not content:
        raise ValueError("seal_file_content_required")
    data = decode_seal_file_content(content)
    file_name = Path(payload.get("file_name") or f"{seal_id}.png").name
    mime_type = payload.get("file_mime_type") or payload.get("mime_type") or "image/png"
    render_width_mm, render_height_mm = normalize_company_seal_upload_dimensions(payload)
    image_info = validate_seal_file_upload(
        file_name,
        mime_type,
        data,
        str(seal.get("seal_size_type") or ""),
        render_width_mm,
        render_height_mm,
    )
    scan_status, scan_signature = scan_seal_upload_bytes(data, file_name)
    actor = seal_actor(session, payload)
    file_id = f"FILE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    seal_file_id = f"SFILE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    storage_key = (
        f"{SEAL_VAULT_PURPOSE_PREFIX}/seals/{seal_id}/"
        f"{SEAL_VAULT_DOCUMENT_ID}/{file_id}-{file_name}"
    )
    file_hash = sha256_bytes(data)
    supabase_storage_upload(storage_key, data, mime_type, EDOC_SEAL_STORAGE_BUCKET)
    rpc_error: Exception | None = None
    created: Dict[str, Any] | None = None
    try:
        response = supabase_request(
            "POST",
            "rpc/edoc_create_company_seal_file_version",
            {
                "p_file_id": file_id,
                "p_seal_file_id": seal_file_id,
                "p_seal_id": seal_id,
                "p_storage_key": storage_key,
                "p_file_name": file_name,
                "p_mime_type": mime_type,
                "p_file_size": len(data),
                "p_sha256": file_hash,
                "p_pixel_width": image_info["pixel_width"],
                "p_pixel_height": image_info["pixel_height"],
                "p_source_aspect_ratio": image_info["source_aspect_ratio"],
                "p_render_width_mm": image_info["render_width_mm"],
                "p_render_height_mm": image_info["render_height_mm"],
                "p_dimension_policy_version": image_info["dimension_policy_version"],
                "p_actor": actor,
                "p_scan_engine": EDOC_SCAN_ENGINE,
                "p_scan_signature": scan_signature,
                "p_usage_log_id": f"SLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
                "p_audit_log_id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            },
        )
        created = response.get("file") if isinstance(response, dict) else None
    except Exception as exc:
        # A transport error can be ambiguous: Postgres may have committed even
        # if the response was lost.  Confirm by the caller-generated immutable
        # id before deciding whether deleting Storage is safe.
        rpc_error = exc

    def valid_created(item: Any) -> bool:
        try:
            return bool(
                isinstance(item, dict)
                and item.get("id") == seal_file_id
                and item.get("seal_id") == seal_id
                and item.get("file_object_id") == file_id
                and item.get("file_hash") == file_hash
                and bool(item.get("dimension_validated"))
                and int(item.get("pixel_width") or 0) == image_info["pixel_width"]
                and int(item.get("pixel_height") or 0) == image_info["pixel_height"]
                and abs(float(item.get("render_width_mm") or 0) - image_info["render_width_mm"]) <= 0.000001
                and abs(float(item.get("render_height_mm") or 0) - image_info["render_height_mm"]) <= 0.000001
                and str(item.get("dimension_policy_version") or "") == EDOC_SEAL_DIMENSION_POLICY_VERSION
                and bool(item.get("is_current"))
                and int(item.get("version") or 0) >= 1
            )
        except (TypeError, ValueError):
            return False

    if not valid_created(created):
        try:
            persisted = supabase_filter_rows(
                "company_seal_files",
                {"id": seal_file_id},
                limit=1,
            )
        except Exception as confirmation_error:
            # Do not delete on an unknown commit state; an orphan object is
            # safer than destroying bytes already referenced by committed DB
            # metadata.  Operations can reconcile this generated file id.
            raise RuntimeError("seal_upload_commit_state_unknown") from confirmation_error
        persisted_item = persisted[0] if persisted else None
        if valid_created(persisted_item):
            created = persisted_item
        elif persisted_item:
            raise RuntimeError("seal_version_persisted_contract_invalid") from rpc_error
        else:
            try:
                supabase_storage_delete(storage_key, EDOC_SEAL_STORAGE_BUCKET)
            except Exception as cleanup_error:
                raise RuntimeError("seal_upload_metadata_failed_storage_cleanup_failed") from cleanup_error
            if rpc_error is not None:
                raise rpc_error
            raise RuntimeError("seal_version_rpc_contract_invalid")
    created_status = {
        **(created or {}),
        "scan_status": scan_status,
        "scan_engine": EDOC_SCAN_ENGINE,
        "last_scan_at": now(),
        "av_clean": True,
        "dimension_valid": True,
        "usable": True,
    }
    return {
        "seal": supabase_company_seal_row(seal_id),
        "file": seal_file_metadata(created_status),
    }


def supabase_list_company_seal_files(seal_id: str, session: Dict[str, Any] | None = None) -> List[Dict[str, Any]]:
    assert_supabase_seal_access(seal_id, session)
    supabase_company_seal_row(seal_id)
    supabase_log_seal_usage(action="view_seal_metadata", actor_id=seal_actor(session), seal_id=seal_id, detail="metadata_only")
    return [
        seal_file_metadata(supabase_seal_file_with_backing_status(row))
        for row in supabase_filter_rows("company_seal_files", {"seal_id": seal_id}, order="version.desc")
    ]


def supabase_set_current_seal_file(file_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    require_seal_custodian_role(session)
    item = supabase_get("company_seal_files", file_id)
    if not item:
        raise ValueError("seal_file_not_found")
    assert_supabase_seal_access(str(item.get("seal_id") or ""), session)
    item = supabase_require_seal_file_av_clean(item)
    seal = supabase_get("company_seals", str(item.get("seal_id") or ""))
    if not seal:
        raise ValueError("seal_not_found")
    require_company_seal_file_dimensions(item, seal.get("seal_size_type"), current=True)
    actor = seal_actor(session)
    response = supabase_request(
        "POST",
        "rpc/edoc_set_current_company_seal_file",
        {
            "p_file_id": file_id,
            "p_actor": actor,
            "p_usage_log_id": f"SLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "p_audit_log_id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        },
    )
    if (
        not isinstance(response, dict)
        or response.get("seal_id") != item["seal_id"]
        or not isinstance(response.get("file"), dict)
        or response["file"].get("id") != file_id
        or not bool(response["file"].get("is_current"))
    ):
        raise RuntimeError("seal_current_rpc_contract_invalid")
    return supabase_company_seal_row(item["seal_id"])


def supabase_get_or_create_pdf_document(payload: Dict[str, Any]) -> Dict[str, Any]:
    doc_payload = payload.get("document") or payload
    doc_id = doc_payload.get("document_id") or doc_payload.get("id")
    if doc_id:
        existing = supabase_get("documents", str(doc_id))
        if existing:
            return existing
    if doc_id and not str(doc_id).startswith("DOC-"):
        doc_id = f"DOC-{doc_id}"
    doc_id = str(doc_id or f"DOC-PDF-{int(time.time() * 1000)}")
    doc = {
        "id": doc_id,
        "doc_no": doc_payload.get("doc_no") or doc_payload.get("no") or doc_id,
        "direction": doc_payload.get("direction") or "發文",
        "doc_type": doc_payload.get("doc_type") or doc_payload.get("type") or "函",
        "priority": doc_payload.get("priority") or "普通件",
        "security_level": doc_payload.get("security_level") or doc_payload.get("security") or "普通",
        "agency_name": doc_payload.get("agency_name") or doc_payload.get("to") or "未指定機關",
        "agency_code": doc_payload.get("agency_code") or doc_payload.get("agencyCode") or "",
        "subject": doc_payload.get("subject") or "未命名公文",
        "body": doc_payload.get("body") or "",
        "status": doc_payload.get("status") or "PDF 已產生",
        "owner": doc_payload.get("owner") or "總務",
        "department": doc_payload.get("department") or doc_payload.get("dept") or "總管理處",
        "due_date": doc_payload.get("due_date") or "",
        "received_at": doc_payload.get("received_at") or None,
        "company_name": doc_payload.get("company_name") or doc_payload.get("companyName") or "歲悅長照股份有限公司",
        "seal_plan_json": doc_payload.get("seal_plan_json") or "{}",
        "metadata_json": doc_payload.get("metadata_json") or "{}",
        "created_at": now(),
        "updated_at": now(),
    }
    return supabase_insert("documents", doc)


def supabase_seal_usage_request_row(
    request_id: str,
    session: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    stored_request = supabase_get("seal_usage_requests", request_id)
    request = dict(stored_request) if stored_request else None
    if not request:
        raise ValueError("seal_usage_request_not_found")
    company = supabase_get("companies", request.get("company_id", "")) or {}
    seal = supabase_get("company_seals", request.get("seal_id", "")) or {}
    assert_supabase_seal_company_access(str(request.get("company_id") or ""), session)
    assert_supabase_seal_company_access(str(seal.get("company_id") or ""), session)
    if request.get("company_id") != seal.get("company_id"):
        raise ValueError("seal_usage_request_company_mismatch")
    request["company_name"] = company.get("name", "")
    request["seal_name"] = seal.get("seal_name", "")
    request["seal_category"] = seal.get("seal_category", "")
    request["seal_size_type"] = seal.get("seal_size_type", "")
    request["stamp_positions"] = parse_json_any(request.get("stamp_positions_json"), []) or []
    request["metadata"] = parse_json_any(request.get("metadata_json"), {}) or {}
    request["approvals"] = supabase_filter_rows("seal_usage_approvals", {"usage_request_id": request_id}, order="approval_order.asc")
    request["logs"] = supabase_filter_rows("seal_usage_logs", {"usage_request_id": request_id}, order="created_at.desc", limit=50)
    return request


def supabase_locked_company_seal_usage_file(
    request: Dict[str, Any],
    seal: Dict[str, Any],
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    metadata = request.get("metadata") if isinstance(request.get("metadata"), dict) else {}
    lock = metadata.get("seal_dimension_lock") if isinstance(metadata, dict) else None
    file_id = str(lock.get("seal_file_id") or "") if isinstance(lock, dict) else ""
    if not file_id:
        raise ValueError("seal_dimension_lock_required")
    row = supabase_get("company_seal_files", file_id)
    if not row:
        raise ValueError("locked_seal_file_not_found")
    file_meta = supabase_require_seal_file_av_clean(row)
    if str(file_meta.get("seal_id") or "") != str(seal.get("id") or ""):
        raise ValueError("seal_dimension_lock_mismatch")
    positions = validate_company_seal_usage_lock(request, seal, file_meta)
    return file_meta, positions


def supabase_list_seal_usage_requests(
    query: Dict[str, List[str]] | None = None,
    session: Dict[str, Any] | None = None,
) -> List[Dict[str, Any]]:
    query = query or {}
    params: Dict[str, str] = {"select": "id", "limit": "300", "order": "requested_at.desc"}
    requested_company_id = str((query.get("company_id") or [""])[0] or "").strip()
    if session:
        user_company_id = str(((session.get("user") or {}).get("company_id") or "")).strip()
        if "seals.manage" in session_permissions(session):
            if requested_company_id:
                assert_supabase_seal_company_access(requested_company_id, session)
        else:
            if not user_company_id:
                raise PermissionError("seal_company_access_forbidden")
            assert_supabase_seal_company_access(user_company_id, session)
            if requested_company_id and requested_company_id != user_company_id:
                assert_supabase_seal_company_access(requested_company_id, session)
            requested_company_id = user_company_id
    if requested_company_id:
        params["company_id"] = f"eq.{requested_company_id}"
    for key in ("seal_id", "requested_by", "usage_type", "status"):
        if query.get(key):
            params[key] = f"eq.{query[key][0]}"
    if query.get("date_from"):
        params["requested_at"] = f"gte.{query['date_from'][0]}"
    if query.get("date_to"):
        params["requested_at"] = f"lte.{query['date_to'][0]}"
    rows = supabase_request("GET", f"seal_usage_requests?{urllib.parse.urlencode(params)}")
    results: List[Dict[str, Any]] = []
    for row in rows:
        try:
            results.append(supabase_seal_usage_request_row(row["id"], session))
        except PermissionError:
            if requested_company_id or "seals.manage" not in session_permissions(session):
                raise
    return results


def supabase_create_seal_usage_request(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    seal_id = payload.get("seal_id") or ""
    if not seal_id:
        raise ValueError("seal_id_required")
    assert_supabase_seal_access(seal_id, session)
    seal = supabase_company_seal_row(seal_id)
    if not seal.get("is_active"):
        raise ValueError("inactive_seal_cannot_be_requested")
    seal_file = supabase_require_current_company_seal_file(seal_id)
    usage_type = payload.get("usage_type") or "official_document"
    if usage_type not in supabase_reference_codes("usage_type"):
        raise ValueError("invalid_usage_type")
    document = supabase_get_or_create_pdf_document({"document_id": document_id, **(payload.get("document") or {})})
    actor = seal_actor(session, payload)
    request_id = payload.get("id") or f"SREQ-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    requested_status = str(payload.get("status") or "pending")
    if requested_status not in {"draft", "pending"}:
        raise ValueError("invalid_initial_seal_request_status")
    positions = canonicalize_company_seal_usage_positions(
        payload.get("stamp_positions") or payload.get("positions") or [],
        seal,
        seal_file,
    )
    metadata = parse_json_any(payload.get("metadata"), {}) if isinstance(payload.get("metadata"), str) else dict(payload.get("metadata") or {})
    metadata["seal_dimension_lock"] = company_seal_usage_lock_metadata(seal, seal_file)
    supabase_insert("seal_usage_requests", {
        "id": request_id,
        "document_id": document["id"],
        "company_id": seal["company_id"],
        "seal_id": seal_id,
        "requested_by": actor,
        "request_reason": payload.get("request_reason") or payload.get("reason") or "",
        "usage_type": usage_type,
        "status": requested_status,
        "stamp_positions_json": positions,
        "stamped_pdf_version_id": None,
        "metadata_json": metadata,
        "requested_at": now(),
        "approved_at": "",
        "stamped_at": "",
        "updated_at": now(),
    })
    approvers = payload.get("approvers") or [{"approver_id": "seal_approver", "approval_order": 1}]
    for index, approver in enumerate(approvers, start=1):
        supabase_insert("seal_usage_approvals", {
            "id": f"SAPP-{request_id}-{index}",
            "usage_request_id": request_id,
            "approver_id": approver.get("approver_id") or approver.get("id") or "seal_approver",
            "approval_order": int(approver.get("approval_order") or index),
            "status": "pending",
            "comment": "",
            "approved_at": "",
            "created_at": now(),
            "updated_at": now(),
        })
    supabase_log_seal_usage(action="request_use", actor_id=actor, usage_request_id=request_id, seal_id=seal_id, document_id=document["id"], detail=payload.get("request_reason") or payload.get("reason") or "")
    return supabase_seal_usage_request_row(request_id, session)


def supabase_approve_seal_usage_request(request_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    request = supabase_seal_usage_request_row(request_id, session)
    if request["status"] not in {"pending", "draft"}:
        raise ValueError("seal_request_not_pending")
    seal = supabase_company_seal_row(request["seal_id"])
    supabase_locked_company_seal_usage_file(request, seal)
    actor = seal_actor(session, payload)
    pending = supabase_filter_rows("seal_usage_approvals", {"usage_request_id": request_id, "status": "pending"}, order="approval_order.asc", limit=1)
    if pending:
        supabase_patch("seal_usage_approvals", pending[0]["id"], {"status": "approved", "approver_id": actor, "comment": payload.get("comment") or "核准用印。", "approved_at": now(), "updated_at": now()})
    remaining = supabase_filter_rows("seal_usage_approvals", {"usage_request_id": request_id, "status": "pending"}, limit=1)
    if not remaining:
        supabase_patch("seal_usage_requests", request_id, {"status": "approved", "approved_at": now(), "updated_at": now()})
    supabase_log_seal_usage(action="approve_use", actor_id=actor, usage_request_id=request_id, seal_id=request["seal_id"], document_id=request["document_id"], detail=payload.get("comment") or "")
    return supabase_seal_usage_request_row(request_id, session)


def supabase_reject_seal_usage_request(request_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    request = supabase_seal_usage_request_row(request_id, session)
    if request["status"] in {"stamped", "cancelled"}:
        raise ValueError("seal_request_cannot_be_rejected")
    actor = seal_actor(session, payload)
    pending = supabase_filter_rows("seal_usage_approvals", {"usage_request_id": request_id, "status": "pending"}, limit=50)
    for approval in pending:
        supabase_patch("seal_usage_approvals", approval["id"], {"status": "rejected", "comment": payload.get("comment") or "駁回用印。", "approved_at": now(), "updated_at": now()})
    supabase_patch("seal_usage_requests", request_id, {"status": "rejected", "updated_at": now()})
    supabase_log_seal_usage(action="reject_use", actor_id=actor, usage_request_id=request_id, seal_id=request["seal_id"], document_id=request["document_id"], detail=payload.get("comment") or "")
    return supabase_seal_usage_request_row(request_id, session)


def supabase_stamp_seal_usage_request(request_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    request = supabase_seal_usage_request_row(request_id, session)
    if request["status"] != "approved":
        raise ValueError("seal_request_must_be_approved_before_stamp")
    seal = supabase_company_seal_row(request["seal_id"])
    if not seal.get("is_active"):
        raise ValueError("inactive_seal_cannot_stamp")
    file_meta, positions = supabase_locked_company_seal_usage_file(request, seal)
    file_object = supabase_get("file_objects", file_meta.get("file_object_id", "")) if file_meta.get("file_object_id") else None
    if not file_object:
        raise ValueError("seal_file_object_required")
    supabase_log_seal_usage(action="read_seal_vault_for_stamp", actor_id=seal_actor(session, payload), usage_request_id=request_id, seal_id=request["seal_id"], document_id=request["document_id"], detail="authorized_backend_stamp_only")
    seal_bytes = supabase_storage_download(file_object["storage_key"], file_object.get("bucket") or EDOC_SEAL_STORAGE_BUCKET)
    if sha256_bytes(seal_bytes) != file_meta["file_hash"]:
        raise ValueError("seal_file_hash_mismatch")
    stamp_no = payload.get("stamp_no") or f"STAMP-{request_id}-{int(time.time())}"
    document = supabase_get("documents", request["document_id"]) or {"id": request["document_id"], "doc_no": request["document_id"], "subject": "用印文件", "body": ""}
    template = payload.get("template") or "公司用印文件"
    dry_package = build_official_pdf_package(pdf_render_document(document, payload), [], template, 1)
    stamps = pdf_stamp_definitions({"stamp_positions": positions, "seal_id": request["seal_id"]}, document, stamp_no, int(dry_package["layout"]["page_count"]))
    stamped_data, stamp_engine, _stamp_metadata = stamp_uploaded_pdf_bytes(
        dry_package["data"],
        stamps,
        stamp_no,
        seal_asset={
            "data": seal_bytes,
            "mime_type": file_meta.get("file_mime_type") or file_object.get("mime_type") or "image/png",
        },
        source_text_on_top=True,
    )
    package = {**dry_package, "data": stamped_data}
    actor = seal_actor(session, payload)
    file_row = supabase_store_file_object(request["document_id"], f"{document.get('doc_no') or request['document_id']}-after-seal.pdf", package["data"], "pdf", "after_seal", actor, "application/pdf")
    pdf_version_id = f"PDF-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    pdf_version = supabase_insert("pdf_versions", {
        "id": pdf_version_id,
        "document_id": request["document_id"],
        "file_object_id": file_row["id"],
        "version_type": "after_seal",
        "template_name": template,
        "stamp_no": stamp_no,
        "coordinates_json": json.dumps({
            **pdf_coordinates_with_layout(payload.get("coordinates") or {}, package, stamps),
            "stamp_engine": stamp_engine,
            "seal_image_applied": True,
        }, ensure_ascii=False),
        "previous_version_id": "",
        "sha256": file_row["sha256"],
        "created_at": now(),
    })
    supabase_patch("seal_usage_requests", request_id, {"status": "stamped", "stamped_at": now(), "stamped_pdf_version_id": pdf_version_id, "updated_at": now()})
    supabase_patch("documents", request["document_id"], {"status": "已用印", "updated_at": now()})
    supabase_log_seal_usage(action="stamp_document", actor_id=actor, usage_request_id=request_id, seal_id=request["seal_id"], document_id=request["document_id"], detail=f"{stamp_no} seal_file_hash={file_meta['file_hash']}")
    return {"request": supabase_seal_usage_request_row(request_id, session), "stamped_file": {"pdf_version_id": pdf_version["id"], "file_object_id": file_row["id"], "sha256": file_row["sha256"], "stamp_no": stamp_no}}


def supabase_official_session_user(session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = session.get("user") if session else None
    if not user:
        raise PermissionError("authentication_required")
    return user


