def supabase_active_user_by_role(role: str, exclude_user_id: str = "") -> Dict[str, Any] | None:
    rows = supabase_filter_rows("users", {"role": role, "status": "啟用"}, order="id.asc", limit=20)
    for row in rows:
        if row.get("id") != exclude_user_id:
            return public_user(row)
    return None


def supabase_active_user_by_finance_identity(employee_id: str = "", email: str = "", exclude_user_id: str = "") -> Dict[str, Any] | None:
    expected_employee_id = str(employee_id or "").strip()
    expected_email = str(email or "").strip().lower()
    rows: List[Dict[str, Any]] = []
    if expected_employee_id:
        rows.extend(supabase_filter_rows(
            "users",
            {"finance_employee_id": expected_employee_id, "status": "啟用"},
            limit=20,
        ))
    if expected_email:
        rows.extend(supabase_filter_rows(
            "users",
            {"email": expected_email, "status": "啟用"},
            limit=20,
        ))
    resolved = select_active_finance_reference_user(
        rows,
        expected_employee_id,
        expected_email,
        exclude_user_id,
    )
    return public_user(resolved) if resolved else None


def supabase_active_workflow_user(
    step_key: str,
    company: Dict[str, Any],
    *,
    unit: str = "",
    exclude_user_ids: Iterable[str] = (),
    extra_roles: Iterable[str] = (),
) -> Dict[str, Any] | None:
    directory = OFFICIAL_WORKFLOW_ACTOR_DIRECTORY.get(step_key) or {}
    roles = {str(role) for role in (*directory.get("roles", ()), *extra_roles) if role}
    logging_roles = {str(role) for role in directory.get("logging_roles", ()) if role}
    excluded = {str(value) for value in exclude_user_ids if value}
    candidates: List[Tuple[Tuple[int, int, int, int, str], Dict[str, Any]]] = []
    shared_candidates: Dict[str, Dict[str, Any]] = {}
    for row in supabase_filter_rows("users", {"status": "啟用"}, order="id.asc", limit=1000):
        if row.get("id") in excluded:
            continue
        role_match = row.get("role") in roles
        logging_match = canonical_logging_role(row.get("logging_role_key")) in logging_roles
        if not role_match and not logging_match:
            continue
        if (
            step_key in {"ceo", "admin_director", "general_affairs_review"}
            and str(row.get("account_source") or "").lower() == "finance"
            and row.get("company_id")
            and launch_company_in_scope(str(row.get("company_id")))
        ):
            shared_candidates[str(row.get("id") or "")] = row
        company_score = workflow_user_company_score(row, company)
        if company_score is None:
            continue
        unit_score = 0 if unit and str(row.get("unit") or "") == unit else 1
        finance_score = 0 if str(row.get("account_source") or "").lower() == "finance" else 1
        candidates.append((
            (
                company_score,
                0 if logging_match else 1,
                unit_score,
                finance_score,
                str(row.get("id") or ""),
            ),
            row,
        ))
    scoped = [item for item in candidates if item[0][0] < 3]
    if scoped:
        return public_user(min(scoped, key=lambda item: item[0])[1])
    if len(shared_candidates) == 1:
        return public_user(next(iter(shared_candidates.values())))
    if len(shared_candidates) > 1:
        return None
    if candidates:
        return public_user(min(candidates, key=lambda item: item[0])[1])
    return None


def supabase_department_head_role(company: Dict[str, Any], department_name: str) -> str:
    rows = supabase_filter_rows("department_registry", {"company_name": company.get("name") or "", "name": department_name or "", "status": "啟用"}, limit=1)
    return rows[0].get("manager_role") if rows else "主任"


def supabase_resolve_official_step_approver(step: Dict[str, Any], applicant: Dict[str, Any], company: Dict[str, Any]) -> Dict[str, Any] | None:
    key = step["key"]
    if key == "applicant_confirm":
        return applicant
    if key == "applicant_manager":
        manager = supabase_active_user_by_finance_identity(
            applicant.get("manager_employee_id") or "",
            applicant.get("manager_email") or "",
            applicant.get("id") or "",
        )
        if manager:
            return manager
        if finance_workflow_actor(applicant):
            return None
        return supabase_active_workflow_user(
            key,
            company,
            unit=applicant.get("unit") or "",
            exclude_user_ids=(applicant.get("id") or "",),
        )
    if key == "department_head":
        direct_manager = supabase_active_user_by_finance_identity(
            applicant.get("manager_employee_id") or "",
            applicant.get("manager_email") or "",
            applicant.get("id") or "",
        )
        approval_manager = supabase_active_user_by_finance_identity(
            applicant.get("approval_manager_employee_id") or "",
            applicant.get("approval_manager_email") or "",
            applicant.get("id") or "",
        )
        if approval_manager:
            return approval_manager
        if finance_workflow_actor(applicant):
            return None
        department_role = supabase_department_head_role(company, applicant.get("unit") or "")
        return supabase_active_workflow_user(
            key,
            company,
            unit=applicant.get("unit") or "",
            exclude_user_ids=(applicant.get("id") or "", (direct_manager or {}).get("id") or ""),
            extra_roles=(department_role,),
        )
    return supabase_active_workflow_user(key, company)


def supabase_internal_launch_user_counts() -> Dict[str, int]:
    roles = list(dict.fromkeys([*INTERNAL_LAUNCH_APPLICANT_ROLES, *INTERNAL_LAUNCH_REQUIRED_ROLES]))
    counts: Dict[str, int] = {}
    for role in roles:
        counts[role] = len(supabase_filter_rows("users", {"role": role, "status": "啟用"}, limit=1000))
    return counts


def supabase_internal_launch_access_readiness(role_counts: Dict[str, int]) -> Dict[str, Any]:
    rows = supabase_filter_rows("users", {"status": "啟用"}, order="role.asc,email.asc", limit=1000)
    expected_roles = list(dict.fromkeys([*INTERNAL_LAUNCH_APPLICANT_ROLES, *INTERNAL_LAUNCH_REQUIRED_ROLES]))
    role_checks: List[Dict[str, Any]] = []
    for role in expected_roles:
        role_users = [user for user in rows if user.get("role") == role]
        formal_users = [user for user in role_users if user_has_formal_login_identity(user)]
        demo_users = [user for user in role_users if user_is_demo_seed_account(user)]
        role_checks.append({
            "role": role,
            "activeCount": len(role_users),
            "formalAccountCount": len(formal_users),
            "demoSeedCount": len(demo_users),
            "hasActiveUser": bool(role_users),
            "hasFormalAccount": bool(formal_users),
        })
    required_roles = ["員工", "主管", "主任", "行政部主任", "總務"]
    missing_active = [role for role in required_roles if role_counts.get(role, 0) < 1]
    missing_formal = [check["role"] for check in role_checks if check["role"] in required_roles and not check["hasFormalAccount"]]
    demo_seed_count = sum(1 for user in rows if user_is_demo_seed_account(user))
    password_login_candidates = sum(1 for user in rows if user.get("password_hash"))
    demo_policy = demo_account_policy_status()
    checks = {
        "activeUserCount": len(rows),
        "demoSeedUserCount": demo_seed_count,
        "passwordLoginCandidateCount": password_login_candidates,
        "demoAccountsDisabled": demo_policy["disabled"],
        "demoAccountsExplicitlyDisabled": demo_policy["explicitDisable"],
        "demoAccountsSafeDefault": demo_policy["safeDefault"],
        "demoAccountsExplicitlyAllowed": demo_policy["explicitAllow"],
        "production": is_production(),
        "roleChecks": role_checks,
    }
    blockers = [f"缺少啟用的「{role}」正式帳號。" for role in missing_active]
    warnings: List[str] = []
    if missing_formal:
        message = f"角色尚未看到非 seed/demo 或外部同步帳號：{'、'.join(missing_formal)}。"
        if is_production():
            blockers.append(message)
        else:
            warnings.append(message)
    if demo_seed_count and not demo_policy["disabled"]:
        warnings.append("仍可使用 seed/demo 帳號政策；正式站需設定 EDOC_DISABLE_DEMO_ACCOUNTS=true。")
    if demo_seed_count and demo_policy["disabled"] and not demo_policy["explicitDisable"]:
        warnings.append("正式站 seed/demo 帳號已由安全預設阻擋；IT 仍需設定 EDOC_DISABLE_DEMO_ACCOUNTS=true 留存明確政策。")
    if demo_policy["disabled"] and demo_seed_count and password_login_candidates == demo_seed_count:
        warnings.append("目前啟用帳號看起來多為 seed/demo 帳號；請確認正式帳號或 Logging Portal 已匯入。")
    return {
        "ready": not blockers,
        "blockers": blockers,
        "warnings": warnings,
        "checks": checks,
        "summary": f"activeUsers={len(rows)}；demoSeedUsers={demo_seed_count}；formalRoleMissing={len(missing_formal)}",
    }


def supabase_first_internal_launch_applicant() -> Dict[str, Any] | None:
    candidates: List[Dict[str, Any]] = []
    for role in INTERNAL_LAUNCH_APPLICANT_ROLES:
        candidates.extend(supabase_filter_rows("users", {"role": role, "status": "啟用"}, order="id.asc", limit=20))
    if not candidates:
        return None
    candidates.sort(key=lambda row: (0 if row.get("role") == "業務助理" else 1, str(row.get("id") or "")))
    return public_user(candidates[0])


def supabase_internal_launch_companies() -> List[Dict[str, Any]]:
    companies = supabase_filter_rows("companies", {"status": "active"}, order="id.asc", limit=200)
    if not companies:
        companies = supabase_filter_rows("companies", {"status": "啟用"}, order="id.asc", limit=200)
    return companies


def supabase_scoped_internal_launch_companies() -> Tuple[List[Dict[str, Any]], Dict[str, Any], List[Dict[str, Any]]]:
    all_companies = supabase_internal_launch_companies()
    companies, scope = filter_launch_companies(all_companies)
    return companies, scope, all_companies


def supabase_internal_launch_finance_applicants_by_company(
    companies: List[Dict[str, Any]],
) -> Dict[str, List[Dict[str, Any]]]:
    rows = [
        public_user(row)
        for row in supabase_filter_rows("users", {"status": "啟用"}, order="role.asc,id.asc", limit=1000)
        if finance_workflow_actor(row) and row.get("role") in INTERNAL_LAUNCH_APPLICANT_ROLES
    ]
    result: Dict[str, List[Dict[str, Any]]] = {}
    for company in companies:
        company_id = str(company.get("id") or company.get("company_id") or "")
        result[company_id] = [
            user
            for user in rows
            if workflow_user_company_score(user, company) in {0, 1}
        ]
    return result


def supabase_internal_launch_company_seal_checks() -> Tuple[List[Dict[str, Any]], List[str]]:
    companies, scope, all_companies = supabase_scoped_internal_launch_companies()
    blockers: List[str] = launch_company_scope_blockers(all_companies, scope)
    checks: List[Dict[str, Any]] = []
    if blockers and not companies:
        return checks, blockers
    for company in companies:
        company_name = company.get("name") or company.get("id") or "未命名公司"
        company_check = {
            "company_id": company.get("id"),
            "company_name": company_name,
            "launchScopeIncluded": True,
            "requiredSeals": [],
        }
        for category, label in INTERNAL_LAUNCH_REQUIRED_SEAL_CATEGORIES.items():
            seals = supabase_filter_rows("company_seals", {"company_id": company.get("id"), "seal_category": category, "is_active": True}, order="seal_size_type.asc,created_at.asc", limit=20)
            has_active = bool(seals)
            has_current = False
            has_unscanned_current = False
            current_seal_id = ""
            for seal in seals:
                designated = supabase_current_company_seal_file(seal.get("id") or "", require_usable=False)
                if designated and designated.get("usable"):
                    has_current = True
                    current_seal_id = seal.get("id") or ""
                    break
                if designated:
                    has_unscanned_current = True
            company_check["requiredSeals"].append({
                "category": category,
                "label": label,
                "active": has_active,
                "currentFile": has_current,
                "sealCount": len(seals),
                "sealIds": [seal.get("id") for seal in seals if seal.get("id")],
                "firstSealId": (seals[0].get("id") if seals else "") or "",
                "currentSealId": current_seal_id,
                "nextAction": (
                    "已具備 AV 通過的 current 版本"
                    if has_current
                    else "完成 Seal Vault 防毒掃描後再設為 current"
                    if has_unscanned_current
                    else "上傳 Seal Vault current 版本"
                    if has_active
                    else "建立啟用印章並上傳 current 版本"
                ),
            })
            if not has_active:
                blockers.append(f"{company_name} 缺少啟用的{label}。")
            elif not has_current:
                blockers.append(f"{company_name} 的{label}尚無 AV 通過的 Seal Vault current 版本。")
        checks.append(company_check)
    return checks, blockers


def supabase_internal_launch_user_journeys() -> List[Dict[str, Any]]:
    official_docs = supabase_filter_rows("official_documents", {}, order="created_at.desc", limit=500)
    official_files = supabase_filter_rows("official_document_files", {}, order="created_at.desc", limit=1000)
    approval_steps = supabase_filter_rows("official_document_approval_steps", {}, order="created_at.desc", limit=1000)
    stamp_positions = supabase_filter_rows("official_document_stamp_positions", {}, order="created_at.desc", limit=1000)
    dispatch_records = supabase_filter_rows("official_document_dispatch_records", {}, order="created_at.desc", limit=500)
    inbound_docs = supabase_filter_rows("inbound_documents", {}, order="created_at.desc", limit=500)
    internal_dispatches = supabase_filter_rows("internal_dispatches", {}, order="created_at.desc", limit=500)
    internal_recipients = supabase_filter_rows("internal_dispatch_recipients", {}, order="created_at.desc", limit=1000)
    internal_replies = supabase_filter_rows("internal_dispatch_replies", {}, order="created_at.desc", limit=1000)

    blank_docs = [item for item in official_docs if item.get("source_type") == "blank_editor"]
    blank_submitted = [item for item in blank_docs if item.get("current_status") not in {"draft", "cancelled"}]
    generated_pdfs = [item for item in official_files if item.get("file_type") == "generated_pdf"]
    uploaded_docs = [item for item in official_docs if item.get("source_type") == "uploaded_pdf"]
    original_pdfs = [item for item in official_files if item.get("file_type") == "original_pdf"]
    stamped_pdfs = [item for item in official_files if item.get("file_type") == "stamped_pdf"]
    ga_dispatches = [item for item in dispatch_records if item.get("dispatch_owner_type") == "general_affairs"]
    completed_ga_dispatches = [
        item for item in ga_dispatches
        if item.get("dispatch_status") in {"dispatched", "sent_by_applicant", "closed"} and item.get("completed_at")
    ]
    ga_dispatch_proofs = [item for item in ga_dispatches if item.get("proof_file_id")]
    assigned_inbound = [item for item in inbound_docs if item.get("assignee_user_id")]
    inbound_with_due = [item for item in inbound_docs if item.get("due_at")]
    closed_inbound = [item for item in inbound_docs if item.get("status") in {"closed", "已結案"}]
    reply_required_dispatches = [item for item in internal_dispatches if bool(item.get("reply_required"))]
    dispatches_with_due = [item for item in internal_dispatches if item.get("due_at")]

    blank_missing = [
        "尚未建立空白公文申請單" if len(blank_docs) < 1 else "",
        "空白公文尚未送出簽核" if len(blank_submitted) < 1 else "",
        "尚未產生簽核關卡" if len(approval_steps) < len(OFFICIAL_DOCUMENT_WORKFLOW_STEPS) else "",
        "尚未產生系統公文 PDF" if len(generated_pdfs) < 1 else "",
    ]
    pdf_missing = [
        "尚未建立上傳 PDF 用印申請" if len(uploaded_docs) < 1 else "",
        "尚未保存原始 PDF" if len(original_pdfs) < 1 else "",
        "尚未設定拖拉用印位置" if len(stamp_positions) < 1 else "",
        "尚未產生已用印 PDF" if len(stamped_pdfs) < 1 else "",
    ]
    dispatch_missing = [
        "尚未建立總務寄發紀錄" if len(ga_dispatches) < 1 else "",
        "總務尚未完成寄發" if len(completed_ga_dispatches) < 1 else "",
        "尚未上傳寄發證明" if len(ga_dispatch_proofs) < 1 else "",
    ]
    inbound_missing = [
        "尚未登錄收文" if len(inbound_docs) < 1 else "",
        "尚未分派承辦人" if len(assigned_inbound) < 1 else "",
        "尚未設定辦理期限" if len(inbound_with_due) < 1 else "",
    ]
    internal_missing = [
        "尚未建立內部派文" if len(internal_dispatches) < 1 else "",
        "尚未設定需回文派文" if len(reply_required_dispatches) < 1 else "",
        "尚未設定回文期限" if len(dispatches_with_due) < 1 else "",
        "尚未指定收件同仁" if len(internal_recipients) < 1 else "",
        "尚未收到同仁回文" if len(internal_replies) < 1 else "",
    ]
    return [
        launch_journey_item(
            "blank_official_document",
            "空白公文撰寫、簽核與附件版本",
            "申請人、主管、行政部主任",
            not any(blank_missing),
            [item for item in blank_missing if item],
            [f"空白公文 {len(blank_docs)} 件", f"已送簽 {len(blank_submitted)} 件", f"簽核節點 {len(approval_steps)} 筆", f"公文 PDF {len(generated_pdfs)} 份"],
            "建立一張空白公文，送出後逐關核准，確認附件區有系統產生 PDF。",
            "同仁要能從零撰寫電子公文，並在同一張申請單看到版本與簽核歷程。",
            "dispatch",
            ["申請單不是草稿", "至少有 5 個簽核節點", "附件區看得到系統產生 PDF"],
        ),
        launch_journey_item(
            "uploaded_pdf_stamping",
            "上傳 PDF、多位置用印與已用印版本",
            "申請人、總務",
            not any(pdf_missing),
            [item for item in pdf_missing if item],
            [f"上傳 PDF 申請 {len(uploaded_docs)} 件", f"原始 PDF {len(original_pdfs)} 份", f"用印位置 {len(stamp_positions)} 個", f"已用印 PDF {len(stamped_pdfs)} 份"],
            "上傳一份 PDF，拖拉至少一個用印位置，核准後確認後端產生 stamped PDF。",
            "同仁要能自己選位子，主管核准後系統自動用印並保留原始檔。",
            "dispatch",
            ["原始 PDF 保留", "至少 1 個用印位置", "附件區置頂顯示已用印 PDF"],
        ),
        launch_journey_item(
            "general_affairs_dispatch",
            "總務寄發、證明附件與申請人確認",
            "總務、申請人",
            not any(dispatch_missing),
            [item for item in dispatch_missing if item],
            [f"總務寄發紀錄 {len(ga_dispatches)} 筆", f"已完成 {len(completed_ga_dispatches)} 筆", f"寄發證明 {len(ga_dispatch_proofs)} 份"],
            "總務下載已用印 PDF，回填發文字號/日期/備註，上傳寄發證明後交申請人確認。",
            "用印完成不等於流程結束；必須寄發、留證、結案，使用者才查得到完整申請單。",
            "dispatch",
            ["總務寄發紀錄存在", "寄發狀態已完成", "發文字號或寄發證明已留存"],
        ),
        launch_journey_item(
            "inbound_assignment",
            "收文登錄、承辦分派與期限",
            "總務、收文承辦",
            not any(inbound_missing),
            [item for item in inbound_missing if item],
            [f"收文 {len(inbound_docs)} 件", f"已分派 {len(assigned_inbound)} 件", f"有期限 {len(inbound_with_due)} 件", f"已結案 {len(closed_inbound)} 件"],
            "登錄一筆收文，上傳附件，指派承辦人並設定期限。",
            "收文同仁要能知道誰承辦、何時到期、附件在哪裡。",
            "inbound",
            ["收文已登錄", "承辦人已指派", "辦理期限已設定"],
        ),
        launch_journey_item(
            "internal_dispatch_reply",
            "內部派文、限期回文與回覆附件",
            "發文者、內部收件同仁",
            not any(internal_missing),
            [item for item in internal_missing if item],
            [f"內部派文 {len(internal_dispatches)} 件", f"需回文 {len(reply_required_dispatches)} 件", f"有期限 {len(dispatches_with_due)} 件", f"收件人 {len(internal_recipients)} 位", f"回文 {len(internal_replies)} 筆"],
            "建立一筆需 N 日內回文的內部派文，指定同仁後由收件人回覆文字與附件。",
            "內部同仁要能收到公文、依期限回覆，總務或發文者可追蹤逾期。",
            "dispatch",
            ["指定至少 1 位收件人", "需回文且有期限", "收件人已送出回文"],
        ),
    ]


def supabase_internal_launch_data_readiness() -> Dict[str, Any]:
    try:
        non_seal_blockers: List[str] = []
        warnings: List[str] = []
        role_counts = supabase_internal_launch_user_counts()
        access_readiness = supabase_internal_launch_access_readiness(role_counts)
        non_seal_blockers.extend(access_readiness.get("blockers", []))
        warnings.extend(access_readiness.get("warnings", []))
        for role in INTERNAL_LAUNCH_REQUIRED_ROLES:
            if role_counts.get(role, 0) < 1:
                non_seal_blockers.append(f"缺少啟用的「{role}」帳號，簽核流程會卡關。")
        companies, launch_company_scope, all_companies = supabase_scoped_internal_launch_companies()
        workflow_readiness = build_internal_launch_workflow_readiness(
            companies,
            supabase_internal_launch_finance_applicants_by_company(companies),
            supabase_resolve_official_step_approver,
        )
        non_seal_blockers.extend(workflow_readiness["blockers"])
        seal_checks, seal_blockers = supabase_internal_launch_company_seal_checks()
        user_journeys = supabase_internal_launch_user_journeys()
        warnings.extend([
            f"{item['title']}尚未完成走測：{compact_evidence(item.get('missing') or [])}"
            for item in user_journeys
            if not item.get("ready")
        ])
        non_seal_blockers = list(dict.fromkeys(non_seal_blockers))
        seal_blockers = list(dict.fromkeys(seal_blockers))
        blockers = [*non_seal_blockers, *seal_blockers]
        ready_without_seal_assets = not non_seal_blockers and workflow_readiness["ready"]
        ready = ready_without_seal_assets and not seal_blockers
        return {
            "ready": ready,
            "readyWithoutSealAssets": ready_without_seal_assets,
            "sealAssetsReady": not seal_blockers,
            "summary": f"roles={role_counts}；companies={len(companies)}/{len(all_companies)}；workflowRoutes={sum(1 for item in workflow_readiness['routeChecks'] if item.get('ready'))}/{len(workflow_readiness['routeChecks'])}；sealCompanies={len(seal_checks)}；journeys={sum(1 for item in user_journeys if item.get('ready'))}/{len(user_journeys)}；blockers={len(blockers)}",
            "blockers": blockers,
            "nonSealBlockers": non_seal_blockers,
            "sealBlockers": seal_blockers,
            "warnings": warnings,
            "checks": {
                "roleCounts": role_counts,
                "accessReadiness": access_readiness,
                "applicantReady": workflow_readiness["applicantReady"],
                "applicantCoverage": workflow_readiness["applicantCoverage"],
                "applicableCompanies": workflow_readiness["applicableCompanyCount"],
                "activeCompanies": len(companies),
                "allActiveCompanies": len(all_companies),
                "launchCompanyScope": launch_company_scope,
                "workflowRouteCodes": workflow_readiness["routeCodes"],
                "workflowRoutes": workflow_readiness["routeChecks"],
                "workflowSteps": workflow_readiness["workflowSteps"],
                "companySeals": seal_checks,
                "userJourneys": user_journeys,
            },
        }
    except Exception as exc:
        blocker = f"無法檢查 Supabase 正式上線資料：{type(exc).__name__}"
        return {
            "ready": False,
            "readyWithoutSealAssets": False,
            "sealAssetsReady": False,
            "summary": "launch data readiness query failed",
            "blockers": [blocker],
            "nonSealBlockers": [blocker],
            "sealBlockers": [],
            "warnings": [],
            "checks": {"error": str(exc)[:160]},
        }


def supabase_official_document_files(document_id: str) -> List[Dict[str, Any]]:
    rows = supabase_filter_rows("official_document_files", {"document_id": document_id}, order="version.desc,created_at.desc", limit=500)
    rows.sort(key=lambda item: (0 if item.get("file_type") == "stamped_pdf" else 1, -int(item.get("version") or 0), str(item.get("created_at") or "")))
    return [official_file_metadata(row) for row in rows]


def supabase_official_raw_document_files(document_id: str, file_type: str = "") -> List[Dict[str, Any]]:
    filters = {"document_id": document_id}
    if file_type:
        filters["file_type"] = file_type
    return supabase_filter_rows("official_document_files", filters, order="version.desc,created_at.desc", limit=500)


def supabase_assert_official_document_uploads_av_clean(document: Dict[str, Any]) -> List[Dict[str, Any]]:
    rows = [
        item
        for item in supabase_official_raw_document_files(document["id"])
        if item.get("file_type") in OFFICIAL_AV_REQUIRED_FILE_TYPES
    ]
    if document.get("source_type") == "uploaded_pdf" and not any(item.get("file_type") == "original_pdf" for item in rows):
        raise ValueError("official_document_source_pdf_required")
    checked: List[Dict[str, Any]] = []
    for row in rows:
        file_object = supabase_get("file_objects", row.get("file_object_id") or "") if row.get("file_object_id") else None
        checked.append(require_official_file_av_clean(row, file_object))
    return checked


def supabase_official_document_steps(document_id: str) -> List[Dict[str, Any]]:
    return supabase_filter_rows(
        "official_document_approval_steps",
        {"document_id": document_id},
        order="workflow_generation.asc,step_order.asc",
        limit=200,
    )


def supabase_current_official_document_steps(document_id: str) -> List[Dict[str, Any]]:
    rows = supabase_official_document_steps(document_id)
    if not rows:
        return []
    generation = max(int(row.get("workflow_generation") or 1) for row in rows)
    return [row for row in rows if int(row.get("workflow_generation") or 1) == generation]


def supabase_official_document_actor_snapshots(document_id: str) -> List[Dict[str, Any]]:
    params = {
        "select": "*",
        "source_type": f"in.({','.join(sorted(OFFICIAL_DOCUMENT_ACTOR_SNAPSHOT_SOURCE_TYPES))})",
        "source_id": f"eq.{document_id}",
        "order": "step_no.asc,created_at.asc",
        "limit": "100",
    }
    return supabase_request(
        "GET",
        f"approval_step_actor_snapshots?{urllib.parse.urlencode(params)}",
    )


def supabase_snapshot_official_document_approval_steps(
    document_id: str,
    steps: List[Dict[str, Any]],
) -> int:
    """Write immutable actor assignments through the service-role backend only."""
    timestamp = now()
    rows = [
        row
        for step in steps
        if (row := official_document_actor_snapshot_payload(document_id, step, timestamp))
    ]
    if not rows:
        return 0
    created = supabase_request(
        "POST",
        "approval_step_actor_snapshots?on_conflict=id",
        rows,
        prefer="resolution=ignore-duplicates,return=representation",
    )
    return len(created or [])


def supabase_official_document_logs(document_id: str) -> List[Dict[str, Any]]:
    return supabase_filter_rows("official_document_approval_logs", {"document_id": document_id}, order="created_at.desc", limit=200)


def supabase_official_document_stamp_request(document_id: str) -> Dict[str, Any] | None:
    rows = supabase_filter_rows(
        "official_document_stamp_requests",
        {"document_id": document_id},
        order="created_at.desc,id.desc",
        limit=1,
    )
    if not rows:
        return None
    data = rows[0]
    positions = supabase_official_stamp_positions(data["id"])
    if (
        not positions
        and str(data.get("status") or "") != "cancelled"
        and str(data.get("error_message") or "") != "cleared_by_draft_correction"
    ):
        positions = official_stamp_positions_payload({
            "stamp_page": data.get("stamp_page"),
            "stamp_x": data.get("stamp_x"),
            "stamp_y": data.get("stamp_y"),
            "stamp_width": data.get("stamp_width"),
            "stamp_height": data.get("stamp_height"),
        }, data.get("seal_id") or "")
    data["stamp_positions"] = positions
    data["text_overlays"] = supabase_official_text_overlays(data["id"])
    return data


def supabase_lock_official_stamp_seal_versions(
    document: Dict[str, Any],
    stamp_request: Dict[str, Any],
) -> Dict[str, Any]:
    """Freeze every Supabase seal placement at submission time."""
    positions = stamp_request.get("stamp_positions") or []
    if not positions:
        raise ValueError("official_document_seal_position_required")
    for position in positions:
        seal_id = str(position.get("seal_id") or stamp_request.get("seal_id") or "")
        selected_file_id = str(position.get("locked_seal_file_id") or "")
        selected_hash = str(position.get("locked_seal_sha256") or "")
        if bool(selected_file_id) != bool(selected_hash):
            raise ValueError("official_seal_file_binding_required")
        seal = supabase_validate_official_document_seal(seal_id, str(document.get("company_id") or ""), require_current=False)
        seal_file = (
            supabase_official_seal_file_by_id(selected_file_id, seal_id)
            if selected_file_id
            else supabase_require_current_company_seal_file(seal_id)
        )
        if selected_file_id and selected_hash != str(seal_file.get("file_hash") or ""):
            raise ValueError("official_seal_file_hash_mismatch")
        if str(seal_file.get("dimension_policy_version") or "") != EDOC_SEAL_DIMENSION_POLICY_VERSION:
            raise ValueError("official_seal_file_policy_upgrade_required")
        profile = company_seal_file_dimension_profile(seal.get("seal_size_type"), seal_file)
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"),
            position.get("width") if selected_file_id else None,
            position.get("height") if selected_file_id else None,
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
            allow_unspecified=not selected_file_id,
        )
        supabase_patch(
            "official_document_stamp_positions",
            str(position.get("id") or ""),
            {
                "width": width,
                "height": height,
                "locked_seal_file_id": seal_file["id"],
                "locked_seal_sha256": seal_file["file_hash"],
                "locked_render_width_pt": profile["width_pt"],
                "locked_render_height_pt": profile["height_pt"],
                "locked_dimension_policy_version": profile["dimension_policy_version"],
                "updated_at": now(),
            },
        )
    supabase_patch(
        "official_document_stamp_requests",
        str(stamp_request.get("id") or ""),
        {"status": "pending", "error_message": "", "updated_at": now()},
    )
    refreshed = supabase_official_document_stamp_request(str(document.get("id") or ""))
    if not refreshed:
        raise ValueError("official_document_stamp_request_required")
    return refreshed


def supabase_locked_legacy_official_seal_asset(
    stamp_request: Dict[str, Any],
) -> Tuple[Dict[str, Any], bytes]:
    """Read a submit-time locked raster seal; never follow current pointers."""
    positions = stamp_request.get("stamp_positions") or []
    locked_versions = {
        (
            str(position.get("seal_id") or stamp_request.get("seal_id") or ""),
            str(position.get("locked_seal_file_id") or ""),
            str(position.get("locked_seal_sha256") or ""),
        )
        for position in positions
    }
    if not locked_versions or any(not all(version) for version in locked_versions):
        raise ValueError("official_locked_seal_version_missing")
    if len(locked_versions) != 1:
        raise ValueError("legacy_multiple_seal_versions_requires_editor_v2")
    seal_id, seal_file_id, locked_hash = next(iter(locked_versions))
    rows = supabase_filter_rows("company_seal_files", {"id": seal_file_id, "seal_id": seal_id}, limit=1)
    if not rows:
        raise ValueError("official_locked_seal_version_missing")
    seal_file = supabase_require_seal_file_av_clean(rows[0])
    seal = supabase_get("company_seals", seal_id)
    if not seal:
        raise ValueError("seal_not_found")
    for position in positions:
        validate_locked_company_seal_position(position, seal.get("seal_size_type"), seal_file)
    if seal_file.get("file_hash") != locked_hash or not seal_file.get("file_object_id"):
        raise ValueError("official_locked_seal_hash_mismatch")
    file_object = supabase_get("file_objects", seal_file["file_object_id"])
    if not file_object:
        raise ValueError("seal_file_object_required")
    seal_bytes = supabase_storage_download(
        file_object["storage_key"],
        file_object.get("bucket") or EDOC_SEAL_STORAGE_BUCKET,
    )
    if sha256_bytes(seal_bytes) != locked_hash:
        raise ValueError("official_locked_seal_hash_mismatch")
    return seal_file, seal_bytes


def supabase_official_stamp_positions(request_id: str) -> List[Dict[str, Any]]:
    return supabase_filter_rows("official_document_stamp_positions", {"request_id": request_id}, order="order_index.asc", limit=100)


def supabase_replace_official_stamp_positions(
    request_id: str,
    seal_id: str,
    payload: Dict[str, Any],
    *,
    allow_persisted_bindings: bool = False,
    allow_unbound_current: bool = False,
) -> List[Dict[str, Any]]:
    existing = supabase_official_stamp_positions(request_id)
    incoming = preserve_unidentified_official_position_bindings(
        official_stamp_positions_payload(payload, seal_id),
        existing,
    )
    incoming = require_official_position_set_intent(
        incoming,
        existing,
        allow_persisted_bindings=allow_persisted_bindings,
    )
    positions = canonicalize_official_company_seal_positions(
        incoming,
        supabase_company_seal_row,
        supabase_official_seal_file_by_id,
        existing,
        allow_persisted_bindings=allow_persisted_bindings,
        allow_unbound_current=allow_unbound_current,
    )
    for row in existing:
        qs = urllib.parse.urlencode({"id": f"eq.{row['id']}"})
        supabase_request("DELETE", f"official_document_stamp_positions?{qs}")
    created: List[Dict[str, Any]] = []
    existing_ids = {str(item.get("id") or "") for item in existing}
    for index, position in enumerate(positions, start=1):
        created.append(supabase_insert("official_document_stamp_positions", {
            "id": (
                str(position.get("id") or "")
                if str(position.get("id") or "") in existing_ids
                else f"ODPOS-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
            ),
            "request_id": request_id,
            "seal_id": position["seal_id"],
            "page": position["page"],
            "x": position["x"],
            "y": position["y"],
            "width": position["width"],
            "height": position["height"],
            "page_ref": position.get("page_ref") or "",
            "rotation": position.get("rotation") or 0,
            "opacity": position.get("opacity") if position.get("opacity") is not None else 1,
            "z_index": position.get("z_index") or index,
            "locked_seal_file_id": position.get("locked_seal_file_id") or None,
            "locked_seal_sha256": position.get("locked_seal_sha256") or "",
            "locked_render_width_pt": position.get("locked_render_width_pt"),
            "locked_render_height_pt": position.get("locked_render_height_pt"),
            "locked_dimension_policy_version": position.get("locked_dimension_policy_version") or "",
            "order_index": index,
            "created_at": now(),
            "updated_at": now(),
        }))
    return created


def supabase_official_text_overlays(request_id: str) -> List[Dict[str, Any]]:
    return supabase_filter_rows(
        "official_document_text_overlays",
        {"request_id": request_id},
        order="order_index.asc",
        limit=100,
    )


def supabase_replace_official_text_overlays(request_id: str, payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    overlays = official_text_overlays_payload(payload)
    for row in supabase_official_text_overlays(request_id):
        qs = urllib.parse.urlencode({"id": f"eq.{row['id']}"})
        supabase_request("DELETE", f"official_document_text_overlays?{qs}")
    created: List[Dict[str, Any]] = []
    for index, overlay in enumerate(overlays, start=1):
        created.append(supabase_insert("official_document_text_overlays", {
            "id": f"ODTEXT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "request_id": request_id,
            **overlay,
            "order_index": index,
            "created_at": now(),
            "updated_at": now(),
        }))
    return created


def supabase_official_dispatch_record_metadata(row: Dict[str, Any] | None) -> Dict[str, Any] | None:
    if not row:
        return None
    data = dict(row)
    method = official_dispatch_method(data.get("dispatch_method"))
    data["dispatch_method_label"] = OFFICIAL_DISPATCH_METHODS[method]["label"]
    owner = supabase_user_by_id(data.get("dispatch_owner_user_id") or "") if data.get("dispatch_owner_user_id") else None
    data["dispatch_owner_name"] = owner.get("name") if owner else (data.get("dispatch_owner_user_id") or data.get("dispatch_owner_type") or "")
    proof_file_id = data.get("proof_file_id")
    if proof_file_id:
        proofs = supabase_filter_rows("official_document_files", {"id": proof_file_id, "document_id": data["document_id"]}, limit=1)
        data["proof_file"] = official_file_metadata(proofs[0]) if proofs else None
    else:
        data["proof_file"] = None
    return data


def supabase_official_dispatch_record(document_id: str) -> Dict[str, Any] | None:
    rows = supabase_filter_rows("official_document_dispatch_records", {"document_id": document_id}, order="created_at.desc", limit=1)
    return supabase_official_dispatch_record_metadata(rows[0]) if rows else None


def supabase_resolve_official_dispatch_owner(document: Dict[str, Any], method: str) -> Dict[str, Any]:
    config = OFFICIAL_DISPATCH_METHODS[method]
    if config["owner_type"] == "general_affairs":
        workflow_owner = official_dispatch_workflow_owner(supabase_official_document_steps(document["id"]))
        return supabase_user_by_id(workflow_owner["id"]) or workflow_owner
    if config["owner_type"] == "applicant":
        return supabase_user_by_id(document["applicant_id"]) or {"id": document["applicant_id"], "name": document.get("applicant_name") or "申請人", "role": "申請人"}
    return {"id": "system", "name": "System", "role": "system"}


def supabase_upsert_official_dispatch_record(
    document: Dict[str, Any],
    method: str | None = None,
    actor: Dict[str, Any] | None = None,
    payload: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    method = official_dispatch_method(method or document.get("dispatch_method"))
    owner = supabase_resolve_official_dispatch_owner(document, method)
    config = OFFICIAL_DISPATCH_METHODS[method]
    payload = payload or {}
    if payload.get("proof_file_id"):
        raise ValueError("official_dispatch_proof_file_server_managed")
    raw = supabase_request(
        "POST",
        "rpc/edoc_create_official_document_dispatch_record",
        {
            "p_document_id": document["id"],
            "p_actor_user_id": str((actor or {}).get("id") or "system"),
        },
    )
    result = raw[0] if isinstance(raw, list) and len(raw) == 1 and isinstance(raw[0], dict) else raw
    if not isinstance(result, dict) or not isinstance(result.get("created"), bool):
        raise RuntimeError("official_dispatch_create_invalid_response")
    record = result.get("record") if isinstance(result.get("record"), dict) else {}
    if (
        record.get("document_id") != document["id"]
        or record.get("dispatch_method") != method
        or record.get("dispatch_owner_type") != config["owner_type"]
        or str(record.get("dispatch_owner_user_id") or "") != str(owner.get("id") or "")
    ):
        raise RuntimeError("official_dispatch_create_invalid_response")
    return supabase_official_dispatch_record_metadata(record) or record


def supabase_advance_official_dispatch_after_stamp(
    document_id: str,
    stamped_file: Dict[str, Any],
    actor: Dict[str, Any] | None,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    method = official_dispatch_method(document.get("dispatch_method"))
    record = supabase_upsert_official_dispatch_record(document, method, actor)
    # The stamp-completion transaction/route RPC owns all business writes.
    # Keeping this idempotent prevents retry-driven duplicate routes, logs or
    # notification outbox entries.
    return record


def supabase_update_official_dispatch_record(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    steps = supabase_official_document_steps(document_id)
    actor_snapshots = supabase_official_document_actor_snapshots(document_id)
    if not canDownloadOfficialDocument(user, document, steps, actor_snapshots) and not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
        raise PermissionError("official_dispatch_access_denied")
    record = supabase_official_dispatch_record(document_id)
    if not record:
        # Keep parity with SQLite: dispatch ownership comes from the persisted
        # workflow route, never from a caller-controlled PATCH field.
        method = official_dispatch_method(document.get("dispatch_method"))
        owner = supabase_resolve_official_dispatch_owner(document, method)
        prospective_record = {
            "dispatch_owner_type": OFFICIAL_DISPATCH_METHODS[method]["owner_type"],
            "dispatch_owner_user_id": owner.get("id") or "",
        }
        if not can_manage_official_dispatch(user, document, prospective_record, session, steps):
            raise PermissionError("official_dispatch_update_forbidden")
        record = supabase_upsert_official_dispatch_record(document, method, user)
    if not can_manage_official_dispatch(user, document, record, session, steps):
        raise PermissionError("official_dispatch_update_forbidden")
    if "proof_file_id" in payload:
        raise ValueError("official_dispatch_proof_file_server_managed")
    allowed = {"external_official_document_number", "dispatch_date", "recipient", "recipient_contact", "dispatch_note"}
    update = {key: payload.get(key) or "" for key in allowed if key in payload}
    if not update:
        return supabase_official_dispatch_record(document_id) or record
    supabase_patch("official_document_dispatch_records", record["id"], update)
    supabase_insert_official_log(document_id, "update_dispatch", user, json.dumps(update, ensure_ascii=False), ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return supabase_official_dispatch_record(document_id) or {}


def supabase_complete_official_dispatch(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    steps = supabase_official_document_steps(document_id)
    record = supabase_official_dispatch_record(document_id)
    if not record:
        method = official_dispatch_method(document.get("dispatch_method"))
        owner = supabase_resolve_official_dispatch_owner(document, method)
        prospective_record = {
            "dispatch_owner_type": OFFICIAL_DISPATCH_METHODS[method]["owner_type"],
            "dispatch_owner_user_id": owner.get("id") or "",
        }
        if not can_manage_official_dispatch(user, document, prospective_record, session, steps):
            raise PermissionError("official_dispatch_complete_forbidden")
        record = supabase_upsert_official_dispatch_record(document, method, user)
    if not can_manage_official_dispatch(user, document, record, session, steps):
        raise PermissionError("official_dispatch_complete_forbidden")
    if record.get("dispatch_owner_type") == "general_affairs" and document.get("current_status") != "pending_general_affairs_dispatch":
        raise ValueError("official_document_not_pending_general_affairs_dispatch")
    if record.get("dispatch_owner_type") == "applicant" and document.get("current_status") != "returned_to_applicant_for_send":
        raise ValueError("official_document_not_returned_to_applicant_for_send")
    if "proof_file_id" in payload:
        raise ValueError("official_dispatch_proof_file_server_managed")
    raw = supabase_request(
        "POST",
        "rpc/edoc_complete_official_document_dispatch",
        {
            "p_document_id": document_id,
            "p_dispatch_record_id": record["id"],
            "p_actor_user_id": str(user.get("id") or ""),
            "p_external_official_document_number": payload.get("external_official_document_number"),
            "p_dispatch_date": payload.get("dispatch_date"),
            "p_recipient": payload.get("recipient"),
            "p_recipient_contact": payload.get("recipient_contact"),
            "p_dispatch_note": payload.get("dispatch_note"),
            "p_ip_address": payload.get("ip_address") or "",
            "p_user_agent": (payload.get("user_agent") or "")[:180],
        },
    )
    result = raw[0] if isinstance(raw, list) and len(raw) == 1 and isinstance(raw[0], dict) else raw
    if not isinstance(result, dict) or not isinstance(result.get("completed"), bool):
        raise RuntimeError("official_dispatch_complete_invalid_response")
    if result.get("document_id") != document_id or result.get("dispatch_record_id") != record["id"]:
        raise RuntimeError("official_dispatch_complete_invalid_response")
    if not result["completed"]:
        reason = str(result.get("reason") or "official_dispatch_completion_conflict")
        if reason != "official_dispatch_already_completed":
            raise ValueError(reason)
    return supabase_official_document_detail(document_id, session)


def supabase_upload_official_dispatch_proof_file(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    steps = supabase_official_document_steps(document_id)
    record = supabase_official_dispatch_record(document_id)
    if not record:
        method = official_dispatch_method(document.get("dispatch_method"))
        owner = supabase_resolve_official_dispatch_owner(document, method)
        prospective_record = {
            "dispatch_owner_type": OFFICIAL_DISPATCH_METHODS[method]["owner_type"],
            "dispatch_owner_user_id": owner.get("id") or "",
        }
        if not can_manage_official_dispatch(user, document, prospective_record, session, steps):
            raise PermissionError("official_dispatch_proof_upload_forbidden")
        record = supabase_upsert_official_dispatch_record(document, method, user)
    if not can_manage_official_dispatch(user, document, record, session, steps):
        raise PermissionError("official_dispatch_proof_upload_forbidden")
    content = payload.get("content_base64") or ""
    if not content:
        raise ValueError("dispatch_proof_file_required")
    data = base64.b64decode(content)
    mime_type = payload.get("file_mime_type") or payload.get("mime_type") or "application/pdf"
    if mime_type.lower() not in OFFICIAL_DISPATCH_PROOF_MIME_TYPES:
        raise ValueError("dispatch_proof_mime_type_not_allowed")
    if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
        raise ValueError("dispatch_proof_file_too_large")
    file_name = Path(payload.get("file_name") or f"{document_id}-dispatch-proof").name
    scan_status, scan_signature = scan_official_upload_bytes(data, file_name)
    file_row = supabase_store_file_object(document_id, file_name, data, "official-documents", "dispatch-proof", official_actor_name(user), mime_type)
    file_row = supabase_persist_file_object_scan_result(
        file_row["id"],
        scan_status,
        scan_signature,
        official_actor_name(user),
    )
    official_file = supabase_insert_official_document_file(document_id, "dispatch_proof", file_row, official_actor_name(user))
    supabase_patch("official_document_dispatch_records", record["id"], {"proof_file_id": official_file["id"], "updated_at": now()})
    supabase_insert_official_log(document_id, "upload_dispatch_proof", user, official_file["file_hash"], file_id=official_file["id"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return {"dispatch_record": supabase_official_dispatch_record(document_id), "file": official_file_metadata(official_file)}


def supabase_upload_official_document_attachment(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document.get("applicant_id") != user.get("id"):
        raise PermissionError("official_document_attachment_upload_forbidden")
    require_official_creation_company(user, document.get("company_id"))
    if document.get("current_status") not in {"draft", "rejected"}:
        raise ValueError("official_document_attachments_locked_after_submit")
    content = payload.get("content_base64") or payload.get("file_content_base64") or ""
    if not content:
        raise ValueError("official_document_attachment_required")
    try:
        data = base64.b64decode(content, validate=True)
    except (ValueError, binascii.Error) as exc:
        raise ValueError("official_document_attachment_invalid_base64") from exc
    if not data:
        raise ValueError("official_document_attachment_empty")
    if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
        raise ValueError("official_document_attachment_too_large")
    file_name = Path(payload.get("file_name") or "attachment.pdf").name
    mime_type = normalized_official_attachment_mime(payload, file_name)
    if mime_type == "application/pdf":
        inspect_editor_pdf(data)
    scan_status, scan_signature = scan_official_upload_bytes(data, file_name)
    file_row = supabase_store_file_object(
        document_id,
        file_name,
        data,
        "official-documents",
        "attachment",
        official_actor_name(user),
        mime_type,
    )
    file_row = supabase_persist_file_object_scan_result(
        file_row["id"],
        scan_status,
        scan_signature,
        official_actor_name(user),
    )
    official_file = supabase_insert_official_document_file(document_id, "attachment", file_row, official_actor_name(user))
    supabase_insert_official_log(
        document_id,
        "upload_attachment",
        user,
        official_file["file_hash"],
        file_id=official_file["id"],
        ip_address=payload.get("ip_address") or "",
        user_agent=payload.get("user_agent") or "",
    )
    return {"file": official_file_metadata(official_file), "document": supabase_official_document_detail(document_id, session)}


def supabase_insert_official_log(
    document_id: str,
    action: str,
    actor: Dict[str, Any] | None,
    comment: str = "",
    *,
    step_id: str = "",
    file_id: str = "",
    ip_address: str = "",
    user_agent: str = "",
    principal_actor_id: str = "",
    decision_evidence: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    actor_name = official_actor_name(actor)
    row = supabase_insert("official_document_approval_logs", {
        "id": f"ODLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "document_id": document_id,
        "step_id": step_id or None,
        "file_id": file_id or None,
        "actor_id": actor.get("id") if actor else "system",
        "actor_name": actor_name,
        "principal_actor_id": principal_actor_id or None,
        "action": action,
        "comment": comment,
        "decision_evidence_json": decision_evidence or {},
        "ip_address": ip_address,
        "user_agent": user_agent[:180] if user_agent else "",
        "created_at": now(),
    })
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": actor_name,
        "action": action,
        "target_type": "official_documents",
        "target_id": document_id,
        "detail": comment,
        "event_type": action if action in LOGGING_AUDIT_EVENT_TYPES else "submit",
        "module_code": "official_documents",
        "resource_type": "official_documents",
        "resource_id": document_id,
        "result": "success",
        "severity": "info",
        "actor_user_id": actor.get("id") if actor else "system",
        "metadata_json": {
            "principal_actor_id": principal_actor_id or "",
            "decision_evidence": decision_evidence or {},
        },
    })
    return row


def supabase_insert_official_document_file(
    document_id: str,
    file_type: str,
    file_row: Dict[str, Any],
    actor: str,
    *,
    stamp_request_id: str = "",
    stamp_claim_token: str = "",
) -> Dict[str, Any]:
    versions = supabase_official_raw_document_files(document_id, file_type)
    next_version = max([int(item.get("version") or 0) for item in versions] or [0]) + 1
    row = {
        "id": f"ODFILE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "document_id": document_id,
        "file_object_id": file_row.get("id"),
        "file_type": file_type,
        "file_name": file_row.get("file_name") or f"{document_id}-{file_type}.pdf",
        "file_storage_key": file_row.get("storage_key") or "",
        "file_mime_type": file_row.get("mime_type") or "application/pdf",
        "file_size": int(file_row.get("size_bytes") or 0),
        "file_hash": file_row.get("sha256") or "",
        "version": next_version,
        "uploaded_by": actor,
        "created_at": now(),
    }
    if stamp_request_id:
        row["stamp_request_id"] = stamp_request_id
        row["stamp_claim_token"] = stamp_claim_token or None
    return supabase_insert("official_document_files", row)


def supabase_store_official_pdf_file(
    document_id: str,
    file_type: str,
    file_name: str,
    data: bytes,
    actor: str,
    *,
    stamp_request_id: str = "",
    stamp_claim_token: str = "",
) -> Dict[str, Any]:
    scan_result = scan_official_upload_bytes(data, file_name) if file_type == "original_pdf" else None
    file_row = supabase_store_file_object(document_id, file_name, data, "official-documents", f"{file_type}-v1", actor, "application/pdf")
    if scan_result:
        file_row = supabase_persist_file_object_scan_result(file_row["id"], scan_result[0], scan_result[1], actor)
    return supabase_insert_official_document_file(
        document_id,
        file_type,
        file_row,
        actor,
        stamp_request_id=stamp_request_id,
        stamp_claim_token=stamp_claim_token,
    )


def supabase_official_pdf_document_payload(document: Dict[str, Any]) -> Dict[str, Any]:
    company = supabase_official_company_row(document["company_id"])
    metadata = parse_json_field(document.get("metadata_json"))
    extra = metadata.get("extra") if isinstance(metadata.get("extra"), dict) else {}
    body_parts = []
    if document.get("description"):
        body_parts.append(f"說明：\n{document['description']}")
    if document.get("method"):
        body_parts.append(f"辦法：\n{document['method']}")
    return {
        "id": document["id"],
        "doc_no": document["id"],
        "company_name": company.get("name") or "歲悅股份有限公司",
        "doc_type": extra.get("document_type") or metadata.get("document_type") or "函",
        "agency_name": document.get("recipient") or "未指定受文者",
        "copy_recipients": official_pdf_copy_recipients(
            extra.get("copy_recipients") or extra.get("copyRecipients") or metadata.get("copy_recipients") or metadata.get("copyRecipients"),
            company.get("name") or "",
        ),
        "subject": document.get("subject") or document.get("title") or "未命名發文",
        "body": "\n\n".join(body_parts) or document.get("description") or "尚未填寫說明內容。",
        "owner": document.get("handler_name") or document.get("applicant_name") or "承辦人",
        "department": document.get("dispatch_unit") or document.get("applicant_department_name") or "",
        "attachments": metadata.get("attachments", "附件詳如附件區"),
        "priority": extra.get("priority") or metadata.get("priority") or "普通件",
        "contact_address": extra.get("contact_address") or extra.get("contactAddress") or company.get("address") or "",
        "contact_owner": extra.get("contact_owner") or extra.get("contactOwner") or document.get("handler_name") or document.get("applicant_name") or "",
        "contact_phone": extra.get("contact_phone") or extra.get("contactPhone") or "",
        "contact_fax": extra.get("contact_fax") or extra.get("contactFax") or EDOC_DEFAULT_CONTACT_FAX,
        "contact_email": extra.get("contact_email") or extra.get("contactEmail") or "",
        "created_at": document.get("created_at"),
    }


def supabase_ensure_official_generated_pdf(document: Dict[str, Any], actor: str = "PDF Worker") -> Dict[str, Any]:
    rows = supabase_official_raw_document_files(document["id"], "generated_pdf")
    if rows:
        return rows[0]
    package = build_official_pdf_package(supabase_official_pdf_document_payload(document), [], "歲悅正式函", 1)
    file_row = supabase_store_official_pdf_file(document["id"], "generated_pdf", f"{document['id']}-generated.pdf", package["data"], actor)
    supabase_insert_official_log(document["id"], "generate_pdf", {"id": "system", "name": actor, "role": "system"}, file_row["file_hash"], file_id=file_row["id"])
    return file_row


def supabase_official_latest_source_file(document: Dict[str, Any]) -> Dict[str, Any]:
    file_type = "original_pdf" if document.get("source_type") == "uploaded_pdf" else "generated_pdf"
    if file_type == "generated_pdf":
        supabase_ensure_official_generated_pdf(document)
    rows = supabase_official_raw_document_files(document["id"], file_type)
    if not rows:
        raise ValueError("official_document_source_pdf_required")
    return rows[0]


def supabase_official_workflow_config() -> Dict[str, Any]:
    rows = supabase_filter_rows("settings", {"key": OFFICIAL_WORKFLOW_SETTING_KEY}, limit=1)
    if not rows:
        return normalize_official_workflow_config()
    return normalize_official_workflow_config(parse_json_field(rows[0].get("value_json")))


def supabase_save_official_workflow_config(payload: Dict[str, Any]) -> Dict[str, Any]:
    config = normalize_official_workflow_config(payload)
    existing = supabase_filter_rows("settings", {"key": OFFICIAL_WORKFLOW_SETTING_KEY}, limit=1)
    body = {
        "key": OFFICIAL_WORKFLOW_SETTING_KEY,
        "value_json": json.dumps(config, ensure_ascii=False),
        "version": int(existing[0].get("version") or 0) + 1 if existing else 1,
        "updated_at": now(),
    }
    supabase_request(
        "POST",
        "settings?on_conflict=key",
        body,
        prefer="resolution=merge-duplicates,return=representation",
    )
    return config


def supabase_create_official_workflow_steps(
    document: Dict[str, Any],
    applicant: Dict[str, Any],
    *,
    actor_plan: Dict[str, Dict[str, Any]] | None = None,
    workflow_steps: List[Dict[str, Any]] | None = None,
) -> List[Dict[str, Any]]:
    seal_context = official_seal_context_from_document(document)
    selected_workflow_steps = workflow_steps or (official_seal_workflow_steps(seal_context["approval_route_code"]) if seal_context else supabase_official_workflow_config()["steps"])
    all_existing = supabase_official_document_steps(document["id"])
    current_generation = max(
        (int(step.get("workflow_generation") or 1) for step in all_existing),
        default=0,
    )
    existing = [
        step for step in all_existing
        if int(step.get("workflow_generation") or 1) == current_generation
    ] if current_generation else []
    target_generation = current_generation or 1
    generation_base = 0
    if existing and all(step.get("status") == "skipped" for step in existing):
        supabase_snapshot_official_document_approval_steps(document["id"], existing)
        generation_base = max(int(step.get("step_order") or 0) for step in all_existing)
        target_generation = current_generation + 1
        existing = []
    if existing and not official_workflow_step_sequence_matches(existing, selected_workflow_steps):
        recoverable_prefix = (
            document.get("current_status") in {"draft", "rejected"}
            and all(step.get("status") == "pending" for step in existing)
        )
        if not recoverable_prefix:
            raise ValueError("official_workflow_existing_steps_invalid")
        supabase_snapshot_official_document_approval_steps(document["id"], existing)
        generation_base = max(int(step.get("step_order") or 0) for step in all_existing)
        target_generation = current_generation + 1
        patch_query = urllib.parse.urlencode({
            "document_id": f"eq.{document['id']}",
            "workflow_generation": f"eq.{current_generation}",
            "status": "eq.pending",
        })
        supabase_request(
            "PATCH",
            f"official_document_approval_steps?{patch_query}",
            {
                "status": "skipped",
                "comment": "未啟用的舊流程已作廢；系統已建立完整簽核流程。",
                "updated_at": now(),
            },
        )
        existing = []
    if existing and document.get("current_status") in {"draft", "rejected"} and any(
        step.get("status") != "pending" for step in existing
    ):
        raise ValueError("official_workflow_existing_steps_invalid")
    if existing:
        if actor_plan is not None:
            for stored_step in existing:
                expected_actor = actor_plan.get(stored_step.get("step_key") or "")
                if not expected_actor or stored_step.get("approver_user_id") != expected_actor.get("id"):
                    raise ValueError(f"official_workflow_actor_snapshot_changed:{stored_step.get('step_key') or 'unknown'}")
        if finance_workflow_actor(applicant):
            for stored_step in existing:
                approver = supabase_user_by_id(stored_step.get("approver_user_id") or "")
                require_valid_finance_workflow_step_actor(
                    stored_step,
                    applicant,
                    approver,
                    seal_context=seal_context,
                )
        supabase_snapshot_official_document_approval_steps(document["id"], existing)
        return existing
    company = supabase_official_company_row(document["company_id"])
    resolved_steps: List[Tuple[Dict[str, Any], Dict[str, Any] | None]] = []
    for step in selected_workflow_steps:
        approver = actor_plan.get(step["key"]) if actor_plan is not None else supabase_resolve_official_step_approver(step, applicant, company)
        require_valid_finance_workflow_step_actor(
            step,
            applicant,
            approver,
            seal_context=seal_context,
        )
        if not approver:
            error = "official_seal_route_actor_unresolved" if seal_context else "official_workflow_actor_unresolved"
            raise ValueError(f"{error}:{step['key']}")
        resolved_steps.append((step, approver))
    pending_rows: List[Dict[str, Any]] = []
    for step, approver in resolved_steps:
        timestamp = now()
        pending_rows.append({
            "id": f"ODSTEP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "document_id": document["id"],
            "workflow_generation": target_generation,
            "step_order": int(step["order"]),
            "step_key": step["key"],
            "step_name": step["name"],
            "approver_user_id": approver.get("id") if approver else "",
            "approver_name": approver.get("name") if approver else step["role"],
            "approver_role": approver.get("role") if approver else step["role"],
            "status": "pending",
            "comment": "",
            "approved_at": "",
            "review_started_at": None,
            "created_at": timestamp,
            "updated_at": timestamp,
        })
    # PostgREST executes one bulk insert request in one database transaction.
    # This prevents a Function interruption from leaving a prefix that could
    # otherwise look like a legitimate shortened workflow on retry.
    created = supabase_request(
        "POST",
        "official_document_approval_steps",
        pending_rows,
        prefer="return=representation",
    )
    if (
        not isinstance(created, list)
        or len(created) != len(pending_rows)
        or {str(row.get("id") or "") for row in created}
        != {str(row.get("id") or "") for row in pending_rows}
    ):
        raise RuntimeError("official_workflow_step_bulk_insert_invalid_response")
    created_by_id = {str(row["id"]): row for row in created}
    created = [created_by_id[str(row["id"])] for row in pending_rows]
    supabase_snapshot_official_document_approval_steps(document["id"], created)
    return created


def supabase_official_document_detail(document_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    all_steps = supabase_official_document_steps(document_id)
    current_generation = max(
        (int(step.get("workflow_generation") or 1) for step in all_steps),
        default=0,
    )
    steps = [
        step for step in all_steps
        if int(step.get("workflow_generation") or 1) == current_generation
    ] if current_generation else []
    actor_snapshots = supabase_official_document_actor_snapshots(document_id)
    user = session.get("user") if session else None
    is_participant = bool(user and canDownloadOfficialDocument(user, document, all_steps, actor_snapshots))
    current_step = next((
        step for step in steps
        if step.get("step_key") == document.get("current_step") and step.get("status") == "pending"
    ), None)
    active_delegation = None
    if user and current_step and current_step.get("status") == "pending" and current_step.get("approver_user_id") != user.get("id"):
        active_delegation = supabase_active_official_workflow_delegation(document, current_step, user)
    if user and not is_participant and not active_delegation:
        if not official_document_user_same_company(user, document) or not str(user.get("company_id") or "").strip():
            raise PermissionError("official_document_company_forbidden")
        if not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
            raise PermissionError("official_document_access_denied")
    files = supabase_official_document_files(document_id)
    logs = supabase_official_document_logs(document_id)
    stamp_request = supabase_official_document_stamp_request(document_id)
    dispatch_record = supabase_official_dispatch_record(document_id)
    package = official_application_package(document, files, steps, logs, stamp_request, dispatch_record)
    raw_missing_items = document.get("correction_missing_items_json")
    correction = {
        "reason_category": document.get("correction_reason_category") or "",
        "missing_items": parse_json_any(raw_missing_items, []),
        "due_at": document.get("correction_due_at") or "",
        "requested_at": document.get("correction_requested_at") or "",
        "resubmitted_at": document.get("correction_resubmitted_at") or "",
    }
    return {
        **document,
        "metadata": parse_json_field(document.get("metadata_json")),
        "official_seal": package.get("official_seal"),
        "document_category": package.get("document_category") or "",
        "approval_route_code": package.get("approval_route_code") or "",
        "approval_route_name": package.get("approval_route_name") or "",
        "application_package": package,
        "document_versions": package["document_versions"],
        "attachments": package["attachments"],
        "download_logs": package["download_logs"],
        "process_logs": package["process_logs"],
        "files": files,
        "approval_steps": steps,
        "approval_step_history": all_steps,
        "logs": logs,
        "stamp_request": package.get("stamp_request"),
        "dispatch_record": dispatch_record,
        "correction": correction,
        "can_correct": bool(user and user.get("id") == document.get("applicant_id") and document.get("current_status") in {"draft", "rejected"}),
        "can_resubmit": bool(user and user.get("id") == document.get("applicant_id") and document.get("current_status") == "rejected"),
        "can_download": is_participant,
        "can_manage_dispatch": bool(user and can_manage_official_dispatch(user, document, dispatch_record, session, steps)),
        "can_retry_stamp": bool(user and official_stamp_recoverable(document, stamp_request) and can_retry_official_stamp(user, steps)),
        "can_confirm": bool(user and user.get("id") == document.get("applicant_id") and document.get("current_step") == "applicant_confirm" and document.get("current_status") in {"stamped", "dispatched", "sent_by_applicant"}),
        "can_act": bool(user and current_step and current_step.get("status") == "pending" and (current_step.get("approver_user_id") == user.get("id") or active_delegation)),
        "acting_for_user_id": current_step.get("approver_user_id") if active_delegation and current_step else "",
        "delegation_id": active_delegation.get("id") if active_delegation else "",
    }


def supabase_list_official_documents(query: Dict[str, List[str]] | None, session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    user = supabase_official_session_user(session)
    query = query or {}
    rows = supabase_filter_rows("official_documents", {}, order="created_at.desc", limit=300)
    status = (query.get("status") or [""])[0]
    company_id = (query.get("company_id") or [""])[0]
    applicant_id = (query.get("applicant_id") or [""])[0]
    scope = (query.get("scope") or [""])[0]
    user_company_id = str(user.get("company_id") or "").strip()
    items: List[Dict[str, Any]] = []
    for item in rows:
        if status and item.get("current_status") != status:
            continue
        if company_id and item.get("company_id") != company_id:
            continue
        if applicant_id and item.get("applicant_id") != applicant_id:
            continue
        steps = supabase_official_document_steps(item["id"])
        actor_snapshots = supabase_official_document_actor_snapshots(item["id"])
        is_applicant = item.get("applicant_id") == user.get("id")
        is_participant = user.get("id") in official_document_participant_ids(item, steps, actor_snapshots)
        if user_company_id and str(item.get("company_id") or "") != user_company_id and not is_participant:
            continue
        dispatch_record = supabase_official_dispatch_record(item["id"])
        current_pending = next((step for step in steps if step.get("status") == "pending" and step.get("step_key") == item.get("current_step")), None)
        active_delegation = None
        if current_pending and current_pending.get("approver_user_id") != user.get("id"):
            active_delegation = supabase_active_official_workflow_delegation(item, current_pending, user)
        is_current_todo = bool(current_pending and (current_pending.get("approver_user_id") == user.get("id") or active_delegation))
        is_dispatch_todo = bool(
            dispatch_record
            and dispatch_record.get("dispatch_status") == "pending"
            and dispatch_record.get("dispatch_owner_user_id") == user.get("id")
        )
        stamp_request = supabase_official_document_stamp_request(item["id"])
        is_stamp_retry_todo = official_stamp_recoverable(item, stamp_request) and can_retry_official_stamp(user, steps)
        if scope == "mine" and not is_applicant:
            continue
        if scope == "todo" and not (is_current_todo or is_dispatch_todo or is_stamp_retry_todo):
            continue
        if not scope and not is_applicant and not is_participant and (not user_company_id or not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"])):
            continue
        seal_context = official_seal_context_from_document(item)
        item["official_seal"] = seal_context
        item["document_category"] = (seal_context or {}).get("document_category") or ""
        item["approval_route_code"] = (seal_context or {}).get("approval_route_code") or ""
        item["approval_route_name"] = (seal_context or {}).get("approval_route_name") or ""
        item["approval_steps"] = steps
        item["stamp_request"] = official_application_package(item, [], [], [], stamp_request).get("stamp_request")
        item["dispatch_record"] = dispatch_record
        item["current_step_name"] = next((step["step_name"] for step in steps if step.get("step_key") == item.get("current_step")), "")
        item["acting_for_user_id"] = current_pending.get("approver_user_id") if active_delegation and current_pending else ""
        item["delegation_id"] = active_delegation.get("id") if active_delegation else ""
        items.append(item)
    return items


def _supabase_editor_latest_revision(document_id: str) -> Dict[str, Any] | None:
    rows = supabase_filter_rows("official_document_editor_revisions", {"document_id": document_id}, order="revision_no.desc", limit=1)
    return rows[0] if rows else None


def _supabase_editor_assert_document_access(document: Dict[str, Any], session: Dict[str, Any] | None, *, write: bool = False) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    user_company_id = str(user.get("company_id") or "")
    if write:
        if user_company_id and user_company_id != str(document.get("company_id") or "") and user.get("id") != "system":
            raise PermissionError("official_editor_company_forbidden")
        metadata = parse_json_field(document.get("metadata_json"))
        if not metadata.get("pdf_editor_v2"):
            raise ValueError("editor_legacy_document_read_only")
        if not pdf_editor_v2_enabled_for_company(str(document.get("company_id") or "")):
            raise PermissionError("pdf_editor_v2_not_enabled_for_company")
        if document.get("applicant_id") != user.get("id"):
            raise PermissionError("official_editor_write_forbidden")
        if document.get("current_status") not in {"draft", "rejected"}:
            raise ValueError("editor_locked_after_submit")
    else:
        steps = supabase_official_document_steps(document["id"])
        actor_snapshots = supabase_official_document_actor_snapshots(document["id"])
        is_participant = canDownloadOfficialDocument(user, document, steps, actor_snapshots)
        if not is_participant:
            if (
                not user_company_id
                or user_company_id != str(document.get("company_id") or "")
            ):
                raise PermissionError("official_editor_company_forbidden")
            if not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
                raise PermissionError("official_editor_read_forbidden")
    return user


def _supabase_insert_editor_revision(document_id: str, state: Dict[str, Any], actor: Dict[str, Any], parent_revision_id: str = "") -> Dict[str, Any]:
    latest = _supabase_editor_latest_revision(document_id)
    revision_no = int(latest.get("revision_no") or 0) + 1 if latest else 1
    normalized = validate_editor_state(json.loads(json.dumps(state, ensure_ascii=False)))
    normalized["revisionNo"] = revision_no
    normalized["manifestSha256"] = canonical_editor_manifest(normalized)
    return supabase_insert("official_document_editor_revisions", {
        "id": f"ODREV-{int(time.time() * 1000)}-{secrets.token_hex(4).upper()}",
        "document_id": document_id,
        "revision_no": revision_no,
        "parent_revision_id": parent_revision_id or (latest.get("id") if latest else None),
        "schema_version": EDOC_EDITOR_SCHEMA_VERSION,
        "editor_state_json": json.dumps(normalized, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
        "manifest_sha256": normalized["manifestSha256"],
        "renderer_version": EDOC_EDITOR_RENDERER_VERSION,
        "created_by": actor.get("id") or actor.get("email") or "system",
        "created_at": now(),
    })


def supabase_create_official_editor_draft(payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    if not session_has_any_permission(session, ["official_documents.compose", "official_documents.all_todo"]):
        raise PermissionError("official_document_create_forbidden")
    company_id = require_official_creation_company(user, payload.get("company_id") or user.get("company_id"))
    if not launch_company_in_scope(company_id):
        raise PermissionError("company_not_in_launch_scope")
    if not pdf_editor_v2_enabled_for_company(company_id):
        raise PermissionError("pdf_editor_v2_not_enabled_for_company")
    company = supabase_official_company_row(company_id)
    require_official_seal_classification(payload)
    document_id = str(payload.get("id") or f"OD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}")
    metadata, seal_context, workflow_template_key = official_editor_draft_metadata(payload, user, company)
    ts = now()
    supabase_insert("official_documents", {
        "id": document_id,
        "company_id": company_id,
        "document_type": payload.get("document_type") or "electronic_seal_pdf_editor_v2",
        "source_type": "uploaded_pdf",
        "title": payload.get("title") or payload.get("subject") or "電子用印 PDF 草稿",
        "subject": payload.get("subject") or payload.get("title") or "",
        "description": payload.get("description") or "",
        "method": payload.get("method") or "",
        "recipient": payload.get("recipient") or "",
        "dispatch_unit": payload.get("dispatch_unit") or user.get("unit") or "",
        "handler_name": payload.get("handler_name") or user.get("name") or "",
        "applicant_id": user["id"],
        "applicant_name": user.get("name") or user.get("email") or "",
        "applicant_department_id": payload.get("applicant_department_id") or user.get("unit") or "",
        "applicant_department_name": payload.get("applicant_department_name") or user.get("unit") or "",
        "workflow_template_key": workflow_template_key,
        "dispatch_method": official_document_dispatch_method("uploaded_pdf", payload.get("dispatch_method")),
        "requires_stamp": True,
        "current_status": "draft",
        "current_step": "",
        "request_reason": payload.get("request_reason") or payload.get("reason") or "",
        "stamped_file_id": None,
        "metadata_json": json.dumps(metadata, ensure_ascii=False),
        "created_at": ts,
        "updated_at": ts,
    })
    revision = _supabase_insert_editor_revision(document_id, {"schemaVersion": 2, "revisionNo": 1, "sourceFiles": [], "pages": [], "elements": [], "manifestSha256": ""}, user)
    supabase_insert_official_log(document_id, "create_editor_draft", user, f"revision_id={revision['id']};schema=2;renderer={EDOC_EDITOR_RENDERER_VERSION}")
    public = _editor_revision_public(revision)
    return {"id": document_id, "document_id": document_id, "company_id": company["id"], "editor_revision": public, "editor_state": public["state"]}


def _supabase_storage_direct_tus_url() -> str:
    base = object_storage_endpoint()
    parsed = urllib.parse.urlparse(EDOC_STORAGE_SUPABASE_URL or base)
    hostname = parsed.hostname or ""
    if hostname.endswith(".supabase.co") and not hostname.endswith(".storage.supabase.co"):
        project_ref = hostname.split(".", 1)[0]
        return f"https://{project_ref}.storage.supabase.co/storage/v1/upload/resumable"
    if not base:
        raise ValueError("supabase_storage_endpoint_required")
    return f"{base.rstrip('/')}/upload/resumable"


def _supabase_create_signed_upload_token(storage_path: str, bucket: str) -> str:
    base = object_storage_endpoint()
    if not base:
        raise ValueError("supabase_storage_endpoint_required")
    url = f"{base.rstrip('/')}/object/upload/sign/{urllib.parse.quote(bucket, safe='')}/{urllib.parse.quote(storage_path, safe='/')}"
    request = urllib.request.Request(url, data=json.dumps({"allowOverwrite": False}).encode("utf-8"), headers=supabase_storage_headers({"Content-Type": "application/json"}), method="POST")
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            payload = json.loads(response.read().decode("utf-8") or "{}")
    except urllib.error.HTTPError as exc:
        detail = redact_text(exc.read().decode("utf-8", "ignore"))
        raise ValueError(f"editor_signed_upload_failed:{exc.code}:{detail[:160]}") from exc
    token = str(payload.get("token") or "")
    if not token:
        raise ValueError("editor_signed_upload_token_missing")
    return token


def supabase_create_official_editor_upload_intent(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    user = _supabase_editor_assert_document_access(document, session, write=True)
    meta = _validate_editor_upload_metadata(payload)
    latest = _supabase_editor_latest_revision(document_id)
    if not latest:
        raise ValueError("editor_revision_not_found")
    asset_id = f"ODASSET-{int(time.time() * 1000)}-{secrets.token_hex(4).upper()}"
    storage_path = f"editor/{document_id}/{asset_id}-{meta['file_name']}"
    expires_at = (datetime.now() + timedelta(hours=2)).isoformat(timespec="seconds")
    row = supabase_insert("official_document_editor_assets", {
        "id": asset_id,
        "document_id": document_id,
        "editor_revision_id": latest["id"],
        "asset_kind": meta["asset_kind"],
        "file_object_id": None,
        "official_file_id": None,
        "file_name": meta["file_name"],
        "mime_type": meta["mime_type"],
        "size_bytes": meta["size_bytes"],
        "sha256": "",
        "expected_sha256": meta["expected_sha256"],
        "storage_bucket": EDOC_STORAGE_BUCKET,
        "storage_path": storage_path,
        "upload_status": "pending",
        "scan_status": "pending",
        "preflight_status": "pending",
        "page_count": 0,
        "metadata_json": json.dumps({"base_revision_no": int(latest["revision_no"]), "expires_at": expires_at}, ensure_ascii=False),
        "created_by": user.get("id") or "",
        "created_at": now(),
        "finalized_at": None,
    })
    token = _supabase_create_signed_upload_token(storage_path, EDOC_STORAGE_BUCKET)
    return {
        "upload_id": asset_id,
        "asset_id": asset_id,
        "protocol": "tus",
        "upload_url": _supabase_storage_direct_tus_url(),
        "headers": {"x-signature": token, "x-upsert": "false", "Cache-Control": "no-store"},
        "metadata": {"bucketName": EDOC_STORAGE_BUCKET, "objectName": storage_path, "contentType": meta["mime_type"], "cacheControl": "0"},
        "chunk_size": EDOC_EDITOR_TUS_CHUNK_SIZE,
        "expires_at": expires_at,
        "asset": _editor_asset_public(row),
    }


def _supabase_editor_asset_failure(asset: Dict[str, Any], error_code: str, *, quarantine: bool = False) -> None:
    metadata = parse_json_any(asset.get("metadata_json"), {}) or {}
    metadata["error_code"] = error_code
    supabase_patch("official_document_editor_assets", asset["id"], {
        "upload_status": "quarantined" if quarantine else "failed",
        "scan_status": "failed" if quarantine else "pending",
        "preflight_status": "blocked" if quarantine else "failed",
        "metadata_json": json.dumps(metadata, ensure_ascii=False),
        "finalized_at": now(),
    })


def supabase_finalize_official_editor_upload(document_id: str, upload_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    user = _supabase_editor_assert_document_access(document, session, write=True)
    rows = supabase_filter_rows("official_document_editor_assets", {"id": upload_id, "document_id": document_id}, limit=1)
    if not rows:
        raise ValueError("editor_upload_not_found")
    asset = rows[0]
    if asset.get("upload_status") == "finalized":
        latest_public = supabase_get_official_editor_state(document_id, session)
        return {"asset": _editor_asset_public(asset), "pages": latest_public["state"].get("pages") or [], "editor_state": latest_public["state"], "editor_revision": latest_public}
    if asset.get("upload_status") in {"failed", "quarantined"}:
        raise ValueError("editor_upload_new_intent_required")
    try:
        data = supabase_storage_download(asset["storage_path"], asset.get("storage_bucket") or EDOC_STORAGE_BUCKET)
    except Exception:
        _supabase_editor_asset_failure(asset, "editor_upload_incomplete")
        raise ValueError("editor_upload_incomplete")
    if len(data) != int(asset["size_bytes"]):
        _supabase_editor_asset_failure(asset, "editor_upload_size_mismatch")
        raise ValueError("editor_upload_size_mismatch")
    digest = sha256_bytes(data)
    if digest != str(asset["expected_sha256"]).upper() or (payload.get("sha256") and str(payload["sha256"]).upper() != digest):
        _supabase_editor_asset_failure(asset, "editor_upload_hash_mismatch")
        raise ValueError("editor_upload_hash_mismatch")
    latest = _supabase_editor_latest_revision(document_id)
    metadata = parse_json_any(asset.get("metadata_json"), {}) or {}
    if not latest or int(metadata.get("base_revision_no") or 0) != int(latest.get("revision_no") or 0):
        _supabase_editor_asset_failure(asset, "editor_revision_conflict")
        raise ValueError("editor_revision_conflict")
    try:
        scan_status, signature = editor_scan_bytes_for_threats(
            data,
            asset["file_name"],
            storage_key=asset.get("storage_path") or "",
            storage_bucket=asset.get("storage_bucket") or EDOC_STORAGE_BUCKET,
            expected_sha256=digest,
        )
    except ValueError as exc:
        _supabase_editor_asset_failure(asset, str(exc), quarantine=True)
        raise
    if scan_status != "已通過":
        _supabase_editor_asset_failure(asset, "editor_asset_quarantined", quarantine=True)
        raise ValueError("editor_asset_quarantined")
    try:
        inspection = inspect_editor_pdf(data) if asset["asset_kind"] in {"source_pdf", "import_pdf"} else inspect_editor_image(data, asset["mime_type"])
    except Exception:
        _supabase_editor_asset_failure(asset, "editor_asset_preflight_failed", quarantine=True)
        raise
    file_id = f"FILE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    file_row = supabase_insert("file_objects", {
        "id": file_id,
        "document_id": document_id,
        "file_name": asset["file_name"],
        "storage_key": asset["storage_path"],
        "bucket": asset.get("storage_bucket") or EDOC_STORAGE_BUCKET,
        "storage_provider": "supabase",
        "mime_type": asset["mime_type"],
        "size_bytes": len(data),
        "sha256": digest,
        "encrypted_sha256": "",
        "encryption_status": "由物件儲存服務控管",
        "encryption_alg": "",
        "encryption_key_id": "",
        "scan_status": "已通過",
        "scan_engine": EDOC_SCAN_ENGINE,
        "quarantine_reason": "",
        "signed_url_expires_at": "",
        "last_scan_at": now(),
        "last_download_at": "",
        "version_label": f"editor-asset-{asset['asset_kind']}",
        "purpose": "official-editor",
        "created_by": official_actor_name(user),
        "created_at": now(),
    })
    official_file = supabase_insert_official_document_file(document_id, "original_pdf", file_row, official_actor_name(user)) if asset["asset_kind"] == "source_pdf" else None
    update = {
        "file_object_id": file_id,
        "official_file_id": official_file.get("id") if official_file else None,
        "sha256": digest,
        "upload_status": "finalized",
        "scan_status": "passed",
        "preflight_status": "passed",
        "page_count": int((inspection or {}).get("pageCount") or 0),
        "metadata_json": json.dumps({**metadata, "inspection_flags": (inspection or {}).get("flags") or {}, "renderer_version": EDOC_EDITOR_RENDERER_VERSION}, ensure_ascii=False),
        "finalized_at": now(),
    }
    asset = {**asset, **update}
    supabase_patch("official_document_editor_assets", upload_id, update)
    revision = _supabase_insert_editor_revision(document_id, _editor_state_with_asset(latest, asset, inspection), user, latest["id"])
    supabase_patch("official_document_editor_assets", upload_id, {"editor_revision_id": revision["id"]})
    supabase_insert_official_log(document_id, "finalize_editor_upload", user, f"asset_id={upload_id};sha256={digest};pages={update['page_count']};scan=passed")
    public = _editor_revision_public(revision)
    return {"asset": _editor_asset_public({**asset, "editor_revision_id": revision["id"]}), "pages": inspection.get("pages") if inspection else [], "editor_state": public["state"], "editor_revision": public}


def supabase_get_official_editor_state(document_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    _supabase_editor_assert_document_access(document, session, write=False)
    latest = _supabase_editor_latest_revision(document_id)
    if not latest:
        raise ValueError("editor_revision_not_found")
    stamp_request = supabase_official_document_stamp_request(document_id)
    public = _editor_revision_public(latest, str((stamp_request or {}).get("locked_editor_revision_id") or ""))
    if stamp_request and stamp_request.get("locked_editor_revision_id") == latest["id"]:
        public["preparedFileId"] = stamp_request.get("prepared_file_id") or ""
        public["preparedSha256"] = stamp_request.get("prepared_sha256") or ""
    prepared_assets = supabase_filter_rows(
        "official_document_editor_assets",
        {"document_id": document_id, "editor_revision_id": latest["id"], "asset_kind": "prepared_pdf", "upload_status": "finalized", "preflight_status": "passed"},
        order="created_at.desc",
        limit=1,
    )
    if prepared_assets and prepared_assets[0].get("official_file_id"):
        prepared_url = official_editor_file_authorized_url(document_id, prepared_assets[0]["official_file_id"])
        public.update({
            "preparedFileId": prepared_assets[0]["official_file_id"],
            "preparedSha256": prepared_assets[0].get("sha256") or "",
            "preparedUrl": prepared_url,
            "authorizedUrl": prepared_url,
        })
    public["assets"] = editor_asset_access_manifest(document_id, public["state"], supabase_mode=True)
    return public


def supabase_save_official_editor_state(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    user = _supabase_editor_assert_document_access(document, session, write=True)
    latest = _supabase_editor_latest_revision(document_id)
    if not latest:
        raise ValueError("editor_revision_not_found")
    expected_revision = int(pdf_safe_float(payload.get("revisionNo", payload.get("revision_no")), 0))
    expected_manifest = str(payload.get("baseManifestSha256") or payload.get("manifestSha256") or payload.get("manifest_sha256") or "")
    if expected_revision != int(latest["revision_no"]) or expected_manifest != latest["manifest_sha256"]:
        raise ValueError("editor_revision_conflict")
    state = payload.get("state") or payload.get("editor_state") or payload
    if not isinstance(state, dict):
        raise ValueError("editor_state_invalid")
    state = validate_editor_state(json.loads(json.dumps(state, ensure_ascii=False)))
    previous_state = parse_json_any(latest["editor_state_json"], {}) or {}
    validate_supabase_editor_seal_placements(
        str(document.get("company_id") or ""),
        state,
        previous_state=previous_state,
    )
    revision = _supabase_insert_editor_revision(document_id, state, user, latest["id"])
    supabase_insert_official_log(document_id, "save_editor_revision", user, f"revision_id={revision['id']};revision_no={revision['revision_no']};manifest={revision['manifest_sha256']};elements={len((parse_json_any(revision['editor_state_json'], {}) or {}).get('elements') or [])}")
    return _editor_revision_public(revision)


def _supabase_editor_asset_bytes(document_id: str, state: Dict[str, Any]) -> Tuple[Dict[str, bytes], List[Dict[str, Any]]]:
    wanted = {str(item.get("assetId") or "") for item in state.get("sourceFiles") or []}
    for element in state.get("elements") or []:
        props = element.get("properties") or {}
        if element.get("kind") == "image" and (props.get("assetId") or props.get("asset_id")):
            wanted.add(str(props.get("assetId") or props.get("asset_id")))
    result: Dict[str, bytes] = {}
    assets: List[Dict[str, Any]] = []
    for asset_id in wanted:
        rows = supabase_filter_rows("official_document_editor_assets", {"id": asset_id, "document_id": document_id}, limit=1)
        if not rows:
            raise ValueError("editor_source_asset_missing")
        asset = rows[0]
        if asset.get("upload_status") != "finalized" or asset.get("scan_status") != "passed" or asset.get("preflight_status") != "passed":
            raise ValueError("editor_asset_not_ready")
        data = supabase_storage_download(asset["storage_path"], asset.get("storage_bucket") or EDOC_STORAGE_BUCKET)
        if sha256_bytes(data) != asset["sha256"]:
            raise ValueError("editor_asset_hash_mismatch")
        result[asset_id] = data
        assets.append(asset)
    return result, assets


def supabase_preflight_official_editor(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    user = _supabase_editor_assert_document_access(document, session, write=True)
    latest = _supabase_editor_latest_revision(document_id)
    if not latest:
        raise ValueError("editor_revision_not_found")
    revision_id = str(payload.get("editorRevisionId") or payload.get("revision_id") or latest["id"])
    manifest = str(payload.get("manifestSha256") or payload.get("manifest_sha256") or latest["manifest_sha256"])
    if revision_id != latest["id"] or manifest != latest["manifest_sha256"]:
        raise ValueError("editor_revision_conflict")
    state = parse_json_any(latest["editor_state_json"], {}) or {}
    if not state.get("pages"):
        raise ValueError("editor_source_pdf_required")
    supabase_assert_official_document_uploads_av_clean(document)
    state_before_binding = canonical_json_hash(state)
    validate_supabase_editor_seal_placements(
        str(document.get("company_id") or ""),
        state,
        previous_state=state,
    )
    if canonical_json_hash(state) != state_before_binding:
        latest = _supabase_insert_editor_revision(document_id, state, user, latest["id"])
        state = parse_json_any(latest["editor_state_json"], {}) or {}
        revision_id = latest["id"]
        manifest = latest["manifest_sha256"]
        supabase_insert_official_log(
            document_id,
            "bind_editor_seal_versions",
            user,
            f"revision_id={revision_id};manifest={manifest};seal_versions=immutable",
        )
    asset_bytes, assets = _supabase_editor_asset_bytes(document_id, state)
    prepared = render_editor_prepared_pdf(state, asset_bytes)
    prepared_hash = sha256_bytes(prepared)
    prepared_file = supabase_store_official_pdf_file(document_id, "prepared_pdf", f"{document_id}-prepared-r{latest['revision_no']}.pdf", prepared, official_actor_name(user))
    prepared_asset = supabase_insert("official_document_editor_assets", {
        "id": f"ODASSET-{int(time.time() * 1000)}-{secrets.token_hex(4).upper()}",
        "document_id": document_id,
        "editor_revision_id": latest["id"],
        "asset_kind": "prepared_pdf",
        "file_object_id": prepared_file.get("file_object_id"),
        "official_file_id": prepared_file["id"],
        "file_name": prepared_file["file_name"],
        "mime_type": "application/pdf",
        "size_bytes": len(prepared),
        "sha256": prepared_hash,
        "expected_sha256": prepared_hash,
        "storage_bucket": EDOC_STORAGE_BUCKET,
        "storage_path": prepared_file.get("file_storage_key") or "",
        "upload_status": "finalized",
        "scan_status": "passed",
        "preflight_status": "passed",
        "page_count": len(state.get("pages") or []),
        "metadata_json": json.dumps({"source_asset_hashes": sorted(asset["sha256"] for asset in assets), "manifest_sha256": manifest, "element_count": len(state.get("elements") or []), "renderer_version": EDOC_EDITOR_RENDERER_VERSION}, ensure_ascii=False),
        "created_by": user.get("id") or "",
        "created_at": now(),
        "finalized_at": now(),
    })
    supabase_insert_official_log(document_id, "editor_preflight", user, f"revision_id={latest['id']};manifest={manifest};prepared_file_id={prepared_file['id']};prepared_sha256={prepared_hash};pages={prepared_asset['page_count']};elements={len(state.get('elements') or [])};renderer={EDOC_EDITOR_RENDERER_VERSION}", file_id=prepared_file["id"])
    prepared_url = official_editor_file_authorized_url(document_id, prepared_file["id"])
    return {"status": "prepared", "documentId": document_id, "editorRevisionId": latest["id"], "revisionNo": int(latest["revision_no"]), "manifestSha256": manifest, "preparedFileId": prepared_file["id"], "preparedSha256": prepared_hash, "preparedUrl": prepared_url, "authorizedUrl": prepared_url, "rendererVersion": EDOC_EDITOR_RENDERER_VERSION, "pageCount": prepared_asset["page_count"], "revision": _editor_revision_public(latest)}


def supabase_official_editor_change_summary(document_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    _supabase_editor_assert_document_access(document, session, write=False)
    stamp_request = supabase_official_document_stamp_request(document_id)
    locked_id = str((stamp_request or {}).get("locked_editor_revision_id") or "")
    if locked_id:
        rows = supabase_filter_rows("official_document_editor_revisions", {"id": locked_id, "document_id": document_id}, limit=1)
        revision = rows[0] if rows else None
    else:
        revision = _supabase_editor_latest_revision(document_id)
    if not revision:
        raise ValueError("editor_revision_not_found")
    state = parse_json_any(revision["editor_state_json"], {}) or {}
    baseline_state: Dict[str, Any] = {"pages": []}
    for baseline_row in supabase_filter_rows("official_document_editor_revisions", {"document_id": document_id}, order="revision_no.asc", limit=300):
        candidate = parse_json_any(baseline_row.get("editor_state_json"), {}) or {}
        if candidate.get("pages"):
            baseline_state = candidate
            break
    page_operations = editor_page_operations(baseline_state, state)
    counts, by_page = editor_by_page_summary(state, page_operations)
    files = supabase_official_document_files(document_id)
    original = next((item for item in files if item.get("file_type") == "original_pdf"), None)
    prepared = next((item for item in files if item.get("id") == (stamp_request or {}).get("prepared_file_id")), None) or next((item for item in files if item.get("file_type") == "prepared_pdf"), None)
    if original:
        original = {**original, "authorizedUrl": official_editor_file_authorized_url(document_id, original["id"])}
    if prepared:
        prepared_url = official_editor_file_authorized_url(document_id, prepared["id"])
        prepared = {**prepared, "preparedUrl": prepared_url, "authorizedUrl": prepared_url}
    return {"documentId": document_id, "original": original, "prepared": prepared, "revision": _editor_revision_public(revision, locked_id), "changes": {"total": len(state.get("elements") or []), "byKind": counts, "byPage": by_page, "pageOperations": page_operations, "pageOrder": [item.get("pageId") for item in sorted(state.get("pages") or [], key=lambda page: int(page.get("order") or 0))]}}


def supabase_editor_seal_preview(
    seal_id: str,
    session: Dict[str, Any] | None,
    *,
    file_id: str = "",
    file_sha256: str = "",
    document_id: str = "",
    revision_id: str = "",
    binding_requested: bool = False,
) -> bytes:
    user = supabase_official_session_user(session)
    seal = supabase_company_seal_row(seal_id)
    if str(user.get("company_id") or "") != str(seal.get("company_id") or ""):
        raise PermissionError("editor_seal_preview_company_forbidden")
    assert_supabase_seal_access(seal_id, session)
    has_binding_value = any((file_id, file_sha256, document_id, revision_id))
    if binding_requested or has_binding_value:
        if not file_id or not file_sha256:
            raise PermissionError("editor_seal_preview_binding_required")
        has_revision_value = bool(document_id or revision_id)
        if has_revision_value and not all((document_id, revision_id)):
            raise PermissionError("editor_seal_preview_binding_required")
        if has_revision_value:
            document = supabase_official_document_row(document_id)
            _supabase_editor_assert_document_access(document, session, write=False)
            revisions = supabase_filter_rows(
                "official_document_editor_revisions",
                {"id": revision_id, "document_id": document_id},
                limit=1,
            )
            if not revisions:
                raise PermissionError("editor_seal_preview_revision_forbidden")
            state = parse_json_any(revisions[0].get("editor_state_json"), {}) or {}
            if not editor_state_references_seal_file(state, seal_id, file_id, file_sha256):
                raise PermissionError("editor_seal_preview_binding_forbidden")
            seal_file = supabase_official_seal_file_by_id(file_id, seal_id)
        else:
            seal_file = supabase_require_current_company_seal_file(seal_id)
            if str(seal_file.get("id") or "") != file_id:
                raise PermissionError("editor_seal_preview_revision_required")
        if str(seal_file.get("file_hash") or "") != file_sha256:
            raise ValueError("editor_seal_file_hash_mismatch")
    else:
        seal_file = supabase_require_current_company_seal_file(seal_id)
    objects = supabase_filter_rows("file_objects", {"id": seal_file.get("file_object_id")}, limit=1)
    if not objects:
        raise ValueError("seal_file_object_required")
    data = supabase_storage_download(objects[0]["storage_key"], objects[0].get("bucket") or EDOC_SEAL_STORAGE_BUCKET)
    if sha256_bytes(data) != seal_file["file_hash"]:
        raise ValueError("seal_file_hash_mismatch")
    supabase_log_seal_usage(action="editor_seal_preview", actor_id=user.get("id") or "", seal_id=seal_id, detail=f"seal_file_id={seal_file['id']};ttl={EDOC_EDITOR_PREVIEW_TTL_SECONDS};watermarked=true")
    return generate_editor_seal_preview(data, seal_file.get("file_mime_type") or "image/png")


def supabase_editor_asset_download(document_id: str, asset_id: str, expires: int, token: str, session: Dict[str, Any] | None) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    _validate_editor_asset_access_token(document_id, asset_id, expires, token)
    document = supabase_official_document_row(document_id)
    user = _supabase_editor_assert_document_access(document, session, write=False)
    rows = supabase_filter_rows("official_document_editor_assets", {"id": asset_id, "document_id": document_id, "upload_status": "finalized", "scan_status": "passed"}, limit=1)
    if not rows:
        raise ValueError("editor_asset_not_found")
    asset = rows[0]
    if asset.get("asset_kind") == "prepared_pdf":
        raise PermissionError("editor_asset_download_forbidden")
    file_object_id = str(asset.get("file_object_id") or "")
    file_object = supabase_get("file_objects", file_object_id) if file_object_id else None
    if not file_object:
        raise ValueError("editor_asset_file_object_missing")
    if not file_object_av_is_clean(file_object):
        raise ValueError("editor_asset_antivirus_required")
    try:
        verify_private_storage_file_metadata(
            asset,
            file_object,
            expected_document_id=document_id,
            expected_storage_key=str(asset.get("storage_path") or ""),
            expected_bucket=str(asset.get("storage_bucket") or EDOC_STORAGE_BUCKET),
        )
    except ValueError as exc:
        raise ValueError("editor_asset_hash_mismatch") from exc
    signed = supabase_storage_create_signed_download_url(
        file_object["storage_key"],
        file_object.get("bucket") or EDOC_STORAGE_BUCKET,
        file_name=asset.get("file_name") or asset_id,
        download=False,
        ttl_seconds=min(EDOC_SIGNED_URL_TTL_SECONDS, max(1, expires - int(time.time()))),
    )
    supabase_insert_official_log(document_id, "editor_asset_download", user, f"asset_id={asset_id};sha256={asset['sha256']};expires={expires}")
    return asset, signed


def _supabase_editor_source_bundle_sha256(document_id: str, state: Dict[str, Any]) -> str:
    hashes: List[Dict[str, str]] = []
    for item in state.get("sourceFiles") or []:
        asset_id = str(item.get("assetId") or "")
        rows = supabase_filter_rows("official_document_editor_assets", {"id": asset_id, "document_id": document_id, "upload_status": "finalized"}, limit=1)
        if not rows or not rows[0].get("sha256"):
            raise ValueError("editor_source_asset_missing")
        hashes.append({"assetId": asset_id, "sha256": str(rows[0]["sha256"])})
    return sha256_bytes(json.dumps(sorted(hashes, key=lambda item: item["assetId"]), sort_keys=True, separators=(",", ":")).encode("utf-8"))


def supabase_lock_official_editor_submission(document: Dict[str, Any], payload: Dict[str, Any], user: Dict[str, Any]) -> Dict[str, Any]:
    metadata = parse_json_field(document.get("metadata_json"))
    if not metadata.get("pdf_editor_v2"):
        return {}
    revision_id = str(payload.get("editorRevisionId") or "")
    manifest = str(payload.get("manifestSha256") or "")
    prepared_file_id = str(payload.get("preparedFileId") or "")
    prepared_sha256 = str(payload.get("preparedSha256") or "")
    if not all((revision_id, manifest, prepared_file_id, prepared_sha256)):
        raise ValueError("editor_preflight_fields_required")
    latest = _supabase_editor_latest_revision(document["id"])
    if not latest or latest["id"] != revision_id or latest["manifest_sha256"] != manifest:
        raise ValueError("editor_revision_conflict")
    prepared_rows = supabase_filter_rows("official_document_files", {"id": prepared_file_id, "document_id": document["id"], "file_type": "prepared_pdf"}, limit=1)
    if not prepared_rows:
        raise ValueError("editor_prepared_file_not_found")
    prepared_file = prepared_rows[0]
    if prepared_file.get("file_hash") != prepared_sha256 or not prepared_file.get("file_object_id"):
        raise ValueError("editor_prepared_hash_mismatch")
    objects = supabase_filter_rows("file_objects", {"id": prepared_file["file_object_id"]}, limit=1)
    if not objects:
        raise ValueError("editor_prepared_file_not_found")
    prepared_bytes = supabase_storage_download(objects[0]["storage_key"], objects[0].get("bucket") or EDOC_STORAGE_BUCKET)
    if sha256_bytes(prepared_bytes) != prepared_sha256:
        raise ValueError("editor_prepared_hash_mismatch")
    preflight_assets = supabase_filter_rows("official_document_editor_assets", {"document_id": document["id"], "editor_revision_id": revision_id, "asset_kind": "prepared_pdf", "official_file_id": prepared_file_id, "sha256": prepared_sha256, "preflight_status": "passed"}, limit=1)
    if not preflight_assets:
        raise ValueError("editor_preflight_not_completed")
    state = parse_json_any(latest["editor_state_json"], {}) or {}
    validate_supabase_editor_seal_placements(
        str(document.get("company_id") or ""),
        state,
        bind_missing=False,
        previous_state=state,
    )
    source_hash = _supabase_editor_source_bundle_sha256(document["id"], state)
    ordered_pages = sorted(state.get("pages") or [], key=lambda item: int(item.get("order") or 0))
    page_numbers = {str(item.get("pageId") or ""): index for index, item in enumerate(ordered_pages, start=1)}
    positions: List[Dict[str, Any]] = []
    seal_elements = sorted([item for item in state.get("elements") or [] if item.get("kind") == "seal"], key=lambda item: int(item.get("zIndex") or 0))
    for index, element in enumerate(seal_elements, start=1):
        props = element.get("properties") or {}
        seal_id = str(props.get("sealId") or props.get("seal_id") or element.get("sealId") or "")
        if not seal_id:
            raise ValueError("editor_seal_id_required")
        seal, seal_file, profile = supabase_editor_seal_file_context(
            str(document.get("company_id") or ""),
            element,
            bind_missing=False,
            require_current_selection=False,
        )
        width, height = canonical_company_seal_dimensions_pt(
            seal.get("seal_size_type"), element.get("width"), element.get("height"),
            render_width_mm=profile["width_mm"],
            render_height_mm=profile["height_mm"],
        )
        positions.append({"seal_id": seal_id, "page": page_numbers.get(str(element.get("pageId") or ""), 0), "page_ref": str(element.get("pageId") or ""), "x": element.get("x"), "y": element.get("y"), "width": width, "height": height, "rotation": element.get("rotation") or 0, "opacity": element.get("opacity") if element.get("opacity") is not None else 1, "z_index": element.get("zIndex") or index, "locked_seal_file_id": seal_file["id"], "locked_seal_sha256": seal_file["file_hash"], "locked_render_width_pt": profile["width_pt"], "locked_render_height_pt": profile["height_pt"], "locked_dimension_policy_version": profile["dimension_policy_version"], "order_index": index})
    if bool(document.get("requires_stamp", True)) and not positions:
        raise ValueError("editor_seal_position_required")
    first = positions[0] if positions else {"seal_id": "", "page": 1, "x": 0, "y": 0, "width": 1, "height": 1}
    timestamp = now()
    request = supabase_official_document_stamp_request(document["id"])
    lock_fields = {"seal_id": first["seal_id"], "stamp_page": first["page"], "stamp_x": first["x"], "stamp_y": first["y"], "stamp_width": first["width"], "stamp_height": first["height"], "locked_editor_revision_id": revision_id, "locked_source_sha256": source_hash, "prepared_file_id": prepared_file_id, "prepared_sha256": prepared_sha256, "editor_manifest_sha256": manifest, "editor_schema_version": EDOC_EDITOR_SCHEMA_VERSION, "renderer_version": EDOC_EDITOR_RENDERER_VERSION, "editor_locked_at": timestamp, "status": "pending", "error_message": "", "updated_at": timestamp}
    if request:
        supabase_patch("official_document_stamp_requests", request["id"], lock_fields)
        request_id = request["id"]
    else:
        request_id = f"ODSTAMP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
        supabase_insert("official_document_stamp_requests", {"id": request_id, "document_id": document["id"], "company_id": document["company_id"], "requested_by": user.get("id") or "", "stamped_file_id": None, "stamped_at": "", "created_at": timestamp, **lock_fields})
    supabase_replace_official_stamp_positions(
        request_id,
        first["seal_id"],
        {"stamp_positions": positions},
        allow_persisted_bindings=True,
    )
    supabase_insert_official_log(document["id"], "lock_editor_revision", user, f"revision_id={revision_id};manifest={manifest};source_sha256={source_hash};prepared_file_id={prepared_file_id};prepared_sha256={prepared_sha256};seal_positions={len(positions)};renderer={EDOC_EDITOR_RENDERER_VERSION}", file_id=prepared_file_id)
    return {"revision_id": revision_id, "manifest_sha256": manifest, "source_sha256": source_hash, "prepared_file_id": prepared_file_id, "prepared_sha256": prepared_sha256, "seal_positions": len(positions)}


def supabase_clone_official_editor_revision_after_reject(document_id: str, actor: Dict[str, Any]) -> Dict[str, Any] | None:
    jobs = supabase_filter_rows(
        "official_document_rejection_jobs",
        {"document_id": document_id},
        order="created_at.desc",
        limit=20,
    )
    job = next((item for item in jobs if item.get("status") in {"pending", "failed", "completed"}), None)
    if job and job.get("status") == "completed" and job.get("target_revision_id"):
        completed = supabase_filter_rows(
            "official_document_editor_revisions",
            {"id": job["target_revision_id"], "document_id": document_id},
            limit=1,
        )
        if not completed:
            raise ValueError("editor_rejection_clone_completion_invalid")
        return _editor_revision_public(completed[0])

    request = supabase_official_document_stamp_request(document_id)
    revision_id = str((job or {}).get("source_revision_id") or (request or {}).get("locked_editor_revision_id") or "")
    if not revision_id:
        return None
    rows = supabase_filter_rows("official_document_editor_revisions", {"id": revision_id, "document_id": document_id}, limit=1)
    if not rows:
        raise ValueError("editor_locked_revision_missing")
    source = rows[0]
    existing = supabase_filter_rows(
        "official_document_editor_revisions",
        {"document_id": document_id, "parent_revision_id": source["id"]},
        order="revision_no.desc",
        limit=1,
    )
    try:
        clone = existing[0] if existing else _supabase_insert_editor_revision(
            document_id,
            parse_json_any(source["editor_state_json"], {}) or {},
            actor,
            source["id"],
        )
    except Exception:
        # A concurrent retry may have won the unique parent-revision insert.
        existing = supabase_filter_rows(
            "official_document_editor_revisions",
            {"document_id": document_id, "parent_revision_id": source["id"]},
            order="revision_no.desc",
            limit=1,
        )
        if not existing:
            if job:
                supabase_patch("official_document_rejection_jobs", job["id"], {
                    "status": "failed",
                    "attempt_count": int(job.get("attempt_count") or 0) + 1,
                    "last_error_code": "editor_rejection_clone_failed",
                })
            raise
        clone = existing[0]
    if job:
        supabase_patch("official_document_rejection_jobs", job["id"], {
            "status": "completed",
            "target_revision_id": clone["id"],
            "attempt_count": int(job.get("attempt_count") or 0) + 1,
            "last_error_code": None,
            "completed_at": now(),
        })
    return _editor_revision_public(clone)


def supabase_verify_locked_editor_for_stamp(document: Dict[str, Any], request: Dict[str, Any]) -> Dict[str, Any] | None:
    revision_id = str(request.get("locked_editor_revision_id") or "")
    if not revision_id:
        return None
    revisions = supabase_filter_rows("official_document_editor_revisions", {"id": revision_id, "document_id": document["id"]}, limit=1)
    if not revisions:
        raise ValueError("editor_locked_revision_missing")
    revision = revisions[0]
    state = parse_json_any(revision["editor_state_json"], {}) or {}
    if canonical_editor_manifest(state) != revision["manifest_sha256"] or revision["manifest_sha256"] != request.get("editor_manifest_sha256"):
        raise ValueError("editor_manifest_hash_mismatch")
    if _supabase_editor_source_bundle_sha256(document["id"], state) != request.get("locked_source_sha256"):
        raise ValueError("editor_source_hash_mismatch")
    prepared_rows = supabase_filter_rows("official_document_files", {"id": request.get("prepared_file_id") or "", "document_id": document["id"], "file_type": "prepared_pdf"}, limit=1)
    if not prepared_rows:
        raise ValueError("editor_prepared_file_missing")
    prepared_file = prepared_rows[0]
    objects = supabase_filter_rows("file_objects", {"id": prepared_file.get("file_object_id") or ""}, limit=1)
    if prepared_file.get("file_hash") != request.get("prepared_sha256") or not objects:
        raise ValueError("editor_prepared_hash_mismatch")
    prepared_bytes = supabase_storage_download(objects[0]["storage_key"], objects[0].get("bucket") or EDOC_STORAGE_BUCKET)
    if sha256_bytes(prepared_bytes) != request.get("prepared_sha256"):
        raise ValueError("editor_prepared_hash_mismatch")
    positions = request.get("stamp_positions") or []
    seal_assets: Dict[str, Dict[str, Any]] = {}
    for position in positions:
        seal_file_id = str(position.get("locked_seal_file_id") or "")
        locked_hash = str(position.get("locked_seal_sha256") or "")
        files = supabase_filter_rows("company_seal_files", {"id": seal_file_id, "seal_id": position.get("seal_id") or ""}, limit=1)
        if not files or not locked_hash:
            raise ValueError("editor_locked_seal_version_missing")
        seal_file = supabase_require_seal_file_av_clean(files[0])
        seal = supabase_get("company_seals", position.get("seal_id") or "")
        if not seal:
            raise ValueError("seal_not_found")
        validate_locked_company_seal_position(position, seal.get("seal_size_type"), seal_file)
        objects = supabase_filter_rows("file_objects", {"id": seal_file.get("file_object_id") or ""}, limit=1)
        if seal_file.get("file_hash") != locked_hash or not objects:
            raise ValueError("editor_seal_hash_mismatch")
        data = supabase_storage_download(objects[0]["storage_key"], objects[0].get("bucket") or EDOC_SEAL_STORAGE_BUCKET)
        if sha256_bytes(data) != locked_hash:
            raise ValueError("editor_seal_hash_mismatch")
        seal_assets[seal_file_id] = {"data": data, "mime_type": seal_file.get("file_mime_type") or "", "sha256": locked_hash}
    return {
        "revision": revision,
        "state": state,
        "prepared_file": prepared_file,
        "prepared_bytes": prepared_bytes,
        "positions": positions,
        "seal_assets": seal_assets,
        "renderer_version": str(request.get("renderer_version") or ""),
    }


def supabase_create_official_document(payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    if not session_has_any_permission(session, ["official_documents.compose", "official_documents.all_todo"]):
        raise PermissionError("official_document_create_forbidden")
    source_type = payload.get("source_type") or "blank_editor"
    if source_type not in {"blank_editor", "uploaded_pdf"}:
        raise ValueError("invalid_official_document_source_type")
    original_pdf_data = validated_uploaded_official_pdf(payload) if source_type == "uploaded_pdf" else b""
    company_id = require_official_creation_company(user, payload.get("company_id") or user.get("company_id"))
    if not launch_company_in_scope(company_id):
        raise PermissionError("company_not_in_launch_scope")
    company = supabase_official_company_row(company_id)
    dispatch_method = official_document_dispatch_method(source_type, payload.get("dispatch_method"))
    document_id = payload.get("id") or f"OD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    ts = now()
    extra_metadata = dict(payload.get("metadata")) if isinstance(payload.get("metadata"), dict) else {}
    extra_metadata.setdefault("contact_owner", payload.get("handler_name") or user.get("name") or "")
    extra_metadata.setdefault("contact_email", user.get("email") or "")
    extra_metadata.setdefault("contact_address", user.get("company_address") or company.get("address") or "")
    extra_metadata["contact_fax"] = str(
        extra_metadata.get("contact_fax") or payload.get("contact_fax") or payload.get("contactFax") or EDOC_DEFAULT_CONTACT_FAX
    ).strip()[:120] or EDOC_DEFAULT_CONTACT_FAX
    extra_metadata["copy_recipients"] = official_pdf_copy_recipients(
        extra_metadata.get("copy_recipients")
        or extra_metadata.get("copyRecipients")
        or payload.get("copy_recipients")
        or payload.get("copyRecipients"),
        company.get("name") or "",
    )[:OFFICIAL_COPY_RECIPIENTS_MAX_LENGTH]
    requires_stamp = True
    seal_context = require_official_seal_classification(payload)
    workflow_template_key = (seal_context or {}).get("workflow_template_key") or payload.get("workflow_template_key") or "internal_official_dispatch_v1"
    metadata = {
        "attachments": payload.get("attachments_summary") or payload.get("attachments") or "",
        "workflow_template": workflow_template_key,
        "future_rule_inputs": {
            "company_id": company_id,
            "department": user.get("unit"),
            "document_type": payload.get("document_type"),
            "seal_id": payload.get("seal_id"),
            "dispatch_method": dispatch_method,
            "amount": payload.get("amount"),
            "document_category": (seal_context or {}).get("document_category") or "",
            "approval_route_code": (seal_context or {}).get("approval_route_code") or "",
        },
    }
    if seal_context:
        metadata["official_seal"] = {
            **seal_context,
            "approval_steps": [
                {"order": step["order"], "key": step["key"], "name": step["name"], "role": step["role"]}
                for step in official_seal_workflow_steps(seal_context["approval_route_code"])
                if step["key"] != "applicant_confirm"
            ],
        }
    if extra_metadata:
        metadata["extra"] = extra_metadata
        if extra_metadata.get("journey"):
            metadata["launch_smoke_journey"] = extra_metadata.get("journey")
        if extra_metadata.get("source"):
            metadata["source"] = extra_metadata.get("source")
    seal_id = payload.get("seal_id")
    submit_requested = bool(payload.get("submit", True))
    if seal_id and requires_stamp:
        supabase_validate_official_document_seal(seal_id, company_id, require_current=submit_requested)
    document = supabase_insert("official_documents", {
        "id": document_id,
        "company_id": company_id,
        "document_type": payload.get("document_type") or ("uploaded_pdf_for_stamp" if source_type == "uploaded_pdf" else "outgoing_official_document"),
        "source_type": source_type,
        "title": payload.get("title") or payload.get("subject") or "未命名發文申請",
        "subject": payload.get("subject") or payload.get("title") or "",
        "description": payload.get("description") or payload.get("body") or "",
        "method": payload.get("method") or payload.get("辦法") or "",
        "recipient": payload.get("recipient") or payload.get("agency_name") or "",
        "dispatch_unit": payload.get("dispatch_unit") or user.get("unit") or "",
        "handler_name": payload.get("handler_name") or user.get("name") or "",
        "applicant_id": user["id"],
        "applicant_name": user.get("name") or user.get("email"),
        "applicant_department_id": payload.get("applicant_department_id") or user.get("unit") or "",
        "applicant_department_name": payload.get("applicant_department_name") or user.get("unit") or "",
        "workflow_template_key": workflow_template_key,
        "dispatch_method": dispatch_method,
        "requires_stamp": requires_stamp,
        "current_status": "draft",
        "current_step": "",
        "request_reason": payload.get("request_reason") or payload.get("reason") or "",
        "stamped_file_id": None,
        "metadata_json": metadata,
        "created_at": ts,
        "updated_at": ts,
    })
    if source_type == "uploaded_pdf":
        file_row = supabase_store_official_pdf_file(document_id, "original_pdf", Path(payload.get("file_name") or f"{document_id}.pdf").name, original_pdf_data, official_actor_name(user))
        supabase_insert_official_log(document_id, "upload_original_pdf", user, file_row["file_hash"], file_id=file_row["id"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    else:
        supabase_ensure_official_generated_pdf(document, official_actor_name(user))
    if seal_id and requires_stamp:
        position = official_stamp_position_payload(payload)
        stamp_request = supabase_insert("official_document_stamp_requests", {
            "id": f"ODSTAMP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "document_id": document_id,
            "company_id": company_id,
            "seal_id": seal_id,
            "requested_by": user["id"],
            **position,
            "status": "pending" if submit_requested else "draft",
            "stamped_file_id": None,
            "error_message": "",
            "created_at": ts,
            "stamped_at": "",
            "updated_at": ts,
        })
        created_positions = supabase_replace_official_stamp_positions(
            stamp_request["id"],
            seal_id,
            payload,
            allow_unbound_current=not submit_requested,
        )
        first_position = created_positions[0]
        supabase_patch("official_document_stamp_requests", stamp_request["id"], {
            "seal_id": first_position["seal_id"],
            "stamp_page": first_position["page"],
            "stamp_x": first_position["x"],
            "stamp_y": first_position["y"],
            "stamp_width": first_position["width"],
            "stamp_height": first_position["height"],
            "updated_at": now(),
        })
        supabase_replace_official_text_overlays(stamp_request["id"], payload)
    supabase_insert_official_log(document_id, "create", user, document["request_reason"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    if payload.get("submit", True):
        return supabase_submit_official_document(document_id, payload, session)
    return supabase_official_document_detail(document_id, session)


def _supabase_cleanup_uncommitted_correction_file(
    document_id: str,
    file_object: Dict[str, Any] | None,
) -> None:
    """Remove an uploaded correction object only after non-commit is proven."""
    if not file_object:
        return
    try:
        supabase_storage_delete(
            file_object.get("storage_key") or "",
            file_object.get("bucket") or EDOC_STORAGE_BUCKET,
        )
    except Exception as cleanup_error:
        log_structured(
            "error",
            "official_correction_storage_rollback_failed",
            document_id=document_id,
            file_object_id=file_object.get("id") or "",
            error=redact_text(str(cleanup_error)),
        )
    try:
        supabase_request(
            "DELETE",
            "file_objects?" + urllib.parse.urlencode({"id": "eq." + str(file_object["id"])}),
        )
    except Exception as cleanup_error:
        log_structured(
            "error",
            "official_correction_metadata_rollback_failed",
            document_id=document_id,
            file_object_id=file_object.get("id") or "",
            error=redact_text(str(cleanup_error)),
        )


def _supabase_official_correction_commit_state(
    document_id: str,
    applicant_id: str,
    log_id: str,
    expected_request_id: str,
    new_request_witness_id: str,
    official_file_id: str,
    file_object_id: str,
) -> str:
    """Reconcile a possibly lost PostgREST response using caller-owned IDs.

    ``committed`` and ``not_committed`` are returned only when every relevant
    witness query succeeds.  Any partial or contradictory state is ``unknown``
    so private storage is retained for operator reconciliation.
    """
    try:
        logs = supabase_filter_rows(
            "official_document_approval_logs",
            {"id": log_id, "document_id": document_id, "action": "correct"},
            limit=2,
        )
        official_files = (
            supabase_filter_rows(
                "official_document_files",
                {"id": official_file_id, "document_id": document_id},
                limit=2,
            )
            if official_file_id
            else []
        )
        object_references = (
            supabase_filter_rows(
                "official_document_files",
                {"file_object_id": file_object_id},
                limit=2,
            )
            if file_object_id
            else []
        )
        expected_requests = (
            supabase_filter_rows(
                "official_document_stamp_requests",
                {"id": expected_request_id, "document_id": document_id},
                limit=2,
            )
            if expected_request_id
            else []
        )
        new_request_witnesses = (
            supabase_filter_rows(
                "official_document_stamp_requests",
                {"id": new_request_witness_id, "document_id": document_id},
                limit=2,
            )
            if new_request_witness_id
            else []
        )
    except Exception:
        return "unknown"

    if (
        len(logs) > 1
        or len(official_files) > 1
        or len(object_references) > 1
        or len(expected_requests) > 1
        or len(new_request_witnesses) > 1
    ):
        return "unknown"
    if logs:
        if str(logs[0].get("actor_id") or "") != applicant_id:
            return "unknown"
        if official_file_id:
            if not official_files or str(official_files[0].get("file_object_id") or "") != file_object_id:
                return "unknown"
            if not object_references or str(object_references[0].get("id") or "") != official_file_id:
                return "unknown"
        elif official_files or object_references:
            return "unknown"
        if expected_request_id and not expected_requests:
            return "unknown"
        return "committed"

    # The RPC writes its log in the same transaction as every other mutation.
    # A caller-generated file/request witness without that log is therefore a
    # contradictory state that must never trigger destructive compensation.
    if official_files or object_references or new_request_witnesses:
        return "unknown"
    return "not_committed"


def supabase_update_official_document_correction(
    document_id: str,
    payload: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document.get("applicant_id") != user.get("id"):
        raise PermissionError("only_applicant_can_correct")
    if document.get("current_status") not in {"draft", "rejected"}:
        raise ValueError("official_document_correction_locked")
    require_official_creation_company(user, document.get("company_id"))
    stamp_request = supabase_official_document_stamp_request(document_id)
    source_pages: List[Dict[str, Any]] = []
    if not OFFICIAL_CORRECTION_FILE_FIELDS.intersection(payload):
        source_meta = supabase_official_latest_source_file(document)
        if not source_meta.get("file_object_id"):
            raise ValueError("official_document_file_object_missing")
        source_object = supabase_get("file_objects", source_meta["file_object_id"])
        if not source_object:
            raise ValueError("official_document_file_object_missing")
        source_bytes = supabase_storage_download(
            source_object.get("storage_key") or "",
            source_object.get("bucket") or EDOC_STORAGE_BUCKET,
        )
        verify_official_file_bytes(source_meta, source_object, source_bytes)
        source_pages = list(inspect_editor_pdf(source_bytes).get("pages") or [])
    plan = _official_correction_plan(
        document,
        payload,
        stamp_request,
        source_pages,
        supabase_company_seal_row,
        supabase_official_seal_file_by_id,
    )
    for seal_id in sorted({str(item.get("seal_id") or plan["seal_id"]) for item in plan["positions"]}):
        if not seal_id:
            continue
        supabase_validate_official_document_seal(
            seal_id,
            str(document.get("company_id") or ""),
            require_current=False,
        )

    changed_fields = [
        key
        for key in OFFICIAL_CORRECTION_EDITABLE_FIELDS
        if key in plan["updates"] and str(document.get(key) or "") != str(plan["updates"][key] or "")
    ]
    changed_fields.extend(plan["render_metadata_changes"])
    document_body_changed = bool(changed_fields)
    previous_context = official_seal_context_from_document(document) or {}
    if previous_context.get("document_category") != plan["seal_context"]["document_category"]:
        changed_fields.append("document_category")
    if str((stamp_request or {}).get("seal_id") or "") != plan["seal_id"]:
        changed_fields.append("seal_id")
    previous_positions = (stamp_request or {}).get("stamp_positions") or []
    comparable_keys = OFFICIAL_STAMP_POSITION_COMPARABLE_FIELDS
    if canonical_json_hash([
        {key: item.get(key) for key in comparable_keys} for item in previous_positions
    ]) != canonical_json_hash([
        {key: item.get(key) for key in comparable_keys} for item in plan["positions"]
    ]):
        changed_fields.append("stamp_positions")

    source_bytes = None
    source_file_type = ""
    source_file_name = ""
    if plan["new_pdf"] is not None:
        latest_original = supabase_official_raw_document_files(document_id, "original_pdf")
        if not latest_original or str(latest_original[0].get("file_hash") or "") != sha256_bytes(plan["new_pdf"]):
            source_bytes = plan["new_pdf"]
            source_file_type = "original_pdf"
            source_file_name = plan["file_name"]
            changed_fields.append("original_pdf")
    elif document.get("source_type") == "blank_editor" and document_body_changed:
        future_document = {**document, **plan["updates"]}
        package = build_official_pdf_package(
            supabase_official_pdf_document_payload(future_document),
            [],
            "歲悅正式函",
            1,
        )
        source_bytes = package["data"]
        source_file_type = "generated_pdf"
        source_file_name = f"{document_id}-generated-correction.pdf"
        changed_fields.append("generated_pdf")

    file_object: Dict[str, Any] | None = None
    if source_bytes is not None:
        scan_result = (
            scan_official_upload_bytes(source_bytes, source_file_name)
            if source_file_type == "original_pdf"
            else None
        )
        file_object = supabase_store_file_object(
            document_id,
            source_file_name,
            source_bytes,
            "official-documents",
            f"{source_file_type}-correction",
            official_actor_name(user),
            "application/pdf",
        )
        try:
            if scan_result:
                file_object = supabase_persist_file_object_scan_result(
                    file_object["id"],
                    scan_result[0],
                    scan_result[1],
                    official_actor_name(user),
                )
        except Exception:
            try:
                supabase_storage_delete(
                    file_object.get("storage_key") or "",
                    file_object.get("bucket") or EDOC_STORAGE_BUCKET,
                )
            finally:
                supabase_request(
                    "DELETE",
                    "file_objects?" + urllib.parse.urlencode({"id": "eq." + str(file_object["id"])}),
                )
            raise

    stamp_request_id = f"ODSTAMP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    official_file_id = f"ODFILE-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}" if file_object else ""
    existing_position_ids = {
        str(item.get("id") or "")
        for item in (stamp_request or {}).get("stamp_positions") or []
    }
    reuse_existing_position_ids = bool(
        stamp_request and document.get("current_status") != "rejected"
    )
    position_ids = [
        (
            str(position.get("id") or "")
            if reuse_existing_position_ids
            and str(position.get("id") or "") in existing_position_ids
            else f"ODPOS-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
        )
        for position in plan["positions"]
    ]
    overlay_ids = [
        f"ODTEXT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
        for _ in plan["text_overlays"]
    ]
    expected_request_id = (
        stamp_request_id
        if plan["positions"] and (document.get("current_status") == "rejected" or not stamp_request)
        else str((stamp_request or {}).get("id") or "")
    )
    new_request_witness_id = (
        stamp_request_id
        if plan["positions"] and (document.get("current_status") == "rejected" or not stamp_request)
        else ""
    )
    log_id = f"ODLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    audit_id = f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    expected = {
        "document_id": document_id,
        "stamp_request_id": expected_request_id,
        "official_file_id": official_file_id,
    }
    try:
        raw = supabase_request("POST", "rpc/edoc_apply_official_document_correction", {
            "p_document_id": document_id,
            "p_applicant_id": user["id"],
            "p_company_id": document["company_id"],
            "p_patch": plan["updates"],
            "p_seal_id": plan["seal_id"],
            "p_stamp_positions": plan["positions"],
            "p_text_overlays": plan["text_overlays"],
            "p_stamp_request_id": stamp_request_id,
            "p_position_ids": position_ids,
            "p_overlay_ids": overlay_ids,
            "p_source_file_object_id": (file_object or {}).get("id") or "",
            "p_official_file_id": official_file_id,
            "p_source_file_type": source_file_type,
            "p_actor_name": official_actor_name(user),
            "p_log_id": log_id,
            "p_audit_id": audit_id,
            "p_updated_fields": sorted(set(changed_fields)),
            "p_ip_address": str(payload.get("ip_address") or "")[:120],
            "p_user_agent": str(payload.get("user_agent") or "")[:180],
        })
        if isinstance(raw, list):
            row = raw[0] if len(raw) == 1 and isinstance(raw[0], dict) else {}
        else:
            row = raw if isinstance(raw, dict) else {}
        if any(str(row.get(key) or "") != str(value or "") for key, value in expected.items()):
            raise RuntimeError("official_document_correction_invalid_response")
    except Exception as rpc_error:
        state = _supabase_official_correction_commit_state(
            document_id,
            user["id"],
            log_id,
            expected_request_id,
            new_request_witness_id,
            official_file_id,
            str((file_object or {}).get("id") or ""),
        )
        if state == "committed":
            try:
                return supabase_official_document_detail(document_id, session)
            except Exception as detail_error:
                raise RuntimeError("official_document_correction_commit_state_unknown") from detail_error
        if state == "not_committed":
            _supabase_cleanup_uncommitted_correction_file(document_id, file_object)
            raise
        log_structured(
            "error",
            "official_correction_commit_state_unknown",
            document_id=document_id,
            log_id=log_id,
            official_file_id=official_file_id,
            error=redact_text(str(rpc_error)),
        )
        raise RuntimeError("official_document_correction_commit_state_unknown") from rpc_error
    return supabase_official_document_detail(document_id, session)


def _supabase_official_resubmit_operation_ids(
    document_id: str,
    applicant_id: str,
    correction_requested_at: str,
) -> Tuple[str, str]:
    digest = hashlib.sha256(
        f"{document_id}\n{applicant_id}\n{correction_requested_at}".encode("utf-8")
    ).hexdigest().upper()
    return f"ODRS-{digest[:32]}", f"AUDRS-{digest[:32]}"


def _supabase_official_resubmit_finalize_state(
    document_id: str,
    applicant_id: str,
    correction_requested_at: str,
    log_id: str,
) -> str:
    try:
        document = supabase_official_document_row(document_id)
        logs = supabase_filter_rows(
            "official_document_approval_logs",
            {"id": log_id, "document_id": document_id, "action": "resubmit"},
            limit=2,
        )
    except Exception:
        return "unknown"
    if str(document.get("applicant_id") or "") != applicant_id:
        return "unknown"
    if str(document.get("correction_requested_at") or "") != correction_requested_at:
        return "unknown"
    missing_items = parse_json_any(document.get("correction_missing_items_json"), [])
    fields_cleared = (
        bool(document.get("correction_resubmitted_at"))
        and document.get("correction_reason_category") in (None, "")
        and missing_items in (None, [], {})
        and document.get("correction_due_at") in (None, "")
    )
    valid_log = bool(
        len(logs) == 1
        and str(logs[0].get("actor_id") or "") == applicant_id
    )
    if fields_cleared and valid_log:
        return "committed"
    if not fields_cleared and not logs:
        return "not_committed"
    return "unknown"


def _supabase_finalize_official_document_resubmit(
    document: Dict[str, Any],
    user: Dict[str, Any],
    payload: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    document_id = str(document["id"])
    requested_at = str(document.get("correction_requested_at") or "")
    if not requested_at:
        raise ValueError("official_document_resubmit_generation_missing")
    log_id, audit_id = _supabase_official_resubmit_operation_ids(document_id, user["id"], requested_at)
    try:
        raw = supabase_request("POST", "rpc/edoc_finalize_official_document_resubmit", {
            "p_document_id": document_id,
            "p_applicant_id": user["id"],
            "p_company_id": document["company_id"],
            "p_expected_correction_requested_at": requested_at,
            "p_log_id": log_id,
            "p_audit_id": audit_id,
            "p_comment": str(payload.get("comment") or "補正完成，重新由第一關送簽")[:2000],
            "p_ip_address": str(payload.get("ip_address") or "")[:120],
            "p_user_agent": str(payload.get("user_agent") or "")[:180],
        })
        row = raw[0] if isinstance(raw, list) and len(raw) == 1 and isinstance(raw[0], dict) else raw
        if not isinstance(row, dict) or str(row.get("document_id") or "") != document_id or str(row.get("log_id") or "") != log_id or row.get("finalized") is not True:
            raise RuntimeError("official_document_resubmit_finalize_invalid_response")
    except Exception as finalize_error:
        state = _supabase_official_resubmit_finalize_state(
            document_id,
            user["id"],
            requested_at,
            log_id,
        )
        if state == "committed":
            return supabase_official_document_detail(document_id, session)
        if state == "unknown":
            raise RuntimeError("official_document_resubmit_commit_state_unknown") from finalize_error
        raise
    return supabase_official_document_detail(document_id, session)


def supabase_resubmit_official_document(
    document_id: str,
    payload: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document.get("applicant_id") != user.get("id"):
        raise PermissionError("only_applicant_can_resubmit")
    require_official_creation_company(user, document.get("company_id"))
    requested_at = str(document.get("correction_requested_at") or "")
    if not requested_at:
        raise ValueError("official_document_not_rejected")
    log_id, _ = _supabase_official_resubmit_operation_ids(document_id, user["id"], requested_at)
    if document.get("current_status") != "rejected":
        state = _supabase_official_resubmit_finalize_state(document_id, user["id"], requested_at, log_id)
        if state == "committed":
            return supabase_official_document_detail(document_id, session)
        if state == "unknown":
            raise RuntimeError("official_document_resubmit_commit_state_unknown")
        if not str(document.get("current_status") or "").startswith("pending_") or not document.get("current_step"):
            raise ValueError("official_document_not_rejected")
        return _supabase_finalize_official_document_resubmit(document, user, payload, session)
    rejection_jobs = supabase_filter_rows(
        "official_document_rejection_jobs",
        {"document_id": document_id},
        order="created_at.desc",
        limit=20,
    )
    if rejection_jobs and rejection_jobs[0].get("status") != "completed":
        raise ValueError("official_document_rejection_revision_pending")
    supabase_submit_official_document(document_id, payload, session)
    submitted_document = supabase_official_document_row(document_id)
    return _supabase_finalize_official_document_resubmit(submitted_document, user, payload, session)


def supabase_submit_official_document(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document["applicant_id"] != user["id"]:
        raise PermissionError("only_applicant_can_submit")
    if document["current_status"] not in {"draft", "rejected"}:
        raise ValueError("official_document_not_submittable")
    if not bool(document.get("requires_stamp", True)):
        raise PermissionError("official_document_stamp_required")
    seal_context = official_seal_context_from_document(document)
    if not seal_context:
        raise ValueError("official_seal_document_category_required")
    workflow_steps = official_seal_workflow_steps(seal_context["approval_route_code"])
    actor_plan: Dict[str, Dict[str, Any]] | None = None
    workflow_lock_metadata: Dict[str, Any] | None = None
    if is_production():
        snapshot = current_finance_bridge_snapshot(user.get("email") or "")
        finance_role = strict_finance_role_profile(
            (snapshot.get("identity") or {}).get("role")
        )["logging_role_key"]
        workflow_steps = official_workflow_steps_for_finance_applicant(
            seal_context["approval_route_code"],
            finance_role,
        )
        user, actor_plan = sync_supabase_finance_snapshot(
            snapshot,
            auth_user_id=user.get("auth_user_id") or "",
            expected_user_id=user["id"],
            require_workflow=True,
            required_step_keys=(step["key"] for step in workflow_steps),
        )
        workflow_lock_metadata = locked_official_finance_workflow_metadata(
            document,
            snapshot,
            finance_role,
            workflow_steps,
        )
        session = {**(session or {}), "user": user}
    require_official_creation_company(user, document.get("company_id"))
    # Resolve the live Finance identity and full exact actor chain before any
    # AV/editor/seal mutation. PostgREST must never guess a global role holder.
    supabase_assert_official_document_uploads_av_clean(document)
    supabase_lock_official_editor_submission(document, payload, user)
    stamp_request = supabase_official_document_stamp_request(document_id)
    if not stamp_request:
        raise ValueError("official_document_seal_required")
    stamp_request = supabase_lock_official_stamp_seal_versions(document, stamp_request)
    supabase_validate_official_document_seal(stamp_request["seal_id"], document["company_id"], require_current=True)
    if document["source_type"] == "blank_editor":
        supabase_ensure_official_generated_pdf(document, official_actor_name(user))
    if workflow_lock_metadata is not None:
        document = supabase_patch(
            "official_documents",
            document_id,
            {"metadata_json": workflow_lock_metadata, "updated_at": now()},
        )
        workflow_lock = workflow_lock_metadata["official_seal"]
        supabase_insert_official_log(
            document_id,
            "lock_finance_workflow",
            user,
            (
                f"policy={workflow_lock['conditional_policy_version']};"
                f"role={workflow_lock['applicant_finance_role']};"
                f"steps={','.join(workflow_lock['approval_step_keys'])};"
                f"snapshot={workflow_lock['finance_snapshot_sha256']}"
            ),
        )
    applicant = supabase_user_by_id(document["applicant_id"]) or user
    steps = supabase_create_official_workflow_steps(
        document,
        applicant,
        actor_plan=actor_plan,
        workflow_steps=workflow_steps,
    )
    first = steps[0]
    review_started_at = now()
    supabase_patch("official_documents", document_id, {"current_status": OFFICIAL_DOCUMENT_STEP_STATUS[first["step_key"]], "current_step": first["step_key"], "updated_at": review_started_at})
    supabase_patch("official_document_approval_steps", first["id"], {"review_started_at": review_started_at, "updated_at": review_started_at})
    supabase_insert_official_log(document_id, "submit", user, payload.get("comment") or "送出發文用印簽核", step_id=first["id"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    if first.get("approver_role"):
        approver = supabase_user_by_id(first.get("approver_user_id") or "") or {}
        supabase_create_and_deliver_notification({
            "type": "發文簽核",
            "title": f"{document['title']} 待{first['step_name']}簽核",
            **exact_notification_target_payload(approver, document.get("company_id") or ""),
            "source": document_id,
            "priority": "高",
            "body": f"{document.get('applicant_name') or '申請人'} 已送出發文用印申請。",
        })
    return supabase_official_document_detail(document_id, session)


def supabase_current_official_pending_step(document: Dict[str, Any]) -> Dict[str, Any]:
    rows = supabase_filter_rows("official_document_approval_steps", {"document_id": document["id"], "step_key": document.get("current_step") or "", "status": "pending"}, order="step_order.asc", limit=1)
    if not rows:
        raise ValueError("official_document_current_step_not_pending")
    return rows[0]


def supabase_next_official_step(
    document_id: str,
    step_order: int,
    workflow_generation: int,
) -> Dict[str, Any] | None:
    for step in supabase_official_document_steps(document_id):
        if (
            int(step.get("workflow_generation") or 1) == workflow_generation
            and int(step.get("step_order") or 0) > step_order
            and step.get("status") == "pending"
        ):
            return step
    return None


def _supabase_verify_decision_file(document_id: str, file_row: Dict[str, Any]) -> Dict[str, Any]:
    if str(file_row.get("document_id") or "") != document_id or not file_row.get("file_object_id"):
        raise ValueError("official_document_decision_file_metadata_invalid")
    file_object = supabase_get("file_objects", str(file_row["file_object_id"]))
    if not file_object:
        raise ValueError("official_document_file_object_missing")
    require_official_file_av_clean(file_row, file_object)
    data = supabase_storage_download(
        file_object["storage_key"],
        file_object.get("bucket") or EDOC_STORAGE_BUCKET,
    )
    verify_official_file_bytes(file_row, file_object, data)
    return _official_decision_file_entry(file_row)


def supabase_official_decision_document_evidence(
    document: Dict[str, Any],
    stamp_request: Dict[str, Any] | None,
) -> Dict[str, Any]:
    source = supabase_official_latest_source_file(document)
    source_entry = _supabase_verify_decision_file(document["id"], source)
    attachment_rows = sorted(
        supabase_official_raw_document_files(document["id"], "attachment"),
        key=lambda item: str(item.get("id") or ""),
    )
    attachments = [
        _supabase_verify_decision_file(document["id"], row)
        for row in attachment_rows
    ]
    request = stamp_request or {}
    v2_values = {
        "revision_id": str(request.get("locked_editor_revision_id") or "").strip(),
        "source_bundle_sha256": str(request.get("locked_source_sha256") or "").strip().upper(),
        "prepared_file_id": str(request.get("prepared_file_id") or "").strip(),
        "prepared_sha256": str(request.get("prepared_sha256") or "").strip().upper(),
        "manifest_sha256": str(request.get("editor_manifest_sha256") or "").strip().upper(),
        "editor_schema_version": int(request.get("editor_schema_version") or 0),
        "renderer_version": str(request.get("renderer_version") or "").strip(),
    }
    is_v2 = any(v2_values.values())
    prepared_entry: Dict[str, Any] | None = None
    if is_v2:
        if (
            not all(v2_values.values())
            or int(v2_values["editor_schema_version"]) < EDOC_EDITOR_SCHEMA_VERSION
            or not re.fullmatch(r"[0-9A-F]{64}", str(v2_values["source_bundle_sha256"]))
            or not re.fullmatch(r"[0-9A-F]{64}", str(v2_values["prepared_sha256"]))
            or not re.fullmatch(r"[0-9A-F]{64}", str(v2_values["manifest_sha256"]))
        ):
            raise ValueError("official_document_editor_decision_lock_incomplete")
        revisions = supabase_filter_rows(
            "official_document_editor_revisions",
            {"id": v2_values["revision_id"], "document_id": document["id"]},
            limit=1,
        )
        if not revisions:
            raise ValueError("editor_locked_revision_missing")
        revision = revisions[0]
        state = parse_json_any(revision.get("editor_state_json"), {}) or {}
        computed_manifest = canonical_editor_manifest(state).upper()
        if (
            computed_manifest != str(revision.get("manifest_sha256") or "").upper()
            or computed_manifest != v2_values["manifest_sha256"]
        ):
            raise ValueError("editor_manifest_hash_mismatch")
        computed_source_bundle = _supabase_editor_source_bundle_sha256(document["id"], state).upper()
        if computed_source_bundle != v2_values["source_bundle_sha256"]:
            raise ValueError("editor_source_hash_mismatch")
        prepared_rows = supabase_filter_rows(
            "official_document_files",
            {
                "id": v2_values["prepared_file_id"],
                "document_id": document["id"],
                "file_type": "prepared_pdf",
            },
            limit=1,
        )
        if not prepared_rows:
            raise ValueError("official_document_prepared_file_missing")
        prepared_entry = _supabase_verify_decision_file(document["id"], prepared_rows[0])
        if prepared_entry["sha256"] != v2_values["prepared_sha256"]:
            raise ValueError("official_document_prepared_sha256_mismatch")
        preflight_assets = supabase_filter_rows(
            "official_document_editor_assets",
            {
                "document_id": document["id"],
                "editor_revision_id": v2_values["revision_id"],
                "asset_kind": "prepared_pdf",
                "official_file_id": v2_values["prepared_file_id"],
                "sha256": v2_values["prepared_sha256"],
                "preflight_status": "passed",
            },
            order="created_at.desc",
            limit=1,
        )
        if not preflight_assets:
            raise ValueError("editor_preflight_not_completed")
    return {
        "source_file": source_entry,
        "source_bundle_sha256": v2_values["source_bundle_sha256"] if is_v2 else "",
        "prepared_file": prepared_entry,
        "prepared_sha256": v2_values["prepared_sha256"] if is_v2 else "",
        "manifest_sha256": v2_values["manifest_sha256"] if is_v2 else "",
        "editor_revision_id": v2_values["revision_id"] if is_v2 else "",
        "editor_schema_version": int(v2_values["editor_schema_version"]) if is_v2 else 0,
        "renderer_version": str(v2_values["renderer_version"]) if is_v2 else "",
        "attachments": attachments,
        "attachments_manifest_sha256": _official_attachment_manifest_sha256(attachments),
        "legacy_renderer": not is_v2,
    }


def supabase_official_review_access_evidence(
    document_id: str,
    step: Dict[str, Any],
    actor_id: str,
    document_evidence: Dict[str, Any],
) -> Dict[str, Any]:
    started_at = str(step.get("review_started_at") or "").strip()
    if not started_at:
        raise ValueError("official_document_review_session_not_started")
    required_ids = [document_evidence["source_file"]["id"]]
    if document_evidence.get("prepared_file"):
        required_ids.append(document_evidence["prepared_file"]["id"])
    required_ids.extend(item["id"] for item in document_evidence.get("attachments") or [])
    access_rows: List[Dict[str, Any]] = []
    for file_id in sorted(set(required_ids)):
        matches = [
            row
            for row in supabase_filter_rows(
                "official_document_approval_logs",
                {
                    "document_id": document_id,
                    "actor_id": actor_id,
                    "file_id": file_id,
                    "action": "download_file",
                },
                order="created_at.desc,id.desc",
                limit=100,
            )
            if str(row.get("created_at") or "") >= started_at
        ]
        if not matches:
            raise ValueError(f"official_document_review_access_required:{file_id}")
        row = matches[0]
        access_rows.append({
            "file_id": str(row.get("file_id") or ""),
            "access_log_id": str(row.get("id") or ""),
            "action": "download_file",
            "accessed_at": str(row.get("created_at") or ""),
        })
    return {
        "step_started_at": started_at,
        "required_file_ids": sorted(set(required_ids)),
        "access_logs": access_rows,
        "server_verified": True,
    }


def supabase_claim_official_document_approval(
    document_id: str,
    expected_step_id: str,
    approver_user_id: str,
    decision_actor_user_id: str,
    decision_evidence: Dict[str, Any],
    comment: str = "",
) -> Dict[str, Any]:
    """Atomically claim a step and bind the review actor/file evidence."""
    raw = supabase_request(
        "POST",
            "rpc/edoc_claim_official_document_approval_v3",
        {
            "p_document_id": document_id,
            "p_expected_step_id": expected_step_id,
            "p_approver_user_id": approver_user_id,
            "p_decision_actor_user_id": decision_actor_user_id,
            "p_comment": comment or "核准",
            "p_decision_evidence": decision_evidence,
        },
    )
    if isinstance(raw, list):
        result = raw[0] if len(raw) == 1 and isinstance(raw[0], dict) else {}
    else:
        result = raw if isinstance(raw, dict) else {}
    if not result or not isinstance(result.get("claimed"), bool):
        raise RuntimeError("official_document_approval_claim_invalid_response")
    if not result["claimed"]:
        if (
            result.get("document_id") != document_id
            or result.get("expected_step_id") != expected_step_id
        ):
            raise RuntimeError("official_document_approval_claim_invalid_response")
        return result
    if (
        result.get("document_id") != document_id
        or result.get("step_id") != expected_step_id
        or result.get("transition") not in {"next_step", "auto_stamp"}
        or not isinstance(result.get("next_step"), dict)
    ):
        raise RuntimeError("official_document_approval_claim_invalid_response")
    if result["transition"] == "auto_stamp" and result["next_step"].get("step_key") != "applicant_confirm":
        raise RuntimeError("official_document_approval_claim_invalid_response")
    if result["transition"] == "next_step" and result["next_step"].get("step_key") == "applicant_confirm":
        raise RuntimeError("official_document_approval_claim_invalid_response")
    return result


def supabase_claim_official_document_rejection(
    document_id: str,
    expected_step_id: str,
    approver_user_id: str,
    decision_actor_user_id: str,
    decision_evidence: Dict[str, Any],
    comment: str = "",
) -> Dict[str, Any]:
    """Atomically reject a step and persist correction/evidence metadata."""
    raw = supabase_request(
        "POST",
            "rpc/edoc_claim_official_document_rejection_v3",
        {
            "p_document_id": document_id,
            "p_expected_step_id": expected_step_id,
            "p_approver_user_id": approver_user_id,
            "p_decision_actor_user_id": decision_actor_user_id,
            "p_comment": comment or "駁回",
            "p_decision_evidence": decision_evidence,
        },
    )
    if isinstance(raw, list):
        result = raw[0] if len(raw) == 1 and isinstance(raw[0], dict) else {}
    else:
        result = raw if isinstance(raw, dict) else {}
    if not result or not isinstance(result.get("claimed"), bool):
        raise RuntimeError("official_document_rejection_claim_invalid_response")
    if not result["claimed"]:
        if (
            result.get("document_id") != document_id
            or result.get("expected_step_id") != expected_step_id
        ):
            raise RuntimeError("official_document_rejection_claim_invalid_response")
        return result
    if (
        result.get("document_id") != document_id
        or result.get("step_id") != expected_step_id
        or result.get("document_status") != "rejected"
        or result.get("document_step") != "applicant"
        or not isinstance(result.get("voided_step_count"), int)
        or int(result.get("voided_step_count") or 0) < 1
    ):
        raise RuntimeError("official_document_rejection_claim_invalid_response")
    return result


def supabase_approve_official_document(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document["current_status"] in {"draft", "stamping", "stamped", "pending_general_affairs_dispatch", "returned_to_applicant_for_send", "dispatched", "sent_by_applicant", "closed", "cancelled", "rejected"}:
        raise ValueError("official_document_not_pending_approval")
    if not bool(document.get("requires_stamp", True)):
        raise PermissionError("official_document_stamp_required")
    step = supabase_current_official_pending_step(document)
    delegation = assert_official_step_actor(user, step, document, supabase_mode=True)
    if step["step_key"] != "applicant_confirm" and user["id"] == document["applicant_id"]:
        raise PermissionError("applicant_cannot_self_approve")
    expected_step_id = str(payload.get("expected_step_id") or payload.get("expectedStepId") or "").strip()
    if not expected_step_id:
        raise ValueError("official_document_approval_expected_step_required")
    if expected_step_id != str(step.get("id") or ""):
        raise ValueError("official_document_approval_already_claimed")
    principal_actor_id = str(step.get("approver_user_id") or "")
    stamp_request = supabase_official_document_stamp_request(document_id)
    document_evidence = supabase_official_decision_document_evidence(document, stamp_request)
    review_access = supabase_official_review_access_evidence(
        document_id,
        step,
        str(user.get("id") or ""),
        document_evidence,
    )
    evidence = official_approval_decision_evidence(
        document,
        stamp_request,
        payload,
        has_attachments=bool(document_evidence["attachments"]),
        step=step,
        actor=user,
        principal_actor_id=principal_actor_id,
        document_evidence=document_evidence,
        review_access=review_access,
    )
    claim = supabase_claim_official_document_approval(
        document_id,
        expected_step_id,
        principal_actor_id,
        str(user.get("id") or ""),
        evidence,
        str(payload.get("comment") or ""),
    )
    if not claim.get("claimed"):
        raise ValueError("official_document_approval_already_claimed")
    if claim["transition"] == "auto_stamp":
        result = supabase_auto_stamp_official_document(document_id, payload, user)
        return {**supabase_official_document_detail(document_id, session), "auto_stamp": result}
    return supabase_official_document_detail(document_id, session)


def supabase_reject_official_document(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document.get("current_status") == "rejected":
        expected_step_id = str(payload.get("expected_step_id") or payload.get("expectedStepId") or "").strip()
        jobs = supabase_filter_rows(
            "official_document_rejection_jobs",
            {"document_id": document_id},
            order="created_at.desc",
            limit=20,
        )
        job = next((item for item in jobs if item.get("expected_step_id") == expected_step_id), None)
        step = supabase_get("official_document_approval_steps", expected_step_id) if expected_step_id else None
        if not job or not step or user.get("id") not in {
            step.get("decision_actor_user_id"),
            step.get("approver_user_id"),
        }:
            raise ValueError("official_document_not_pending_approval")
        editor_revision = supabase_clone_official_editor_revision_after_reject(document_id, user)
        result = supabase_official_document_detail(document_id, session)
        if editor_revision:
            result["editor_revision"] = editor_revision
            result["editor_state"] = editor_revision["state"]
            result["approval_restart_required"] = True
        return result
    if document["current_status"] in {"draft", "stamping", "stamped", "pending_general_affairs_dispatch", "returned_to_applicant_for_send", "dispatched", "sent_by_applicant", "closed", "cancelled", "rejected"}:
        raise ValueError("official_document_not_pending_approval")
    step = supabase_current_official_pending_step(document)
    delegation = assert_official_step_actor(user, step, document, supabase_mode=True)
    if step["step_key"] != "applicant_confirm" and user["id"] == document["applicant_id"]:
        raise PermissionError("applicant_cannot_self_approve")
    expected_step_id = str(payload.get("expected_step_id") or payload.get("expectedStepId") or "").strip()
    if not expected_step_id:
        raise ValueError("official_document_approval_expected_step_required")
    if expected_step_id != str(step.get("id") or ""):
        raise ValueError("official_document_approval_already_claimed")
    comment = payload.get("comment") or "駁回"
    principal_actor_id = str(step.get("approver_user_id") or "")
    stamp_request = supabase_official_document_stamp_request(document_id)
    document_evidence = supabase_official_decision_document_evidence(document, stamp_request)
    review_access = supabase_official_review_access_evidence(
        document_id,
        step,
        str(user.get("id") or ""),
        document_evidence,
    )
    rejection_evidence = {
        **official_approval_decision_evidence(
            document,
            stamp_request,
            payload,
            has_attachments=bool(document_evidence["attachments"]),
            step=step,
            actor=user,
            principal_actor_id=principal_actor_id,
            document_evidence=document_evidence,
            review_access=review_access,
            require_client_acknowledgements=False,
            decision_type="reject",
        ),
        **structured_rejection_evidence(payload),
        "schema_version": 2,
        "decision_type": "reject",
    }
    claim = supabase_claim_official_document_rejection(
        document_id,
        expected_step_id,
        principal_actor_id,
        str(user.get("id") or ""),
        rejection_evidence,
        str(comment),
    )
    if not claim.get("claimed"):
        raise ValueError("official_document_approval_already_claimed")
    editor_revision = supabase_clone_official_editor_revision_after_reject(document_id, user)
    result = supabase_official_document_detail(document_id, session)
    if editor_revision:
        result["editor_revision"] = editor_revision
        result["editor_state"] = editor_revision["state"]
        result["approval_restart_required"] = True
    return result


def supabase_cancel_official_document(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document["applicant_id"] != user["id"]:
        raise PermissionError("only_applicant_can_cancel")
    raw = supabase_request(
        "POST",
        "rpc/edoc_cancel_official_document",
        {"p_document_id": document_id, "p_applicant_user_id": str(user.get("id") or "")},
    )
    result = _supabase_stamp_rpc_result(raw, "cancelled", "official_document_cancel_invalid_response")
    if result.get("document_id") != document_id:
        raise RuntimeError("official_document_cancel_invalid_response")
    if not result.get("cancelled"):
        raise ValueError(str(result.get("reason") or "official_document_cancel_conflict"))
    supabase_insert_official_log(document_id, "cancel", user, payload.get("comment") or "申請人取消", ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return supabase_official_document_detail(document_id, session)


def supabase_confirm_official_document(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document["applicant_id"] != user["id"]:
        raise PermissionError("only_applicant_can_confirm")
    if document["current_status"] not in {"returned_to_applicant_for_send", "stamped", "dispatched", "sent_by_applicant"}:
        raise ValueError("official_document_not_ready_for_applicant_confirm")
    if document["current_status"] == "returned_to_applicant_for_send":
        supabase_complete_official_dispatch(document_id, payload, session)
    step = next((item for item in supabase_official_document_steps(document_id) if item.get("step_key") == "applicant_confirm"), None)
    if step and step.get("status") == "pending":
        supabase_patch("official_document_approval_steps", step["id"], {"status": "approved", "comment": payload.get("comment") or "申請人確認完成", "approved_at": now(), "updated_at": now()})
    supabase_patch("official_documents", document_id, {"current_status": "closed", "current_step": "", "updated_at": now()})
    supabase_insert_official_log(document_id, "confirm", user, payload.get("comment") or "申請人確認已用印版本", ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return supabase_official_document_detail(document_id, session)


def supabase_update_official_stamp_position(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    if document["applicant_id"] != user["id"]:
        raise PermissionError("only_applicant_can_update_stamp_position")
    if document["current_status"] != "draft":
        raise ValueError("stamp_position_locked_after_submit")
    stamp_request = supabase_official_document_stamp_request(document_id)
    if not stamp_request:
        raise ValueError("official_document_stamp_request_not_found")
    supabase_validate_official_document_seal(
        str(stamp_request.get("seal_id") or ""),
        str(document.get("company_id") or ""),
        require_current=False,
    )
    created_positions = supabase_replace_official_stamp_positions(
        stamp_request["id"],
        stamp_request["seal_id"],
        payload,
        allow_unbound_current=True,
    )
    first_position = created_positions[0]
    position = {
        "stamp_page": first_position["page"],
        "stamp_x": first_position["x"],
        "stamp_y": first_position["y"],
        "stamp_width": first_position["width"],
        "stamp_height": first_position["height"],
    }
    supabase_patch("official_document_stamp_requests", stamp_request["id"], {**position, "updated_at": now()})
    if "text_overlays" in payload or "textOverlays" in payload:
        supabase_replace_official_text_overlays(stamp_request["id"], payload)
    supabase_insert_official_log(document_id, "update_stamp_position", user, json.dumps(position, ensure_ascii=False), ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    return supabase_official_document_detail(document_id, session)


def _supabase_stamp_rpc_result(raw: Any, result_key: str, error_code: str) -> Dict[str, Any]:
    if isinstance(raw, list):
        result = raw[0] if len(raw) == 1 and isinstance(raw[0], dict) else {}
    else:
        result = raw if isinstance(raw, dict) else {}
    if not result or not isinstance(result.get(result_key), bool):
        raise RuntimeError(error_code)
    return result


def supabase_claim_official_document_stamp(
    document_id: str,
    stamp_request_id: str,
    claim_token: str,
    claim_owner_id: str,
    lease_seconds: int = EDOC_STAMP_CLAIM_LEASE_SECONDS,
) -> Dict[str, Any]:
    result = _supabase_stamp_rpc_result(
        supabase_request(
            "POST",
            "rpc/edoc_claim_official_document_stamp",
            {
                "p_document_id": document_id,
                "p_stamp_request_id": stamp_request_id,
                "p_claim_token": claim_token,
                "p_claim_owner_id": claim_owner_id,
                "p_lease_seconds": lease_seconds,
            },
        ),
        "claimed",
        "official_stamp_claim_invalid_response",
    )
    if result.get("document_id") != document_id or result.get("stamp_request_id") != stamp_request_id:
        raise RuntimeError("official_stamp_claim_invalid_response")
    if result["claimed"] and result.get("claim_token") != claim_token:
        raise RuntimeError("official_stamp_claim_invalid_response")
    return result


def supabase_complete_official_document_stamp_claim(
    document_id: str,
    stamp_request_id: str,
    claim_token: str,
    stamped_file_id: str,
) -> Dict[str, Any]:
    result = _supabase_stamp_rpc_result(
        supabase_request(
            "POST",
            "rpc/edoc_complete_official_document_stamp",
            {
                "p_document_id": document_id,
                "p_stamp_request_id": stamp_request_id,
                "p_claim_token": claim_token,
                "p_stamped_file_id": stamped_file_id,
            },
        ),
        "completed",
        "official_stamp_complete_invalid_response",
    )
    if result.get("document_id") != document_id or result.get("stamp_request_id") != stamp_request_id:
        raise RuntimeError("official_stamp_complete_invalid_response")
    if result["completed"] and result.get("stamped_file_id") != stamped_file_id:
        raise RuntimeError("official_stamp_complete_invalid_response")
    return result


def supabase_fail_official_document_stamp_claim(
    document_id: str,
    stamp_request_id: str,
    claim_token: str,
    detail: str,
) -> Dict[str, Any]:
    result = _supabase_stamp_rpc_result(
        supabase_request(
            "POST",
            "rpc/edoc_fail_official_document_stamp",
            {
                "p_document_id": document_id,
                "p_stamp_request_id": stamp_request_id,
                "p_claim_token": claim_token,
                "p_error_message": detail[:500],
            },
        ),
        "failed",
        "official_stamp_fail_invalid_response",
    )
    if result.get("document_id") != document_id or result.get("stamp_request_id") != stamp_request_id:
        raise RuntimeError("official_stamp_fail_invalid_response")
    return result


def supabase_official_stamp_candidate_file(
    document_id: str,
    stamp_request_id: str,
) -> Tuple[Dict[str, Any], bytes] | None:
    rows = supabase_filter_rows(
        "official_document_files",
        {"document_id": document_id, "file_type": "stamped_pdf", "stamp_request_id": stamp_request_id},
        order="created_at.desc",
        limit=1,
    )
    if not rows:
        return None
    file_meta = rows[0]
    file_object = supabase_get("file_objects", file_meta.get("file_object_id") or "") if file_meta.get("file_object_id") else None
    if not file_object:
        raise ValueError("official_stamp_candidate_file_invalid")
    data = supabase_storage_download(file_object["storage_key"], file_object.get("bucket") or EDOC_STORAGE_BUCKET)
    verify_official_file_bytes(file_meta, file_object, data)
    return file_meta, data


def supabase_auto_stamp_official_document(document_id: str, payload: Dict[str, Any], actor: Dict[str, Any] | None = None) -> Dict[str, Any]:
    document = supabase_official_document_row(document_id)
    stamp_request = supabase_official_document_stamp_request(document_id)
    if not stamp_request:
        raise ValueError("official_document_stamp_request_required")
    claim_token = secrets.token_hex(32)
    claim = supabase_claim_official_document_stamp(
        document_id,
        stamp_request["id"],
        claim_token,
        str((actor or {}).get("id") or "system"),
    )
    if not claim.get("claimed"):
        return {"ok": False, "error": claim.get("reason") or "official_stamp_claim_busy", "claim": claim}
    try:
        document = supabase_official_document_row(document_id)
        stamp_request = supabase_official_document_stamp_request(document_id) or stamp_request
        supabase_assert_official_document_uploads_av_clean(document)
        # Candidate recovery is still a finalization path; never skip locked
        # manifest, hash, AV and dimension verification.
        prevalidated_editor = supabase_verify_locked_editor_for_stamp(document, stamp_request)
        prevalidated_legacy_asset: Tuple[Dict[str, Any], bytes] | None = None
        if not prevalidated_editor:
            prevalidated_legacy_asset = supabase_locked_legacy_official_seal_asset(stamp_request)
        candidate = supabase_official_stamp_candidate_file(document_id, stamp_request["id"])
        if candidate:
            stamped_file, _ = candidate
            engine = "recovered-stamped-candidate"
            layout = {"recovered": True}
            stamp_no = payload.get("stamp_no") or f"ODSTAMP-{document_id}-RECOVERED"
            locked_editor = prevalidated_editor
            seal_file = {"file_hash": "", "file_mime_type": ""}
            text_overlays: List[Dict[str, Any]] = []
        else:
            locked_editor = prevalidated_editor
            seal = supabase_company_seal_row(stamp_request["seal_id"])
            if not seal.get("is_active"):
                raise ValueError("inactive_seal_cannot_stamp")
            supabase_insert_official_log(document_id, "read_seal_vault_for_stamp", actor, "authorized_backend_stamp_only", ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
            if locked_editor:
                seal_file = {"file_hash": "", "file_mime_type": ""}
                seal_bytes = b""
                source_file = locked_editor["prepared_file"]
                original_pdf = locked_editor["prepared_bytes"]
            else:
                if not prevalidated_legacy_asset:
                    raise ValueError("official_locked_seal_version_missing")
                seal_file, seal_bytes = prevalidated_legacy_asset
                source_file = supabase_official_latest_source_file(document)
                source_object = supabase_get("file_objects", source_file.get("file_object_id") or "") if source_file.get("file_object_id") else None
                if not source_object:
                    raise ValueError("official_source_file_object_missing")
                original_pdf = supabase_storage_download(source_object["storage_key"], source_object.get("bucket") or EDOC_STORAGE_BUCKET)
                verify_official_file_bytes(source_file, source_object, original_pdf)
            stamp_no = payload.get("stamp_no") or f"ODSTAMP-{document_id}-{int(time.time())}"
            positions = official_stamp_positions_from_request(stamp_request, seal)
            text_overlays = stamp_request.get("text_overlays") or []
            if locked_editor:
                stamped_pdf, engine, layout = stamp_prepared_pdf_with_locked_seals(locked_editor)
            else:
                stamped_pdf, engine, layout = stamp_uploaded_pdf_bytes(
                    original_pdf,
                    [{**item, "stamp_no": stamp_no} for item in positions],
                    stamp_no,
                    text_overlays,
                    {"data": seal_bytes, "mime_type": seal_file.get("file_mime_type") or ""},
                    source_text_on_top=document.get("source_type") == "blank_editor",
                )
            renewed = supabase_claim_official_document_stamp(
                document_id,
                stamp_request["id"],
                claim_token,
                str((actor or {}).get("id") or "system"),
            )
            if not renewed.get("claimed"):
                raise ValueError("official_stamp_claim_lost")
            stamped_file = supabase_store_official_pdf_file(
                document_id,
                "stamped_pdf",
                f"{document_id}-stamped.pdf",
                stamped_pdf,
                "Auto Stamp",
                stamp_request_id=stamp_request["id"],
                stamp_claim_token=claim_token,
            )
        renewed = supabase_claim_official_document_stamp(
            document_id,
            stamp_request["id"],
            claim_token,
            str((actor or {}).get("id") or "system"),
        )
        if not renewed.get("claimed"):
            raise ValueError("official_stamp_claim_lost")
        completed = supabase_complete_official_document_stamp_claim(
            document_id,
            stamp_request["id"],
            claim_token,
            stamped_file["id"],
        )
        if not completed.get("completed"):
            raise ValueError("official_stamp_claim_lost")
        seal_hash_audit = ",".join(sorted({str(item.get("locked_seal_sha256") or "") for item in (stamp_request.get("stamp_positions") or []) if item.get("locked_seal_sha256")})) or seal_file["file_hash"]
        try:
            supabase_insert_official_log(document_id, "auto_stamp", actor, f"{engine} {stamp_no} seal_hashes={seal_hash_audit} seal_image=true text_overlays={len(text_overlays)} prepared_sha256={(locked_editor or {}).get('prepared_file', {}).get('file_hash', '')}", file_id=stamped_file["id"], ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
            dispatch_record = supabase_advance_official_dispatch_after_stamp(document_id, stamped_file, actor, payload)
            post_processing_warning = ""
        except Exception as post_exc:
            dispatch_record = supabase_official_dispatch_record(document_id)
            post_processing_warning = f"stamp_post_processing_failed:{type(post_exc).__name__}"
        return {"ok": True, "stamped_file": official_file_metadata(stamped_file), "engine": engine, "layout": layout, "dispatch_record": dispatch_record, "post_processing_warning": post_processing_warning}
    except Exception as exc:
        detail = redact_text(str(exc))[:500]
        failed = supabase_fail_official_document_stamp_claim(document_id, stamp_request["id"], claim_token, detail)
        if failed.get("failed"):
            supabase_insert_official_log(document_id, "auto_stamp_failed", actor, detail, ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
            try:
                ga_actor = official_dispatch_workflow_owner(supabase_official_document_steps(document_id))
                ga_user = supabase_user_by_id(ga_actor["id"]) or {}
                supabase_create_and_deliver_notification({
                    "type": "發文用印失敗",
                    "title": f"{document['title']} 自動用印失敗",
                    **exact_notification_target_payload(ga_user, document.get("company_id") or ""),
                    "source": document_id,
                    "priority": "高",
                    "body": detail,
                })
            except Exception as notification_exc:
                log_structured(
                    "error",
                    "official_stamp_failure_notification_failed",
                    document_id=document_id,
                    error=redact_text(str(notification_exc))[:200],
                )
            return {"ok": False, "error": "auto_stamp_failed", "detail": detail}
        return {"ok": False, "error": "official_stamp_claim_lost", "detail": "用印租約已由其他工作程序接手。"}


def supabase_retry_official_document_stamp(document_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    stamp_request = supabase_official_document_stamp_request(document_id)
    if not official_stamp_recoverable(document, stamp_request):
        raise ValueError("official_document_not_recoverable_for_stamp")
    steps = supabase_official_document_steps(document_id)
    if not can_retry_official_stamp(user, steps):
        raise PermissionError("official_stamp_retry_forbidden")
    unapproved_steps = [
        step for step in steps
        if step.get("step_key") != "applicant_confirm" and step.get("status") != "approved"
    ]
    if unapproved_steps:
        raise ValueError("official_document_not_fully_approved_for_stamp_retry")
    if not stamp_request:
        raise ValueError("official_document_stamp_request_required")
    supabase_insert_official_log(document_id, "retry_auto_stamp", user, payload.get("comment") or "總務重試自動用印", ip_address=payload.get("ip_address") or "", user_agent=payload.get("user_agent") or "")
    result = supabase_auto_stamp_official_document(document_id, payload, user)
    return {**supabase_official_document_detail(document_id, session), "auto_stamp": result}


def supabase_official_document_download_file(document_id: str, file_id: str, session: Dict[str, Any] | None, ip_address: str = "", user_agent: str = "") -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    user = supabase_official_session_user(session)
    document = supabase_official_document_row(document_id)
    steps = supabase_official_document_steps(document_id)
    actor_snapshots = supabase_official_document_actor_snapshots(document_id)
    if not canDownloadOfficialDocument(user, document, steps, actor_snapshots):
        raise PermissionError("official_document_download_forbidden")
    supabase_assert_official_document_uploads_av_clean(document)
    rows = supabase_filter_rows("official_document_files", {"id": file_id, "document_id": document_id}, limit=1)
    if not rows:
        raise ValueError("official_document_file_not_found")
    file_meta = rows[0]
    file_object = supabase_get("file_objects", file_meta.get("file_object_id") or "") if file_meta.get("file_object_id") else None
    if not file_object:
        raise ValueError("official_document_file_object_missing")
    file_object = require_official_file_av_clean(file_meta, file_object)
    try:
        verify_private_storage_file_metadata(file_meta, file_object, expected_document_id=document_id)
    except ValueError as exc:
        raise ValueError("official_file_hash_mismatch") from exc
    signed = supabase_storage_create_signed_download_url(
        file_object["storage_key"],
        file_object.get("bucket") or EDOC_STORAGE_BUCKET,
        file_name=file_meta.get("file_name") or f"{document_id}.pdf",
        download=True,
    )
    supabase_insert_official_log(document_id, "download_file", user, file_meta["file_type"], file_id=file_id, ip_address=ip_address, user_agent=user_agent)
    supabase_insert("file_access_logs", {
        "id": f"FLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "attachment_id": None,
        "file_object_id": file_meta.get("file_object_id"),
        "document_id": None,
        "actor": official_actor_name(user),
        "action": "發文附件下載",
        "ip": ip_address,
        "device": user_agent[:180] if user_agent else "",
        "watermark_text": "",
        "result": "成功",
        "detail": f"official_document_id={document_id};{file_meta['file_type']}",
        "created_at": now(),
    })
    return document, {**file_meta, "object": file_object}, signed


def supabase_inbound_document_detail(inbound_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    row = supabase_get("inbound_documents", inbound_id)
    if not row:
        raise ValueError("inbound_document_not_found")
    if session is not None and not supabase_can_access_inbound_document(row, session):
        raise PermissionError("inbound_document_view_forbidden")
    row["metadata"] = parse_json_any(row.get("metadata_json"), {}) or {}
    row["attachments"] = supabase_filter_rows("inbound_document_attachments", {"inbound_document_id": inbound_id}, order="created_at.desc", limit=100)
    return row


def supabase_can_access_inbound_document(
    document: Dict[str, Any],
    session: Dict[str, Any] | None,
) -> bool:
    user = session.get("user") if session else None
    if not user:
        return False
    if session_has_any_permission(
        session,
        ["official_documents.all_records", "official_documents.all_todo", "official_documents.receive"],
    ):
        return True
    if user.get("id") in {document.get("created_by"), document.get("assignee_user_id")}:
        return True
    dispatches = supabase_filter_rows(
        "internal_dispatches",
        {"inbound_document_id": document.get("id") or ""},
        limit=100,
    )
    return any(
        any(
            recipient.get("recipient_user_id") == user.get("id")
            for recipient in supabase_filter_rows(
                "internal_dispatch_recipients",
                {"dispatch_id": dispatch.get("id") or ""},
                limit=300,
            )
        )
        for dispatch in dispatches
    )


def supabase_inbound_document_download_attachment(
    inbound_id: str,
    attachment_id: str,
    session: Dict[str, Any] | None,
    ip_address: str = "",
    user_agent: str = "",
) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    user = supabase_official_session_user(session)
    document = supabase_inbound_document_detail(inbound_id)
    if not supabase_can_access_inbound_document(document, session):
        raise PermissionError("inbound_attachment_download_forbidden")
    attachments = supabase_filter_rows(
        "inbound_document_attachments",
        {"id": attachment_id, "inbound_document_id": inbound_id},
        limit=1,
    )
    if not attachments:
        raise ValueError("inbound_attachment_not_found")
    attachment = attachments[0]
    file_object = supabase_get("file_objects", attachment.get("file_object_id") or "")
    if not file_object:
        raise ValueError("inbound_attachment_file_missing")
    if str(file_object.get("scan_status") or "").strip() == "已隔離":
        raise ValueError("inbound_attachment_quarantined")
    if not file_object_av_is_clean(file_object):
        raise ValueError("inbound_attachment_antivirus_required")
    try:
        verify_private_storage_file_metadata(attachment, file_object, expected_document_id=inbound_id)
    except ValueError as exc:
        raise ValueError("inbound_attachment_hash_mismatch") from exc
    signed = supabase_storage_create_signed_download_url(
        file_object["storage_key"],
        file_object.get("bucket") or EDOC_STORAGE_BUCKET,
        file_name=attachment.get("file_name") or f"{inbound_id}-attachment",
        download=True,
    )
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": official_actor_name(user),
        "action": "download_inbound_attachment",
        "target_type": "inbound_documents",
        "target_id": inbound_id,
        "detail": f"attachment_id={attachment_id}",
        "event_type": "sensitive_access",
        "module_code": "official_documents",
        "result": "success",
        "severity": "info",
    })
    supabase_insert("file_access_logs", {
        "id": f"FLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "attachment_id": None,
        "file_object_id": attachment.get("file_object_id"),
        "document_id": None,
        "actor": official_actor_name(user),
        "action": "收錄附件下載",
        "ip": ip_address,
        "device": user_agent[:180],
        "watermark_text": "",
        "result": "成功",
        "detail": f"inbound_document_id={inbound_id}",
        "created_at": now(),
    })
    return document, {**attachment, "object": file_object}, signed


def supabase_list_inbound_documents(query: Dict[str, List[str]] | None, session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    user = supabase_official_session_user(session)
    rows = supabase_filter_rows("inbound_documents", {}, order="created_at.desc", limit=300)
    status = (query or {}).get("status", [""])[0] if query else ""
    assignee_user_id = (query or {}).get("assignee_user_id", [""])[0] if query else ""
    company_wide = session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo", "official_documents.receive"])
    linked_inbound_ids: set[str] = set()
    if not company_wide:
        recipient_rows = supabase_filter_rows(
            "internal_dispatch_recipients",
            {"recipient_user_id": user.get("id") or ""},
            limit=1000,
        )
        for recipient in recipient_rows:
            dispatch = supabase_get("internal_dispatches", recipient.get("dispatch_id") or "")
            if dispatch and dispatch.get("inbound_document_id"):
                linked_inbound_ids.add(dispatch["inbound_document_id"])
    scoped: List[Dict[str, Any]] = []
    for row in rows:
        if status and row.get("status") != status:
            continue
        if assignee_user_id and row.get("assignee_user_id") != assignee_user_id:
            continue
        if not company_wide:
            if row.get("assignee_user_id") != user.get("id") and row.get("created_by") != user.get("id") and row.get("id") not in linked_inbound_ids:
                continue
        scoped.append(supabase_inbound_document_detail(row["id"]))
    return scoped


def supabase_create_inbound_document(payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    source_type = (payload.get("source_type") or "manual").strip()
    if not can_create_inbound_archive(session, source_type):
        raise PermissionError("inbound_archive_create_forbidden")
    inbound_id = payload.get("id") or f"INB-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    row = supabase_insert("inbound_documents", {
        "id": inbound_id,
        "receive_no": payload.get("receive_no") or payload.get("receiveNo") or f"收文字第{datetime.now().strftime('%Y%m%d%H%M%S')}",
        "source_type": source_type,
        "external_exchange_id": payload.get("external_exchange_id") or payload.get("exchange_id") or "",
        "sender_name": payload.get("sender_name") or payload.get("agency_name") or "未指定來文單位",
        "sender_contact": payload.get("sender_contact") or "",
        "subject": payload.get("subject") or "未命名收文",
        "body": payload.get("body") or payload.get("description") or "",
        "recipient_department_id": payload.get("recipient_department_id") or "",
        "recipient_department_name": payload.get("recipient_department_name") or payload.get("department") or user.get("unit") or "",
        "assignee_user_id": payload.get("assignee_user_id") or "",
        "assignee_name": payload.get("assignee_name") or "",
        "due_at": payload.get("due_at") or "",
        "priority": payload.get("priority") or "普通件",
        "security_level": payload.get("security_level") or "普通",
        "status": payload.get("status") or "registered",
        "metadata_json": payload.get("metadata") or {},
        "created_by": user.get("id") or "",
        "created_at": now(),
        "updated_at": now(),
        "closed_at": "",
    })
    supabase_insert("audit_logs", {"id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}", "actor": official_actor_name(user), "action": "register_inbound_document", "target_type": "inbound_documents", "target_id": inbound_id, "detail": row["subject"], "event_type": "submit", "module_code": "official_documents", "result": "success", "severity": "info"})
    if payload.get("content_base64"):
        supabase_upload_inbound_attachment(inbound_id, payload, session)
    return supabase_inbound_document_detail(inbound_id)


def supabase_assign_inbound_document(inbound_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    supabase_inbound_document_detail(inbound_id)
    assignee_id = payload.get("assignee_user_id") or payload.get("user_id") or ""
    assignee = supabase_user_by_id(assignee_id) if assignee_id else None
    update = {
        "recipient_department_id": payload.get("recipient_department_id") or payload.get("department_id") or "",
        "recipient_department_name": payload.get("recipient_department_name") or payload.get("department") or (assignee.get("unit") if assignee else ""),
        "assignee_user_id": assignee_id,
        "assignee_name": payload.get("assignee_name") or (assignee.get("name") if assignee else ""),
        "due_at": payload.get("due_at") or "",
        "status": payload.get("status") or "assigned",
        "updated_at": now(),
    }
    supabase_patch("inbound_documents", inbound_id, update)
    supabase_insert("audit_logs", {"id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}", "actor": official_actor_name(user), "action": "assign_inbound_document", "target_type": "inbound_documents", "target_id": inbound_id, "detail": json.dumps(update, ensure_ascii=False), "event_type": "assign", "module_code": "official_documents", "result": "success", "severity": "info"})
    if assignee:
        supabase_create_and_deliver_notification({
            "type": "收文分派",
            "title": f"{inbound_id} 已分派給你",
            **exact_notification_target_payload(assignee, user.get("company_id") or ""),
            "source": inbound_id,
            "body": payload.get("note") or "請於期限內處理收文。",
        })
    return supabase_inbound_document_detail(inbound_id)


def supabase_upload_inbound_attachment(inbound_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    document = supabase_inbound_document_detail(inbound_id)
    if not supabase_can_access_inbound_document(document, session):
        raise PermissionError("inbound_attachment_upload_forbidden")
    content = payload.get("content_base64") or payload.get("file_content_base64") or ""
    if not content:
        raise ValueError("inbound_attachment_required")
    data = base64.b64decode(content)
    if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
        raise ValueError("inbound_attachment_too_large")
    file_name = Path(payload.get("file_name") or "inbound-attachment.pdf").name
    mime_type = payload.get("file_mime_type") or payload.get("mime_type") or "application/pdf"
    scan_status, scan_signature = scan_official_upload_bytes(data, file_name)
    file_row = supabase_store_file_object(inbound_id, file_name, data, "inbound-documents", "inbound-attachment", official_actor_name(user), mime_type)
    file_row = supabase_persist_file_object_scan_result(
        file_row["id"],
        scan_status,
        scan_signature,
        official_actor_name(user),
    )
    row = supabase_insert("inbound_document_attachments", {
        "id": f"INBATT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "inbound_document_id": inbound_id,
        "file_object_id": file_row["id"],
        "file_name": file_name,
        "file_mime_type": mime_type,
        "file_size": len(data),
        "file_hash": file_row["sha256"],
        "attachment_type": payload.get("attachment_type") or "inbound_attachment",
        "uploaded_by": user.get("id") or "",
        "created_at": now(),
    })
    supabase_insert("audit_logs", {"id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}", "actor": official_actor_name(user), "action": "upload_inbound_attachment", "target_type": "inbound_documents", "target_id": inbound_id, "detail": row["file_hash"], "event_type": "sensitive_access", "module_code": "official_documents", "result": "success", "severity": "info"})
    return {"inbound_document": supabase_inbound_document_detail(inbound_id), "attachment": row}


def supabase_launch_smoke_inbound_assignee() -> Dict[str, Any]:
    for role in ("業務助理", "員工", "主管"):
        user = supabase_active_user_by_role(role)
        if user:
            return user
    raise ValueError("launch_smoke_inbound_assignee_required")


def supabase_create_inbound_assignment_launch_smoke(
    payload: Dict[str, Any] | None,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    payload = payload or {}
    user = supabase_official_session_user(session)
    if not session_has_any_permission(session, ["official_documents.receive", "official_documents.all_todo", "official_documents.all_records"]):
        raise PermissionError("inbound_launch_smoke_forbidden")
    assignee = supabase_user_by_id(payload.get("assignee_user_id") or "") if payload.get("assignee_user_id") else supabase_launch_smoke_inbound_assignee()
    package = build_launch_inbound_smoke_pdf()
    date_compact = datetime.now().strftime("%Y%m%d")
    suffix = secrets.token_hex(3).upper()
    inbound = supabase_create_inbound_document(
        {
            "receive_no": payload.get("receive_no") or f"收測字第{date_compact}{suffix}號",
            "source_type": "manual",
            "external_exchange_id": payload.get("external_exchange_id") or f"MANUAL-SMOKE-{date_compact}-{suffix}",
            "sender_name": "去識別化來文機關",
            "sender_contact": "contact@example.invalid",
            "subject": "去識別化收文登錄與分派走測",
            "body": "本筆收文僅供下週一內部正式上線走測，確認收文登錄、附件、承辦分派、辦理期限與 audit log。",
            "priority": "普通件",
            "security_level": "普通",
            "metadata": {
                "source": "backend_launch_smoke_test",
                "journey": "inbound_assignment",
                "contains_personal_data": False,
                "contains_official_exchange_payload": False,
            },
            "file_name": package["file_name"],
            "file_mime_type": package["mime_type"],
            "content_base64": base64.b64encode(package["data"]).decode("ascii"),
            "ip_address": payload.get("ip_address") or "",
            "user_agent": payload.get("user_agent") or "",
        },
        session,
    )
    due_at = payload.get("due_at") or f"{(datetime.now() + timedelta(days=3)).strftime('%Y-%m-%d')} 18:00:00"
    assigned = supabase_assign_inbound_document(
        inbound["id"],
        {
            "assignee_user_id": assignee["id"],
            "assignee_name": assignee.get("name") or "",
            "recipient_department_name": payload.get("recipient_department_name") or assignee.get("unit") or "總管理處",
            "due_at": due_at,
            "note": "去識別化走測：已由後端建立收文並分派承辦與期限。",
        },
        session,
    )
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": official_actor_name(user),
        "action": "launch_smoke_inbound_assignment",
        "target_type": "inbound_documents",
        "target_id": assigned["id"],
        "detail": f"assignee={assignee['id']} due_at={due_at}",
        "event_type": "launch_smoke",
        "module_code": "official_documents",
        "result": "success",
        "severity": "info",
    })
    return {
        "ok": True,
        "journey": "inbound_assignment",
        "inbound_document": assigned,
        "assignee": public_user(assignee),
        "next_action": "請承辦人回到收文管理查看附件、期限與後續辦理狀態。",
    }


def supabase_close_inbound_document(inbound_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    supabase_inbound_document_detail(inbound_id)
    supabase_patch("inbound_documents", inbound_id, {"status": "closed", "closed_at": now(), "updated_at": now()})
    supabase_insert("audit_logs", {"id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}", "actor": official_actor_name(user), "action": "close_inbound_document", "target_type": "inbound_documents", "target_id": inbound_id, "detail": payload.get("comment") or "收文結案", "event_type": "approve", "module_code": "official_documents", "result": "success", "severity": "info"})
    return supabase_inbound_document_detail(inbound_id)


def supabase_internal_dispatch_detail(dispatch_id: str, session: Dict[str, Any] | None = None) -> Dict[str, Any]:
    row = supabase_get("internal_dispatches", dispatch_id)
    if not row:
        raise ValueError("internal_dispatch_not_found")
    row["metadata"] = parse_json_any(row.get("metadata_json"), {}) or {}
    row["recipients"] = supabase_filter_rows("internal_dispatch_recipients", {"dispatch_id": dispatch_id}, order="created_at.asc", limit=300)
    if session is not None:
        user = supabase_official_session_user(session)
        allowed = (
            row.get("sender_user_id") == user.get("id")
            or any(item.get("recipient_user_id") == user.get("id") for item in row["recipients"])
            or session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"])
        )
        if not allowed:
            raise PermissionError("internal_dispatch_view_forbidden")
    row["replies"] = supabase_filter_rows("internal_dispatch_replies", {"dispatch_id": dispatch_id}, order="created_at.desc", limit=300)
    for reply in row["replies"]:
        reply["attachment"] = None
        if reply.get("attachment_file_id"):
            attachment = supabase_get("file_objects", reply["attachment_file_id"])
            if attachment:
                reply["attachment"] = {
                    "attachment_file_id": attachment.get("id"),
                    "file_name": attachment.get("file_name"),
                    "mime_type": attachment.get("mime_type"),
                    "file_size": int(attachment.get("size_bytes") or 0),
                    "sha256": attachment.get("sha256"),
                    "scan_status": attachment.get("scan_status"),
                }
    row["logs"] = supabase_filter_rows("internal_dispatch_logs", {"dispatch_id": dispatch_id}, order="created_at.desc", limit=300)
    row["inbound_document"] = supabase_inbound_document_detail(row["inbound_document_id"]) if row.get("inbound_document_id") else None
    return row


def supabase_internal_dispatch_recipient_directory(session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    require_internal_dispatch_creator(session)
    users = supabase_filter_rows("users", {"status": "啟用"}, order="unit.asc,name.asc", limit=500)
    return [
        {"id": user.get("id"), "name": user.get("name"), "unit": user.get("unit"), "role": user.get("role")}
        for user in users
    ]


def supabase_internal_dispatch_log(dispatch_id: str, user: Dict[str, Any] | None, action: str, detail: str = "", payload: Dict[str, Any] | None = None) -> Dict[str, Any]:
    row = supabase_insert("internal_dispatch_logs", {
        "id": f"IDLOG-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "dispatch_id": dispatch_id,
        "actor_id": user.get("id") if user else "system",
        "action": action,
        "detail": detail,
        "ip_address": (payload or {}).get("ip_address") or "",
        "user_agent": ((payload or {}).get("user_agent") or "")[:180],
        "created_at": now(),
    })
    supabase_insert("audit_logs", {"id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}", "actor": official_actor_name(user), "action": action, "target_type": "internal_dispatches", "target_id": dispatch_id, "detail": detail, "event_type": "submit", "module_code": "official_documents", "result": "success", "severity": "info"})
    return row


def supabase_list_internal_dispatches(query: Dict[str, List[str]] | None, session: Dict[str, Any] | None) -> List[Dict[str, Any]]:
    user = supabase_official_session_user(session)
    rows = supabase_filter_rows("internal_dispatches", {}, order="created_at.desc", limit=300)
    status = (query or {}).get("status", [""])[0] if query else ""
    result: List[Dict[str, Any]] = []
    for row in rows:
        if status and row.get("status") != status:
            continue
        recipients = supabase_filter_rows("internal_dispatch_recipients", {"dispatch_id": row["id"]}, limit=300)
        if not session_has_any_permission(session, ["official_documents.all_records", "official_documents.all_todo"]):
            if row.get("sender_user_id") != user.get("id") and not any(item.get("recipient_user_id") == user.get("id") for item in recipients):
                continue
        detail = supabase_internal_dispatch_detail(row["id"], session)
        result.append(detail)
    return result


def supabase_create_internal_dispatch(payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = require_internal_dispatch_creator(session)
    recipients = payload.get("recipients") or []
    if not isinstance(recipients, list) or not recipients:
        raise ValueError("internal_dispatch_recipients_required")
    if not all(isinstance(recipient, dict) for recipient in recipients):
        raise ValueError("invalid_internal_dispatch_recipient")
    default_action_required = bool(payload.get("reply_required", False))
    recipient_actions = [bool(recipient.get("action_required", default_action_required)) for recipient in recipients]
    dispatch_id = payload.get("id") or f"IDISP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    inbound_document_id = payload.get("inbound_document_id") or ""
    if inbound_document_id:
        supabase_inbound_document_detail(inbound_document_id)
    reply_required = any(recipient_actions)
    due_days = int(pdf_safe_float(payload.get("reply_due_days"), 0)) if reply_required else 0
    due_at = payload.get("due_at") or ((datetime.now() + timedelta(days=due_days)).strftime("%Y-%m-%d %H:%M:%S") if due_days else "")
    row = supabase_insert("internal_dispatches", {
        "id": dispatch_id,
        "official_document_id": payload.get("official_document_id") or payload.get("document_id") or None,
        "inbound_document_id": inbound_document_id or None,
        "title": payload.get("title") or payload.get("subject") or "內部派文",
        "subject": payload.get("subject") or payload.get("title") or "內部派文",
        "body": payload.get("body") or "",
        "sender_user_id": user.get("id") or "",
        "sender_name": user.get("name") or user.get("email") or "",
        "sender_department": user.get("unit") or "",
        "reply_required": reply_required,
        "reply_due_days": due_days or None,
        "due_at": due_at,
        "reply_status": "pending" if reply_required else "not_required",
        "status": "sent",
        "metadata_json": payload.get("metadata") or {},
        "created_at": now(),
        "updated_at": now(),
        "closed_at": "",
    })
    for index, recipient in enumerate(recipients, start=1):
        action_required = recipient_actions[index - 1]
        recipient_user_id = recipient.get("user_id") or recipient.get("recipient_user_id") or ""
        recipient_user = supabase_user_by_id(recipient_user_id) if recipient_user_id else None
        rec = supabase_insert("internal_dispatch_recipients", {
            "id": f"IDREC-{int(time.time() * 1000)}-{index}-{secrets.token_hex(2).upper()}",
            "dispatch_id": dispatch_id,
            "recipient_type": recipient.get("recipient_type") or ("department" if recipient.get("department_id") else "user"),
            "recipient_user_id": recipient_user_id,
            "recipient_department_id": recipient.get("department_id") or recipient.get("recipient_department_id") or "",
            "recipient_name": recipient.get("name") or recipient.get("recipient_name") or (recipient_user.get("name") if recipient_user else ""),
            "action_required": action_required,
            "status": "pending" if action_required else "informed",
            "read_at": "",
            "replied_at": "",
            "created_at": now(),
            "updated_at": now(),
        })
        if recipient_user:
            notice = (f"請於 {due_at} 前處理並回覆。" if due_at else "請處理並回覆。") if action_required else "此件僅供知悉，不需回覆。"
            supabase_create_and_deliver_notification({
                "type": "內部派文",
                "title": row["subject"],
                **exact_notification_target_payload(recipient_user, user.get("company_id") or ""),
                "source": dispatch_id,
                "body": f"{row['sender_name']} 發送內部公文。{notice}",
            })
    supabase_internal_dispatch_log(dispatch_id, user, "create_internal_dispatch", row["subject"], payload)
    return supabase_internal_dispatch_detail(dispatch_id, session)


def supabase_reply_internal_dispatch(dispatch_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    detail = supabase_internal_dispatch_detail(dispatch_id, session)
    recipient = next((item for item in detail["recipients"] if item.get("recipient_user_id") == user.get("id")), None)
    if not recipient:
        raise PermissionError("internal_dispatch_reply_forbidden")
    if recipient and not bool(recipient.get("action_required")):
        raise PermissionError("internal_dispatch_reply_not_required")
    attachment_file_id = None
    if payload.get("content_base64"):
        data = base64.b64decode(payload["content_base64"])
        if len(data) > EDOC_INLINE_JSON_UPLOAD_MAX_FILE_SIZE_MB * 1024 * 1024:
            raise ValueError("internal_dispatch_reply_attachment_too_large")
        file_name = Path(payload.get("file_name") or f"{dispatch_id}-reply-attachment").name
        scan_status, scan_signature = scan_official_upload_bytes(data, file_name)
        file_row = supabase_store_file_object(dispatch_id, file_name, data, "internal-dispatches", "reply-attachment", official_actor_name(user), payload.get("file_mime_type") or "application/pdf")
        supabase_persist_file_object_scan_result(file_row["id"], scan_status, scan_signature, official_actor_name(user))
        attachment_file_id = file_row["id"]
    row = supabase_insert("internal_dispatch_replies", {
        "id": f"IDREP-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "dispatch_id": dispatch_id,
        "recipient_id": recipient.get("id") if recipient else None,
        "replier_user_id": user.get("id") or "",
        "replier_name": user.get("name") or user.get("email") or "",
        "reply_text": payload.get("reply_text") or payload.get("body") or "",
        "attachment_file_id": attachment_file_id,
        "status": "submitted",
        "created_at": now(),
    })
    if recipient:
        supabase_patch("internal_dispatch_recipients", recipient["id"], {"status": "replied", "replied_at": now(), "updated_at": now()})
    refreshed = supabase_internal_dispatch_detail(dispatch_id, session)
    if refreshed.get("reply_required") and not any(bool(item.get("action_required")) and item.get("status") != "replied" for item in refreshed["recipients"]):
        supabase_patch("internal_dispatches", dispatch_id, {"reply_status": "completed", "status": "reply_completed", "updated_at": now()})
    supabase_internal_dispatch_log(dispatch_id, user, "reply_internal_dispatch", row["reply_text"], payload)
    return supabase_internal_dispatch_detail(dispatch_id, session)


def supabase_mark_internal_dispatch_read(dispatch_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    detail = supabase_internal_dispatch_detail(dispatch_id, session)
    recipient = next((item for item in detail["recipients"] if item.get("recipient_user_id") == user.get("id")), None)
    if not recipient:
        raise PermissionError("internal_dispatch_read_forbidden")
    if not recipient.get("read_at"):
        supabase_patch("internal_dispatch_recipients", recipient["id"], {"read_at": now(), "updated_at": now()})
        supabase_internal_dispatch_log(dispatch_id, user, "read_internal_dispatch", "recipient_opened_dispatch", payload)
    return supabase_internal_dispatch_detail(dispatch_id, session)


def supabase_internal_dispatch_reply_attachment(
    dispatch_id: str,
    reply_id: str,
    session: Dict[str, Any] | None,
) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    user = supabase_official_session_user(session)
    supabase_internal_dispatch_detail(dispatch_id, session)
    rows = supabase_filter_rows("internal_dispatch_replies", {"id": reply_id, "dispatch_id": dispatch_id}, limit=1)
    if not rows or not rows[0].get("attachment_file_id"):
        raise ValueError("internal_dispatch_reply_attachment_not_found")
    reply = rows[0]
    file_object = supabase_get("file_objects", reply["attachment_file_id"])
    if not file_object:
        raise ValueError("internal_dispatch_reply_attachment_not_found")
    if not file_object_av_is_clean(file_object):
        raise ValueError("internal_dispatch_reply_attachment_antivirus_required")
    signed = supabase_storage_create_signed_download_url(
        file_object.get("storage_key") or "",
        file_object.get("bucket") or EDOC_STORAGE_BUCKET,
        file_name=file_object.get("file_name") or f"{reply_id}-attachment",
        download=True,
    )
    supabase_internal_dispatch_log(dispatch_id, user, "download_internal_dispatch_reply_attachment", f"reply_id={reply_id}")
    return reply, file_object, signed


def supabase_close_internal_dispatch(dispatch_id: str, payload: Dict[str, Any], session: Dict[str, Any] | None) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    detail = supabase_internal_dispatch_detail(dispatch_id, session)
    if detail.get("sender_user_id") != user.get("id") and not session_has_any_permission(session, ["official_documents.all_todo", "official_documents.all_records"]):
        raise PermissionError("internal_dispatch_close_forbidden")
    supabase_patch("internal_dispatches", dispatch_id, {"status": "closed", "closed_at": now(), "updated_at": now()})
    supabase_internal_dispatch_log(dispatch_id, user, "close_internal_dispatch", payload.get("comment") or "內部派文結案", payload)
    return supabase_internal_dispatch_detail(dispatch_id, session)


def supabase_role_permissions(role_name: str) -> List[str]:
    fallback = ROLE_PERMISSION_FALLBACKS.get(role_name, [])
    # Fetch the role plus its permission codes through PostgREST's embedded
    # relations in one request.  The previous three-request chain was paid on
    # every cold Finance SSO login and materially delayed the first screen.
    role_qs = urllib.parse.urlencode({
        "select": "id,role_permissions(permission_id,permissions(code))",
        "name": f"eq.{role_name}",
        "limit": "1",
    })
    try:
        roles = supabase_request("GET", f"roles?{role_qs}")
        if not roles:
            return fallback
        codes = set(fallback)
        for link in roles[0].get("role_permissions") or []:
            embedded = link.get("permissions") or {}
            permission_rows = embedded if isinstance(embedded, list) else [embedded]
            for permission in permission_rows:
                code = roster_text(permission.get("code")) if isinstance(permission, dict) else ""
                if code:
                    codes.add(code)
        return sorted(codes)
    except RuntimeError:
        # Older PostgREST schemas may not expose the embedded relationship.
        # Keep the authorization result correct while allowing a safe rollout;
        # only this compatibility branch performs the legacy requests.
        role_id_qs = urllib.parse.urlencode({"select": "id", "name": f"eq.{role_name}", "limit": "1"})
        roles = supabase_request("GET", f"roles?{role_id_qs}")
        if not roles:
            return fallback
        rp_qs = urllib.parse.urlencode({"select": "permission_id", "role_id": f"eq.{roles[0]['id']}"})
        links = supabase_request("GET", f"role_permissions?{rp_qs}")
        if not links:
            return fallback
        ids = ",".join([item["permission_id"] for item in links])
        perm_qs = urllib.parse.urlencode({"select": "code", "id": f"in.({ids})"})
        return sorted({item["code"] for item in supabase_request("GET", f"permissions?{perm_qs}")} | set(fallback))


def _supabase_login_bundle(raw: Any) -> Dict[str, Any] | None:
    """Normalize a JSONB RPC response without accepting ambiguous shapes."""
    if raw is None:
        return None
    if isinstance(raw, list):
        if not raw:
            return None
        if len(raw) != 1 or not isinstance(raw[0], dict):
            raise RuntimeError("finance_login_rpc_response_invalid")
        raw = raw[0]
    if not isinstance(raw, dict):
        raise RuntimeError("finance_login_rpc_response_invalid")
    session = raw.get("session")
    user = raw.get("user")
    permissions = raw.get("permissions")
    if not isinstance(session, dict) or not isinstance(user, dict) or not isinstance(permissions, list):
        raise RuntimeError("finance_login_rpc_response_invalid")
    if any(not isinstance(code, str) or not code.strip() for code in permissions):
        raise RuntimeError("finance_login_rpc_response_invalid")
    return {
        "session": session,
        "user": user,
        "permissions": sorted(set(permissions) | set(ROLE_PERMISSION_FALLBACKS.get(roster_text(user.get("role")), []))),
    }


def _supabase_login_rpc_missing(error: RuntimeError) -> bool:
    detail = str(error)
    return "PGRST202" in detail or "Could not find the function" in detail


def supabase_create_finance_login_session(
    user: Dict[str, Any],
    ip: str,
    device: str,
) -> Dict[str, Any]:
    """Atomically create the session, audit row and exact RBAC payload."""
    ts = now()
    token = secrets.token_urlsafe(36)
    expires = (datetime.now() + timedelta(hours=8)).strftime("%Y-%m-%d %H:%M:%S")
    session_id = f"SES-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    login_event_id = f"LOGIN-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    try:
        raw = supabase_request("POST", "rpc/edoc_create_finance_login_session_v1", {
            "p_user_id": user["id"],
            "p_session_id": session_id,
            "p_token_hash": hash_token(token),
            "p_provider": "Finance Google SSO",
            "p_ip": ip,
            "p_device": device,
            "p_expires_at": expires,
            "p_created_at": ts,
            "p_login_event_id": login_event_id,
        })
        bundle = _supabase_login_bundle(raw)
        if not bundle:
            raise RuntimeError("finance_login_rpc_response_invalid")
        if (
            roster_text(bundle["session"].get("id")) != session_id
            or roster_text(bundle["session"].get("user_id")) != roster_text(user.get("id"))
            or roster_text(bundle["user"].get("id")) != roster_text(user.get("id"))
            or roster_text(bundle["session"].get("expires_at")) != expires
            or "password_hash" in bundle["user"]
        ):
            raise RuntimeError("finance_login_rpc_response_invalid")
        return {
            "token": token,
            "expiresAt": expires,
            "user": bundle["user"],
            "permissions": bundle["permissions"],
        }
    except RuntimeError as error:
        if not _supabase_login_rpc_missing(error):
            raise
        # Compatibility is intentionally limited to a missing RPC during a
        # phased rollback. Validation, authorization and database errors from
        # an installed RPC remain fail-closed.
        supabase_insert("auth_sessions", {
            "id": session_id,
            "user_id": user["id"],
            "token_hash": hash_token(token),
            "provider": "Finance Google SSO",
            "ip": ip,
            "device": device,
            "expires_at": expires,
            "created_at": ts,
        })
        refreshed = supabase_patch("users", user["id"], {
            "last_login_at": ts,
            "last_synced_from_logging_at": ts,
        })
        supabase_insert("login_events", {
            "id": login_event_id,
            "user_id": user["id"],
            "email": user.get("email") or "",
            "provider": "Finance Google SSO",
            "ip": ip,
            "device": device,
            "status": "成功",
            "reason": "沿用已佈建的 Finance Google 帳號進入公文收發電子用印系統",
            "created_at": ts,
        })
        refreshed.pop("password_hash", None)
        return {
            "token": token,
            "expiresAt": expires,
            "user": refreshed,
            "permissions": supabase_role_permissions(refreshed.get("role", "")),
        }


def supabase_authenticate(payload: Dict[str, Any], ip: str, device: str) -> Tuple[Dict[str, Any], int]:
    email = str(payload.get("email", "")).strip().lower()
    password = str(payload.get("password", ""))
    provider = str(payload.get("provider") or payload.get("environment") or "本機帳號")
    if not test_fixture_accounts_enabled():
        return {"error": "finance_sso_required", "detail": "請由公司統一登入頁使用 Finance Google 帳號登入。"}, 403
    if not email or not password:
        return {"error": "invalid_request", "detail": "請輸入帳號與密碼。"}, 400
    qs = urllib.parse.urlencode({"select": "*", "email": f"eq.{email}", "limit": "1"})
    users = supabase_request("GET", f"users?{qs}")
    if not users:
        supabase_insert("login_events", {"id": f"LOGIN-{int(time.time() * 1000)}", "email": email, "provider": provider, "ip": ip, "device": device, "status": "失敗", "reason": "帳號不存在"})
        return {"error": "invalid_credentials", "detail": "帳號或密碼不正確。"}, 401
    user = users[0]
    if user.get("status") != "啟用":
        supabase_insert("login_events", {"id": f"LOGIN-{int(time.time() * 1000)}", "user_id": user["id"], "email": email, "provider": provider, "ip": ip, "device": device, "status": "失敗", "reason": "帳號停用"})
        return {"error": "account_disabled", "detail": "此帳號已停用。"}, 403
    if user.get("role") not in ALLOWED_EDOC_ROLES:
        supabase_insert("login_events", {"id": f"LOGIN-{int(time.time() * 1000)}", "user_id": user["id"], "email": email, "provider": provider, "ip": ip, "device": device, "status": "失敗", "reason": "角色未授權"})
        return {"error": "role_forbidden", "detail": "此帳號角色未授權使用電子公文系統。"}, 403
    if demo_login_blocked(email, password):
        supabase_insert("login_events", {"id": f"LOGIN-{int(time.time() * 1000)}", "user_id": user["id"], "email": email, "provider": provider, "ip": ip, "device": device, "status": "失敗", "reason": "正式站禁止 demo 帳號登入"})
        return {"error": "demo_login_disabled", "detail": "正式環境已關閉 demo 帳號，請使用正式帳號或 Logging Portal 登入。"}, 403
    if not verify_password(password, user.get("password_hash")):
        supabase_insert("login_events", {"id": f"LOGIN-{int(time.time() * 1000)}", "user_id": user["id"], "email": email, "provider": provider, "ip": ip, "device": device, "status": "失敗", "reason": "密碼錯誤"})
        return {"error": "invalid_credentials", "detail": "帳號或密碼不正確。"}, 401
    token = secrets.token_urlsafe(36)
    expires = (datetime.now() + timedelta(hours=8)).strftime("%Y-%m-%d %H:%M:%S")
    supabase_insert("auth_sessions", {"id": f"SES-{int(time.time() * 1000)}", "user_id": user["id"], "token_hash": hash_token(token), "provider": provider, "ip": ip, "device": device, "expires_at": expires})
    supabase_patch("users", user["id"], {"last_login_at": now()})
    supabase_insert("login_events", {"id": f"LOGIN-{int(time.time() * 1000)}", "user_id": user["id"], "email": email, "provider": provider, "ip": ip, "device": device, "status": "成功", "reason": "帳密驗證通過"})
    user.pop("password_hash", None)
    return {"token": token, "expiresAt": expires, "user": user, "permissions": supabase_role_permissions(user.get("role", ""))}, 200


def supabase_upsert_finance_manager_placeholder(
    manager: Dict[str, str],
    source_user: Dict[str, Any],
    company: Dict[str, str],
    ts: str,
) -> Dict[str, Any] | None:
    employee_id = manager.get("employee_id") or ""
    email = (manager.get("email") or "").lower()
    if not employee_id and not email:
        return None
    rows = supabase_filter_rows("users", {"finance_employee_id": employee_id}, limit=1) if employee_id else []
    if not rows and email:
        rows = supabase_filter_rows("users", {"email": email}, limit=1)
    profile = logging_role_profile(manager.get("role_key") or "section_chief")
    account_id = employee_id or email
    manager_email = email or f"{employee_id.lower()}@finance.local"
    values = {
        "account_source": "finance",
        "logging_account_id": account_id,
        "logging_role_key": profile["logging_role_key"],
        "finance_employee_id": employee_id,
        "company_id": company.get("id") or "",
        "company_name": company.get("name") or "",
        "company_address": company.get("address") or "",
        "external_account_payload_json": json.dumps({"source": "finance_manager_reference"}, ensure_ascii=False),
        "last_synced_from_logging_at": ts,
        "name": manager.get("name") or (email.split("@")[0] if email else account_id),
        "email": manager_email,
        "unit": roster_text(source_user.get("department") or source_user.get("unit") or profile["unit"]),
        "title": profile["title"],
        "job_level": profile["job_level"],
        "role": profile["role"],
        "provider": "Finance Google SSO",
        "mfa_status": "由 Finance 管理",
        "status": "啟用",
    }
    if rows:
        return supabase_patch("users", rows[0]["id"], values)
    return supabase_insert("users", {
        "id": f"FIN-{hashlib.sha256(account_id.encode('utf-8')).hexdigest()[:12].upper()}",
        **values,
        "created_at": ts,
    })


def supabase_upsert_finance_company_snapshot(
    source: Dict[str, Any],
    *,
    source_revision: int = 0,
    event_id: str = "",
    update_existing: bool = True,
) -> Tuple[Dict[str, Any], str]:
    """Reconcile one Finance company by stable entity id with optional CAS.

    ``member.changed`` carries a company snapshot for identity resolution, but
    its revision belongs to the member—not the company.  Callers therefore set
    ``update_existing=False`` for member/JIT snapshots: an existing company is
    resolved without mutating its independently revisioned master fields, while
    a previously unseen company can still be provisioned.
    """
    entity_id = roster_text(source.get("entityId") or source.get("entity_id"))
    name = roster_text(source.get("name"))
    tax_id = roster_text(source.get("taxId") if "taxId" in source else source.get("tax_id"))
    address = roster_text(source.get("address"))
    if not entity_id or not name:
        raise FinanceBridgeContractError("finance_company_invalid")
    if isinstance(source_revision, bool) or not isinstance(source_revision, int) or source_revision < 0:
        raise FinanceBridgeContractError("finance_company_revision_invalid")
    rows = supabase_filter_rows("companies", {"finance_entity_id": entity_id}, order="id.asc", limit=2)
    if len(rows) > 1:
        raise FinanceBridgeDenied("finance_company_ambiguous")
    existing = rows[0] if rows else None
    adopted_by_name = False
    if not existing:
        name_rows = supabase_filter_rows("companies", {"name": name}, order="id.asc", limit=2)
        if len(name_rows) > 1:
            raise FinanceBridgeDenied("finance_company_ambiguous")
        if name_rows:
            candidate = name_rows[0]
            candidate_entity = roster_text(candidate.get("finance_entity_id"))
            if candidate_entity and candidate_entity != entity_id:
                raise FinanceBridgeDenied("finance_company_identity_conflict")
            if roster_text(candidate.get("source_system")).lower() not in {"", "finance"}:
                raise FinanceBridgeDenied("finance_company_identity_conflict")
            existing = candidate
            adopted_by_name = True
    active = source.get("active", True) is not False
    values: Dict[str, Any] = {
        "name": name,
        "tax_id": tax_id,
        "address": address,
        "finance_entity_id": entity_id,
        "source_system": "finance",
        "last_synced_from_finance_at": now(),
        "status": "active" if active else "inactive",
        "updated_at": now(),
    }
    source_updated_at = roster_text(source.get("sourceUpdatedAt") or source.get("source_updated_at"))
    if source_updated_at:
        values["finance_source_updated_at"] = source_updated_at
    if source_revision:
        values.update({
            "finance_source_revision": source_revision,
            "finance_source_event_id": roster_text(event_id),
        })
    if existing:
        if not update_existing:
            if not adopted_by_name:
                return existing, "resolved"
            # A legacy exact-name row may be safely bound to the stable Finance
            # entity id, but member snapshots must not rewrite company master
            # attributes (name/address/tax/status) without company revision CAS.
            identity_values = {
                "finance_entity_id": entity_id,
                "source_system": "finance",
                "last_synced_from_finance_at": now(),
                "updated_at": now(),
            }
            try:
                return supabase_patch("companies", existing["id"], identity_values), "resolved"
            except RuntimeError:
                rows = supabase_filter_rows(
                    "companies",
                    {"finance_entity_id": entity_id},
                    order="id.asc",
                    limit=2,
                )
                if len(rows) == 1:
                    return rows[0], "resolved"
                raise
        current_revision = int(existing.get("finance_source_revision") or 0)
        if source_revision and source_revision <= current_revision:
            return existing, "stale"
        if source_revision:
            query = urllib.parse.urlencode({
                "id": f"eq.{existing['id']}",
                "finance_source_revision": f"eq.{current_revision}",
            })
            rows = supabase_request("PATCH", f"companies?{query}", values)
            if rows:
                return rows[0], "applied"
            latest = supabase_get("companies", existing["id"])
            if latest and int(latest.get("finance_source_revision") or 0) >= source_revision:
                return latest, "stale"
            raise FinanceBridgeUnavailable("finance_company_revision_conflict")
        return supabase_patch("companies", existing["id"], values), "applied"
    company_id = f"FINCO-{hashlib.sha256(entity_id.encode('utf-8')).hexdigest()[:12].upper()}"
    try:
        return supabase_insert("companies", {"id": company_id, **values, "created_at": now()}), "applied"
    except RuntimeError:
        rows = supabase_filter_rows("companies", {"finance_entity_id": entity_id}, order="id.asc", limit=2)
        if len(rows) == 1:
            if not update_existing:
                return rows[0], "resolved"
            if source_revision and int(rows[0].get("finance_source_revision") or 0) >= source_revision:
                return rows[0], "stale"
            if not source_revision:
                return supabase_patch("companies", rows[0]["id"], values), "applied"
        raise


def supabase_upsert_finance_module_link(
    user: Dict[str, Any],
    source: Dict[str, Any],
    *,
    sync_status: str,
    event_id: str = "",
    source_revision: int = 0,
) -> Dict[str, Any]:
    """Maintain one canonical Finance→EDOC link for JIT and background sync."""
    finance_user_id = roster_text(source.get("finance_user_id") or source.get("financeUserId"))
    if not user.get("id") or not finance_user_id:
        raise FinanceBridgeContractError("finance_identity_invalid")
    if sync_status not in {"active", "pending", "inactive"}:
        raise FinanceBridgeContractError("finance_identity_invalid")
    canonical_rows = supabase_filter_rows(
        "module_account_links",
        {"source_system": "finance", "source_account_id": finance_user_id, "target_module": "edoc"},
        order="created_at.asc",
        limit=2,
    )
    if len(canonical_rows) > 1:
        raise FinanceBridgeDenied("finance_module_link_ambiguous")
    if canonical_rows and roster_text(canonical_rows[0].get("user_id")) != roster_text(user.get("id")):
        raise FinanceBridgeDenied("finance_module_link_identity_conflict")
    # Supersede any old employee-number aliases before activating the stable id.
    other_links = supabase_filter_rows(
        "module_account_links",
        {"user_id": user["id"], "source_system": "finance", "target_module": "edoc"},
        order="created_at.asc",
        limit=20,
    )
    for link in other_links:
        if link.get("source_account_id") != finance_user_id and link.get("sync_status") != "superseded":
            supabase_patch("module_account_links", link["id"], {"sync_status": "superseded"})
    metadata = {
        "source": "finance_master",
        "eventId": roster_text(event_id),
        "sourceRevision": int(source_revision or 0),
    }
    values = {
        "user_id": user["id"],
        "source_system": "finance",
        "source_account_id": finance_user_id,
        "source_role_key": roster_text((source.get("profile") or {}).get("logging_role_key") or source.get("role")),
        "source_email": roster_text(source.get("email")).lower(),
        "target_module": "edoc",
        "target_role_key": roster_text(user.get("role")),
        "sync_status": sync_status,
        # This legacy bridge column is TEXT in the production schema (despite
        # the ``_json`` suffix).  Always send canonical JSON text so PostgREST
        # never has to coerce an object into text and receipt hashes/log output
        # remain deterministic across JIT and background-sync paths.
        "metadata_json": json.dumps(
            metadata,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ),
        "last_synced_at": now(),
        "updated_at": now(),
    }
    if canonical_rows:
        return supabase_patch("module_account_links", canonical_rows[0]["id"], values)
    link_id = f"LINK-FINANCE-EDOC-{hashlib.sha256(finance_user_id.encode('utf-8')).hexdigest()[:12].upper()}"
    try:
        return supabase_insert("module_account_links", {"id": link_id, **values, "created_at": now()})
    except RuntimeError:
        # A concurrent delivery may have created the canonical link after the
        # initial lookup. Re-resolve it, but never reassign another user link.
        rows = supabase_filter_rows(
            "module_account_links",
            {"source_system": "finance", "source_account_id": finance_user_id, "target_module": "edoc"},
            order="created_at.asc",
            limit=2,
        )
        if len(rows) == 1 and roster_text(rows[0].get("user_id")) == roster_text(user.get("id")):
            return supabase_patch("module_account_links", rows[0]["id"], values)
        raise


def supabase_enforce_finance_company_state(
    user: Dict[str, Any],
    source: Dict[str, Any],
    company: Dict[str, Any],
    *,
    event_id: str,
    source_revision: int,
) -> Tuple[Dict[str, Any], bool]:
    """Apply company-owned cache fields and fail closed on company disable.

    This check runs *after* the member/link CAS write. If company.changed races
    before this read, the inactive state is enforced here; if it races after
    this read, the company cascade runs after our write and wins instead.
    """
    latest = supabase_get("companies", roster_text(company.get("id"))) or company
    if roster_text(latest.get("id")) != roster_text(company.get("id")):
        raise FinanceBridgeDenied("finance_company_identity_conflict")
    company_inactive = roster_text(latest.get("status")).lower() not in {"active", "啟用"}
    values: Dict[str, Any] = {}
    if roster_text(user.get("company_name")) != roster_text(latest.get("name")):
        values["company_name"] = roster_text(latest.get("name"))
    if roster_text(user.get("company_address")) != roster_text(latest.get("address")):
        values["company_address"] = roster_text(latest.get("address"))
    if company_inactive:
        values.update({"status": "停用", "finance_source_status": "inactive"})
    if values:
        user = supabase_patch("users", user["id"], values)
    if company_inactive:
        supabase_upsert_finance_module_link(
            user,
            source,
            sync_status="inactive",
            event_id=event_id,
            source_revision=source_revision,
        )
        supabase_update_many(
            "auth_sessions",
            {"user_id": user["id"], "revoked_at": "__is_null__"},
            {"revoked_at": now()},
        )
    return user, company_inactive


def supabase_cascade_finance_company_projection(company: Dict[str, Any]) -> Dict[str, int]:
    """Refresh denormalized company fields; disable users when Finance disables it."""
    company_id = roster_text(company.get("id"))
    if not company_id:
        raise FinanceBridgeContractError("finance_company_invalid")
    users = supabase_filter_rows(
        "users",
        {"company_id": company_id, "account_source": "finance"},
        order="id.asc",
        limit=1000,
    )
    if len(users) >= 1000:
        raise FinanceBridgeUnavailable("finance_company_projection_limit_exceeded")
    company_inactive = roster_text(company.get("status")).lower() not in {"active", "啟用"}
    revoked_sessions = 0
    inactivated_links = 0
    for user in users:
        values: Dict[str, Any] = {
            "company_name": roster_text(company.get("name")),
            "company_address": roster_text(company.get("address")),
        }
        if company_inactive:
            values.update({"status": "停用", "finance_source_status": "inactive"})
        supabase_patch("users", user["id"], values)
        if not company_inactive:
            continue
        links = supabase_filter_rows(
            "module_account_links",
            {"user_id": user["id"], "source_system": "finance", "target_module": "edoc"},
            order="created_at.asc",
            limit=50,
        )
        if len(links) >= 50:
            raise FinanceBridgeUnavailable("finance_module_link_limit_exceeded")
        for link in links:
            if link.get("sync_status") in {"active", "pending"}:
                supabase_patch(
                    "module_account_links",
                    link["id"],
                    {"sync_status": "inactive", "last_synced_at": now(), "updated_at": now()},
                )
                inactivated_links += 1
        revoked = supabase_update_many(
            "auth_sessions",
            {"user_id": user["id"], "revoked_at": "__is_null__"},
            {"revoked_at": now()},
        )
        revoked_sessions += len(revoked or [])
    return {
        "affectedUsers": len(users),
        "inactivatedLinks": inactivated_links,
        "revokedSessions": revoked_sessions,
    }


def supabase_finance_company_by_entity(
    entity_id: str,
    *,
    require_launch_scope: bool = True,
) -> Dict[str, Any]:
    rows = supabase_filter_rows(
        "companies",
        {"finance_entity_id": str(entity_id or "").strip(), "status": "active"},
        order="id.asc",
        limit=2,
    )
    if len(rows) != 1:
        raise FinanceBridgeDenied("finance_company_unmapped")
    company = rows[0]
    if (
        require_launch_scope
        and is_production()
        and launch_company_scope_mode() == "manual_allowlist"
        and not launch_company_scope_ids()
    ):
        raise FinanceBridgeDenied("finance_company_launch_scope_required")
    if require_launch_scope and not launch_company_in_scope(str(company.get("id") or "")):
        raise FinanceBridgeDenied("finance_company_outside_launch_scope")
    return company


def _supabase_finance_snapshot_user_candidate(
    source: Dict[str, Any],
    auth_user_id: str = "",
) -> Dict[str, Any] | None:
    """Resolve the eDoc projection by Finance master identity.

    ``auth_user_id`` in a Finance snapshot belongs to the *Finance* Supabase
    project.  It must never be used as an eDoc ``auth.users`` foreign key or as
    an eDoc candidate selector; the two projects have independent Auth
    namespaces.  The argument remains for call compatibility while stable
    Finance user id plus normalized email are the only projection keys.
    """
    finance_user_id = source["finance_user_id"]
    email = source["email"]
    # Resolve every canonical alias in one PostgREST round trip. The old
    # three-query lookup was safe but made every Finance login pay the same
    # network latency three times before session creation.
    identity_terms = [
        f"logging_account_id.eq.{finance_user_id}",
        f"finance_employee_id.eq.{finance_user_id}",
        f"email.eq.{email}",
    ]
    query = urllib.parse.urlencode({
        "select": "*",
        "or": f"({','.join(identity_terms)})",
        "limit": "3",
    })
    rows = supabase_request("GET", f"users?{query}")
    candidates: Dict[str, Dict[str, Any]] = {
        str(row.get("id") or ""): row
        for row in rows
        if isinstance(row, dict)
    }
    candidates.pop("", None)
    if len(candidates) > 1:
        raise FinanceBridgeDenied("finance_identity_ambiguous")
    existing = next(iter(candidates.values()), None)
    if existing:
        existing_source = roster_text(existing.get("account_source")).lower()
        existing_finance_id = roster_text(existing.get("logging_account_id") or existing.get("finance_employee_id"))
        if existing_source not in {"", "finance"}:
            raise FinanceBridgeDenied("finance_identity_conflict")
        if existing_finance_id and existing_finance_id != finance_user_id:
            raise FinanceBridgeDenied("finance_identity_conflict")
    return existing


def _supabase_upsert_finance_snapshot_user(
    source: Dict[str, Any],
    company: Dict[str, Any],
    metadata: Dict[str, Any],
    *,
    existing: Dict[str, Any] | None = None,
    auth_user_id: str = "",
    manager: Dict[str, Any] | None = None,
    department_head: Dict[str, Any] | None = None,
    source_revision: int = 0,
    event_id: str = "",
) -> Tuple[Dict[str, Any], str]:
    profile = source["profile"]
    projection_state = roster_text(source.get("projection_state")) or "active"
    status_by_state = {"active": "啟用", "pending": "待啟用", "inactive": "停用"}
    if projection_state not in status_by_state:
        raise FinanceBridgeContractError("finance_identity_state_invalid")
    if isinstance(source_revision, bool) or not isinstance(source_revision, int) or source_revision < 0:
        raise FinanceBridgeContractError("finance_identity_revision_invalid")
    values: Dict[str, Any] = {
        "account_source": "finance",
        "logging_account_id": source["finance_user_id"],
        "logging_role_key": profile["logging_role_key"],
        "finance_employee_id": source["finance_user_id"],
        "company_id": company["id"],
        "company_name": company["name"],
        "company_address": company.get("address") or "",
        "external_account_payload_json": json.dumps({
            **metadata,
            "financeProfile": {
                "departmentName": source.get("department_name") or "",
                "jobTitle": source.get("job_title") or "",
                "extension": source.get("extension") or "",
                "contactEmail": source.get("contact_email") or "",
            },
        }, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
        "last_synced_from_logging_at": now(),
        "name": source["name"],
        "email": source["email"],
        "unit": source.get("department_name") or source["department_code"],
        "title": source.get("job_title") or source["role_label"],
        "job_level": profile["job_level"],
        "role": profile["role"],
        "provider": "Finance Google SSO",
        "mfa_status": "由 Finance 管理",
        "status": status_by_state[projection_state],
        "finance_source_status": projection_state,
    }
    # Finance and eDoc use separate Supabase Auth projects.  A Finance Auth UUID
    # is valid evidence inside the signed handoff, but is not a valid foreign
    # key to eDoc auth.users.  Preserve an existing local eDoc binding; clear it
    # only when the canonical Finance email changes and requires re-verification.
    if existing and roster_text(existing.get("email")).lower() != source["email"]:
        # Email changes require a fresh verified Google handoff before binding.
        values["auth_user_id"] = None
    if source.get("source_updated_at"):
        values["finance_source_updated_at"] = source["source_updated_at"]
    if source_revision:
        values["finance_source_revision"] = source_revision
        values["finance_source_event_id"] = roster_text(event_id)
    if manager:
        values.update({
            "manager_employee_id": manager["finance_user_id"],
            "manager_name": manager["name"],
            "manager_email": manager["email"],
            "manager_role_key": manager["profile"]["logging_role_key"],
        })
    if department_head:
        values.update({
            "approval_manager_employee_id": department_head["finance_user_id"],
            "approval_manager_name": department_head["name"],
            "approval_manager_email": department_head["email"],
            "approval_manager_role_key": department_head["profile"]["logging_role_key"],
        })
    if existing:
        current_revision = int(existing.get("finance_source_revision") or 0)
        if source_revision and source_revision <= current_revision:
            return existing, "stale"
        if source_revision:
            query = urllib.parse.urlencode({
                "id": f"eq.{existing['id']}",
                "finance_source_revision": f"eq.{current_revision}",
            })
            rows = supabase_request("PATCH", f"users?{query}", values)
            if rows:
                return rows[0], "applied"
            latest = supabase_get("users", existing["id"])
            if latest and int(latest.get("finance_source_revision") or 0) >= source_revision:
                return latest, "stale"
            raise FinanceBridgeUnavailable("finance_identity_revision_conflict")
        return supabase_patch("users", existing["id"], values), "applied"
    user_id = f"FIN-{hashlib.sha256(source['finance_user_id'].encode('utf-8')).hexdigest()[:12].upper()}"
    try:
        return supabase_insert("users", {
            "id": user_id,
            **values,
            "created_at": now(),
        }), "applied"
    except RuntimeError:
        candidate = _supabase_finance_snapshot_user_candidate(source)
        if candidate and source_revision and int(candidate.get("finance_source_revision") or 0) >= source_revision:
            return candidate, "stale"
        raise


def _sync_supabase_finance_snapshot(
    snapshot: Dict[str, Any],
    *,
    auth_user_id: str = "",
    expected_user_id: str = "",
    require_workflow: bool = False,
    required_step_keys: Iterable[str] = (),
    require_launch_scope: bool = True,
) -> Tuple[Dict[str, Any], Dict[str, Dict[str, Any]], Dict[str, str]]:
    required_step_keys = tuple(required_step_keys)
    normalized = normalize_finance_bridge_snapshot(
        snapshot,
        require_workflow=require_workflow,
        required_step_keys=required_step_keys,
    )
    company_cache: Dict[Tuple[str, bool], Dict[str, Any]] = {}

    def company_for(entity_id: str, *, require_launch_scope: bool) -> Dict[str, Any]:
        cache_key = (entity_id, require_launch_scope)
        if cache_key not in company_cache:
            company_cache[cache_key] = supabase_finance_company_by_entity(
                entity_id,
                require_launch_scope=require_launch_scope,
            )
        return company_cache[cache_key]

    applicant = normalized["applicant"]
    actor_sources = normalized["actors"]
    # Resolve identity bindings before the first company/user mutation.
    applicant_existing = _supabase_finance_snapshot_user_candidate(applicant)
    actor_existing = {
        slot: _supabase_finance_snapshot_user_candidate(actor)
        for slot, actor in actor_sources.items()
    }
    snapshot_company = snapshot["company"]
    applicant_company, company_disposition = supabase_upsert_finance_company_snapshot(
        snapshot_company,
        update_existing=False,
    )
    if roster_text(applicant_company.get("status")).lower() not in {"active", "啟用"}:
        # A revisioned company.changed event outranks the unversioned company
        # snapshot embedded in member/JIT payloads. Never activate a member in
        # a company that the company projection already marks inactive.
        applicant["projection_state"] = "inactive"
        applicant["auth_user_id"] = ""
        auth_user_id = ""
    company_cache[(applicant["entity_id"], False)] = applicant_company
    if require_launch_scope:
        applicant_company = company_for(applicant["entity_id"], require_launch_scope=True)
    else:
        company_cache[(applicant["entity_id"], False)] = applicant_company
    for actor in actor_sources.values():
        company_for(actor["entity_id"], require_launch_scope=False)

    company_cache[(applicant["entity_id"], True)] = applicant_company
    company_cache[(applicant["entity_id"], False)] = applicant_company

    actor_users: Dict[str, Dict[str, Any]] = {}
    actor_dispositions: Dict[str, str] = {}
    event_id = roster_text(snapshot.get("eventId"))
    for slot, actor in actor_sources.items():
        actor_source_revision = int(actor.get("source_revision") or 0)
        actor_user, actor_disposition = _supabase_upsert_finance_snapshot_user(
            actor,
            company_for(actor["entity_id"], require_launch_scope=False),
            normalized["metadata"],
            existing=actor_existing[slot],
            source_revision=actor_source_revision,
            event_id=event_id,
        )
        actor_users[slot] = actor_user
        actor_dispositions[slot] = actor_disposition
        if actor_disposition == "applied":
            supabase_upsert_finance_module_link(
                actor_user,
                actor,
                sync_status="active",
                event_id=event_id,
                source_revision=actor_source_revision,
            )
        actor_user, actor_company_inactive = supabase_enforce_finance_company_state(
            actor_user,
            actor,
            company_for(actor["entity_id"], require_launch_scope=False),
            event_id=event_id,
            source_revision=actor_source_revision,
        )
        if actor_company_inactive:
            actor_dispositions[slot] = "inactive"
        actor_users[slot] = actor_user
    source_revision = int(applicant.get("source_revision") or 0)
    user, user_disposition = _supabase_upsert_finance_snapshot_user(
        applicant,
        applicant_company,
        normalized["metadata"],
        existing=applicant_existing,
        auth_user_id=auth_user_id,
        manager=actor_sources.get("applicantManager"),
        department_head=actor_sources.get("departmentHead"),
        source_revision=source_revision,
        event_id=event_id,
    )
    if user_disposition == "applied":
        supabase_upsert_finance_module_link(
            user,
            applicant,
            sync_status=applicant["projection_state"],
            event_id=event_id,
            source_revision=source_revision,
        )
        if applicant["projection_state"] != "active":
            supabase_update_many(
                "auth_sessions",
                {"user_id": user["id"], "revoked_at": "__is_null__"},
                {"revoked_at": now()},
            )
    user, company_inactive = supabase_enforce_finance_company_state(
        user,
        applicant,
        applicant_company,
        event_id=event_id,
        source_revision=source_revision,
    )
    if company_inactive:
        applicant["projection_state"] = "inactive"
    if expected_user_id and user.get("id") != expected_user_id:
        raise FinanceBridgeDenied("finance_identity_mismatch")
    required_plan_keys = set(required_step_keys)
    plan = {
        step_key: actor_users[slot]
        for step_key, slot in FINANCE_BRIDGE_ACTOR_SLOTS.items()
        if slot in actor_users and (not require_workflow or step_key in required_plan_keys)
    }
    plan["applicant_confirm"] = user
    return user, plan, {
        "user": user_disposition,
        "company": company_disposition,
        "projection": applicant["projection_state"],
        **{f"actor:{slot}": disposition for slot, disposition in actor_dispositions.items()},
    }


def sync_supabase_finance_snapshot(
    snapshot: Dict[str, Any],
    *,
    auth_user_id: str = "",
    expected_user_id: str = "",
    require_workflow: bool = False,
    required_step_keys: Iterable[str] = (),
) -> Tuple[Dict[str, Any], Dict[str, Dict[str, Any]]]:
    """JIT adapter over the same revisioned projection used by background sync."""
    user, plan, _ = _sync_supabase_finance_snapshot(
        snapshot,
        auth_user_id=auth_user_id,
        expected_user_id=expected_user_id,
        require_workflow=require_workflow,
        required_step_keys=required_step_keys,
        require_launch_scope=True,
    )
    return user, plan


def sync_supabase_finance_login_snapshot(
    snapshot: Dict[str, Any],
    *,
    portal_authenticated: bool = False,
) -> Dict[str, Any]:
    """Refresh only the applicant projection needed to enter the eDoc shell.

    Approval actors are synchronized by the durable Finance outbox and are
    revalidated again when a document is submitted.  Re-upserting every actor
    during an ordinary login added many sequential database round trips while
    providing no extra authority for shell entry.
    """
    normalized = normalize_finance_bridge_snapshot(snapshot)
    applicant = normalized["applicant"]
    # The common Portal and Finance use separate Supabase Auth namespaces.
    # A signed Portal handoff is the Google authentication evidence for eDoc;
    # an otherwise active Finance employee must not be forced to pre-bind a
    # second Auth UUID before their first eDoc visit.
    if portal_authenticated and applicant["projection_state"] == "pending":
        applicant["projection_state"] = "active"
    actor_sources = normalized["actors"]
    existing = _supabase_finance_snapshot_user_candidate(applicant)
    company, _ = supabase_upsert_finance_company_snapshot(
        snapshot["company"],
        update_existing=False,
    )
    if roster_text(company.get("finance_entity_id")) != applicant["entity_id"]:
        raise FinanceBridgeDenied("finance_company_identity_conflict")
    if roster_text(company.get("status")).lower() not in {"active", "啟用"}:
        applicant["projection_state"] = "inactive"
    if (
        is_production()
        and launch_company_scope_mode() == "manual_allowlist"
        and not launch_company_scope_ids()
    ):
        raise FinanceBridgeDenied("finance_company_launch_scope_required")
    if not launch_company_in_scope(roster_text(company.get("id"))):
        raise FinanceBridgeDenied("finance_company_outside_launch_scope")

    source_revision = int(applicant.get("source_revision") or 0)
    event_id = roster_text(snapshot.get("eventId"))
    user, disposition = _supabase_upsert_finance_snapshot_user(
        applicant,
        company,
        normalized["metadata"],
        existing=existing,
        manager=actor_sources.get("applicantManager"),
        department_head=actor_sources.get("departmentHead"),
        source_revision=source_revision,
        event_id=event_id,
    )
    portal_promoted = (
        portal_authenticated
        and applicant["projection_state"] == "active"
        and user.get("status") != "啟用"
    )
    if portal_promoted:
        user = supabase_patch("users", user["id"], {
            "status": "啟用",
            "finance_source_status": "active",
            "last_synced_from_logging_at": now(),
        })
    if disposition == "applied" or portal_promoted:
        supabase_upsert_finance_module_link(
            user,
            applicant,
            sync_status=applicant["projection_state"],
            event_id=event_id,
            source_revision=source_revision,
        )
    user, company_inactive = supabase_enforce_finance_company_state(
        user,
        applicant,
        company,
        event_id=event_id,
        source_revision=source_revision,
    )
    if company_inactive or applicant["projection_state"] != "active" or user.get("status") != "啟用":
        raise FinanceBridgeDenied("finance_identity_inactive")
    return user


def claim_supabase_finance_member_sync_nonce(verified: Dict[str, Any]) -> bool:
    """Atomically consume one authenticated Finance sync nonce."""
    current_timestamp = int(time.time())
    try:
        supabase_request(
            "DELETE",
            "finance_member_sync_nonces?" + urllib.parse.urlencode({
                "expires_at": f"lt.{current_timestamp - FINANCE_MEMBER_SYNC_MAX_AGE_SECONDS}",
            }),
        )
    except RuntimeError:
        # Expiry cleanup is best effort; uniqueness still enforces replay safety.
        pass
    row = {
        "nonce_hash": verified["nonceHash"],
        "issued_at": int(verified["timestamp"]),
        "expires_at": int(verified["timestamp"]) + FINANCE_MEMBER_SYNC_MAX_AGE_SECONDS,
        "consumed_at": now(),
    }
    try:
        supabase_request("POST", "finance_member_sync_nonces", row)
        return True
    except RuntimeError:
        rows = supabase_filter_rows(
            "finance_member_sync_nonces",
            {"nonce_hash": verified["nonceHash"]},
            limit=1,
        )
        if rows:
            return False
        raise


def supabase_finance_sync_receipt(event_id: str) -> Dict[str, Any] | None:
    rows = supabase_filter_rows("finance_member_sync_receipts", {"event_id": event_id}, limit=1)
    return rows[0] if rows else None


def supabase_record_finance_sync_receipt(
    payload: Dict[str, Any],
    payload_sha256: str,
    *,
    apply_status: str,
    result_code: str,
    user_id: str = "",
    company_id: str = "",
) -> Dict[str, Any]:
    event_id = roster_text(payload.get("eventId"))
    existing = supabase_finance_sync_receipt(event_id)
    if existing and (
        existing.get("payload_sha256") != payload_sha256
        or int(existing.get("source_revision") or 0) != int(payload.get("sourceRevision") or 0)
        or existing.get("event_type") != payload.get("eventType")
    ):
        raise FinanceBridgeDenied("finance_member_sync_event_id_conflict")
    values = {
        "event_type": payload["eventType"],
        "source_revision": int(payload["sourceRevision"]),
        "finance_user_id": roster_text((payload.get("identity") or {}).get("financeUserId")) or None,
        "finance_entity_id": roster_text((payload.get("company") or {}).get("entityId")) or None,
        "projected_user_id": roster_text(user_id) or None,
        "projected_company_id": roster_text(company_id) or None,
        "payload_sha256": payload_sha256,
        "apply_status": apply_status,
        "result_code": result_code,
        "completed_at": now(),
    }
    if existing:
        # Never downgrade a successfully applied receipt because a concurrent
        # duplicate observed the new source revision and classified it stale.
        if existing.get("apply_status") == "applied" and apply_status != "applied":
            return existing
        query = urllib.parse.urlencode({"event_id": f"eq.{event_id}"})
        rows = supabase_request("PATCH", f"finance_member_sync_receipts?{query}", values)
        return rows[0] if rows else existing
    try:
        rows = supabase_request("POST", "finance_member_sync_receipts", {
            "event_id": event_id,
            **values,
            "received_at": now(),
        })
        return rows[0] if rows else {"event_id": event_id, **values}
    except RuntimeError:
        concurrent = supabase_finance_sync_receipt(event_id)
        if concurrent and concurrent.get("payload_sha256") == payload_sha256:
            return concurrent
        raise


def _supabase_deactivate_unsupported_finance_member(
    snapshot: Dict[str, Any],
    *,
    event_id: str,
    source_revision: int,
) -> Tuple[Dict[str, Any] | None, Dict[str, Any], str]:
    """Deactivate an old unsupported/system account without inventing a role."""
    identity = snapshot.get("identity") or {}
    source = {
        "finance_user_id": roster_text(identity.get("financeUserId")),
        "email": roster_text(identity.get("email")).lower(),
    }
    existing = _supabase_finance_snapshot_user_candidate(source)
    company, _ = supabase_upsert_finance_company_snapshot(
        snapshot.get("company") or {},
        update_existing=False,
    )
    if not existing:
        return None, company, "applied"
    current_revision = int(existing.get("finance_source_revision") or 0)
    if source_revision <= current_revision:
        return existing, company, "stale"
    values: Dict[str, Any] = {
        "account_source": "finance",
        "logging_account_id": source["finance_user_id"],
        "finance_employee_id": source["finance_user_id"],
        "company_id": company["id"],
        "company_name": company["name"],
        "company_address": company.get("address") or "",
        "name": roster_text(identity.get("name")) or existing.get("name") or source["finance_user_id"],
        "email": source["email"] or existing.get("email") or "",
        "unit": roster_text(identity.get("departmentName") or identity.get("unitName") or identity.get("departmentCode")),
        "title": roster_text(identity.get("jobTitle") or identity.get("roleLabel")) or existing.get("title") or "",
        "provider": "Finance Google SSO",
        "mfa_status": "由 Finance 管理",
        "status": "停用",
        "finance_source_status": "inactive",
        "finance_source_revision": source_revision,
        "finance_source_event_id": event_id,
        "finance_source_updated_at": roster_text(identity.get("sourceUpdatedAt")),
        "last_synced_from_logging_at": now(),
    }
    if roster_text(existing.get("email")).lower() != source["email"]:
        values["auth_user_id"] = None
    query = urllib.parse.urlencode({
        "id": f"eq.{existing['id']}",
        "finance_source_revision": f"eq.{current_revision}",
    })
    rows = supabase_request("PATCH", f"users?{query}", values)
    if not rows:
        latest = supabase_get("users", existing["id"])
        if latest and int(latest.get("finance_source_revision") or 0) >= source_revision:
            return latest, company, "stale"
        raise FinanceBridgeUnavailable("finance_identity_revision_conflict")
    user = rows[0]
    supabase_upsert_finance_module_link(
        user,
        {**source, "role": roster_text(identity.get("role"))},
        sync_status="inactive",
        event_id=event_id,
        source_revision=source_revision,
    )
    supabase_update_many(
        "auth_sessions",
        {"user_id": user["id"], "revoked_at": "__is_null__"},
        {"revoked_at": now()},
    )
    return user, company, "applied"


def _supabase_deactivate_unmapped_finance_member(
    snapshot: Dict[str, Any],
    *,
    event_id: str,
    source_revision: int,
) -> Tuple[Dict[str, Any], str]:
    """Persist an orphaned Finance identity without inventing a company.

    Finance can retain a historical personnel row whose ``entityId`` no
    longer exists in its canonical company master.  The row is still mirrored
    for audit/dedup purposes, but remains disabled with no company binding.
    Once Finance corrects the entity, the next revision follows the normal
    path and activates the same stable eDoc user automatically.
    """
    normalized = normalize_finance_bridge_snapshot(snapshot)
    applicant = normalized["applicant"]
    applicant["projection_state"] = "inactive"
    applicant["auth_user_id"] = ""
    existing = _supabase_finance_snapshot_user_candidate(applicant)
    user, disposition = _supabase_upsert_finance_snapshot_user(
        applicant,
        {"id": None, "name": "", "address": ""},
        normalized["metadata"],
        existing=existing,
        source_revision=source_revision,
        event_id=event_id,
    )
    if disposition == "applied":
        supabase_upsert_finance_module_link(
            user,
            applicant,
            sync_status="inactive",
            event_id=event_id,
            source_revision=source_revision,
        )
        supabase_update_many(
            "auth_sessions",
            {"user_id": user["id"], "revoked_at": "__is_null__"},
            {"revoked_at": now()},
        )
    return user, disposition


def supabase_apply_finance_member_sync_event(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Apply one validated member/company event using stable ids and revision CAS."""
    event_type = payload["eventType"]
    event_id = payload["eventId"]
    source_revision = int(payload["sourceRevision"])
    if event_type == "company.changed":
        company, disposition = supabase_upsert_finance_company_snapshot(
            payload["company"],
            source_revision=source_revision,
            event_id=event_id,
        )
        cascade = supabase_cascade_finance_company_projection(company)
        return {
            "status": disposition,
            "companyId": company.get("id") or "",
            **cascade,
        }

    snapshot = finance_member_event_snapshot(payload)
    identity = snapshot["identity"]
    company_missing = (
        "company_missing" in (payload.get("issues") or [])
        and not roster_text((snapshot.get("company") or {}).get("name"))
    )
    if company_missing:
        user, disposition = _supabase_deactivate_unmapped_finance_member(
            snapshot,
            event_id=event_id,
            source_revision=source_revision,
        )
        return {
            "status": disposition,
            "userId": user.get("id") or "",
            "companyId": "",
            "projectionState": "inactive",
        }
    source_probe = {
        "finance_user_id": roster_text(identity.get("financeUserId")),
        "email": roster_text(identity.get("email")).lower(),
    }
    existing = _supabase_finance_snapshot_user_candidate(source_probe)
    if existing and source_revision <= int(existing.get("finance_source_revision") or 0):
        companies = supabase_filter_rows(
            "companies",
            {"finance_entity_id": roster_text((snapshot.get("company") or {}).get("entityId"))},
            limit=1,
        )
        return {
            "status": "stale",
            "userId": existing.get("id") or "",
            "companyId": companies[0].get("id") if companies else "",
        }
    identity_active = identity.get("active") is True
    org_active = roster_text(identity.get("orgStatus")).lower() in {"active", "enabled", "啟用", "在職"}
    company_active = (snapshot.get("company") or {}).get("active", True) is not False
    finance_role = canonical_logging_role(identity.get("role"))
    force_inactive = finance_role == "system_account"
    if force_inactive or not identity_active or not org_active or not company_active:
        try:
            strict_finance_role_profile(identity.get("role"))
        except FinanceBridgeDenied:
            user, company, disposition = _supabase_deactivate_unsupported_finance_member(
                snapshot,
                event_id=event_id,
                source_revision=source_revision,
            )
            return {
                "status": disposition,
                "userId": (user or {}).get("id") or "",
                "companyId": company.get("id") or "",
            }
    user, _, dispositions = _sync_supabase_finance_snapshot(
        snapshot,
        require_launch_scope=False,
    )
    return {
        "status": dispositions["user"],
        "userId": user.get("id") or "",
        "companyId": user.get("company_id") or "",
        "projectionState": dispositions.get("projection") or roster_text(user.get("finance_source_status")) or (
            "inactive"
            if force_inactive
            else "active"
            if identity_active
            and org_active
            and company_active
            and identity.get("authUserBound") is True
            and identity.get("googleLoginVerified") is True
            else "pending"
            if identity_active and org_active and company_active
            else "inactive"
        ),
    }


def finance_member_sync_success_response(
    payload: Dict[str, Any],
    result: Dict[str, Any],
    *,
    status: str | None = None,
) -> Dict[str, Any]:
    """Build the pinned 200 response understood by old and new workers."""
    disposition = roster_text(status or result.get("status"))
    if disposition not in {"applied", "stale", "replayed"}:
        raise FinanceBridgeContractError("finance_member_sync_result_invalid")
    return {
        "ok": True,
        "eventId": payload["eventId"],
        "eventType": payload["eventType"],
        "sourceRevision": int(payload["sourceRevision"]),
        **result,
        "status": disposition,
        # Keep boolean compatibility for the first Finance worker while the
        # enum remains canonical. Exactly one status boolean is true.
        "applied": disposition == "applied",
        "stale": disposition == "stale",
        "replayed": disposition == "replayed",
    }


def supabase_resolve_preprovisioned_portal_user(source_user: Dict[str, Any]) -> Dict[str, Any]:
    """Atomically resolve/bind one active EDOC Finance row through a server-only RPC."""
    auth_user_id, email = portal_finance_identity(source_user)
    rows = supabase_request(
        "POST",
        "rpc/edoc_resolve_portal_finance_user",
        {"p_auth_user_id": auth_user_id, "p_email": email},
    )
    if not isinstance(rows, list):
        rows = [rows] if isinstance(rows, dict) else []
    candidate, _ = select_preprovisioned_finance_user(rows, auth_user_id, email)
    if roster_text(candidate.get("auth_user_id")) != auth_user_id:
        raise PortalFinanceIdentityDenied()
    return candidate


def supabase_authenticate_preprovisioned_logging_bridge(
    source_user: Dict[str, Any],
    ip: str,
    device: str,
) -> Tuple[Dict[str, Any], int]:
    """Create a session from signed Portal identity plus live Finance authority."""
    _portal_auth_user_id, email = portal_finance_identity(source_user)
    snapshot = current_finance_bridge_snapshot(email)
    user = sync_supabase_finance_login_snapshot(
        snapshot,
        portal_authenticated=True,
    )
    if user.get("role") not in ALLOWED_EDOC_ROLES:
        return {"error": "role_forbidden", "detail": "此 Finance 帳號未授權使用公文收發電子用印系統。"}, 403
    # One service-only RPC creates the session, updates verification time,
    # records the login event and returns exact RBAC permissions atomically.
    # The former four sequential Data API calls dominated cold-login latency.
    session = supabase_create_finance_login_session(user, ip, device)
    public_profile = session["user"]
    return {
        **session,
        "user": public_profile,
        "bridge": {
            "sourceSystem": "finance",
            "loggingAccountId": public_profile.get("logging_account_id") or public_profile.get("finance_employee_id") or public_profile["id"],
            "loggingRoleKey": public_profile.get("logging_role_key") or "",
            "targetModule": "edoc",
            "targetRole": public_profile.get("role") or "",
        },
    }, 200


def authenticate_verified_portal_handoff_supabase(
    source_user: Dict[str, Any],
    ip: str,
    device: str,
) -> Tuple[Dict[str, Any], int]:
    """Create an EDOC bearer session from a payload already verified and consumed."""
    if is_production():
        try:
            return supabase_authenticate_preprovisioned_logging_bridge(source_user, ip, device)
        except FinanceBridgeDenied as error:
            return {
                "error": "logging_bridge_denied",
                "detail": PORTAL_FINANCE_IDENTITY_ERROR,
                "_diagnostic": str(error),
            }, 403
        except FinanceBridgeUnavailable as error:
            return {
                "error": "logging_bridge_unavailable",
                "detail": "finance_bridge_unavailable",
                "_diagnostic": str(error),
            }, 503
        except PortalFinanceIdentityDenied:
            return {
                "error": "logging_bridge_denied",
                "detail": PORTAL_FINANCE_IDENTITY_ERROR,
                "_diagnostic": "portal_finance_identity_denied",
            }, 403
        except RuntimeError:
            return {
                "error": "logging_bridge_unavailable",
                "detail": "bridge_backend_unavailable",
                "_diagnostic": "bridge_backend_unavailable",
            }, 503
    return supabase_authenticate_logging_bridge(source_user, ip, device)


def supabase_authenticate_logging_bridge(payload: Dict[str, Any], ip: str, device: str) -> Tuple[Dict[str, Any], int]:
    try:
        source_user, error = extract_logging_bridge_user(payload)
        if error:
            return {"error": "logging_bridge_denied", "detail": error}, 403 if error in {"invalid_signature", "unsigned_bridge_payload", "portal_handoff_required"} else 400
        if is_production():
            return supabase_authenticate_preprovisioned_logging_bridge(source_user, ip, device)
        logging_role_key = canonical_logging_role(source_user.get("loggingRoleKey") or source_user.get("logging_role_key") or source_user.get("role"))
        profile = logging_role_profile(logging_role_key)
        email = roster_text(source_user.get("email")).lower()
        if not email:
            return {"error": "logging_bridge_denied", "detail": "missing_email"}, 400
        logging_account_id = roster_text(source_user.get("loggingAccountId") or source_user.get("logging_account_id") or source_user.get("id") or source_user.get("profileId") or email)
        display_name = roster_text(source_user.get("name") or source_user.get("display_name") or source_user.get("roleLabel") or email.split("@")[0])
        unit = roster_text(source_user.get("unit") or source_user.get("department") or source_user.get("departmentCode") or source_user.get("department_code") or profile["unit"])
        title = roster_text(source_user.get("title") or source_user.get("roleLabel") or profile["title"])
        job_level = normalize_edoc_job_level(source_user.get("jobLevel") or source_user.get("job_level") or profile["job_level"])
        edoc_role = profile["role"]
        finance_employee_id = roster_text(source_user.get("employeeNo") or source_user.get("employeeId") or source_user.get("employee_id"))
        company = finance_company_profile(source_user)
        manager = finance_manager_profile(source_user, "manager")
        approval_manager = finance_manager_profile(source_user, "approvalManager")
        if edoc_role not in ALLOWED_EDOC_ROLES:
            return {"error": "role_forbidden", "detail": "此 Finance 帳號未授權使用公文收發電子用印系統。"}, 403

        bridge_identity_terms = [f"logging_account_id.eq.{logging_account_id}", f"email.eq.{email}"]
        if finance_employee_id:
            bridge_identity_terms.insert(1, f"finance_employee_id.eq.{finance_employee_id}")
        qs = urllib.parse.urlencode({
            "select": "*",
            "or": f"({','.join(bridge_identity_terms)})",
            "limit": "1",
        })
        rows = supabase_request("GET", f"users?{qs}")
        user = rows[0] if rows else None
        ts = now()
        update_payload = {
            "auth_user_id": roster_text(source_user.get("authUserId") or source_user.get("auth_user_id")) or None,
            "account_source": "finance",
            "logging_account_id": logging_account_id,
            "logging_role_key": logging_role_key,
            "finance_employee_id": finance_employee_id,
            "company_id": company.get("id") or "",
            "company_name": company.get("name") or "",
            "company_address": company.get("address") or "",
            "manager_employee_id": manager.get("employee_id") or "",
            "manager_name": manager.get("name") or "",
            "manager_email": manager.get("email") or "",
            "manager_role_key": manager.get("role_key") or "",
            "approval_manager_employee_id": approval_manager.get("employee_id") or "",
            "approval_manager_name": approval_manager.get("name") or "",
            "approval_manager_email": approval_manager.get("email") or "",
            "approval_manager_role_key": approval_manager.get("role_key") or "",
            "external_account_payload_json": json.dumps(redact_sensitive(source_user), ensure_ascii=False),
            "last_synced_from_logging_at": ts,
            "name": display_name,
            "email": email,
            "unit": unit,
            "title": title,
            "job_level": job_level,
            "role": edoc_role,
            "provider": "Finance Google SSO",
            "mfa_status": "由 Finance 管理",
            "status": "啟用",
        }
        if user:
            user = supabase_patch("users", user["id"], update_payload)
        else:
            user = supabase_insert("users", {
                "id": f"LOG-{hashlib.sha256(logging_account_id.encode('utf-8')).hexdigest()[:10].upper()}",
                **update_payload,
            })

        supabase_upsert_finance_manager_placeholder(manager, source_user, company, ts)
        supabase_upsert_finance_manager_placeholder(approval_manager, source_user, company, ts)
        link_id = f"LINK-FINANCE-EDOC-{hashlib.sha256(logging_account_id.encode('utf-8')).hexdigest()[:10].upper()}"
        link_qs = urllib.parse.urlencode({
            "select": "*",
            "source_system": "eq.finance",
            "source_account_id": f"eq.{logging_account_id}",
            "target_module": "eq.edoc",
            "limit": "1",
        })
        links = supabase_request("GET", f"module_account_links?{link_qs}")
        link_payload = {
            "id": link_id,
            "user_id": user["id"],
            "source_system": "finance",
            "source_account_id": logging_account_id,
            "source_role_key": logging_role_key,
            "source_email": email,
            "target_module": "edoc",
            "target_role_key": edoc_role,
            "sync_status": "active",
            "metadata_json": {"source": "finance_google_sso"},
            "last_synced_at": ts,
        }
        if links:
            supabase_patch("module_account_links", links[0]["id"], link_payload)
        else:
            supabase_insert("module_account_links", link_payload)
        supabase_insert("audit_logs", {
            "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "actor": "Finance SSO Bridge",
            "action": "同步外部帳號",
            "target_type": "module_account_links",
            "target_id": link_id,
            "ip": ip,
            "device": device,
            "detail": f"{email} / {logging_role_key} → {edoc_role}",
            "event_type": "external_account_status_change",
            "severity": "critical",
            "result": "success",
            "module_code": "system_permissions",
            "resource_type": "external_account",
            "resource_id": link_id,
            "data_scope": "custom",
            "actor_roles_json": ["system_permissions.manage"],
            "target_user_id": user["id"],
            "target_email": email,
            "reason": "Finance Google 帳號進入公文收發電子用印系統，自動同步帳號、公司與主管關係。",
            "request_id": f"req_{secrets.token_hex(8)}",
            "before_snapshot_json": {},
            "after_snapshot_json": {"role": edoc_role, "job_level": job_level, "unit": unit, "logging_role_key": logging_role_key},
            "metadata_json": {"source_system": "finance", "target_module": "edoc", "logging_role_key": logging_role_key, "company_id": company.get("id") or ""},
        })
        token = secrets.token_urlsafe(36)
        expires = (datetime.now() + timedelta(hours=8)).strftime("%Y-%m-%d %H:%M:%S")
        supabase_insert("auth_sessions", {"id": f"SES-{int(time.time() * 1000)}", "user_id": user["id"], "token_hash": hash_token(token), "provider": "Finance Google SSO", "ip": ip, "device": device, "expires_at": expires})
        supabase_patch("users", user["id"], {"last_login_at": ts})
        supabase_insert("login_events", {"id": f"LOGIN-{int(time.time() * 1000)}", "user_id": user["id"], "email": email, "provider": "Finance Google SSO", "ip": ip, "device": device, "status": "成功", "reason": "沿用 Finance Google 帳號進入公文收發電子用印系統"})
        user.pop("password_hash", None)
        incoming_permissions = []
        if isinstance(payload.get("permissions"), list):
            incoming_permissions = payload["permissions"]
        elif isinstance(payload.get("user"), dict) and isinstance(payload["user"].get("permissions"), list):
            incoming_permissions = payload["user"]["permissions"]
        permissions = sorted(set(supabase_role_permissions(user.get("role", ""))) | set(logging_permissions_to_edoc_codes(incoming_permissions)))
        return {
            "token": token,
            "expiresAt": expires,
            "user": user,
            "permissions": permissions,
            "bridge": {
                "sourceSystem": "finance",
                "loggingAccountId": logging_account_id,
                "loggingRoleKey": logging_role_key,
                "targetModule": "edoc",
                "targetRole": edoc_role,
            },
        }, 200
    except FinanceBridgeDenied:
        return {"error": "logging_bridge_denied", "detail": PORTAL_FINANCE_IDENTITY_ERROR}, 403
    except FinanceBridgeUnavailable:
        return {"error": "logging_bridge_unavailable", "detail": "finance_bridge_unavailable"}, 503
    except PortalFinanceIdentityDenied:
        return {"error": "logging_bridge_denied", "detail": PORTAL_FINANCE_IDENTITY_ERROR}, 403
    except RuntimeError as error:
        detail = "bridge_backend_unavailable" if is_production() else str(error)
        return {"error": "logging_bridge_unavailable", "detail": detail}, 503


def finance_session_revalidation_due(
    user: Dict[str, Any],
    *,
    current_time: datetime | None = None,
) -> bool:
    """Return whether this session needs one fresh Finance authority check."""
    verified_at = parse_time(roster_text(user.get("last_synced_from_logging_at")))
    if verified_at == datetime.min:
        return True
    current = current_time or datetime.now()
    age_seconds = (current - verified_at).total_seconds()
    return age_seconds < -300 or age_seconds >= EDOC_FINANCE_SESSION_REVALIDATE_SECONDS


def supabase_current_session(token: str) -> Dict[str, Any] | None:
    if not token:
        return None
    token_hash = hash_token(token)
    try:
        bundle = _supabase_login_bundle(
            supabase_request(
                "POST",
                "rpc/edoc_resolve_finance_session_v1",
                {"p_token_hash": token_hash},
            )
        )
    except RuntimeError as error:
        if not _supabase_login_rpc_missing(error):
            raise
        # Safe rollback compatibility for deployments briefly running against
        # the prior schema. Installed RPC failures never take this branch.
        qs = urllib.parse.urlencode({"select": "*", "token_hash": f"eq.{token_hash}", "revoked_at": "is.null", "limit": "1"})
        sessions = supabase_request("GET", f"auth_sessions?{qs}")
        if not sessions or sessions[0].get("expires_at", "") <= now():
            return None
        user = supabase_get("users", sessions[0]["user_id"])
        if not user:
            return None
        bundle = {
            "session": sessions[0],
            "user": user,
            "permissions": supabase_role_permissions(user.get("role", "")),
        }
    if not bundle:
        return None
    session_row = bundle["session"]
    user = bundle["user"]
    permissions = bundle["permissions"]
    identity_invalid = (
        user.get("status") != "啟用"
        or user.get("role") not in ALLOWED_EDOC_ROLES
        or (
            is_production()
            and (
                str(user.get("account_source") or "").strip().lower() != "finance"
                # Finance and eDoc are separate Supabase Auth projects. The
                # Finance UUID is verified during the signed handoff, but it
                # must not be required as an eDoc auth.users foreign key.
                or not str(user.get("logging_account_id") or user.get("finance_employee_id") or "").strip()
                or not str(user.get("company_id") or "").strip()
            )
        )
    )
    if identity_invalid:
        supabase_patch("auth_sessions", session_row["id"], {"revoked_at": now()})
        return None
    if is_production() and finance_session_revalidation_due(user):
        previous_role = user.get("role")
        try:
            snapshot = current_finance_bridge_snapshot(user.get("email") or "")
            refreshed = sync_supabase_finance_login_snapshot(
                snapshot,
                portal_authenticated=True,
            )
            if refreshed.get("id") != user.get("id"):
                raise FinanceBridgeDenied("finance_identity_mismatch")
            verified_at = now()
            user = supabase_patch("users", user["id"], {
                "last_synced_from_logging_at": verified_at,
            })
            if user.get("role") != previous_role:
                permissions = supabase_role_permissions(user.get("role", ""))
        except FinanceBridgeDenied:
            supabase_patch("auth_sessions", session_row["id"], {"revoked_at": now()})
            return None
        except FinanceBridgeUnavailable:
            return None
    user.pop("password_hash", None)
    return {
        "sessionId": session_row["id"],
        "expiresAt": session_row["expires_at"],
        "user": user,
        "permissions": permissions,
    }


def supabase_dashboard() -> Dict[str, Any]:
    documents = supabase_list("documents", {})
    tasks = supabase_list("exchange_tasks", {})
    audits = supabase_list("audit_logs", {})
    complete = [item for item in tasks if "完成" in item.get("status", "") or "確認" in item.get("status", "")]
    return {
        "documents": len(documents),
        "inboundPending": len([item for item in documents if item.get("direction") == "收文" and item.get("status") in {"待登錄", "待分派"}]),
        "dispatchPending": len([item for item in documents if item.get("direction") == "發文" and item.get("status") in {"草稿", "待清稿", "已清稿"}]),
        "exchangeTasks": len(tasks),
        "exchangeFailed": len([item for item in tasks if "失敗" in item.get("status", "")]),
        "successRate": round((len(complete) / len(tasks)) * 100, 1) if tasks else 100,
        "auditLogs": len(audits),
    }


