def supabase_exchange_outboxes(filters: Dict[str, str]) -> List[Dict[str, Any]]:
    params = {"select": "*", "limit": "500", **filters}
    qs = urllib.parse.urlencode(params)
    return supabase_request("GET", f"exchange_outbox?{qs}")


def supabase_exchange_queue_document(payload: Dict[str, Any]) -> Dict[str, Any]:
    document_id = payload.get("document_id")
    if not document_id:
        raise ValueError("document_id is required")
    existing = supabase_exchange_outboxes({"document_id": f"eq.{document_id}"})
    if existing:
        return existing[0]
    document = supabase_get("documents", document_id)
    if not document:
        raise ValueError(f"document_not_found:{document_id}")
    outbox = {
        "id": f"EXOUT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "document_id": document_id,
        "doc_no": document.get("doc_no", ""),
        "target_agency": payload.get("target_agency") or document.get("agency_name", ""),
        "target_agency_code": payload.get("target_agency_code") or document.get("agency_code", ""),
        "status": "待發文",
        "provider": EDOC_EXCHANGE_PROVIDER,
        "environment": EDOC_EXCHANGE_ENV,
        "package_id": payload.get("package_id") or f"PKG-{document.get('doc_no', document_id)}",
        "external_id": "",
        "idempotency_key": payload.get("idempotency_key") or f"{document_id}:{document.get('doc_no', '')}",
        "retry_count": 0,
        "max_retries": int(payload.get("max_retries") or EDOC_EXCHANGE_MAX_RETRIES),
        "last_error_code": "",
        "last_error_message": "",
        "next_retry_at": "",
        "sent_at": "",
        "returned_at": "",
    }
    created = supabase_insert("exchange_outbox", outbox)
    supabase_exchange_history("outbox", created["id"], "", "待發文", "公文已加入交換待發佇列。", "QUEUED", {})
    return created


def supabase_exchange_send_document(payload: Dict[str, Any]) -> Dict[str, Any]:
    assert_formal_exchange_allowed(payload)
    outbox = supabase_get("exchange_outbox", payload.get("outbox_id") or payload.get("id") or "") if (payload.get("outbox_id") or payload.get("id")) else supabase_exchange_queue_document(payload)
    if not outbox:
        raise ValueError("outbox_not_found")
    document = supabase_get("documents", outbox["document_id"]) or {}
    metadata = json.loads(document.get("metadata_json") or "{}") if isinstance(document.get("metadata_json"), str) else document.get("metadata_json") or {}
    provider = MockExchangeProvider()
    package = {
        "outbox_id": outbox["id"],
        "document_id": outbox["document_id"],
        "doc_no": outbox.get("doc_no"),
        "subject": document.get("subject"),
        "target_agency": outbox.get("target_agency"),
        "target_agency_code": outbox.get("target_agency_code"),
        "metadata": metadata,
        "mock_scenario": payload.get("mock_scenario") or ("success" if payload.get("mock_retry_success") and outbox.get("status") in {"失敗", "退文"} else metadata.get("mock_exchange")),
        "mock_retry_success": payload.get("mock_retry_success", True),
    }
    result = provider.send_official_document(package)
    status = result.get("status") or ("已送出" if result.get("ok") else "失敗")
    patch_payload = {
        "status": status,
        "external_id": result.get("external_id") or outbox.get("external_id") or "",
        "last_error_code": result.get("error_code", ""),
        "last_error_message": result.get("message", ""),
        "next_retry_at": (datetime.now() + timedelta(minutes=5)).strftime("%Y-%m-%d %H:%M:%S") if status == "失敗" else "",
        "sent_at": now() if status == "已送出" and not outbox.get("sent_at") else outbox.get("sent_at", ""),
    }
    updated = supabase_patch("exchange_outbox", outbox["id"], patch_payload)
    supabase_exchange_history("outbox", outbox["id"], outbox.get("status", ""), status, result.get("message", ""), result.get("provider_status", ""), result.get("summary", {}))
    supabase_exchange_log("outbox", outbox["id"], "sendOfficialDocument", "outbound", payload, result, "success" if result.get("ok") else "failed")
    return {"ok": bool(result.get("ok")), "item": updated, "provider": redact_sensitive(result)}


def supabase_exchange_query_status(payload: Dict[str, Any]) -> Dict[str, Any]:
    assert_formal_exchange_allowed(payload)
    outbox = supabase_get("exchange_outbox", payload.get("outbox_id") or payload.get("id") or "")
    if not outbox:
        return {"ok": False, "error": "outbox_not_found"}
    result = MockExchangeProvider().query_delivery_status(outbox)
    status = result.get("status") or outbox.get("status")
    patch_payload = {
        "status": status,
        "last_error_code": result.get("error_code", ""),
        "last_error_message": result.get("message", ""),
        "returned_at": now() if status == "退文" and not outbox.get("returned_at") else outbox.get("returned_at", ""),
    }
    updated = supabase_patch("exchange_outbox", outbox["id"], patch_payload)
    supabase_exchange_history("outbox", outbox["id"], outbox.get("status", ""), status, result.get("message", ""), result.get("provider_status", ""), result.get("summary", {}))
    supabase_exchange_log("outbox", outbox["id"], "queryDeliveryStatus", "outbound", payload, result, "success" if result.get("ok") else "failed")
    return {"ok": bool(result.get("ok")), "item": updated, "provider": redact_sensitive(result)}


def supabase_exchange_retry_failed(payload: Dict[str, Any]) -> Dict[str, Any]:
    assert_formal_exchange_allowed(payload)
    outbox = supabase_get("exchange_outbox", payload.get("outbox_id") or payload.get("id") or "")
    if not outbox:
        return {"ok": False, "error": "outbox_not_found"}
    retry_count = int(outbox.get("retry_count") or 0)
    max_retries = int(outbox.get("max_retries") or EDOC_EXCHANGE_MAX_RETRIES)
    if retry_count >= max_retries:
        updated = supabase_patch("exchange_outbox", outbox["id"], {"status": "已達重送上限"})
        return {"ok": False, "error": "retry_limit_reached", "item": updated}
    supabase_patch("exchange_outbox", outbox["id"], {"retry_count": retry_count + 1})
    return supabase_exchange_send_document({"outbox_id": outbox["id"], "mock_retry_success": payload.get("mock_retry_success", True)})


def supabase_exchange_receive_documents(payload: Dict[str, Any]) -> Dict[str, Any]:
    assert_formal_exchange_allowed(payload)
    provider = MockExchangeProvider()
    items = provider.receive_official_documents(payload)
    rows = []
    for item in items:
        doc = supabase_insert("documents", {
            "id": f"DOC-IN-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "doc_no": item.get("doc_no"),
            "direction": "收文",
            "doc_type": item.get("doc_type", "函"),
            "priority": item.get("priority", "普通件"),
            "security_level": item.get("security_level", "普通"),
            "agency_name": item.get("source_agency", ""),
            "agency_code": item.get("source_agency_code", ""),
            "subject": item.get("subject", ""),
            "body": item.get("body", ""),
            "status": "待登錄",
            "owner": "總務",
            "department": "總管理處",
            "due_date": (datetime.now() + timedelta(days=7)).strftime("%Y-%m-%d"),
            "received_at": now(),
        })
        inbox = supabase_insert("exchange_inbox", {
            "id": f"EXIN-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "document_id": doc["id"],
            "external_id": item["external_id"],
            "source_agency": item.get("source_agency", ""),
            "source_agency_code": item.get("source_agency_code", ""),
            "doc_no": item.get("doc_no", ""),
            "subject": item.get("subject", ""),
            "status": "待確認",
            "provider": EDOC_EXCHANGE_PROVIDER,
            "environment": EDOC_EXCHANGE_ENV,
            "received_at": now(),
            "acknowledged_at": "",
            "raw_summary_json": item.get("summary", {}),
        })
        supabase_exchange_history("inbox", inbox["id"], "", "待確認", "Mock 收文已寫入待確認。", "MOCK_RECEIVED", item.get("summary", {}))
        supabase_exchange_log("inbox", inbox["id"], "receiveOfficialDocuments", "inbound", payload, item, "success")
        rows.append(inbox)
    return {"count": len(rows), "items": rows}


def supabase_exchange_acknowledge_received(payload: Dict[str, Any]) -> Dict[str, Any]:
    inbox = supabase_get("exchange_inbox", payload.get("inbox_id") or payload.get("id") or "")
    if not inbox:
        return {"ok": False, "error": "inbox_not_found"}
    result = MockExchangeProvider().acknowledge_received(inbox)
    updated = supabase_patch("exchange_inbox", inbox["id"], {"status": "已入案", "acknowledged_at": now()})
    if inbox.get("document_id"):
        supabase_patch("documents", inbox["document_id"], {"status": "待分派"})
    supabase_exchange_history("inbox", inbox["id"], inbox.get("status", ""), "已入案", result.get("message", ""), result.get("provider_status", ""), result.get("summary", {}))
    supabase_exchange_log("inbox", inbox["id"], "acknowledgeReceived", "inbound", payload, result, "success")
    return {"ok": True, "item": updated, "provider": redact_sensitive(result)}


def supabase_next_run(schedule_text: str) -> str:
    return compute_next_run_at(schedule_text)


def supabase_execute_job_logic(job: Dict[str, Any]) -> Dict[str, Any]:
    job_type = job["job_type"]
    if job_type == "pullInbound":
        result = supabase_exchange_receive_documents({})
        return {"message": f"成功：拉取 {result.get('count', 0)} 筆收文", "payload": result}
    if job_type == "exchangeSendPending":
        assert_formal_exchange_allowed({})
        outboxes = [item for item in supabase_list("exchange_outbox", {"status": ["待發文"]})[:20]]
        results = [supabase_exchange_send_document({"outbox_id": item["id"]}) for item in outboxes]
        return {"message": f"成功：送出 {len(results)} 筆待發交換公文", "payload": {"count": len(results), "results": results}}
    if job_type == "exchangeRetryFailed":
        assert_formal_exchange_allowed({})
        candidates = []
        for status_text in ["失敗", "退文"]:
            candidates.extend(supabase_list("exchange_outbox", {"status": [status_text]}))
        due = [
            item for item in candidates
            if int(item.get("retry_count") or 0) < int(item.get("max_retries") or EDOC_EXCHANGE_MAX_RETRIES)
            and (not item.get("next_retry_at") or item.get("next_retry_at") <= now())
        ][:20]
        results = [supabase_exchange_retry_failed({"outbox_id": item["id"]}) for item in due]
        return {"message": f"成功：重送 {len(results)} 筆交換失敗公文", "payload": {"count": len(results), "results": results}}
    if job_type == "tokenCheck":
        sessions = supabase_list("auth_sessions", {})
        expiring_before = (datetime.now() + timedelta(hours=1)).strftime("%Y-%m-%d %H:%M:%S")
        active = [item for item in sessions if not item.get("revoked_at") and item.get("expires_at", "") > now()]
        expiring = [item for item in active if item.get("expires_at", "") <= expiring_before]
        return {"message": f"成功：有效 session {len(active)}，1 小時內到期 {len(expiring)}", "payload": {"active_sessions": len(active), "expiring": len(expiring)}}
    if job_type == "nextDayCheck":
        tasks = supabase_list("exchange_tasks", {})
        checked = 0
        for task in [item for item in tasks if item.get("direction") == "發文"]:
            checked += 1
            status = task.get("status") if task.get("status") in {"交換失敗", "退回補正"} else "已確認收文"
            supabase_patch("exchange_tasks", task["id"], {"status": status, "next_check_at": compute_next_run_at("每日 09:00")})
            supabase_insert("exchange_events", {
                "id": f"EVT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
                "task_id": task["id"],
                "document_id": task.get("document_id"),
                "event_type": "next_day_check",
                "message": "Vercel Cron 完成發文翌日查核。",
                "payload_json": "{}",
            })
        return {"message": f"成功：完成 {checked} 筆發文翌日查核", "payload": {"checked": checked}}
    if job_type == "exchangeSync":
        assert_formal_exchange_allowed({})
        sent_outboxes = supabase_list("exchange_outbox", {"status": ["已送出"]})
        gateway_results = [supabase_exchange_query_status({"outbox_id": item["id"]}) for item in sent_outboxes[:50]]
        tasks = supabase_list("exchange_tasks", {})
        for task in tasks:
            supabase_insert("exchange_events", {
                "id": f"EVT-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
                "task_id": task["id"],
                "document_id": task.get("document_id"),
                "event_type": "status_sync",
                "message": f"Vercel Cron 同步交換狀態：{task.get('status')}",
                "payload_json": json.dumps({"status": task.get("status")}, ensure_ascii=False),
            })
        return {"message": f"成功：同步 {len(gateway_results)} 筆新介接層狀態，保留 {len(tasks)} 筆舊交換事件", "payload": {"synced": len(gateway_results), "results": gateway_results, "legacyEvents": len(tasks)}}
    if job_type == "overdueReminder":
        documents = supabase_list("documents", {})
        today = datetime.now().strftime("%Y-%m-%d")
        overdue = [item for item in documents if item.get("due_date") and item.get("due_date") < today and "完成" not in item.get("status", "")]
        for doc in overdue:
            supabase_insert("audit_logs", {
                "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
                "actor": "Vercel Cron",
                "action": "逾期稽催",
                "target_type": "documents",
                "target_id": doc["id"],
                "ip": "vercel",
                "device": "cron",
                "detail": f"{doc.get('doc_no')} / {doc.get('owner')} / {doc.get('due_date')}",
            })
        return {"message": f"成功：產生 {len(overdue)} 筆逾期稽催紀錄", "payload": {"overdue": len(overdue)}}
    if job_type == "contractRenewalCheck":
        contracts = supabase_list("contracts", {})
        today = datetime.now().date()
        due_contracts = []
        notified = 0
        for contract in contracts:
            if not contract.get("end_date") or contract.get("status") in {"已終止", "已作廢"}:
                continue
            end_date = parse_time(contract.get("end_date", "")).date()
            days_left = (end_date - today).days
            alert_days = int(contract.get("renewal_alert_days") or 60)
            if 0 <= days_left <= alert_days:
                due_contracts.append(contract)
                target = exact_supabase_notification_target_from_metadata(
                    contract.get("metadata_json")
                )
                if not target:
                    log_structured(
                        "warning",
                        "contract_renewal_notification_skipped",
                        contract_id=contract.get("id") or "",
                        error="notification_exact_target_required",
                    )
                    continue
                notice = supabase_create_notification({
                    "type": "合約續約",
                    "title": f"{contract.get('title')} 即將到期",
                    **exact_notification_target_payload(target, target.get("company_id") or ""),
                    "channel": "Email + 系統通知",
                    "priority": "高" if days_left <= 30 else "中",
                    "source": contract.get("contract_no"),
                    "body": f"{contract.get('counterparty')} 合約將於 {contract.get('end_date')} 到期，剩餘 {days_left} 天，請確認續約、重簽或終止。",
                })
                notified += 1
                supabase_insert("audit_logs", {
                    "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
                    "actor": "Vercel Cron",
                    "action": "合約續約提醒",
                    "target_type": "contracts",
                    "target_id": contract["id"],
                    "ip": "vercel",
                    "device": "cron",
                    "detail": notice["id"],
                })
        skipped = len(due_contracts) - notified
        return {
            "message": f"成功：找到 {len(due_contracts)} 筆到期合約，精準投遞 {notified} 筆，略過 {skipped} 筆未綁定對象資料。",
            "payload": {
                "dueContracts": len(due_contracts),
                "notified": notified,
                "skipped": skipped,
            },
        }
    if job_type == "reportGenerate":
        report = supabase_dashboard()
        supabase_request("POST", "settings?on_conflict=key", {
            "key": "latest_report",
            "value_json": json.dumps({"generated_at": now(), **report}, ensure_ascii=False),
            "version": 1,
            "updated_at": now(),
        }, prefer="resolution=merge-duplicates,return=representation")
        return {"message": f"成功：報表已產生，公文 {report['documents']} 件，交換成功率 {report['successRate']}%", "payload": report}
    if job_type == "archiveSeal":
        return {"message": "成功：Supabase Storage 歸檔檢查已排程，正式檔案桶接入後執行雜湊抽查", "payload": {"storage": "pending_bucket"}}
    return {"message": f"成功：{job_type} 無額外動作", "payload": {}}


def supabase_run_background_job(job_id: str) -> Dict[str, Any]:
    job = supabase_get("background_jobs", job_id)
    if not job:
        return {"error": "not_found", "job_id": job_id}
    if job.get("status") != "啟用":
        return {"id": job_id, "status": "skipped", "result": "任務未啟用"}
    started = datetime.now()
    run_id = f"RUN-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    try:
        result = supabase_execute_job_logic(job)
        status = "成功"
        message = result["message"]
        payload = result.get("payload", {})
    except Exception as exc:
        status = "失敗"
        message = str(exc)
        payload = {"error": message}
    finished = datetime.now()
    duration_ms = int((finished - started).total_seconds() * 1000)
    next_run = supabase_next_run(job["schedule_text"])
    supabase_insert("job_runs", {
        "id": run_id,
        "job_id": job_id,
        "job_type": job["job_type"],
        "status": status,
        "result": message,
        "started_at": started.strftime("%Y-%m-%d %H:%M:%S"),
        "finished_at": finished.strftime("%Y-%m-%d %H:%M:%S"),
        "duration_ms": duration_ms,
        "payload_json": json.dumps(payload, ensure_ascii=False),
    })
    supabase_patch("background_jobs", job_id, {
        "last_result": f"{status}：{message}",
        "next_run_at": next_run,
        "run_count": int(job.get("run_count") or 0) + 1,
    })
    return {"run_id": run_id, "job_id": job_id, "status": status, "result": message, "next_run_at": next_run, "duration_ms": duration_ms, "payload": payload}


def supabase_run_due_background_jobs(all_enabled: bool = False) -> Dict[str, Any]:
    jobs = supabase_list("background_jobs", {})
    if not all_enabled:
        jobs = [job for job in jobs if job.get("status") == "啟用" and (job.get("next_run_at") or "") <= now()]
    else:
        jobs = [job for job in jobs if job.get("status") == "啟用"]
    jobs.sort(key=lambda item: item.get("next_run_at") or "")
    results = [supabase_run_background_job(job["id"]) for job in jobs]
    return {"count": len(results), "results": results}


def supabase_notification_credential_status(channel: str, rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    credential = next((row for row in rows if row.get("channel") == channel), {"channel": channel, "status": "未設定"})
    required = channel_required_env(channel)
    if channel == "Line 工作群組" and not env_present("LINE_WEBHOOK_URL"):
        missing = [] if env_present("LINE_CHANNEL_ACCESS_TOKEN") and env_present("LINE_TARGET_ID") else required
    else:
        missing = [name for name in required if env_present(name) is False]
    expires_at = credential.get("expires_at") or ""
    expiry = parse_time(expires_at) if expires_at else datetime.max
    days_left = None if expiry == datetime.max else (expiry - datetime.now()).days
    if missing:
        status = "缺少環境憑證"
    elif expiry < datetime.now():
        status = "已到期"
    elif days_left is not None and days_left <= 14:
        status = "即將到期"
    else:
        status = "有效"
    return {**credential, "channel": channel, "status": status, "missing": missing, "days_left": days_left, "ok": status == "有效"}


def supabase_monitoring_snapshot() -> Dict[str, Any]:
    readiness = production_readiness()
    alerts: List[Dict[str, str]] = []
    for name in readiness["missing"]:
        append_alert(alerts, "critical" if is_production() else "warning", "ENV-MISSING", f"缺少正式環境變數 {name}", "到 Vercel Project Settings 補齊後重新部署。")
    for item in readiness["blockers"]:
        append_alert(alerts, "critical", "READINESS-BLOCKER", item, "先處理 production readiness blocker，再開放正式交換。")
    for item in readiness["warnings"]:
        append_alert(alerts, "warning", "READINESS-WARNING", item, "排入上線前檢核清單，避免正式營運缺口。")

    exchange_tasks = supabase_list("exchange_tasks", {})
    deliveries = supabase_list("notification_deliveries", {})
    job_runs = supabase_list("job_runs", {"order": ["finished_at.desc"], "limit": ["20"]})
    documents = supabase_list("documents", {"limit": ["1000"]})
    attachments = supabase_list("attachments", {"limit": ["1000"]})
    credential_rows = supabase_list("notification_channel_credentials", {}) if "notification_channel_credentials" in TABLES else []
    credentials = [supabase_notification_credential_status(channel, credential_rows) for channel in ["Email", "Line 工作群組", "系統站內通知"]]

    counts = {
        "documents": len(documents),
        "attachments": len(attachments),
        "exchange_failed": len([item for item in exchange_tasks if item.get("status") in {"交換失敗", "失敗", "逾期未確認"}]),
        "notification_failed": len([item for item in deliveries if item.get("status") in {"失敗", "未設定", "憑證異常"}]),
        "job_failed": len([item for item in job_runs if item.get("status") in {"失敗", "錯誤"}]),
    }
    if counts["exchange_failed"]:
        append_alert(alerts, "critical", "EXCHANGE-FAILED", f"{counts['exchange_failed']} 筆交換任務失敗或逾期。", "由總務工作台重送或執行翌日查核。")
    if counts["notification_failed"]:
        append_alert(alerts, "warning", "NOTIFICATION-FAILED", f"{counts['notification_failed']} 筆通知派送失敗。", "到通知中心重送，並檢查 Email/Line 憑證。")
    if counts["job_failed"]:
        append_alert(alerts, "warning", "JOB-FAILED", f"{counts['job_failed']} 筆背景任務失敗。", "到背景任務頁查看 job_runs 與 API log。")

    last_job = job_runs[0] if job_runs else None
    last_job_age = age_minutes(last_job.get("finished_at") if last_job else None)
    if is_production() and (last_job_age is None or last_job_age > EDOC_MONITORING_EXPECTED_CRON_MINUTES + 120):
        append_alert(alerts, "critical", "CRON-STALLED", "正式環境背景排程超過預期時間未執行。", "檢查 Vercel Cron、CRON_SECRET 與 /api/cron/run-due 執行紀錄。")

    for credential in credentials:
        if credential.get("status") in {"缺少環境憑證", "已到期", "未設定"}:
            append_alert(alerts, "critical" if is_production() else "warning", "CREDENTIAL-INVALID", f"{credential['channel']} 憑證狀態：{credential.get('status')}", "補齊正式憑證、有效期限與環境變數後重新驗證。")
        elif credential.get("status") == "即將到期":
            append_alert(alerts, "warning", "CREDENTIAL-EXPIRING", f"{credential['channel']} 憑證即將到期。", "在到期前完成換證與驗證。")
    signing_service = signing_service_status()
    if signing_service["productionBlocked"]:
        append_alert(alerts, "critical", "SIGNING-SERVICE-INCOMPLETE", f"正式簽章服務尚未設定：{', '.join(signing_service['missing'])}", "設定 HSM/KMS、信任根憑證、TSA、OCSP、CRL 與 EDOC_SIGNING_SECRET 後重新部署。")
    elif not signing_service["ready"]:
        append_alert(alerts, "warning", "SIGNING-SERVICE-SIMULATION", f"簽章服務仍為模擬或不完整：{', '.join(signing_service['missing'])}", "正式上線前完成外部簽章服務接入。")
    storage_service = storage_service_status()
    if storage_service["productionBlocked"]:
        append_alert(alerts, "critical", "STORAGE-SERVICE-INCOMPLETE", f"正式檔案儲存與防毒尚未設定：{', '.join(storage_service['missing'])}", "設定 Supabase Storage private bucket、檔案加密、短效 URL、正式 AV endpoint/API key 後重新部署。")
    elif not storage_service["ready"]:
        append_alert(alerts, "warning", "STORAGE-SERVICE-SIMULATION", f"檔案儲存或防毒服務仍為本機/不完整：{', '.join(storage_service['missing'])}", "正式上線前完成物件儲存與防毒引擎接入。")

    checks = {
        "database": {"status": "ok", "mode": "supabase", "detail": SUPABASE_URL},
        "readiness": {"status": "ok" if readiness["ready"] else "needs_action", "missing": readiness["missing"], "blockers": readiness["blockers"]},
        "storage": {"status": "ok" if storage_service["ready"] else "needs_action", **storage_service},
        "cron": {"status": "ok" if last_job_age is not None else "not_yet_run", "lastRun": last_job, "ageMinutes": last_job_age},
        "notifications": {"status": "ok" if all(item.get("status") in {"有效", "即將到期"} for item in credentials) else "needs_action", "credentials": credentials},
        "signing": {"status": "ok" if signing_service["ready"] else "needs_action", **signing_service},
        "jAgent": {"status": "needs_action" if counts["exchange_failed"] else "ok", "failedTasks": counts["exchange_failed"]},
    }
    status = monitoring_status(alerts)
    return {
        "ok": status != "critical",
        "status": status,
        "checkedAt": now(),
        "deployment": deployment_report(),
        "checks": checks,
        "counts": counts,
        "alerts": alerts,
    }


def run_supabase_monitoring_check() -> Dict[str, Any]:
    snapshot = supabase_monitoring_snapshot()
    webhook = post_monitoring_webhook(snapshot) if snapshot["alerts"] else {"sent": False, "reason": "無告警"}
    log_structured("info", "production_monitoring_check", status=snapshot["status"], alerts=len(snapshot["alerts"]), webhook_sent=bool(webhook.get("sent")), runtime="vercel")
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": "Ops Monitor",
        "action": "正式部署監控檢查",
        "target_type": "production_monitoring",
        "target_id": snapshot["status"],
        "ip": "vercel",
        "device": "serverless",
        "detail": json.dumps({"alerts": snapshot["alerts"], "webhook": webhook}, ensure_ascii=False),
        "created_at": now(),
    })
    return {**snapshot, "webhook": webhook}


def stable_json_hash(value: Any) -> str:
    data = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return sha256_bytes(data)


COMPLIANCE_CONTROL_REQUIREMENTS = [
    ("C-001", "機關公文電子交換作業辦法", "收發文、交換事件、異常處理與留存可追蹤", ["documents", "exchange_events", "audit_logs"]),
    ("C-002", "公文電子交換系統資訊安全管理規範", "帳號、RBAC、憑證、Token、IP/裝置與操作留痕", ["users", "auth_sessions", "login_events", "audit_logs"]),
    ("C-003", "文書及檔案管理電腦化作業規範", "文號、附件清冊、PDF 套版、用印版本與歸檔保存", ["pdf_versions", "seal_assets", "file_objects"]),
    ("C-004", "個人資料保護法與內部資安政策", "敏感遮罩、密件隔離、浮水印、檔案存取紀錄", ["attachment_security", "file_access_logs"]),
    ("C-005", "正式資料庫權限政策", "RLS、密件 row-level 隔離、保留年限、audit log 不可竄改", ["document_acl", "audit_logs"]),
    ("C-006", "正式檔案儲存與病毒掃描政策", "Private bucket、加密、短效 URL、防毒掃描與隔離阻擋", ["file_objects", "virus_scan_jobs"]),
    ("C-007", "電子簽章憑證合法性驗證政策", "信任鏈、TSA、OCSP、CRL 與不可否認簽章證據", ["signing_certificates", "certificate_validation_events", "electronic_signatures"]),
    ("C-008", "委外與營運管理", "部署、監控、排程、通知、備份復原與 SOP", ["background_jobs", "job_runs", "notification_deliveries"]),
]


def compliance_control_report(counts: Dict[str, int]) -> List[Dict[str, Any]]:
    rows = []
    for control_id, source, requirement, evidence_tables in COMPLIANCE_CONTROL_REQUIREMENTS:
        evidence = {table: counts.get(table, 0) for table in evidence_tables}
        implemented = any(count > 0 for count in evidence.values())
        rows.append({
            "id": control_id,
            "source": source,
            "requirement": requirement,
            "evidence_tables": evidence,
            "status": "已驗收" if implemented else "待補證據",
        })
    return rows


def compliance_score(controls: List[Dict[str, Any]], blockers: List[str]) -> int:
    base = round((len([item for item in controls if item["status"] == "已驗收"]) / max(1, len(controls))) * 100)
    return max(0, base - min(30, len(blockers) * 5))


def compliance_attestation_payload(
    *,
    counts: Dict[str, int],
    readiness: Dict[str, Any],
    monitoring: Dict[str, Any] | None,
    latest_drill: Dict[str, Any] | None,
    signer_name: str,
    signer_role: str,
    reviewer_name: str,
    reviewer_role: str,
    period: str,
    attestation_type: str,
) -> Dict[str, Any]:
    controls = compliance_control_report(counts)
    blockers = list(readiness.get("blockers") or [])
    if not latest_drill:
        blockers.append("尚未完成備份還原演練。")
    if monitoring and monitoring.get("status") == "critical":
        blockers.append("正式監控仍有 critical 告警。")
    score = compliance_score(controls, blockers)
    status = "通過" if score >= 90 and not blockers else "有條件通過" if score >= 70 else "不通過"
    report = {
        "attestation_type": attestation_type,
        "period": period,
        "generated_at": now(),
        "signer": {"name": signer_name, "role": signer_role},
        "reviewer": {"name": reviewer_name, "role": reviewer_role},
        "status": status,
        "score": score,
        "controls": controls,
        "readiness": {
            "environment": readiness.get("environment"),
            "ready": readiness.get("ready"),
            "databaseMode": readiness.get("databaseMode"),
            "missing": readiness.get("missing", []),
            "blockers": readiness.get("blockers", []),
            "warnings": readiness.get("warnings", []),
        },
        "monitoring": {
            "status": monitoring.get("status") if monitoring else "未執行",
            "alerts": monitoring.get("alerts", [])[:10] if monitoring else [],
        },
        "latest_backup_drill": latest_drill,
        "counts": counts,
        "blockers": blockers,
        "evidence_documents": [
            "docs/compliance-control-matrix.md",
            "docs/database-security-policy.md",
            "docs/file-storage-scanning-policy.md",
            "docs/certificate-legality-validation-policy.md",
            "docs/backup-restore-drill.md",
            "docs/notification-delivery-test.md",
            "docs/deployment-production.md",
        ],
    }
    report_hash = stable_json_hash(report)
    return {
        "id": f"COMP-{datetime.now().strftime('%Y%m%d-%H%M%S')}-{secrets.token_hex(3).upper()}",
        "attestation_type": attestation_type,
        "period": period,
        "signer_name": signer_name,
        "signer_role": signer_role,
        "reviewer_name": reviewer_name,
        "reviewer_role": reviewer_role,
        "status": status,
        "score": score,
        "report_hash": report_hash,
        "report": report,
        "signed_at": now(),
        "non_repudiation": {
            "report_hash": report_hash,
            "signed_at": now(),
            "signer_role": signer_role,
            "signature_method": "backend-attestation-hash",
            "ip": "127.0.0.1" if not RUNNING_ON_VERCEL else "vercel",
        },
    }


def latest_local_backup_drill(conn: sqlite3.Connection) -> Dict[str, Any] | None:
    row = conn.execute("SELECT * FROM audit_logs WHERE action = '備份還原演練' ORDER BY created_at DESC LIMIT 1").fetchone()
    if not row:
        return None
    item = row_to_dict(row)
    try:
        detail = json.loads(item.get("detail") or "{}")
    except json.JSONDecodeError:
        detail = {"detail": item.get("detail")}
    return {"audit_id": item["id"], "created_at": item["created_at"], **detail}


def create_compliance_attestation(conn: sqlite3.Connection, payload: Dict[str, Any]) -> Dict[str, Any]:
    counts = sqlite_table_counts(DB_PATH)
    readiness = production_readiness()
    monitoring = local_monitoring_snapshot(conn)
    latest_drill = latest_local_backup_drill(conn)
    attestation = compliance_attestation_payload(
        counts=counts,
        readiness=readiness,
        monitoring=monitoring,
        latest_drill=latest_drill,
        signer_name=payload.get("signer_name") or payload.get("signer") or "行政部主任",
        signer_role=payload.get("signer_role") or "行政部主任",
        reviewer_name=payload.get("reviewer_name") or "主任",
        reviewer_role=payload.get("reviewer_role") or "主任",
        period=payload.get("period") or datetime.now().strftime("%Y-Q%q").replace("%q", str((datetime.now().month - 1) // 3 + 1)),
        attestation_type=payload.get("attestation_type") or "法遵驗收與內控制度簽核",
    )
    conn.execute(
        """
        INSERT INTO compliance_attestations (
          id, attestation_type, period, signer_name, signer_role, reviewer_name, reviewer_role,
          status, score, report_hash, report_json, signed_at, non_repudiation_json
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            attestation["id"], attestation["attestation_type"], attestation["period"], attestation["signer_name"],
            attestation["signer_role"], attestation["reviewer_name"], attestation["reviewer_role"],
            attestation["status"], attestation["score"], attestation["report_hash"],
            json.dumps(attestation["report"], ensure_ascii=False), attestation["signed_at"],
            json.dumps(attestation["non_repudiation"], ensure_ascii=False),
        ),
    )
    log_audit(conn, attestation["signer_name"], "法遵驗收與內控制度簽核", "compliance_attestations", attestation["id"], f"{attestation['status']} score={attestation['score']} hash={attestation['report_hash']}")
    return attestation


def supabase_backup_restore_drill(payload: Dict[str, Any]) -> Dict[str, Any]:
    started = time.time()
    scope = str(payload.get("scope") or "全部資料表")
    target_env = str(payload.get("target_env") or payload.get("target") or "隔離還原專案")
    rto_target = int(payload.get("rto_target_minutes") or payload.get("rtoTarget") or 30)
    rpo_target = int(payload.get("rpo_target_minutes") or payload.get("rpoTarget") or 15)
    drill_id = f"DRILL-{datetime.now().strftime('%Y%m%d-%H%M%S')}-{secrets.token_hex(3).upper()}"
    source_ref = urllib.parse.urlparse(SUPABASE_URL).hostname or ""
    source_ref = source_ref.split(".", 1)[0] if source_ref else ""

    def record(report: Dict[str, Any]) -> Dict[str, Any]:
        supabase_insert("audit_logs", {
            "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
            "actor": "Ops Drill", "action": "備份還原演練",
            "target_type": "backup_restore_drill", "target_id": drill_id,
            "ip": "vercel", "device": "serverless",
            "detail": json.dumps({
                "result": report.get("result"), "blocked": report.get("blocked", False),
                "receipt_id": report.get("receipt_id", ""), "receipt_sha256": report.get("receipt_sha256", ""),
                "database_restored": (report.get("database") or {}).get("restored", False),
                "storage_restored": (report.get("storage") or {}).get("restored", False),
            }, ensure_ascii=False),
            "event_type": "sensitive_access", "result": "success" if report.get("ok") else "failed",
            "module_code": "backup_restore", "resource_type": "backup_restore_drill",
            "resource_id": drill_id, "request_id": f"req_{secrets.token_hex(8)}", "created_at": now(),
        })
        return report

    missing = [
        name for name, value in {
            "EDOC_RESTORE_DRILL_ENDPOINT": EDOC_RESTORE_DRILL_ENDPOINT,
            "EDOC_RESTORE_DRILL_TOKEN": EDOC_RESTORE_DRILL_TOKEN,
        }.items() if not value
    ]
    if missing:
        return record({
            "id": drill_id, "ok": False, "blocked": True, "result": "blocked",
            "created_at": now(), "scope": scope, "target_env": target_env,
            "missing": missing,
            "detail": "isolated_database_and_storage_restore_runner_not_configured",
            "checks": {"database_restored": False, "storage_restored": False, "hash_match": False, "target_isolated": False},
            "improvements": ["設定隔離 Supabase 還原 runner，完成 Database 與 private Storage 實際還原後再執行。"],
        })

    request_payload = {
        "drill_id": drill_id, "source_project_ref": source_ref, "scope": scope,
        "target_environment": target_env, "rto_target_minutes": rto_target, "rpo_target_minutes": rpo_target,
        "required_checks": ["database_restore", "storage_restore", "row_counts", "object_hashes", "permissions", "pdf_open_sample"],
    }
    request = urllib.request.Request(
        EDOC_RESTORE_DRILL_ENDPOINT,
        data=json.dumps(request_payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {EDOC_RESTORE_DRILL_TOKEN}",
            "Content-Type": "application/json", "X-EDOC-Request-ID": drill_id,
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=EDOC_RESTORE_DRILL_TIMEOUT_SECONDS) as response:
            evidence = json.loads(response.read().decode("utf-8") or "{}")
    except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError, ValueError) as exc:
        return record({
            "id": drill_id, "ok": False, "blocked": True, "result": "blocked",
            "created_at": now(), "scope": scope, "target_env": target_env,
            "detail": "isolated_restore_runner_failed", "error_code": type(exc).__name__,
            "checks": {"database_restored": False, "storage_restored": False, "hash_match": False, "target_isolated": False},
        })

    database = evidence.get("database") if isinstance(evidence.get("database"), dict) else {}
    storage = evidence.get("storage") if isinstance(evidence.get("storage"), dict) else {}
    target_ref = str(evidence.get("target_project_ref") or "")
    receipt_id = str(evidence.get("receipt_id") or "")
    receipt_sha256 = str(evidence.get("receipt_sha256") or "").lower()
    target_isolated = bool(evidence.get("target_isolated")) and bool(target_ref) and target_ref != source_ref
    database_ok = bool(database.get("restored") and database.get("integrity") and database.get("counts_match"))
    storage_ok = bool(storage.get("restored") and storage.get("hash_match") and storage.get("counts_match"))
    receipt_ok = bool(receipt_id and re.fullmatch(r"[0-9a-f]{64}", receipt_sha256))
    rto_minutes = int(evidence.get("rto_minutes") or 0)
    rpo_minutes = int(evidence.get("rpo_minutes") or 0)
    rto_ok = 0 < rto_minutes <= rto_target
    rpo_ok = 0 <= rpo_minutes <= rpo_target
    ok = bool(evidence.get("ok")) and target_isolated and database_ok and storage_ok and receipt_ok and rto_ok and rpo_ok
    return record({
        "id": drill_id, "ok": ok, "blocked": not ok, "result": "通過" if ok else "blocked",
        "created_at": now(), "scope": scope, "target_env": target_env,
        "target_project_ref": target_ref, "target_isolated": target_isolated,
        "database": database, "storage": storage, "receipt_id": receipt_id, "receipt_sha256": receipt_sha256,
        "rto_minutes": rto_minutes, "rto_target_minutes": rto_target,
        "rpo_minutes": rpo_minutes, "rpo_target_minutes": rpo_target,
        "duration_ms": int((time.time() - started) * 1000),
        "checks": {
            "database_restored": database_ok, "storage_restored": storage_ok,
            "hash_match": bool(storage.get("hash_match")), "target_isolated": target_isolated,
            "receipt_valid": receipt_ok, "rto_ok": rto_ok, "rpo_ok": rpo_ok,
        },
        "improvements": [] if ok else ["還原證據不完整或未達 RTO/RPO；不得宣稱演練通過。"],
    })


def supabase_create_compliance_attestation(payload: Dict[str, Any]) -> Dict[str, Any]:
    snapshot_counts = {}
    for table in TABLES:
        try:
            snapshot_counts[table] = len(supabase_list(table, {"limit": ["1000"]}))
        except Exception:
            snapshot_counts[table] = 0
    readiness = production_readiness()
    monitoring = supabase_monitoring_snapshot()
    drill_rows = [row for row in supabase_list("audit_logs", {"limit": ["1000"]}) if row.get("action") == "備份還原演練"]
    drill_rows.sort(key=lambda item: item.get("created_at") or "", reverse=True)
    latest_drill = drill_rows[0] if drill_rows else None
    attestation = compliance_attestation_payload(
        counts=snapshot_counts,
        readiness=readiness,
        monitoring=monitoring,
        latest_drill=latest_drill,
        signer_name=payload.get("signer_name") or payload.get("signer") or "行政部主任",
        signer_role=payload.get("signer_role") or "行政部主任",
        reviewer_name=payload.get("reviewer_name") or "主任",
        reviewer_role=payload.get("reviewer_role") or "主任",
        period=payload.get("period") or datetime.now().strftime("%Y-Q%q").replace("%q", str((datetime.now().month - 1) // 3 + 1)),
        attestation_type=payload.get("attestation_type") or "法遵驗收與內控制度簽核",
    )
    row = {
        "id": attestation["id"],
        "attestation_type": attestation["attestation_type"],
        "period": attestation["period"],
        "signer_name": attestation["signer_name"],
        "signer_role": attestation["signer_role"],
        "reviewer_name": attestation["reviewer_name"],
        "reviewer_role": attestation["reviewer_role"],
        "status": attestation["status"],
        "score": attestation["score"],
        "report_hash": attestation["report_hash"],
        "report_json": attestation["report"],
        "signed_at": attestation["signed_at"],
        "non_repudiation_json": attestation["non_repudiation"],
    }
    try:
        supabase_insert("compliance_attestations", row)
    except Exception:
        pass
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": attestation["signer_name"],
        "action": "法遵驗收與內控制度簽核",
        "target_type": "compliance_attestations",
        "target_id": attestation["id"],
        "ip": "vercel",
        "device": "serverless",
        "detail": f"{attestation['status']} score={attestation['score']} hash={attestation['report_hash']}",
        "created_at": now(),
    })
    return attestation


def supabase_create_notification(payload: Dict[str, Any]) -> Dict[str, Any]:
    item = {
        "id": payload.get("id") or f"NTF-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "type": payload.get("type") or "一般通知",
        "title": payload.get("title") or f"{payload.get('type') or '一般'}通知",
        "target_role": payload.get("target_role") or payload.get("target") or "行政部主任",
        "target_user_id": payload.get("target_user_id") or "",
        "target_company_id": payload.get("target_company_id") or payload.get("company_id") or "",
        "target_email": payload.get("target_email") or "",
        "channel": payload.get("channel") or "系統通知",
        "status": payload.get("status") or "未讀",
        "priority": payload.get("priority") or "中",
        "source": payload.get("source") or "",
        "action_url": payload.get("action_url") or (f"/#officialWorkflow?document={urllib.parse.quote(str(payload.get('source') or ''))}" if payload.get("source") else ""),
        "body": payload.get("body") or "請確認公文收發電子用印系統待辦事項。",
        "delivery_receipt": payload.get("delivery_receipt") or "",
        "created_at": payload.get("created_at") or now(),
        "sent_at": payload.get("sent_at") or None,
    }
    target_user = supabase_user_by_id(item["target_user_id"]) if item["target_user_id"] else None
    if not target_user and item["target_email"]:
        item["target_user_id"] = supabase_notification_target_user_id(item["target_role"], item["target_email"])
        target_user = supabase_user_by_id(item["target_user_id"]) if item["target_user_id"] else None
    if not target_user or target_user.get("status") != "啟用":
        raise ValueError("notification_exact_target_required")
    if item["target_company_id"] and str(target_user.get("company_id") or "") != str(item["target_company_id"]):
        raise PermissionError("notification_target_company_forbidden")
    if item["target_email"] and str(target_user.get("email") or "").lower() != str(item["target_email"]).lower():
        raise PermissionError("notification_target_identity_mismatch")
    item["target_company_id"] = str(target_user.get("company_id") or "")
    item["target_email"] = str(target_user.get("email") or "")
    item["target_role"] = str(target_user.get("role") or "員工")
    existing = supabase_get("notifications", item["id"])
    if existing:
        return existing
    return supabase_insert("notifications", item)


def supabase_notification_target_email(role: str, explicit: str = "") -> str:
    return str(explicit or "").strip()


def supabase_notification_target_user_id(role: str, explicit_email: str = "") -> str:
    if explicit_email:
        qs = urllib.parse.urlencode({"select": "id", "email": f"eq.{explicit_email}", "status": "eq.啟用", "limit": "1"})
        rows = supabase_request("GET", f"users?{qs}")
        if rows:
            return rows[0]["id"]
    return ""


def supabase_push_system_notification(item: Dict[str, Any]) -> Dict[str, str]:
    existing = supabase_filter_rows("system_inbox", {"notification_id": item["id"]}, order="created_at.desc", limit=1)
    if existing:
        return {"status": "成功", "receipt": existing[0]["id"], "error": ""}
    inbox_id = f"INBOX-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    target_user_id = str(item.get("target_user_id") or "").strip()
    if not target_user_id:
        raise ValueError("notification_exact_target_required")
    supabase_insert("system_inbox", {
        "id": inbox_id,
        "notification_id": item["id"],
        "target_role": item["target_role"],
        "target_user_id": target_user_id,
        "title": item["title"],
        "body": item["body"],
        "status": "未讀",
    })
    return {"status": "成功", "receipt": inbox_id, "error": ""}


def supabase_record_notification_delivery(notification_id: str, channel: str, target: str, status: str, receipt: str = "", error: str = "") -> Dict[str, Any]:
    return supabase_insert("notification_deliveries", {
        "id": f"NDEL-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "notification_id": notification_id,
        "channel": channel,
        "target": target,
        "status": status,
        "receipt": receipt,
        "error": error,
        "attempt_count": 1,
    })


def supabase_deliver_notification(notification_id: str, force_channel: str = "") -> Dict[str, Any]:
    item = supabase_get("notifications", notification_id)
    if not item:
        return {"id": notification_id, "status": "失敗", "error": "notification_not_found", "results": []}
    channels = notification_channels(force_channel or item["channel"])
    target_email = supabase_notification_target_email(item["target_role"], item.get("target_email") or "")
    results: List[Dict[str, str]] = []
    credential_rows = supabase_list("notification_channel_credentials", {}) if "notification_channel_credentials" in TABLES else []
    for channel in channels:
        credential = supabase_notification_credential_status(channel, credential_rows)
        if channel != "系統站內通知" and credential["status"] not in {"有效", "即將到期"}:
            result = {"status": "憑證異常", "receipt": "", "error": f"{channel} 正式憑證{credential['status']}，請先完成憑證驗證或更新。"}
            target = target_email if channel == "Email" else "公文收發電子用印系統 LINE 工作群組"
            supabase_record_notification_delivery(item["id"], channel, target, result["status"], result.get("receipt", ""), result.get("error", ""))
            results.append({"channel": channel, "target": target, **result, "attempted_at": now(), "duration_ms": 0})
            continue
        started = time.time()
        if channel == "Email":
            result = send_email_notification(target_email, item["title"], item["body"], item["id"])
            target = target_email
        elif channel == "Line 工作群組":
            result = send_line_notification(f"{item['title']}\n{item['body']}")
            target = "公文收發電子用印系統 LINE 工作群組"
        else:
            result = supabase_push_system_notification(item)
            target = item["target_role"]
        supabase_record_notification_delivery(item["id"], channel, target, result["status"], result.get("receipt", ""), result.get("error", ""))
        results.append(notification_attempt_result(channel, target, result, started))
    success_count = len([entry for entry in results if entry["status"] == "成功"])
    receipt_text = "；".join(
        f"{entry['channel']}->{entry['target']}:{entry['status']}{('/' + entry['receipt']) if entry.get('receipt') else ''}{(' / ' + entry['error']) if entry.get('error') else ''}"
        for entry in results
    )
    status = "已派送" if success_count == len(results) else "部分派送" if success_count else "派送失敗"
    supabase_patch("notifications", item["id"], {"status": status, "sent_at": now(), "delivery_receipt": receipt_text})
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": "Notify Worker",
        "action": "通知派送",
        "target_type": "notifications",
        "target_id": item["id"],
        "ip": "vercel",
        "device": "serverless",
        "detail": receipt_text,
    })
    return {"id": item["id"], "status": status, "success": success_count, "total": len(results), "receipt": receipt_text, "results": results}


def supabase_create_and_deliver_notification(payload: Dict[str, Any]) -> Dict[str, Any]:
    notice = supabase_create_notification({**payload, "channel": payload.get("channel") or "Email + 系統通知"})
    try:
        delivery = supabase_deliver_notification(notice["id"], notice["channel"])
    except Exception as exc:
        detail = redact_text(str(exc))[:500]
        delivery = {"id": notice["id"], "status": "派送失敗", "success": 0, "total": 0, "receipt": "", "error": detail, "results": []}
        try:
            supabase_patch("notifications", notice["id"], {"status": "派送失敗", "delivery_receipt": detail})
            supabase_insert("audit_logs", {
                "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
                "actor": "Notify Worker",
                "action": "通知自動派送失敗",
                "target_type": "notifications",
                "target_id": notice["id"],
                "ip": "vercel",
                "device": "serverless",
                "detail": detail,
            })
        except Exception:
            log_structured("error", "notification_delivery_audit_failed", notification_id=notice["id"])
    return {**notice, "delivery": delivery}


def supabase_ensure_notification_for_source(payload: Dict[str, Any]) -> Dict[str, Any]:
    source = payload.get("source") or ""
    notice_type = payload.get("type") or ""
    if source and notice_type:
        qs = urllib.parse.urlencode({"select": "*", "source": f"eq.{source}", "type": f"eq.{notice_type}", "limit": "1"})
        rows = supabase_request("GET", f"notifications?{qs}")
        if rows:
            return rows[0]
    return supabase_create_notification(payload)


def supabase_sync_notifications_from_business_state() -> Dict[str, Any]:
    created = 0
    items: List[Dict[str, Any]] = []
    skipped: List[Dict[str, str]] = []
    documents = supabase_list("documents", {})
    for doc in [item for item in documents if item.get("direction") == "收文" and item.get("status") in {"待登錄", "待分派"}]:
        target = exact_supabase_notification_target_from_metadata(doc.get("metadata_json"))
        if not target:
            skipped.append({"source": str(doc.get("id") or ""), "reason": "notification_exact_target_required"})
            continue
        qs = urllib.parse.urlencode({"select": "id", "source": f"eq.{doc['id']}", "type": "eq.收文", "limit": "1"})
        before = supabase_request("GET", f"notifications?{qs}")
        item = supabase_ensure_notification_for_source({
            "type": "收文",
            "title": f"{doc.get('doc_no')} {doc.get('status')}",
            **exact_notification_target_payload(target, target.get("company_id") or ""),
            "channel": "系統通知",
            "priority": "高",
            "source": doc["id"],
            "body": f"{doc.get('agency_name')} 來文「{doc.get('subject')}」需處理。",
        })
        created += 0 if before else 1
        items.append(item)
    for doc in [item for item in documents if item.get("direction") == "發文" and item.get("status") in {"待清稿", "已清稿", "交換失敗"}]:
        target = exact_supabase_notification_target_from_metadata(doc.get("metadata_json"))
        if not target:
            skipped.append({"source": str(doc.get("id") or ""), "reason": "notification_exact_target_required"})
            continue
        notice_type = "交換失敗" if doc.get("status") == "交換失敗" else "待清稿"
        qs = urllib.parse.urlencode({"select": "id", "source": f"eq.{doc['id']}", "type": f"eq.{notice_type}", "limit": "1"})
        before = supabase_request("GET", f"notifications?{qs}")
        item = supabase_ensure_notification_for_source({
            "type": notice_type,
            "title": f"{doc.get('doc_no')} {doc.get('status')}",
            **exact_notification_target_payload(target, target.get("company_id") or ""),
            "channel": "Email + Line + 系統通知" if notice_type == "交換失敗" else "Email + 系統通知",
            "priority": "高",
            "source": doc["id"],
            "body": f"{doc.get('subject')} 目前狀態：{doc.get('status')}。",
        })
        created += 0 if before else 1
        items.append(item)
    return {"created": created, "items": items, "skipped": skipped}


def supabase_retry_failed_notifications() -> Dict[str, Any]:
    rows = [
        item for item in supabase_list("notifications", {})
        if item.get("status") in {"派送失敗", "部分派送"} or not item.get("delivery_receipt")
    ]
    results = [supabase_deliver_notification(row["id"]) for row in rows]
    return {"count": len(results), "results": results}


def _archive_entry_name(file_meta: Dict[str, Any]) -> str:
    name = Path(str(file_meta.get("file_name") or file_meta.get("id") or "file.bin")).name
    safe_name = re.sub(r"[^0-9A-Za-z._\-\u4e00-\u9fff]", "_", name)[:180] or "file.bin"
    return f"files/{int(file_meta.get('version') or 1):04d}_{file_meta.get('file_type') or 'file'}_{file_meta.get('id')}_{safe_name}"


def _official_archive_safe_audit_row(row: Dict[str, Any]) -> Dict[str, Any]:
    """Return the minimum audit-chain witness safe to place in an archive.

    Audit rows can contain names, email addresses, request bodies and document
    text in ``actor``/``detail`` or other extended fields.  The preservation
    package needs the immutable chain coordinates and entry hash, not that raw
    payload.  Keep an irreversible actor witness and explicitly state that the
    source payload was redacted so an archive reader cannot mistake this subset
    for a byte-for-byte copy of the audit table.
    """
    safe = {
        key: row.get(key)
        for key in (
            "id", "action", "target_type", "target_id", "event_type", "result",
            "module_code", "resource_type", "resource_id", "chain_sequence",
            "chain_segment", "previous_hash", "entry_hash", "chain_status",
            "chain_integrity_status", "created_at",
        )
        if row.get(key) is not None
    }
    actor_hash = str(row.get("actor_hash") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{16}", actor_hash):
        actor_hash = sha256_bytes(str(row.get("actor") or "").encode("utf-8"))[:16]
    safe["actor_hash"] = actor_hash
    safe["source_payload_redacted"] = True
    safe["selection_non_contiguous"] = True
    return safe


def _official_archive_audit_boundary(audit_chain: List[Dict[str, Any]]) -> Dict[str, Any]:
    segments: List[Dict[str, Any]] = []
    segment_names: List[str] = []
    for row in audit_chain:
        segment = str(row.get("chain_segment") or "unsegmented")
        if segment not in segment_names:
            segment_names.append(segment)
    for segment in segment_names:
        rows = [row for row in audit_chain if str(row.get("chain_segment") or "unsegmented") == segment]
        segments.append({
            "chain_segment": segment,
            "first_sequence": rows[0].get("chain_sequence"),
            "last_sequence": rows[-1].get("chain_sequence"),
            "first_previous_hash": rows[0].get("previous_hash") or "",
            "last_entry_hash": rows[-1].get("entry_hash") or "",
            "row_count": len(rows),
            "selection_non_contiguous": True,
        })
    return {
        "first_sequence": audit_chain[0].get("chain_sequence") if audit_chain else None,
        "last_sequence": audit_chain[-1].get("chain_sequence") if audit_chain else None,
        "first_previous_hash": audit_chain[0].get("previous_hash") if audit_chain else "",
        "last_entry_hash": audit_chain[-1].get("entry_hash") if audit_chain else "",
        "row_count": len(audit_chain),
        "selection_non_contiguous": True,
        "segments": segments,
    }


def _official_archive_registration_matches(row: Dict[str, Any], expected: Dict[str, Any]) -> bool:
    try:
        return (
            row.get("id") == expected["id"]
            and row.get("document_id") == expected["document_id"]
            and row.get("requested_by") == expected["requested_by"]
            and str(row.get("manifest_sha256") or "").lower() == expected["manifest_sha256"].lower()
            and str(row.get("package_sha256") or "").lower() == expected["package_sha256"].lower()
            and int(row.get("entry_count")) == expected["entry_count"]
            and int(row.get("package_size_bytes")) == expected["package_size_bytes"]
            and row.get("renderer_version") == expected["renderer_version"]
            and row.get("storage_bucket") == expected["storage_bucket"]
            and row.get("storage_path") == expected["storage_path"]
            and row.get("status") == "ready"
        )
    except (KeyError, TypeError, ValueError):
        return False


def _build_official_archive_zip(
    *,
    export_id: str,
    document: Dict[str, Any],
    files_with_bytes: List[Tuple[Dict[str, Any], bytes]],
    approval_steps: List[Dict[str, Any]],
    approval_logs: List[Dict[str, Any]],
    actor_snapshots: List[Dict[str, Any]],
    stamp_request: Dict[str, Any] | None,
    stamp_positions: List[Dict[str, Any]],
    text_overlays: List[Dict[str, Any]],
    dispatch_record: Dict[str, Any] | None,
    dispatch_events: List[Dict[str, Any]],
    editor_revisions: List[Dict[str, Any]],
    notifications: List[Dict[str, Any]],
    notification_deliveries: List[Dict[str, Any]],
    file_access_logs: List[Dict[str, Any]],
    exchange_status_history: List[Dict[str, Any]],
    audit_chain: List[Dict[str, Any]],
    requested_by: Dict[str, Any],
) -> Tuple[bytes, Dict[str, Any], str]:
    entries: List[Dict[str, Any]] = []
    for file_meta, data in files_with_bytes:
        actual_hash = sha256_bytes(data)
        expected_hash = str(file_meta.get("file_hash") or "").lower()
        if not expected_hash or actual_hash.lower() != expected_hash:
            raise ValueError("official_archive_file_hash_mismatch")
        entries.append({
            "path": _archive_entry_name(file_meta),
            "file_id": file_meta.get("id") or "",
            "file_type": file_meta.get("file_type") or "",
            "file_name": file_meta.get("file_name") or "",
            "version": int(file_meta.get("version") or 1),
            "size_bytes": len(data),
            "sha256": actual_hash,
        })
    safe_document = {
        key: document.get(key)
        for key in (
            "id", "company_id", "document_type", "source_type", "title", "subject", "description", "method",
            "recipient", "dispatch_unit", "handler_name", "applicant_id", "applicant_name",
            "applicant_department_id", "applicant_department_name", "workflow_template_key", "dispatch_method",
            "current_status", "current_step", "request_reason", "stamped_file_id", "retention_until",
            "retention_policy_version", "legal_hold", "disposition_status", "created_at", "updated_at",
        )
    }
    safe_audit_chain = [_official_archive_safe_audit_row(row) for row in audit_chain]
    manifest_core = {
        "schema_version": 1,
        "export_id": export_id,
        "record_type": "official_document_archive_package",
        "document": safe_document,
        "entries": entries,
        "approval_steps": approval_steps,
        "approval_logs": approval_logs,
        "actor_snapshots": actor_snapshots,
        "stamp_request": stamp_request or {},
        "stamp_positions": stamp_positions,
        "locked_seal_assets": [
            {
                "position_id": position.get("id") or "",
                "seal_id": position.get("seal_id") or (stamp_request or {}).get("seal_id") or "",
                "seal_file_id": position.get("locked_seal_file_id") or "",
                "sha256": position.get("locked_seal_sha256") or "",
            }
            for position in stamp_positions
        ],
        "text_overlays": text_overlays,
        "dispatch_record": dispatch_record or {},
        "dispatch_events": dispatch_events,
        "editor_revisions": editor_revisions,
        "notifications": notifications,
        "notification_deliveries": notification_deliveries,
        "file_access_logs": file_access_logs,
        "exchange_status_history": exchange_status_history,
        "audit_chain": safe_audit_chain,
        "audit_chain_boundary": _official_archive_audit_boundary(safe_audit_chain),
        "formal_exchange_provider_enabled": False,
        "renderer_version": EDOC_EDITOR_RENDERER_VERSION,
        "requested_by_user_id": requested_by.get("id") or "",
        "created_at": now(),
        "seal_vault_originals_included": False,
    }
    manifest_sha256 = stable_json_hash(manifest_core)
    manifest = {**manifest_core, "manifest_sha256": manifest_sha256}
    manifest_bytes = json.dumps(manifest, ensure_ascii=False, sort_keys=True, indent=2).encode("utf-8")
    output = io.BytesIO()
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        archive.writestr("manifest.json", manifest_bytes)
        for (file_meta, data), entry in zip(files_with_bytes, entries):
            archive.writestr(entry["path"], data)
    package = output.getvalue()
    return package, manifest, sha256_bytes(package)


def build_official_document_archive_package(
    conn: sqlite3.Connection,
    document_id: str,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = official_session_user(session)
    detail = official_document_detail(conn, document_id, session)
    if not detail.get("can_download") and not session_has_any_permission(session, ["audit_logs.export"]):
        raise PermissionError("official_archive_export_forbidden")
    files_with_bytes: List[Tuple[Dict[str, Any], bytes]] = []
    for file_meta in detail.get("files") or []:
        file_object_id = str(file_meta.get("file_object_id") or "")
        if not file_object_id:
            raise ValueError("official_archive_file_object_required")
        file_object, data = read_file_object_bytes(conn, file_object_id)
        verify_official_file_bytes(file_meta, file_object, data)
        files_with_bytes.append((file_meta, data))
    stamp_request = official_document_stamp_request(conn, document_id)
    positions = official_stamp_positions(conn, stamp_request["id"]) if stamp_request else []
    overlays = official_text_overlays(conn, stamp_request["id"]) if stamp_request else []
    revisions = [
        {**row_to_dict(row), "editor_state_json": parse_json_any(row["editor_state_json"], {})}
        for row in conn.execute("SELECT * FROM official_document_editor_revisions WHERE document_id = ? ORDER BY revision_no", (document_id,)).fetchall()
    ]
    notifications = [
        row_to_dict(row)
        for row in conn.execute("SELECT * FROM notifications WHERE source = ? ORDER BY created_at", (document_id,)).fetchall()
    ]
    notice_ids = [item["id"] for item in notifications]
    deliveries: List[Dict[str, Any]] = []
    if notice_ids:
        placeholders = ",".join("?" for _ in notice_ids)
        deliveries = [row_to_dict(row) for row in conn.execute(f"SELECT * FROM notification_deliveries WHERE notification_id IN ({placeholders}) ORDER BY created_at", notice_ids).fetchall()]
    file_object_ids = [str(item.get("file_object_id") or "") for item in detail.get("files") or [] if item.get("file_object_id")]
    file_access_logs: List[Dict[str, Any]] = []
    if file_object_ids:
        placeholders = ",".join("?" for _ in file_object_ids)
        for access_row in conn.execute(
            f"SELECT id, file_object_id, action, result, actor, created_at FROM file_access_logs WHERE file_object_id IN ({placeholders}) ORDER BY created_at",
            file_object_ids,
        ).fetchall():
            access = row_to_dict(access_row)
            file_access_logs.append({
                "id": access.get("id"),
                "file_object_id": access.get("file_object_id"),
                "action": access.get("action"),
                "result": access.get("result"),
                "actor_hash": sha256_bytes(str(access.get("actor") or "").encode("utf-8"))[:16],
                "created_at": access.get("created_at"),
            })
    exchange_refs: List[Tuple[str, str]] = []
    for ref_type, table in (("outbox", "exchange_outbox"), ("inbox", "exchange_inbox")):
        exchange_refs.extend(
            (ref_type, str(row["id"]))
            for row in conn.execute(f"SELECT id FROM {table} WHERE document_id = ?", (document_id,)).fetchall()
        )
    exchange_status_history: List[Dict[str, Any]] = []
    for ref_type, ref_id in exchange_refs:
        exchange_status_history.extend([
            row_to_dict(row) for row in conn.execute(
                """
                SELECT id, exchange_ref_type, exchange_ref_id, from_status, to_status,
                       provider_status_code, created_at
                FROM exchange_status_history
                WHERE exchange_ref_type = ? AND exchange_ref_id = ?
                ORDER BY created_at
                """,
                (ref_type, ref_id),
            ).fetchall()
        ])
    dispatch_events = []
    for event_row in conn.execute(
            """
            SELECT id, dispatch_record_id, document_id, event_sequence, event_type,
                   from_status, to_status, changed_fields_json,
                   record_snapshot_sha256, database_actor, created_at
            FROM official_document_dispatch_events
            WHERE document_id = ?
            ORDER BY event_sequence, created_at, id
            """,
            (document_id,),
        ).fetchall():
        event = row_to_dict(event_row)
        event["changed_fields"] = parse_json_any(event.pop("changed_fields_json", "[]"), [])
        dispatch_events.append(event)
    audit_chain = []
    for audit_row in conn.execute(
        """
        SELECT id, actor, action, target_type, target_id, event_type, result,
               module_code, resource_type, resource_id, chain_sequence,
               chain_segment, previous_hash, entry_hash, chain_status, created_at
        FROM audit_logs
        WHERE (target_type = 'official_documents' AND target_id = ?)
           OR (resource_type = 'official_documents' AND resource_id = ?)
        ORDER BY chain_segment, chain_sequence, created_at, id
        """,
        (document_id, document_id),
    ).fetchall():
        audit = row_to_dict(audit_row)
        audit["actor_hash"] = sha256_bytes(str(audit.pop("actor", "") or "").encode("utf-8"))[:16]
        audit["selection_non_contiguous"] = True
        audit_chain.append(audit)
    export_id = f"ODARCH-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    package, manifest, package_sha256 = _build_official_archive_zip(
        export_id=export_id,
        document=detail,
        files_with_bytes=files_with_bytes,
        approval_steps=detail.get("approval_steps") or [],
        approval_logs=detail.get("logs") or [],
        actor_snapshots=official_document_actor_snapshots(conn, document_id),
        stamp_request=stamp_request,
        stamp_positions=positions,
        text_overlays=overlays,
        dispatch_record=detail.get("dispatch_record"),
        dispatch_events=dispatch_events,
        editor_revisions=revisions,
        notifications=notifications,
        notification_deliveries=deliveries,
        file_access_logs=file_access_logs,
        exchange_status_history=exchange_status_history,
        audit_chain=audit_chain,
        requested_by=user,
    )
    row = {
        "id": export_id, "document_id": document_id, "requested_by": user["id"],
        "manifest_sha256": manifest["manifest_sha256"], "package_sha256": package_sha256,
        "entry_count": len(manifest["entries"]), "package_size_bytes": len(package),
        "renderer_version": EDOC_EDITOR_RENDERER_VERSION, "status": "ready", "created_at": now(),
    }
    insert_row(conn, "official_document_archive_exports", row)
    log_audit(
        conn, official_actor_name(user), "匯出正式公文保存包", "official_documents", document_id,
        f"export_id={export_id};manifest_sha256={manifest['manifest_sha256']};package_sha256={package_sha256};entries={len(manifest['entries'])}",
        event_type="export", actor_user_id=user["id"], data_scope="custom",
    )
    return {"data": package, "file_name": f"{document_id}-archive.zip", "manifest": manifest, "export": row}


def verify_official_document_archive_sources(
    conn: sqlite3.Connection,
    document_id: str,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = official_session_user(session)
    detail = official_document_detail(conn, document_id, session)
    if not detail.get("can_download") and not session_has_any_permission(session, ["audit_logs.export"]):
        raise PermissionError("official_archive_verify_forbidden")
    verified: List[Dict[str, Any]] = []
    for file_meta in detail.get("files") or []:
        file_object_id = str(file_meta.get("file_object_id") or "")
        if not file_object_id:
            raise ValueError("official_archive_file_object_required")
        file_object, data = read_file_object_bytes(conn, file_object_id)
        verify_official_file_bytes(file_meta, file_object, data)
        verified.append({
            "file_id": file_meta.get("id"),
            "file_type": file_meta.get("file_type"),
            "sha256": sha256_bytes(data),
            "size_bytes": len(data),
        })
    verification_hash = stable_json_hash(verified)
    log_audit(
        conn, official_actor_name(user), "驗證正式公文保存來源", "official_documents", document_id,
        f"files={len(verified)};verification_sha256={verification_hash}",
        event_type="verify", actor_user_id=user["id"], data_scope="custom",
    )
    return {
        "ok": True,
        "document_id": document_id,
        "verified_at": now(),
        "file_count": len(verified),
        "verification_sha256": verification_hash,
        "files": verified,
    }


def supabase_build_official_document_archive_package(
    document_id: str,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    detail = supabase_official_document_detail(document_id, session)
    if not detail.get("can_download") and not session_has_any_permission(session, ["audit_logs.export"]):
        raise PermissionError("official_archive_export_forbidden")
    files_with_bytes: List[Tuple[Dict[str, Any], bytes]] = []
    for file_meta in detail.get("files") or []:
        file_object = supabase_get("file_objects", str(file_meta.get("file_object_id") or ""))
        if not file_object or is_seal_vault_file(file_object):
            raise ValueError("official_archive_file_object_required")
        data = supabase_storage_download(file_object.get("storage_key") or "", file_object.get("bucket") or EDOC_STORAGE_BUCKET)
        verify_official_file_bytes(file_meta, file_object, data)
        files_with_bytes.append((file_meta, data))
    stamp_request = supabase_official_document_stamp_request(document_id)
    positions = supabase_official_stamp_positions(stamp_request["id"]) if stamp_request else []
    overlays = supabase_official_text_overlays(stamp_request["id"]) if stamp_request else []
    revisions = []
    for revision in supabase_filter_rows("official_document_editor_revisions", {"document_id": document_id}, order="revision_no.asc", limit=1000):
        revisions.append({**revision, "editor_state_json": parse_json_any(revision.get("editor_state_json"), {})})
    notifications = supabase_filter_rows("notifications", {"source": document_id}, order="created_at.asc", limit=1000)
    deliveries: List[Dict[str, Any]] = []
    for notification in notifications:
        deliveries.extend(supabase_filter_rows("notification_deliveries", {"notification_id": notification["id"]}, order="created_at.asc", limit=1000))
    file_access_by_id: Dict[str, Dict[str, Any]] = {}
    for file_meta in detail.get("files") or []:
        file_object_id = str(file_meta.get("file_object_id") or "")
        if not file_object_id:
            continue
        for access in supabase_filter_rows(
            "file_access_logs",
            {"file_object_id": file_object_id},
            order="created_at.asc",
            limit=1000,
            select="id,file_object_id,action,result,actor,created_at",
        ):
            file_access_by_id[str(access.get("id") or "")] = {
                "id": access.get("id"),
                "file_object_id": access.get("file_object_id"),
                "action": access.get("action"),
                "result": access.get("result"),
                "actor_hash": sha256_bytes(str(access.get("actor") or "").encode("utf-8"))[:16],
                "created_at": access.get("created_at"),
            }
    exchange_refs: List[Tuple[str, str]] = []
    for ref_type, table in (("outbox", "exchange_outbox"), ("inbox", "exchange_inbox")):
        exchange_refs.extend(
            (ref_type, str(row.get("id") or ""))
            for row in supabase_filter_rows(table, {"document_id": document_id}, limit=1000, select="id")
            if row.get("id")
        )
    exchange_status_history: List[Dict[str, Any]] = []
    for ref_type, ref_id in exchange_refs:
        exchange_status_history.extend(supabase_filter_rows(
            "exchange_status_history",
            {"exchange_ref_type": ref_type, "exchange_ref_id": ref_id},
            order="created_at.asc",
            limit=1000,
            select="id,exchange_ref_type,exchange_ref_id,from_status,to_status,provider_status_code,created_at",
        ))
    dispatch_events = supabase_filter_rows(
        "official_document_dispatch_events",
        {"document_id": document_id},
        order="event_sequence.asc,created_at.asc",
        limit=1000,
        select=(
            "id,dispatch_record_id,document_id,event_sequence,event_type,from_status,to_status,"
            "changed_fields,record_snapshot_sha256,database_actor,created_at"
        ),
    )
    audit_by_id: Dict[str, Dict[str, Any]] = {}
    audit_select = (
        "id,actor,action,target_type,target_id,event_type,result,module_code,resource_type,resource_id,"
        "chain_sequence,chain_segment,previous_hash,entry_hash,chain_status,created_at"
    )
    for filters in (
        {"target_type": "official_documents", "target_id": document_id},
        {"resource_type": "official_documents", "resource_id": document_id},
    ):
        for row in supabase_filter_rows(
            "audit_logs",
            filters,
            order="chain_segment.asc,chain_sequence.asc,created_at.asc,id.asc",
            limit=1000,
            select=audit_select,
        ):
            safe_row = dict(row)
            safe_row["actor_hash"] = sha256_bytes(str(safe_row.pop("actor", "") or "").encode("utf-8"))[:16]
            safe_row["selection_non_contiguous"] = True
            audit_by_id[str(safe_row.get("id") or "")] = safe_row
    audit_chain = sorted(
        audit_by_id.values(),
        key=lambda item: (
            str(item.get("chain_segment") or ""),
            int(item.get("chain_sequence") or 0),
            str(item.get("created_at") or ""),
            str(item.get("id") or ""),
        ),
    )
    export_id = f"ODARCH-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}"
    package, manifest, package_sha256 = _build_official_archive_zip(
        export_id=export_id,
        document=detail,
        files_with_bytes=files_with_bytes,
        approval_steps=detail.get("approval_steps") or [],
        approval_logs=detail.get("logs") or [],
        actor_snapshots=supabase_official_document_actor_snapshots(document_id),
        stamp_request=stamp_request,
        stamp_positions=positions,
        text_overlays=overlays,
        dispatch_record=detail.get("dispatch_record"),
        dispatch_events=dispatch_events,
        editor_revisions=revisions,
        notifications=notifications,
        notification_deliveries=deliveries,
        file_access_logs=list(file_access_by_id.values()),
        exchange_status_history=exchange_status_history,
        audit_chain=audit_chain,
        requested_by=user,
    )
    # Production archives can exceed Vercel's function response limit.  Store
    # the immutable package in the normal private EDOC bucket and return only
    # a short-lived URL; archive bytes never traverse the browser-facing
    # function response and Seal Vault originals are never included.
    storage_path = f"official-document-archives/{document_id}/{export_id}.zip"
    supabase_storage_upload(storage_path, package, "application/zip", EDOC_STORAGE_BUCKET)
    expected_registration = {
        "id": export_id,
        "document_id": document_id,
        "requested_by": user["id"],
        "manifest_sha256": manifest["manifest_sha256"],
        "package_sha256": package_sha256,
        "entry_count": len(manifest["entries"]),
        "package_size_bytes": len(package),
        "renderer_version": EDOC_EDITOR_RENDERER_VERSION,
        "storage_bucket": EDOC_STORAGE_BUCKET,
        "storage_path": storage_path,
    }
    try:
        raw = supabase_request("POST", "rpc/edoc_register_official_archive_export", {
            "p_id": expected_registration["id"],
            "p_document_id": expected_registration["document_id"],
            "p_requested_by": expected_registration["requested_by"],
            "p_manifest_sha256": expected_registration["manifest_sha256"],
            "p_package_sha256": expected_registration["package_sha256"],
            "p_entry_count": expected_registration["entry_count"],
            "p_package_size_bytes": expected_registration["package_size_bytes"],
            "p_renderer_version": expected_registration["renderer_version"],
            "p_storage_bucket": expected_registration["storage_bucket"],
            "p_storage_path": expected_registration["storage_path"],
        })
        if isinstance(raw, list):
            row = raw[0] if len(raw) == 1 and isinstance(raw[0], dict) else {}
        else:
            row = raw if isinstance(raw, dict) else {}
        if not _official_archive_registration_matches(row, expected_registration):
            raise RuntimeError("official_archive_export_registration_invalid")
    except Exception:
        # Do not leave an unindexed preservation package reachable in Storage
        # when the authoritative export record could not be committed.
        try:
            supabase_storage_delete(storage_path, EDOC_STORAGE_BUCKET)
        except Exception as cleanup_error:
            log_structured(
                "error",
                "official_archive_orphan_cleanup_failed",
                export_id=export_id,
                document_id=document_id,
                error=redact_text(str(cleanup_error)),
            )
        raise
    signed = supabase_storage_create_signed_download_url(
        storage_path,
        EDOC_STORAGE_BUCKET,
        file_name=f"{document_id}-archive.zip",
        download=True,
    )
    return {
        "file_name": f"{document_id}-archive.zip",
        "manifest": manifest,
        "export": row,
        "download_url": signed["url"],
        "expires_at": signed["expires_at"],
        "expires_in": signed["expires_in"],
    }


def supabase_verify_official_document_archive_sources(
    document_id: str,
    session: Dict[str, Any] | None,
) -> Dict[str, Any]:
    user = supabase_official_session_user(session)
    detail = supabase_official_document_detail(document_id, session)
    if not detail.get("can_download") and not session_has_any_permission(session, ["audit_logs.export"]):
        raise PermissionError("official_archive_verify_forbidden")
    verified: List[Dict[str, Any]] = []
    for file_meta in detail.get("files") or []:
        file_object = supabase_get("file_objects", str(file_meta.get("file_object_id") or ""))
        if not file_object or is_seal_vault_file(file_object):
            raise ValueError("official_archive_file_object_required")
        data = supabase_storage_download(
            file_object.get("storage_key") or "",
            file_object.get("bucket") or EDOC_STORAGE_BUCKET,
        )
        verify_official_file_bytes(file_meta, file_object, data)
        verified.append({
            "file_id": file_meta.get("id"),
            "file_type": file_meta.get("file_type"),
            "sha256": sha256_bytes(data),
            "size_bytes": len(data),
        })
    verification_hash = stable_json_hash(verified)
    supabase_insert("audit_logs", {
        "id": f"AUD-{int(time.time() * 1000)}-{secrets.token_hex(3).upper()}",
        "actor": official_actor_name(user), "actor_user_id": user["id"],
        "action": "驗證正式公文保存來源", "target_type": "official_documents",
        "target_id": document_id,
        "detail": f"files={len(verified)};verification_sha256={verification_hash}",
        "event_type": "verify", "result": "success", "module_code": "official_documents",
        "resource_type": "official_documents", "resource_id": document_id,
        "request_id": f"req_{secrets.token_hex(8)}", "created_at": now(),
    })
    return {
        "ok": True,
        "document_id": document_id,
        "verified_at": now(),
        "file_count": len(verified),
        "verification_sha256": verification_hash,
        "files": verified,
    }


class Handler(SimpleHTTPRequestHandler):
    server_version = "SuiyueEdocBackend/1.0"

    def translate_path(self, path: str) -> str:
        parsed = urlparse(path)
        rel = unquote(parsed.path).lstrip("/") or "index.html"
        return str((ROOT / rel).resolve())

    def end_headers(self) -> None:
        self.send_header("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type, Authorization, If-Match, X-EDOC-Handoff-Exchange")
        super().end_headers()

    def do_OPTIONS(self) -> None:
        self.send_response(HTTPStatus.NO_CONTENT)
        self.end_headers()

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        if parsed.path.startswith("/api/"):
            self.handle_api("GET", parsed.path, parse_qs(parsed.query))
            return
        super().do_GET()

    def do_POST(self) -> None:
        self.handle_api("POST", urlparse(self.path).path, {})

    def do_PUT(self) -> None:
        self.handle_api("PUT", urlparse(self.path).path, {})

    def do_PATCH(self) -> None:
        self.handle_api("PATCH", urlparse(self.path).path, {})

    def do_DELETE(self) -> None:
        self.handle_api("DELETE", urlparse(self.path).path, {})

    def read_json(self) -> Dict[str, Any]:
        length = int(self.headers.get("Content-Length", "0") or "0")
        if not length:
            return {}
        raw = self.rfile.read(length).decode("utf-8")
        return json.loads(raw) if raw else {}

    def read_form_urlencoded(self) -> Dict[str, str]:
        content_type = self.headers.get("Content-Type", "").split(";", 1)[0].strip().lower()
        if content_type != "application/x-www-form-urlencoded":
            raise ValueError("invalid_handoff_content_type")
        try:
            length = int(self.headers.get("Content-Length", "0") or "0")
        except ValueError as error:
            raise ValueError("invalid_handoff_content_length") from error
        if length <= 0 or length > PORTAL_HANDOFF_FORM_MAX_BYTES:
            raise ValueError("invalid_handoff_content_length")
        try:
            raw = self.rfile.read(length).decode("utf-8", errors="strict")
            pairs = urllib.parse.parse_qsl(
                raw,
                keep_blank_values=True,
                strict_parsing=True,
                max_num_fields=4,
            )
        except (UnicodeDecodeError, ValueError) as error:
            raise ValueError("invalid_handoff_form") from error
        if not pairs or len({name for name, _ in pairs}) != len(pairs):
            raise ValueError("invalid_handoff_form")
        values = dict(pairs)
        # The current Portal submits one compact ``token`` field.  A Portal
        # page that was already open before the rollout can still submit the
        # previous two-field ``payload`` + ``signature`` shape.  Both carry
        # the exact same HMAC-protected assertion and are verified by
        # ``verify_portal_handoff_payload`` below.  Accept either exact shape
        # so a cached, authenticated Portal tab is not stranded during a
        # rolling deployment; mixed, partial, duplicate or extra fields stay
        # fail-closed.
        field_names = set(values)
        current_shape = field_names == {"token"} and bool(values.get("token"))
        legacy_shape = (
            field_names == {"payload", "signature"}
            and bool(values.get("payload"))
            and bool(values.get("signature"))
        )
        if not (current_shape or legacy_shape):
            raise ValueError("invalid_handoff_form")
        return values

    def read_body_bytes(self, max_bytes: int = EDOC_EDITOR_MAX_FILE_SIZE_MB * 1024 * 1024) -> bytes:
        length = int(self.headers.get("Content-Length", "0") or "0")
        if length <= 0:
            raise ValueError("editor_local_upload_content_required")
        if length > max_bytes:
            raise ValueError("editor_pdf_too_large")
        data = self.rfile.read(length)
        if len(data) != length:
            raise ValueError("editor_upload_incomplete")
        return data

    def send_json(
        self,
        data: Any,
        status: int = 200,
        extra_headers: Iterable[Tuple[str, str]] | None = None,
    ) -> None:
        body = json.dumps(data, ensure_ascii=False, indent=2).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        for name, value in extra_headers or ():
            self.send_header(name, value)
        self.end_headers()
        self.wfile.write(body)

    def send_archive_package(self, package: Dict[str, Any]) -> None:
        data = package["data"]
        file_name = Path(str(package.get("file_name") or "official-document-archive.zip")).name
        self.send_response(200)
        self.send_header("Content-Type", "application/zip")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Content-Disposition", f"attachment; filename*=UTF-8''{urllib.parse.quote(file_name)}")
        self.send_header("X-EDOC-Archive-Manifest-SHA256", package["manifest"]["manifest_sha256"])
        self.send_header("X-EDOC-Archive-Package-SHA256", package["export"]["package_sha256"])
        self.send_header("Cache-Control", "private, no-store, max-age=0")
        self.end_headers()
        self.wfile.write(data)

