    def send_editor_seal_preview(self, seal_id: str, *, supabase_mode: bool = False) -> None:
        query = parse_qs(urlparse(self.path).query, keep_blank_values=True)

        def first_query_value(*names: str) -> str:
            for name in names:
                values = query.get(name) or []
                if values:
                    return str(values[0] or "").strip()
            return ""

        binding = {
            "file_id": first_query_value("fileId", "file_id", "seal_file_id"),
            "file_sha256": first_query_value(
                "fileSha256", "file_sha256", "seal_file_sha256", "sha256"
            ),
            "document_id": first_query_value("documentId", "document_id"),
            "revision_id": first_query_value("revisionId", "revision_id"),
            "binding_requested": bool(
                set(query).intersection({
                    "fileId", "file_id", "seal_file_id",
                    "fileSha256", "file_sha256", "seal_file_sha256", "sha256",
                    "documentId", "document_id", "revisionId", "revision_id",
                })
            ),
        }
        if supabase_mode:
            session = supabase_current_session(self.bearer_token())
            data = supabase_editor_seal_preview(seal_id, session, **binding)
        else:
            with connect() as conn:
                session = current_session(conn, self.bearer_token())
                data = local_editor_seal_preview(conn, seal_id, session, **binding)
                conn.commit()
        self.send_response(200)
        self.send_header("Content-Type", "image/png")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "private, no-store, no-cache, max-age=0")
        self.send_header("Pragma", "no-cache")
        self.send_header("Expires", "0")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Content-Security-Policy", "default-src 'none'; sandbox")
        self.send_header("X-EDOC-Preview-Expires-In", str(EDOC_EDITOR_PREVIEW_TTL_SECONDS))
        self.end_headers()
        self.wfile.write(data)

